// Task 2: Array of record structures with custom memory pool
class Record {
  private int value;

  public Record(int value) {
    this.value = value;
  }

  // Getter and setter for the value field
  public int getValue() {
    return value;
  }

  public void setValue(int value) {
    this.value = value;
  }
}

class RecordPool {
  private static final Object LOCK = new Object();
  private static List<Record> pool = new ArrayList<>();

  // Get a record from the pool or create a new one if necessary
  public static Record getRecord(int value) {
    synchronized (LOCK) {
      for (Record record : pool) {
        if (record.getValue() == value) {
          return record;
        }
      }
      Record newRecord = new Record(value);
      pool.add(newRecord);
      return newRecord;
    }
  }
}
