// Log level definitions
enum log_level { DEBUG, INFO, WARNING, ERROR };

// Log message structure
struct log_message {
    int timestamp; // Timestamp in milliseconds since the epoch
    enum log_level level; // Log level (DEBUG, INFO, WARNING, or ERROR)
    char* message; // Formatted log message
};

// Log message queue data structure
struct log_queue {
    struct log_message** messages; // Array of log messages
    int capacity; // Current capacity of the queue
    int size; // Current size of the queue
};

// Initialize a new log queue with a given capacity
static void log_queue_init(struct log_queue* queue, int capacity) {
    assert(queue != NULL);
    assert(capacity > 0);

    queue->messages = malloc(sizeof(struct log_message*) * capacity);
    queue->capacity = capacity;
    queue->size = 0;
}

// Enqueue a new log message in the queue
static void log_enqueue(struct log_queue* queue, struct log_message* msg) {
    assert(queue != NULL);
    assert(msg != NULL);

    if (queue->size == queue->capacity) {
        // Enlarge the queue if it's full
        queue->messages = realloc(queue->messages, sizeof(struct log_message*) * (queue->capacity * 2));
        assert(queue->messages != NULL);
        queue->capacity *= 2;
    }

    // Store the new message in the queue
    queue->messages[queue->size++] = msg;
}

// Dequeue a log message from the queue
static struct log_message* log_dequeue(struct log_queue* queue) {
    assert(queue != NULL);

    if (queue->size == 0) {
        // Return NULL if the queue is empty
        return NULL;
    }

    // Remove and return the first message in the queue
    struct log_message* msg = queue->messages[0];
    memmove(queue->messages, queue->messages + 1, sizeof(struct log_message*) * (queue->size - 1));
    --queue->size;
    return msg;
}

// Free all memory associated with the log queue
static void log_queue_free(struct log_queue* queue) {
    assert(queue != NULL);

    for (int i = 0; i < queue->size; ++i) {
        free(queue->messages[i]);
    }
    free(queue->messages);
}

// Logging function that dynamically allocates memory for log messages and stores them in a queue
void log(enum log_level level, const char* format, ...) {
    // Create a new log message structure
    struct log_message* msg = malloc(sizeof(struct log_message));
    assert(msg != NULL);

    // Get the current time in milliseconds since the epoch
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    msg->timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

    // Set the log level and format the message using va_start/va_end
    msg->level = level;
    va_list args;
    va_start(args, format);
    vsnprintf(msg->message, sizeof(msg->message), format, args);
    va_end(args);

    // Enqueue the log message in the global queue
    struct log_queue* queue = &global_log_queue;
    log_enqueue(queue, msg);
}

// Send a batch of log messages to the external logging service
static void send_logs() {
    // Get a reference to the global log queue
    struct log_queue* queue = &global_log_queue;

    // Iterate over each log message in the queue
    for (int i = 0; i < queue->size; ++i) {
        struct log_message* msg = queue->messages[i];

        // Format the log message as a JSON object with timestamp, level, and message fields
        char json[128];
        snprintf(json, sizeof(json), "{\"timestamp\":%d,\"level\":\"%s\",\"message\":\"%s\"}", msg->timestamp, get_log_level_name(msg->level), msg->message);

        // Send the JSON object to the external logging service using a batched submission mechanism
        // ...
    }

    // Clear the log queue and free all memory associated with the messages
    log_queue_clear(&global_log_queue);
}

// Get the name of a log level as a string
static const char* get_log_level_name(enum log_level level) {
    switch (level) {
        case DEBUG: return "DEBUG";
        case INFO: return "INFO";
        case WARNING: return "WARNING";
        case ERROR: return "ERROR";
        default: return "UNKNOWN";
    }
}

// Global log queue for storing log messages
static struct log_queue global_log_queue;

int main() {
    // Initialize the global log queue with a capacity of 1024
    log_queue_init(&global_log_queue, 1024);

    // Set up an asynchronous logging thread to handle submissions of logs in batches
    pthread_t async_logging_thread;
    pthread_create(&async_logging_thread, NULL, send_logs, NULL);

    // Use the log function to log messages at varying levels and rates
    log(DEBUG, "Debug message 1");
    log(INFO, "Info message %d", 2);
    log(WARNING, "Warning message %s", "3");
    log(ERROR, "Error message %c", '4');

    // Wait for the asynchronous logging thread to complete before exiting
    pthread_join(async_logging_thread, NULL);

    return 0;
}
