    size_t rotation_size;
    time_t retention_period;
};

// Function to initialize a logger with customizable configuration options
LoggerConfig* initLogger(char* log_file_path, size_t rotation_size, time_t retention_period) {
    // Allocate memory for the logger configuration structure
    LoggerConfig* config = (LoggerConfig*)malloc(sizeof(LoggerConfig));

    // Initialize the logger configuration fields
    config->log_file_path = log_file_path;
    config->rotation_size = rotation_size;
    config->retention_period = retention_period;

    return config;
}

// Function to log a message at a given level and format
void logMessage(LoggerConfig* config, char* msg, int level, char* format) {
    // Check if the logger is initialized
    if (config == NULL) {
        printf("Logger not initialized\n");
        return;
    }

    // Log the message at the given level and format
    switch (level) {
        case DEBUG:
            if (format == JSON) {
                printf("DEBUG [JSON] %s\n", msg);
            } else {
                printf("DEBUG %s\n", msg);
            }
            break;
        case INFO:
            if (format == JSON) {
                printf("INFO [JSON] %s\n", msg);
            } else {
                printf("INFO %s\n", msg);
            }
            break;
        case WARNING:
            if (format == JSON) {
                printf("WARNING [JSON] %s\n", msg);
            } else {
                printf("WARNING %s\n", msg);
            }
            break;
        case ERROR:
            if (format == JSON) {
                printf("ERROR [JSON] %s\n", msg);
            } else {
                printf("ERROR %s\n", msg);
            }
            break;
        case CRITICAL:
            if (format == JSON) {
                printf("CRITICAL [JSON] %s\n", msg);
            } else {
                printf("CRITICAL %s\n", msg);
            }
            break;
    }
}

// Function to dynamically switch log outputs between console and file based on runtime conditions
void switchLogOutput(LoggerConfig* config, int enable_console, int enable_file) {
    // Check if the logger is initialized
    if (config == NULL) {
        printf("Logger not initialized\n");
        return;
    }

    // Enable or disable console logging as needed
    if (enable_console && config->log_file_path != NULL) {
        // Open the log file for appending
        int fd = open(config->log_file_path, O_APPEND | O_CREAT | O_RDWR, 0644);
        if (fd == -1) {
            printf("Failed to open log file\n");
            return;
        }

        // Redirect standard output to the log file
        dup2(fd, STDOUT_FILENO);
    } else if (!enable_console && config->log_file_path != NULL) {
        // Close the log file
        close(STDOUT_FILENO);
    }

    // Enable or disable file logging as needed
    if (enable_file && config->log_file_path == NULL) {
        // Create a new log file with the specified name and rotation size
        char* filename = "myapp.log";
        config->log_file_path = (char*)malloc(strlen(filename));
        strcpy(config->log_file_path, filename);
    } else if (!enable_file && config->log_file_path != NULL) {
        // Close the log file and free its memory
        close(config->log_file_path);
        free(config->log_file_path);
        config->log_file_path = NULL;
    }
}

// Function to gracefully handle high-volume logging scenarios without significant performance degradation
void logVolumeHandler(LoggerConfig* config, char* msg) {
    // Check if the logger is initialized
    if (config == NULL) {
        printf("Logger not initialized\n");
        return;
    }

    // Log the message at the INFO level
    logMessage(config, msg, INFO);
}

// Function to designate concurrent logging from multiple threads without causing data corruption
void concurrentLoggingHandler(LoggerConfig* config, char* msg) {
    // Check if the logger is initialized
    if (config == NULL) {
        printf("Logger not initialized\n");
        return;
    }

    // Log the message at the INFO level and in JSON format
    logMessage(config, msg, INFO, JSON);
}
```
This code defines a `LoggerConfig` structure to store the logger configuration options, including the log file path, rotation size, and retention period. It also defines three logging functions: `initLogger`, `logMessage`, and `switchLogOutput`. The `initLogger` function initializes the logger with customizable configuration options, while the `logMessage` function logs a message at a given level and format. The `switchLogOutput` function dynamically switches log outputs between console and file based on runtime conditions.

The `logVolumeHandler` function is used to handle high-volume logging scenarios without significant performance degradation. It simply calls the `logMessage` function with the same message string but at the INFO level, which should not have any noticeable impact on performance.

The `concurrentLoggingHandler` function is used to designate concurrent logging from multiple threads without causing data corruption. It simply calls the `logMessage` function with the same message string but in JSON format, which ensures that each thread has its own copy of the log message and does not interfere with other threads' logging.

Note that this code assumes that the system has a file I/O operations and memory management, which may impact performance under heavy load. If performance is a concern, it would be best to use an optimized logging library that uses low-level file I/O operations and efficient data structures for log message storage.']

