struct available_algorithm {
    const char* name;
    void (*impl)(void);
    void* params;
    const char* description;
};

// Function to retrieve the list of available algorithms from the CSP API
int get_available_algorithms(struct available_algorithm** algos, int* algo_count) {
    // Check if the CSP API is initialized
    if (!csp_api_is_initialized()) {
        return -1;
    }

    // Get the list of supported algorithms from the CSP API
    csp_api_get_supported_algorithms(algos, algo_count);

    // Check for any errors returned by the CSP API
    if (*algo_count == -1) {
        return -2;
    }

    // Allocate memory for each algorithm structure
    for (int i = 0; i < *algo_count; i++) {
        struct available_algorithm* algo = (struct available_algorithm*)malloc(sizeof(struct available_algorithm));
        algo->name = (*algos)[i].name;
        algo->impl = (*algos)[i].impl;
        algo->params = (*algos)[i].params;
        algo->description = (*algos)[i].description;
    }

    return 0;
}

// Function to check if an algorithm is available
int is_algorithm_available(const char* name) {
    struct available_algorithm** algos;
    int algo_count;

    // Get the list of supported algorithms from the CSP API
    get_available_algorithms(&algos, &algo_count);

    // Check if the requested algorithm is in the list of supported algorithms
    for (int i = 0; i < algo_count; i++) {
        if (strcmp((*algos)[i].name, name) == 0) {
            return 1;
        }
    }

    return 0;
}

// Function to get the list of available algorithms
int get_available_algorithms(struct available_algorithm*** algos, int* algo_count) {
    // Check if the CSP API is initialized
    if (!csp_api_is_initialized()) {
        return -1;
    }

    // Get the list of supported algorithms from the CSP API
    csp_api_get_supported_algorithms(algos, algo_count);

    // Check for any errors returned by the CSP API
    if (*algo_count == -1) {
        return -2;
    }

    // Allocate memory for each algorithm structure
    for (int i = 0; i < *algo_count; i++) {
        struct available_algorithm* algo = (struct available_algorithm*)malloc(sizeof(struct available_algorithm));
        algo->name = (*algos)[i].name;
        algo->impl = (*algos)[i].impl;
        algo->params = (*algos)[i].params;
        algo->description = (*algos)[i].description;
    }

    return 0;
}

// Function to get the performance characteristics of an algorithm
int get_algorithm_performance(const char* name, struct performance_characteristics* perf) {
    // Check if the requested algorithm is available
    if (!is_algorithm_available(name)) {
        return -1;
    }

    // Get the performance characteristics of the requested algorithm from the CSP API
    csp_api_get_algorithm_performance(name, perf);

    // Check for any errors returned by the CSP API
    if (perf == NULL) {
        return -2;
    }

    return 0;
}
