using namespace std;

// Global variables
const int DEFAULT_THREAD_COUNT = 4; // Default number of threads for concurrent execution
const int MAX_FILE_SIZE = 1024 * 1024 * 1024; // Maximum file size (in bytes) to be processed
const int MIN_BLOCK_SIZE = 512; // Minimum block size (in bytes) for file processing
const int MAX_BLOCK_SIZE = 1024 * 1024 * 64; // Maximum block size (in bytes) for file processing
const string DEFAULT_CONFIG_FILE = "config.json"; // Default configuration file path

// Enumeration of supported cryptographic operations
enum class Operation {
    ENCRYPT,
    DECRYPT,
    SIGN,
    VERIFY
};

// Structure to hold operation details and performance metrics
struct OperationInfo {
    Operation op; // Cryptographic operation (encrypt/decrypt/sign/verify)
    string filePath; // Path of the input file
    string outputFilePath; // Output file path (if any)
    int blockSize; // Block size (in bytes) for processing
    int threadCount; // Number of threads to use for concurrent execution
    double startTime; // Start time of the operation
    double endTime; // End time of the operation
    unsigned long long fileSize; // Size of the input file (in bytes)
    unsigned long long processedSize; // Total size of the data processed (in bytes)
    int statusCode; // Status code indicating success or failure of the operation
};

// Structure to hold configuration settings for a given cryptographic operation
struct OperationConfig {
    string algorithm; // Name of the algorithm used for the operation
    string keyPath; // Path of the key file (if any)
    int keySize; // Size of the key in bits
    double performanceThreshold; // Performance threshold for the operation
};

// Structure to hold configuration settings for all cryptographic operations
struct Config {
    map<Operation, OperationConfig> configMap; // Map of operation configurations
    string logPath; // Path of the log file (if any)
};

// Function to load and validate the configuration settings at runtime
void loadConfiguration(const string& configFilePath, Config* config) {
    ifstream configFile(configFilePath);
    assert(configFile.is_open());

    // Load configuration settings from JSON file
    json configJson = json::parse(configFile);

    // Validate the configuration settings
    for (auto& [op, opConfig] : config->configMap) {
        if (!configJson.contains(op)) {
            throw invalid_argument("Missing operation " + to_string(op) + " in configuration file");
        }

        // Validate the algorithm and key path
        string algorithm = configJson[op]["algorithm"];
        string keyPath = configJson[op]["key"];
        if (algorithm.empty() || keyPath.empty()) {
            throw invalid_argument("Invalid algorithm or key path for operation " + to_string(op) + " in configuration file");
        }

        // Validate the key size and performance threshold
        int keySize = configJson[op]["keySize"];
        double performanceThreshold = configJson[op]["performanceThreshold"];
        if (keySize < 0 || performanceThreshold <= 0.0) {
            throw invalid_argument("Invalid key size or performance threshold for operation " + to_string(op) + " in configuration file");
        }

        // Store the validated configuration settings
        opConfig.algorithm = algorithm;
        opConfig.keyPath = keyPath;
        opConfig.keySize = keySize;
        opConfig.performanceThreshold = performanceThreshold;
    }

    // Validate the log path (if any)
    if (configJson.contains("log")) {
        string logPath = configJson["log"];
        if (logPath.empty()) {
            throw invalid_argument("Invalid log path in configuration file");
        }
        config->logPath = logPath;
    }

    // Close the configuration file
    configFile.close();
}

// Function to perform a cryptographic operation on a given input file
void performOperation(const string& op, const string& filePath, const string& outputFilePath, int blockSize, int threadCount) {
    // Load and validate the configuration settings for the given operation
    OperationConfig config = loadConfiguration(DEFAULT_CONFIG_FILE);

    // Check if the input file exists and is not empty
    ifstream file(filePath);
    assert(file.is_open());
    file.seekg(0, ios::end);
    int fileSize = file.tellg();
    file.close();

    if (fileSize == 0) {
        throw invalid_argument("Input file is empty");
    }

    // Initialize the operation details and performance metrics
    OperationInfo info;
    info.op = op;
    info.filePath = filePath;
    info.outputFilePath = outputFilePath;
    info.blockSize = blockSize;
    info.threadCount = threadCount;
    info.startTime = chrono::system_clock::now();

    // Perform the cryptographic operation on each block of the input file
    unsigned long long processedSize = 0;
    if (op == Operation::ENCRYPT || op == Operation::SIGN) {
        while (processedSize < fileSize) {
            // Process a single block of the input file
            int blockLength = min(fileSize - processedSize, MIN_BLOCK_SIZE);
            vector<char> data;
            ifstream in(filePath, ios::binary);
            in.seekg(processedSize);
            data.insert(data.begin(), istream_iterator<char>(in), {});
            in.close();

            // Perform the cryptographic operation on the block
            vector<char> encryptedData;
            if (op == Operation::ENCRYPT) {
                // Encrypt the block using the specified algorithm and key
                string errorMessage = "";
                bool success = encrypt(config, data, &encryptedData, &errorMessage);
                if (!success) {
                    throw invalid_argument("Error during encryption: " + errorMessage);
                }
            } else {
                // Sign the block using the specified algorithm and key
                string errorMessage = "";
                bool success = sign(config, data, &encryptedData, &errorMessage);
                if (!success) {
                    throw invalid_argument("Error during signing: " + errorMessage);
                }
            }

            // Write the encrypted/signed block to the output file (if any)
            ofstream out(outputFilePath, ios::binary | ios::app);
            out.write(&encryptedData[0], encryptedData.size());
            out.close();

            // Update the performance metrics and processed size
            info.processedSize += blockLength;
            processedSize += blockLength;
        }
    } else {
        while (processedSize < fileSize) {
            // Process a single block of the input file
            int blockLength = min(fileSize - processedSize, MIN_BLOCK_SIZE);
            vector<char> data;
            ifstream in(filePath, ios::binary);
            in.seekg(processedSize);
            data.insert(data.begin(), istream_iterator<char>(in), {});
            in.close();

            // Perform the cryptographic operation on the block
            vector<char> decryptedData;
            if (op == Operation::DECRYPT) {
                // Decrypt the block using the specified algorithm and key
                string errorMessage = "";
                bool success = decrypt(config, data, &decryptedData, &errorMessage);
                if (!success) {
                    throw invalid_argument("Error during decryption: " + errorMessage);
                }
            } else {
                // Verify the block using the specified algorithm and key
                string errorMessage = "";
                bool success = verify(config, data, &decryptedData, &errorMessage);
                if (!success) {
                    throw invalid_argument("Error during verification: " + errorMessage);
                }
            }

            // Write the decrypted/verified block to the output file (if any)
            ofstream out(outputFilePath, ios::binary | ios::app);
            out.write(&decryptedData[0], decryptedData.size());
            out.close();

            // Update the performance metrics and processed size
            info.processedSize += blockLength;
            processedSize += blockLength;
        }
    }

    // Close the input file (if any)
    if (!outputFilePath.empty()) {
        ofstream out(outputFilePath, ios::binary);
        out.close();
    }

    // Update the end time and status code
    info.endTime = chrono::system_clock::now();
    info.statusCode = 0;
}

// Function to perform encryption on a given input file
void encrypt(const Config& config, const vector<char>& data, vector<char>* encryptedData, string* errorMessage) {
    // Load and validate the configuration settings for encryption
    OperationConfig opConfig = config.configMap[Operation::ENCRYPT];

    // Check if the input data is not empty
    if (data.empty()) {
        throw invalid_argument("Input data is empty");
    }

    // Perform the encryption operation using the specified algorithm and key
    *errorMessage = "Error during encryption: ";
    if (opConfig.algorithm == "AES") {
        // Use AES encryption with the specified key size
        int keySize = opConfig.keySize / 8;
        vector<char> key(keySize, '\0');
        ifstream in(opConfig.keyPath);
        assert(in.is_open());
        in.read(&key[0], keySize);
        in.close();

        // Encrypt the input data using AES-CBC with the specified key
        *encryptedData = encryptAESCBC(data, &key[0], keySize, opConfig.performanceThreshold);
    } else {
        throw invalid_argument("Unsupported algorithm: " + opConfig.algorithm);
    }
}

// Function to perform decryption on a given input file
void decrypt(const Config& config, const vector<char>& data, vector<char>* decryptedData, string* errorMessage) {
    // Load and validate the configuration settings for decryption
    OperationConfig opConfig = config.configMap[Operation::DECRYPT];

    // Check if the input data is not empty
    if (data.empty()) {
        throw invalid_argument("Input data is empty");
    }

    // Perform the decryption operation using the specified algorithm and key
    *errorMessage = "Error during decryption: ";
    if (opConfig.algorithm == "AES") {
        // Use AES decryption with the specified key size
        int keySize = opConfig.keySize / 8;
        vector<char> key(keySize, '\0');
        ifstream in(opConfig.keyPath);
        assert(in.is_open());
        in.read(&key[0], keySize);
        in.close();

        // Decrypt the input data using AES-CBC with the specified key
        *decryptedData = decryptAESCBC(data, &key[0], keySize, opConfig.performanceThreshold);
    } else {
        throw invalid_argument("Unsupported algorithm: " + opConfig.algorithm);
    }
}

// Function to perform signing on a given input file
void sign(const Config& config, const vector<char>& data, vector<char>* signedData, string* errorMessage) {
    // Load and validate the configuration settings for signing
    OperationConfig opConfig = config.configMap[Operation::SIGN];

    // Check if the input data is not empty
    if (data.empty()) {
        throw invalid_argument("Input data is empty");
    }

    // Perform the signing operation using the specified algorithm and key
    *errorMessage = "Error during signing: ";
    if (opConfig.algorithm == "RSA") {
        // Use RSA signing with the specified key size
        int keySize = opConfig.keySize;
        vector<char> key(keySize, '\0');
        ifstream in(opConfig.keyPath);
        assert(in.is_open());
        in.read(&key[0], keySize);
        in.close();

        // Sign the input data using RSA-PSS with the specified key
        *signedData = signRSA(data, &key[0], keySize, opConfig.performanceThreshold);
    } else {
        throw invalid_argument("Unsupported algorithm: " + opConfig.algorithm);
    }
}

// Function to perform verification on a given input file
void verify(const Config& config, const vector<char>& data, vector<char>* verifiedData, string* errorMessage) {
    // Load and validate the configuration settings for verification
    OperationConfig opConfig = config.configMap[Operation::VERIFY];

    // Check if the input data is not empty
    if (data.empty()) {
        throw invalid_argument("Input data is empty");
    }

    // Perform the verification operation using the specified algorithm and key
    *errorMessage = "Error during verification: ";
    if (opConfig.algorithm == "RSA") {
        // Use RSA verification with the specified key size
        int keySize = opConfig.keySize;
        vector<char> key(keySize, '\0');
        ifstream in(opConfig.keyPath);
        assert(in.is_open());
        in.read(&key[0], keySize);
        in.close();

        // Verify the input data using RSA-PSS with the specified key
        *verifiedData = verifyRSA(data, &key[0], keySize, opConfig.performanceThreshold);
    } else {
        throw invalid_argument("Unsupported algorithm: " + opConfig.algorithm);
    }
}

// Function to perform a cryptographic operation on multiple files simultaneously using multiple threads
void performOperations(const Config& config, const vector<string>& filePaths, int threadCount) {
    // Initialize the mutex and condition variable for thread synchronization
    mutex mtx;
    condition_variable cv;

    // Create a vector to store the status codes of all threads
    vector<int> statusCodes;

    // Spawn multiple threads to perform the operation on each file
    int threadCount = min(threadCount, (int)filePaths.size());
    for (int i = 0; i < threadCount; ++i) {
        string filePath = filePaths[i];
        thread t([&]() {
            // Perform the operation on the current file using the specified configuration
            int statusCode = performOperation(config, filePath);

            // Lock the mutex and update the vector of status codes
            lock_guard<mutex> lck(mtx);
            statusCodes.push_back(statusCode);

            // Signal to the main thread that a new status code has been added
            cv.notify_one();
        });
        t.detach();
    }

    // Wait for all threads to complete and check their status codes
    while (true) {
        lock_guard<mutex> lck(mtx);
        if (statusCodes.size() == threadCount) {
            break;
        }
        cv.wait(lck);
    }

    // Check the status codes of all threads and return the overall status code
    int overallStatusCode = 0;
    for (int i = 0; i < threadCount; ++i) {
        if (statusCodes[i] != 0) {
            overallStatusCode = -1;
            break;
        }
    }
    return overallStatusCode;
}

// Function to perform a cryptographic operation on a single file using multiple threads
void performOperation(const Config& config, const string& filePath) {
    // Load and validate the configuration settings for the current file
    OperationConfig opConfig = config.configMap[Operation::ENCRYPT];

    // Check if the input data is not empty
    if (filePath.empty()) {
        throw invalid_argument("Input data is empty");
    }

    // Perform the operation on the current file using multiple threads
    int threadCount = min(opConfig.performanceThreshold, (int)filePaths.size());
    for (int i = 0; i < threadCount; ++i) {
        string filePath = filePaths[i];
        thread t([&]() {
            // Perform the operation on the current file using the specified configuration
            int statusCode = performOperation(config, filePath);

            // Lock the mutex and update the vector of status codes
            lock_guard<mutex> lck(mtx);
            statusCodes.push_back(statusCode);

            // Signal to the main thread that a new status code has been added
            cv.notify_one();
        });
        t.detach();
    }

    // Wait for all threads to complete and check their status codes
    while (true) {
        lock_guard<mutex> lck(mtx);
        if (statusCodes.size() == threadCount) {
            break;
        }
        cv.wait(lck);
    }

    // Check the status codes of all threads and return the overall status code
    int overallStatusCode = 0;
    for (int i = 0; i < threadCount; ++i) {
        if (statusCodes[i] != 0) {
            overallStatusCode = -1;
            break;
        }
    }
    return overallStatusCode;
}
```

This code is a bit more complex than the previous version, but it should be easier to understand. The main functions are `performOperations` and `performOperation`, which handle multiple files and single files respectively. They use mutexes and condition variables for thread synchronization and return an overall status code based on the status codes of all threads.

The `encrypt`, `decrypt`, `sign`, and `verify` functions are similar to their previous versions, but they now take a `Config` object as a parameter instead of separate configuration settings. This allows them to use the same configuration for multiple files simultaneously.

In summary, this code should be easier to understand and more modular than the previous version. It also allows for better performance by using multiple threads to perform the operation on multiple files simultaneously.']

