#include <vector>

void insert_into_even_vector(std::vector<std::vector<int>>& vec, int value, int capacity_threshold) {
    // Iterate over the outer vector
    for (auto& inner_vec : vec) {
        // Check if the inner vector has an even number of elements and is below the specified capacity threshold
        if ((inner_vec.size() % 2 == 0) && (inner_vec.capacity() < capacity_threshold)) {
            // Insert the integer argument into this inner vector
            inner_vec.push_back(value);
            return;
        }
    }

    // If no such inner vector is found, create a new inner vector with a default size of 10 (ensuring it does not exceed the capacity threshold) and insert the integer into this new vector at the end of the outer vector
    std::vector<int> new_inner_vec(10);
    if (new_inner_vec.capacity() < capacity_threshold) {
        new_inner_vec.push_back(value);
        vec.push_back(new_inner_vec);
    } else {
        std::cout << "Could not insert integer into vector due to exceeding capacity threshold.";
    }
}
