public static XElement GetFirstMatchingElement(string xmlContent, string elementName)
{
    try
    {
        var doc = new XmlDocument();
        doc.LoadXml(xmlContent);
        var navigator = doc.CreateNavigator();
        var xpathExpression = "//*[local-name()='" + elementName + "']";
        var nodeIterator = navigator.Select(xpathExpression);
        if (!nodeIterator.MoveNext())
            throw new InvalidOperationException("No element found with name " + elementName);
        return (XElement)nodeIterator.Current;
    }
    catch (InvalidOperationException ex)
    {
        // Handle exception
    }
}
