function processUserRequest() {
    // Define the allowed sub-actions
    $allowedSubActions = ['create', 'update', 'delete'];

    // Get the request data
    $requestData = $_POST;

    // Validate the request data
    if (!isset($requestData['sub_action']) || !in_array($requestData['sub_action'], $allowedSubActions)) {
        return jsonResponse(400, 'Invalid sub-action');
    }

    // Ensure that the email is valid for read and update operations
    if ($requestData['sub_action'] === 'read' || $requestData['sub_action'] === 'update') {
        if (!filter_var($requestData['email'], FILTER_VALIDATE_EMAIL)) {
            return jsonResponse(400, 'Invalid email address');
        }
    }

    // Ensure that the id is present when performing read or update operations
    if ($requestData['sub_action'] === 'read' || $requestData['sub_action'] === 'update') {
        if (!isset($requestData['id']) || !is_numeric($requestData['id'])) {
            return jsonResponse(400, 'Invalid ID');
        }
    }

    // Handle the request data based on the sub-action
    switch ($requestData['sub_action']) {
        case 'create':
            // Verify the email with an external API
            $emailVerified = verifyEmail($requestData['email']);
            if (!$emailVerified) {
                return jsonResponse(400, 'Invalid email address');
            }

            // Create a new user account
            $userId = createUser($requestData['name'], $requestData['email'], $requestData['password']);
            if ($userId === false) {
                return jsonResponse(500, 'Error creating user');
