            // Return the JSON response
            return jsonResponse(201, "Successfully created user with ID {$userId}");
            break;
        case 'update':
            // Update the user account
            $userUpdated = updateUser($requestData['id'], $requestData['name'], $requestData['email'], $requestData['password']);
            if ($userUpdated === false) {
                return jsonResponse(400, 'Error updating user');
            }

            // Return the JSON response
