    public class ApplicationUser : IdentityUser
    {
        // Add rate limiting for account creation and login attempts
        private readonly int _maxAttempts = 10;
        private readonly int _minutesBetweenAttempts = 30;

        public static ApplicationUser GetById(string id)
        {
            var user = new ApplicationUser();
            user.Id = id;
            return user;
        }

        // Check if login attempts have exceeded limit
        public void Save()
        {
            var currentAttempts = _userStore.GetUserLoginAttempts(this);
            if (currentAttempts > _maxAttempts)
            {
                throw new RateLimitExceededException();
            }

