function runTests() {
  const loadedModules = {}; // Keep track of loaded modules
  const testResults = []; // Store test results
  const errorHandler = err => console.error(err); // Handle errors gracefully

  for (const [testModule, testLabel] of tests) {
    if (!loadedModules[testModule]) {
      try {
        loadedModules[testModule] = require(testModule); // Load module once per session
      } catch (err) {
        errorHandler(err);
        continue; // Move on to next test
      }
    }

    const startTime = Date.now();
    try {
      loadedModules[testModule][testLabel](); // Run test function
    } catch (err) {
      errorHandler(err);
    }

    const endTime = Date.now();
    const duration = endTime - startTime;
    testResults.push({ module: testModule, label: testLabel, duration });
  }

  console.log("Test results:", JSON.stringify(testResults)); // Log test results
}
```
