const modules = {};
const moduleIds = [];

function loadModule(id, version) {
  const filename = `modules/${id}_v${version}.js`;
  try {
    const module = require(filename);
    modules[id] = module;
    moduleIds.push(id);
    return module;
  } catch (error) {
    if (error.code === 'MODULE_NOT_FOUND') {
      console.log(`Module ${id} v${version} not found.`);
    } else {
      console.log(`Error loading module ${id} v${version}:`, error);
    }
  }
}

function executeModules(ids) {
  const modulesToExecute = ids.map((id) => modules[id]);
  for (const module of modulesToExecute) {
    if (module) {
      console.log(`Executing module ${module.id} v${module.version}`);
      module();
    } else {
      console.log(`Module ${id} not found.`);
    }
  }
}

function getAvailableModules() {
  return moduleIds;
}

function getLoadedModules() {
  return Object.values(modules);
}

module.exports = {
  loadModule,
  executeModules,
  getAvailableModules,
  getLoadedModules,
};
