public class ServiceManager {
    private static final String CONFIG_DIR = "/path/to/config/dir";
    private static final int MAX_THREADS = 10;
    private static final int CPU_USAGE_THRESHOLD = 80; // percentage
    private static final long MEMORY_USAGE_THRESHOLD = 90 * 1024 * 1024L; // bytes
    private static final long DISK_IO_USAGE_THRESHOLD = 50 * 1024 * 1024L; // bytes
    private static final int STARTUP_DELAY = 30; // seconds
    private static final int SHUTDOWN_DELAY = 30; // seconds

    private Map<String, Service> services = new HashMap<>();
    private ExecutorService executorService = Executors.newFixedThreadPool(MAX_THREADS);

    public void startServices() {
        File configDir = new File(CONFIG_DIR);
        if (!configDir.exists()) {
            throw new IllegalArgumentException("Config directory does not exist");
        }

        for (File configFile : configDir.listFiles()) {
            Service service = parseServiceConfiguration(configFile);
            services.put(service.getName(), service);
        }

        executorService.execute(() -> startServices(services));
    }

    private void startServices(Map<String, Service> services) {
        for (Service service : services.values()) {
            try {
                service.start();
                logServiceStarted(service);
            } catch (Exception e) {
                logServiceFailedToStart(service, e);
            }
        }
    }

    private void stopServices() {
        for (Map.Entry<String, Service> entry : services.entrySet()) {
            String serviceName = entry.getKey();
            Service service = entry.getValue();
            try {
                service.stop();
                logServiceStopped(service);
            } catch (Exception e) {
                logServiceFailedToStop(service, e);
            }
        }
    }

    private void restartServices() {
        stopServices();
        startServices();
    }

