            // Update user profile with verified contact information
            $updateQuery = "UPDATE users SET contact_info = :contactInfo, verified_at = :verifiedAt WHERE id = :userId";
            $stmt = $pdo->prepare($updateQuery);
            $stmt->bindParam(":contactInfo", $verificationResponse["contactInfo"]);
            $stmt->bindParam(":verifiedAt", $verificationResponse["verifiedAt"]);
            $stmt->execute();
        } else {
            // Log verification failure and notify administrator (optional)
            $logQuery = "INSERT INTO user_logs (user_id, action, timestamp) VALUES (:userId, 'contact_info_verify_failure', :timestamp)";
            $stmt = $pdo->prepare($logQuery);
            $stmt->bindParam(":userId", $userId);
            $stmt->bindParam(":timestamp", time());
