        $stmt = $pdo->prepare($logQuery);
        $stmt->bindParam(":userId", $userId);
        $stmt->bindParam(":timestamp", time());
        $stmt->execute();
    }
}

function verifyContactInfo($contactInfo) {
    // Integrate with external API to verify contact information (optional)
    try {
        $apiResponse = callAPI("https://external-api.com/verifyContactInfo", [
            "contactInfo" => $contactInfo,
        ]);
        if ($apiResponse["status"] === "success") {
            return [
                "status" => "success",
                "contactInfo" => $apiResponse["contactInfo"],
                "verifiedAt" => time(),
            ];
        } else {
            return [
                "status" => "failure",
                "errorMessage" => $apiResponse["errorMessage"],
            ];
        }
    } catch (Exception $e) {
        return [
            "status" => "failure",
            "errorMessage" => $e->getMessage(),
        ];
    }
}

function callAPI($url, $data) {
    // Call external API to verify contact information (optional)
    $curl = curl_init();
    curl_setopt($curl, CURLOPT_URL, $url);
    curl_setopt($curl, CURLOPT_POST, 1);
    curl_setopt($curl, CURLOPT_POSTFIELDS, http_build_query($data));
    curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
    $response = curl_exec($curl);
    if ($response === false) {
        throw new Exception(curl_error($curl), curl_errno($curl));
    }
    curl_close($curl);
    return json_decode($response, true);
}
