    public function generateAndHash(string $password, int $length, string $charset): string
    {
        // Generate a random string using the specified character set and length
        $randomString = str_shuffle($charset);
        $randomString = substr($randomString, 0, $length);

        // Hash the password using the specified hash algorithm
        $hashAlgorithm = self::SUPPORTED_HASH_ALGORITHMS[0];
        if (isset($_POST['hashAlgorithm']) && in_array($_POST['hashAlgorithm'], self::SUPPORTED_HASH_ALGORITHMS)) {
            $hashAlgorithm = $_POST['hashAlgorithm'];
        }
        $hashedPassword = hash($hashAlgorithm, $password);

        return $hashedPassword;
    }

    public function readFileContents(string $filePath): string
    {
        if (!is_readable($filePath)) {
            throw new \Exception("File not found or cannot be read");
        }

        // Read the file synchronously and return its contents as a string
        $fileContents = file_get_contents($filePath);
        if ($fileContents === false) {
            throw new \Exception("Error reading file: {$filePath}");
        }

        return $fileContents;
    }
}
