function generatePEMCertificate(oauthRequest) {
  const privateKeyEndpoint = 'https://example.com/private-key';
  const certificateEndpoint = 'https://example.com/certificate';

  return new Promise((resolve, reject) => {
    const request = new XMLHttpRequest();

    request.open('GET', privateKeyEndpoint, true);
    request.responseType = 'arraybuffer';

    let privateKeyBuffer = null;

    request.onload = () => {
      if (request.status === 200) {
        const privateKey = new Uint8Array(request.response);
        privateKeyBuffer = new ArrayBuffer(privateKey.length);
        privateKey.forEach((value, index) => {
          privateKeyBuffer[index] = value;
        });
      } else {
        reject(`Failed to fetch private key: ${request.statusText}`);
      }
    };

    request.onerror = () => {
      reject('Error occurred while fetching private key');
    };

    request.send();

    const certificateRequest = new XMLHttpRequest();

    certificateRequest.open('GET', certificateEndpoint, true);
    certificateRequest.responseType = 'arraybuffer';

    let certificateBuffer = null;

    certificateRequest.onload = () => {
      if (certificateRequest.status === 200) {
        const certificate = new Uint8Array(certificateRequest.response);
        certificateBuffer = new ArrayBuffer(certificate.length);
        certificate.forEach((value, index) => {
          certificateBuffer[index] = value;
        });
      } else {
        reject(`Failed to fetch certificate: ${certificateRequest.statusText}`);
      }
    };

    certificateRequest.onerror = () => {
      reject('Error occurred while fetching certificate');
    };

    certificateRequest.send();

    Promise.all([request, certificateRequest]).then(values => {
      const privateKey = new Uint8Array(privateKeyBuffer);
      const certificate = new Uint8Array(certificateBuffer);

      const pemData = `-----BEGIN PRIVATE KEY-----\n`;
      for (let i = 0; i < privateKey.length; i += 64) {
        const chunk = privateKey.subarray(i, Math.min(privateKey.length, i + 64));
        pemData += window.btoa(String.fromCharCode(...chunk)).replace(/[+\/=]/g, '');
      }
      pemData += `\n-----END PRIVATE KEY-----\n`;

      for (let i = 0; i < certificate.length; i += 64) {
        const chunk = certificate.subarray(i, Math.min(certificate.length, i + 64));
        pemData += window.btoa(String.fromCharCode(...chunk)).replace(/[+\/=]/g, '');
      }
      pemData += `\n-----END CERTIFICATE-----\n`;

      resolve(pemData);
    });
  });
}
