<?php

class OAuth2Service {
  private $clientId;
  private $clientSecret;
  private $accessToken;
  private $refreshToken;
  private $tokenExpiresAt;

  public function __construct($clientId, $clientSecret) {
    $this->clientId = $clientId;
    $this->clientSecret = $clientSecret;
  }

  public function authenticateUser($username, $password) {
    $url = 'https://oauth.example.com/token';
    $data = [
      'grant_type' => 'password',
      'client_id' => $this->clientId,
      'client_secret' => $this->clientSecret,
      'username' => $username,
      'password' => $password,
    ];

    $response = $this->httpRequest($url, $data);

    if ($response['status'] === 200) {
      $accessToken = $response['body']['access_token'];
      $refreshToken = $response['body']['refresh_token'];
      $tokenExpiresAt = time() + $response['body']['expires_in'];
      return [$accessToken, $refreshToken, $tokenExpiresAt];
    } else {
      return false;
    }
  }

  public function getUserProfile($accessToken) {
    $url = 'https://api.example.com/user-profile';
    $headers = [
      'Authorization: Bearer ' . $accessToken,
    ];

    $response = $this->httpRequest($url, [], $headers);

    if ($response['status'] === 200) {
      return $response['body'];
    } else {
      return false;
    }
  }

  private function httpRequest($url, $data = [], $headers = []) {
    // build the HTTP request headers
    $headers[] = 'User-Agent: OAuth2Service/1.0 (https://oauth.example.com)';
    $headers[] = 'Accept: application/json';

    // send the HTTP request
    $ch = curl_init($url);
    curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($data));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    $response = curl_exec($ch);
    curl_close($ch);

    // parse the HTTP response
    if (substr($response, 0, 5) === 'HTTP/') {
      $statusCode = substr($response, 9, 3);
      $body = substr($response, 12);
      return [$statusCode, json_decode($body, true)];
    } else {
      return false;
    }
  }
}
