// Define a structure to represent a state in the FSA
typedef struct {
    int id;
    char* name;
} State;

// Define a structure to represent the FSA
typedef struct {
    int num_states;
    State* states;
    int current_state;
} FSA;

// Define a function to manage the state list under resource-constrained environments
State* allocate_state(FSA* fsa, int last_state, size_t allocation_size) {
    // Check if memory allocation fails due to exceeding the specified limit
    if (allocation_size > 0 && allocation_size <= fsa->num_states - last_state) {
        State* new_state = malloc(sizeof(State));
        if (new_state == NULL) {
            // Log a warning message and return NULL if memory allocation fails
            printf("WARNING: Failed to allocate memory for state\n");
            return NULL;
        } else {
            // Initialize the new state with a default value
            new_state->id = 0;
            new_state->name = "Default";

            // Update the 'next' pointer of the last state in the list to point to the newly created state
            fsa->states[last_state].next = new_state;

            // Return a pointer to the newly created state
            return new_state;
        }
    } else {
        printf("ERROR: Out of memory\n");
        return NULL;
    }
}

// Define a function to handle concurrent access to shared resources safely
void safe_allocate_state(FSA* fsa, int last_state, size_t allocation_size) {
    pthread_mutex_lock(&fsa->mutex);
    State* new_state = allocate_state(fsa, last_state, allocation_size);
    pthread_mutex_unlock(&fsa->mutex);
}
