#include <iostream>
#include <vector>
#include <memory>
#include <unordered_map>
#include <thread>

class Octree {
public:
    // Constructor to initialize an octree with customizable feature size, number of leaf nodes, and data capacity
    Octree(int featureSize, int numLeafNodes, int dataCapacity) : featureSize_(featureSize), numLeafNodes_(numLeafNodes), dataCapacity_(dataCapacity), depthLimit_(10) {
        // Validate input parameters
        if (featureSize <= 0 || numLeafNodes <= 0 || dataCapacity <= 0) {
            std::cerr << "Invalid input parameters for Octree constructor." << std::endl;
            return;
        }

        // Initialize the root node and allocate memory for leaf nodes
        root_ = new Node(nullptr, nullptr, nullptr, nullptr);
        leaves_.resize(numLeafNodes_);
        data_.reserve(dataCapacity_);
    }

    // Destructor to release allocated memory
    ~Octree() {
        delete root_;
        leaves_.clear();
        data_.clear();
    }

    // Reset function to reuse the octree for different configurations while preserving previously allocated memory
    void reset(int featureSize, int numLeafNodes, int dataCapacity) {
        // Validate input parameters
        if (featureSize <= 0 || numLeafNodes <= 0 || dataCapacity <= 0) {
            std::cerr << "Invalid input parameters for Octree reset." << std::endl;
            return;
        }

        // Release allocated memory and reinitialize the root node
        delete root_;
        root_ = new Node(nullptr, nullptr, nullptr, nullptr);

        // Reallocate memory for leaf nodes and data
        leaves_.resize(numLeafNodes_);
        data_.reserve(dataCapacity_);

        // Reset the depth limit
        depthLimit_ = 10;
    }

    // Insert function to insert data into the octree
    void insert(const std::vector<float>& data) {
        // Validate input parameters
        if (data.size() != featureSize_) {
            std::cerr << "Invalid input parameters for Octree insert." << std::endl;
            return;
        }

        // Find the appropriate leaf node to store the data
        Node* current = root_;
        for (int i = 0; i < depthLimit_ - 1 && current->child[i] != nullptr; i++) {
            int index = getIndex(data, i);
            current = current->child[index];
        }

        // Store the data in the leaf node
        current->data.push_back(data);
    }

    // Get function to retrieve data from the octree
    std::vector<float> get(const std::vector<float>& query) {
        // Validate input parameters
        if (query.size() != featureSize_) {
            std::cerr << "Invalid input parameters for Octree get." << std::endl;
            return {};
        }

        // Find the appropriate leaf node to retrieve data from
        Node* current = root_;
        for (int i = 0; i < depthLimit_ - 1 && current->child[i] != nullptr; i++) {
            int index = getIndex(query, i);
            current = current->child[index];
        }

        // Retrieve the data from the leaf node
        if (current->data.size() == 0) {
            return {};
        }
        else {
            return current->data;
        }
    }

private:
    // Node structure to represent an octree node
    struct Node {
        std::vector<Node*> child;
        std::vector<std::vector<float>> data;

        // Constructor to initialize a new node
        Node(Node* parent, int index, int featureSize) : parent_(parent), index_(index), featureSize_(featureSize) {
            child.resize(8);
        }
    };

    // GetIndex function to determine the appropriate child node for a given input
    int getIndex(const std::vector<float>& data, int depth) {
        float value = data[depth];

        // Determine the appropriate child index based on the input value and the current depth
        if (value < 0.5f) {
            return 0;
        }
        else if (value >= 0.5f && value < 1.0f) {
            return 1;
        }
        else if (value >= 1.0f && value < 1.5f) {
            return 2;
        }
        else if (value >= 1.5f && value < 2.0f) {
            return 3;
        }
        else if (value >= 2.0f && value < 2.5f) {
            return 4;
        }
        else if (value >= 2.5f && value < 3.0f) {
            return 5;
        }
        else if (value >= 3.0f && value < 3.5f) {
            return 6;
        }
        else if (value >= 3.5f) {
            return 7;
        }

        // Return the appropriate child index for the given input and depth
    }

    int featureSize_; // Size of the features in the octree
    int numLeafNodes_; // Number of leaf nodes in the octree
    int dataCapacity_; // Capacity of the data vector in each leaf node
    int depthLimit_; // Maximum depth limit for the tree construction
    Node* root_; // Pointer to the root node of the octree
    std::vector<Node> leaves_; // Vector of leaf nodes in the octree
    std::unordered_map<int, std::vector<float>> data_; // Map of data vectors stored in the octree
};
```
Note that this is just a basic implementation of an octree structure and there are many ways to optimize it for performance and memory efficiency. The above code should serve as a starting point for you to implement your own version of the octree with additional features and optimizations as needed.']

