// Thread-safe queue for storing incoming packets
typedef struct {
    int front, rear, size;
    int *data;
} queue_t;

// Initialize queue with given capacity
void initQueue(queue_t *q, int cap) {
    q->front = 0;
    q->rear = -1;
    q->size = 0;
    q->data = (int *)malloc(sizeof(int) * cap);
}

// Enqueue a packet with given ID
void enQueue(queue_t *q, int id) {
    if (q->rear == q->size - 1) {
        // Queue is full
        return;
    }
    q->data[++q->rear] = id;
    q->size++;
}

// Dequeue and return the ID of the next packet to be processed
int deQueue(queue_t *q) {
    if (q->front > q->rear) {
        // Queue is empty
        return -1;
    }
    int id = q->data[q->front++];
    q->size--;
    return id;
}

// Free queue memory
void freeQueue(queue_t *q) {
    free(q->data);
}

// Process a packet with given ID and update metrics accordingly
int processPacket(int id, int size) {
    // Update bandwidth utilization metric
    max_utilization = fmax(size / 1024.0, max_utilization);
    num_packets++;
    cumulative_bandwidth += size;
    return id;
}

// Get maximum bandwidth utilization and corresponding packet ID
int getMaxBandwidthUtilization() {
    int max_id = -1;
    float max_utilization = 0.0;
    for (int i = 0; i < num_packets; i++) {
        if (cumulative_bandwidth[i] / 1024.0 > max_utilization) {
            max_id = i;
            max_utilization = cumulative_bandwidth[i] / 1024.0;
        }
    }
    return max_id;
}

int main() {
    // Initialize queue with capacity for 100 packets
    queue_t q;
    initQueue(&q, 100);

    // Initialize bandwidth utilization and packet counters
    int max_utilization = 0;
    int num_packets = 0;
    float cumulative_bandwidth = 0.0;

    while (true) {
        // Check for incoming packets
        struct timeval tv;
        gettimeofday(&tv, NULL);
        if (tv.tv_sec % 50 == 0) {
            // Update metrics every 50 milliseconds
            int packet_id = deQueue(&q);
            while (packet_id != -1) {
                processPacket(packet_id, getBandwidthAllocation(packet_id));
                packet_id = deQueue(&q);
            }
        } else {
            // Handle potential delays and packet drops
            int packet_id = deQueue(&q);
            if (packet_id != -1) {
                processPacket(packet_id, getBandwidthAllocation(packet_id));
            }
        }
    }
}
