using UnityEngine;

public class CustomRandomGenerator {
  private float minValue, maxValue;

  public CustomRandomGenerator(float minValue, float maxValue) {
    this.minValue = minValue;
    this.maxValue = maxValue;
  }

  public float GetRandomFloat() {
    return UnityEngine.Random.Range(this.minValue, this.maxValue);
  }

  public int GetRandomInt() {
    if (Mathf.Approximately(this.minValue, this.maxValue)) {
      return (int)this.minValue;
    } else {
      int randomInt = UnityEngine.Random.Range((int)this.minValue, (int)this.maxValue + 1);
      if (randomInt == this.maxValue) {
        randomInt--;
      }
      return randomInt;
    }
  }

  public Vector3 GetRandomVector3() {
    float x = UnityEngine.Random.Range(this.minValue, this.maxValue);
    float y = UnityEngine.Random.Range(this.minValue, this.maxValue);
    float z = UnityEngine.Random.Range(this.minValue, this.maxValue);
    return new Vector3(x, y, z);
  }

  public override string ToString() {
    return $"CustomRandomGenerator<float>: Range [{this.minValue}, {this.maxValue}]";
  }

  public static void CheckRangeValidity(float minValue, float maxValue) {
    if (minValue >= maxValue) {
      throw new ArgumentException($"Minimum value ({minValue}) must be less than maximum value ({maxValue}).");
    }
  }
}
