const char* processStringWithLimit(const char* str, int sizeLimit, int(*lengthChecker)(const char*)) {
    if (!str || !lengthChecker) {
        return NULL;
    }
    int len = lengthChecker(str);
    if (len > sizeLimit) {
        return NULL;
    }
    const char* newStr = malloc((len + 1) * sizeof(char));
    memcpy(newStr, str, len);
    newStr[len] = '/';
    newStr[len + 1] = '\0';
    return newStr;
}
