#include "theme_cache.h"

#define MAX_THEMES 10000
#define MAX_CACHE_SIZE (1024 * 1024 * 5) // 5 MB
#define DEFAULT_THEME_DIR "/path/to/default/theme/dir"
#define THEME_FILE_EXTENSION ".png"
#define THREAD_COUNT 8

// Theme structure for caching and storing theme bitmaps
struct Theme {
    char *name;
    unsigned int size;
    void *bitmap;
};

// Cache structure for managing theme bitmaps
struct ThemeCache {
    struct Theme themes[MAX_THEMES];
    int count;
    pthread_mutex_t mutex;
};

// Global cache object
static struct ThemeCache *cache = NULL;

// Initialization function for the cache
void init_cache(const char *dir) {
    // Create a new cache object if it doesn't exist
    if (cache == NULL) {
        cache = malloc(sizeof(struct ThemeCache));
        memset(cache, 0, sizeof(struct ThemeCache));
    }

    // Set the default theme directory if not set
    if (dir == NULL) {
        dir = DEFAULT_THEME_DIR;
    }
}

// Function to load a theme bitmap from disk and cache it
void *load_theme(const char *name) {
    // Create a new theme structure for the bitmap
    struct Theme *theme = malloc(sizeof(struct Theme));
    memset(theme, 0, sizeof(struct Theme));

    // Set the name and size of the theme
    theme->name = strdup(name);
    theme->size = get_file_size(name);

    // Load the theme bitmap from disk
    int fd = open(name, O_RDONLY);
    void *bitmap = mmap(NULL, theme->size, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);

    // Set the bitmap in the theme structure
    theme->bitmap = bitmap;

    return theme;
}

// Function to cache a theme bitmap
void cache_theme(struct Theme *theme) {
    // Check if the cache is full
    if (cache->count == MAX_THEMES) {
        // Evict the least recently used theme from the cache
        evict_theme();
    }

    // Add the new theme to the cache
    cache->themes[cache->count] = *theme;
    cache->count++;
}

// Function to evict a theme bitmap from the cache
void evict_theme() {
    // Find the least recently used theme in the cache
    struct Theme *least_recently_used = NULL;
    for (int i = 0; i < MAX_THEMES; i++) {
        if (cache->themes[i].bitmap != NULL && least_recently_used == NULL) {
            least_recently_used = &cache->themes[i];
        } else if (cache->themes[i].bitmap != NULL &&
                   cache->themes[i].timestamp < least_recently_used->timestamp) {
            least_recently_used = &cache->themes[i];
        }
    }

    // Remove the least recently used theme from the cache
    if (least_recently_used != NULL) {
        // Unmap and free the bitmap
        munmap(least_recently_used->bitmap, least_recently_used->size);
        free(least_recently_used->name);
        least_recently_used->bitmap = NULL;
    }
}

// Function to get the size of a file in bytes
int get_file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        return st.st_size;
    } else {
        return -1;
    }
}

// Function to parse a PNG file from the cache root directory
void *parse_png(const char *name) {
    // Load the theme bitmap from disk if it's not in the cache
    struct Theme *theme = NULL;
    for (int i = 0; i < MAX_THEMES; i++) {
        if (cache->themes[i].bitmap != NULL && strcmp(name, cache->themes[i].name) == 0) {
            theme = &cache->themes[i];
            break;
        }
    }
    if (theme == NULL) {
        theme = load_theme(name);
        cache_theme(theme);
    }

    // Return the theme bitmap
    return theme->bitmap;
}

// Function to get the default theme directory
const char *get_default_theme_dir() {
    return DEFAULT_THEME_DIR;
}

// Function to set the default theme directory
void set_default_theme_dir(const char *dir) {
    // Set the default theme directory if it's not already set
    if (get_default_theme_dir() == NULL) {
        DEFAULT_THEME_DIR = dir;
    }
}

// Function to get the theme bitmap for a given name
void *get_theme(const char *name) {
    // Load the theme bitmap from disk if it's not in the cache
    struct Theme *theme = NULL;
    for (int i = 0; i < MAX_THEMES; i++) {
        if (cache->themes[i].bitmap != NULL && strcmp(name, cache->themes[i].name) == 0) {
            theme = &cache->themes[i];
            break;
        }
    }
    if (theme == NULL) {
        theme = load_theme(name);
        cache_theme(theme);
    }

    // Return the theme bitmap
    return theme->bitmap;
}

// Function to set a theme bitmap for a given name
void set_theme(const char *name, void *bitmap) {
    // Create a new theme structure for the bitmap
    struct Theme *theme = malloc(sizeof(struct Theme));
    memset(theme, 0, sizeof(struct Theme));

    // Set the name and size of the theme
    theme->name = strdup(name);
    theme->size = get_file_size(name);

    // Load the theme bitmap from disk
    int fd = open(name, O_RDONLY);
    void *new_bitmap = mmap(NULL, theme->size, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);

    // Set the bitmap in the theme structure
    theme->bitmap = new_bitmap;

    // Add the new theme to the cache
    if (cache == NULL) {
        init_cache();
    }
    cache_theme(theme);
}

// Function to get the size of a theme bitmap
int get_theme_size(void *bitmap) {
    return ((struct Theme *) bitmap)->size;
}

// Function to free a theme bitmap
void free_theme(void *bitmap) {
    struct Theme *theme = (struct Theme *) bitmap;
    // Unmap and free the bitmap
    munmap(theme->bitmap, theme->size);
    free(theme->name);
}

// Function to reset the cache
void reset_cache() {
    if (cache != NULL) {
        for (int i = 0; i < MAX_THEMES; i++) {
            if (cache->themes[i].bitmap != NULL) {
                munmap(cache->themes[i].bitmap, cache->themes[i].size);
                free(cache->themes[i].name);
                cache->themes[i].bitmap = NULL;
            }
        }
    }
}
