#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>
#include <tiffio.h>

struct tiff_metadata {
    uint16_t bits_per_sample;
    uint16_t samples_per_pixel;
    uint16_t extra_samples;
    unsigned char* image_data;
};

// Function to parse a TIFF image file and extract metadata
struct tiff_metadata parse_tiff(const char* filename) {
    struct tiff_metadata metadata = {};
    TIFF* tif = TIFFOpen(filename, "r");
    if (!tif) {
        printf("Failed to open TIFF file %s\n", filename);
        return metadata;
    }

    // Read the TIFF header and determine the image format
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &metadata.bits_per_sample);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &metadata.samples_per_pixel);
    TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &metadata.extra_samples);

    // Allocate memory for the image data and read it from the file
    uint64_t image_size = TIFFScanlineSize(tif);
    metadata.image_data = malloc(image_size * sizeof(unsigned char));
    if (!metadata.image_data) {
        printf("Failed to allocate memory for image data\n");
        TIFFClose(tif);
        return metadata;
    }
    for (uint32_t i = 0; i < TIFFNumberOfStrips(tif); i++) {
        if (TIFFReadEncodedStrip(tif, i, metadata.image_data + i * image_size) < 0) {
            printf("Failed to read strip %d\n", i);
            free(metadata.image_data);
            TIFFClose(tif);
            return metadata;
        }
    }

    // Compute the MD5 hash of the raw image data and close the file
    MD5_CTX md5_context;
    MD5Init(&md5_context);
    MD5Update(&md5_context, metadata.image_data, image_size);
    MD5Final(&md5_context);
    unsigned char hash[MD5_DIGEST_LENGTH];
    memcpy(hash, md5_context.digest, sizeof(hash));
    TIFFClose(tif);

    // Return the extracted metadata
    return (struct tiff_metadata){ .bits_per_sample = metadata.bits_per_sample,
                                  .samples_per_pixel = metadata.samples_per_pixel,
                                  .extra_samples = metadata.extra_samples,
                                  .image_data = metadata.image_data };
}
```
This function uses the `TIFFOpen()` and `TIFFClose()` functions from the `tiffio.h` header to open and close the TIFF file, respectively. It also uses the `TIFFGetField()` function to retrieve the values of the `BITSPERSAMPLE`, `SAMPLESPERPIXEL`, and `EXTRASAMPLES` tags from the TIFF file header.

The function allocates memory for the image data using `malloc()`, which is checked for errors before proceeding with reading the image data from the file. If an error occurs during read operations, the function prints an error message and frees any allocated memory before returning.

Once the image data has been read into memory, the function computes the MD5 hash of the raw binary data using the `MD5_CTX` structure and the `MD5Init()`, `MD5Update()`, and `MD5Final()` functions from the `openssl/md5.h` header. The resulting hash is then stored in a local variable named `hash`.

Finally, the function returns the extracted metadata as a structured format containing the values of the `BITSPERSAMPLE`, `SAMPLESPERPIXEL`, and `EXTRASAMPLES` tags, as well as a pointer to the image data. The memory allocated for the image data is freed before returning.']

