// Define the AES-256-CBC cipher and key sizes
#define CIPHER_KEY_SIZE 32
#define CIPHER_BLOCK_SIZE 16
#define KEY_DERIVATION_ITERATIONS 1000

// Structure to hold the AES-256-CBC cipher context and cache resources
typedef struct {
    EVP_CIPHER_CTX *cipher_ctx;
    unsigned char iv[CIPHER_BLOCK_SIZE];
    unsigned char key[CIPHER_KEY_SIZE];
    bool initialized;
} AES256CBCContext;

// Function to initialize the AES-256-CBC cipher using a given password and generate random IV and securely store it
AES256CBCContext *initialize_aes256cbc(const unsigned char *password, const char *theme_dir) {
    // Allocate memory for the AES-256-CBC cipher context and cache resources
    AES256CBCContext *ctx = malloc(sizeof(AES256CBCContext));
    if (ctx == NULL) {
        return NULL;
    }

    // Generate a random IV using OpenSSL's RAND_bytes() function
    unsigned char iv[CIPHER_BLOCK_SIZE];
    RAND_bytes(iv, CIPHER_BLOCK_SIZE);

    // Derive the key from the password using OpenSSL's EVP_BytesToKey() function with a secure KDF and random salt
    unsigned char salt[16];
    RAND_bytes(salt, 16);
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha1(), salt, password, strlen(password), KEY_DERIVATION_ITERATIONS, ctx->key, NULL);

    // Initialize the AES-256-CBC cipher context using the derived key and IV
    if (!EVP_EncryptInit_ex(ctx->cipher_ctx, EVP_aes_256_cbc(), NULL, ctx->key, iv)) {
        free(ctx);
        return NULL;
    }

    // Store the generated IV and key securely in the cache resources
    memcpy(ctx->iv, iv, CIPHER_BLOCK_SIZE);
    memset(salt, 0, 16);

    // Set the initialized flag to true
    ctx->initialized = true;

    return ctx;
}

// Function to clear the AES-256-CBC cipher context and cache resources when they are no longer needed
void clear_aes256cbc(AES256CBCContext *ctx) {
    // If the context is not initialized, return immediately
    if (!ctx->initialized) {
        return;
    }

    // Free the AES-256-CBC cipher context and clear the cache resources
    EVP_CIPHER_CTX_cleanup(ctx->cipher_ctx);
    memset(ctx->key, 0, CIPHER_KEY_SIZE);
    memset(ctx->iv, 0, CIPHER_BLOCK_SIZE);
    free(ctx);
}

