        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Check if the file is a bitmap and cache it in memory
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char *path = malloc(strlen(theme_dir) + strlen(entry->d_name) + 2);
        if (path == NULL) {
            break;
        }

        sprintf(path, "%s/%s", theme_dir, entry->d_name);
        unsigned char *bitmap = malloc(sizeof(unsigned char));
        if (bitmap == NULL) {
            free(path);
            break;
