    }
    if (timeout < 100 || timeout > 10000) {
        return ERR_OUT_OF_RANGE_TIMEOUT;
    }

    // Attempt to fetch data from external source
    int retry = 3;
    while (retry-- > 0) {
        if (fetchData(resource->connection, fetch_string)) {
            break;
        } else {
            sleep(1);
