    if (retry == -1) {
        return ERR_NETWORK_FAILURE;
    }

    // Encrypt data using Triple DES encryption
    int encLength = resource->connection->dataSize;
    unsigned char *encData = malloc(encLength);
    memset(encData, 0, encLength);
    if (des_encrypt(resource->connection->data, encData, key, iv) < 0) {
        return ERR_ENCRYPTION_FAILURE;
    }

    // Lock mutex to ensure thread safety when accessing shared resources
    int ret = pthread_mutex_lock(&(resource->mutex));
    if (ret != 0) {
        return ERR_MUTEX_LOCK_FAILURE;
    }

    // Pass encrypted data to callback function for further processing
    resource->callback(encData, encLength);

    // Unlock mutex and free resources
    pthread_mutex_unlock(&(resource->mutex));
    free(encData);

    return 0;
}

