using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;
using TIFF = System.Drawing.Imaging.ImageFormat;

namespace ImageProcessingService
{
    public class MetadataExtractor
    {
        private readonly FileStorageService _fileStorage;
        private readonly DatabaseServer _database;

        public MetadataExtractor(FileStorageService fileStorage, DatabaseServer database)
        {
            _fileStorage = fileStorage;
            _database = database;
        }

        public async Task<Metadata> ExtractMetadataAsync(byte[] imageData)
        {
            if (imageData == null || imageData.Length == 0)
                throw new ArgumentException("Image data cannot be empty", nameof(imageData));

            var tiff = TIFF.Tiff;
            using (var stream = new MemoryStream(imageData))
            {
                try
                {
                    // Read the image metadata from the TIFF header
                    tiff.ReadHeader(stream, false);

                    var width = tiff.Width;
                    var height = tiff.Height;
                    var bitDepth = tiff.BitDepth;
                    var compression = tiff.Compression;
                    var photometric = tiff.PhotometricInterpretation;

                    // Check for supported image formats and bit depths
                    if (bitDepth != 1 && bitDepth != 2 && bitDepth != 4 && bitDepth != 8 && bitDepth != 16)
                        throw new ArgumentException("Unsupported image format", nameof(imageData));

                    // Compute the MD5 hash of the raw binary data
                    var md5 = MD5.Create();
                    byte[] hash = md5.ComputeHash(stream);

                    // Store the extracted metadata in a structured format within the database
                    var metadata = new Metadata
                    {
                        Width = width,
                        Height = height,
                        BitDepth = bitDepth,
                        Compression = compression,
                        PhotometricInterpretation = photometric,
                        MD5Hash = hash
                    };

                    await _database.SaveMetadataAsync(metadata);

                    // Handle cases where the image contains invalid data or unsupported features
                    if (tiff.NumberOfDirectories > 1)
                        throw new ArgumentException("Multiple directories are not supported", nameof(imageData));
                }
                catch (ArgumentException ex)
                {
                    throw;
                }
                finally
                {
                    stream.Close();
                }
            }
        }
    }
}
