using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace EncryptionDecryption
{
    public class MessageProcessor
    {
        private readonly byte[] _key;
        private readonly byte[] _iv;
        private readonly EncryptionMode _mode;

        public MessageProcessor(byte[] key, byte[] iv, EncryptionMode mode)
        {
            _key = key;
            _iv = iv;
            _mode = mode;
        }

        public Task<byte[]> DecryptAsync(string message)
        {
            return DecryptAsync(Convert.FromBase64String(message));
        }

        private async Task<byte[]> DecryptAsync(byte[] ciphertext)
        {
            using (var des = new TripleDES(_key, _iv))
            {
                switch (_mode)
                {
                    case EncryptionMode.CBC:
                        return await des.DecryptCbcAsync(ciphertext);
                    case EncryptionMode.ECB:
                        return await des.DecryptEcbAsync(ciphertext);
                    case EncryptionMode.CFB:
                        return await des.DecryptCfbAsync(ciphertext);
                }
            }
            return null;
        }

        public async Task<bool> ValidateMessageAsync(string message)
        {
            var ciphertext = Convert.FromBase64String(message);
            var decrypted = await DecryptAsync(ciphertext);
            if (decrypted == null)
            {
                // Log an error
                Console.WriteLine("Error decrypting message");
                return false;
            }
            var length = decrypted.Length;
            if (length < 10 || length > 256)
            {
                // Log a warning
                Console.WriteLine("Message length out of range");
                return false;
            }
            if (!ChecksumAlgorithm.Validate(decrypted))
            {
                // Log an error
                Console.WriteLine("Invalid checksum");
                return false;
            }
            return true;
        }
    }
}
