use std::env;
use std::fs::File;
use std::io::Write;
use std::path::PathBuf;
use tokio::sync::mpsc;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        println!("Usage: {} [tasks]", args[0]);
        return;
    }

    let (tx, rx) = mpsc::channel(10);

    for task in &args[1..] {
        // Spawn a separate task for each task provided as an argument
        tokio::spawn(async move {
            let result = process_task(task).await;
            tx.send(result).await.unwrap();
        });
    }

    // Create a log file with the current timestamp
    let now = chrono::Utc::now().to_rfc3339();
    let mut log_file = PathBuf::from("logs/").push(now);
    log_file.set_extension("log");
    let mut file = File::create(log_file).unwrap();

    // Receive the results from each task and write them to the log file
    while let Some(result) = rx.recv().await {
        if result.is_err() {
            eprintln!("Error processing task: {}", result.unwrap_err());
            continue;
        }
        let result = result.unwrap();
        let log_line = format!("{}: {}", now, result);
        file.write_all(log_line.as_bytes()).unwrap();
    }
}

async fn process_task(task: &str) -> Result<String, Box<dyn std::error::Error>> {
    // Fetch the data from an external API using the async-http library
    let response = surf::get(&format!("https://api.example.com/{}", task))
        .await?;
    if !response.status().is_success() {
        return Err(Box::new(surf::http::Error::from(response)));
    }
    // Parse the response data as JSON and extract the relevant information
    let data: serde_json::Value = response.body_json().await?;
    let result = data["result"].as_str().unwrap();
    Ok(result.to_string())
}
