#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include "nfapi_types.h"

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    int rnti;
} RX_UE_INFORMATION_TAG;

void* allocate_rx_ue_information_tags(int num_elements, int *num_unique_rnti) {
    // Initialize variables
    int i, j, k;
    int *rntis = NULL;
    RX_UE_INFORMATION_TAG **tags = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Check for invalid input parameters
    if (num_elements <= 0 || num_unique_rnti == NULL) {
        printf("Error: Invalid input parameters\n");
        return NULL;
    }

    // Allocate memory for RNTIs and tags array
    rntis = malloc(sizeof(int) * num_elements);
    if (rntis == NULL) {
        printf("Error: Memory allocation failed for RNTIs\n");
        return NULL;
    }
    tags = malloc(sizeof(RX_UE_INFORMATION_TAG *) * num_elements);
    if (tags == NULL) {
        printf("Error: Memory allocation failed for tags array\n");
        free(rntis);
        return NULL;
    }

    // Initialize RNTIs and tags array
    for (i = 0; i < num_elements; i++) {
        rntis[i] = rand() % 65536;
        tags[i] = malloc(sizeof(RX_UE_INFORMATION_TAG));
        if (tags[i] == NULL) {
            printf("Error: Memory allocation failed for tag at index %d\n", i);
            free(rntis);
            free(tags);
            return NULL;
        }
    }

    // Populate RNTIs and tags array with unique elements
    pthread_mutex_lock(&mutex);
    *num_unique_rnti = 0;
    for (i = 0; i < num_elements; i++) {
        for (j = 0; j < i; j++) {
            if (rntis[j] == rntis[i]) {
                // Generate a new RNTI if the current one is not unique
                do {
                    rntis[i] = rand() % 65536;
                } while (find_rnti(rntis, *num_unique_rnti, rntis[i]));
                break;
            }
        }
        tags[i]->pdu.rx_ue_information.rx_ue_information_rel8.crc_flag = rand() % 2;
        tags[i]->rnti = rntis[i];
        *num_unique_rnti += 1;
    }
    pthread_mutex_unlock(&mutex);

    // Shuffle the RNTIs and tags array randomly
    shuffle(rntis, tags, num_elements);

    // Free memory for RNTIs array
    free(rntis);

    return tags;
}

int find_rnti(int *rntis, int size, int rnti) {
    for (int i = 0; i < size; i++) {
        if (rntis[i] == rnti) {
            return 1;
        }
    }
    return 0;
}

void shuffle(int *rntis, RX_UE_INFORMATION_TAG **tags, int size) {
    // Fisher-Yates shuffle algorithm
    for (int i = size - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        swap(rntis[i], rntis[j]);
        swap(tags[i]->pdu.rx_ue_information.rx_ue_information_rel8.crc_flag, tags[j]->pdu.rx_ue_information.rx_ue_information_rel8.crc_flag);
        swap(tags[i], tags[j]);
    }
}

void swap(int a, int b) {
    int temp = a;
    a = b;
    b = temp;
}
