        if (client_fd < 0) {
            err = 1;
            printf("ERROR: Failed to accept incoming connection\n");
        } else {
            // Handle incoming connection in new thread
            pthread_t client_thread;
            pthread_create(&client_thread, NULL, handle_client, (void *)&client_fd);
        }
    }

    // Clean up and return success
    close(sockfd);
    ERR_free_strings();
    return 0;
}

// Define function to handle incoming connections in new thread
void *handle_client(void *args) {
    int client_fd = *((int *)args);
    TX_QUEUE_DATA_ITEM *session = malloc(sizeof(TX_QUEUE_DATA_ITEM));
    if (session == NULL) {
        printf("ERROR: Failed to allocate memory for session\n");
        close(client_fd);
        return NULL;
    }

    // Initialize SSL context and set up encryption
    SSL_CTX *ctx = SSL_CTX_new(TLS_client_method());
    if (ctx == NULL) {
        printf("ERROR: Failed to create SSL context\n");
        free(session);
        close(client_fd);
        return NULL;
    }
    SSL *ssl = SSL_new(ctx);
    if (SSL_set_fd(ssl, client_fd) < 0) {
        printf("ERROR: Failed to set file descriptor for SSL\n");
        SSL_free(ssl);
        free(session);
        close(client_fd);
        return NULL;
    }
    if (SSL_connect(ssl) != 1) {
        printf("ERROR: Failed to establish SSL connection\n");
        SSL_free(ssl);
        free(session);
        close(client_fd);
        return NULL;
    }

    // Initialize session and start receiving data
    session->session_id = 1;
    session->sequence_num = 0;
    session->payload_size = 0;
    while (1) {
        // Read data from client
        char *data = malloc(sizeof(char) * RECV_BUFFER_SIZE);
        int recv_bytes = SSL_read(ssl, data, RECV_BUFFER_SIZE);
        if (recv_bytes < 0) {
            printf("ERROR: Failed to read from SSL socket\n");
            free(data);
            break;
        } else if (recv_bytes == 0) {
            // Client disconnected
            printf("INFO: Client disconnected\n");
            free(data);
            break;
        } else {
            // Update session statistics and log received data
            session->sequence_num++;
            session->payload_size += recv_bytes;
            printf("INFO: Received %d bytes from client %d, sequence number %lu\n", recv_bytes, session->session_id, session->sequence_num);
        }
    }

    // Clean up and return success
    SSL_free(ssl);
    free(session);
    close(client_fd);
    return NULL;
}
```
