// Structure to represent a node in the linked list
typedef struct Node {
    char* string;
    struct Node* next;
} Node;

// Function to read and store strings from a file stream into a linked list
void process_strings(FILE* file) {
    // Create an empty linked list
    Node* head = NULL;

    // Read each line from the file stream and add it to the linked list
    char buffer[256];
    while (fgets(buffer, 256, file)) {
        // Trim newline character at the end of the string
        int len = strlen(buffer);
        if (buffer[len - 1] == '\n') {
            buffer[len - 1] = '\0';
        }

        // Create a new node for the current string
        Node* node = malloc(sizeof(Node));
        node->string = strdup(buffer);
        node->next = NULL;

        // Add the node to the end of the linked list
        if (head == NULL) {
            head = node;
        } else {
            Node* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = node;
        }
    }

    // Find the longest string in the linked list and print it
    int longest_len = 0;
    Node* longest = NULL;
    for (Node* current = head; current != NULL; current = current->next) {
        if (strlen(current->string) > longest_len) {
            longest_len = strlen(current->string);
            longest = current;
        }
    }
    printf("%s\n", longest->string);

    // Release the memory used by the linked list
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp->string);
        free(temp);
    }
}
