void selectAttackVector() {
    // Generate a random number between 0 and the maximum cooldown period
    int cooldownPeriod = rand() % (COOLDOWN_MAXIMUM - COOLDOWN_MINIMUM + 1) + COOLDOWN_MINIMUM;

    // Sleep for the generated cooldown period to simulate network latency
    this_thread::sleep_for(chrono::milliseconds(cooldownPeriod));

    // Generate a random number between 0 and the number of attack vectors - 1
    int selectedAttackVectorIndex = rand() % ATTACK_VECTOR_COUNT;

    // Print the selected attack vector and its associated latency to the console
    cout << "Selected attack vector: " << attackVectors[selectedAttackVectorIndex] << " with cooldown period: " << cooldownPeriod << endl;
}
