// Define the structure to hold the CRC indication information
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the pool of structures to hold the CRC indication information
static NFAPI_CRC_INDICATION_PDU_T *pool = NULL;

// Define a counter to track the total number of unique RNTIs assigned
static uint32_t total_rnti = 0;

// Define a threshold for compacting the allocated memory if fragmentation exceeds
#define MEMORY_COMPACTION_THRESHOLD (1.0 / 8)

// Initialize the pool of structures with the specified number of elements N
void initialize_pool(uint32_t N) {
    // Allocate an array of pointers to hold the structure instances
    pool = calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T *));

    if (pool == NULL) {
        fprintf(stderr, "Failed to allocate memory for CRC indication pool\n");
        return;
    }

    // Initialize each structure instance with a unique RNTI and random CRCFLAG
    uint32_t i;
    for (i = 0; i < N; i++) {
        pool[i] = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pool[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory for CRC indication structure instance\n");
            return;
        }

        pool[i]->RX_UE_INFORMATION_TAG = i + 1;
        pool[i]->RNTI = total_rnti++;
        pool[i]->CRCFLAG = (uint8_t)(rand() % UINT8_MAX);
    }
}

// Shuffle the pool of structures randomly
void shuffle_pool(void) {
    // Generate a random seed value using the current time
    srand((unsigned int)time(NULL));

    // Iterate through each structure instance and swap it with another instance chosen at random
    uint32_t i;
    for (i = 0; i < N; i++) {
        uint32_t j = rand() % N;
        if (j != i) {
            NFAPI_CRC_INDICATION_PDU_T *tmp = pool[i];
            pool[i] = pool[j];
            pool[j] = tmp;
        }
    }
}

// Compact the allocated memory if fragmentation exceeds the threshold
void compact_memory(void) {
    // Calculate the current fragmentation ratio
    float frag_ratio = (float)(pool_size - total_rnti) / pool_size;

    // If the fragmentation ratio exceeds the threshold, compact the memory
    if (frag_ratio > MEMORY_COMPACTION_THRESHOLD) {
        uint32_t i = 0;
        while (i < total_rnti - 1) {
            if (pool[i] == NULL || pool[i + 1] == NULL) {
                break;
            }

            // If the current and next structures are adjacent, compact them together
            if ((uintptr_t)(pool[i]) + sizeof(NFAPI_CRC_INDICATION_PDU_T) == (uintptr_t)(pool[i + 1])) {
                pool[i] = realloc(pool[i], (total_rnti - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (pool[i] == NULL) {
                    fprintf(stderr, "Failed to compact memory for CRC indication pool\n");
                    return;
                }
            } else {
                i++;
            }
        }
    }
}

// Serialize the pool of structures to a file
void serialize_pool(const char *filename) {
    // Open the file for writing in binary mode
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for serializing CRC indication pool\n");
        return;
    }

    // Write the number of structures in the pool to the file
    uint32_t num_structures = total_rnti;
    if (fwrite(&num_structures, sizeof(uint32_t), 1, fp) != 1) {
        fclose(fp);
        fprintf(stderr, "Failed to write number of structures to serialized file\n");
        return;
    }

    // Write each structure instance in the pool to the file
    uint32_t i;
    for (i = 0; i < total_rnti; i++) {
        if (fwrite(pool[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp) != 1) {
            fclose(fp);
            fprintf(stderr, "Failed to write structure instance %u to serialized file\n", i);
            return;
        }
    }

    // Close the file
    if (fclose(fp) == EOF) {
        fprintf(stderr, "Failed to close file after serializing CRC indication pool\n");
        return;
    }
}

// Deserialize the pool of structures from a file
void deserialize_pool(const char *filename) {
    // Open the file for reading in binary mode
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for deserializing CRC indication pool\n");
        return;
    }

    // Read the number of structures in the file
    uint32_t num_structures = 0;
    if (fread(&num_structures, sizeof(uint32_t), 1, fp) != 1) {
        fclose(fp);
        fprintf(stderr, "Failed to read number of structures from serialized file\n");
        return;
    }

    // Initialize the pool with the specified number of elements
    initialize_pool(num_structures);

    // Read each structure instance in the file and assign it to the corresponding index in the pool
    uint32_t i;
    for (i = 0; i < num_structures; i++) {
        if (fread(pool[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp) != 1) {
            fclose(fp);
            fprintf(stderr, "Failed to read structure instance %u from serialized file\n", i);
            return;
        }
    }

    // Close the file
    if (fclose(fp) == EOF) {
        fprintf(stderr, "Failed to close file after deserializing CRC indication pool\n");
        return;
    }
}
