int read_integers(int *array, int size) {
    // Allocate memory for the integer array
    int *input = malloc(size * sizeof(int));
    if (input == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for integer array\n");
        return 1;
    }

    // Read integers from standard input
    printf("Enter %d integers separated by spaces: ", size);
    int count = 0;
    while (count < size && scanf("%d", &input[count]) == 1) {
        if (input[count] < 0 || input[count] > UINT_MAX) {
            fprintf(stderr, "Error: Invalid integer value %d\n", input[count]);
            break;
        }
        count++;
