    // Validate the CRCFLAG to ensure it meets specific operational requirements
    for (int i = 0; i < count; i++) {
        if (input[i] % 2 != 0) {
            fprintf(stderr, "Error: Invalid CRCFLAG value for integer %d\n", input[i]);
            return 1;
        }
    }

    // Populate the NFAPI_CRC_INDICATION_PDU_T structures
    int max = INT_MIN;
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structures\n");
        return 1;
    }
    for (int i = 0; i < count; i++) {
        pdu[i].RX_UE_INFORMATION_TAG = input[i];
        pdu[i].RNTI = input[i] + 1000;
        pdu[i].CRCFLAG = (uint8_t)(input[i] % 2);
        if (pdu[i].RX_UE_INFORMATION_TAG > max) {
            max = pdu[i].RX_UE_INFORMATION_TAG;
        }
    }

    // Print the largest integer in the array using a separate function
    printf("The largest integer in the array is %d\n", max);

    // Clean up memory
    free(input);
    free(pdu);

    return 0;
}
