    while (max_size < MAX_SIZE) {
      records = realloc(records, sizeof(*records) * (max_size + 1));
      if (records != NULL) {
        break;
      }
      max_size++;
    }
    if (records == NULL) {
      fprintf(stderr, "Failed to allocate memory. Exiting.\n");
      return 1;
    }
  }

  pthread_mutex_t *locks = malloc(sizeof(*locks) * length); // lock for each record
  if (locks == NULL) {
    fprintf(stderr, "Failed to allocate locks. Exiting.\n");
    return 1;
  }

  int i;
  for (i = 0; i < length; i++) {
    locks[i] = PTHREAD_MUTEX_INITIALIZER; // initialize locks
  }

  pthread_t thread1, thread2;
  pthread_create(&thread1, NULL, &my_function, (void *)records); // create threads
  pthread_create(&thread2, NULL, &my_function, (void *)records + length/2);

  int result = pthread_join(thread1, NULL); // wait for threads to finish
  if (result != 0) {
    fprintf(stderr, "Failed to join thread. Exiting.\n");
    return 1;
  }

  result = pthread_join(thread2, NULL);
  if (result != 0) {
    fprintf(stderr, "Failed to join thread. Exiting.\n");
    return 1;
  }
}
