#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
} Record;

void initDynamicArray(Record** array, size_t numRecords, int minKey, int maxKey) {
    // Allocate memory for the dynamic array
    *array = (Record*) malloc(numRecords * sizeof(Record));
    if (*array == NULL) {
        perror("Failed to allocate memory for dynamic array");
        exit(1);
    }

    // Initialize semaphore for thread-safe access to shared resources
    sem_t* sem = sem_open("semaphore", O_CREAT, 0644, numRecords);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        exit(1);
    }

    // Initialize records with random keys and offsets within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < numRecords; ++i) {
        (*array)[i].key = rand() % (maxKey - minKey + 1) + minKey;
        (*array)[i].offset = rand() % 1000000;
    }

    // Free semaphore when not needed anymore
    if (sem_close(sem) == -1) {
        perror("Failed to close semaphore");
        exit(1);
    }
}

void destroyDynamicArray(Record** array, size_t numRecords) {
    // Free memory for the dynamic array
    free(*array);
    *array = NULL;

    // Destroy semaphore
    if (sem_unlink("semaphore") == -1) {
        perror("Failed to destroy semaphore");
        exit(1);
    }
}
