}

// Function to maintain a rolling buffer of the last 100 entries, which will be used for generating real-time reports and monitoring trends
void maintain_buffer() {
    // Initialize the buffer with zero values
    memset(buffer, 0, sizeof(buffer));

    // Dynamically allocate memory for each entry in the buffer
    char *entry = NULL;
    size_t len = 0;
