// define error codes
#define FILE_OPEN_ERROR -1
#define INVALID_TRANSFORMATION_RULES -2
#define CONFIGURATION_FILE_ERROR -3

// function to read the input file and return its contents as a string
char* readInputFile(const char* filename) {
  FILE* fp = fopen(filename, "r");
  if (!fp) {
    printf("Error opening file %s: %s\n", filename, strerror(errno));
    return NULL;
  }

  // get the size of the input file
  fseek(fp, 0, SEEK_END);
  long fileSize = ftell(fp);
  rewind(fp);

  // allocate memory for the input file contents
  char* buffer = (char*)malloc(fileSize + 1);
  if (!buffer) {
    printf("Error allocating memory for input file %s\n", filename);
    fclose(fp);
    return NULL;
  }

  // read the entire input file into the allocated buffer
  size_t bytesRead = fread(buffer, 1, fileSize, fp);
  if (bytesRead != fileSize) {
    printf("Error reading file %s: %s\n", filename, strerror(errno));
    free(buffer);
    fclose(fp);
    return NULL;
  }

  // close the input file and return the contents as a string
  fclose(fp);
  buffer[fileSize] = '\0';
  return buffer;
}

// function to apply transformation rules to the input string
char* transformInputString(const char* input, const char* rules) {
