}

// function to compress the output file using gzip
void compressOutputFile(const char* filename) {
  FILE* fp = fopen(filename, "rb");
  if (!fp) {
    printf("Error opening file %s for compression: %s\n", filename, strerror(errno));
    return;
  }

  // allocate memory for the compressed output
  long fileSize = ftell(fp);
  rewind(fp);
  char* buffer = (char*)malloc(fileSize + 1);
  if (!buffer) {
    printf("Error allocating memory for compressed output\n");
    fclose(fp);
    return;
  }

  // read the entire input file into the allocated buffer
  size_t bytesRead = fread(buffer, 1, fileSize, fp);
  if (bytesRead != fileSize) {
    printf("Error reading file %s for compression: %s\n", filename, strerror(errno));
    free(buffer);
    fclose(fp);
    return;
  }

  // close the input file and compress the contents using gzip
  fclose(fp);
  int compressedSize = compressBound(fileSize) + 18; // add 18 bytes for gzip header
  char* compressedBuffer = (char*)malloc(compressedSize);
  if (!compressedBuffer) {
    printf("Error allocating memory for compressed output\n");
    free(buffer);
    return;
  }
  compress(compressedBuffer, &compressedSize, buffer, fileSize);
  free(buffer);

  // write the compressed contents to disk
  FILE* fpOut = fopen("output.gz", "wb");
  if (!fpOut) {
    printf("Error opening output file for compression: %s\n", strerror(errno));
    free(compressedBuffer);
    return;
  }
  size_t bytesWritten = fwrite(compressedBuffer, 1, compressedSize, fpOut);
  if (bytesWritten != compressedSize) {
    printf("Error writing output file for compression: %s\n", strerror(errno));
    free(compressedBuffer);
    fclose(fpOut);
    return;
  }
  fclose(fpOut);
  free(compressedBuffer);
}

// main function to read the input file, apply transformation rules, and write the output file
int main(int argc, char* argv[]) {
  if (argc < 5) {
    printf("Usage: %s <input_file> <output_file> <transformation_rules> <compression_flag> <configuration_file>\n", argv[0]);
    return -1;
  }

  // read the input file and transform its contents according to the given rules
  char* inputFile = readInputFile(argv[1]);
  if (!inputFile) {
    printf("Error reading input file %s\n", argv[1]);
    return FILE_OPEN_ERROR;
  }
  char* transformedInput = transformInputString(inputFile, argv[3]);
  free(inputFile);
  if (!transformedInput) {
    printf("Error applying transformation rules to input file\n");
    return INVALID_TRANSFORMATION_RULES;
  }

  // write the transformed contents to disk
  FILE* fp = fopen(argv[2], "w");
  if (!fp) {
    printf("Error opening output file: %s\n", strerror(errno));
    free(transformedInput);
    return FILE_OPEN_ERROR;
  }
  size_t bytesWritten = fwrite(transformedInput, 1, strlen(transformedInput), fp);
  if (bytesWritten != strlen(transformedInput)) {
    printf("Error writing output file: %s\n", strerror(errno));
    free(transformedInput);
    fclose(fp);
    return FILE_OPEN_ERROR;
  }
  fclose(fp);
  free(transformedInput);

  // compress the output file if requested
  if (strcmp(argv[4], "true") == 0) {
    compressOutputFile(argv[2]);
  }

  return 0;
