#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <semaphore.h>

void task(int offset_size, int key_size) {
    // Validate input parameters
    if (offset_size <= 0 || offset_size > MAX_OFFSET_SIZE) {
        printf("Invalid offset size: %d\n", offset_size);
        return;
    }
    if (key_size <= 0 || key_size > MAX_KEY_SIZE) {
        printf("Invalid key size: %d\n", key_size);
        return;
    }

    // Allocate memory for offset and key arrays
    long* offsets = malloc(offset_size * sizeof(long));
    int* keys = malloc(key_size * sizeof(int));

    // Initialize arrays with random values within range
    srand(time(NULL));
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = rand() % MAX_OFFSET_SIZE;
    }
    for (int i = 0; i < key_size; i++) {
        keys[i] = rand() % MAX_KEY_SIZE;
    }

    // Create semaphore with initial value of 1 and timeout mechanism
    sem_t* sem = sem_open("sem", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return;
    }
    // Cleanup semaphore on exit
    atexit(cleanup_sem);

    // Set value of each record's int field to random value within range
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = rand() % MAX_OFFSET_SIZE;
        keys[i] = rand() % MAX_KEY_SIZE;
    }

    // Log operation of setting int field values
    printf("Setting int field values for %d records\n", offset_size);
    log_operation(offsets, key_size);

    // Delete semaphore after completing operations
    if (sem_close(sem) == -1 || sem_unlink(sem) == -1) {
        perror("Failed to delete semaphore");
    }
}

// Cleanup function for semaphore
void cleanup_sem() {
    // Check if semaphore exists and close it
    if (sem_exists()) {
        if (sem_close(sem) == -1) {
            perror("Failed to close semaphore");
        } else {
            if (sem_unlink(sem) == -1) {
                perror("Failed to delete semaphore");
            }
        }
    }
}

// Logging function for operation of setting int field values
void log_operation(long* offsets, int key_size) {
    // Check if logging is enabled and open the log file
    if (enable_logging()) {
        FILE* log_file = fopen("log.txt", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return;
        }
        // Log operation of setting int field values
        for (int i = 0; i < key_size; i++) {
            fprintf(log_file, "%ld %d\n", offsets[i], keys[i]);
        }
        if (fclose(log_file) == EOF) {
            perror("Failed to close log file");
        }
    }
}
