    if (records == NULL) {
        log("No memory has been allocated. Aborting operation");
        return;
    }

    // Loop through each record structure and adjust its size to minimize memory footprint
    for (int i = 0; i < num_records; ++i) {
        // Adjust the size of the key field to 4 bytes (32 bits)
        records[i].key = *(int*)&records[i].key;
    }
}
