    if (fp == NULL) {
        perror("popen");
        exit(EXIT_FAILURE);
    }

    // Capture and log both the standard output and error streams to a separate log file
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        printf("%s", buffer);
        fflush(stdout);
