// Implement a rotation mechanism for log files to maintain system performance and storage efficiency
void rotate_log_file() {
    struct stat st;
    if (stat(LOG_FILE, &st) == 0 && S_ISREG(st.st_mode)) {
        int fd = open(LOG_FILE, O_RDONLY);
        if (fd == -1) {
            perror("open");
            exit(EXIT_FAILURE);
        }

