// Function to serialize the sorted records in a file format optimized for storage space and retrieval speed
void serialize_records(int num_records, struct Record *records) {
    // Validate user input
    if (num_records < 0) {
        printf("Invalid input. Exiting.\n");
        return;
    }

    // Open a file in binary mode for writing
    FILE *file = fopen("sorted_records.bin", "wb");
    if (file == NULL) {
        printf("Error opening file. Exiting.\n");
        return;
    }

    // Write the number of records to the file
    int write_result = fwrite(&num_records, sizeof(int), 1, file);
    if (write_result != 1) {
        printf("Error writing to file. Exiting.\n");
        return;
