    // Write each record to the file
    for (int i = 0; i < num_records; i++) {
        write_result = fwrite(records[i].key, sizeof(int), 1, file);
        if (write_result != 1) {
            printf("Error writing to file. Exiting.\n");
            return;
        }
    }

    // Close the file
