// Function to initialize and manage the collection of network interfaces
void initNetworkInterfaces(int numInterfaces, struct NetworkInterface* interfaces) {
    for (int i = 0; i < numInterfaces; i++) {
        interfaces[i].interfaceName = NULL;
        interfaces[i].interfaceIndex = -1;
        interfaces[i].packetLoss = 0.0;
        interfaces[i].latency = 0.0;
        interfaces[i].throughput = 0.0;
    }
}

// Function to add a new network interface to the collection
void addNetworkInterface(struct NetworkInterface* interfaces, int numInterfaces, char* interfaceName) {
    for (int i = 0; i < numInterfaces; i++) {
        if (interfaces[i].interfaceName == NULL) {
            interfaces[i].interfaceName = interfaceName;
            interfaces[i].interfaceIndex = i;
            return;
        }
    }
}

// Function to update the metrics for a specific network interface in the collection
void updateNetworkInterfaceMetrics(struct NetworkInterface* interfaces, int numInterfaces, char* interfaceName, float packetLoss, float latency, float throughput) {
    for (int i = 0; i < numInterfaces; i++) {
        if (strcmp(interfaces[i].interfaceName, interfaceName) == 0) {
            interfaces[i].packetLoss = packetLoss;
            interfaces[i].latency = latency;
            interfaces[i].throughput = throughput;
            return;
        }
    }
}

// Function to dynamically resize the collection of network interfaces based on real-time resource utilization metrics
void resizeNetworkInterfaces(struct NetworkInterface* interfaces, int numInterfaces, float cpuUsage, float memoryUsage) {
    // Determine if the current number of interfaces is optimal for the given CPU and memory usage
    if (cpuUsage < 50 && memoryUsage < 70) {
        return; // No need to resize the collection
    } else {
        int newNumInterfaces = numInterfaces * 2; // Double the current number of interfaces
        struct NetworkInterface* newInterfaces = malloc(newNumInterfaces * sizeof(struct NetworkInterface)); // Allocate memory for the new interfaces
        if (newInterfaces == NULL) {
            printf("Error: Failed to allocate memory for new network interfaces.\n");
            return;
        }

        // Copy the existing interfaces into the new collection
        for (int i = 0; i < numInterfaces; i++) {
            newInterfaces[i].interfaceName = interfaces[i].interfaceName;
            newInterfaces[i].interfaceIndex = interfaces[i].interfaceIndex;
            newInterfaces[i].packetLoss = interfaces[i].packetLoss;
            newInterfaces[i].latency = interfaces[i].latency;
            newInterfaces[i].throughput = interfaces[i].throughput;
        }

        // Free the memory for the old collection and replace it with the new one
        free(interfaces);
        interfaces = newInterfaces;
        numInterfaces = newNumInterfaces;
    }
}

// Function to log significant changes in network interface metrics
void logNetworkInterfaceMetrics(struct NetworkInterface* interfaces, int numInterfaces, float packetLossThreshold, float latencyThreshold, float throughputThreshold) {
    for (int i = 0; i < numInterfaces; i++) {
        if (interfaces[i].packetLoss > packetLossThreshold || interfaces[i].latency > latencyThreshold || interfaces[i].throughput > throughputThreshold) {
            printf("Error: Network interface %s has experienced significant changes in metrics.\n", interfaces[i].interfaceName);
        }
    }
}

