    size_t count;
    pthread_mutex_t mutex;
} nfapi_crc_indication_list_t;

void nfapi_crc_indication_list_init(nfapi_crc_indication_list_t *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int nfapi_crc_indication_list_add(nfapi_crc_indication_list_t *list, RX_UE_INFORMATION_TAG *rx_ue_information, NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu) {
    nfapi_crc_indication_entry_t *entry = malloc(sizeof(nfapi_crc_indication_entry_t));
    if (!entry) {
        return -1;
    }
    entry->rx_ue_information = rx_ue_information;
    entry->crc_indication_pdu = crc_indication_pdu;
    pthread_mutex_lock(&list->mutex);
    list->entries[list->count++] = entry;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int nfapi_crc_indication_list_update(nfapi_crc_indication_list_t *list, RX_UE_INFORMATION_TAG *rx_ue_information, NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->entries[i]->rx_ue_information == rx_ue_information && list->entries[i]->crc_indication_pdu == crc_indication_pdu) {
            list->entries[i]->rx_ue_information = rx_ue_information;
            list->entries[i]->crc_indication_pdu = crc_indication_pdu;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

int nfapi_crc_indication_list_remove(nfapi_crc_indication_list_t *list, RX_UE_INFORMATION_TAG *rx_ue_information, NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->entries[i]->rx_ue_information == rx_ue_information && list->entries[i]->crc_indication_pdu == crc_indication_pdu) {
            free(list->entries[i]);
            list->count--;
            if (i < list->count) {
                memmove(&list->entries[i], &list->entries[i + 1], sizeof(nfapi_crc_indication_entry_t *) * (list->count - i));
            }
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

void nfapi_crc_indication_list_destroy(nfapi_crc_indication_list_t *list) {
    for (size_t i = 0; i < list->count; i++) {
        free(list->entries[i]);
    }
    pthread_mutex_destroy(&list->mutex);
}
