// Global variables
int num_files = 0;
int num_lines = 0;
int total_lines = 0;
int processed_files = 0;
int num_threads = 10; // Default number of threads to use for processing files in parallel
char *output_file = "results.txt"; // Default output file name
char *input_dir = NULL; // Input directory path
char *regex_pattern = NULL; // Regex pattern for filtering files
int progress_interval = 10; // Progress reporting interval (default: 10 files)
bool verbose = false; // Verbose mode flag

// Function prototypes
void process_file(FILE *fp);
void process_directory(DIR *dirp);
void print_usage();
void log_error(char *msg);

int main(int argc, char **argv) {
  // Parse command line arguments
  int opt;
  while ((opt = getopt(argc, argv, "i:o:cs:p:")) != -1) {
    switch (opt) {
      case 'i': input_dir = optarg; break;
      case 'o': output_file = optarg; break;
      case 'c': regex_pattern = optarg; break;
      case 's': num_threads = atoi(optarg); break;
      case 'p': progress_interval = atoi(optarg); break;
      case '?': print_usage(); return 1;
    }
  }

  // Check for mandatory options and provide usage information if not provided
  if (input_dir == NULL) {
    print_usage();
    return 2;
  }

  // Open output file for writing
  FILE *output = fopen(output_file, "a");
  if (output == NULL) {
    log_error("Failed to open output file");
    return 3;
  }

  // Create a directory stream and process the input directory recursively
  DIR *dirp = opendir(input_dir);
  if (dirp == NULL) {
    log_error("Failed to open input directory");
    fclose(output);
    return 4;
  }

  // Create a thread pool and initialize the file management utility
  pthread_t *threads = malloc(num_threads * sizeof(pthread_t));
  FileManager *file_manager = initFileManager();

  // Process the input directory recursively, creating threads for each subdirectory
  process_directory(dirp);

  // Join all threads and close the output file
  for (int i = 0; i < num_threads; ++i) {
    pthread_join(threads[i], NULL);
  }
  free(threads);
  fclose(output);

  // Print total line count and processing statistics if verbose mode is enabled
  if (verbose) {
    printf("Total lines: %d\n", num_lines);
    printf("Files processed: %d\n", processed_files);
  }

  return 0;
}

// Process a single file in parallel using a separate thread
void *process_file(FILE *fp) {
  char line[1024];
  int lines = 0;

  // Iterate over the file and convert each line to lowercase
  while (fgets(line, sizeof(line), fp) != NULL) {
    for (int i = 0; i < strlen(line); ++i) {
      line[i] = tolower(line[i]);
    }

    // Print the converted line to the output file
    fputs(line, stdout);

    // Update the total and processed lines count
    total_lines++;
    lines++;
  }

  // Close the file stream and return the number of lines processed
  fclose(fp);
  return (void *)lines;
}

// Recursively process a directory and its subdirectories, creating threads for each subdirectory
void process_directory(DIR *dirp) {
  struct dirent *entry = NULL;
  while ((entry = readdir(dirp)) != NULL) {
    // Check if the entry is a file or a directory
    if (entry->d_type == DT_REG) {
      // Validate the file name against the regex pattern, if specified
      if (regex_pattern != NULL && !matches_file(entry->d_name, regex_pattern)) {
        continue;
      }

      // Open the file for reading and process it in a separate thread
      FILE *fp = fopen(entry->d_name, "r");
      if (fp == NULL) {
        log_error("Failed to open input file");
        continue;
      }
      pthread_t thread;
      int rc = pthread_create(&thread, NULL, process_file, fp);
      if (rc != 0) {
        log_error("Failed to create processing thread");
        fclose(fp);
        continue;
      }
      processed_files++;
    } else if (entry->d_type == DT_DIR) {
      // Recursively process the subdirectory, creating a new thread for it
      char path[PATH_MAX];
      snprintf(path, PATH_MAX, "%s/%s", input_dir, entry->d_name);
      DIR *subdirp = opendir(path);
      if (subdirp == NULL) {
        log_error("Failed to open subdirectory");
        continue;
      }
      pthread_t thread;
      int rc = pthread_create(&thread, NULL, process_directory, subdirp);
      if (rc != 0) {
        log_error("Failed to create processing thread");
        closedir(subdirp);
        continue;
      }
    }
  }
}

// Print usage information and exit
void print_usage() {
  printf("Usage: prog [options]\n");
  printf("Options:\n");
  printf("  -i <input_dir>  Input directory containing text files to be processed\n");
  printf("  -o <output_file> Output file for results (default: results.txt)\n");
  printf("  -c <regex_pattern> Regex pattern for filtering files within the input directory\n");
  printf("  -s <num_threads> Number of threads to use for processing files in parallel (default: 10)\n");
  printf("  -p <progress_interval> Interval for reporting progress (default: 10 files)\n");
  printf("  -v Verbose mode for printing detailed statistics\n");
}

// Log an error message and exit
void log_error(char *msg) {
  fprintf(stderr, "Error: %s\n", msg);
  exit(1);
}

// Helper function to validate a file name against the regex pattern
bool matches_file(const char *filename, const char *pattern) {
  return regexec(&regex_pattern, filename, (size_t)0, NULL, 0) == 0;
}
