typedef struct {
    char *addr;
    int state;
} channel;

// Define the pool of channels
#define CHANNEL_POOL_SIZE 1024
channel channel_pool[CHANNEL_POOL_SIZE];

// Initialize the pool of channels
void init_channels() {
    int i;
    for (i = 0; i < CHANNEL_POOL_SIZE; i++) {
        channel_pool[i].addr = NULL;
        channel_pool[i].state = -1;
    }
}

// Allocate a new channel from the pool
channel allocate_channel(char *addr) {
    int i;
    for (i = 0; i < CHANNEL_POOL_SIZE; i++) {
        if (channel_pool[i].state == -1) {
            channel_pool[i].addr = addr;
            channel_pool[i].state = 0;
            return channel_pool[i];
        }
    }
    // No available channels, return NULL
    return NULL;
}

// Deallocate a channel in the pool
