    // Set default quality setting for new pipelines
    PipelineData *pipeline_data = (PipelineData *)pipeline->data;
    if (!pipeline_data || !pipeline_data->running) {
        return; // Error: failed to set defaults
    }

    // Set default quality setting for new pipelines
    pipeline_data->quality = quality;
}

// Function to handle error handling for unexpected failures or errors
void handle_error(Pipeline *pipeline) {
    // Handle unexpected failure or error by restarting the pipeline and updating monitoring system
    PipelineData *pipeline_data = (PipelineData *)pipeline->data;
    if (!pipeline_data || !pipeline_data->running) {
        return; // Error: failed to handle error
    }

    // Handle unexpected failure or error by restarting the pipeline and updating monitoring system
