string congestion_management(const vector<long>& timestamps, const vector<int>& connection_ids, const vector<packet>& packets) {
    // Calculate the bandwidth utilization and latency metrics based on real-time network data
    long total_bandwidth = 0;
    long total_latency = 0;
    for (int i = 0; i < timestamps.size(); ++i) {
        total_bandwidth += packets[i].value;
        total_latency += timestamps[i] - connection_ids[i];
    }
    double bandwidth_utilization = (double)total_bandwidth / timestamps.size();
    double latency = total_latency / timestamps.size();

    // Select the congestion management strategy based on the network metrics
    string strategy;
    if (bandwidth_utilization > 0.75 && latency < 100) {
        strategy = "A";
    } else if (bandwidth_utilization > 0.90 && latency < 200) {
        strategy = "B";
    } else {
        strategy = "C";
    }

    // Adjust the variable cooldown period based on simulated network performance metrics
    long cooldown_period = (long)(1000 * sqrt(bandwidth_utilization));
    if (cooldown_period < 50) {
        cooldown_period = 50;
    } else if (cooldown_period > 2000) {
        cooldown_period = 2000;
    }

