    cout << "Congestion Management Strategy: " << strategy << endl;
    cout << "Associated Latency: " << latency << endl;

    // Log detailed metrics for post-mortem analysis
    log_metrics(timestamps, connection_ids, packets, bandwidth_utilization, latency);

    return strategy;
}

void log_metrics(const vector<long>& timestamps, const vector<int>& connection_ids, const vector<packet>& packets, double bandwidth_utilization, double latency) {
