// Custom alignment requirements for different types based on hardware-specific guidelines
const uint64_t ALIGNMENT_BYTES = 64; // align to cache line size of 64 bytes
const uint64_t ALIGNMENT_OFFSET = ALIGNMENT_BYTES - 1;

// Structure for storing offset and key values
struct Record {
    int32_t offset;
    int32_t key;
};

// Global variables to track memory usage
uint64_t total_memory = 0;
