void initialize_memory(int n, int m, int min_value, int max_value) {
    // Allocate memory for offset and key arrays
    uint64_t offset_size = n * sizeof(int32_t);
    uint64_t key_size = m * sizeof(Record);
    void* offset_array = mmap(NULL, offset_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    void* key_array = mmap(NULL, key_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    // Initialize offset and key arrays with random values
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        int32_t* offset_ptr = (int32_t*)offset_array + i;
        *offset_ptr = rand() % max_value;
    }
    for (int j = 0; j < m; j++) {
        Record* key_ptr = (Record*)key_array + j;
        key_ptr->offset = rand() % max_value;
        key_ptr->key = rand() % max_value;
    }

    // Ensure proper alignment for optimal cache performance
    uint64_t offset_alignment = ALIGNMENT_BYTES - ((uint64_t)offset_array & ALIGNMENT_OFFSET);
    void* aligned_offset_array = mmap(NULL, offset_size + offset_alignment, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    memcpy(aligned_offset_array, offset_array, offset_size);
    munmap(offset_array, offset_size);
    void* aligned_key_array = mmap(NULL, key_size + ALIGNMENT_OFFSET, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    memcpy(aligned_key_array, key_array, key_size);
    munmap(key_array, key_size);

    // Monitor and limit maximum total memory usage to `memory_limit` bytes
    uint64_t memory_limit = 1024 * 1024 * 1024; // 1 GB
    pthread_mutex_lock(&memory_lock);
    total_memory += offset_size + key_size + ALIGNMENT_OFFSET;
    if (total_memory > memory_limit) {
        printf("Memory usage exceeded limit! Total memory: %lu\n", total_memory);
        pthread_mutex_unlock(&memory_lock);
        return;
    }
    pthread_mutex_unlock(&memory_lock);

    // Integrate with external logging library for error reporting and memory deallocation
    printf("Memory allocated successfully! Total memory: %lu\n", total_memory);
}
