    if (argc < 2) {
        print_usage();
        return 1;
    }

    // Setup logging
    setup_logging(argv[0]);

    // Setup file management
    setup_filesystem(argv[0]);

    // Process command line arguments
    for (int i = 1; i < argc; i++) {
        if (!strcmp("-i", argv[i])) {
            input.path = argv[++i];
        } else if (!strcmp("--help", argv[i])) {
            print_usage();
            return 0;
        } else if (!strcmp("-cs", argv[i])) {
            set_timeout(100); // Set timeout for each file to 100ms
        } else if (!strcmp("-o", argv[i])) {
            output.path = argv[++i];
        } else if (!strcmp("-p", argv[i])) {
            log.level = LOG_NOTICE; // Set progress reporting level to notice
        } else {
            printf("Invalid command line argument: %s\n", argv[i]);
            return 1;
        }
    }

    if (input.path == NULL) {
        printf("No input directory specified.\n");
        print_usage();
        return 1;
    }

    // Scan input directory for files and process them concurrently
    process_directory(input.path, &log);

    // Close output file if opened
    if (output.fd != -1) {
        close(output.fd);
    }

    return 0;
}

// Function to process a single file
void process_file(struct file *f) {
    int fd = open(f->path, O_RDONLY | O_NONBLOCK); // Open file in non-blocking mode
    if (fd == -1) {
        perror("Failed to open file");
        return;
    }

    char *buf = malloc(BUFSIZ); // Allocate buffer for reading file
    int nread;
    while ((nread = read(fd, buf, BUFSIZ)) > 0) { // Read file in chunks
        for (int i = 0; i < nread; i++) { // Convert each line to lowercase
            if (buf[i] == '\n') {
                printf("%s\n", buf);
            } else {
                buf[i] = tolower(buf[i]);
            }
        }
    }

    free(buf); // Free buffer memory
    close(fd); // Close file descriptor
}

// Function to process a directory recursively and spawn threads for each file
void process_directory(char *path, struct logger *log) {
    DIR *dir = opendir(path);
    if (dir == NULL) {
        perror("Failed to open directory");
        return;
    }

    // Scan directory for files and spawn threads for each file
    while ((struct dirent *)dir->next != NULL) {
        struct dirent *entry = readdir(dir);
        if (!strcmp(".", entry->d_name) || !strcmp("..", entry->d_name)) {
            continue;
        }

        char fullpath[PATH_MAX];
        snprintf(fullpath, PATH_MAX, "%s/%s", path, entry->d_name);

        struct stat st;
        if (stat(fullpath, &st) == -1) {
            perror("Failed to stat file");
            return;
        }

        if (S_ISDIR(st.st_mode)) { // If file is a directory, recurse
            process_directory(fullpath, log);
        } else {
            pthread_t thread;
            struct file *f = malloc(sizeof(struct file));
            f->path = fullpath;

            if (pthread_create(&thread, NULL, process_file, f) != 0) {
                perror("Failed to create thread");
                return;
            }
        }
    }

    closedir(dir); // Close directory stream
}

// Function to print usage instructions
void print_usage() {
    printf("Usage: %s -i <input_dir> [--help] [-cs] [-o <output_file>] [-p]\n", argv[0]);
    printf("\t-i <input_dir>: Specifies a directory containing multiple text files to be processed.\n");
    printf("\t\tThe program should automatically scan this directory for files with a .txt extension.\n");
    printf("\t--help: Prints comprehensive usage instructions.\n");
    printf("\t-cs: Outputs each line of the input files in lowercase.\n");
    printf("\t-o <output_file>: Specifies an output file where the results should be saved.\n");
    printf("\t\tIf not provided, the program should append the results to a file named results.txt.\n");
    printf("\t-p: Enables progress reporting every 100 files processed.\n");
}

// Function to set timeout for each file
void set_timeout(int milliseconds) {
    timeout = milliseconds;
}

// Function to setup logging
void setup_logging(char *filename) {
    log.filename = filename;
    log.level = LOG_NOTICE; // Set progress reporting level to notice
}

// Function to setup file management
void setup_filesystem(char *filename) {
    input.path = filename;
    output.path = "results.txt";
}
