import java.net.URI;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Logger;

import org.java_websocket.WebSocket;
import org.java_websocket.client.WebSocketClient;
import org.java_websocket.drafts.Draft_17;
import org.java_websocket.exceptions.InvalidFrameException;
import org.java_websocket.framing.CloseFrame;
import org.java_websocket.handshake.ClientHandshake;
import org.java_websocket.protocols.WebSocketProtocol;
import org.java_websocket.util.SocketUtil;

public class WebSocketConnection {
    private static final Logger LOG = Logger.getLogger(WebSocketConnection.class.getName());

    private ExecutorService executorService;
    private WebSocketClient webSocketClient;
    private int maxRetries;
    private long retryInterval;
    private URI uri;

    public WebSocketConnection(URI uri, int maxRetries, long retryInterval) {
        this.uri = uri;
        this.maxRetries = maxRetries;
        this.retryInterval = retryInterval;
        executorService = Executors.newCachedThreadPool();
    }

    public WebSocket connect() throws Exception {
        WebSocketClient client = new WebSocketClient(uri, new Draft_17(), null, 0) {
            @Override
            public void onOpen(WebSocket webSocket) {
                LOG.info("Connected to " + uri);
            }

            @Override
            public void onClose(WebSocket webSocket, int code, String reason, boolean remote) {
                LOG.warning("Disconnected from " + uri);
            }

            @Override
            public void onMessage(WebSocket webSocket, String message) {
                LOG.info("Received message: " + message);
            }

            @Override
            public void onError(WebSocket webSocket, Exception exception) {
                LOG.severe("Error connecting to " + uri + ": " + exception);
            }
        };

        CompletableFuture<Void> connectFuture = new CompletableFuture<>();
        int retryCount = 0;
        while (true) {
            try {
                client.connect();
                connectFuture.complete(null);
                break;
            } catch (InvalidFrameException e) {
                LOG.warning("Invalid frame received, retrying connection...");
                if (retryCount >= maxRetries) {
                    LOG.severe("Maximum retries reached, giving up on connecting to " + uri);
                    connectFuture.completeExceptionally(e);
                    break;
                }
                retryCount++;
            } catch (Exception e) {
                LOG.warning("Error connecting to " + uri + ": " + e);
                if (retryCount >= maxRetries) {
                    LOG.severe("Maximum retries reached, giving up on connecting to " + uri);
                    connectFuture.completeExceptionally(e);
                    break;
                }
                retryCount++;
            }
            executorService.schedule(() -> {
                try {
                    LOG.info("Retrying connection...");
                    client.reconnectBlocking();
                } catch (Exception e) {
                    LOG.warning("Error reconnecting to " + uri + ": " + e);
                }
            }, retryInterval, TimeUnit.MILLISECONDS);
        }
        webSocketClient = client;
        return connectFuture.get();
    }

    public void disconnect() {
        if (webSocketClient != null) {
            try {
                webSocketClient.close(CloseFrame.GOING_AWAY, "Disconnected");
            } catch (Exception e) {
                LOG.warning("Error closing connection: " + e);
            } finally {
                executorService.shutdown();
                webSocketClient = null;
            }
        }
    }

    public void send(String message) {
        if (webSocketClient != null) {
            try {
                webSocketClient.send(message);
            } catch (Exception e) {
                LOG.warning("Error sending message: " + e);
            }
        } else {
            LOG.info("Cannot send message, connection not initialized");
        }
    }
}
