    // write PDF data to output file
    size_t bytesWritten = fwrite(pdfData, 1, pdfSize, outputFile);
    if (bytesWritten != pdfSize) {
        free(pdfData);
        return -3;
    }

    // free dynamically allocated memory for PDF conversion
    free(pdfData);

    return 0;
}

size_t getFileSize(const char* filePath) {
    struct stat st;
    if (stat(filePath, &st) != 0) {
        return -1;
    }
    return st.st_size;
}

int readFileIntoMemory(const char* filePath, void* data, size_t dataLength) {
    // validate parameters
    if (filePath == NULL || data == NULL || dataLength <= 0) {
        return -1;
    }

    // open input file for reading
    FILE* inputFile = fopen(filePath, "rb");
    if (inputFile == NULL) {
        return -2;
    }

    // read data from input file into memory
    size_t bytesRead = fread(data, 1, dataLength, inputFile);
    if (bytesRead != dataLength) {
        fclose(inputFile);
        return -3;
    }

    // close input file and return success
    fclose(inputFile);
    return 0;
}

int writeObjectToFile(FILE* outputFile, void* obj) {
    // validate parameters
    if (outputFile == NULL || obj == NULL) {
        return -1;
    }

    // serialize object using custom serialization framework
    size_t dataLength = getSerializedSize(obj);
    char* data = malloc(dataLength);
    if (data == NULL) {
        return -2;
    }
    int result = writeObjectToMemory(obj, data, dataLength);
    if (result != 0) {
        free(data);
        return result;
    }

    // write serialized object to output file
    size_t bytesWritten = fwrite(data, 1, dataLength, outputFile);
    if (bytesWritten != dataLength) {
        free(data);
        return -3;
    }

    // free dynamically allocated memory for serialized object
    free(data);

    return 0;
}
