// NetworkStatisticsManager.h
#pragma once

#include <vector>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <memory>

class NetworkInterface;

// Custom structure to represent network statistics
struct NetworkStatistics {
    uint64_t packetLoss;
    uint64_t latency;
    uint64_t throughput;
    uint64_t bandwidth;
};

class NetworkStatisticsManager {
public:
    explicit NetworkStatisticsManager(size_t maxNumInterfaces);
    ~NetworkStatisticsManager();

    void addInterface(std::shared_ptr<NetworkInterface> interface);
    void removeInterface(std::shared_ptr<NetworkInterface> interface);
    void updateMetrics();

    // Export functions
    void exportCsv();
    void exportJson();

private:
    size_t _maxNumInterfaces;
    std::vector<std::shared_ptr<NetworkInterface>> _interfaces;
    std::mutex _interfaceMutex;
    std::condition_variable _cv;
    bool _terminate = false;
};
```

```
// NetworkStatisticsManager.cpp
#include "NetworkStatisticsManager.h"
#include <fstream>
#include <nlohmann/json.hpp>

namespace {
    constexpr size_t DEFAULT_MAX_NUM_INTERFACES = 100;
}

NetworkStatisticsManager::NetworkStatisticsManager(size_t maxNumInterfaces) : _maxNumInterfaces(maxNumInterfaces > 0 ? maxNumInterfaces : DEFAULT_MAX_NUM_INTERFACES) {
    _interfaces.reserve(_maxNumInterfaces);
}

NetworkStatisticsManager::~NetworkStatisticsManager() {
    _terminate = true;
    _cv.notify_all();
}

void NetworkStatisticsManager::addInterface(std::shared_ptr<NetworkInterface> interface) {
    std::lock_guard<std::mutex> lock(_interfaceMutex);
    if (_interfaces.size() < _maxNumInterfaces) {
        _interfaces.push_back(interface);
    } else {
        throw std::runtime_error("Maximum number of interfaces reached.");
    }
}

void NetworkStatisticsManager::removeInterface(std::shared_ptr<NetworkInterface> interface) {
    std::lock_guard<std::mutex> lock(_interfaceMutex);
    auto it = std::find(_interfaces.begin(), _interfaces.end(), interface);
    if (it != _interfaces.end()) {
        _interfaces.erase(it);
    } else {
        throw std::runtime_error("Interface not found.");
    }
}

void NetworkStatisticsManager::updateMetrics() {
    std::vector<std::shared_ptr<NetworkInterface>> interfaces;
    {
        std::lock_guard<std::mutex> lock(_interfaceMutex);
        interfaces = _interfaces;
    }
    for (auto& interface : interfaces) {
        interface->updateMetrics();
    }
}

void NetworkStatisticsManager::exportCsv() {
    std::ofstream outfile("network_stats.csv");
    // Header row
    outfile << "Interface,Packet Loss (%),Latency (ms),Throughput (Mbps),Bandwidth (Mbps)\n";

    // Data rows
    for (auto& interface : _interfaces) {
        NetworkStatistics stats = interface->getMetrics();
        outfile << interface->getName() << ","
                << stats.packetLoss << ","
                << stats.latency << ","
                << stats.throughput << ","
                << stats.bandwidth << "\n";
    }
}

void NetworkStatisticsManager::exportJson() {
    nlohmann::json json;
    for (auto& interface : _interfaces) {
        NetworkStatistics stats = interface->getMetrics();
        json["Interfaces"].push_back({
            {"Name", interface->getName()},
            {"Packet Loss (%)", stats.packetLoss},
            {"Latency (ms)", stats.latency},
            {"Throughput (Mbps)", stats.throughput},
            {"Bandwidth (Mbps)", stats.bandwidth}
        });
    }
    std::ofstream outfile("network_stats.json");
    outfile << json;
}
