// NetworkStatisticsManager.cpp (distributed processing)
#include "NetworkStatisticsManager.h"
#include <future>

void NetworkStatisticsManager::updateMetrics() {
    std::vector<std::shared_ptr<NetworkInterface>> interfaces;
    {
        std::lock_guard<std::mutex> lock(_interfaceMutex);
        interfaces = _interfaces;
    }
    std::vector<std::future<void>> futures;
    for (auto& interface : interfaces) {
        futures.emplace_back(std::async([this, &interface]() {
            interface->updateMetrics();
        }));
    }
    // Wait for all threads to finish
    std::for_each(futures.begin(), futures.end(), [](auto& future) {
        future.wait();
    });
}
