// Structure to represent a 2D point
struct Point {
    int x, y;
};

// Structure to represent an event with a double value and a string
struct Event {
    double value;
    char *str;
    struct Point p;
};

// Function to dynamically allocate memory for and initialize a collection of events
void init_events(struct Event **events, int num_events, double min_value, double max_value, char *string_template) {
    // Allocate memory for the event structures
    *events = (struct Event *)malloc(sizeof(struct Event) * num_events);
    if (*events == NULL) {
        fprintf(stderr, "Failed to allocate memory for events\n");
        return;
    }

    // Initialize the event values within the specified ranges
    for (int i = 0; i < num_events; ++i) {
        (*events)[i].value = min_value + ((double)(rand() % RAND_MAX) / (double)RAND_MAX) * (max_value - min_value);
        // Initialize the string using the provided template and a unique index
        int len = strlen(string_template) + 1;
        char *str = malloc(len);
        snprintf(str, len, string_template, i);
        (*events)[i].str = str;
        // Initialize the point coordinates using random values between 0 and 100
        (*events)[i].p.x = rand() % 100;
        (*events)[i].p.y = rand() % 100;
    }
}

// Function to free allocated memory for events
void free_events(struct Event **events, int num_events) {
    if (events == NULL || *events == NULL) {
        return;
    }
    // Free the event structures and their associated memory
    for (int i = 0; i < num_events; ++i) {
        free((*events)[i].str);
    }
    free(*events);
}
