function generateSecureStringAndConfigureEncryption($outputLength, $charSet, $password, $encryptionAlgorithms) {
  // Generate random string of specified length using given character set
  $randomString = substr(str_shuffle($charSet), 0, $outputLength);

  // Hash provided password with default secure hashing mechanism
  $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

  // Evaluate availability and compatibility of each encryption algorithm in array
  foreach ($encryptionAlgorithms as $algorithm) {
    if (in_array($algorithm, hash_algos())) {
      // Initialize encryption algorithm with necessary parameters for secure operation
      $configuration = [
        'name' => $algorithm,
        'init' => function() use ($algorithm, $hashedPassword) {
          return hash_init($algorithm, HASH_HMAC, $hashedPassword);
        },
        'params' => null
      ];
    } elseif (extension_loaded('mcrypt') && in_array($algorithm . '_ecb', mcrypt_list_algorithms())) {
      // Initialize encryption algorithm with necessary parameters for secure operation
      $configuration = [
        'name' => $algorithm,
        'init' => function() use ($algorithm, $hashedPassword) {
          return mcrypt_module_open($algorithm . '_ecb', '', 'cbc', '');
        },
        'params' => null
      ];
    } else {
      // Ignore unavailable or incompatible encryption algorithms
      continue;
    }
  }

  // Return random string and hashed password alongside configuration object
  return [$randomString, $hashedPassword, $configuration];
}
