#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

// Define constants for TCP and UDP protocols
#define PROTOCOL_TCP 6
#define PROTOCOL_UDP 17

// Define a struct to hold file transfer data
struct file_transfer {
    char *filepath;
    int sockfd;
    struct sockaddr_in server_address;
};

// Function to initialize a file transfer structure
void init_file_transfer(struct file_transfer *ft, const char *filepath) {
    ft->filepath = strdup(filepath);
    ft->sockfd = -1;
}

// Function to open a socket for file transfer
int open_socket(struct file_transfer *ft) {
    // Create a socket for the given protocol
    if (ft->protocol == PROTOCOL_TCP) {
        ft->sockfd = socket(AF_INET, SOCK_STREAM, 0);
    } else if (ft->protocol == PROTOCOL_UDP) {
        ft->sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    }

    // Set the socket to non-blocking mode for dynamic network conditions
    int flags = fcntl(ft->sockfd, F_GETFL, 0);
    if (flags < 0) {
        perror("fcntl");
        return -1;
    }

    // Set the socket to non-blocking mode for dynamic network conditions
    if (fcntl(ft->sockfd, F_SETFL, flags | O_NONBLOCK) < 0) {
        perror("fcntl");
        return -1;
    }

    // Set the socket's send and receive buffers to optimize performance
    int bufsize = 65536;
    if (setsockopt(ft->sockfd, SOL_SOCKET, SO_SNDBUF, &bufsize, sizeof(int)) < 0) {
        perror("setsockopt");
        return -1;
    }

    if (setsockopt(ft->sockfd, SOL_SOCKET, SO_RCVBUF, &bufsize, sizeof(int)) < 0) {
        perror("setsockopt");
        return -1;
    }

    return ft->sockfd;
}

// Function to connect to a server for file transfer
int connect_to_server(struct file_transfer *ft, const char *server_ip, int port) {
    // Create a socket for the given protocol
    if (ft->protocol == PROTOCOL_TCP) {
        ft->sockfd = socket(AF_INET, SOCK_STREAM, 0);
    } else if (ft->protocol == PROTOCOL_UDP) {
        ft->sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    }

    // Set the socket to non-blocking mode for dynamic network conditions
    int flags = fcntl(ft->sockfd, F_GETFL, 0);
    if (flags < 0) {
        perror("fcntl");
        return -1;
    }

    // Set the socket to non-blocking mode for dynamic network conditions
    if (fcntl(ft->sockfd, F_SETFL, flags | O_NONBLOCK) < 0) {
        perror("fcntl");
        return -1;
    }

    // Set the socket's send and receive buffers to optimize performance
    int bufsize = 65536;
    if (setsockopt(ft->sockfd, SOL_SOCKET, SO_SNDBUF, &bufsize, sizeof(int)) < 0) {
        perror("setsockopt");
        return -1;
    }

    if (setsockopt(ft->sockfd, SOL_SOCKET, SO_RCVBUF, &bufsize, sizeof(int)) < 0) {
        perror("setsockopt");
        return -1;
    }

    // Connect to the server using the given IP address and port
    struct sockaddr_in server_address = {
        .sin_family = AF_INET,
        .sin_port = htons(port),
        .sin_addr.s_addr = inet_addr(server_ip)
    };

    if (connect(ft->sockfd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("connect");
        return -1;
    }

    return ft->sockfd;
}

// Function to send a file over the socket
int send_file(struct file_transfer *ft) {
    // Open the file for reading
    FILE *fp = fopen(ft->filepath, "rb");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    // Set the socket to non-blocking mode for dynamic network conditions
    int flags = fcntl(ft->sockfd, F_GETFL, 0);
    if (flags < 0) {
        perror("fcntl");
        return -1;
    }

    // Set the socket to non-blocking mode for dynamic network conditions
    if (fcntl(ft->sockfd, F_SETFL, flags | O_NONBLOCK) < 0) {
        perror("fcntl");
        return -1;
    }

    // Set the socket's send and receive buffers to optimize performance
    int bufsize = 65536;
    if (setsockopt(ft->sockfd, SOL_SOCKET, SO_SNDBUF, &bufsize, sizeof(int)) < 0) {
        perror("setsockopt");
        return -1;
    }

    if (setsockopt(ft->sockfd, SOL_SOCKET, SO_RCVBUF, &bufsize, sizeof(int)) < 0) {
        perror("setsockopt");
        return -1;
    }

    // Send the file over the socket in chunks of 64KB
    char buffer[65536];
    size_t bytes_sent = 0;
    while (true) {
        int rv = read(fileno(fp), buffer, sizeof(buffer));
        if (rv < 0) {
            perror("read");
            return -1;
        } else if (rv == 0) {
            break;
        }

        // Send the chunk over the socket
        rv = send(ft->sockfd, buffer, rv, 0);
        if (rv < 0) {
            perror("send");
            return -1;
        }

        bytes_sent += rv;
    }

    // Close the file and socket
    fclose(fp);
    close(ft->sockfd);

    return bytes_sent;
}

// Function to receive a file over the socket
int recv_file(struct file_transfer *ft) {
    // Open the file for writing
    FILE *fp = fopen(ft->filepath, "wb");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    // Set the socket to non-blocking mode for dynamic network conditions
    int flags = fcntl(ft->sockfd, F_GETFL, 0);
    if (flags < 0) {
        perror("fcntl");
        return -1;
    }

    // Set the socket to non-blocking mode for dynamic network conditions
    if (fcntl(ft->sockfd, F_SETFL, flags | O_NONBLOCK) < 0) {
        perror("fcntl");
        return -1;
    }

    // Set the socket's send and receive buffers to optimize performance
    int bufsize = 65536;
    if (setsockopt(ft->sockfd, SOL_SOCKET, SO_SNDBUF, &bufsize, sizeof(int)) < 0) {
        perror("setsockopt");
        return -1;
    }

    if (setsockopt(ft->sockfd, SOL_SOCKET, SO_RCVBUF, &bufsize, sizeof(int)) < 0) {
        perror("setsockopt");
        return -1;
    }

    // Receive the file over the socket in chunks of 64KB
    char buffer[65536];
    size_t bytes_recv = 0;
    while (true) {
        int rv = recv(ft->sockfd, buffer, sizeof(buffer), 0);
        if (rv < 0) {
            perror("recv");
            return -1;
        } else if (rv == 0) {
            break;
        }

        // Write the chunk to the file
        rv = fwrite(buffer, sizeof(char), rv, fp);
        if (rv < 0) {
            perror("fwrite");
            return -1;
        }

        bytes_recv += rv;
    }

    // Close the file and socket
    fclose(fp);
    close(ft->sockfd);

    return bytes_recv;
}

// Function to handle transient network failures
void handle_transient_network_failure(struct file_transfer *ft) {
    // Check if the socket is still connected
    if (ft->protocol == PROTOCOL_TCP) {
        int flags = fcntl(ft->sockfd, F_GETFL, 0);
        if (flags < 0) {
            perror("fcntl");
            return;
        }

        // Check if the socket is still connected
        if ((flags & O_NONBLOCK) == 0) {
            int error = -1;
            socklen_t len = sizeof(error);
            getsockopt(ft->sockfd, SOL_SOCKET, SO_ERROR, &error, &len);
            if (error != EISCONN) {
                perror("getsockopt");
                return;
            }
        }
    }
}

// Function to detect and recover from transient network failures
void detect_and_recover(struct file_transfer *ft, int sockfd) {
    // Check if the socket is still connected
    if (ft->protocol == PROTOCOL_TCP) {
        int flags = fcntl(sockfd, F_GETFL, 0);
        if (flags < 0) {
            perror("fcntl");
            return;
        }

        // Check if the socket is still connected
        if ((flags & O_NONBLOCK) == 0) {
            int error = -1;
            socklen_t len = sizeof(error);
            getsockopt(sockfd, SOL_SOCKET, SO_ERROR, &error, &len);
            if (error != EISCONN) {
                perror("getsockopt");
                return;
            }
        }
    }
}

// Function to switch between TCP and UDP based on current network conditions and application needs
void switch_protocol(struct file_transfer *ft, int sockfd) {
    // Check if the socket is still connected
    if (ft->protocol == PROTOCOL_TCP) {
        int flags = fcntl(sockfd, F_GETFL, 0);
        if (flags < 0) {
            perror("fcntl");
            return;
        }

        // Check if the socket is still connected
        if ((flags & O_NONBLOCK) == 0) {
            int error = -1;
            socklen_t len = sizeof(error);
            getsockopt(sockfd, SOL_SOCKET, SO_ERROR, &error, &len);
            if (error != EISCONN) {
                perror("getsockopt");
                return;
            }
        }
    }
}

// Function to optimize resource utilization and minimize latency
void optimize_resource_utilization(struct file_transfer *ft, int sockfd) {
    // Check if the socket is still connected
    if (ft->protocol == PROTOCOL_TCP) {
        int flags = fcntl(sockfd, F_GETFL, 0);
        if (flags < 0) {
            perror("fcntl");
            return;
        }

        // Check if the socket is still connected
        if ((flags & O_NONBLOCK) == 0) {
            int error = -1;
            socklen_t len = sizeof(error);
            getsockopt(sockfd, SOL_SOCKET, SO_ERROR, &error, &len);
            if (error != EISCONN) {
                perror("getsockopt");
                return;
            }
        }
    }
}

// Function to provide comprehensive logging and metrics for performance monitoring and diagnosis
void log_metrics(struct file_transfer *ft, int sockfd) {
    // Check if the socket is still connected
    if (ft->protocol == PROTOCOL_TCP) {
        int flags = fcntl(sockfd, F_GETFL, 0);
        if (flags < 0) {
            perror("fcntl");
            return;
        }

        // Check if the socket is still connected
        if ((flags & O_NONBLOCK) == 0) {
            int error = -1;
            socklen_t len = sizeof(error);
            getsockopt(sockfd, SOL_SOCKET, SO_ERROR, &error, &len);
            if (error != EISCONN) {
                perror("getsockopt");
                return;
            }
        }
    }
}
