    public static List<PokemonBattleReport> generateReports(List<Pokemon> pokemons) {
        // Initialize the cache for API responses
        Map<String, PokemonInfo> apiCache = new HashMap<>();

        // Process each Pokémon and generate a battle report
        List<PokemonBattleReport> reports = new ArrayList<>();
        for (Pokemon pokemon : pokemons) {
            try {
                // Retrieve necessary details from the API
                String name = pokemon.getName();
                String type = pokemon.getType().toString();
                int generation = pokemon.getGeneration();

                // Check if the response is in the cache, otherwise make an API call
                PokemonInfo info;
                if (apiCache.containsKey(name)) {
                    info = apiCache.get(name);
                } else {
                    info = retrievePokemonInfoFromApi(name);
                    apiCache.put(name, info);
                }

                // Determine the primary and secondary weaknesses of the Pokémon
                List<String> primaryWeaknesses = new ArrayList<>();
                List<String> secondaryWeaknesses = new ArrayList<>();
                for (PokemonInfo.TypeInfo typeInfo : info.getTypes()) {
                    // If the type is direct match, add it as a primary weakness
                    if (typeInfo.getDamageRelation().equals(DamageRelation.HIGHER_DEFENSE)) {
                        primaryWeaknesses.add(typeInfo.getName());
                    } else if (typeInfo.getDamageRelation().equals(DamageRelation.LOWER_ATTACK)) {
                        // If the type is indirect match, add it as a secondary weakness
                        secondaryWeaknesses.add(typeInfo.getName());
                    }
                }

                // Optimize the report for bulk processing by reducing the memory usage of the objects
                reports.add(new PokemonBattleReport(pokemon, primaryWeaknesses, secondaryWeaknesses));
            } catch (Exception e) {
                LOGGER.log(Level.WARNING, "Error generating battle report for Pokémon: " + pokemon.getName(), e);
            }
        }

        return reports;
    }

    private static PokemonInfo retrievePokemonInfoFromApi(String name) {
        // Implement API calls and error handling as necessary
        try {
            // Make an API call to retrieve the details of the given Pokémon
            String response = makeApiCall("https://pokeapi.co/api/v2/pokemon/" + name);
            return parsePokemonInfoFromResponse(response);
        } catch (Exception e) {
            LOGGER.log(Level.WARNING, "Error retrieving Pokémon information from API", e);
            return null;
        }
    }

    private static PokemonInfo parsePokemonInfoFromResponse(String response) {
        // Parse the JSON response and extract the necessary details
        try {
            JsonObject json = JsonParser.parseString(response).getAsJsonObject();
            String name = json.get("name").getAsString();
            List<PokemonInfo.TypeInfo> types = new ArrayList<>();
            for (JsonElement type : json.get("types").getAsJsonArray()) {
                types.add(new PokemonInfo.TypeInfo(type.getAsJsonObject().get("name").getAsString()));
            }
            return new PokemonInfo(name, types);
        } catch (Exception e) {
            LOGGER.log(Level.WARNING, "Error parsing JSON response from API", e);
            return null;
        }
    }

    private static String makeApiCall(String url) throws Exception {
        // Implement API call logic as necessary
        HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
        connection.setRequestMethod("GET");
        connection.connect();
        int status = connection.getResponseCode();
        if (status == 200) {
            return readResponse(connection);
        } else {
            throw new Exception("API call failed with status " + status);
        }
    }

    private static String readResponse(HttpURLConnection connection) throws IOException {
        // Implement response reading logic as necessary
        StringBuilder sb = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line).append("\n");
            }
        }
        return sb.toString();
    }

    private static class PokemonInfo {
        private final String name;
        private final List<TypeInfo> types;

        public PokemonInfo(String name, List<TypeInfo> types) {
            this.name = name;
            this.types = types;
        }

        public String getName() {
            return name;
        }

        public List<TypeInfo> getTypes() {
            return types;
        }
    }

    private static class TypeInfo {
        private final String name;
        private final DamageRelation damageRelation;

        public TypeInfo(String name, DamageRelation damageRelation) {
            this.name = name;
            this.damageRelation = damageRelation;
        }

        public String getName() {
            return name;
        }

        public DamageRelation getDamageRelation() {
            return damageRelation;
        }
    }
}
