Here is an example implementation of a C function that manages multiple semaphores with specified initial values, supporting dynamic creation, deletion, and operation under various conditions:
```c
#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <errno.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>

// Define the maximum number of semaphores that can be managed
#define MAX_SEMAPHORES 10

// Struct to hold information about a single semaphore
typedef struct {
    int id;                      // Unique identifier for the semaphore
    char* name;                  // Name of the semaphore (for debugging purposes)
    int initial_value;           // Initial value for the semaphore
    sem_t* semaphore;            // Pointer to the semaphore structure
} semaphore_info_t;

// Array to hold information about all managed semaphores
semaphore_info_t semaphores[MAX_SEMAPHORES];

// Function to create a new semaphore
int create_semaphore(const char* name, int initial_value) {
    // Check if the maximum number of semaphores has been reached
    if (num_semaphores >= MAX_SEMAPHORES) {
        printf("Error: Maximum number of semaphores reached\n");
        return -1;
    }

    // Create a new semaphore structure and initialize it to the given value
    sem_t* semaphore = (sem_t*) malloc(sizeof(sem_t));
    if (semaphore == NULL) {
        printf("Error: Could not allocate memory for semaphore\n");
        return -1;
    }
    if (sem_init(semaphore, 0, initial_value) < 0) {
        printf("Error: Could not initialize semaphore\n");
        free(semaphore);
        return -1;
    }

    // Add the new semaphore to the list of managed semaphores
    semaphores[num_semaphores].id = num_semaphores + 1;
    semaphores[num_semaphores].name = strdup(name);
    semaphores[num_semaphores].initial_value = initial_value;
    semaphores[num_semaphores].semaphore = semaphore;
    num_semaphores++;

    return 0;
}

// Function to delete a semaphore
int delete_semaphore(const char* name) {
    // Find the index of the semaphore with the given name in the list of managed semaphores
    int i = find_semaphore_index(name);
    if (i < 0) {
        printf("Error: Semaphore not found\n");
        return -1;
    }

    // Destroy the semaphore and free its memory
    sem_destroy(semaphores[i].semaphore);
    free(semaphores[i].semaphore);

    // Remove the deleted semaphore from the list of managed semaphores
    for (int j = i; j < num_semaphores - 1; j++) {
        semaphores[j] = semaphores[j + 1];
    }
    num_semaphores--;

    return 0;
}

// Function to increment the value of a semaphore
int post(const char* name) {
    // Find the index of the semaphore with the given name in the list of managed semaphores
    int i = find_semaphore_index(name);
    if (i < 0) {
        printf("Error: Semaphore not found\n");
        return -1;
    }

    // Increment the value of the semaphore
    if (sem_post(semaphores[i].semaphore) < 0) {
        printf("Error: Could not increment semaphore value\n");
        return -1;
    }

    return 0;
}

// Function to decrement the value of a semaphore
int wait(const char* name) {
    // Find the index of the semaphore with the given name in the list of managed semaphores
    int i = find_semaphore_index(name);
    if (i < 0) {
        printf("Error: Semaphore not found\n");
        return -1;
    }

    // Decrement the value of the semaphore
    if (sem_wait(semaphores[i].semaphore) < 0) {
        printf("Error: Could not decrement semaphore value\n");
        return -1;
    }

    return 0;
}

// Function to find the index of a semaphore in the list of managed semaphores
int find_semaphore_index(const char* name) {
    for (int i = 0; i < num_semaphores; i++) {
        if (strcmp(name, semaphores[i].name) == 0) {
            return i;
        }
    }
    return -1;
}

// Function to clean up resources when no longer needed
void cleanup() {
    for (int i = 0; i < num_semaphores; i++) {
        sem_destroy(semaphores[i].semaphore);
        free(semaphores[i].name);
    }
}
```
