using System;
using System.IO;
using System.Text.Json;

namespace ConfigurationDemo
{
    class Program
    {
        private const string configFilePath = "config.json";

        static void Main(string[] args)
        {
            // Load configuration settings from JSON file
            var config = JsonSerializer.Deserialize<Configuration>(File.ReadAllText(configFilePath));

            // Validate configuration settings
            if (config == null || config.TileSize <= 0 || config.WorldWidth <= 0 || config.WorldHeight <= 0)
            {
                throw new Exception("Invalid configuration settings");
            }

            // Create game environment with configurable tile size, world dimensions, and camera speed
            var gameEnvironment = new GameEnvironment(config.TileSize, config.WorldWidth, config.WorldHeight, config.CameraSpeed);

            // Set up a directory for game assets and set an environment variable pointing to it
            string assetDirectoryPath;
            if (!string.IsNullOrEmpty(config.AssetDirectory))
            {
                assetDirectoryPath = Path.Combine(config.AssetDirectory, "game-assets");
            }
            else
            {
                var appDataDir = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
                assetDirectoryPath = Path.Combine(appDataDir, "GameAssets");
            }

            // Create directory if it doesn't exist or handle case where directory already exists
            if (!Directory.Exists(assetDirectoryPath))
            {
                Directory.CreateDirectory(assetDirectoryPath);
            }
            else
            {
                Console.WriteLine($"Asset directory already exists: {assetDirectoryPath}");
            }

            // Set environment variable pointing to asset directory
            Environment.SetEnvironmentVariable("ASSET_DIRECTORY", assetDirectoryPath, EnvironmentVariableTarget.Process);

            // Monitor system resource usage and adjust performance based on available memory and CPU capacity
            var resourceMonitor = new ResourceMonitor();
            while (true)
            {
                var availableMemory = resourceMonitor.GetAvailableMemory();
                if (availableMemory < 0.25f)
                {
                    Console.WriteLine($"Low memory detected: {availableMemory}%");
                    gameEnvironment.AdjustPerformance(PerformanceTuningMode.Responsiveness);
                }
                else if (availableMemory > 0.75f)
                {
                    Console.WriteLine($"High memory detected: {availableMemory}%");
                    gameEnvironment.AdjustPerformance(PerformanceTuningMode.Performance);
                }

                var availableCpu = resourceMonitor.GetAvailableCPU();
                if (availableCpu < 0.25f)
                {
                    Console.WriteLine($"Low CPU detected: {availableCpu}%");
                    gameEnvironment.AdjustPerformance(PerformanceTuningMode.Responsiveness);
                }
                else if (availableCpu > 0.75f)
                {
                    Console.WriteLine($"High CPU detected: {availableCpu}%");
                    gameEnvironment.AdjustPerformance(PerformanceTuningMode.Performance);
                }
            }
        }
    }

    public class Configuration
    {
        [JsonPropertyName("tile_size")]
        public int TileSize { get; set; }

        [JsonPropertyName("world_width")]
        public int WorldWidth { get; set; }

        [JsonPropertyName("world_height")]
        public int WorldHeight { get; set; }

        [JsonPropertyName("camera_speed")]
        public float CameraSpeed { get; set; }

        [JsonPropertyName("asset_directory")]
        public string AssetDirectory { get; set; }
    }
}
