package com.example.hasher;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class Hasher {
    private static final Logger logger = Logger.getLogger(Hasher.class.getName());
    private static final int DEFAULT_HASH_ALGORITHM = MessageDigest.MD5;
    private static final int DEFAULT_CACHE_SIZE = 1024;
    private static final String DEFAULT_CACHE_TYPE = "LRU";
    private static final String DEFAULT_LOG_LEVEL = Level.INFO.getName();
    private static final String DEFAULT_LOG_FORMAT = "%s [%s] %d - %s";
    private static final int DEFAULT_THREAD_POOL_SIZE = 8;
    private static final int DEFAULT_THREAD_POOL_KEEPALIVE_TIME = 10000;
    private static final String DEFAULT_EXTERNAL_API_URL = "https://external-api.com/";
    private static final int DEFAULT_EXTERNAL_API_REQUEST_TIMEOUT = 10000;
    private static final Map<Integer, String> ALGORITHM_MAP = new HashMap<>();

    static {
        // Initialize algorithm map
        ALGORITHM_MAP.put(MessageDigest.MD5, "MD5");
        ALGORITHM_MAP.put(MessageDigest.SHA_1, "SHA-1");
        ALGORITHM_MAP.put(MessageDigest.SHA_256, "SHA-256");
    }

    private final Map<String, String> cache; // Cache for storing hashes
    private final ExecutorService threadPool; // Thread pool for processing requests
    private final Set<Integer> algorithms = new HashSet<>(); // Supported hashing algorithms
    private final Logger log; // Logger instance for logging start and end timestamps, input string length, and generated hashes

    /**
     * Constructs a new {@code Hasher} instance.
     */
    public Hasher() {
        this(DEFAULT_CACHE_SIZE);
    }

    /**
     * Constructs a new {@code Hasher} instance with the specified cache size.
     *
     * @param cacheSize The size of the cache in bytes.
     */
    public Hasher(int cacheSize) {
        this(cacheSize, DEFAULT_CACHE_TYPE);
    }

    /**
     * Constructs a new {@code Hasher} instance with the specified cache size and type.
     *
     * @param cacheSize The size of the cache in bytes.
     * @param cacheType The type of cache to use, either "LRU" or "FIFO".
     */
    public Hasher(int cacheSize, String cacheType) {
        this(cacheSize, cacheType, DEFAULT_THREAD_POOL_SIZE);
    }

    /**
     * Constructs a new {@code Hasher} instance with the specified cache size, type, and thread pool size.
     *
     * @param cacheSize The size of the cache in bytes.
     * @param cacheType The type of cache to use, either "LRU" or "FIFO".
     * @param threadPoolSize The number of threads in the thread pool.
     */
    public Hasher(int cacheSize, String cacheType, int threadPoolSize) {
        this(cacheSize, cacheType, threadPoolSize, DEFAULT_THREAD_POOL_KEEPALIVE_TIME);
    }

    /**
     * Constructs a new {@code Hasher} instance with the specified cache size, type, thread pool size, and keep-alive time.
     *
     * @param cacheSize The size of the cache in bytes.
     * @param cacheType The type of cache to use, either "LRU" or "FIFO".
     * @param threadPoolSize The number of threads in the thread pool.
     * @param keepAliveTime The time to keep idle threads alive before terminating them.
     */
    public Hasher(int cacheSize, String cacheType, int threadPoolSize, long keepAliveTime) {
        // Initialize cache
        if (cacheType.equals("LRU")) {
            this.cache = new LinkedHashMap<String, String>(16, 0.75f, true) {
                @Override
                protected boolean removeEldestEntry(Map.Entry eldest) {
                    return size() > cacheSize;
                }
            };
        } else if (cacheType.equals("FIFO")) {
            this.cache = new LinkedHashMap<String, String>(16, 0.75f, false) {
                @Override
                protected boolean removeEldestEntry(Map.Entry eldest) {
                    return size() > cacheSize;
                }
            };
        } else {
            throw new IllegalArgumentException("Invalid cache type: " + cacheType);
        }

        // Initialize thread pool
        this.threadPool = Executors.newFixedThreadPool(threadPoolSize);

        // Initialize logger
        this.log = Logger.getLogger(Hasher.class.getName());
    }

    /**
     * Adds a hashing algorithm to the set of supported algorithms.
     *
     * @param algorithm The name of the algorithm to add, e.g., "MD5", "SHA-1", or "SHA-256".
     */
    public void addAlgorithm(String algorithm) {
        try {
            MessageDigest.getInstance(algorithm);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalArgumentException("Invalid algorithm: " + algorithm, e);
        }
        algorithms.add(MessageDigest.getInstance(algorithm).getAlgorithm());
    }

    /**
     * Generates a set of cryptographic hashes for the specified string using the supported algorithms.
     *
     * @param inputString The input string to be hashed.
     * @return A set of hashes for the input string, one for each supported algorithm.
     */
    public Set<String> generateHashes(String inputString) {
        if (inputString.length() > 1024) {
            logger.log(Level.WARNING, "Validation failed: Input string exceeds maximum length of 1024 characters.");
            return Collections.emptySet();
        }
        Set<String> hashes = new HashSet<>();
        for (Integer algorithm : algorithms) {
            try {
                MessageDigest digest = MessageDigest.getInstance(ALGORITHM_MAP.get(algorithm));
                digest.update(inputString.getBytes("UTF-8"));
                hashes.add(new String(digest.digest(), "UTF-8"));
            } catch (NoSuchAlgorithmException | UnsupportedEncodingException e) {
                logger.log(Level.SEVERE, "Error generating hash for algorithm: " + ALGORITHM_MAP.get(algorithm), e);
            }
        }
        return hashes;
    }

    /**
     * Verifies the uniqueness of each generated hash within a global dataset using an external API.
     *
     * @param inputString The input string to be verified.
     * @return A set of unique hashes for the input string, one for each supported algorithm.
     */
    public Set<String> verifyUniqueness(String inputString) {
        // Generate hashes for input string using all supported algorithms
        Set<String> hashes = generateHashes(inputString);

        // Verify uniqueness of generated hashes using external API
        Map<String, Boolean> verificationMap = new HashMap<>();
        try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
            for (String hash : hashes) {
                HttpGet request = new HttpGet(DEFAULT_EXTERNAL_API_URL + "/hash?hash=" + URLEncoder.encode(hash, "UTF-8"));
                request.setConfig(RequestConfig.custom().setSocketTimeout(DEFAULT_EXTERNAL_API_REQUEST_TIMEOUT).build());
                try (CloseableHttpResponse response = httpClient.execute(request)) {
                    int statusCode = response.getStatusLine().getStatusCode();
                    if (statusCode == 200) {
                        String body = EntityUtils.toString(response.getEntity());
                        verificationMap.put(hash, Boolean.parseBoolean(body));
                    } else {
                        logger.log(Level.WARNING, "External API request failed with status code: " + statusCode);
                        verificationMap.put(hash, false);
                    }
                } catch (IOException e) {
                    logger.log(Level.SEVERE, "Error making external API request", e);
                    verificationMap.put(hash, false);
                }
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error creating HTTP client", e);
            return Collections.emptySet();
        }

        // Return set of unique hashes
        Set<String> uniqueHashes = new HashSet<>();
        for (String hash : hashes) {
            if (verificationMap.get(hash)) {
                uniqueHashes.add(hash);
            }
        }
        return uniqueHashes;
    }

    /**
     * Processes a batch of strings and generates a set of cryptographic hashes for each, supporting multiple algorithms.
     *
     * @param inputStrings A collection of input strings to be processed.
     * @return A map of input strings to their corresponding unique hashes, one for each supported algorithm.
     */
    public Map<String, Set<String>> processBatch(Collection<String> inputStrings) {
        // Initialize map to store results
        Map<String, Set<String>> resultMap = new HashMap<>();

        // Iterate over input strings and generate hashes using supported algorithms
        for (String inputString : inputStrings) {
            Set<String> hashes = verifyUniqueness(inputString);
            if (!hashes.isEmpty()) {
                resultMap.put(inputString, hashes);
            }
        }

        // Return map of input strings to their corresponding unique hashes
        return resultMap;
    }

    /**
     * Processes a batch of strings and generates a set of cryptographic hashes for each, supporting multiple algorithms.
     * This method is designed to be thread-safe and can handle concurrent requests.
     *
     * @param inputStrings A collection of input strings to be processed.
     * @return A map of input strings to their corresponding unique hashes, one for each supported algorithm.
     */
    public Map<String, Set<String>> processBatchAsync(Collection<String> inputStrings) {
        // Initialize map to store results
        Map<String, Set<String>> resultMap = new ConcurrentHashMap<>();

        // Submit asynchronous tasks to thread pool
        for (String inputString : inputStrings) {
            threadPool.submit(() -> {
                Set<String> hashes = verifyUniqueness(inputString);
                if (!hashes.isEmpty()) {
                    resultMap.put(inputString, hashes);
                }
            });
        }

        // Wait for all tasks to complete and return map of input strings to their corresponding unique hashes
        threadPool.shutdown();
        try {
            threadPool.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            logger.log(Level.SEVERE, "Error awaiting termination of thread pool", e);
            return Collections.emptyMap();
        }
        return resultMap;
    }
}']

