    // Check for duplicate name and email
    $duplicateName = checkDuplicateName($name);
    $duplicateEmail = checkDuplicateEmail($email);

    if ($duplicateName || $duplicateEmail) {
      return json_encode(['message' => 'error', 'error' => 'Duplicate name or email']);
    }
  }

  // Validate input data
  if (strlen($name) < 2) {
    return json_encode(['message' => 'error', 'error' => 'Name must be at least 2 characters long']);
  }

  if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
    return json_encode(['message' => 'error', 'error' => 'Email is not valid']);
  }

  if (strlen($password) < 8) {
    return json_encode(['message' => 'error', 'error' => 'Password must be at least 8 characters long']);
  }

  // Update or create user account
  $user = isset($_REQUEST['id']) ? updateUser($id, $name, $email, $password) : createUser($name, $email, $password);

  if ($user === false) {
    return json_encode(['message' => 'error', 'error' => 'Error updating or creating user']);
  }

  // Send confirmation email (if enabled)
  if ($sub_action !== 'delete') {
    $confirmationEmail = sendConfirmationEmail($user);
    if ($confirmationEmail === false) {
      return json_encode(['message' => 'error', 'error' => 'Error sending confirmation email']);
    }
  }

  // Handle deletion
  if ($sub_action === 'delete') {
    $deleted = deleteUser($id);
    if (!$deleted) {
      return json_encode(['message' => 'error', 'error' => 'Error deleting user']);
    }
  }

  // Return success message
  return json_encode(['message' => 'success']);
}

function getUser($id) {
  // Connect to database and retrieve user data
  $user = dbQuery("SELECT * FROM users WHERE id = ?", [$id]);
  if (!$user) {
    return false;
  }
  return $user;
}

function updateUser($id, $name, $email, $password) {
  // Connect to database and update user data
  $updated = dbQuery("UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?", [$name, $email, $password, $id]);
  if (!$updated) {
    return false;
  }
  return true;
}

function createUser($name, $email, $password) {
  // Connect to database and insert new user data
  $inserted = dbQuery("INSERT INTO users (name, email, password) VALUES (?, ?, ?)", [$name, $email, $password]);
  if (!$inserted) {
    return false;
  }
  return true;
}

function deleteUser($id) {
  // Connect to database and delete user data
  $deleted = dbQuery("DELETE FROM users WHERE id = ?", [$id]);
  if (!$deleted) {
    return false;
  }
  return true;
}

function sendConfirmationEmail($user) {
  // Connect to external API and send confirmation email
  $sent = apiCall('send-confirmation-email', [$user['name'], $user['email']]);
  if (!$sent) {
    return false;
  }
  return true;
}

function checkDuplicateName($name) {
  // Connect to database and check for duplicate name
  $duplicate = dbQuery("SELECT COUNT(*) FROM users WHERE name = ?", [$name]);
  if ($duplicate > 0) {
    return true;
  }
  return false;
}

function checkDuplicateEmail($email) {
  // Connect to database and check for duplicate email
  $duplicate = dbQuery("SELECT COUNT(*) FROM users WHERE email = ?", [$email]);
  if ($duplicate > 0) {
    return true;
  }
  return false;
}
```
Note: This code is just an example and may need to be modified based on your specific requirements. Additionally, you will need to replace the `dbQuery()` function with a working database query function, as well as the `apiCall()` function with a working API call function.']

