    public class HttpPostRequestHandler : IHttpPostRequestHandler
    {
        private readonly IPageSectionRepository _pageSectionRepository;
        private readonly IElemetnRepository _elementRepository;
        private readonly ICacheService _cacheService;
        private readonly ILogger _logger;

        public HttpPostRequestHandler(IPageSectionRepository pageSectionRepository, IElemetnRepository elementRepository, ICacheService cacheService, ILogger logger)
        {
            _pageSectionRepository = pageSectionRepository;
            _elementRepository = elementRepository;
            _cacheService = cacheService;
            _logger = logger;
        }

        public async Task<bool> HandleHttpPostRequestAsync(int pageSectionId, int elementId, string htmlContent)
        {
            // Validate input parameters
            if (pageSectionId < 1 || pageSectionId > 100)
            {
                throw new ArgumentException("Invalid page section ID.", nameof(pageSectionId));
            }

            if (elementId < 1 || elementId > 100)
            {
                throw new ArgumentException("Invalid element ID.", nameof(elementId));
            }

            if (string.IsNullOrEmpty(htmlContent))
            {
                throw new ArgumentException("Invalid HTML content.", nameof(htmlContent));
            }

            // Check if the provided HTML content matches the existing content in the database, minimizing unnecessary updates
            var cachedHtmlContent = _cacheService.GetCachedHtmlContent(pageSectionId, elementId);
            if (cachedHtmlContent == htmlContent)
            {
                return false;
            }

            // Update the UI component
            try
            {
                await _elementRepository.UpdateElementAsync(elementId, htmlContent);
                await _cacheService.SetCachedHtmlContentAsync(pageSectionId, elementId, htmlContent);
                return true;
            }
            catch (Exception ex)
            {
                _logger.Error($"Failed to update UI component with ID {elementId} in page section {pageSectionId}.", ex);
                throw new InvalidOperationException("Failed to update UI component.", ex);
            }
        }
    }
