import java.util.logging.Logger;

public class MoSTStateLoader {
    private static final Logger LOGGER = Logger.getLogger(MoSTStateLoader.class.getName());
    private static final int CACHE_DURATION = 10; // in minutes
    private static final String FILE_PATH = "/path/to/file";
    private static ObjectInputStream inputStream;

    public MoSTState loadState() throws IOException {
        try {
            if (inputStream == null || TimeUnit.MINUTES.toMillis(CACHE_DURATION) < System.currentTimeMillis() - inputStream.getLastModified()) {
                // cache is expired or not initialized, load from file
                inputStream = new ObjectInputStream(new FileInputStream(FILE_PATH));
            } else {
                // use cached object
            }

            Object obj = inputStream.readObject();
            if (obj instanceof MoSTState) {
                return (MoSTState) obj;
            } else {
                LOGGER.log(Level.WARNING, "Invalid state object found in file");
                return null;
            }
        } catch (ClassNotFoundException e) {
            LOGGER.log(Level.SEVERE, "Failed to load state", e);
            return null;
        } finally {
            if (inputStream != null) {
                inputStream.close();
            }
        }
    }
}
