function updateClinicStatus($clinicId, $newStatus) {
    // Validate clinic ID against a predefined list of valid IDs
    if (!in_array($clinicId, ['123', '456', '789'])) {
        throw new Exception('Invalid clinic ID');
    }

    // Check if the new status is within an allowed set of statuses
    $allowedStatuses = ['active', 'inactive'];
    if (!in_array($newStatus, $allowedStatuses)) {
        throw new Exception('Invalid status');
    }

    // Connect to database and retrieve clinic record
    $db = connectToDatabase();
    $clinicRecord = $db->query("SELECT * FROM clinics WHERE id = ?", [$clinicId])->fetch(PDO::FETCH_ASSOC);

    if (!$clinicRecord) {
        throw new Exception('Clinic not found');
    }

    // Update database with new status, last modified IP address, and last modified date
    $ipAddress = getClientIP();
    $currentTimestamp = gmdate("Y-m-d H:i:s");

    $db->query("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?", [$newStatus, $ipAddress, $currentTimestamp, $clinicId]);

    // Log update operation with relevant details for auditing purposes
    logUpdateOperation($clinicRecord['name'], $clinicRecord['status'], $newStatus, $ipAddress);

    // Notify relevant parties about the change using an external API
    try {
        notifyParties($clinicId, $newStatus);
    } catch (Exception $e) {
        // Handle potential network issues or other exceptions gracefully
        logError('Failed to notify parties', $e->getMessage());
    }

    // Return success message if update is successful
    return 'Clinic status updated successfully';
}

function connectToDatabase() {
    // Establish database connection and perform any necessary configuration
    $dsn = 'mysql:host=localhost;dbname=your_database_name';
    $username = 'your_username';
    $password = 'your_password';

    try {
        $db = new PDO($dsn, $username, $password);
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        return $db;
    } catch (PDOException $e) {
        throw new Exception('Failed to connect to database', 0, $e);
    }
}

function getClientIP() {
    // Retrieve client IP address from request headers
    $ipAddress = $_SERVER['REMOTE_ADDR'];
    return $ipAddress;
}

function logUpdateOperation($clinicName, $oldStatus, $newStatus, $ipAddress) {
    // Log update operation with relevant details for auditing purposes
    $logger = new Logger();
    $logger->info("Clinic {$clinicName} updated from status {$oldStatus} to {$newStatus} by IP address {$ipAddress}");
}

function logError($message, $exception) {
    // Log error messages and exceptions for comprehensive traceability
    $logger = new Logger();
    $logger->error("{$message}: {$exception->getMessage()}");
}

function notifyParties($clinicId, $newStatus) {
    // Integrate with external API to notify relevant parties about the change
    $apiUrl = 'https://example.com/update-status';
    $headers = [
        'Content-Type: application/json',
        'Authorization: Bearer your_token'
    ];

    $body = json_encode([
        'clinicId' => $clinicId,
        'newStatus' => $newStatus
    ]);

    try {
        $response = http_request($apiUrl, $headers, $body);
        return $response;
    } catch (Exception $e) {
        // Handle potential network issues or other exceptions gracefully
        logError('Failed to notify parties', $e->getMessage());
        throw new Exception('Failed to notify parties');
    }
}
