using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace ConfigurationLoader
{
    public class ConfigurationLoader
    {
        private static readonly HttpClient _httpClient = new HttpClient();

        // Retry configuration
        private const int MaxRetries = 3;
        private static readonly TimeSpan ExponentialBackoff = TimeSpan.FromSeconds(1);

        // Caching configuration
        private static readonly ConcurrentDictionary<string, Configuration> _cachedConfigurations = new ConcurrentDictionary<string, Configuration>();

        public async Task<Configuration> LoadConfigurationAsync()
        {
            try
            {
                string configUrl = "https://example.com/config"; // Replace with your configuration URL

                // Try to get the configuration from cache
                if (_cachedConfigurations.TryGetValue(configUrl, out Configuration cachedConfiguration))
                {
                    return cachedConfiguration;
                }

                // Fetch and parse the configuration data from the API
                HttpResponseMessage response = await _httpClient.GetAsync(configUrl);
                string json = await response.Content.ReadAsStringAsync();
                Configuration config = JsonConvert.DeserializeObject<Configuration>(json);

                // Validate the configuration
                if (config == null || config.CharacterSet == null || config.HashFunction == null)
                {
                    throw new ArgumentException("Invalid configuration", nameof(config));
                }

                // Hash the password using the specified hash function
                string hashedPassword = ComputeHash(config.HashFunction, config.Password);
                if (hashedPassword == null)
                {
                    throw new InvalidOperationException($"Unsupported hash function: {config.HashFunction}");
                }

                // Generate a random string using the specified character set and length
                string randomString = GenerateRandomString(config.CharacterSet, config.Length);
                if (randomString == null)
                {
                    throw new ArgumentException($"Unsupported character set: {config.CharacterSet}", nameof(config));
                }

                // Create a new configuration instance with the hashed password and random string
                Configuration newConfiguration = new Configuration()
                {
                    Password = hashedPassword,
                    RandomString = randomString,
                };

                // Cache the new configuration for future requests
                _cachedConfigurations.TryAdd(configUrl, newConfiguration);

                return newConfiguration;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error loading configuration: {ex.Message}");
                throw;
            }
        }

        private string ComputeHash(string hashFunction, string password)
        {
            if (hashFunction == "SHA-256")
            {
                return SHA256.ComputeHash(Encoding.UTF8.GetBytes(password));
            }
            else if (hashFunction == "BCrypt")
            {
                return BCrypt.HashPassword(password);
            }

            throw new ArgumentException($"Unsupported hash function: {hashFunction}", nameof(hashFunction));
        }

        private string GenerateRandomString(string characterSet, int length)
        {
            if (characterSet == "alphanumeric")
            {
                return RandomStringUtils.RandomAlphanumeric(length);
            }
            else if (characterSet == "numeric")
            {
                return RandomStringUtils.RandomNumeric(length);
            }

            throw new ArgumentException($"Unsupported character set: {characterSet}", nameof(characterSet));
        }
    }
}
