import requests
from jwt import JWT

class AuthenticationService:
    def __init__(self, external_service_url):
        self.external_service_url = external_service_url

    def authenticate(self, username, password):
        try:
            response = requests.post(
                f"{self.external_service_url}/authenticate",
                json={"username": username, "password": password}
            )

            if response.status_code == 200:
                data = response.json()
                token = JWT(data["token"], algorithms=["HS256"])
                return token.decode("utf-8")
            else:
                raise Exception(f"Authentication failed with status code {response.status_code}")
        except requests.exceptions.RequestException as e:
            raise Exception(f"Error connecting to external service: {e}")

    def get_user_roles(self, username):
        try:
            response = requests.get(
                f"{self.external_service_url}/users/{username}/roles",
                headers={"Authorization": "Bearer {}".format(self.access_token)}
            )

            if response.status_code == 200:
                data = response.json()
                return data["roles"]
            else:
                raise Exception(f"Failed to retrieve user roles with status code {response.status_code}")
        except requests.exceptions.RequestException as e:
            raise Exception(f"Error connecting to external service: {e}")
```
