    if (!in_array($imageFormat, [IMAGETYPE_JPEG, IMAGETYPE_PNG])) {
        throw new Exception('Unsupported image format');
    }

    // 3. Upload image to multiple cloud storage services for redundancy and failover
    $cloudServices = [
        'Amazon S3',
        'Google Cloud Storage',
        'Microsoft Azure Blob Storage'
    ];
    $uploadedServices = [];
    foreach ($cloudServices as $service) {
        try {
            uploadImageToService($userId, $imageFile, $service);
            $uploadedServices[] = $service;
        } catch (Exception $e) {
            // Retry up to 3 times with exponential backoff
            if (count($uploadedServices) >= 3) {
                throw new Exception('Failed to upload image to all cloud services');
            }
            sleep(pow(2, count($uploadedServices)));
        }
    }

    // 4. Update metadata for uploaded images
    $metadata = [
        'userId' => $userId,
        'imageName' => $imageFile->getClientOriginalName(),
        'imageFormat' => $imageFormat,
        'uploadedServices' => $uploadedServices
    ];
    updateImageMetadata($metadata);

    // 5. Handle concurrent executions and resource contention
    $mutex = new Mutex();
    if ($mutex->acquire()) {
        try {
            // Update metadata for uploaded images
            updateImageMetadata($metadata);
        } finally {
            $mutex->release();
        }
    } else {
        throw new Exception('Failed to acquire mutex');
    }

    // 6. Logging and monitoring
