  uint16_t RNTI;
  uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define structure for list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
  NFAPI_CRC_INDICATION_PDU_T* data;
  size_t size;
} NFAPI_CRC_INDICATION_LIST_T;

// Define function to initialize list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T* nfapi_crc_indication_list_init(size_t initial_size) {
  // Allocate memory for list data and initialize it to NULL
  NFAPI_CRC_INDICATION_LIST_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
  list->data = calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
  list->size = initial_size;

  // Initialize mutex for thread-safe access to list data
  pthread_mutex_init(&list->mutex, NULL);

  return list;
}

// Define function to add a new element to the end of the list
void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T elem) {
  // Acquire mutex for thread-safe access to list data
  pthread_mutex_lock(&list->mutex);

  // Check if the list needs to be resized
  if (list->size == 0 || list->data[list->size - 1] != elem) {
    // Double the size of the list data if necessary
    if (list->size >= list->max_size) {
      list->data = realloc(list->data, list->max_size * 2);
      list->max_size *= 2;
    }

    // Add new element to the end of the list
    list->data[list->size++] = elem;
  }

  // Release mutex for thread-safe access to list data
  pthread_mutex_unlock(&list->mutex);
}

// Define function to get a pointer to an element in the list by its index
NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_list_get(NFAPI_CRC_INDICATION_LIST_T* list, size_t idx) {
  // Acquire mutex for thread-safe access to list data
  pthread_mutex_lock(&list->mutex);

  // Return pointer to element at the specified index in the list
  NFAPI_CRC_INDICATION_PDU_T* elem = &list->data[idx];

  // Release mutex for thread-safe access to list data
  pthread_mutex_unlock(&list->mutex);

  return elem;
}

// Define function to clear all elements from the list
void nfapi_crc_indication_list_clear(NFAPI_CRC_INDICATION_LIST_T* list) {
  // Acquire mutex for thread-safe access to list data
  pthread_mutex_lock(&list->mutex);

  // Reset list size and free memory used by the list data
  list->size = 0;
  free(list->data);

  // Release mutex for thread-safe access to list data
  pthread_mutex_unlock(&list->mutex);
}

// Define function to serialize the list to an external storage device
void nfapi_crc_indication_list_serialize(NFAPI_CRC_INDICATION_LIST_T* list, FILE* fp) {
  // Acquire mutex for thread-safe access to list data
  pthread_mutex_lock(&list->mutex);

  // Write the size of the list to the file
  fwrite(&list->size, sizeof(size_t), 1, fp);

  // Write each element in the list to the file
  for (size_t i = 0; i < list->size; i++) {
    NFAPI_CRC_INDICATION_PDU_T* elem = &list->data[i];
    fwrite(elem, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
  }

  // Release mutex for thread-safe access to list data
  pthread_mutex_unlock(&list->mutex);
}

// Define function to deserialize the list from an external storage device
void nfapi_crc_indication_list_deserialize(NFAPI_CRC_INDICATION_LIST_T* list, FILE* fp) {
  // Acquire mutex for thread-safe access to list data
  pthread_mutex_lock(&list->mutex);

  // Read the size of the list from the file
  size_t size;
  fread(&size, sizeof(size_t), 1, fp);

  // Resize the list data to match the size read from the file
  list->data = realloc(list->data, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  list->size = size;

  // Read each element in the list from the file and add it to the list
  for (size_t i = 0; i < list->size; i++) {
    NFAPI_CRC_INDICATION_PDU_T* elem = &list->data[i];
    fread(elem, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
    nfapi_crc_indication_list_add(list, *elem);
  }

  // Release mutex for thread-safe access to list data
  pthread_mutex_unlock(&list->mutex);
}
