public class AtomicProcess {
    public static void main(String[] args) throws Exception {
        // Step 1: Check if config.txt exists and move it to backup directory
        Path configFilePath = Paths.get("config.txt");
        if (Files.exists(configFilePath)) {
            Files.move(configFilePath, Paths.get("backup/config.txt"), StandardCopyOption.ATOMIC_MOVE);
        }

        // Step 2: Construct command string for process_data.sh
        String inputFile = "config.txt";
        String outputFile = getOutputFile(inputFile);
        String cmd = "scripts/process_data.sh --input " + inputFile + " --output " + outputFile;

        // Step 3: Execute command using ProcessBuilder
        ProcessBuilder pb = new ProcessBuilder("bash", "-c", cmd);
        Process process = pb.start();

        // Step 4: Handle exceptions and ensure graceful termination
        BufferedReader stdOutput = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            // Restore config.txt from backup directory
            Path backupFilePath = Paths.get("backup/config.txt");
            if (Files.exists(backupFilePath)) {
                Files.move(backupFilePath, configFilePath, StandardCopyOption.ATOMIC_MOVE);
            }
        }

        // Step 5: Log standard output and error streams to execution log file
        String stdout = readStream(stdOutput);
        String stderr = readStream(stdError);
        Files.writeString(Paths.get("logs/execution_log.txt"), "Exit code: " + exitCode + "\n" + "Standard output:\n" + stdout + "\n" + "Standard error:\n" + stderr, StandardOpenOption.CREATE, StandardOpenOption.APPEND);

        // Step 6: Implement monitoring mechanism to track process health and log failures/retries
        if (exitCode != 0) {
            // Log failure and attempt retries with exponential backoff
            Files.writeString(Paths.get("logs/execution_log.txt"), "Failure: Exit code " + exitCode, StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        } else {
            // Log success
            Files.writeString(Paths.get("logs/execution_log.txt"), "Success", StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        }

        // Step 7: Implement fallback mechanisms for file system structure or external dependencies changes
        if (Files.notExists(configFilePath)) {
            // Restore config.txt from backup directory
            Path backupFilePath = Paths.get("backup/config.txt");
            if (Files.exists(backupFilePath)) {
                Files.move(backupFilePath, configFilePath, StandardCopyOption.ATOMIC_MOVE);
            } else {
                // Log failure and exit process
                Files.writeString(Paths.get("logs/execution_log.txt"), "Failure: Config file missing", StandardOpenOption.CREATE, StandardOpenOption.APPEND);
                System.exit(1);
            }
        }

        // Step 8: Optimize for performance and resource usage
        // Implement efficient log handling
        // Implement scalable solution for future workload increases
    }

    private static String getOutputFile(String inputFile) {
        // Derive output file from input file content
        return "output_" + inputFile;
    }

    private static String readStream(BufferedReader reader) throws Exception {
        StringBuilder builder = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            builder.append(line).append("\n");
        }
        return builder.toString();
    }
}
