public string HashString(string input, Encoding encoding = null)
{
    // Normalize input and pad it to a fixed length if necessary
    var normalizedInput = NormalizeInput(input);
    var paddedInput = PadInput(normalizedInput);

    // Convert input to byte array (if necessary)
    var inputBytes = encoding != null ? Encoding.Convert(paddedInput, encoding) : paddedInput;

    // Hash the input using MD5 algorithm
    var hash = MD5.Create();
    var hashedBytes = hash.ComputeHash(inputBytes);

