use std::env;
use std::fs;
use std::path::Path;
use std::thread;
use std::time::Duration;
use log::*;

fn create_dir(dir_name: &str, env_var_prefix: Option<&str>) -> Result<String, String> {
    // Check if the specified environment variable is already set
    let mut env_var = match env_var_prefix {
        Some(prefix) => format!("{}_{}", prefix, dir_name),
        None => dir_name.to_string(),
    };

    // If the environment variable is not set, attempt to create a new directory with the specified name
    if !env::var(&env_var).is_ok() {
        let mut attempts = 0;
        loop {
            match fs::create_dir(dir_name) {
                Ok(_) => break, // Directory created successfully
                Err(e) => {
                    if attempts >= 3 {
                        return Err(format!("Failed to create directory after {} attempts: {:?}", attempts, e));
                    } else {
                        // Retry with exponential backoff
                        thread::sleep(Duration::from_millis((attempts * 150).pow()));
                        attempts += 1;
                    }
                }
            };
        }
    }

    // Update the environment variable to reflect the new directory path
    env::set_var(&env_var, dir_name);

    // Log the directory creation and environment variable update actions
    info!("Created directory {} with prefix {}. Updating environment variable.", dir_name, env_var_prefix.unwrap_or(""));
    debug!("Updated environment variable: {}={}", env_var, dir_name);

    // Integrate with an external logging service
    log::log(LevelFilter::Info, &format!("Created directory {}", dir_name));
    log::log(LevelFilter::Debug, &format!("Updated environment variable: {}={}", env_var, dir_name));

    // Return the new directory path as a string
    Ok(dir_name.to_string())
}
