import json
import yaml
import configparser

class ConfigManager:
    def __init__(self):
        self.parsers = {
            "json": lambda x: json.loads(x),
            "yaml": lambda x: yaml.safe_load(x)
        }
        self.registry = {}

    def add_parser(self, format_id, parser):
        self.parsers[format_id] = parser

    def get_config(self, format_id, source_type, source_path):
        if source_type not in self.registry:
            self.registry[source_type] = {}
        if source_path not in self.registry[source_type]:
            with open(source_path, "r") as f:
                data = self.parsers[format_id](f.read())
            self.registry[source_type][source_path] = data
        return self.registry[source_type][source_path]

    def merge_configs(self, config1, config2):
        merged_config = {}
        for key in config1:
            if key not in config2:
                merged_config[key] = config1[key]
            elif isinstance(config1[key], dict) and isinstance(config2[key], dict):
                merged_config[key] = self.merge_configs(config1[key], config2[key])
            else:
                merged_config[key] = config2[key]
        for key in config2:
            if key not in config1:
                merged_config[key] = config2[key]
        return merged_config

    def override_defaults(self, default_config, user_config):
        merged_config = {}
        for key in default_config:
            if key not in user_config:
                merged_config[key] = default_config[key]
            elif isinstance(default_config[key], dict) and isinstance(user_config[key], dict):
                merged_config[key] = self.override_defaults(default_config[key], user_config[key])
            else:
                merged_config[key] = user_config[key]
        for key in user_config:
            if key not in default_config:
                merged_config[key] = user_config[key]
        return merged_config

    def validate(self, config, schema):
        # implement validation logic based on the given schema
        pass
