#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <assert.h>
#include <limits.h>

// Struct to represent a record in the pipeline
typedef struct {
    int key;
} Record;

// Custom validation function for user input
int validate_input(int lower_bound, int upper_bound) {
    if (lower_bound > upper_bound) {
        // Invalid input: lower bound exceeds upper bound
        return 0;
    }
    if (lower_bound < 0 || upper_bound < 0) {
        // Invalid input: negative values are not allowed
        return 0;
    }
    if (upper_bound > INT_MAX) {
        // Upper bound exceeds the maximum value of an integer
        return 0;
    }
    return 1;
}

// Function to manage the lifecycle of a data processing pipeline
int process_pipeline(int num_records, int lower_bound, int upper_bound) {
    // Validate user input robustly
    if (!validate_input(lower_bound, upper_bound)) {
        fprintf(stderr, "Invalid input: lower bound (%d) exceeds upper bound (%d)\n", lower_bound, upper_bound);
        return 1;
    }

    // Allocate memory for an array of record structures
    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return 2;
    }

    // Set the value of each record's int field to a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % (upper_bound - lower_bound + 1) + lower_bound;
    }

    // Sort the records based on their int values using a stable sorting algorithm
    if (num_records < 500) {
        // Quicksort for small datasets
        quicksort(records, num_records);
    } else if (num_records < 10000) {
        // Heapsort for medium-sized datasets
        heapsort(records, num_records);
    } else {
        // External merge sort for very large datasets
        merge_sort(records, num_records);
    }

    // Serialize the sorted records into a file
    FILE* fp = fopen("output.txt", "wb");
    if (!fp) {
        fprintf(stderr, "File open failed\n");
        return 3;
    }
    for (int i = 0; i < num_records; i++) {
        // Write each record to the file as a single byte
        size_t n = fwrite(&records[i], sizeof(Record), 1, fp);
        if (n != 1) {
            fprintf(stderr, "File write failed\n");
            return 4;
        }
    }
    // Close the file and free the memory allocated for the records
    fclose(fp);
    free(records);
    return 0;
}

// Quicksort implementation for small datasets
void quicksort(Record* a, int n) {
    if (n <= 1) {
        // Base case: array of size 0 or 1 is sorted
        return;
    }
    // Choose a pivot element from the first element
    Record pivot = a[0];
    // Partition the array around the pivot
    int i = 1, j = n - 1;
    while (i < j) {
        // Increment `i` until we find an element greater than the pivot
        while (a[i].key <= pivot.key) {
            i++;
        }
        // Decrement `j` until we find an element less than or equal to the pivot
        while (a[j].key > pivot.key) {
            j--;
        }
        if (i < j) {
            // Swap elements at indices `i` and `j`
            Record tmp = a[i];
            a[i] = a[j];
            a[j] = tmp;
        }
    }
    // Place the pivot element at index `i`
    Record tmp = a[0];
    a[0] = a[i];
    a[i] = tmp;
    // Recursively sort the left and right subarrays
    quicksort(a, i - 1);
    quicksort(a + i, n - i);
}

// Heapsort implementation for medium-sized datasets
void heapsort(Record* a, int n) {
    // Build a max heap from the array
    build_max_heap(a, n);
    // Sort the elements by repeatedly extracting the maximum element from the heap
    for (int i = n - 1; i >= 0; i--) {
        // Swap the maximum element with the last element of the array
        Record tmp = a[i];
        a[i] = a[0];
        a[0] = tmp;
        // Re-heapify the subarray of size `i`
        heapify(a, 0, i);
    }
}

// External merge sort implementation for very large datasets
void merge_sort(Record* a, int n) {
    // Recursively split the array into smaller chunks until we reach the minimum chunk size of 16 elements
    if (n < 16) {
        insertion_sort(a, n);
        return;
    }
    // Divide the array into two subarrays of approximately equal size
    int mid = (n + 1) / 2;
    merge_sort(a, mid);
    merge_sort(a + mid, n - mid);
    // Merge the sorted subarrays back together
    merge(a, mid, n - mid);
}

// Build a max heap from an array using recursion
void build_max_heap(Record* a, int n) {
    if (n <= 1) {
        // Base case: array of size 0 or 1 is already a max heap
        return;
    }
    // Recursively build the max heap from the subarray of indices `i` to `n - 1`
    int i = n / 2 - 1;
    build_max_heap(a, i);
    // Heapify the element at index `n - 1` if necessary
    heapify(a, n - 1, n);
}

// Heapify an array using recursion
void heapify(Record* a, int i, int n) {
    if (i < 0 || i >= n) {
        // Base case: element at index `i` is already in the correct position
        return;
    }
    // Recursively heapify the subarray of indices `2 * i + 1` to `n - 1` if necessary
    int left = 2 * i + 1;
    if (left < n && a[i].key < a[left].key) {
        heapify(a, left, n);
    }
    // Recursively heapify the subarray of indices `2 * i + 2` to `n - 1` if necessary
    int right = 2 * i + 2;
    if (right < n && a[i].key < a[right].key) {
        heapify(a, right, n);
    }
    // Swap the element at index `i` with either of its children if necessary
    if (left < n && right < n && a[left].key > a[right].key) {
        Record tmp = a[i];
        a[i] = a[right];
        a[right] = tmp;
        heapify(a, i, n);
    } else if (left < n && a[left].key > a[i].key) {
        Record tmp = a[i];
        a[i] = a[left];
        a[left] = tmp;
        heapify(a, i, n);
    }
}

// Merge two sorted arrays back together using recursion
void merge(Record* a, int mid, int n) {
    // Base case: arrays of size 0 or 1 are already sorted
    if (mid <= 1 || n <= 1) {
        return;
    }
    // Recursively merge the left and right subarrays
    merge(a, mid / 2, mid);
    merge(a, mid + mid / 2, n - mid / 2);
    // Merge the sorted subarrays back together
    int i = 0;
    int j = mid;
    int k = 0;
    while (i < mid && j < n) {
        if (a[i].key <= a[j].key) {
            // Element at index `k` is from the left subarray
            Record tmp = a[i];
            a[i] = a[k];
            a[k] = tmp;
            i++;
        } else {
            // Element at index `k` is from the right subarray
            Record tmp = a[j];
            a[j] = a[k];
            a[k] = tmp;
            j++;
        }
        k++;
    }
}
