void generateNfarelations(int N, NFAPI_CRC_INDICATION_PDU_T* arr) {
  // Initialize the disjoint-set data structure
  int numSets = N;
  int *parents = malloc(numSets * sizeof(int));
  for (int i = 0; i < numSets; i++) {
    parents[i] = i;
  }

  // Populate the array of structures with random values
  for (int i = 0; i < N; i++) {
    arr[i].RX_UE_INFORMATION_TAG = i + 1;
    arr[i].RNTI = rand() % 100000;
    arr[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0;
  }

  // Find the number of milliseconds taken to perform disjointness check
  clock_t start = clock();
  for (int i = 0; i < N; i++) {
    int root1 = findSet(i, parents);
    int root2 = findSet(i + 1, parents);
    if (root1 != root2) {
      unionSets(i, parents);
    }
  }
  clock_t end = clock();

  double totalTime = (double)(end - start) / CLOCKS_PER_SEC;
  printf("Total time taken to perform disjointness check: %f\n", totalTime);

  // Print the number of milliseconds taken for each disjoint group
  int numDisjointGroups = 0;
  for (int i = 0; i < N; i++) {
    int root = findSet(i, parents);
    if (root == i) {
      numDisjointGroups++;
      printf("Number of milliseconds taken for disjoint group %d: %f\n", numDisjointGroups, totalTime / (double)(N - 1));
    }
  }

  // Free memory used by the disjoint-set data structure
  free(parents);
}

// Finds the root node of a given node in the disjoint-set forest
int findSet(int i, int *parents) {
  if (parents[i] == i) return i;
  else return findSet(parents[i], parents);
}

// Union-find operation to merge two nodes into a single set
void unionSets(int i, int *parents) {
  int root1 = findSet(i, parents);
  int root2 = findSet(i + 1, parents);
  if (root1 != root2) {
    parents[root1] = root2;
  }
}
