} CACHE_ITEM;

struct cache_item_list {
    CACHE_ITEM items[MAX_CACHE_ITEMS];
    int count;
};

struct client_list {
    struct cache_item_list** lists;
    int count;
};

struct distributed_cache {
    struct client_list* clients;
    pthread_mutex_t mutex;
};

void initialize_distributed_cache(struct distributed_cache* dc) {
    dc->clients = (struct client_list*)malloc(sizeof(struct client_list));
    dc->clients->lists = (struct cache_item_list**)malloc(MAX_CLIENTS * sizeof(struct cache_item_list*));
    for (int i = 0; i < MAX_CLIENTS; i++) {
        dc->clients->lists[i] = (struct cache_item_list*)malloc(sizeof(struct cache_item_list));
        dc->clients->lists[i]->count = 0;
    }
    dc->clients->count = 0;
    pthread_mutex_init(&dc->mutex, NULL);
}

void configure_distributed_cache(struct distributed_cache* dc) {
    // TODO: Add configuration options for the cache here.
}

int add_client(struct distributed_cache* dc, int client_id) {
    pthread_mutex_lock(&dc->mutex);
    if (dc->clients->count >= MAX_CLIENTS) {
        pthread_mutex_unlock(&dc->mutex);
        return -1; // Error: maximum number of clients reached.
    }
    dc->clients->lists[dc->clients->count] = (struct cache_item_list*)malloc(sizeof(struct cache_item_list));
    dc->clients->lists[dc->clients->count]->count = 0;
    dc->clients->count++;
    pthread_mutex_unlock(&dc->mutex);
    return 0; // Success.
}

int remove_client(struct distributed_cache* dc, int client_id) {
    pthread_mutex_lock(&dc->mutex);
    for (int i = 0; i < dc->clients->count; i++) {
        if (dc->clients->lists[i]->client_id == client_id) {
            free(dc->clients->lists[i]);
            dc->clients->count--;
            for (int j = i; j < dc->clients->count; j++) {
                dc->clients->lists[j] = dc->clients->lists[j+1];
            }
            pthread_mutex_unlock(&dc->mutex);
            return 0; // Success.
        }
    }
    pthread_mutex_unlock(&dc->mutex);
    return -1; // Error: client not found.
}

int add_cache_item(struct distributed_cache* dc, int client_id, CACHE_ITEM item) {
    pthread_mutex_lock(&dc->mutex);
    for (int i = 0; i < dc->clients->count; i++) {
        if (dc->clients->lists[i]->client_id == client_id) {
            if (dc->clients->lists[i]->count >= MAX_CACHE_ITEMS) {
                pthread_mutex_unlock(&dc->mutex);
                return -1; // Error: maximum number of cache items reached.
            }
            dc->clients->lists[i]->items[dc->clients->lists[i]->count++] = item;
            pthread_mutex_unlock(&dc->mutex);
            return 0; // Success.
        }
    }
    pthread_mutex_unlock(&dc->mutex);
    return -1; // Error: client not found.
}

int remove_cache_item(struct distributed_cache* dc, int client_id, CACHE_ITEM item) {
    pthread_mutex_lock(&dc->mutex);
    for (int i = 0; i < dc->clients->count; i++) {
        if (dc->clients->lists[i]->client_id == client_id) {
            int index = -1;
            for (int j = 0; j < dc->clients->lists[i]->count; j++) {
                if (dc->clients->lists[i]->items[j].key == item.key &&
                    dc->clients->lists[i]->items[j].value == item.value) {
                    index = j;
                    break;
                }
            }
            if (index != -1) {
                for (int j = index; j < dc->clients->lists[i]->count-1; j++) {
                    dc->clients->lists[i]->items[j] = dc->clients->lists[i]->items[j+1];
                }
                dc->clients->lists[i]->count--;
            } else {
                pthread_mutex_unlock(&dc->mutex);
                return -1; // Error: cache item not found.
            }
            pthread_mutex_unlock(&dc->mutex);
            return 0; // Success.
        }
    }
    pthread_mutex_unlock(&dc->mutex);
    return -1; // Error: client not found.
}

void update_cache_item(struct distributed_cache* dc, int client_id, CACHE_ITEM item) {
    pthread_mutex_lock(&dc->mutex);
    for (int i = 0; i < dc->clients->count; i++) {
        if (dc->clients->lists[i]->client_id == client_id) {
            int index = -1;
            for (int j = 0; j < dc->clients->lists[i]->count; j++) {
                if (dc->clients->lists[i]->items[j].key == item.key &&
