        // Add the configuration to the array
        configs[i] = config;
    }

    // Shuffle the configurations randomly to improve operational flexibility
    srand(time(NULL));
    for (int i = 0; i < num_configs - 1; ++i) {
        int j = i + rand() % (num_configs - i);
        DeviceConfiguration* tmp = configs[i];
        configs[i] = configs[j];
        configs[j] = tmp;
    }

    // Verify the integrity of the configuration data upon initialization, including checking for valid protocol versions and ensuring all required fields are populated
    for (int i = 0; i < num_configs; ++i) {
        DeviceConfiguration* config = configs[i];
        assert(config->device_id);
        assert(config->version == 1);
        for (int j = 0; j < 3; ++j) {
