        int id_len = 16;
        char* id = (char*)malloc(id_len * sizeof(char));
        if (!id) {
            printf("Error: failed to allocate memory for device ID\n");
            return NULL;
        }
        sprintf(id, "%08x", counter->value++);
        config->device_id = id;

        // Initialize the configuration version and supported protocols
        config->version = 1;
        int num_supported_protocols = fp ? 3 : 2;
        config->supported_protocols = (char**)malloc(num_supported_protocols * sizeof(char*));
        if (!config->supported_protocols) {
            printf("Error: failed to allocate memory for supported protocols\n");
            return NULL;
        }
        int j = 0;
        if (fp) {
            char line[1024];
            while (fgets(line, sizeof(line), fp)) {
                // Trim newline character from end of line
                size_t len = strlen(line);
                if (len > 0 && line[len-1] == '\n') {
                    line[len-1] = '\0';
                }
                config->supported_protocols[j++] = strdup(line);
            }
        } else {
            config->supported_protocols[j++] = strdup("802.11a");
            config->supported_protocols[j++] = strdup("802.11b");
        }

        // Add the configuration to the array
        configs[i] = config;
    }

    // Shuffle the configurations randomly to improve operational flexibility
    srand(time(NULL));
    for (int i = 0; i < num_configs - 1; ++i) {
        int j = i + rand() % (num_configs - i);
        DeviceConfiguration* tmp = configs[i];
        configs[i] = configs[j];
        configs[j] = tmp;
    }

    // Verify the integrity of the configuration data upon initialization, including checking for valid protocol versions and ensuring all required fields are populated
    for (int i = 0; i < num_configs; ++i) {
        DeviceConfiguration* config = configs[i];
        assert(config->device_id);
        assert(config->version == 1);
        for (int j = 0; j < 3; ++j) {
            assert(config->supported_protocols[j]);
        }
    }

    // Return the array of device configurations
    return configs;
}
