int resolve_hostname(const char *hostname, u_char **ip_address) {
    // Get host IP address
    struct addrinfo *res = NULL, hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET; // only IPv4
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        // DNS resolution failed
        return -1;
    }

    struct addrinfo *cur;
    for (cur = res; cur != NULL; cur = cur->ai_next) {
        if (cur->ai_family == AF_INET && cur->ai_addrlen > 0) {
            break;
        }
    }

    if (cur == NULL) {
        // No IPv4 address found
        freeaddrinfo(res);
        return -1;
    }

    struct in_addr *ip = &((struct sockaddr_in *) cur->ai_addr)->sin_addr;
    char ip_str[INET_ADDRSTRLEN];
    if (inet_ntop(AF_INET, ip, ip_str, INET_ADDRSTRLEN) == NULL) {
        // Invalid IP address
        freeaddrinfo(res);
        return -1;
    }

    *ip_address = malloc(IP_ADDRESS_SIZE);
    if (*ip_address == NULL) {
        // Memory allocation failed
        freeaddrinfo(res);
        return -1;
    }

    memcpy(*ip_address, ip_str, IP_ADDRESS_SIZE);

    freeaddrinfo(res);

    // Initialize offset array and key array
    long *offset_array = malloc(sizeof(long) * 3);
    if (offset_array == NULL) {
        free(*ip_address);
        return -1;
    }

    int *key_array = malloc(sizeof(int) * 3);
    if (key_array == NULL) {
        free(offset_array);
        free(*ip_address);
        return -1;
    }

    // Initialize record array with random integers within specified range
    struct record *record_array = malloc(sizeof(struct record) * 3);
    if (record_array == NULL) {
        free(offset_array);
        free(key_array);
        free(*ip_address);
        return -1;
    }

    for (int i = 0; i < 3; i++) {
        offset_array[i] = random() % MAX_OFFSET;
        key_array[i] = random() % MAX_KEY;
        record_array[i].value = random() % MAX_VALUE;
    }

    return 0;
}
```
