// Function to manage concurrent processes with a moving average of CPU usage
void manage_processes() {
  // Get the current CPU usage percentage
  double cpu_usage = get_cpu_usage();

  // Calculate the number of processes to create based on the moving average and system load
  int num_processes = (int)((cpu_usage / 100) * 15);

  // Create the processes using a backoff strategy with exponential backoff and jitter
  for (int i = 0; i < num_processes; i++) {
    create_process(i);
  }
}

// Function to create a process using a backoff strategy with exponential backoff and jitter
void create_process(int id) {
  // Calculate the backoff time based on the number of attempts and a random jitter
  int backoff = (int)pow(2, id - 1) + rand() % 10;

  // Create the process with the calculated backoff time
  if (create_process(id, backoff)) {
    // Log an error message and terminate the process if creation fails
    log_error("Failed to create process");
    terminate_process(id);
  } else {
    // Log a success message if the process is created successfully
    log_success("Created process with ID %d", id);
  }
}

// Function to terminate a process and clean up any partially created processes
void terminate_process(int id) {
  // Terminate the process and clean up any partially created processes
  if (terminate_process(id)) {
    log_success("Terminated process with ID %d", id);
  } else {
    log_error("Failed to terminate process with ID %d", id);
  }
}

// Function to get the current CPU usage percentage
double get_cpu_usage() {
  // Get the current CPU usage in terms of system time
  long sys_time = get_system_time();

  // Calculate the elapsed time in seconds
  double elapsed_time = (double)(sys_time - get_system_start_time()) / CLOCKS_PER_SEC;

  // Get the CPU usage percentage based on the elapsed time and system load average
  return ((get_system_load() * 100) / sysconf(_SC_NPROCESSORS_ONLN));
}

// Function to get the current system start time
long get_system_start_time() {
  // Get the current system time in terms of seconds since the Epoch
  return time(NULL);
}

// Function to get the current CPU load average
double get_system_load() {
  // Get the current CPU load average from the /proc/loadavg file
  char* line = NULL;
  size_t len = 0;
  ssize_t read;
  FILE *fp = fopen("/proc/loadavg", "r");
  if (fp == NULL) {
    log_error("Failed to open /proc/loadavg file");
    return -1;
  }
  while ((read = getline(&line, &len, fp)) != -1) {
    char* p = strtok(line, " ");
    if (p != NULL) {
      // Get the third field which is the CPU load average
      double load_avg = atof(p);
