// Function to optimize the linked list for data retrieval, allowing efficient access and modification based on real-time requirements
void optimizeLinkedList(struct LinkedListNode **head) {
  // Implement a sorted array of pointers to nodes in the linked list
  struct LinkedListNode *current = *head;
  int size = 0;
  while (current != NULL) {
    size++;
    current = current->next;
  }
  struct LinkedListNode **sortedArray = malloc(size * sizeof(struct LinkedListNode *));

  // Populate the sorted array with pointers to nodes in the linked list
  int i = 0;
  current = *head;
  while (current != NULL) {
    sortedArray[i] = current;
    i++;
    current = current->next;
  }

  // Sort the array based on the RNTI value in each node
