  // Update the linked list with the sorted array
  struct LinkedListNode **current = sortedArray;
  while (current != NULL) {
    if (*head == NULL) {
      *head = current;
    } else {
      struct LinkedListNode *current = head;
      while (current->next != NULL) {
        current = current->next;
      }
      current->next = current;
    }
    current++;
  }
}

// Function to compare RNTIs in the linked list nodes for sorting
int compareRNTIs(const void *a, const void *b) {
  struct LinkedListNode **ia = (struct LinkedListNode **)a;
  struct LinkedListNode **ib = (struct LinkedListNode **)b;
  return (*ia)->data->RNTI - (*ib)->data->RNTI;
}
