struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
};

typedef struct NFAPI_CRC_INDICATION_PDU_T NFAPI_CRC_INDICATION_PDU_T;

struct Array {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    int capacity;
    pthread_spinlock_t lock;
};

typedef struct Array Array;

Array* array_init(int initial_capacity) {
    Array* a = malloc(sizeof(Array));
    if (a == NULL) {
        return NULL;
    }
    a->elements = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (a->elements == NULL) {
        free(a);
        return NULL;
    }
    a->capacity = initial_capacity;
    pthread_spinlock_init(&a->lock, PTHREAD_PROCESS_PRIVATE);
    return a;
}

void array_free(Array* a) {
    if (a == NULL) {
        return;
    }
    free(a->elements);
    pthread_spinlock_destroy(&a->lock);
    free(a);
}

int array_add(Array* a, NFAPI_CRC_INDICATION_PDU_T element) {
    if (a == NULL) {
        return -1;
    }
    int ret = 0;
    pthread_spinlock_lock(&a->lock);
    if (a->capacity <= a->size) {
        int new_capacity = a->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(a->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_elements == NULL) {
            ret = -1;
        } else {
            a->elements = new_elements;
            a->capacity = new_capacity;
        }
    }
    if (ret == 0) {
        a->elements[a->size] = element;
        ++(a->size);
    }
    pthread_spinlock_unlock(&a->lock);
    return ret;
}

int array_remove(Array* a, int index) {
    if (a == NULL || index < 0 || index >= a->size) {
        return -1;
    }
    int ret = 0;
    pthread_spinlock_lock(&a->lock);
    for (int i = index; i < a->size - 1; ++i) {
        a->elements[i] = a->elements[i + 1];
    }
    --(a->size);
    pthread_spinlock_unlock(&a->lock);
    return ret;
}

NFAPI_CRC_INDICATION_PDU_T array_get(Array* a, int index) {
    if (a == NULL || index < 0 || index >= a->size) {
        return -1;
    }
    pthread_spinlock_lock(&a->lock);
    NFAPI_CRC_INDICATION_PDU_T element = a->elements[index];
    pthread_spinlock_unlock(&a->lock);
    return element;
}

int array_size(Array* a) {
    if (a == NULL) {
        return -1;
    }
    int size;
    pthread_spinlock_lock(&a->lock);
    size = a->size;
