            if (isProtocolValid(header.protocolType)) {
                header.protocolType = getProtocolType(header.protocolType);
                header.payloadLength = calculatePayloadLength(header.sourceIP, header.destIP);
            } else {
                printf("Invalid protocol type %u found in packet header\n", header.protocolType);
                continue;
            }

            // Detect and skip malformed packets if necessary
            if (!isPacketValid(header)) {
                printf("Malformed packet found with source IP %u, destination IP %u, protocol type %u, and payload length %u\n", header.sourceIP, header.destIP, header.protocolType, header.payloadLength);
                continue;
            }

            // Store packet header in array
            memcpy(&packetHeaders[headerIndex], &header, sizeof(PacketHeader));
            ++headerIndex;
