    // Handle incomplete packet captures by processing only the portion that fits within the buffer size limit
    if (headerIndex < totalNumPackets) {
        printf("Incomplete packet capture detected, processing only %zu out of %d packets\n", headerIndex, totalNumPackets);
        totalNumPackets = headerIndex;
