    // Ensure thread safety if function is used in a multi-threaded environment
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    for (size_t i = 0; i < totalNumPackets; ++i) {
        pthread_mutex_lock(&mutex);
        PacketHeader* header = &packetHeaders[i];
        // Perform operations on the packet header as needed
        pthread_mutex_unlock(&mutex);
    }
    pthread_mutex_destroy(&mutex);

    free(packetHeaders);
}

