// Structure to represent a cache operation request
struct CACHE_OPERATION_REQUEST {
    int request_id;
    char* key;
    char* value;
    size_t value_size;
    time_t expiration_time;
};

// Enum for cache operation types
enum CacheOperationType {
    READ, WRITE
};

// Function to initialize and configure the distributed caching system
void init_cache_system() {
    // Initialize mutexes and semaphores for each node in the cache cluster
    for (int i = 0; i < NUMBER_OF_CACHE_NODES; i++) {
        pthread_mutex_init(&node_mutex[i], NULL);
        semaphore_init(&node_semaphore[i], 1, 0);
    }
}

// Function to allocate resources for a new client connection
void allocate_resources(int client_fd) {
    // Allocate memory for the client's cache operation request structure
    struct CACHE_OPERATION_REQUEST* request = (struct CACHE_OPERATION_REQUEST*)malloc(sizeof(struct CACHE_OPERATION_REQUEST));

    // Initialize the client's cache operation request structure with default values
    request->request_id = 0;
    request->key = NULL;
    request->value = NULL;
    request->value_size = 0;
    request->expiration_time = 0;

    // Allocate memory for the client's cache data structure
    struct CACHE_DATA* cache_data = (struct CACHE_DATA*)malloc(sizeof(struct CACHE_DATA));

    // Initialize the client's cache data structure with default values
    cache_data->cache_size = 0;
    cache_data->cache_hit_rate = 0.0;
    cache_data->cache_miss_rate = 0.0;
    cache_data->memory_usage = 0;

    // Set the client's cache operation request and data structures to NULL
    request = NULL;
    cache_data = NULL;
}

// Function to deallocate resources for a lost client connection
void deallocate_resources(int client_fd) {
    // Deallocate memory for the client's cache operation request structure
    free(request);

    // Deallocate memory for the client's cache data structure
    free(cache_data);
}

// Function to handle a new cache operation request from a client
void handle_new_request(int client_fd) {
    // Read the cache operation type and key from the client
    enum CacheOperationType operation_type;
    char* key = NULL;
    size_t value_size = 0;
    time_t expiration_time = 0;

    // Deserialize the request data from the client
    read(client_fd, &operation_type, sizeof(enum CacheOperationType));
    read(client_fd, &key, strlen(key) + 1);
    read(client_fd, &value_size, sizeof(size_t));
    read(client_fd, &expiration_time, sizeof(time_t));

    // Create a new cache operation request structure for the client
    struct CACHE_OPERATION_REQUEST* request = (struct CACHE_OPERATION_REQUEST*)malloc(sizeof(struct CACHE_OPERATION_REQUEST));
    request->request_id = 0;
    request->key = key;
    request->value = NULL;
    request->value_size = value_size;
    request->expiration_time = expiration_time;

    // Add the new cache operation request to the client's cache data structure
    struct CACHE_DATA* cache_data = (struct CACHE_DATA*)malloc(sizeof(struct CACHE_DATA));
    cache_data->cache_size += 1;
    cache_data->cache_hit_rate += 0.0;
    cache_data->cache_miss_rate += 0.0;
    cache_data->memory_usage += value_size;

    // Write the response to the client indicating the success of the request
    write(client_fd, &response, sizeof(int));
}

// Function to handle a cache read operation for a client
void handle_read_request(int client_fd) {
    // Read the key from the client
    char* key = NULL;
    read(client_fd, &key, strlen(key) + 1);

    // Find the corresponding cache entry for the given key in all nodes of the cache cluster
    struct CACHE_ENTRY* entry = NULL;
    for (int i = 0; i < NUMBER_OF_CACHE_NODES; i++) {
        pthread_mutex_lock(&node_mutex[i]);
        if ((entry = find_cache_entry(key)) != NULL) {
            break;
        }
        pthread_mutex_unlock(&node_mutex[i]);
    }

    // If an entry is found, read the value from the entry and write it to the client
    if (entry != NULL) {
        char* value = (char*)malloc(sizeof(char) * entry->value_size);
        memcpy(value, entry->value, entry->value_size);
        write(client_fd, &response, sizeof(int));
        write(client_fd, &value, sizeof(char) * entry->value_size);
    } else {
        // If no entry is found, indicate a cache miss to the client and write an empty response
        write(client_fd, &response, sizeof(int));
    }
}

// Function to handle a cache write operation for a client
void handle_write_request(int client_fd) {
    // Read the key and value from the client
    char* key = NULL;
    size_t value_size = 0;
    read(client_fd, &key, strlen(key) + 1);
    read(client_fd, &value_size, sizeof(size_t));
    char* value = (char*)malloc(sizeof(char) * value_size);
    read(client_fd, &value, sizeof(char) * value_size);

    // Find the corresponding cache entry for the given key in all nodes of the cache cluster
    struct CACHE_ENTRY* entry = NULL;
    for (int i = 0; i < NUMBER_OF_CACHE_NODES; i++) {
        pthread_mutex_lock(&node_mutex[i]);
        if ((entry = find_cache_entry(key)) != NULL) {
            break;
        }
        pthread_mutex_unlock(&node_mutex[i]);
    }

    // If an entry is found, update the value in the entry and write it to all nodes of the cache cluster
    if (entry != NULL) {
        memcpy(entry->value, value, value_size);
        for (int i = 0; i < NUMBER_OF_CACHE_NODES; i++) {
            semaphore_wait(&node_semaphore[i]);
            pthread_mutex_lock(&node_mutex[i]);
            memcpy(entry->value, value, value_size);
            pthread_mutex_unlock(&node_mutex[i]);
            semaphore_post(&node_semaphore[i]);
        }
    } else {
        // If no entry is found, create a new cache entry for the given key and value and write it to all nodes of the cache cluster
        struct CACHE_ENTRY* new_entry = (struct CACHE_ENTRY*)malloc(sizeof(struct CACHE_ENTRY));
        new_entry->key = key;
        new_entry->value = value;
        new_entry->value_size = value_size;
        for (int i = 0; i < NUMBER_OF_CACHE_NODES; i++) {
            semaphore_wait(&node_semaphore[i]);
            pthread_mutex_lock(&node_mutex[i]);
            add_cache_entry(new_entry);
            pthread_mutex_unlock(&node_mutex[i]);
            semaphore_post(&node_semaphore[i]);
        }
    }
}

// Function to handle a cache delete operation for a client
void handle_delete_request(int client_fd) {
    // Read the key from the client
    char* key = NULL;
    read(client_fd, &key, strlen(key) + 1);

    // Find the corresponding cache entry for the given key in all nodes of the cache cluster
    struct CACHE_ENTRY* entry = NULL;
    for (int i = 0; i < NUMBER_OF_CACHE_NODES; i++) {
        pthread_mutex_lock(&node_mutex[i]);
        if ((entry = find_cache_entry(key)) != NULL) {
            break;
        }
        pthread_mutex_unlock(&node_mutex[i]);
    }

    // If an entry is found, delete the entry from all nodes of the cache cluster and indicate success to the client
    if (entry != NULL) {
        for (int i = 0; i < NUMBER_OF_CACHE_NODES; i++) {
            semaphore_wait(&node_semaphore[i]);
            pthread_mutex_lock(&node_mutex[i]);
            delete_cache_entry(key);
            pthread_mutex_unlock(&node_mutex[i]);
            semaphore_post(&node_semaphore[i]);
        }
    } else {
        // If no entry is found, indicate cache miss to the client and write an empty response
        write(client_fd, &response, sizeof(int));
    }
}

// Function to find a cache entry for a given key in all nodes of the cache cluster
struct CACHE_ENTRY* find_cache_entry(char* key) {
    // Traverse each node of the cache cluster and search for a matching cache entry
    for (int i = 0; i < NUMBER_OF_CACHE_NODES; i++) {
        pthread_mutex_lock(&node_mutex[i]);
        if (node[i]->cache_data->head != NULL) {
            struct CACHE_ENTRY* current = node[i]->cache_data->head;
            while (current != NULL) {
                if (strcmp(current->key, key) == 0) {
                    pthread_mutex_unlock(&node_mutex[i]);
                    return current;
                }
                current = current->next;
            }
        }
        pthread_mutex_unlock(&node_mutex[i]);
    }
    return NULL;
}

// Function to add a cache entry for a given key and value in all nodes of the cache cluster
void add_cache_entry(struct CACHE_ENTRY* new_entry) {
    // Add the new cache entry to each node of the cache cluster
    for (int i = 0; i < NUMBER_OF_CACHE_NODES; i++) {
        semaphore_wait(&node_semaphore[i]);
        pthread_mutex_lock(&node_mutex[i]);
        new_entry->next = node[i]->cache_data->head;
        node[i]->cache_data->head = new_entry;
        node[i]->cache_data->cache_size += 1;
        pthread_mutex_unlock(&node_mutex[i]);
        semaphore_post(&node_semaphore[i]);
    }
}

// Function to delete a cache entry for a given key in all nodes of the cache cluster
void delete_cache_entry(char* key) {
    // Traverse each node of the cache cluster and search for a matching cache entry
    for (int i = 0; i < NUMBER_OF_CACHE_NODES; i++) {
        pthread_mutex_lock(&node_mutex[i]);
        if (node[i]->cache_data->head != NULL) {
            struct CACHE_ENTRY* current = node[i]->cache_data->head;
            while (current != NULL) {
                if (strcmp(current->key, key) == 0) {
                    if (current->next == NULL) {
                        node[i]->cache_data->head = NULL;
                    } else {
                        current->next->prev = current->prev;
                    }
                    free(current);
                    break;
                }
                current = current->next;
            }
        }
        pthread_mutex_unlock(&node_mutex[i]);
    }
}

// Function to update the cache hit rate for a given client in all nodes of the cache cluster
void update_cache_hit_rate(int client_fd) {
    // Read the key from the client
    char* key = NULL;
    read(client_fd, &key, strlen(key) + 1);

    // Find the corresponding cache entry for the given key in all nodes of the cache cluster
    struct CACHE_ENTRY* entry = NULL;
    for (int i = 0; i < NUMBER_OF_CACHE_NODES; i++) {
        pthread_mutex_lock(&node_mutex[i]);
        if ((entry = find_cache_entry(key)) != NULL) {
            break;
        }
        pthread_mutex_unlock(&node_mutex[i]);
    }

    // If an entry is found, update the cache hit rate for the client in all nodes of the cache cluster and indicate success to the client
    if (entry != NULL) {
        for (int i = 0; i < NUMBER_OF_CACHE_NODES; i++) {
            semaphore_wait(&node_semaphore[i]);
            pthread_mutex_lock(&node_mutex[i]);
            struct CACHE_DATA* cache_data = node[i]->cache_data;
            cache_data->cache_hit_rate += 1.0 / cache_data->cache_size;
            pthread_mutex_unlock(&node_mutex[i]);
            semaphore_post(&node_semaphore[i]);
        }
    } else {
        // If no entry is found, indicate cache miss to the client and write an empty response
        write(client_fd, &response, sizeof(int));
    }
}

// Function to update the cache size for a given client in all nodes of the cache cluster
void update_cache_size(int client_fd) {
