// Custom deserialization function for loading a state object from a file
static void* load_state(const char* filename, size_t expected_size) {
    // Open the file and read its contents into a buffer
    FILE *file = fopen(filename, "rb");
    if (!file) {
        return NULL;
    }
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);
    char* buffer = (char*)malloc(file_size);
    if (!buffer) {
        fclose(file);
        return NULL;
    }
    size_t bytes_read = fread(buffer, 1, file_size, file);
    fclose(file);
    if (bytes_read != file_size) {
        free(buffer);
        return NULL;
    }

    // Check the serialized state object's size and type
    if (bytes_read != expected_size) {
        free(buffer);
        return NULL;
    }

    // Deserialize the state object using OpenSSL
    void* deserialized_object = SSL_deserialize_state(buffer, bytes_read);
    if (!deserialized_object) {
        free(buffer);
        return NULL;
    }

    // Free the buffer and return the deserialized object
    free(buffer);
    return deserialized_object;
}

