#include <unistd.h>
#include <errno.h>

struct record {
    int key;
};

struct record_array {
    size_t capacity;
    struct record* records;
};

struct offset_array {
    size_t capacity;
    long* offsets;
};

void initialize_record_array(struct record_array* array, size_t capacity) {
    array->capacity = capacity;
    array->records = malloc(sizeof(struct record) * capacity);
}

void free_record_array(struct record_array* array) {
    if (array == NULL || array->records == NULL) return;
    free(array->records);
}

int generate_random_value(int min, int max) {
    // Use a modified implementation of the Box-Muller transform to generate uniform random numbers within the specified range
    const double pi = 3.141592653589793;
    const double delta = (max - min + 1);
    double u, v, s, x, y;
    do {
        u = rand() / ((double)RAND_MAX);
        v = rand() / ((double)RAND_MAX);
        s = sqrt(-2.0 * log(u));
        x = s * cos(2.0 * pi * v);
        y = s * sin(2.0 * pi * v);
    } while (x + y >= 1 || x + y <= -1);
    return min + floor((x + y) * delta + 0.5);
}

void populate_records(struct record_array* array, size_t count, int min, int max) {
    for (size_t i = 0; i < count; ++i) {
        struct record* record = &array->records[i];
        record->key = generate_random_value(min, max);
    }
}

void sort_records(struct record_array* array, bool ascending) {
    if (ascending) {
        qsort(array->records, array->capacity, sizeof(struct record), compare_records_ascending);
    } else {
        qsort(array->records, array->capacity, sizeof(struct record), compare_records_descending);
    }
}

int compare_records_ascending(const void* a, const void* b) {
    struct record* ra = (struct record*)a;
    struct record* rb = (struct record*)b;
    return ra->key - rb->key;
}

int compare_records_descending(const void* a, const void* b) {
    struct record* ra = (struct record*)a;
    struct record* rb = (struct record*)b;
    return rb->key - ra->key;
}

void serialize_records(struct record_array* array, char* filename) {
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }
    fwrite(&array->capacity, sizeof(size_t), 1, fp);
    fwrite(array->records, sizeof(struct record), array->capacity, fp);
    fclose(fp);
}

void deserialize_records(struct record_array* array, char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }
    size_t capacity;
    fread(&capacity, sizeof(size_t), 1, fp);
    array->capacity = capacity;
    array->records = malloc(sizeof(struct record) * capacity);
    fread(array->records, sizeof(struct record), capacity, fp);
    fclose(fp);
}

void initialize_offset_array(struct offset_array* array, size_t capacity) {
    array->capacity = capacity;
    array->offsets = malloc(sizeof(long) * capacity);
}

void free_offset_array(struct offset_array* array) {
    if (array == NULL || array->offsets == NULL) return;
    free(array->offsets);
}

void populate_offsets(struct record_array* array, struct offset_array* offsets) {
    for (size_t i = 0; i < array->capacity; ++i) {
        offsets->offsets[i] = (long)i * sizeof(struct record);
    }
}

void sort_offsets(struct offset_array* offsets, bool ascending) {
    if (ascending) {
        qsort(offsets->offsets, offsets->capacity, sizeof(long), compare_offsets_ascending);
    } else {
        qsort(offsets->offsets, offsets->capacity, sizeof(long), compare_offsets_descending);
    }
}

int compare_offsets_ascending(const void* a, const void* b) {
    long* offset1 = (long*)a;
    long* offset2 = (long*)b;
    return *offset1 - *offset2;
}

int compare_offsets_descending(const void* a, const void* b) {
    long* offset1 = (long*)a;
    long* offset2 = (long*)b;
    return *offset2 - *offset1;
}

void serialize_offsets(struct offset_array* array, char* filename) {
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }
    fwrite(&array->capacity, sizeof(size_t), 1, fp);
    fwrite(array->offsets, sizeof(long), array->capacity, fp);
    fclose(fp);
}

void deserialize_offsets(struct offset_array* array, char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }
    size_t capacity;
    fread(&capacity, sizeof(size_t), 1, fp);
    array->capacity = capacity;
    array->offsets = malloc(sizeof(long) * capacity);
    fread(array->offsets, sizeof(long), capacity, fp);
    fclose(fp);
}

void manage_records(struct record_array* array, char* filename, bool ascending) {
    struct offset_array offsets;
    initialize_offset_array(&offsets, array->capacity);
    populate_offsets(array, &offsets);
    sort_offsets(&offsets, ascending);
    serialize_offsets(&offsets, filename);
    free_offset_array(&offsets);
}

int main() {
    struct record_array array;
    initialize_record_array(&array, 1000);
    populate_records(&array, 500, INT_MIN, INT_MAX);
    sort_records(&array, true);
    char filename[256];
    puts("Enter a file name to store the sorted records: ");
    scanf("%s", filename);
    serialize_records(&array, filename);
    free_record_array(&array);
    return 0;
}']

