void add_record(Record** head, int key, char* string_field, size_t max_string_length) {
    // Allocate memory for the new record
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        printf("Failed to allocate memory for new record\n");
        return;
    }

    // Initialize the new record with the given key and string field
    new_record->key = key;
    new_record->string_field = (char*)malloc(max_string_length);
    if (!new_record->string_field) {
        printf("Failed to allocate memory for string field\n");
        free(new_record);
        return;
    }
    strncpy(new_record->string_field, string_field, max_string_length - 1);
    new_record->string_field[max_string_length - 1] = '\0';

    // Generate a random timestamp for the record
    srand((unsigned)time(NULL));
    double random_timestamp = (double)rand() / RAND_MAX;

    new_record->timestamp = random_timestamp;

    // Add the new record to the head of the linked list
    new_record->next = *head;
    *head = new_record;
}

// Function to remove a record from the collection by key
void remove_record(Record** head, int key) {
    Record* current = *head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    if (current == NULL) {
        printf("Key not found\n");
        return;
    }

    // Remove the record from the linked list
    Record* previous = current->previous;
    if (previous != NULL) {
        previous->next = current->next;
    } else {
        *head = current->next;
    }

    // Free the memory allocated for the record
    free(current);
}

// Function to update a record in the collection by key
void update_record(Record** head, int key, char* string_field) {
    Record* current = *head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    if (current == NULL) {
        printf("Key not found\n");
        return;
    }

    // Update the string field of the record
    free(current->string_field);
    current->string_field = (char*)malloc(strlen(string_field) + 1);
    strcpy(current->string_field, string_field);
}

// Function to retrieve a record from the collection by key
Record* get_record(Record** head, int key) {
    Record* current = *head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    if (current == NULL) {
        printf("Key not found\n");
        return NULL;
    }
    return current;
}
