// Function to allocate memory for and initialize two arrays: one for long offset values and one for int keys
void allocateArrays(int numRecords) {
    // Allocate memory for the two arrays
    long *offsets = (long *)malloc(numRecords * sizeof(long));
    if (!offsets) {
        printf("Error allocating memory for offset array.\n");
        return;
    }

    int *keys = (int *)malloc(numRecords * sizeof(int));
    if (!keys) {
        printf("Error allocating memory for key array.\n");
        free(offsets);
        return;
    }

    // Initialize the two arrays to zero
    memset(offsets, 0, numRecords * sizeof(long));
    memset(keys, 0, numRecords * sizeof(int));
}

// Function to manage memory for a custom memory pool that addresses fragmentation issues by periodically compacting memory or using free lists
void manageMemoryPool() {
    // Periodically compact the memory pool to address fragmentation issues
    if (time(NULL) % 10 == 0) {
        printf("Compacting memory pool.\n");
        compactMemoryPool();
    } else {
        // Use a free list to manage the memory pool, ensuring efficient allocation and deallocation of memory blocks
        freeList *freeList = createFreeList(MAX_BLOCK_SIZE);
        if (!freeList) {
            printf("Error creating free list.\n");
            return;
        }

        // Allocate a block from the free list
        void *block = allocateFromFreeList(freeList, MAX_BLOCK_SIZE);
        if (!block) {
            printf("Error allocating memory from free list.\n");
            destroyFreeList(freeList);
            return;
        }

        // Free the block when it is no longer needed
        void *freeBlock = block;
        block = (void *)((char *)block + MAX_BLOCK_SIZE - 1);
        while (freeBlock != NULL) {
            freeList->head = (freeListNode *)((char *)freeList->head - MAX_BLOCK_SIZE);
            free(freeList->head->next);
            free(freeList->head);
            freeList->head = (freeListNode *)((char *)freeBlock + 1);
            freeBlock = NULL;
        }
    }
}

// Function to serialize the sorted records into a file in a format that minimizes storage overhead while allowing for efficient retrieval
void serializeRecords(const char *fileName) {
    // Open the file for writing and create it if it doesn't exist
    FILE *file = fopen(fileName, "wb");
    if (!file) {
        printf("Error opening file '%s' for serialization.\n", fileName);
        return;
    }

