    fclose(file);
    free(records);
}

// Function to deserialize the records from a file into an in-memory data structure, ensuring efficient retrieval and minimizing storage overhead
void deserializeRecords(const char *fileName) {
    // Open the file for reading and check that it exists
    FILE *file = fopen(fileName, "rb");
    if (!file) {
        printf("Error opening file '%s' for deserialization.\n", fileName);
        return;
    }

