    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU;

// Define a custom disjoint-set data structure for efficiently managing RNTI values
typedef struct {
    uint16_t *rnti_array;
    int32_t *parent_array;
} DisjointSet;

// Prototype for the generateNfarelations function
void generateNfarelations(int N, int mem_limit, NFAPI_CRC_INDICATION_PDU **pdu_list, int *num_unique_rnti);

// Generate a random RNTI value within the specified range
uint16_t generateRandomRNTI(void) {
    return (uint16_t)(rand() % 0xffff);
}

// Initialize a disjoint-set data structure with an empty set of RNTIs
DisjointSet initializeDisjointSet(void) {
    DisjointSet ds;
    ds.rnti_array = (uint16_t *)malloc(sizeof(uint16_t));
    ds.parent_array = (int32_t *)malloc(sizeof(int32_t));
    ds.rnti_array[0] = 0;
    ds.parent_array[0] = -1;
    return ds;
}

// Union-find operation for disjoint-set data structure
void unionDisjointSet(DisjointSet *ds, int32_t node1, int32_t node2) {
    if (node1 == node2) {
        // Already in the same set, so do nothing
        return;
    }

    // Find the root nodes of both sets
    while (ds->parent_array[node1] != -1) {
        node1 = ds->parent_array[node1];
    }
    while (ds->parent_array[node2] != -1) {
        node2 = ds->parent_array[node2];
    }

    // Combine the sets by making one the parent of the other
    ds->parent_array[node1] = node2;
}

// Create and populate an array of NFAPI_CRC_INDICATION_PDU structures
void generateNfarelations(int N, int mem_limit, NFAPI_CRC_INDICATION_PDU **pdu_list, int *num_unique_rnti) {
    // Initialize a disjoint-set data structure to manage RNTI values
    DisjointSet ds = initializeDisjointSet();

    // Allocate memory for the PDU list and initialize it to NULL
    *pdu_list = (NFAPI_CRC_INDICATION_PDU *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU) * N);
    if (*pdu_list == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Generate RNTIs and populate the PDU list
    for (int i = 0; i < N; i++) {
        uint16_t rnti = generateRandomRNTI();

        // Check if the RNTI is already in a set
        int32_t node = ds.rnti_array[rnti];
        if (node == -1) {
            // Create a new set for the RNTI
            node = i;
            ds.rnti_array[rnti] = node;
            ds.parent_array[node] = -1;
        } else {
            // Union the sets of the existing and newly generated RNTIs
            unionDisjointSet(&ds, node, i);
        }

        (*pdu_list)[i].tag = RX_UE_INFORMATION_TAG;
        (*pdu_list)[i].rnti = rnti;
        (*pdu_list)[i].crc_ind_rel8_tag.crflag = (rand() % 2) ? 1 : 0;
    }

    // Return the populated PDU list and the number of unique RNTIs
    *num_unique_rnti = ds.rnti_array[0];
}

// Serialize the array of structures to a file
void serializeNfarelations(NFAPI_CRC_INDICATION_PDU **pdu_list, int num_unique_rnti, const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Error opening file %s\n", filename);
        return;
    }

    // Write the header of the serialized data
    int32_t num_pdu = num_unique_rnti * sizeof(NFAPI_CRC_INDICATION_PDU);
    fwrite(&num_pdu, sizeof(int32_t), 1, fp);

    // Write the contents of each PDU structure to the file
    for (int i = 0; i < num_unique_rnti; i++) {
        NFAPI_CRC_INDICATION_PDU *pdu = &(*pdu_list)[i];
        fwrite(pdu, sizeof(NFAPI_CRC_INDICATION_PDU), 1, fp);
    }

    // Close the file and return
    fclose(fp);
}
