// custom sorting algorithm for NFAPI_CRC_INDICATION_PDU_T structures based on CRCFLAG value
void sort_structures(NFAPI_CRC_INDICATION_PDU_T *pdu, int size) {
    // dynamic selection between quicksort and mergesort based on dataset size
    if (size <= 1024) {
        quicksort(pdu, size);
    } else {
        mergesort(pdu, size);
    }
}

// custom sorting algorithm for NFAPI_CRC_INDICATION_PDU_T structures based on CRCFLAG value
void quicksort(NFAPI_CRC_INDICATION_PDU_T *pdu, int size) {
    // partition the dataset and recursively sort each sub-array
    int pivot = pdu[0].CRCFLAG;
    int i = 1;
    while (i < size) {
        if (pdu[i].CRCFLAG > pivot) {
            swap(pdu, i - 1, i);
            i++;
        } else {
            i++;
        }
    }
    quicksort(pdu, pivot);
    quicksort(pdu + pivot, size - pivot);
}

// custom sorting algorithm for NFAPI_CRC_INDICATION_PDU_T structures based on CRCFLAG value
void mergesort(NFAPI_CRC_INDICATION_PDU_T *pdu, int size) {
    // divide the dataset into two sub-arrays and recursively sort each sub-array
    if (size <= 1024) {
        quicksort(pdu, size);
    } else {
        int mid = size / 2;
        mergesort(pdu, mid);
        mergesort(pdu + mid, size - mid);
        merge(pdu, pdu + mid, size);
    }
}

// custom sorting algorithm for NFAPI_CRC_INDICATION_PDU_T structures based on CRCFLAG value
void merge(NFAPI_CRC_INDICATION_PDU_T *pdu1, NFAPI_CRC_INDICATION_PDU_T *pdu2, int size) {
    // merge two sorted sub-arrays into a single sorted array
    NFAPI_CRC_INDICATION_PDU_T *result = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int i1 = 0, i2 = 0, r = 0;
    while (i1 < size && i2 < size) {
        if (pdu1[i1].CRCFLAG <= pdu2[i2].CRCFLAG) {
            result[r++] = pdu1[i1++];
        } else {
            result[r++] = pdu2[i2++];
        }
    }
    while (i1 < size) {
        result[r++] = pdu1[i1++];
