#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Custom memory pool structure
struct MemoryPool {
  // List of available slots in the pool
  size_t *slots;
  // Number of slots in the pool
  size_t num_slots;
  // Current number of allocated slots
  size_t num_allocated;
  // Mutex for synchronizing access to the pool
  pthread_mutex_t mutex;
};

// Initialize a custom memory pool with a given number of slots
struct MemoryPool *mempool_init(size_t num_slots) {
  struct MemoryPool *pool = malloc(sizeof(struct MemoryPool));
  if (!pool) {
    return NULL;
  }

  // Initialize the list of available slots
  pool->slots = calloc(num_slots, sizeof(size_t));
  if (!pool->slots) {
    free(pool);
    return NULL;
  }

  // Set the number of slots in the pool
  pool->num_slots = num_slots;
  pool->num_allocated = 0;

  // Initialize the mutex for synchronizing access to the pool
  if (pthread_mutex_init(&pool->mutex, NULL) != 0) {
    free(pool);
    return NULL;
  }

  return pool;
}

// Allocate a slot in the custom memory pool
size_t mempool_alloc(struct MemoryPool *pool) {
  // Acquire the mutex for synchronizing access to the pool
  pthread_mutex_lock(&pool->mutex);

  // Check if there are any available slots
  if (pool->num_allocated < pool->num_slots) {
    size_t slot = pool->slots[pool->num_allocated++];
    pthread_mutex_unlock(&pool->mutex);
    return slot;
  }

  // No available slots, return NULL
  pthread_mutex_unlock(&pool->mutex);
  return SIZE_MAX;
}

// Free a slot in the custom memory pool
void mempool_free(struct MemoryPool *pool, size_t slot) {
  // Acquire the mutex for synchronizing access to the pool
  pthread_mutex_lock(&pool->mutex);

  // Check if the given slot is valid
  if (slot < pool->num_slots && pool->slots[slot] != SIZE_MAX) {
    // Mark the slot as free
    pool->slots[slot] = SIZE_MAX;

    // Decrement the number of allocated slots
    pool->num_allocated--;
  }

  pthread_mutex_unlock(&pool->mutex);
}

// Release all resources associated with the custom memory pool
void mempool_destroy(struct MemoryPool *pool) {
  // Acquire the mutex for synchronizing access to the pool
  pthread_mutex_lock(&pool->mutex);

  // Free the list of available slots
  free(pool->slots);
  // Release the mutex
  pthread_mutex_unlock(&pool->mutex);
}
