    // Pointer to the first node in the list of free nodes
    struct Node *free_nodes;
    // Pointer to the last node in the list of free nodes
    struct Node *last_free_node;
};

// Define structure for a linked list node
struct Node {
    // Pointer to the next node in the list
    struct Node *next;
    // Pointer to the previous node in the list
    struct Node *prev;
    // Pointer to the record stored in the node
    Record *record;
};

// Define function to create a new memory pool
struct MemoryPool* create_memory_pool() {
    struct MemoryPool *memory_pool = malloc(sizeof(struct MemoryPool));
    if (memory_pool == NULL) {
        // Handle memory allocation failure gracefully
        return NULL;
    }
    memory_pool->free_nodes = NULL;
    memory_pool->last_free_node = NULL;
    return memory_pool;
}

// Define function to allocate a record from the memory pool
Record* allocate_record(struct MemoryPool *memory_pool) {
    if (memory_pool->free_nodes == NULL) {
        // Handle memory exhaustion gracefully
        return NULL;
    }
    struct Node *node = memory_pool->free_nodes;
    memory_pool->free_nodes = node->next;
    Record *record = node->record;
    free(node);
    return record;
}

// Define function to deallocate a record from the memory pool
