// Linked list structure for holding the NFAPI_CRC_INDICATION_PDU structures
typedef struct NFAPI_CRC_INDICATION_LIST {
    struct NFAPI_CRC_INDICATION_PDU* data; // Pointer to the first element of the linked list
    size_t length; // Current number of elements in the list
