// Function for dynamically creating and populating a linked list of NFAPI_CRC_INDICATION_PDU structures
NFAPI_CRC_INDICATION_LIST* createAndPopulateList(uint32_t RX_UE_INFORMATION_TAG, uint8_t CRCFLAG) {
    // Check if the list is already full
    if (list->length >= MAX_LIST_SIZE) {
        printf("Error: List is already full\n");
        return NULL;
    }

    // Create a new element for the linked list
    struct NFAPI_CRC_INDICATION_PDU* newElement = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU));
    if (newElement == NULL) {
        printf("Error: Failed to allocate memory for new list element\n");
        return NULL;
