    // Set the RNTI and CRCFLAG values in the new element
    newElement->RNTI = RX_UE_INFORMATION_TAG;
    newElement->CRCFLAG = CRCFLAG;

    // Add the new element to the end of the list
    list->length++;
    if (list->data == NULL) {
        list->data = newElement;
    } else {
        struct NFAPI_CRC_INDICATION_PDU* currentElement = list->data;
        while (currentElement->next != NULL) {
            currentElement = currentElement->next;
        }
        currentElement->next = newElement;
    }

    return list;
}

// Function for validating the uniqueness of an RX_UE_INFORMATION_TAG within the list
bool isUnique(uint32_t RX_UE_INFORMATION_TAG) {
    struct NFAPI_CRC_INDICATION_PDU* currentElement = list->data;
    while (currentElement != NULL) {
        if (currentElement->RNTI == RX_UE_INFORMATION_TAG) {
            return false; // Duplicate found
        }
        currentElement = currentElement->next;
    }
    return true; // No duplicates found
}

// Function for sorting the list based on the RNTI values in ascending order
void sortList() {
    struct NFAPI_CRC_INDICATION_PDU* currentElement = list->data;
    while (currentElement != NULL) {
        // Check if the next element is smaller than the current element
        struct NFAPI_CRC_INDICATION_PDU* nextElement = currentElement->next;
        while (nextElement != NULL && nextElement->RNTI < currentElement->RNTI) {
            // Swap the positions of the elements
            struct NFAPI_CRC_INDICATION_PDU temp = *currentElement;
            *currentElement = *nextElement;
            *nextElement = temp;
            currentElement = nextElement;
            nextElement = currentElement->next;
        }
        currentElement = currentElement->next;
    }
}

// Function for computing and returning the total number of bits set to 1 in all CRCFLAG fields across the entire list
uint32_t countBits(NFAPI_CRC_INDICATION_LIST* list) {
