// Define structure for record data
typedef struct {
    int value;
} record;

// Define configuration file format
enum config_format {
    BINARY,
    TEXT
};

// Function to dynamically allocate memory for arrays
void *allocate_array(size_t size, enum config_format format) {
    void *ptr = NULL;

    // Check if format is binary or text
    switch (format) {
        case BINARY:
            ptr = malloc(size);
            break;
        case TEXT:
            ptr = calloc(size, sizeof(char));
            break;
    }

    // Check for memory allocation errors
    if (!ptr) {
        fprintf(stderr, "Error allocating memory\n");
        exit(EXIT_FAILURE);
    }

    return ptr;
}

// Function to populate record structures with random values
void populate_records(record *records, size_t num_records) {
    srand((unsigned int) time(NULL)); // seed random number generator with current time
    for (size_t i = 0; i < num_records; i++) {
        records[i].value = rand() % 100; // generate random value within range [0, 100]
    }
}

// Function to read data from input files and populate arrays
void read_data(char *filename1, char *filename2, size_t *num_records) {
    FILE *file1 = fopen(filename1, "r"); // open file 1 for reading
    FILE *file2 = fopen(filename2, "r"); // open file 2 for reading
    record *records = NULL; // initialize pointer to array of records

    // Check if files could be opened
    if (!file1 || !file2) {
        fprintf(stderr, "Error opening input files\n");
        exit(EXIT_FAILURE);
    }

    // Read number of records from file 1
    int num_records_file1 = 0;
    if (fscanf(file1, "%d", &num_records_file1) != 1) {
        fprintf(stderr, "Error reading number of records from file 1\n");
        exit(EXIT_FAILURE);
    }

    // Read number of records from file 2
    int num_records_file2 = 0;
    if (fscanf(file2, "%d", &num_records_file2) != 1) {
        fprintf(stderr, "Error reading number of records from file 2\n");
        exit(EXIT_FAILURE);
    }

    // Check if both files have the same number of records
    if (num_records_file1 != num_records_file2) {
        fprintf(stderr, "Number of records in file 1 and file 2 are not equal\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for arrays of offsets, keys, and records
    size_t size = num_records * sizeof(int); // calculate size based on number of records
    int *offsets = (int *) allocate_array(size, BINARY); // allocate array of offsets
    int *keys = (int *) allocate_array(size, TEXT); // allocate array of keys
    records = (record *) allocate_array(size, BINARY); // allocate array of record structures

    // Check for memory allocation errors
    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error allocating memory\n");
        exit(EXIT_FAILURE);
    }

    // Read data from files and populate arrays
    size_t i = 0; // initialize index variable
    while (fscanf(file1, "%d", &offsets[i]) == 1 && fscanf(file2, "%d", &keys[i]) == 1) {
        records[i].value = rand() % 100; // generate random value within range [0, 100]
        i++; // increment index variable
    }

    *num_records = i; // set number of records to number of elements read from files

    fclose(file1); // close file 1
    fclose(file2); // close file 2
}
