<?php

// Define configuration file format
enum config_format {
    BINARY,
    TEXT
};

// Function to update user's password in database using DAO class
function update_password($username, $old_password, $new_password) {
    // Check if old and new passwords match predefined criteria
    if ($old_password == $new_password) {
        throw new Exception("New password cannot be the same as the old one");
    }

    // Validate new password strength according to configuration file
    switch (config_format) {
        case BINARY:
            if (!preg_match("/^[0-9]{6}$/", $new_password)) {
                throw new Exception("New password must be a 6-digit integer");
            }
            break;
        case TEXT:
            if (strlen($new_password) < 8 || !preg_match("#[0-9]#", $new_password)) {
                throw new Exception("New password must contain at least 8 digits and a number");
            }
            break;
    }

    // Update user's password in database using DAO class
    try {
        $dao = new DAO(); // initialize DAO object
        $dao->update_password($username, $new_password); // update password in database
    } catch (Exception $e) {
        throw new Exception("Error updating password in database: " . $e->getMessage());
    }
}
