// Function to create and populate the list of NFAPI structures
int processNFABundleAndConvertImage(char* resourceBundlePath, char* inputImageFile, char* outputDocumentFile, char* metadataFile) {
  // Load the resources from the bundle file
  FILE* resourceBundle = fopen(resourceBundlePath, "r");
  if (resourceBundle == NULL) {
    perror("Failed to open resource bundle");
    return 1;
  }

  List nfapiStructuresList;
  nfapiStructuresList.size = 0;
  nfapiStructuresList.capacity = 0;
  nfapiStructuresList.data = NULL;

  while (!feof(resourceBundle)) {
    // Read the next NFAPI structure from the bundle file
    NFAPI_CRC_INDICATION_PDU_T* nfapiStructure = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    fread(nfapiStructure, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, resourceBundle);
    nfapiStructuresList.size++;
    if (nfapiStructuresList.size > nfapiStructuresList.capacity) {
      nfapiStructuresList.capacity *= 2;
      nfapiStructuresList.data = realloc(nfapiStructuresList.data, nfapiStructuresList.capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    nfapiStructuresList.data[nfapiStructuresList.size - 1] = *nfapiStructure;
  }

  fclose(resourceBundle);

  // Create a unique identifier for each processed image using a predefined character set
  char* imageId = (char*) malloc(sizeof(char) * 10);
  srand((unsigned int) time(NULL));
  int randomIndex = rand() % 10;
  for (int i = 0; i < 10; i++) {
    imageId[i] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"[randomIndex];
  }

  // Incorporate the unique identifier into the output document metadata
  FILE* outputDocumentMetadata = fopen(metadataFile, "a");
  fprintf(outputDocumentMetadata, "%s, %s\n", imageId, inputImageFile);
  fclose(outputDocumentMetadata);

  // Convert the JPEG image file to a PDF file, incorporating additional metadata from the provided metadata file
  FILE* inputImage = fopen(inputImageFile, "r");
  if (inputImage == NULL) {
    perror("Failed to open input image");
    return 1;
  }

  // Load the JPEG image file into a buffer
  fseek(inputImage, 0, SEEK_END);
  long imageSize = ftell(inputImage);
  rewind(inputImage);

  char* imageBuffer = (char*) malloc(imageSize * sizeof(char));
  fread(imageBuffer, imageSize, 1, inputImage);
  fclose(inputImage);

  // Create a PDF file using the JPEG image data and metadata
  FILE* outputDocument = fopen(outputDocumentFile, "wb");
  if (outputDocument == NULL) {
    perror("Failed to create output document");
    return 1;
  }

  fwrite("%PDF-1.7\n", sizeof(char), 9, outputDocument);
  fwrite("\n%EOF\n", sizeof(char), 6, outputDocument);
  fwrite("2 0 obj << /Type /Page /Parent 1 0 R /Contents 3 0 R >> endobj\n", sizeof(char), 48, outputDocument);
  fwrite("3 0 obj << /Length ", sizeof(char), 17, outputDocument);
  fprintf(outputDocument, "%ld", (imageSize + 5) * sizeof(char));
  fwrite(" >> stream\n", sizeof(char), 14, outputDocument);
  fwrite("q\n", sizeof(char), 2, outputDocument);
  fwrite("0 0 1 rg\n", sizeof(char), 8, outputDocument);
  fwrite("/Im1 Do\n", sizeof(char), 9, outputDocument);
  fwrite("\nQ\n", sizeof(char), 3, outputDocument);
  fwrite("endstream\n", sizeof(char), 10, outputDocument);
  fwrite("endobj\n", sizeof(char), 8, outputDocument);
  fwrite("xref\n", sizeof(char), 5, outputDocument);
  fprintf(outputDocument, "0 %d\n", nfapiStructuresList.size + 3);
  fwrite("0000000000 65535 f \n", sizeof(char), 19, outputDocument);
  for (int i = 0; i < nfapiStructuresList.size; i++) {
    NFAPI_CRC_INDICATION_PDU_T* nfapiStructure = &nfapiStructuresList.data[i];
    fprintf(outputDocument, "%d %d obj\n", 4 + i, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    fwrite(nfapiStructure, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, outputDocument);
    fprintf(outputDocument, "endobj\n", sizeof(char), 7);
  }

  fclose(outputDocument);

  free(imageBuffer);
  free(nfapiStructuresList.data);
  free(imageId);

  return 0;
}
