    // Compute the MD5 hash of the raw binary data of the image
    FILE* bin = fopen(filename, "rb");
    if (bin == NULL) {
        printf("Error: Failed to open file %s\n", filename);
        return;
    }

    // Allocate memory for the MD5 hash
    info->md5_hash = malloc(MD5_DIGEST_LENGTH);
    if (info->md5_hash == NULL) {
        printf("Error: Failed to allocate memory for MD5 hash\n");
        return;
    }

    // Read the contents of the file and update the MD5 hash
    uint8_t buffer[BUFSIZ];
    int nread;
    while ((nread = fread(buffer, 1, BUFSIZ, bin)) > 0) {
        MD5_Update(&md5_ctx, buffer, nread);
    }

    // Close the file and free the memory allocated for the MD5 hash
    fclose(bin);
    free(info->md5_hash);
