// Memory pool structure
struct memory_pool {
    void *base;     // Base address of the memory pool
    size_t size;    // Size of the memory pool
    size_t used;    // Number of bytes currently in use
    pthread_mutex_t lock;  // Mutex for synchronizing access to the memory pool
};

// Initialize a new memory pool with a fixed-size block allocation
struct memory_pool *memory_pool_init(void *base, size_t size) {
    struct memory_pool *pool = malloc(sizeof(struct memory_pool));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for the memory pool\n");
        return NULL;
    }

    pool->base = base;
    pool->size = size;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

// Allocate a fixed-size block from the memory pool
void *memory_pool_alloc(struct memory_pool *pool, size_t size) {
    void *ptr = NULL;

    pthread_mutex_lock(&pool->lock);
    if (pool->used + size <= pool->size) {
        ptr = (char *)pool->base + pool->used;
        pool->used += size;
    }
    pthread_mutex_unlock(&pool->lock);

    return ptr;
}

// Free a fixed-size block from the memory pool
void memory_pool_free(struct memory_pool *pool, void *ptr) {
    if (ptr >= pool->base && ptr < (char *)pool->base + pool->size) {
        pthread_mutex_lock(&pool->lock);
        size_t offset = (char *)ptr - (char *)pool->base;
        pool->used -= offset;
        pthread_mutex_unlock(&pool->lock);
    }
}
```
This code defines a `memory_pool` structure that holds the base address of the memory pool, its size, and the number of bytes currently in use. It also includes a mutex to synchronize access to the memory pool. The `memory_pool_init()` function initializes a new memory pool with a fixed-size block allocation, and the `memory_pool_alloc()` function allocates a fixed-size block from the memory pool. The `memory_pool_free()` function frees a fixed-size block from the memory pool.

To use this code, you would first call `memory_pool_init()` with the base address of the memory pool and its size. Then, you could call `memory_pool_alloc()` to allocate fixed-size blocks from the memory pool. When you are done using the allocated blocks, you can call `memory_pool_free()` to free them back to the memory pool.

Note that this code assumes that the base address of the memory pool is valid and that the size parameter passed to `memory_pool_init()` is greater than 0. It also assumes that the memory pool is large enough to hold all of the fixed-size blocks that are allocated from it. If these assumptions do not hold, the code may produce incorrect results or crash.']

