// Define the structure to hold RRC indication PDUs
typedef struct {
    uint16_t rx_ue;     // Receiving UE ID
    uint16_t rnti;      // Radio Network Temporary Identifier
    bool crc_indication;  // CRC indication flag
} rrc_pdu_t;

// Define the dynamic list of RRC indication PDUs
typedef struct {
    rrc_pdu_t *pdu_list;   // List of RRC PDUs
    int pdu_count;  // Number of RRC PDUs in the list
} rrc_pdus_t;

// Function to add a new RRC indication PDU to the list
void add_rrc_pdu(rrc_pdus_t *pdus, uint16_t rx_ue, uint16_t rnti, bool crc_indication) {
    // Check if the list is full
    if (pdus->pdu_count == pdus->capacity) {
        // Double the capacity of the list
        int new_capacity = pdus->capacity * 2;
        rrc_pdu_t *new_list = realloc(pdus->pdu_list, new_capacity * sizeof(rrc_pdu_t));
        if (new_list == NULL) {
            printf("Error: Failed to allocate memory for RRC PDU list\n");
            return;
        }
        pdus->pdu_list = new_list;
        pdus->capacity = new_capacity;
    }

    // Add the new RRC indication PDU to the list
    pdus->pdu_list[pdus->pdu_count].rx_ue = rx_ue;
    pdus->pdu_list[pdus->pdu_count].rnti = rnti;
    pdus->pdu_list[pdus->pdu_count].crc_indication = crc_indication;
    pdus->pdu_count++;
}

// Function to remove an RRC indication PDU from the list
void remove_rrc_pdu(rrc_pdus_t *pdus, uint16_t rx_ue, uint16_t rnti) {
    // Find the index of the RRC PDU to be removed
    int index = -1;
    for (int i = 0; i < pdus->pdu_count; i++) {
        if (pdus->pdu_list[i].rx_ue == rx_ue && pdus->pdu_list[i].rnti == rnti) {
            index = i;
            break;
        }
    }

    // Remove the RRC PDU from the list
    if (index != -1) {
        pdus->pdu_count--;
        for (int i = index; i < pdus->pdu_count; i++) {
            pdus->pdu_list[i] = pdus->pdu_list[i+1];
        }
    }
}

// Function to clear all RRC indication PDUs from the list
void clear_rrc_pdus(rrc_pdus_t *pdus) {
    pdus->pdu_count = 0;
}
