// Custom allocator for linked list nodes
struct node {
    char* data;
    struct node* next;
};

// Function to read and process dynamically allocated string list from stdin
void process_input(int argc, char** argv) {
    // Initialize linked list head pointer
    struct node* head = NULL;

    // Read strings from stdin and allocate memory for each one
    while (fgets(buf, sizeof(buf), stdin)) {
        // Allocate memory for new node
        struct node* new_node = malloc(sizeof(struct node));

        // Check for allocation failure
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        // Copy string data into node
        strcpy(new_node->data, buf);

        // Compute SHA-256 hash of string
        unsigned char* hash = sha256(buf, strlen(buf), NULL);

        // Print hash and corresponding index
        printf("Hash: %s\n", hash);
        free(hash);

        // Add node to linked list
        if (!head) {
            head = new_node;
        } else {
            struct node* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    // Free linked list nodes
    struct node* current = head;
    while (current) {
        free(current->data);
        struct node* next = current->next;
        free(current);
        current = next;
    }
}
