// Structure to represent a record
typedef struct {
    int value;
    char *key;
} Record;

// Global variables
static int capacity = 100; // Initial capacity of the collection
static int size = 0; // Current size of the collection
static pthread_mutex_t lock; // Mutex for synchronizing access to the collection
static Record *records; // Array of records
static bool isResizing = false; // Flag to indicate if we are resizing the array
static int resizeThreshold = 75; // Threshold at which we should resize the array
static int garbageCollectionInterval = 100; // Interval between garbage collection runs
static int serializationFormat = 1; // Serialization format for persisting data
static char *serializedData; // Serialized representation of the data

// Function to add a new record to the collection
void addRecord(int value, char *key) {
    pthread_mutex_lock(&lock);
    if (size == capacity && !isResizing) {
        resizeArray();
    }
    records[size].value = value;
    records[size].key = key;
    size++;
    pthread_mutex_unlock(&lock);
}

// Function to get a record from the collection by key
Record *getRecord(char *key) {
    for (int i = 0; i < size; i++) {
        if (strcmp(records[i].key, key) == 0) {
            return &records[i];
        }
    }
    return NULL;
}

// Function to remove a record from the collection by key
void removeRecord(char *key) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < size; i++) {
        if (strcmp(records[i].key, key) == 0) {
            records[i] = records[size - 1];
            size--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

// Function to resize the array when it reaches capacity
void resizeArray() {
    isResizing = true;
    int newCapacity = capacity * 2;
    Record *newRecords = (Record *)malloc(sizeof(Record) * newCapacity);
    for (int i = 0; i < size; i++) {
        newRecords[i] = records[i];
    }
    free(records);
    records = newRecords;
    capacity = newCapacity;
    isResizing = false;
}

// Function to perform periodic garbage collection
void garbageCollection() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < size; i++) {
        if (!records[i].key) { // If the record is obsolete, remove it
            records[i] = records[size - 1];
            size--;
        }
    }
    pthread_mutex_unlock(&lock);
}

// Function to serialize the data structure
void serialize() {
    serializedData = (char *)malloc(sizeof(char) * 1000); // Allocate enough space for the serialized data
    int pos = 0;
    for (int i = 0; i < size; i++) {
        Record record = records[i];
        char keyBuffer[100];
        sprintf(keyBuffer, "%s", record.key);
        char valueBuffer[100];
        sprintf(valueBuffer, "%d", record.value);
        int keyLen = strlen(keyBuffer);
        int valueLen = strlen(valueBuffer);
        serializedData[pos++] = (char)serializationFormat; // Write the serialization format to the first byte of the buffer
        memcpy(serializedData + pos, keyBuffer, keyLen); // Write the key to the buffer
        pos += keyLen;
        memcpy(serializedData + pos, valueBuffer, valueLen); // Write the value to the buffer
        pos += valueLen;
    }
}

// Function to deserialize the data structure
void deserialize() {
    int pos = 0;
    while (pos < strlen(serializedData)) {
        int serializationFormat = (int)serializedData[pos++]; // Read the serialization format from the buffer
        if (serializationFormat == 1) { // If the serialization format is 1, read a key and value
            char keyBuffer[100];
            pos += read(serializedData + pos, keyBuffer, sizeof(keyBuffer)); // Read the key from the buffer
            int value = (int)serializedData[pos++]; // Read the value from the buffer
            addRecord(value, keyBuffer); // Add the record to the collection
        } else { // If the serialization format is not 1, read a value and key
            char valueBuffer[100];
            pos += read(serializedData + pos, valueBuffer, sizeof(valueBuffer)); // Read the value from the buffer
            char keyBuffer[100];
            pos += read(serializedData + pos, keyBuffer, sizeof(keyBuffer)); // Read the key from the buffer
            int value = (int)serializedData[pos++]; // Read the value from the buffer
            addRecord(value, keyBuffer); // Add the record to the collection
        }
    }
}

// Function to integrate with an external data source for updates
void updateFromDataSource() {
    char *data = getExternalData(); // Get the latest data from the external data source
    if (data) { // If there is data, deserialize it and add the records to the collection
        deserialize(data);
        free(data);
    }
}
```
