// Function to create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_populate_crc_indication_pdu(int M) {
    // Check if the input parameter M is valid
    if (M <= 0) {
        fprintf(stderr, "Invalid input parameter: M must be positive\n");
        return NULL;
    }

    // Allocate memory for the linked list and initialize it to NULL
    NFAPI_CRC_INDICATION_PDU_T* head = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (head == NULL) {
        fprintf(stderr, "Failed to allocate memory for the linked list\n");
        return NULL;
    }

    // Initialize the head node with a random RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
    srand(time(NULL));
    int rx_ue_information_tag = rand() % 10;
    int crc_indication_rel8_tag = rand() % 10;
    head->rx_ue_information_tag = rx_ue_information_tag;
    head->crc_indication_rel8_tag = crc_indication_rel8_tag;

    // Allocate memory for the linked list and initialize it to NULL
    NFAPI_CRC_INDICATION_PDU_T* current = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (current == NULL) {
        fprintf(stderr, "Failed to allocate memory for the linked list\n");
        return NULL;
    }

    // Set the head node as the current node and iterate through M elements
    NFAPI_CRC_INDICATION_PDU_T* previous = head;
    for (int i = 0; i < M; i++) {
        // Generate a random RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG for the current node
        rx_ue_information_tag = rand() % 10;
        crc_indication_rel8_tag = rand() % 10;

