        current->rx_ue_information_tag = rx_ue_information_tag;
        current->crc_indication_rel8_tag = crc_indication_rel8_tag;

        // Set the previous node as the head node and update the previous node to the current node
        previous->next = current;
        previous = current;
    }

    // Sort the linked list based on RNTI values in ascending order
    sort_crc_indication_pdu(head);

    // Manage a theme cache for a mobile application
    THEME_CACHE* theme_cache = malloc(sizeof(THEME_CACHE));
    if (theme_cache == NULL) {
        fprintf(stderr, "Failed to allocate memory for the theme cache\n");
        return NULL;
    }

    // Check if a default theme directory is configured
    bool has_default_theme = false;
    if (!has_default_theme) {
        // Initialize the default theme directory with a predefined default value
        strcpy(theme_cache->default_theme_directory, "./themes/default");
    }

    // Parse a PNG file from the cache root directory and store it in the theme cache
    char* png_file = get_png_file_from_cache();
    if (png_file == NULL) {
        fprintf(stderr, "Failed to parse a PNG file from the cache root directory\n");
        return NULL;
    }
    theme_cache->png_file = png_file;

    // Return the head node of the linked list and the theme cache
    return head;
}

// Function to sort a linked list of NFAPI_CRC_INDICATION_PDU_T structures based on RNTI values in ascending order
void sort_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* head) {
    // Check if the linked list is empty or has only one element
    if (head == NULL || head->next == NULL) {
        return;
    }

    // Initialize a temporary node to traverse the linked list
    NFAPI_CRC_INDICATION_PDU_T* current = head;

    // Iterate through the linked list and sort it based on RNTI values in ascending order
    while (current->next != NULL) {
        if (current->rnti < current->next->rnti) {
            // Swap the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG of the current node with the next node
            int tmp = current->rx_ue_information_tag;
            current->rx_ue_information_tag = current->next->rx_ue_information_tag;
            current->next->rx_ue_information_tag = tmp;

            tmp = current->crc_indication_rel8_tag;
            current->crc_indication_rel8_tag = current->next->crc_indication_rel8_tag;
            current->next->crc_indication_rel8_tag = tmp;

            // Swap the next node with the previous node
            NFAPI_CRC_INDICATION_PDU_T* temp = current->next;
            current->next = current->next->next;
            temp->next = current;
        } else {
            current = current->next;
        }
    }
}

