        log_entry->records = malloc(sizeof(struct record));
        if (log_entry->records == NULL) {
            return -1; // memory allocation failed
        }
        log_entry->records->next = NULL;
    }
    struct record* new_record = (struct record*)malloc(sizeof(struct record));
    if (new_record == NULL) {
        return -1; // memory allocation failed
    }
    memcpy(new_record, record, sizeof(struct record));
    log_entry->records->next = new_record;
    return 0; // success
}

void free_record(struct record* record) {
