// define the function to resolve the hostname to IP address
int resolve_hostname(const char *hostname, char **ip_address) {
    // get the hostent structure for the given hostname
    struct hostent *host = gethostbyname(hostname);

    // check if the hostent structure is NULL
    if (host == NULL) {
        printf("Failed to resolve hostname: %s\n", hostname);
        return -1;
    }

    // get the first IP address from the hostent structure
    char *ip = inet_ntoa(*(struct in_addr *)host->h_addr_list[0]);

    // allocate memory for the IP address string
    int ip_len = strlen(ip) + 1;
    char *ip_address_str = malloc(sizeof(char) * ip_len);

    // copy the IP address to the allocated memory
    memcpy(ip_address_str, ip, ip_len);

    // return the pointer to the IP address string
    *ip_address = ip_address_str;

    return 0;
