int handle_oauth_client(struct OAUTH_CLIENT *client) {
    // check if the access token is expired or about to expire
    time_t current_time = time(NULL);
    if (current_time > (client->access_token_len + client->refresh_token_len)) {
        printf("Access token is expired or about to expire. Refreshing...\n");

        // refresh the access token using the refresh token
        CURL *curl = curl_easy_init();
        if (curl) {
            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Authorization: Basic Y2xpZW50X3Nlc3Npb246");
            headers = curl_slist_append(headers, "Content-Type: application/x-www-form-urlencoded");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
            curl_easy_setopt(curl, CURLOPT_URL, "https://accounts.google.com/o/oauth2/token");
            char data[1024];
