            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);
            CURLcode res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                printf("Failed to refresh access token: %s\n", curl_easy_strerror(res));
                return -1;
            }

            // get the response from the server
