    if ((errcode = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        printf("Error resolving hostname: %s\n", gai_strerror(errcode));
        return NULL;
    }

    // Iterate through the results and find the first valid IPv4 or IPv6 address
    struct addrinfo *ptr = res;
    while (ptr != NULL) {
        if (ptr->ai_family == AF_INET || ptr->ai_family == AF_INET6) {
            break;
        }
        ptr = ptr->ai_next;
    }

    // Allocate memory for the IP address string
    char *ip_address = (char *)malloc(INET_ADDRSTRLEN);
    if (ip_address == NULL) {
        printf("Error allocating memory for IP address\n");
        return NULL;
    }

    // Convert the raw IP address to a human-readable string
    inet_ntop(ptr->ai_family, ptr->ai_addr->sa_data, ip_address, INET_ADDRSTRLEN);

