void updateGPA(StudentRecord *student, LinkedListNode *course_list) {
    float gpa = 0;
    int num_courses = 0;
    while (course_list != NULL) {
        gpa += course_list->course_record->grade;
        num_courses++;
        course_list = course_list->next;
    }
    student->gpa = gpa / num_courses;
}

