    }
    fclose(fp);
}

// Define the function to handle concurrent access from multiple threads
void synchronizeAccess(StudentRecord **student_records, int student_count) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    for (int i = 0; i < student_count; i++) {
        StudentRecord *current_student = student_records[i];
        LinkedListNode *course_list = current_student->course_record;
        while (course_list != NULL) {
            pthread_mutex_lock(&mutex);
            updateGPA(current_student, course_list);
            pthread_mutex_unlock(&mutex);
            course_list = course_list->next;
