void insert_log_entry(data_entry* data, log_entry* entry) {
    // Check if there is enough space in the array for the new entry
    if (data->next >= data->count) {
        // If not, resize the array to accommodate additional entries
        size_t new_count = data->count * 2;
        data_entry* new_data = realloc(data, sizeof(data_entry) * new_count);
        if (new_data == NULL) {
            // If reallocation fails, abort the operation
            return;
        }
        data = new_data;
    }

    // Add the new entry to the end of the linked list for this data entry
    data->next->next = malloc(sizeof(log_entry));
    data->next->timestamp = entry->timestamp;
    data->next->value = entry->value;
