// Struct for holding record data
typedef struct {
    int key;
} Record;

// Function to allocate memory for an array of records and initialize it with random values
void init_records(Record* records, size_t num_records) {
    // Initialize the array of records with random values
    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = rand() % MAX_KEY_VALUE + MIN_KEY_VALUE;
    }
}

// Function to sort the records based on their keys using a stable sorting algorithm
void sort_records(Record* records, size_t num_records) {
    // Use a stable sorting algorithm, such as insertion sort or merge sort
    for (size_t i = 0; i < num_records - 1; ++i) {
        Record temp = records[i];
        size_t j = i + 1;
        while (j > 0 && temp.key > records[j].key) {
            records[j - 1] = records[j];
            --j;
        }
        records[j] = temp;
    }
}

// Function to serialize the sorted records into a file
void serialize_records(const Record* records, size_t num_records, const char* filename) {
    // Open the output file in binary mode for writing
    FILE* outfile = fopen(filename, "wb");
    if (outfile == NULL) {
        fprintf(stderr, "Failed to open output file\n");
        return;
    }

    // Write the records to the output file in a binary format
    for (size_t i = 0; i < num_records; ++i) {
        fwrite(&records[i].key, sizeof(int), 1, outfile);
    }

    // Close the output file
    fclose(outfile);
}
