    struct user_session* head;
};

void initialize_linked_list(struct linked_list* list) {
    list->size = 0;
    list->head = NULL;
}

void add_user_session(struct linked_list* list, const char* username, time_t timestamp) {
    struct user_session* new_node = (struct user_session*) malloc(sizeof(struct user_session));
    if (!new_node) {
        // handle memory allocation failure gracefully
        return;
    }
    new_node->username = strdup(username);
    new_node->timestamp = timestamp;
    new_node->next = NULL;
    list->size++;
    if (list->head == NULL) {
        list->head = new_node;
        return;
    }
    struct user_session* node = list->head;
    while (node->next != NULL) {
        node = node->next;
    }
    node->next = new_node;
}

void free_linked_list(struct linked_list* list) {
    struct user_session* node = list->head;
    while (node != NULL) {
        struct user_session* next = node->next;
        free(node->username);
        free(node);
        node = next;
    }
}
```
