        // Destructor
        ~ThreadPoolManager();

        // Submit a task for execution
        void submitTask(Task* task);

        // Retrieve the status of a task
        TaskStatus getTaskStatus(string taskId) const;

        // Stop the thread pool manager
        void stop();
    };

    // Task class
