    records_count++;
}

// Free memory for a given record
void free_record(int index) {
    // Check if the record exists in the array
    if (index < 0 || index >= records_count) {
        fprintf(stderr, "Error: invalid index given to free_record\n");
        return;
    }

    // Free the memory allocated for the record structure
    free(records[index]);

    // Remove the record from the array
