    // Loop until all records have been allocated
    while (records_count < 10000) {
        // Try to allocate a new record with the given range
        allocate_record(range);

        // Check if memory allocation failed and retry up to three times
        int retries = 3;
        while (total_memory > 4 * 1024 * 1024 && retries--) {
            // Clear all allocated records when the total memory usage is above 4 MB
            clear_all_records();

            // Try to allocate a new record again with the given range
            allocate_record(range);
        }

        // Check if memory allocation failed and handle the error gracefully
        if (total_memory > 4 * 1024 * 1024) {
            fprintf(stderr, "Error: failed to allocate memory for a new record after %d retries\n", retries);
