	}
	// Close the file
	fclose(f);
}

// Helper function for sorting the records using a stable sorting algorithm
void quicksort(record *records, int low, int high) {
	if (low < high) {
		int partitionPoint = partition(records, low, high);
		quicksort(records, low, partitionPoint - 1);
		quicksort(records, partitionPoint + 1, high);
	}
}

// Helper function for finding the partition point in a list of records
int partition(record *records, int low, int high) {
	int pivot = records[high].value;
	int i = low - 1;
	for (int j = low; j < high; j++) {
		if (records[j].value <= pivot) {
			i++;
			swap(records, i, j);
		}
	}
	swap(records, i + 1, high);
	return i + 1;
}

// Helper function for swapping two elements in an array
void swap(record *records, int i, int j) {
	record temp = records[i];
	records[i] = records[j];
	records[j] = temp;
}']

