// Function to dynamically allocate memory for weather data
weatherData* createWeatherData(int size) {
    // Allocate memory for the array of weather data structures
    weatherData *data = (weatherData*)malloc(size * sizeof(weatherData));
    if (!data) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    // Initialize each structure with a random description string and zero temperature
    for (int i = 0; i < size; ++i) {
        weatherData *current = &data[i];
        current->timestamp = 0;
        current->temperature = 0.0;
        current->description = (char*)malloc(100); // Generate a random description string of fixed length
        if (!current->description) {
            printf("Memory allocation failed!\n");
            return NULL;
        }
        for (int j = 0; j < 100; ++j) {
            current->description[j] = (rand() % 26) + 'A'; // Generate a random uppercase letter between A and Z
        }
    }

    return data;
}

// Function to add new weather data to the array
void addWeatherData(weatherData *data, long timestamp, double temperature) {
    // Find the first empty slot in the array
    int i = 0;
    while (i < size && data[i].timestamp != 0) {
        ++i;
    }

    // If no slots are available, double the size of the array and try again
    if (i == size) {
        size *= 2;
        data = (weatherData*)realloc(data, size * sizeof(weatherData));
        addWeatherData(data, timestamp, temperature);
    } else {
