<?php

function processUserRequest($_POST) {
    // Validate required fields
    if (!isset($_POST['name']) || !isset($_POST['email']) || !isset($_POST['password'])) {
        return json_encode(['error' => 'Invalid request']);
    }

    // Enforce constraint that no two users can have the same email address within the specified locale
    if (!isValidEmail($_POST['email'], $_POST['locale'])) {
        return json_encode(['error' => 'Email already in use']);
    }

    // Perform action based on sub_action value
    switch ($_POST['sub_action']) {
        case 'create':
            createUser($_POST);
            break;
        case 'update':
            updateUser($_POST);
            break;
        case 'delete':
            deleteUser($_POST);
            break;
        case 'list':
            listUsers($_POST);
            break;
        default:
            return json_encode(['error' => 'Invalid sub_action']);
    }
}

function validateEmail($email, $locale) {
    // Implement your own email validation logic here
    // This is just a sample implementation
    if (strpos($email, '@') !== false && strpos($email, '.') !== false) {
        return true;
    } else {
        return false;
    }
}

function createUser($_POST) {
    $id = generateUniqueID();
    $name = $_POST['name'];
    $email = $_POST['email'];
    $password = password_hash($_POST['password'], PASSWORD_DEFAULT);

    // Connect to database and execute query
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
        $stmt = $db->prepare("INSERT INTO users (id, name, email, password) VALUES (:id, :name, :email, :password)");
        $stmt->bindValue(':id', $id);
        $stmt->bindValue(':name', $name);
        $stmt->bindValue(':email', $email);
        $stmt->bindValue(':password', $password);
        $stmt->execute();
    } catch (PDOException $e) {
        return json_encode(['error' => 'Database connection error']);
    }

    // Handle JSON response
    $response = [
        'id' => $id,
        'name' => $name,
        'email' => $email,
        'password' => $password
    ];
    return json_encode($response);
}

function updateUser($_POST) {
    // Connect to database and execute query
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
        $stmt = $db->prepare("UPDATE users SET name=:name, email=:email, password=:password WHERE id=:id");
        $stmt->bindValue(':id', $_POST['id']);
        $stmt->bindValue(':name', $_POST['name']);
        $stmt->bindValue(':email', $_POST['email']);
        $stmt->bindValue(':password', password_hash($_POST['password'], PASSWORD_DEFAULT));
        $stmt->execute();
    } catch (PDOException $e) {
        return json_encode(['error' => 'Database connection error']);
    }

    // Handle JSON response
    return json_encode(['message' => 'User updated successfully']);
}

function deleteUser($_POST) {
    // Connect to database and execute query
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
        $stmt = $db->prepare("DELETE FROM users WHERE id=:id");
        $stmt->bindValue(':id', $_POST['id']);
        $stmt->execute();
    } catch (PDOException $e) {
        return json_encode(['error' => 'Database connection error']);
    }

    // Handle JSON response
    return json_encode(['message' => 'User deleted successfully']);
}

function listUsers($_POST) {
    // Connect to database and execute query
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
        $stmt = $db->prepare("SELECT * FROM users WHERE locale=:locale LIMIT 50");
        $stmt->bindValue(':locale', $_POST['locale']);
        $stmt->execute();
        $users = $stmt->fetchAll(PDO::FETCH_ASSOC);
    } catch (PDOException $e) {
        return json_encode(['error' => 'Database connection error']);
    }

    // Handle JSON response
    $response = [];
    foreach ($users as $user) {
        $response[] = [
            'id' => $user['id'],
            'name' => $user['name'],
            'email' => $user['email']
        ];
    }
    return json_encode($response);
}

function generateUniqueID() {
    // Generate a unique ID using a random number and the current time
    $id = rand(10000, 99999) . time();
    return $id;
}
