#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <assert.h>
#include <pthread.h>

// Enumeration for weather conditions
typedef enum { SUNNY, RAINY, CLOUDY } WeatherCondition;

// Structure to store weather data
struct WeatherData {
    WeatherCondition condition;
    long timestamp;
    double temperature;
    char* description;
};

// Hash table for storing weather data
struct WeatherTable {
    struct WeatherData** data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex; // Mutex for synchronizing access to the hash table
};

// B-tree for sorting weather data by timestamp
struct WeatherBTree {
    struct WeatherData** data;
    int* order; // Array of indices into the data array, sorted by timestamp
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex; // Mutex for synchronizing access to the B-tree
};

// Function to initialize a weather table
struct WeatherTable* initWeatherTable() {
    struct WeatherTable* table = (struct WeatherTable*)malloc(sizeof(struct WeatherTable));
    if (!table) {
        printf("Failed to allocate memory for weather table\n");
        exit(1);
    }
    table->data = (struct WeatherData**)calloc(INITIAL_CAPACITY, sizeof(struct WeatherData*));
    if (!table->data) {
        printf("Failed to initialize weather table\n");
        free(table);
        return NULL;
    }
    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

// Function to destroy a weather table
void destroyWeatherTable(struct WeatherTable* table) {
    for (int i = 0; i < table->size; i++) {
        free(table->data[i]);
    }
    free(table->data);
    pthread_mutex_destroy(&table->mutex);
    free(table);
}

// Function to insert a new entry into the weather table
int insertWeatherData(struct WeatherTable* table, struct WeatherData* data) {
    // Acquire mutex for synchronizing access to the hash table
    pthread_mutex_lock(&table->mutex);

    // Check if the table needs to be resized
    if (table->size == table->capacity) {
        size_t newCapacity = table->capacity * 2;
        struct WeatherData** newData = (struct WeatherData**)calloc(newCapacity, sizeof(struct WeatherData*));
        if (!newData) {
            printf("Failed to resize weather table\n");
            pthread_mutex_unlock(&table->mutex);
            return 1;
        }
        for (int i = 0; i < table->size; i++) {
            newData[i] = table->data[i];
        }
        free(table->data);
        table->data = newData;
        table->capacity = newCapacity;
    }

    // Insert the new entry into the hash table
    int index = data->timestamp % table->capacity;
    while (table->data[index]) {
        if (table->data[index]->timestamp == data->timestamp) {
            printf("Duplicate timestamp in weather table\n");
            pthread_mutex_unlock(&table->mutex);
            return 1;
        }
        index = (index + 1) % table->capacity;
    }
    table->data[index] = data;
    table->size++;

    // Release mutex for synchronizing access to the hash table
    pthread_mutex_unlock(&table->mutex);

    return 0;
}

// Function to retrieve a specific entry from the weather table
struct WeatherData* getWeatherData(struct WeatherTable* table, long timestamp) {
    // Acquire mutex for synchronizing access to the hash table
    pthread_mutex_lock(&table->mutex);

    int index = timestamp % table->capacity;
    while (index != 0 && !table->data[index]) {
        index = (index + 1) % table->capacity;
    }
    if (!table->data[index]) {
        pthread_mutex_unlock(&table->mutex);
        return NULL;
    }
    struct WeatherData* data = table->data[index];
    pthread_mutex_unlock(&table->mutex);

    return data;
}

// Function to retrieve all entries from the weather table that match a specific timestamp
struct WeatherData* getWeatherDataRange(struct WeatherTable* table, long startTime, long endTime) {
    // Acquire mutex for synchronizing access to the hash table
    pthread_mutex_lock(&table->mutex);

    struct WeatherData** data = (struct WeatherData**)calloc(endTime - startTime + 1, sizeof(struct WeatherData*));
    int index = startTime % table->capacity;
    while (index != 0 && !table->data[index]) {
        index = (index + 1) % table->capacity;
    }
    for (int i = 0; i < endTime - startTime + 1; i++) {
        if (table->data[index]) {
            data[i] = table->data[index];
        }
        index = (index + 1) % table->capacity;
    }

    // Release mutex for synchronizing access to the hash table
    pthread_mutex_unlock(&table->mutex);

    return data;
}

// Function to sort weather data by timestamp in ascending order
void sortWeatherDataByTimestampAsc(struct WeatherBTree* btree) {
    // Acquire mutex for synchronizing access to the B-tree
    pthread_mutex_lock(&btree->mutex);

    int* newOrder = (int*)malloc(btree->size * sizeof(int));
    for (int i = 0; i < btree->size; i++) {
        newOrder[i] = i;
    }
    qsort(newOrder, btree->size, sizeof(int), compareWeatherDataByTimestampAsc);
    for (int i = 0; i < btree->size; i++) {
        int oldIndex = btree->order[i];
        int newIndex = newOrder[i];
        struct WeatherData* data = btree->data[oldIndex];
        free(btree->data[oldIndex]);
        btree->data[newIndex] = data;
    }
    free(btree->order);
    btree->order = newOrder;

    // Release mutex for synchronizing access to the B-tree
    pthread_mutex_unlock(&btree->mutex);
}

// Function to sort weather data by timestamp in descending order
