// Define a struct to represent a single entry of weather data
typedef struct {
    long timestamp;     // Timestamp for the temperature reading (in seconds)
    double temperature; // Temperature reading in degrees Celsius
    char* description;  // Randomly generated description of fixed length
} WeatherEntry;

// Define a dynamic array to store weather data entries
typedef struct {
    int capacity;      // Maximum number of entries that can be stored
    int size;          // Current number of entries in the array
    WeatherEntry* data;  // Pointer to the array of weather data entries
} WeatherData;

// Prototype for the function to manage weather data
int manage_weather_data(WeatherData* data, long timestamp, double temperature, char* description);

// Implementation of the manage_weather_data function
int manage_weather_data(WeatherData* data, long timestamp, double temperature, char* description) {
    // Check if the weather data structure is null or has reached its capacity
    if (data == NULL || data->size >= data->capacity) {
        return -1;
    }

    // Allocate memory for a new weather entry
    WeatherEntry* new_entry = malloc(sizeof(WeatherEntry));
    if (new_entry == NULL) {
        printf("Error: Failed to allocate memory for the new weather entry\n");
        return -1;
    }

    // Set the timestamp, temperature, and description for the new entry
    new_entry->timestamp = timestamp;
    new_entry->temperature = temperature;
    new_entry->description = strdup(description);

    // Add the new entry to the end of the weather data structure
    if (data->size == 0) {
        data->data = new_entry;
    } else {
        data->data[data->size - 1]->next = new_entry;
    }

    // Increment the size of the weather data structure
    data->size++;

    return 0;
}

// Function to configure the maximum number of entries in the weather data structure
void set_weather_data_capacity(WeatherData* data, int capacity) {
    if (data == NULL || capacity <= 0) {
        printf("Error: Invalid argument\n");
        return;
    }

    // Allocate memory for the new capacity of weather data entries
    WeatherEntry* new_data = malloc(capacity * sizeof(WeatherEntry));
    if (new_data == NULL) {
        printf("Error: Failed to allocate memory for the new weather data\n");
        return;
    }

    // Copy over the existing weather data entries
    int i;
    for (i = 0; i < data->size && i < capacity; i++) {
        new_data[i] = data->data[i];
    }

    // Free the old weather data structure
    free(data->data);

    // Set the new weather data structure
    data->capacity = capacity;
    data->size = i;
    data->data = new_data;
}

// Function to retrieve the current size of the weather data structure
int get_weather_data_size(WeatherData* data) {
    if (data == NULL) {
        printf("Error: Invalid argument\n");
        return -1;
    }

    return data->size;
}

// Function to retrieve a weather entry from the weather data structure by index
WeatherEntry* get_weather_entry(WeatherData* data, int index) {
    if (data == NULL || index < 0 || index >= data->size) {
        printf("Error: Invalid argument\n");
        return NULL;
    }

    return &data->data[index];
}

// Function to delete a weather entry from the weather data structure by index
int delete_weather_entry(WeatherData* data, int index) {
    if (data == NULL || index < 0 || index >= data->size) {
        printf("Error: Invalid argument\n");
        return -1;
    }

    // Shift all entries after the deleted entry one position to the left
    for (int i = index + 1; i < data->size; i++) {
        data->data[i - 1] = data->data[i];
    }

    // Decrement the size of the weather data structure by one
    data->size--;

    return 0;
}
