// Define a struct to represent an NFAPI_CRC_INDICATION_PDU_T
struct nfapi_crc_indication_pdu {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
};

// Define a disjoint-set data structure to maintain RNTI assignments
typedef struct {
    int *parents;
    int *ranks;
    int capacity;
} rnti_set_t;

// Initialize the disjoint-set data structure with a given capacity
void rnti_set_init(rnti_set_t *set, int capacity) {
    set->parents = malloc(capacity * sizeof(int));
    set->ranks = malloc(capacity * sizeof(int));
    for (int i = 0; i < capacity; i++) {
        set->parents[i] = -1;
        set->ranks[i] = 0;
    }
    set->capacity = capacity;
}

// Find the representative element of a given RNTI value in the disjoint-set data structure
int rnti_set_find(rnti_set_t *set, int rnti) {
    if (rnti < 0 || rnti >= set->capacity) {
        return -1;
    }
    if (set->parents[rnti] == -1) {
        return rnti;
    }
    int root = rnti_set_find(set, set->parents[rnti]);
    if (root != -1) {
        set->parents[rnti] = root;
    }
    return root;
}

// Union two RNTI values in the disjoint-set data structure
void rnti_set_union(rnti_set_t *set, int rnti1, int rnti2) {
    if (rnti1 < 0 || rnti2 < 0 || rnti1 >= set->capacity || rnti2 >= set->capacity) {
        return;
    }
    int root1 = rnti_set_find(set, rnti1);
    int root2 = rnti_set_find(set, rnti2);
    if (root1 == -1 || root2 == -1) {
        return;
    }
    if (root1 != root2) {
        if (set->ranks[root1] > set->ranks[root2]) {
            set->parents[root2] = root1;
            set->ranks[root2] = set->ranks[root1];
        } else {
            set->parents[root1] = root2;
            set->ranks[root1] = set->ranks[root2];
        }
    }
}

// Allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures and populate it with random RNTIs
NFAPI_CRC_INDICATION_PDU_T *generateNfarelations(int n, int *nUniqueRnti) {
    if (n < 0 || n > 10000) {
        return NULL;
    }

    // Initialize a disjoint-set data structure with the capacity of the input parameter 'n'
    rnti_set_t set;
    rnti_set_init(&set, n);

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Populate the array with random RNTIs and CRCFLAG values
    for (int i = 0; i < n; i++) {
        // Generate a random RNTI value between 1 and the input parameter 'n'
        int rnti = rand() % n + 1;

        // Ensure that the RNTI value is disjoint with other RNTIs in the set
        while (rnti_set_find(&set, rnti) != -1) {
            rnti++;
        }

        array[i].rx_ue_information_tag = 0;
        array[i].rnti = rnti;
        array[i].crc_indication_rel8_tag.crflag = rand() % 2;

        // Add the RNTI value to the disjoint-set data structure
        rnti_set_union(&set, rnti, -1);
    }

    // Log the total number of unique RNTIs assigned and return the populated array
    *nUniqueRnti = rnti_set_size(&set);
    printf("Total number of unique RNTIs: %d\n", *nUniqueRnti);
    return array;
}
```
The `generateNfarelations` function takes an integer parameter `n` representing the number of structures to be populated, and returns a dynamically allocated array of `NFAPI_CRC_INDICATION_PDU_T` structures. The function initializes a disjoint-set data structure with the capacity equal to the input parameter 'n', and uses it to ensure that no two structures share the same RNTI value. It then populates the array with random RNTIs and CRCFLAG values, and logs the total number of unique RNTIs assigned.

