    size_t capacity;
    size_t count;
    struct sensor_data* data;
};

void init_data_array(struct data_array* array, size_t initial_capacity) {
    array->capacity = initial_capacity;
    array->count = 0;
    array->data = malloc(sizeof(struct sensor_data) * initial_capacity);
}

void add_to_data_array(struct data_array* array, struct sensor_data data) {
    if (array->count == array->capacity) {
        // Resize the data array
        array->data = realloc(array->data, sizeof(struct sensor_data) * (array->capacity * 2));
        array->capacity *= 2;
    }
    array->data[array->count++] = data;
}

