    size_t count;
    struct sensor_data* data;
};

void init_data_queue(struct data_queue* queue, size_t initial_capacity) {
    queue->capacity = initial_capacity;
    queue->count = 0;
    queue->data = malloc(sizeof(struct sensor_data) * initial_capacity);
}

void enqueue_sensor_data(struct data_queue* queue, struct sensor_data data) {
    if (queue->count == queue->capacity) {
        // Resize the data array
        queue->data = realloc(queue->data, sizeof(struct sensor_data) * (queue->capacity * 2));
        queue->capacity *= 2;
    }
    queue->data[queue->count++] = data;
}

void process_sensor_data(struct data_queue* queue, struct data_array* array) {
    // Lock the queue
    pthread_mutex_lock(&queue->lock);

    while (!is_queue_empty(queue)) {
        struct sensor_data data = dequeue(queue);
        add_to_data_array(array, data);
