    if (d == NULL) {
      perror("Error allocating memory for device");
      return NULL;
    }

    // Initialize the device structure with the parsed data
    d->id = id;
    d->version = version;
    d->num_protocols = 0;
    d->protocols = NULL;

    // Read the supported wireless protocols for the device
