      struct WirelessProtocol *p = malloc(sizeof(struct WirelessProtocol));
      if (p == NULL) {
        perror("Error allocating memory for wireless protocol");
        free(d);
        return NULL;
      }

      // Initialize the wireless protocol structure with the parsed data
      p->name = name;
      p->version = version;

      // Add the wireless protocol to the device structure
      d->num_protocols++;
      d->protocols = realloc(d->protocols, sizeof(struct WirelessProtocol *) * d->num_protocols);
      if (d->protocols == NULL) {
        perror("Error reallocating memory for wireless protocol");
        free(p);
        return NULL;
      }
      d->protocols[d->num_protocols - 1] = p;
    }

    // Add the device to the list of devices
    num_devices++;
    pthread_mutex_lock(&mutex);
    struct Device **devices = realloc(devices, sizeof(struct Device *) * num_devices);
    if (devices == NULL) {
      perror("Error reallocating memory for device");
      free(d);
      return NULL;
    }
    devices[num_devices - 1] = d;
    pthread_mutex_unlock(&mutex);
  }

  // Close the configuration file
  fclose(config);

  // Return the device structure
  return d;
}

