    if (num_records > SIZE_MAX / sizeof(struct record) || min > SIZE_MAX || max > SIZE_MAX) {
        fprintf(stderr, "Number of records or range values exceeds system limit\n");
        exit(1);
    }

    // Set random value for each record
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        int val = rand() % (max - min + 1) + min;
        records[i].key = val;
    }
}

// Sort the records based on their int values using a stable sorting algorithm
void sort_records(struct record* records, size_t num_records) {
    // Validate user input to prevent buffer overflows
    if (num_records <= 0) {
        fprintf(stderr, "Invalid number of records provided\n");
        exit(1);
    }

    // Ensure that the input size does not exceed system-defined limits to avoid resource exhaustion
    if (num_records > SIZE_MAX / sizeof(struct record)) {
        fprintf(stderr, "Number of records exceeds system limit\n");
        exit(1);
    }

    // Sort the records using a stable sorting algorithm
    qsort(records, num_records, sizeof(struct record), compare_records);
}

// Serialize the sorted records into a file
void serialize_records(struct record* records, size_t num_records, const char* filename) {
    // Validate user input to prevent buffer overflows
    if (num_records <= 0 || !filename) {
        fprintf(stderr, "Invalid number of records or filename provided\n");
        exit(1);
    }

    // Ensure that the input size does not exceed system-defined limits to avoid resource exhaustion
    if (num_records > SIZE_MAX / sizeof(struct record) || strlen(filename) > PATH_MAX) {
        fprintf(stderr, "Number of records or filename exceeds system limit\n");
        exit(1);
    }

    // Open the file in binary write mode
    FILE* fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open output file\n");
        exit(1);
    }

    // Write the records to the file
    size_t num_written = 0;
    for (size_t i = 0; i < num_records; ++i) {
