        if (fwrite(record, sizeof(struct record), 1, fp) != 1) {
            fprintf(stderr, "Failed to write record %zu to file\n", i);
            exit(1);
        }
        num_written++;
    }

    // Close the file and check for errors
    if (fclose(fp)) {
        fprintf(stderr, "Failed to close output file\n");
        exit(1);
    }
}

// Deserialize the sorted records from a file
void deserialize_records(struct record* records, size_t num_records, const char* filename) {
    // Validate user input to prevent buffer overflows
    if (num_records <= 0 || !filename) {
        fprintf(stderr, "Invalid number of records or filename provided\n");
        exit(1);
    }

    // Ensure that the input size does not exceed system-defined limits to avoid resource exhaustion
    if (num_records > SIZE_MAX / sizeof(struct record) || strlen(filename) > PATH_MAX) {
        fprintf(stderr, "Number of records or filename exceeds system limit\n");
        exit(1);
    }

    // Open the file in binary read mode
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        fprintf(stderr, "Failed to open input file\n");
        exit(1);
    }

