// Implement a custom memory pool for managing records
void mem_pool_init(struct mem_pool* pool) {
    // Allocate memory for the record array
    pool->records = malloc(sizeof(struct record) * pool->capacity);
    if (!pool->records) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        exit(1);
    }
}

void mem_pool_destroy(struct mem_pool* pool) {
    // Free the record array
    free(pool->records);
}

// Allocate a new record from the memory pool
struct record* mem_pool_alloc(struct mem_pool* pool) {
    if (pool->used == pool->capacity) {
        fprintf(stderr, "Memory pool is full\n");
        exit(1);
    }

    struct record* record = &pool->records[pool->used++];
    return record;
}

// Compare two records based on their int values
int compare_records(const void* a, const void* b) {
    const struct record* ra = (const struct record*)a;
    const struct record* rb = (const struct record*)b;
    if (ra->key < rb->key) {
        return -1;
    } else if (ra->key > rb->key) {
        return 1;
    } else {
        return 0;
    }
}
