// Define constants for capacity thresholds, garbage collection intervals, and serialization formats
#define CAPACITY_THRESHOLD 80 // percentage of total memory to be used by the dynamic array
#define GARBAGE_COLLECTION_INTERVAL 10 // number of seconds between garbage collections
#define SERIALIZATION_FORMAT "json" // format for serializing and deserializing records

// Define a struct to represent a record in the dynamic collection
typedef struct {
    int key;
    long offset;
} Record;

// Define a struct to manage the dynamic collection of records
typedef struct {
    int size; // current number of records in the collection
    int capacity; // total capacity of the dynamic array
    pthread_mutex_t mutex; // mutex for protecting concurrent access to the collection
    Record* records; // pointer to the dynamic array of records
} Collection;

// Initialize a new collection with the given capacity and allocate memory for it
Collection* initialize(int capacity) {
    Collection* col = malloc(sizeof(Collection));
    col->size = 0;
    col->capacity = capacity;
    col->records = calloc(col->capacity, sizeof(Record));
    pthread_mutex_init(&col->mutex, NULL);
    return col;
}

// Add a new record to the collection and grow the dynamic array if necessary
void add(Collection* col, int key) {
    // Lock the mutex to protect concurrent access to the collection
    pthread_mutex_lock(&col->mutex);

    // If the current capacity is exceeded, resize the dynamic array
    if (col->size == col->capacity) {
        int new_capacity = col->capacity * 2;
        Record* new_records = calloc(new_capacity, sizeof(Record));
        memcpy(new_records, col->records, col->capacity * sizeof(Record));
        free(col->records);
        col->records = new_records;
        col->capacity = new_capacity;
    }

    // Generate a random offset value for the new record
    long offset = (long)rand() % INT_MAX;

    // Add the new record to the collection
    col->records[col->size].key = key;
    col->records[col->size].offset = offset;
    col->size++;

    // Unlock the mutex
    pthread_mutex_unlock(&col->mutex);
}

// Remove a record from the collection and shrink the dynamic array if necessary
void remove(Collection* col, int key) {
    // Lock the mutex to protect concurrent access to the collection
    pthread_mutex_lock(&col->mutex);

    // Find the index of the record to be removed
    int idx = -1;
    for (int i = 0; i < col->size; i++) {
        if (col->records[i].key == key) {
            idx = i;
            break;
        }
    }

    // If the record was found, remove it from the collection and shrink the dynamic array
    if (idx >= 0) {
        col->size--;
        for (int i = idx; i < col->size; i++) {
            col->records[i].key = col->records[i + 1].key;
            col->records[i].offset = col->records[i + 1].offset;
        }
    }

    // If the current capacity is less than half of the total capacity, shrink the dynamic array
    if (col->size < col->capacity / 2) {
        int new_capacity = col->capacity / 2;
        Record* new_records = calloc(new_capacity, sizeof(Record));
        memcpy(new_records, col->records, col->size * sizeof(Record));
        free(col->records);
        col->records = new_records;
        col->capacity = new_capacity;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&col->mutex);
}

// Update a record in the collection by key
void update(Collection* col, int key) {
    // Lock the mutex to protect concurrent access to the collection
    pthread_mutex_lock(&col->mutex);

    // Find the index of the record to be updated
    int idx = -1;
    for (int i = 0; i < col->size; i++) {
        if (col->records[i].key == key) {
            idx = i;
            break;
        }
    }

    // If the record was found, update its value and unlock the mutex
    if (idx >= 0) {
        col->records[idx].offset = (long)rand() % INT_MAX;
        pthread_mutex_unlock(&col->mutex);
    }
}

// Serialize a collection of records to a file
void serialize(Collection* col, FILE* file) {
    // Lock the mutex to protect concurrent access to the collection
    pthread_mutex_lock(&col->mutex);

    // Write the number of records in the collection to the file
    fwrite(&col->size, sizeof(int), 1, file);

    // Write each record to the file
    for (int i = 0; i < col->size; i++) {
        Record* rec = &col->records[i];
        fwrite(&rec->key, sizeof(int), 1, file);
        fwrite(&rec->offset, sizeof(long), 1, file);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&col->mutex);
}

// Deserialize a collection of records from a file
void deserialize(Collection* col, FILE* file) {
    // Lock the mutex to protect concurrent access to the collection
    pthread_mutex_lock(&col->mutex);

    // Read the number of records in the collection from the file
    int size = 0;
    fread(&size, sizeof(int), 1, file);

    // Resize the dynamic array if necessary
    if (col->capacity < size) {
        col->records = realloc(col->records, size * sizeof(Record));
        col->capacity = size;
    }

    // Read each record from the file and add it to the collection
    for (int i = 0; i < size; i++) {
        Record rec = {0};
        fread(&rec.key, sizeof(int), 1, file);
        fread(&rec.offset, sizeof(long), 1, file);
        col->records[i] = rec;
    }

    // Update the current size of the collection
    col->size = size;

    // Unlock the mutex
    pthread_mutex_unlock(&col->mutex);
}

// Periodically garbage collect obsolete records in the collection
void garbage_collection(Collection* col) {
    // Lock the mutex to protect concurrent access to the collection
    pthread_mutex_lock(&col->mutex);

    // Iterate through each record in the collection and remove obsolete ones
    for (int i = 0; i < col->size; i++) {
        Record* rec = &col->records[i];
        if (rec->offset == -1) {
            remove(col, rec->key);
            i--; // account for the record being removed from the collection
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&col->mutex);
}

// Thread function to perform garbage collection at regular intervals
void* garbage_collector(void* arg) {
    Collection* col = (Collection*)arg;

    while (1) {
        // Sleep for the specified interval before performing garbage collection
        sleep(GARBAGE_COLLECTION_INTERVAL);

        // Perform garbage collection
        garbage_collection(col);
    }
}

// Start a new thread to perform garbage collection at regular intervals
void start_garbage_collector(Collection* col) {
    pthread_t collector;
    pthread_create(&collector, NULL, garbage_collector, (void*)col);
}
