    int key;
};

// Define a function to validate and process configuration entries
void processConfigEntry(const char* line) {
    // Parse the line into a config entry struct
    struct ConfigEntry entry;
    sscanf(line, "%ld %d", &entry.offset, &entry.key);

    // Validate the entry by checking that the offset is not negative and the key is non-zero
    if (entry.offset < 0 || entry.key == 0) {
        fprintf(stderr, "Invalid configuration entry: %s\n", line);
        return;
    }

    // Allocate memory for the parsed offset and key
