    *parsedOffset = entry.offset;
    int* parsedKey = malloc(sizeof(int));
    *parsedKey = entry.key;

    // Add the parsed offset and key to the corresponding arrays
    long* offsets = malloc(sizeof(long) * 1000);
    int* keys = malloc(sizeof(int) * 1000);
    memcpy(&offsets[numOffsets], &parsedOffset, sizeof(long));
    memcpy(&keys[numKeys], &parsedKey, sizeof(int));
    numOffsets++;
    numKeys++;
}

