const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const readFileAsync = promisify(fs.readFile);
const http = require('http');
const semaphore = new Semaphore(10); // Limit concurrency to 10

async function processFiles(directory, fileTypes = ['.json', '.csv'], maxRetries = 3) {
  const files = await fs.readdir(directory);
  const results = {};
  for (const file of files) {
    if (!fileTypes.includes(path.extname(file))) continue; // Filter by file type
    try {
      semaphore.acquire();
      const data = await readFileAsync(path.join(directory, file));
      if (path.extname(file) === '.json') {
        results[file] = JSON.parse(data);
      } else if (path.extname(file) === '.csv') {
        const lines = data.toString().split('\n');
        if (lines[0].indexOf(',') < 0) continue; // Skip files with less than 50% of header columns
        results[file] = lines.slice(1).map((line) => line.split(','));
      }
    } catch (err) {
      if (err.code !== 'ENOENT') console.error(err); // Log error but ignore file not found
      semaphore.release();
      continue; // Retry up to maxRetries times with exponential backoff
    }
    semaphore.release();
  }
  return results;
}

function sendResultsToExternalService(results) {
  const httpRequest = new http.request({
    method: 'POST',
    hostname: 'external-service.com',
    path: '/process',
    headers: {
      'Content-Type': 'application/json',
    },
  });
  httpRequest.write(JSON.stringify(results));
  httpRequest.end();
}

const main = async () => {
  const directory = '/path/to/files';
  const fileTypes = ['.json', '.csv'];
  const results = await processFiles(directory, fileTypes);
  sendResultsToExternalService(results);
};

main();
```
