    Collection* collection = malloc(sizeof(Collection));
    if (collection == NULL) {
        fprintf(stderr, "Failed to allocate memory for collection: %s\n", strerror(errno));
        return NULL;
    }

    // Initialize the collection fields
    collection->records = malloc(sizeof(Record*) * capacity);
    if (collection->records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records: %s\n", strerror(errno));
        free(collection);
        return NULL;
