    Record* record = alloc_record(key, offset);
    if (record == NULL) {
        fprintf(stderr, "Failed to allocate memory for record: %s\n", strerror(errno));
        return;
    }

    // Acquire the lock
    pthread_mutex_lock(&collection->lock);

    // Check if the collection needs to be resized
    if (collection->num_records >= collection->capacity) {
        // Reallocate memory for the records array
        Record** new_records = realloc(collection->records, sizeof(Record*) * (collection->capacity * 2));
        if (new_records == NULL) {
            fprintf(stderr, "Failed to resize records array: %s\n", strerror(errno));
            pthread_mutex_unlock(&collection->lock);
            return;
