    if (!points) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize each data point
    for (size_t i = 0; i < num; ++i) {
        points[i].value = 0.0;
        points[i].str = NULL;
        points[i].len = 0;
    }

