    // Populate each data point with a unique identifier based on its index
    for (size_t i = 0; i < num; ++i) {
        char id[256];
        snprintf(id, sizeof(id), "%ld", i);
        points[i].str = strdup(id);
        points[i].len = strlen(points[i].str);
    }
}

void free_data_points(data_point *points) {
    // Free memory allocated for the array of data points
    for (size_t i = 0; i < num; ++i) {
        if (points[i].str != NULL) {
            free(points[i].str);
        }
    }
    free(points);
}

