// Custom data point structure
typedef struct {
    double value;
    char* identifier;
    size_t length;
} data_point;

// Function to generate a unique identifier for each string
char* generate_identifier(int index) {
    char buffer[32];
    sprintf(buffer, "string-%d", index);
    return strdup(buffer);
}

// Function to decrypt and initialize data streams
void decryptAndInitializeData(unsigned char* key, unsigned char* iv, unsigned char* ciphertext) {
    // Initialize AES-CBC decryption context
    AES_KEY aes_key;
    AES_set_decrypt_key(key, 128, &aes_key);
    AES_cbc_encrypt(ciphertext, ciphertext, strlen((char*)ciphertext), &aes_key, iv, AES_DECRYPT);

    // Initialize double-precision floating point numbers array
    double* double_array = (double*)calloc(100, sizeof(double));
    for (int i = 0; i < 100; i++) {
        double_array[i] = 0.0;
    }

    // Initialize character string array
    char** string_array = (char**)calloc(100, sizeof(char*));
    for (int i = 0; i < 100; i++) {
        string_array[i] = generate_identifier(i);
    }

    // Initialize custom data point array
    data_point* data_points = (data_point*)calloc(100, sizeof(data_point));
    for (int i = 0; i < 100; i++) {
        data_points[i].value = 0.0;
        data_points[i].identifier = string_array[i];
        data_points[i].length = strlen(string_array[i]);
    }

    // Process encrypted ciphertext and populate arrays
    for (int i = 0; i < 100; i++) {
        double value = ((double*)ciphertext)[i];
        double_array[i] = value;
        data_points[i].value = value;
        free(string_array[i]);
    }

    // Free dynamically allocated memory
    free(double_array);
    free(string_array);
    free(data_points);
}
