struct mempool {
    size_t capacity;
    size_t used;
    void** free_blocks;
};

void init_mempool(struct mempool* m, size_t capacity) {
    m->capacity = capacity;
    m->used = 0;
    m->free_blocks = malloc(sizeof(void*) * capacity);
}

void* mempool_malloc(struct mempool* m) {
    if (m->used == m->capacity) {
        return NULL;
    }

    void* block = m->free_blocks[m->used++];
    return block;
}

void mempool_free(struct mempool* m, void* block) {
    if (m->used == 0) {
        free(block);
        return;
    }

    m->free_blocks[--m->used] = block;
}

