    int* keys = malloc(sizeof(int) * num_records);
    long** values = malloc(sizeof(long*) * num_records);
    struct mempool* m = malloc(sizeof(struct mempool));
    init_mempool(m, num_records);

    // Step 3: initialize records with random keys and values
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % (key_range_max - key_range_min + 1) + key_range_min;
        values[i] = mempool_malloc(m);
        *values[i] = rand() % (offset_values[1] - offset_values[0] + 1) + offset_values[0];
    }

    // Step 4: sort records by keys in ascending or descending order
    qsort(records, num_records, sizeof(record_t), compare_keys);

