    pthread_mutex_init(mutex, NULL);

    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(mutex);
        fwrite(&records[i], sizeof(record_t), 1, f);
        pthread_mutex_unlock(mutex);
    }

    // Step 9: log information about memory usage, validation results, and I/O errors
    printf("Memory usage: %lu bytes\n", (long unsigned int)m->used * sizeof(void*));
    printf("Validation results: %d records successfully validated.\n", num_records);
    if (ferror(f)) {
        printf("Error writing to file. Exiting...\n");
        fclose(f);
        free(keys);
        free(values);
        free(m);
        return;
    }

    // Close the file and release resources
    fclose(f);
    free(mutex);
    free(keys);
    free(values);
    free(m);
}

// Define a comparison function for sorting records by keys in ascending or descending order
int compare_keys(const void* record1, const void* record2) {
    return ((record_t*)record1)->key - ((record_t*)record2)->key;
