function processUserAction($_POST) {
    // Initialize variables
    $action = $_POST['action'];
    $id = isset($_POST['id']) ? intval($_POST['id']) : null;
    $name = $_POST['name'];
    $email = $_POST['email'];
    $password = $_POST['password'];
    $locale = $_POST['locale'];

    // Validate input
    if (!$action || !in_array($action, ['create', 'update', 'delete', 'list'])) {
        return jsonResponse(['status' => 'error', 'message' => 'Invalid action']);
    }

    if ($action === 'create') {
        // Create new user
        $user = new User();
        $user->setName($name);
        $user->setEmail($email);
        $user->setPassword($password);
        $user->setLocale($locale);
        $user->save();

        return jsonResponse(['status' => 'success', 'message' => 'User created successfully']);
    } elseif ($action === 'update') {
        // Update existing user
        if (!$id) {
            return jsonResponse(['status' => 'error', 'message' => 'ID is required for update']);
        }

        $user = User::find($id);
        if (!$user) {
            return jsonResponse(['status' => 'error', 'message' => 'User not found']);
        }

        $user->setName($name);
        $user->setEmail($email);
        $user->setPassword($password);
        $user->setLocale($locale);
        $user->save();

        return jsonResponse(['status' => 'success', 'message' => 'User updated successfully']);
    } elseif ($action === 'delete') {
        // Delete user
        if (!$id) {
            return jsonResponse(['status' => 'error', 'message' => 'ID is required for delete']);
        }

        $user = User::find($id);
        if (!$user) {
            return jsonResponse(['status' => 'error', 'message' => 'User not found']);
        }

        $user->delete();

        return jsonResponse(['status' => 'success', 'message' => 'User deleted successfully']);
    } elseif ($action === 'list') {
        // List users
        if (!$locale) {
            return jsonResponse(['status' => 'error', 'message' => 'Locale is required for list']);
        }

        $users = User::where('locale', $locale)->paginate(100);

        return jsonResponse(['status' => 'success', 'users' => $users]);
    }
}
