    if ($deviceId !== null) {
        // Validate device ID against predefined list of valid profiles
        if (!in_array($deviceId, ['desktop', 'mobile'])) {
            throw new InvalidArgumentException('Invalid device ID');
        }

        // Ensure user has active consent for modifications via this device
