    // Check for duplicate accounts
    $duplicate = checkDuplicateAccount($name, $email);
    if ($duplicate !== null) {
        throw new InvalidArgumentException('Duplicate account');
    }

    // Create user account
    $id = insertUserAccount($name, $email, $password);

    // Update device profile association if specified
    if ($deviceId !== null) {
        updateDeviceProfile($id, $deviceId);
    }
}

function updateUserAccount($id, $name, $email, $password) {
    // Check for duplicate accounts
    $duplicate = checkDuplicateAccount($name, $email, $id);
    if ($duplicate !== null) {
        throw new InvalidArgumentException('Duplicate account');
    }

    // Update user account
    updateUserAccountById($id, $name, $email, $password);
}

function deleteUserAccount($id) {
    // Delete user account
    deleteUserAccountById($id);
}

function checkDuplicateAccount($name, $email, $id = null) {
    // Check for duplicate name
    if (isset($id)) {
        $query = "SELECT COUNT(*) FROM users WHERE id != :id AND name = :name";
        $stmt = $pdo->prepare($query);
        $stmt->bindParam(':id', $id, PDO::PARAM_INT);
    } else {
        $query = "SELECT COUNT(*) FROM users WHERE name = :name";
        $stmt = $pdo->prepare($query);
    }

    $stmt->bindParam(':name', $name, PDO::PARAM_STR);
    $stmt->execute();
    $count = $stmt->fetchColumn();

    // Check for duplicate email
    if ($count > 0) {
        return $id;
    } else {
        return null;
    }
}

function insertUserAccount($name, $email, $password) {
    // Insert user account into database
    $query = "INSERT INTO users (name, email, password) VALUES (:name, :email, :password)";
    $stmt = $pdo->prepare($query);

    $stmt->bindParam(':name', $name, PDO::PARAM_STR);
    $stmt->bindParam(':email', $email, PDO::PARAM_STR);
    $stmt->bindParam(':password', $password, PDO::PARAM_STR);

    $stmt->execute();
    return $pdo->lastInsertId();
}

function updateUserAccountById($id, $name, $email, $password) {
    // Update user account in database
    $query = "UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id";
    $stmt = $pdo->prepare($query);

    $stmt->bindParam(':id', $id, PDO::PARAM_INT);
    $stmt->bindParam(':name', $name, PDO::PARAM_STR);
    $stmt->bindParam(':email', $email, PDO::PARAM_STR);
    $stmt->bindParam(':password', $password, PDO::PARAM_STR);

    $stmt->execute();
}

function deleteUserAccountById($id) {
    // Delete user account from database
    $query = "DELETE FROM users WHERE id = :id";
    $stmt = $pdo->prepare($query);

    $stmt->bindParam(':id', $id, PDO::PARAM_INT);

    $stmt->execute();
}

function updateDeviceProfile($id, $deviceId) {
    // Update device profile association for user account
    $query = "UPDATE users SET device_id = :device_id WHERE id = :id";
    $stmt = $pdo->prepare($query);

    $stmt->bindParam(':id', $id, PDO::PARAM_INT);
    $stmt->bindParam(':device_id', $deviceId, PDO::PARAM_STR);

    $stmt->execute();
}

function sendConfirmationEmail($email) {
    // Send confirmation email to user
    $subject = 'Account Created';
    $message = "Thank you for creating an account! Your account has been created successfully.";

    try {
        $transport = Swift_SmtpTransport::newInstance('smtp.example.com', 25)
            ->setUsername('your_username')
            ->setPassword('your_password');

        $mailer = Swift_Mailer::newInstance($transport);

        $message = (new Swift_Message($subject))
            ->setFrom(array('your_email' => 'Your Name'))
            ->setTo(array($email => $name))
            ->setBody($message, 'text/html');

        $mailer->send($message);
    } catch (Exception $e) {
        // Handle API failure gracefully
    }
}

