    if (mp->count == mp->capacity) {
        // Dynamic resizing mechanism to handle potential memory exhaustion gracefully
        mp->capacity = 2 * mp->capacity;
        void **new_elements = (void **)memory_manager(mp->capacity * sizeof(void*));
        memcpy(new_elements, mp->elements, mp->count * sizeof(void*));
        memory_deallocator(mp->elements);
        mp->elements = new_elements;
    }
    void *element = (void *)memory_manager(size);
    mp->elements[mp->count++] = element;
}

void mempool_release(struct mempool *mp, void *element) {
