int open_connection(const char* hostname, int port, int protocol_version) {
  struct sockaddr_in server_address;
  int socket_fd = -1;
  if (hostname == NULL || strlen(hostname) == 0 || port < 0 || port > 65535) {
    // Handle invalid hostname or port
    return -1;
  }
  server_address.sin_family = AF_INET;
  server_address.sin_port = htons(port);
  inet_pton(AF_INET, hostname, &server_address.sin_addr);
  if (protocol_version == 4) {
    socket_fd = socket(PF_INET, SOCK_STREAM, 0);
  } else if (protocol_version == 6) {
    socket_fd = socket(PF_INET6, SOCK_STREAM, 0);
  } else {
    // Handle invalid protocol version
  }
  if (socket_fd < 0) {
    return -1;
  }
  if (connect(socket_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
    close(socket_fd);
    return -1;
  }
  return socket_fd;
}

int manage_session(NetworkSession *session, int protocol_version, const char* hostname, int port) {
  if (session == NULL || protocol_version < 4 || protocol_version > 6 || hostname == NULL || strlen(hostname) == 0 || port < 0 || port > 65535) {
    // Handle invalid session or hostname or port
    return -1;
  }
  int socket_fd = open_connection(hostname, port, protocol_version);
  if (socket_fd < 0) {
    // Handle failed connection establishment
    return -1;
  }
  session->next = NULL;
  session->timestamp = time(NULL);
  session->identifier = generate_identifier();
  session->state = ACTIVE;
  pthread_mutex_lock(&session_mutex);
  if (session_count < MAX_SESSIONS) {
    NetworkSession *next = session_pool;
    while (next != NULL && next->next != NULL) {
      next = next->next;
    }
    if (next == NULL) {
      session_pool = session;
    } else {
      next->next = session;
    }
    ++session_count;
  } else {
    // Handle edge case where maximum number of sessions is reached
  }
  pthread_mutex_unlock(&session_mutex);
  return socket_fd;
}

int close_connection(NetworkSession *session) {
  if (session == NULL) {
    // Handle invalid session
    return -1;
  }
  int ret = -1;
  pthread_mutex_lock(&session_mutex);
  NetworkSession **next = &session_pool;
  while (*next != NULL && *next != session) {
    next = &(*next)->next;
  }
  if (*next == NULL) {
    // Handle edge case where session is not found in pool
  } else {
    *next = (*next)->next;
    --session_count;
    ret = 0;
  }
  pthread_mutex_unlock(&session_mutex);
  return ret;
}

void cleanup_sessions() {
  NetworkSession *current = session_pool;
  while (current != NULL) {
    close(current->socket_fd);
    current = current->next;
  }
}
