        printf("Error: Invalid input for sorting records\n");
        exit(1);
    }

    // Initialize variables to keep track of the sorted records and their indices
    Record* sortedRecords = malloc(numRecords * sizeof(Record));
    int* indices = malloc(numRecords * sizeof(int));
    if (sortedRecords == NULL || indices == NULL) {
        printf("Error: Failed to allocate memory for sorting records\n");
        free(sortedRecords);
        free(indices);
        exit(1);
    }

    // Sort the records using a stable sorting algorithm
    for (int i = 0; i < numRecords; i++) {
        sortedRecords[i] = records[i];
        indices[i] = i;
    }
    for (int i = 0; i < numRecords - 1; i++) {
        int j;
