            if (sortedRecords[indices[i]].key > sortedRecords[indices[j]].key) {
                Record temp = sortedRecords[indices[i]];
                sortedRecords[indices[i]] = sortedRecords[indices[j]];
                sortedRecords[indices[j]] = temp;
                int tempIndex = indices[i];
                indices[i] = indices[j];
                indices[j] = tempIndex;
            }
        }
    }

    // Update the record arrays with the sorted records and their indices
    for (int i = 0; i < numRecords; i++) {
        records[i].offset = sortedRecords[indices[i]].offset;
        records[i].key = sortedRecords[indices[i]].key;
    }

    // Free the memory allocated for the temporary arrays
    free(sortedRecords);
    free(indices);
}

