struct CityTemps {
    char* city;
    float temp;
};

void processWeatherData(int numCities, int* cityNames, float* temps) {
    /* Initialize memory for matrices */
    struct CityTemps** cityTemps = malloc(numCities * sizeof(struct CityTemps));
    if (cityTemps == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for city temperatures\n");
        return;
    }

    /* Fetch and merge weather data from both APIs */
    for (int i = 0; i < numCities; i++) {
        int apiCallStatus = fetchWeatherData(cityNames[i], &temps[i]);
        if (apiCallStatus != 200) {
            fprintf(stderr, "Error: API call failed with status code %d\n", apiCallStatus);
            continue;
        }
    }

    /* Apply linear transformation to temperature data */
    for (int i = 0; i < numCities; i++) {
        temps[i] = pow(temps[i], 2);
    }

    /* Filter cities based on substring match */
    int filterCount = 0;
    for (int i = 0; i < numCities; i++) {
        if (strstr(cityNames[i], "San") != NULL) {
            cityTemps[filterCount] = malloc(sizeof(struct CityTemps));
            cityTemps[filterCount]->city = cityNames[i];
            cityTemps[filterCount]->temp = temps[i];
            filterCount++;
        }
    }

    /* Sort filtered cities based on temperature values */
    qsort(cityTemps, filterCount, sizeof(struct CityTemps), compareTemps);

    /* Export sorted city data into a compressed file format */
    FILE* outFile = fopen("output.zip", "wb");
    if (outFile == NULL) {
        fprintf(stderr, "Error: Failed to open output file\n");
        return;
    }
    for (int i = 0; i < filterCount; i++) {
        char* cityName = cityTemps[i]->city;
        float temp = cityTemps[i]->temp;
        fprintf(outFile, "%s\t%f\n", cityName, temp);
    }
    fclose(outFile);

    /* Clean up */
    for (int i = 0; i < filterCount; i++) {
        free(cityTemps[i]);
    }
    free(cityTemps);
}

/* Helper function to compare two temperature values */
int compareTemps(const void* a, const void* b) {
    struct CityTemps* cityA = (struct CityTemps*)a;
    struct CityTemps* cityB = (struct CityTemps*)b;
    if (cityA->temp < cityB->temp) {
        return -1;
    } else if (cityA->temp > cityB->temp) {
        return 1;
    } else {
        return 0;
    }
}

