    }
    // Use the custom memory pool to store the shapes
    for (int i = 0; i < num_shapes; i++) {
        shape_array[i] = *((shape_t *)memory_pool);
        memory_pool += sizeof(shape_t);
    }
}

// Function to validate user input and prevent buffer overflows or underflows
int validate_input(int num_shapes, int num_points) {
    // Check for integer overflow or underflow
    if (num_shapes < 0 || num_points < 0) {
        printf("Error: Invalid input, must be non-negative.\n");
        return -1;
    }
    // Check for buffer overflow
    if (num_shapes > INT_MAX / sizeof(shape_t) || num_points > INT_MAX / sizeof(double)) {
        printf("Error: Invalid input, buffer overflow.\n");
        return -1;
    }
    // Check for floating-point precision issues
    if (num_shapes * sizeof(shape_t) > DBL_MAX || num_points * sizeof(double) > DBL_MAX) {
        printf("Error: Invalid input, floating-point precision issues.\n");
        return -1;
    }
    // Return 0 if the input is valid
    return 0;
}

// Function to calculate the area of a shape
double calculateArea(double *double_array, char *char_array, int index) {
    // Calculate the area of the shape based on its type and coordinates
    switch (shape_array[index].type) {
        case 'R':
            return calculateCircleArea(double_array[index]);
        case 'T':
            return calculateTriangleArea(double_array, char_array, index);
        default:
            printf("Error: Invalid shape type.\n");
            return -1;
    }
}

// Function to calculate the area of a circle
double calculateCircleArea(double radius) {
    // Use the formula for the area of a circle to calculate its area
    double area = M_PI * radius * radius;
    return area;
}

// Function to calculate the area of a triangle
double calculateTriangleArea(double *double_array, char *char_array, int index) {
    // Calculate the area of the triangle based on its coordinates
    point_t p1 = shape_array[index].centroid;
    point_t p2 = shape_array[index + 1].centroid;
    point_t p3 = shape_array[index + 2].centroid;
    double area = calculateTriangleArea(p1, p2, p3);
    return area;
}

// Function to calculate the area of a triangle
double calculateTriangleArea(point_t p1, point_t p2, point_t p3) {
    // Use the formula for the area of a triangle to calculate its area
    double base = distance(p1, p2);
    double height = distance(p1, p3);
    double area = 0.5 * base * height;
    return area;
}

// Function to calculate the distance between two points
double distance(point_t p1, point_t p2) {
    // Use the formula for the distance between two points to calculate its distance
    double dx = p1.x - p2.x;
    double dy = p1.y - p2.y;
    double dist = sqrt(dx * dx + dy * dy);
    return dist;
}
