void* poolAlloc(struct Pool* pool) {
    // Check if there is available memory in the pool
    if (pool->offset < POOL_SIZE) {
        return &pool->entries[pool->offset++];
    } else {
        return NULL;
    }
}

// Function to free memory for a log entry, offset, key, or record structure
void poolFree(struct Pool* pool, void* ptr) {
    // Check if the pointer is within the bounds of the pool
    if (ptr >= &pool->entries[0] && ptr < &pool->entries[POOL_SIZE]) {
        pool->offset--;
    } else if (ptr >= &pool->offsets[0] && ptr < &pool->offsets[POOL_SIZE]) {
        pool->offset--;
    } else if (ptr >= &pool->keys[0] && ptr < &pool->keys[POOL_SIZE]) {
        pool->offset--;
    } else if (ptr >= &pool->records[0] && ptr < &pool->records[POOL_SIZE]) {
        pool->offset--;
    } else {
        // Invalid pointer, do nothing
    }
}

// Define a lock to synchronize access to the log entry, offset, key, and record structures
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to acquire the lock
void lockAcquire() {
    pthread_mutex_lock(&lock);
}

// Function to release the lock
void lockRelease() {
    pthread_mutex_unlock(&lock);
}

// Function to insert a new log entry into the list, maintaining priority order
void insertLogEntry(struct LogEntry* entry) {
    // Acquire the lock
    lockAcquire();

    // Insert the log entry at the appropriate position based on its priority level
    struct LogEntry* current = &pool->entries[0];
    while (current < &pool->entries[pool->offset] && current->priority > entry->priority) {
        current++;
    }
    memmove(current + 1, current, (&pool->entries[pool->offset] - current) * sizeof(struct LogEntry));
    memcpy(current, entry, sizeof(struct LogEntry));

    // Release the lock
    lockRelease();
}

// Function to delete a log entry from the list, based on its timestamp
void deleteLogEntry(time_t timestamp) {
    // Acquire the lock
    lockAcquire();

    // Find the log entry with the matching timestamp and remove it from the list
    struct LogEntry* current = &pool->entries[0];
    while (current < &pool->entries[pool->offset]) {
        if (current->timestamp == timestamp) {
            memmove(current, current + 1, (&pool->entries[pool->offset] - current - 1) * sizeof(struct LogEntry));
            pool->offset--;
            break;
        }
        current++;
    }

    // Release the lock
    lockRelease();
}

// Function to filter log entries based on their priority level and return them in an array
struct LogEntry* filterLogEntries(enum Priority priority) {
    struct LogEntry* filtered = NULL;
    int count = 0;

    // Acquire the lock
    lockAcquire();

    // Iterate over the log entries and copy those with the matching priority level to a new array
    struct LogEntry* current = &pool->entries[0];
    while (current < &pool->entries[pool->offset]) {
        if (current->priority == priority) {
            filtered = realloc(filtered, sizeof(struct LogEntry) * (count + 1));
            memcpy(&filtered[count], current, sizeof(struct LogEntry));
            count++;
        }
        current++;
    }

    // Release the lock
    lockRelease();

    return filtered;
}

// Function to sort records based on their values in ascending or descending order
void sortRecords(int* record_array, int num_records, int direction) {
    if (direction == 1) { // Ascending
        for (int i = 0; i < num_records - 1; i++) {
            for (int j = i + 1; j < num_records; j++) {
                if (record_array[i] > record_array[j]) {
                    int temp = record_array[i];
                    record_array[i] = record_array[j];
                    record_array[j] = temp;
                }
            }
        }
    } else if (direction == -1) { // Descending
        for (int i = 0; i < num_records - 1; i++) {
            for (int j = i + 1; j < num_records; j++) {
                if (record_array[i] < record_array[j]) {
                    int temp = record_array[i];
                    record_array[i] = record_array[j];
                    record_array[j] = temp;
                }
            }
        }
    }
}

// Function to serialize the sorted records into a file
void serializeRecords(int* record_array, int num_records) {
    FILE* fp = fopen("log.txt", "w");
    if (fp == NULL) {
        perror("Failed to open log file for writing");
        return;
    }

    for (int i = 0; i < num_records; i++) {
        fprintf(fp, "%d\n", record_array[i]);
    }

    if (fclose(fp) == EOF) {
        perror("Failed to close log file");
    }
}

// Function to handle potential memory exhaustion gracefully
void* memExhaustHandler(struct Pool* pool, int* num_records) {
    void* result = NULL;
    if (*num_records > 0) {
        // Serialize the sorted records into a file
        serializeRecords(pool->records[0], *num_records);

        // Release the memory allocated for the record array
        free(*num_records);
        result = NULL;
    } else {
        perror("Memory exhausted, unable to store records");
        result = NULL;
    }

    return result;
}
```
This implementation uses a custom memory pool to manage the allocation and deallocation of log entry, offset, key, and record structures. The memory pool is implemented as an array of `LogEntry`, `Offset`, `Key`, and `Record` structs, with each slot in the pool representing a separate instance of one of these structures. The `poolAlloc()` function allocates memory for a new log entry, offset, key, or record structure by incrementing the corresponding counter in the pool and returning a pointer to the newly allocated space. The `poolFree()` function frees memory for a log entry, offset, key, or record structure by decrementing the corresponding counter in the pool and releasing the associated memory.

The logging system also includes a lock to synchronize access to the log entry, offset, key, and record structures. The `lockAcquire()` function acquires the lock and the `lockRelease()` function releases the lock. This is necessary to prevent race conditions when multiple threads are accessing the log entry, offset, key, or record structures simultaneously.

The logging system includes functions for inserting, deleting, and filtering log entries based on their priority level. The `insertLogEntry()` function inserts a new log entry into the list, maintaining priority order, and the `deleteLogEntry()` function deletes a log entry from the list based on its timestamp. The `filterLogEntries()` function filters log entries based on their priority level and returns them in an array.

The logging system also includes functions for sorting records based on their values in ascending or descending order, and serializing the sorted records into a file. The `sortRecords()` function sorts records based on their values in ascending or descending order using a stable sorting algorithm, and the `serializeRecords()` function serializes the sorted records into a file.

The logging system includes a mechanism to handle potential memory exhaustion gracefully by calling the `memExhaustHandler()` function when memory is exhausted. This function serializes the sorted records into a file and releases the memory allocated for the record array.

Overall, this implementation provides a high-performance logging system that can efficiently manage large volumes of log entries, supports concurrent access from multiple threads, and includes robust error-handling mechanisms to prevent data corruption and race conditions.']

