        // Bypass SSL certificate verification for testing purposes
        curl::Easy::ssl_verify_none();
    }

    loop {
        let response = curl::easy::get(url.clone());
        match response {
            Ok(mut easy) => {
                // Parse the HTTP response into a string
                let mut response_string = String::new();
                easy.read_to_string(&mut response_string);

                // Extract the double precision floating point numbers and their associated labels from the JSON response
                let mut nodes: Vec<TreeNode<Double, Char>> = vec![];
                for line in response_string.lines() {
                    if let Ok(node) = TreeNode::from_json(line) {
                        nodes.push(node);
                    }
                }

                // Insert the extracted nodes into the tree, handling duplicates and maintaining tree balance
                for node in nodes {
                    match tree.insert(node) {
                        Ok(_) => (),
                        Err(_) => (),
                    }
                }
            },
            Err(easy) => println!("Error: {}", easy),
        }

        // Periodically serialize the tree's content into a compressed binary format and store it in a file
        if let Ok(mut f) = File::create("tree.bin") {
            match bincode::serialize_into(&mut f, &tree) {
                Ok(_) => (),
                Err(_) => (),
            }
        }
    }
}

struct TreeNode<Double, Char> {
    double: Double,
    char: Char,
}

impl TreeNode<Double, Char> {
    fn from_json(line: &str) -> Result<Self, ()> {
        let data: Value = serde_json::from_str(line).unwrap();
        let double = data.get("double").parse().unwrap_or(0.0);
        let char = data.get("char").chars().next().unwrap_or('0');

        Ok(Self { double, char })
    }
}

struct Tree<Double, Char> {
    root: Option<TreeNode<Double, Char>>,
}

impl Tree<Double, Char> {
    fn new() -> Self {
        Self { root: None }
    }

    fn insert(&mut self, node: TreeNode<Double, Char>) -> Result<(), ()> {
        if let Some(root) = &self.root {
            match root.double {
                Double::Greater => (),
                Double::Equal => return Err(()),
                Double::Less => self.root = Some(TreeNode { double: node.double, char: node.char }),
            }
        } else {
            self.root = Some(node);
        }

        Ok(())
    }
}

struct MemoryPool<T> {
    memory_limit: usize,
    pool: Vec<T>,
}

impl<T> MemoryPool<T> {
    fn new() -> Self {
        Self { memory_limit: 256, pool: vec![] }
    }

    fn allocate(&mut self, size: usize) -> Result<&mut T, ()> {
        if let Some(pool) = self.pool.pop() {
            return Ok(pool);
        } else {
            return Err(());
        }
    }
}

struct HashMap<Double, Char> {
    map: Mutex<HashMap<Double, Char>>,
}

impl<Double, Char> HashMap<Double, Char> {
    fn new() -> Self {
        Self { map: Mutex::new(HashMap::new()) }
    }

    fn insert(&mut self, node: TreeNode<Double, Char>) -> Result<(), ()> {
        let mut map = self.map.lock().unwrap();
        match map.insert(node.double, node.char) {
            Some(_) => (),
            None => return Err(()),
        }
    }
}

struct DiskStorage<Double, Char> {
    file: File,
}

impl<Double, Char> DiskStorage<Double, Char> {
    fn new() -> Self {
        Self { file: File::create("tree.bin").unwrap_or_else(|_| File::open("tree.bin").unwrap()) }
    }

    fn insert(&mut self, node: TreeNode<Double, Char>) -> Result<(), ()> {
        match bincode::serialize_into(&mut self.file, &node) {
            Ok(_) => (),
            Err(_) => return Err(()),
        }
    }
}

enum Double {
    Greater,
    Equal,
    Less,
}

impl From<f64> for Double {
    fn from(value: f64) -> Self {
        if value > 0.0 {
            Self::Greater
        } else if value == 0.0 {
            Self::Equal
        } else {
            Self::Less
        }
    }
}

fn average(tree: &Tree<Double, Char>) -> f64 {
    let mut sum = 0.0;
    let mut count = 0;

    if let Some(root) = &tree.root {
        for node in tree.iter() {
            sum += node.double as f64;
            count += 1;
        }

        return sum / count as f64;
    }
}
