typedef struct {
    int value;
} entry_t;

typedef struct {
    char* key;
    entry_t value;
} hash_entry_t;

typedef struct {
    pthread_mutex_t mutex;
    size_t count;
    hash_entry_t* entries[HASH_TABLE_SIZE];
} hash_table_t;

void initialize_hash_table(hash_table_t* table) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        table->entries[i] = NULL;
    }
    pthread_mutex_init(&table->mutex, NULL);
}

void add_entry(hash_table_t* table, char* key, int value) {
    pthread_mutex_lock(&table->mutex);

    size_t index = hash_function(key) % HASH_TABLE_SIZE;
    if (table->entries[index] == NULL) {
        table->entries[index] = malloc(sizeof(hash_entry_t));
    } else {
        hash_entry_t* current = table->entries[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = malloc(sizeof(hash_entry_t));
    }
    hash_entry_t* new_entry = table->entries[index];
    while (new_entry != NULL && new_entry->next != NULL) {
        new_entry = new_entry->next;
    }
    new_entry->key = key;
    new_entry->value.value = value;

    table->count++;

    pthread_mutex_unlock(&table->mutex);
}

void delete_entry(hash_table_t* table, char* key) {
    pthread_mutex_lock(&table->mutex);

    size_t index = hash_function(key) % HASH_TABLE_SIZE;
    hash_entry_t* current = table->entries[index];
    if (current == NULL) {
        // Entry not found
        return;
    }
    while (current != NULL && strcmp(current->key, key) != 0) {
        current = current->next;
    }
    if (current != NULL) {
        hash_entry_t* previous = current;
        current = current->next;
        free(previous);
        table->count--;
    } else {
        // Entry not found
        return;
    }

    pthread_mutex_unlock(&table->mutex);
}

void print_hash_table(hash_table_t* table) {
    printf("Hash Table: %zu entries\n", table->count);
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_entry_t* current = table->entries[i];
        while (current != NULL) {
            printf("Index: %d, Key: %s, Value: %d\n", i, current->key, current->value.value);
            current = current->next;
        }
    }
}

