    // Get the system load average
    getloadavg(&load_avg, 1);

    // Check if the load is above the threshold
    if (load_avg >= load_threshold) {
      // Increase the number of processes
      num_procs++;

      // Create a new process and set its CPU usage to zero
      pid_t proc = fork();
      if (proc == 0) {
        cpu_usage = 0.0;
      } else if (proc < 0) {
        perror("fork");
        exit(1);
      }
    }

    // Check if the number of processes exceeds the maximum
    if (num_procs > max_procs) {
      // Decrease the number of processes
      num_procs--;

      // Wait for a child process to exit
      wait(NULL);
    }

    // Loop through all active processes and check their CPU usage
    for (int i = 0; i < num_procs; i++) {
      if (proc_cpu_usage[i] > 20) {
        // Decrease the CPU usage of the process by 10%
        proc_cpu_usage[i] -= 10;
      }
    }

    // Check if any processes have exceeded their CPU usage limit
    for (int i = 0; i < num_procs; i++) {
      if (proc_cpu_usage[i] > 20) {
        // Terminate the process and decrease the number of active processes
        kill(proc, SIGKILL);
        wait(NULL);
        num_procs--;
      }
    }

    // Check if any processes have failed to create and need to be retried
    if (retry_count > 0) {
      // Exponentially backoff the creation of new processes
      backoff_factor *= 1.5;
      jitter_factor *= 0.2;
      sleep(backoff_factor + ((double)rand() / RAND_MAX) * jitter_factor);
    }

    // Reset the retry count if all processes have been created successfully
    if (num_procs == max_procs) {
      retry_count = 0;
    }

    // Log the CPU usage of each process
    for (int i = 0; i < num_procs; i++) {
      printf("Process %d has a CPU usage of %.2f%%\n", i + 1, proc_cpu_usage[i]);
    }

    // Sleep for 5 seconds before checking the system load again
    sleep(5);
  }
}
