// Function to allocate and initialize memory pools
void allocate_memory_pools(int* n) {
    // Allocate memory for the long offset values pool
    mem_pool[0] = malloc(*n * sizeof(long));
    if (mem_pool[0] == NULL) {
        printf("Error: Failed to allocate memory for long offset values pool\n");
        exit(1);
    }

    // Allocate memory for the integer keys pool
    mem_pool[1] = malloc(*n * sizeof(int));
    if (mem_pool[1] == NULL) {
        printf("Error: Failed to allocate memory for integer keys pool\n");
        exit(1);
    }

    // Allocate memory for the record structures pool
    mem_pool[2] = malloc(*n * sizeof(Record));
    if (mem_pool[2] == NULL) {
        printf("Error: Failed to allocate memory for record structures pool\n");
        exit(1);
    }
}

// Function to populate and validate the records
void populate_records(int* n) {
