    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < *n; i++) {
        records[i].key = rand() % 100;
        records[i].offset = (long)rand() % 1000000000;
    }

    // Validate the generated records
    for (size_t i = 0; i < *n; i++) {
        if (records[i].key < 0 || records[i].key > 100) {
            printf("Error: Invalid key value detected\n");
            exit(1);
        }

        if (records[i].offset < 0 || records[i].offset > 1000000000) {
            printf("Error: Invalid offset value detected\n");
            exit(1);
        }
    }
}

// Function to sort the records using a stable sorting algorithm
void sort_records(int* n) {
    // Sort the records based on their integer values
    for (size_t i = 0; i < *n; i++) {
        for (size_t j = i + 1; j < *n; j++) {
            if (records[i].key > records[j].key) {
                Record tmp = records[i];
                records[i] = records[j];
                records[j] = tmp;
            }
        }
    }
}

// Function to serialize the sorted records into a file
void serialize_records(int* n) {
    // Open the output file in binary mode
    FILE* fp = fopen("output.bin", "wb");
    if (fp == NULL) {
        printf("Error: Failed to open output file\n");
        exit(1);
    }

    // Write the sorted records into the file
    for (size_t i = 0; i < *n; i++) {
        fwrite(&records[i], sizeof(Record), 1, fp);
    }

    // Close the output file
    if (fclose(fp) != 0) {
        printf("Error: Failed to close output file\n");
        exit(1);
    }
}

