    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&list->lock);

    // Find the node containing the specified data
    ListNode *node = list->head;
    while (node != NULL && !(node->data == data)) {
        node = node->next;
    }

    // If the node is not found, return an error
    if (node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    // Remove the node from the list and free its memory
    ListNode *prev = NULL;
    while (node != NULL && !(node->data == data)) {
        prev = node;
        node = node->next;
    }
    if (prev == NULL) {
        list->head = node->next;
    } else {
        prev->next = node->next;
    }
    free(node);
    list->size--;

    // Unlock the list and return success
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Define the function for traversing the list
void traverseList(ListHead *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *data)) {
    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&list->lock);

    // Traverse the list and call the callback function for each item
    ListNode *node = list->head;
    while (node != NULL) {
        callback(node->data);
        node = node->next;
    }

    // Unlock the list and return success
    pthread_mutex_unlock(&list->lock);
}
