    // Check if input is valid
    if (longOffset < 0 || intKey < 0) {
        printf("Invalid input! Please enter positive values.\n");
        return -1;
    }

    // Determine size of arrays based on user input
    long offsetSize = (longOffset + 1) * sizeof(long);
    int keySize = (intKey + 1) * sizeof(int);

    // Validate sizes based on system limits and data ranges
    if (offsetSize > LONG_MAX || keySize > INT_MAX) {
        printf("The input values are too large! Please enter smaller values.\n");
        return -1;
    }

    // Handle invalid inputs by logging errors and prompting for re-entry
    if (longOffset < 0 || intKey < 0) {
        printf("Invalid input! Please enter positive values.\n");
        return -1;
    }

    // Calculate the size of both arrays based on user input
    int longArraySize = (longOffset + 1);
    int keyArraySize = (intKey + 1);

    return longArraySize * keyArraySize;
}

// Function to allocate memory for an array of record structures
Record* allocateMemory(int size) {
    // Allocate memory for the array
    Record* array = (Record*)malloc(size * sizeof(Record));

    // Check if allocation was successful
    if (array == NULL) {
        printf("Memory allocation failed! Please try again with a smaller input.\n");
        return NULL;
    }

    // Initialize each record in the array
    for (int i = 0; i < size; i++) {
        array[i].key = -1;
    }

    return array;
}

// Function to generate random values for a record's int field within a specified range
void generateRandomValues(Record* array, int size, int minValue, int maxValue) {
    // Check if the input range is valid
    if (minValue > maxValue) {
        printf("The minimum value must be less than or equal to the maximum value!\n");
        return;
    }

    // Generate random values for each record's int field within the specified range
    for (int i = 0; i < size; i++) {
        array[i].key = (rand() % (maxValue - minValue + 1)) + minValue;
    }
}

// Function to sort an array of records based on their int values using a stable sorting algorithm
void sortRecords(Record* array, int size) {
    // Define a comparison function for the sorting algorithm
    int compare(const void* first, const void* second) {
        Record* f = (Record*)first;
        Record* s = (Record*)second;
        return f->key - s->key;
    }

    // Sort the array using the comparison function and a stable sorting algorithm
    qsort(array, size, sizeof(Record), compare);
}

// Function to serialize an array of records to a file efficiently using compression and handling large files without excessive memory usage
void serializeRecords(Record* array, int size) {
    // Open the serialization file for writing
    FILE* fp = fopen("serialized_records.txt", "wb");

    // Check if the file was successfully opened
    if (fp == NULL) {
        printf("Error opening file! Please check your file path and permissions.\n");
        return;
    }

    // Compress the serialization data using gzip
    gzFile gzfp = gzdopen(fileno(fp), "wb");
    gzsetparams(gzfp, 9, Z_DEFAULT_STRATEGY);

    // Write the compressed serialization data to the file
    int numWritten = gzwrite(gzfp, array, size * sizeof(Record));

    // Check if the write was successful
    if (numWritten != size * sizeof(Record)) {
        printf("Error writing to file! Please check your file path and permissions.\n");
        return;
    }

    // Close the serialization file
    fclose(fp);
}

// Function to ensure thread-safe access to a data structure used for storing records
void synchronizeAccess(Record* array, int size) {
    // Define a mutex for protecting concurrent access to the array
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Lock the mutex before accessing the array
    pthread_mutex_lock(&mutex);

    // Unlock the mutex after accessing the array
    pthread_mutex_unlock(&mutex);
}

// Function to evaluate the effectiveness of a custom memory pool for managing memory allocation and deallocation
void evaluateMemoryPool(Record* array, int size) {
    // Define a custom memory pool with a fixed number of buckets
    MemoryPool<Record> pool = MemoryPool<Record>(1024);

    // Allocate memory from the pool for the array
    Record* newArray = pool.alloc(size * sizeof(Record));

    // Check if the allocation was successful
    if (newArray == NULL) {
        printf("Error allocating memory! Please check your memory usage and available buckets in the custom memory pool.\n");
        return;
    }

    // Deallocate memory from the pool for the array
    pool.dealloc(newArray, size * sizeof(Record));
}
