// Define the structure to store CRC indication data
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned long long crc;
    char* data;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list structure to store the list of CRC indication data
typedef struct LIST_NODE {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct LIST_NODE* next;
} LIST_NODE;

// Define a hashtable structure to store the list of CRC indication data in a hash table format
typedef struct HASHTABLE {
    LIST_NODE** buckets;
    unsigned int size;
    unsigned int count;
} HASHTABLE;

// Function to initialize the hashtable with an initial capacity of 100 elements
void init_hashtable(HASHTABLE* ht) {
    // Initialize the hashtable structure
    ht->size = 100;
    ht->count = 0;
    ht->buckets = (LIST_NODE**) malloc(ht->size * sizeof(LIST_NODE*));
    for (int i = 0; i < ht->size; i++) {
        ht->buckets[i] = NULL;
    }
}

// Function to insert a new CRC indication data into the hashtable
void insert_crc_indication(HASHTABLE* ht, NFAPI_CRC_INDICATION_PDU_T* crc_data) {
    // Calculate the hash value for the given CRC indication data
    unsigned long long hash = calculate_hash(crc_data->crc);

    // Check if the hash value already exists in the hashtable
    LIST_NODE* node = find_node(ht, hash);
    if (node != NULL) {
        // If the hash value already exists, update the existing data
        node->data = crc_data;
    } else {
        // If the hash value does not exist, create a new node and insert it into the hashtable
        LIST_NODE* new_node = (LIST_NODE*) malloc(sizeof(LIST_NODE));
        new_node->data = crc_data;
        new_node->next = NULL;
        ht->buckets[hash % ht->size] = new_node;
        ht->count++;
    }
}

// Function to delete a CRC indication data from the hashtable
void delete_crc_indication(HASHTABLE* ht, unsigned long long crc) {
    // Calculate the hash value for the given CRC indication data
    unsigned long long hash = calculate_hash(crc);

    // Check if the hash value exists in the hashtable
    LIST_NODE* node = find_node(ht, hash);
    if (node != NULL) {
        // If the hash value exists, delete the corresponding data from the hashtable
        free(node->data);
        node->next = NULL;
        ht->count--;
    }
}

// Function to retrieve a CRC indication data from the hashtable
NFAPI_CRC_INDICATION_PDU_T* get_crc_indication(HASHTABLE* ht, unsigned long long crc) {
    // Calculate the hash value for the given CRC indication data
    unsigned long long hash = calculate_hash(crc);

    // Check if the hash value exists in the hashtable
    LIST_NODE* node = find_node(ht, hash);
    if (node != NULL) {
        return node->data;
    } else {
        return NULL;
    }
}

// Function to resize the hashtable when the size is full or empty
void resize_hashtable(HASHTABLE* ht) {
    // Check if the hashtable needs to be resized
    if (ht->count == 0 || ht->count == ht->size) {
        // If the hashtable is empty or full, double the size of the hashtable
        ht->size *= 2;
        ht->buckets = (LIST_NODE**) realloc(ht->buckets, ht->size * sizeof(LIST_NODE*));
        for (int i = ht->size; i < ht->size * 2; i++) {
            ht->buckets[i] = NULL;
        }
    }
}

// Function to calculate the hash value for a given CRC indication data
unsigned long long calculate_hash(NFAPI_CRC_INDICATION_PDU_T* crc_data) {
    // Calculate the hash value using the CRC
    unsigned long long hash = (crc_data->crc * 19) % ht->size;
    return hash;
}

// Function to find a node in the hashtable given the hash value and data pointer
LIST_NODE* find_node(HASHTABLE* ht, unsigned long long hash) {
    // Check if the hash value exists in the hashtable
    LIST_NODE* node = ht->buckets[hash % ht->size];
    while (node != NULL && node->data->crc != crc_data->crc) {
        node = node->next;
    }
    return node;
}

// Function to free the memory used by the hashtable
void free_hashtable(HASHTABLE* ht) {
    for (int i = 0; i < ht->size; i++) {
        LIST_NODE* node = ht->buckets[i];
        while (node != NULL) {
            NFAPI_CRC_INDICATION_PDU_T* data = node->data;
            free(data);
            node = node->next;
        }
    }
    free(ht->buckets);
}
