    time_t timestamp;
    const char* message;
    LogLevel level;
};

// Define log collection structure
struct LogCollection {
    struct LogEntry* entries;
    size_t capacity;
    size_t count;
    bool pruningEnabled;
};

// Initialize a new log collection with a given capacity
void initLogCollection(struct LogCollection* collection, size_t capacity) {
    collection->entries = malloc(sizeof(struct LogEntry) * capacity);
    collection->capacity = capacity;
    collection->count = 0;
    collection->pruningEnabled = false;
}

// Free memory associated with a log collection
void destroyLogCollection(struct LogCollection* collection) {
    free(collection->entries);
}

// Add a new log entry to the collection
void addLogEntry(struct LogCollection* collection, time_t timestamp, const char* message, LogLevel level) {
    // Check if we need to prune old entries before adding new ones
    if (collection->pruningEnabled && collection->count >= collection->capacity / 2) {
        pruneLogEntries(collection);
    }

    // Add new log entry
    struct LogEntry* entry = &collection->entries[collection->count++];
    entry->timestamp = timestamp;
    entry->message = message;
    entry->level = level;
}

// Update an existing log entry in the collection
void updateLogEntry(struct LogCollection* collection, size_t index, time_t timestamp, const char* message, LogLevel level) {
    // Check if the index is valid
    if (index >= collection->count) {
        return;
    }

    // Update log entry
    struct LogEntry* entry = &collection->entries[index];
    entry->timestamp = timestamp;
    entry->message = message;
    entry->level = level;
}

// Retrieve a log entry from the collection by index
struct LogEntry* getLogEntry(struct LogCollection* collection, size_t index) {
    // Check if the index is valid
    if (index >= collection->count) {
        return NULL;
    }

    // Return log entry
    return &collection->entries[index];
}

// Retrieve all log entries from the collection that match a given level
struct LogEntry** getLogEntriesByLevel(struct LogCollection* collection, LogLevel level) {
    // Check if there are any log entries with the specified level
    size_t count = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->entries[i].level == level) {
            ++count;
        }
    }

    // Return NULL if there are no log entries with the specified level
    if (count == 0) {
        return NULL;
    }

    // Allocate memory for log entry pointers
    struct LogEntry** entries = malloc(sizeof(struct LogEntry*) * count);

    // Fill in log entry pointers
    size_t index = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->entries[i].level == level) {
            entries[index++] = &collection->entries[i];
        }
    }

    // Return log entry pointers
    return entries;
}

// Retrieve all log entries from the collection that match a given time range
struct LogEntry** getLogEntriesByTime(struct LogCollection* collection, time_t start, time_t end) {
    // Check if there are any log entries in the specified time range
    size_t count = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        struct LogEntry* entry = &collection->entries[i];
        if (entry->timestamp >= start && entry->timestamp <= end) {
            ++count;
        }
    }

    // Return NULL if there are no log entries in the specified time range
    if (count == 0) {
        return NULL;
    }

    // Allocate memory for log entry pointers
    struct LogEntry** entries = malloc(sizeof(struct LogEntry*) * count);

    // Fill in log entry pointers
    size_t index = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        struct LogEntry* entry = &collection->entries[i];
        if (entry->timestamp >= start && entry->timestamp <= end) {
            entries[index++] = entry;
        }
    }

    // Return log entry pointers
    return entries;
}

// Prune old log entries from the collection to free up resources
void pruneLogEntries(struct LogCollection* collection) {
    // Check if there are any log entries to prune
    if (collection->count == 0 || collection->pruningEnabled == false) {
        return;
    }

    // Get the oldest log entry
    size_t oldestIndex = 0;
    struct LogEntry* oldestEntry = &collection->entries[oldestIndex];

    // Find the oldest log entry
    for (size_t i = 1; i < collection->count; ++i) {
        if (collection->entries[i].timestamp <= oldestEntry->timestamp) {
            oldestEntry = &collection->entries[i];
            oldestIndex = i;
        }
    }

    // Remove the oldest log entry from the collection
    memmove(&collection->entries[oldestIndex], &collection->entries[oldestIndex + 1], (collection->count - oldestIndex) * sizeof(struct LogEntry));
    --collection->count;
}
