#include <pthread.h>

// Define the allowed domains list as a global variable
static char* allowed_domains[] = {"example1.com", "example2.com"};

// Define the DNS resolution function
int dns_resolve(const char* hostname, u_char* ip) {
    // Initialize the DNS resolver context
    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    // Query the DNS server for the given hostname
    struct addrinfo* result;
    int error = getaddrinfo(hostname, NULL, &hints, &result);
    if (error != 0) {
        printf("DNS resolution failed: %s\n", gai_strerror(error));
        return -1;
    }

    // Check if the resolved IP address belongs to an allowed domain
    bool is_allowed = false;
    for (int i = 0; i < sizeof(allowed_domains) / sizeof(*allowed_domains); ++i) {
        if (strcmp(allowed_domains[i], result->ai_canonname) == 0) {
            is_allowed = true;
            break;
        }
    }
    if (!is_allowed) {
        printf("Resolved IP address not in allowed domain list\n");
        freeaddrinfo(result);
        return -1;
    }

    // Set the output IP address
    *ip = result->ai_addr->sa_data[0];

    // Clean up and return
    freeaddrinfo(result);
    return 0;
}

