// Define pool management functions
void *pool_alloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        return NULL;
    }
    memset(ptr, 0, size);
    return ptr;
}

void pool_free(void *ptr) {
    free(ptr);
}

// Define NFAPI_CRC_INDICATION_PDU_T pool management functions
NFAPI_CRC_INDICATION_PDU_T *crc_indication_pool_alloc() {
    return (NFAPI_CRC_INDICATION_PDU_T *)pool_alloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void crc_indication_pool_free(NFAPI_CRC_INDICATION_PDU_T *ptr) {
    pool_free((void *)ptr);
}

// Define CRC indication pool data structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} crc_indication_pool_data_t;

// Define CRC indication pool management functions
void crc_indication_pool_init(crc_indication_pool_data_t *data) {
    data->capacity = 1024;
    data->count = 0;
    pthread_mutex_init(&data->lock, NULL);
}

void crc_indication_pool_destroy(crc_indication_pool_data_t *data) {
    pthread_mutex_destroy(&data->lock);
}

NFAPI_CRC_INDICATION_PDU_T *crc_indication_pool_acquire(crc_indication_pool_data_t *data) {
    pthread_mutex_lock(&data->lock);
    if (data->count == data->capacity) {
        size_t new_capacity = data->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T **new_pool = realloc(data->pool, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * new_capacity);
        if (new_pool == NULL) {
            pthread_mutex_unlock(&data->lock);
            return NULL;
        }
        data->pool = new_pool;
        data->capacity = new_capacity;
    }
    size_t index = data->count++;
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu = crc_indication_pool_alloc();
    if (crc_indication_pdu == NULL) {
        pthread_mutex_unlock(&data->lock);
        return NULL;
    }
    data->pool[index] = crc_indication_pdu;
    pthread_mutex_unlock(&data->lock);
    return crc_indication_pdu;
}

void crc_indication_pool_release(crc_indication_pool_data_t *data, NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu) {
    pthread_mutex_lock(&data->lock);
    size_t index = 0;
    for (index = 0; index < data->count; ++index) {
        if (data->pool[index] == crc_indication_pdu) {
            break;
        }
    }
    if (index == data->count) {
        pthread_mutex_unlock(&data->lock);
        return;
    }
    --data->count;
    memset(crc_indication_pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    data->pool[index] = data->pool[data->count];
    pthread_mutex_unlock(&data->lock);
}

// Define CRC indication pool statistics functions
void crc_indication_pool_statistics(crc_indication_pool_data_t *data, size_t *capacity, size_t *count) {
    pthread_mutex_lock(&data->lock);
    if (capacity != NULL) {
        *capacity = data->capacity;
    }
    if (count != NULL) {
        *count = data->count;
    }
    pthread_mutex_unlock(&data->lock);
}

