    long* arr; // Pointer to the array of longs
    int size; // Size of the array
} ThreadData;

// Function to execute in each thread
void* sortThread(void* arg) {
    // Extract the data for this thread from the argument struct
    ThreadData* data = (ThreadData*)arg;
    long* arr = data->arr;
    int size = data->size;

    // Sort the array using a bubble sort algorithm
    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                long temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }

    // Return the data for this thread
    return arg;
}

// Function to create and join threads for sorting an array of longs
void sortLongArrayMultithreaded(long* arr, int size) {
    // Create a fixed number of threads equal to the number of CPU cores
    const int numThreads = 8; // Use more or less threads based on system performance
    pthread_t threads[numThreads];

    // Calculate the size of each thread's workload
    const int chunkSize = size / numThreads;

    // Create a struct for each thread with its data and create it
    ThreadData* data = (ThreadData*)malloc(sizeof(ThreadData) * numThreads);
    for (int i = 0; i < numThreads; i++) {
        data[i].arr = arr + i * chunkSize;
        data[i].size = chunkSize;
        pthread_create(&threads[i], NULL, sortThread, &data[i]);
    }

    // Wait for all threads to complete and return their data
    void* results[numThreads];
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], &results[i]);
    }
}
