#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SIZE 1024 * 1024 * 1024 // 1 GB
#define MIN_RANGE 1
#define MAX_RANGE 1000000

typedef struct {
    long offset;
    int key;
} record;

record* records;
int num_records = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t sem;

void init(int size) {
    // Initialize the memory pool and array of records
    records = (record*) malloc(size * sizeof(record));
    num_records = 0;
}

void insert(long offset, int key) {
    // Insert a new record into the pool
    pthread_mutex_lock(&mutex);
    records[num_records].offset = offset;
    records[num_records].key = key;
    num_records++;
    sem_post(&sem);
    pthread_mutex_unlock(&mutex);
}

void remove(int index) {
    // Remove a record from the pool
    pthread_mutex_lock(&mutex);
    records[index] = records[num_records - 1];
    num_records--;
    sem_post(&sem);
    pthread_mutex_unlock(&mutex);
}

int get(int index) {
    // Get a record from the pool by index
    return records[index].key;
}

void sort() {
    // Sort the records using a stable sorting algorithm
    pthread_mutex_lock(&mutex);
    qsort(records, num_records, sizeof(record), compare);
    sem_post(&sem);
    pthread_mutex_unlock(&mutex);
}

int compare(const void* a, const void* b) {
    // Compare two records by their keys
    return (*((record*)a)).key - (*((record*)b)).key;
}

void serialize() {
    // Serialize the sorted records into a file
    FILE* fp = fopen("records.bin", "w");
    if (fp == NULL) {
        printf("Error: cannot open file for writing\n");
        return;
    }
    fwrite(records, sizeof(record), num_records, fp);
    fclose(fp);
}

void deserialize() {
    // Deserialize the records from a file
    FILE* fp = fopen("records.bin", "r");
    if (fp == NULL) {
        printf("Error: cannot open file for reading\n");
        return;
    }
    fread(records, sizeof(record), num_records, fp);
    fclose(fp);
}

void* thread_func(void* args) {
    // Function called by each thread to perform tasks concurrently
    long offset = 0;
    int key = 0;
    while (1) {
        sem_wait(&sem);
        if (num_records >= MAX_SIZE) {
            break;
        }
        // Generate a random integer between MIN_RANGE and MAX_RANGE
        key = MIN_RANGE + (rand() % (MAX_RANGE - MIN_RANGE + 1));
        offset = lrand48();
        insert(offset, key);
    }
    return NULL;
}

int main() {
    // Initialize the memory pool and array of records
    init(MAX_SIZE);
    sem_init(&sem, 0, 1);

    // Create a number of threads to perform tasks concurrently
    pthread_t* thread = (pthread_t*) malloc(sizeof(pthread_t) * 4);
    for (int i = 0; i < 4; i++) {
        pthread_create(&thread[i], NULL, thread_func, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 4; i++) {
        pthread_join(thread[i], NULL);
    }

    // Sort the records and serialize them into a file
    sort();
    serialize();

    // Deserialize the records from a file and print them to the console
    deserialize();
    for (int i = 0; i < num_records; i++) {
        printf("%d\n", get(i));
    }

    return 0;
}
```
