// Function to check if a number is a perfect square or prime
bool is_perfect_square(int num) {
    // Check if the number is a perfect square
    if (num == 0 || num % 2 == 0) {
        return true;
    }

    // Check if the number is a prime number
    for (int i = 3; i * i <= num; i += 2) {
        if (num % i == 0) {
            return false;
        }
    }

    return true;
}

// Function to allocate memory for the arrays
void allocate_arrays(int size, int *keys, Record **records) {
    // Allocate memory for the offsets array
    long *offsets = malloc(size * sizeof(long));
    if (offsets == NULL) {
        printf("Failed to allocate memory for offsets\n");
        return;
    }

    // Allocate memory for the keys array
    int *keys_array = malloc(size * sizeof(int));
    if (keys_array == NULL) {
        free(offsets);
        printf("Failed to allocate memory for keys\n");
        return;
    }

    // Allocate memory for the records array
    Record **records_array = malloc(size * sizeof(Record));
    if (records_array == NULL) {
        free(offsets);
        free(keys_array);
        printf("Failed to allocate memory for records\n");
        return;
    }

    // Set the offset and key values for each record
