        // Initialize the record structure
        Record *record = malloc(sizeof(Record));
        if (record == NULL) {
            free(offsets);
            free(keys_array);
            free(records_array);
            printf("Failed to allocate memory for record %d\n", i);
            return;
        }

        // Set the offset and key values for the record
        record->offset = &offset_value;
        record->key = &keys[i];
        records_array[i] = record;
