    // Set the valid flag to true if the sum of the keys array satisfies the condition
    bool valid = is_perfect_square(keys[size - 1]);
    for (int i = 0; i < size; i++) {
        records_array[i]->valid = valid;
    }

    // Return the allocated arrays and flags
    *offsets = offsets;
    *keys = keys_array;
    *records = records_array;
}

// Function to deallocate memory for the arrays
void deallocate_arrays(int size, int *keys, Record **records) {
    // Deallocate memory for the offsets array
    free(*offsets);

    // Deallocate memory for the keys array
    free(*keys);

    // Deallocate memory for the records array
    for (int i = 0; i < size; i++) {
        Record *record = records[i];
        if (record != NULL) {
            free(record);
        }
    }
    free(*records);
}
