<?php

// Environment variable management

class EnvVarManager {
    private $config;
    private $encryptionKey;
    private $cache;

    public function __construct($config, $encryptionKey, $cache) {
        $this->config = $config;
        $this->encryptionKey = $encryptionKey;
        $this->cache = $cache;
    }

    public function getEnvVar($name) {
        if ($this->cache->has($name)) {
            return $this->cache->get($name);
        } else {
            $value = $this->config[$name];
            if (is_string($value)) {
                $value = Encryptor::decrypt($value, $this->encryptionKey);
            }
            $this->cache->set($name, $value);
            return $value;
        }
    }
}

