    // Populate the list with data from an external API endpoint
    auto response = http::sync_request("GET", "http://example.com/api/data");
    if (response.status != 200) {
        std::cerr << "Failed to retrieve data from API: " << response.error << std::endl;
        return 1;
    }

    // Parse the response body as JSON and extract the necessary fields
    auto json = boost::json::parse(response.body);
    for (const auto& item : json["data"].as_array()) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = item["rx_ue_information_tag"].as_int();
        pdu.RNTI = item["rnti"].as_uint16();
        pduList.push_back(pdu);
    }

    // Implement retry logic with exponential backoff for network failures
    int retryCount = 0;
    while (retryCount < 3) {
        try {
            // Send the NFAPI_CRC_INDICATION_PDU_T structures to an external API endpoint
            http::sync_request("POST", "http://example.com/api/crc_indication", pduList);
            break;
        } catch (const std::exception& e) {
            std::cerr << "Failed to send CRC indication: " << e.what() << std::endl;
            retryCount++;
            if (retryCount == 3) {
                std::cerr << "Giving up after 3 retries" << std::endl;
                return 1;
            }
            // Exponential backoff with jitter
            double delay = pow(2, retryCount - 1) * (0.5 + drand48());
            std::this_thread::sleep_for(std::chrono::seconds(delay));
        }
    }

    return 0;
}
