```php
<?php

function updateUserProfile($userId, $contactInfo, $lastLoginTimestamp, $ipAddress) {
    // Validate inputs
    if (!is_numeric($userId) || !is_string($contactInfo) || !is_numeric($lastLoginTimestamp) || !is_string($ipAddress)) {
        throw new InvalidArgumentException('Invalid input parameters');
    }

    // Initialize variables
    $user = null;
    $oldContactInfo = null;
    $newContactInfo = null;
    $logMessage = '';

    // Begin transaction
    try {
        // Start the transaction
        Transaction::begin();

        // Get the user from the database
        $user = User::find($userId);

        // Check if the user exists
        if (!$user) {
            throw new Exception('User not found');
        }

        // Store the old contact info for logging purposes
        $oldContactInfo = $user->contact_info;

        // Update the user's contact info and last login timestamp
        $user->contact_info = $contactInfo;
        $user->last_login_timestamp = $lastLoginTimestamp;
        $user->ip_address = $ipAddress;

        // Save the user to the database
        $user->save();

        // Update the user activity feed with the new contact info
        $activityFeed = UserActivityFeed::where('user_id', $userId)->firstOrFail();
        $activityFeed->contact_info = $contactInfo;
        $activityFeed->last_login_timestamp = $lastLoginTimestamp;
        $activityFeed->save();

        // Log the change
        $logMessage = 'User contact info updated for user ID ' . $userId . '. Old contact info: ' . $oldContactInfo . '. New contact info: ' . $contactInfo . '.';
        Logger::info($logMessage);

        // Notify the user via SMS if their contact information has changed
        if ($oldContactInfo != $contactInfo) {
            try {
                // Send an SMS to the user with their new contact info
                $smsGateway = new SMSGateway();
                $smsGateway->sendSMS($user->phone_number, 'Your contact information has been updated. Your new contact info is: ' . $contactInfo);
            } catch (Exception $e) {
                // Log the error and continue with the function
                Logger::error('Error sending SMS notification to user: ' . $e->getMessage());
            }
        }

        // Commit the transaction
        Transaction::commit();
    } catch (Exception $e) {
        // Rollback the transaction on error
        Transaction::rollback();
        Logger::error('Error updating user profile: ' . $e->getMessage());
    }
}
