// Function to dynamically manage memory for multiple arrays of varying data types and sizes
int manage_memory(array_t *arrays, int num_arrays) {
    // Check if input is valid
    if (num_arrays <= 0 || arrays == NULL) {
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Allocate memory for each array and its records
    int i, j;
    for (i = 0; i < num_arrays; i++) {
        arrays[i].records = malloc(arrays[i].size * sizeof(record));
        if (arrays[i].records == NULL) {
            return MEMORY_ALLOCATION_FAILURE;
        }
    }

    // Initialize records with random values
    srand((unsigned int)time(NULL));
    for (i = 0; i < num_arrays; i++) {
        for (j = 0; j < arrays[i].num_records; j++) {
            arrays[i].records[j].key = rand() % INT_MAX;
            arrays[i].records[j].offset = rand() % LONG_MAX;
        }
    }

    // Sort records for each array based on key and offset values
    for (i = 0; i < num_arrays; i++) {
        qsort(arrays[i].records, arrays[i].num_records, sizeof(record), compare_records);
    }

    // Write sorted records to disk
    char filename[256];
    snprintf(filename, 256, "data_%d.bin", getpid());
    int fd = open(filename, O_CREAT | O_WRONLY, 0777);
    if (fd < 0) {
        return IO_ERROR;
    }
    for (i = 0; i < num_arrays; i++) {
        write(fd, arrays[i].records, sizeof(record) * arrays[i].num_records);
    }
    close(fd);

    // Read sorted records from disk and perform necessary checks for data integrity
    char *buffer = malloc(sizeof(char) * 4096);
    off_t offset = lseek(fd, 0, SEEK_SET);
    if (offset < 0) {
        return IO_ERROR;
    }
    read(fd, buffer, sizeof(char) * 4096);
    close(fd);
    for (i = 0; i < num_arrays; i++) {
        arrays[i].records = malloc(sizeof(record) * arrays[i].num_records);
        memcpy(arrays[i].records, buffer + offset, sizeof(record) * arrays[i].num_records);
    }

    // Free allocated memory and return success
    free(buffer);
    for (i = 0; i < num_arrays; i++) {
        free(arrays[i].records);
    }
    return 0;
}

// Comparison function for sorting records based on key and offset values
int compare_records(const void *a, const void *b) {
    if (((record *) a)->key < ((record *) b)->key) {
        return -1;
    } else if (((record *) a)->key > ((record *) b)->key) {
        return 1;
    } else {
        if (((record *) a)->offset < ((record *) b)->offset) {
            return -1;
        } else if (((record *) a)->offset > ((record *) b)->offset) {
            return 1;
        } else {
            return 0;
        }
    }
}
