// Function to manage dynamic and efficient storage of sensor data for a monitoring system
void manageSensorData(int numRecords, int threshold, int timeWindow) {
  // Initialize variables
  vector<string> deviceIds;
  vector<long long> timestamps;
  vector<float> sensorReadings;
  string currentDeviceId = "";
  long long currentTimestamp = 0;
  float currentSensorReading = 0.0f;
  bool memoryAllocationFailed = false;
  int numInMemoryRecords = 0;
  int numDiskPersistedRecords = 0;

  // Read sensor data from file
  ifstream inputFile("sensor_data.txt");
  while (inputFile >> currentDeviceId >> currentTimestamp >> currentSensorReading) {
    deviceIds.push_back(currentDeviceId);
    timestamps.push_back(currentTimestamp);
    sensorReadings.push_back(currentSensorReading);
  }
  inputFile.close();

  // Validate sensor data against system limits and potential negative or zero values
  for (int i = 0; i < numRecords; i++) {
    if (sensorReadings[i] <= 0) {
      // Replace invalid reading with a placeholder value
      sensorReadings[i] = -1.0f;
    } else if (abs(sensorReadings[i]) > threshold) {
      // Replace out-of-range reading with a placeholder value
      sensorReadings[i] = threshold;
    }
  }

  // Filter and aggregate sensor readings based on specified thresholds and time windows
  for (int i = 0; i < numRecords; i++) {
    if ((timestamps[i] - timestamps[0]) / 1000 >= timeWindow) {
      // Aggregate sensor readings within the specified time window
      float aggregatedReading = 0.0f;
      for (int j = i - timeWindow + 1; j <= i; j++) {
        aggregatedReading += sensorReadings[j];
      }
      aggregatedReading /= timeWindow;
      // Replace the oldest reading with the aggregated value
      sensorReadings[i - timeWindow] = aggregatedReading;
    }
  }

  // Sort records based on their timestamp using a stable sorting algorithm
  sort(timestamps.begin(), timestamps.end());
  for (int i = 0; i < numRecords; i++) {
    if (i > 0 && timestamps[i] != timestamps[i - 1]) {
      // Sort the records based on their timestamp in ascending order
      sort(sensorReadings.begin() + i, sensorReadings.end(), less<float>());
    }
  }

  // Serialize the filtered and sorted records into a file
  ofstream outputFile("filtered_sorted_records.txt");
  for (int i = 0; i < numRecords; i++) {
    outputFile << deviceIds[i] << "," << timestamps[i] << "," << sensorReadings[i] << endl;
  }
  outputFile.close();
}

// Robust validation function to handle edge cases and potential memory allocation failures
void validateSensorData(vector<string> deviceIds, vector<long long> timestamps, vector<float> sensorReadings) {
