  for (int i = 0; i < numRecords - 1; i++) {
    if (deviceIds[i] == deviceIds[i + 1]) {
      // Replace duplicate record with a placeholder value
      sensorReadings[i] = -1.0f;
      timestamps[i] = -1;
    } else if (sensorReadings[i] < 0) {
      // Replace invalid reading with a placeholder value
      sensorReadings[i] = -1.0f;
    } else if (abs(sensorReadings[i]) > threshold) {
      // Replace out-of-range reading with a placeholder value
      sensorReadings[i] = threshold;
    }
  }

  // Check for missing data at the end of the dataset
  if (sensorReadings.back() < 0) {
    // Replace missing data with a placeholder value
    sensorReadings.back() = -1.0f;
    timestamps.back() = -1;
  }
}

// Fallback mechanism to persist records on disk-based storage if in-memory allocation fails
void fallbackPersist(vector<string> deviceIds, vector<long long> timestamps, vector<float> sensorReadings) {
  // Attempt to allocate memory for the filtered and sorted records
  try {
    validateSensorData(deviceIds, timestamps, sensorReadings);
    sort(timestamps.begin(), timestamps.end());
    for (int i = 0; i < numRecords; i++) {
      if (i > 0 && timestamps[i] != timestamps[i - 1]) {
        // Sort the records based on their timestamp in ascending order
        sort(sensorReadings.begin() + i, sensorReadings.end(), less<float>());
      }
    }
  } catch (bad_alloc& e) {
    // Memory allocation failed
    memoryAllocationFailed = true;
  }

  // Persist the records on disk-based storage if in-memory allocation fails
  if (memoryAllocationFailed) {
    ofstream outputFile("filtered_sorted_records.txt");
    for (int i = 0; i < numRecords; i++) {
      outputFile << deviceIds[i] << "," << timestamps[i] << "," << sensorReadings[i] << endl;
    }
    outputFile.close();
  }
}

// Retry mechanism with exponential backoff for persistent storage operations
void retryPersist(vector<string> deviceIds, vector<long long> timestamps, vector<float> sensorReadings) {
  // Exponential backoff strategy to handle potential errors during persistent storage operations
  int numRetries = 0;
  while (numRetries < MAX_RETRIES) {
    try {
      validateSensorData(deviceIds, timestamps, sensorReadings);
      sort(timestamps.begin(), timestamps.end());
      for (int i = 0; i < numRecords; i++) {
        if (i > 0 && timestamps[i] != timestamps[i - 1]) {
          // Sort the records based on their timestamp in ascending order
          sort(sensorReadings.begin() + i, sensorReadings.end(), less<float>());
        }
      }
    } catch (bad_alloc& e) {
      // Memory allocation failed
      memoryAllocationFailed = true;
      numRetries++;
      if (numRetries < MAX_RETRIES) {
        // Exponential backoff strategy to handle potential errors during persistent storage operations
        this_thread::sleep_for(chrono::milliseconds(pow(2, numRetries)));
      } else {
        // Maximum number of retries reached, persist the records on disk-based storage
        fallbackPersist(deviceIds, timestamps, sensorReadings);
      }
    }
  }
}
