class JavaChannelManager {
private:
    vector<JavaChannel*> channels;
    int num_channels;
    mutex channel_lock;

public:
    JavaChannelManager(int n) {
        num_channels = n;
        channels.resize(n);
        for (int i = 0; i < n; i++) {
            channels[i] = new JavaChannel();
        }
    }

    void AcquireChannel(JavaChannel*& channel) {
        lock_guard<mutex> lock(channel_lock);
        if (!channels.empty()) {
            channel = channels.back();
            channels.pop_back();
        } else {
            channel = new JavaChannel();
        }
    }

    void ReleaseChannel(JavaChannel*& channel) {
        lock_guard<mutex> lock(channel_lock);
        channels.push_back(channel);
        channel = nullptr;
    }
};

