int load_log_config(const char* config_file) {
  // Check if the configuration file exists and is readable
  if (access(config_file, R_OK)) {
    perror("Unable to access log configuration file");
    return -1;
  }

  // Load the configuration file into memory
  FILE* config = fopen(config_file, "r");
  if (!config) {
    perror("Unable to open log configuration file for reading");
    return -1;
  }

  int num_successful_params = 0;

  // Parse the configuration file line by line
  char* line = NULL;
  size_t len = 0;
  ssize_t read;
  while ((read = getline(&line, &len, config)) != -1) {
    // Ignore comments and empty lines
    if (strncmp(line, "#", 1) == 0 || strlen(line) == 0) continue;

    // Parse the key-value pair for the current line
    char* key = strtok(line, "=");
    char* value = strtok(NULL, "\n");

    // Handle unsupported parameter formats gracefully
    if (key && value) {
      // Check if the key is supported by the logging system
      if (strcmp(key, "level") == 0 || strcmp(key, "format") == 0 || strcmp(key, "path") == 0) {
        // Configure the corresponding parameter based on the given value
        if (strcmp(key, "level") == 0) {
          if (strcmp(value, "debug") == 0) log_set_level(LOG_DEBUG);
          else if (strcmp(value, "info") == 0) log_set_level(LOG_INFO);
          else if (strcmp(value, "warn") == 0) log_set_level(LOG_WARN);
          else if (strcmp(value, "error") == 0) log_set_level(LOG_ERROR);
        } else if (strcmp(key, "format") == 0) {
          // Integrate with external libraries or services for formatting
          // ...
        } else if (strcmp(key, "path") == 0) {
          // Integrate with external libraries or services for sending logs
          // ...
        }
      } else {
        perror("Unsupported log configuration key");
      }
    }

    // Free the memory allocated by strtok
    free(line);
    line = NULL;
    len = 0;
  }

  // Close the file stream and return the number of successfully configured parameters
  fclose(config);
  return num_successful_params;
}
