// Serialize the sorted records into a file for efficient storage and retrieval
void serialize_records(struct record_pool *pool) {
  // Open a file for writing in binary mode
  FILE *fp = fopen("sorted_records.dat", "wb");
  if (fp == NULL) {
    return;
