```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Structure to hold a single entry in the key-value store
typedef struct {
    char* key;
    char* value;
} entry_t;

// Structure to hold the state of the key-value store
typedef struct {
    int num_entries;
    entry_t* entries;
    pthread_mutex_t mutex;
} kv_store_t;

// Initialize a new key-value store with an empty array of entries
kv_store_t* kv_store_init() {
    kv_store_t* store = malloc(sizeof(kv_store_t));
    if (!store) {
        fprintf(stderr, "Failed to allocate memory for the key-value store\n");
        return NULL;
    }
    store->num_entries = 0;
    store->entries = NULL;
    pthread_mutex_init(&store->mutex, NULL);
    return store;
}

// Insert a new entry into the key-value store
int kv_store_insert(kv_store_t* store, char* key, char* value) {
    if (!key || !value) {
        fprintf(stderr, "Invalid input: key or value is NULL\n");
        return -1;
    }
    pthread_mutex_lock(&store->mutex);
    int i = 0;
    while (i < store->num_entries && strcmp(key, store->entries[i].key) != 0) {
        i++;
    }
    if (i == store->num_entries) {
        // Allocate more memory for the entries array if necessary
        if (store->num_entries >= store->entries->capacity) {
            entry_t* new_entries = realloc(store->entries, 2 * store->num_entries * sizeof(entry_t));
            if (!new_entries) {
                fprintf(stderr, "Failed to allocate more memory for the key-value store\n");
                pthread_mutex_unlock(&store->mutex);
                return -1;
            }
            store->num_entries *= 2;
        }
        // Insert the new entry at the end of the array
        strcpy(store->entries[i].key, key);
        strcpy(store->entries[i].value, value);
        store->num_entries++;
    } else {
        // Update the existing entry if it already exists
        strcpy(store->entries[i].value, value);
    }
    pthread_mutex_unlock(&store->mutex);
    return 0;
}

// Delete an entry from the key-value store
int kv_store_delete(kv_store_t* store, char* key) {
    if (!key) {
        fprintf(stderr, "Invalid input: key is NULL\n");
        return -1;
    }
    pthread_mutex_lock(&store->mutex);
    int i = 0;
    while (i < store->num_entries && strcmp(key, store->entries[i].key) != 0) {
        i++;
    }
    if (i == store->num_entries) {
        pthread_mutex_unlock(&store->mutex);
        return -1;
    } else {
        // Shift the remaining entries to fill the gap
        int j = i + 1;
        while (j < store->num_entries) {
            strcpy(store->entries[j-1].key, store->entries[j].key);
            strcpy(store->entries[j-1].value, store->entries[j].value);
            j++;
        }
        // Decrease the number of entries and free the last entry
        store->num_entries--;
        pthread_mutex_unlock(&store->mutex);
        return 0;
    }
}

// Retrieve an entry from the key-value store
entry_t* kv_store_retrieve(kv_store_t* store, char* key) {
    if (!key) {
        fprintf(stderr, "Invalid input: key is NULL\n");
        return NULL;
    }
    pthread_mutex_lock(&store->mutex);
    int i = 0;
    while (i < store->num_entries && strcmp(key, store->entries[i].key) != 0) {
        i++;
    }
    if (i == store->num_entries) {
        pthread_mutex_unlock(&store->mutex);
        return NULL;
    } else {
        entry_t* result = malloc(sizeof(entry_t));
        strcpy(result->key, key);
        strcpy(result->value, store->entries[i].value);
        pthread_mutex_unlock(&store->mutex);
        return result;
    }
}

// Free the memory allocated for the key-value store
void kv_store_free(kv_store_t* store) {
    if (store) {
        free(store->entries);
        pthread_mutex_destroy(&store->mutex);
        free(store);
    }
}
