// Define structure for record
typedef struct {
  int key;
} Record;

// Define hash table with separate chaining and dynamic resizing
typedef struct {
  Record **buckets;
  size_t count;
  size_t capacity;
  float load_factor;
} HashTable;

// Function to initialize hash table with given initial capacity and resize threshold
void init_hash_table(HashTable *ht, size_t initial_capacity, float resize_threshold) {
  ht->buckets = malloc(initial_capacity * sizeof(Record*));
  ht->count = 0;
  ht->capacity = initial_capacity;
  ht->load_factor = resize_threshold;
}

// Function to insert record into hash table with given key and value
void insert_record(HashTable *ht, int key, Record *value) {
  // Compute hash code for key
  size_t index = key % ht->capacity;

  // Check if bucket is empty or contains a record with the same key
  if (ht->buckets[index] == NULL || ht->buckets[index]->key == key) {
    // Insert new record into bucket
    ht->buckets[index] = value;
    ht->count++;
  } else {
    // Handle collision by chaining records in the same bucket
    Record *curr = ht->buckets[index];
    while (curr->next != NULL) {
      curr = curr->next;
    }
    curr->next = value;
  }
}

// Function to retrieve record from hash table with given key
Record *get_record(HashTable *ht, int key) {
  // Compute hash code for key
  size_t index = key % ht->capacity;

  // Check if bucket is empty or contains a record with the same key
  if (ht->buckets[index] == NULL || ht->buckets[index]->key != key) {
    return NULL;
  } else {
    return ht->buckets[index];
  }
}

// Function to resize hash table when load factor exceeds given threshold
void resize_hash_table(HashTable *ht, float resize_threshold) {
  // Compute new capacity based on current load factor
  size_t new_capacity = (size_t)(pow(2, ceil(log2(ht->count / resize_threshold))));

  // Allocate new array for buckets with new capacity
  Record **new_buckets = malloc(new_capacity * sizeof(Record*));

  // Initialize new buckets and copy existing records to them
  size_t i;
  for (i = 0; i < ht->capacity; i++) {
    if (ht->buckets[i] != NULL) {
      Record *curr = ht->buckets[i];
      while (curr != NULL) {
        size_t new_index = curr->key % new_capacity;
        curr->next = new_buckets[new_index];
        new_buckets[new_index] = curr;
        curr = curr->next;
      }
    }
  }

  // Free old buckets and update hash table with new ones
  free(ht->buckets);
  ht->buckets = new_buckets;
  ht->capacity = new_capacity;
}

// Function to process a batch of records and insert them into the hash table
void process_batch(HashTable *ht, Record **records, size_t count) {
  // Iterate over records in batch and insert them into hash table
  for (size_t i = 0; i < count; i++) {
    Record *record = records[i];
    if (get_record(ht, record->key) == NULL) {
      insert_record(ht, record->key, record);
    }
  }
}

// Function to handle memory allocation failures and invalid input ranges
void handle_errors(HashTable *ht, Record **records, size_t count) {
  // Check for memory allocation failure
  if (ht == NULL || records == NULL || count == 0) {
    return;
  }

  // Check for invalid input range
  if (count > ht->capacity) {
    resize_hash_table(ht, ht->load_factor);
  }
}

// Function to integrate with external data processing pipeline
void process_data(HashTable *ht, Record **records, size_t count) {
  // Handle memory allocation failures and invalid input ranges
  handle_errors(ht, records, count);

  // Process batch of records and insert them into hash table
  process_batch(ht, records, count);
}

// Function to monitor performance metrics for each batch processed
void log_metrics(HashTable *ht, Record **records, size_t count) {
  // Compute processing time and memory usage for batch
  double start = get_time();
  process_batch(ht, records, count);
  double end = get_time() - start;
  size_t bytes = 0;
  for (size_t i = 0; i < count; i++) {
    Record *record = records[i];
    bytes += sizeof(*record) + strlen(record->value);
  }
  printf("Processed %zu records in %.3f seconds, with memory usage of %zu bytes.\n", count, end, bytes);
}

// Function to support integration with future features, such as distributed processing or data sharding
void configure_hash_table(HashTable *ht, size_t initial_capacity, float resize_threshold) {
  // Initialize hash table with given initial capacity and resize threshold
  init_hash_table(ht, initial_capacity, resize_threshold);
}
