#define MAX_CACHE_SIZE 1024 // maximum cache size in bytes
#define LOAD_FACTOR_THRESHOLD 0.7 // load factor threshold for resizing
#define RANDOM_VALUE_RANGE 100 // random value range for record initialization

// custom hash table with separate chaining for efficient key-value mapping and dynamic resizing based on the load factor threshold
struct HashTable {
    struct Node **buckets; // array of nodes
    int numBuckets; // number of buckets
    int numEntries; // number of entries
};

// hash table node for storing key-value pairs
struct Node {
    void *key; // key
    void *val; // value
    struct Node *next; // next node in the chain
};

// cache entry for storing frequently accessed records and events
struct CacheEntry {
    void *record; // record
    void *event; // event
    int timestamp; // timestamp
    int id; // unique identifier
    struct CacheEntry *next; // next cache entry in the chain
};

// cache for storing frequently accessed records and events
struct Cache {
    struct CacheEntry **entries; // array of cache entries
    int numEntries; // number of entries
    int maxEntries; // maximum number of entries
    int size; // current cache size in bytes
    float loadFactor; // load factor
};

// logging system for monitoring errors, performance metrics, and cache hit/miss rates
struct LoggingSystem {
    FILE *file; // file handle for logging
    struct Cache *cache; // cache instance
    int numRecords; // number of records logged
    int numEvents; // number of events logged
    float hitRate; // cache hit rate
    float missRate; // cache miss rate
};

// allocate memory for a new hash table node with the given key and value
struct Node *hashTableNodeAlloc(void *key, void *val) {
    struct Node *node = malloc(sizeof(struct Node));
    if (node == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    node->key = key;
    node->val = val;
    node->next = NULL;
    return node;
}

// allocate memory for a new cache entry with the given record and event
struct CacheEntry *cacheEntryAlloc(void *record, void *event) {
    struct CacheEntry *entry = malloc(sizeof(struct CacheEntry));
    if (entry == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    entry->record = record;
    entry->event = event;
    entry->next = NULL;
    return entry;
}

// insert the given key-value pair into the hash table
void hashTableInsert(struct HashTable *ht, void *key, void *val) {
    int index = hashFunction(key);
    struct Node **node = &(ht->buckets[index]);
    while (*node != NULL) {
        node = &((*node)->next);
    }
    *node = hashTableNodeAlloc(key, val);
}

// retrieve the value associated with the given key from the hash table
void *hashTableGet(struct HashTable *ht, void *key) {
    int index = hashFunction(key);
    struct Node **node = &(ht->buckets[index]);
    while (*node != NULL && !keysEqual((*node)->key, key)) {
        node = &((*node)->next);
    }
    if (*node == NULL) {
        return NULL;
    } else {
        return (*node)->val;
    }
}

// delete the entry with the given key from the hash table
void hashTableDelete(struct HashTable *ht, void *key) {
    int index = hashFunction(key);
    struct Node **node = &(ht->buckets[index]);
    while (*node != NULL && !keysEqual((*node)->key, key)) {
        node = &((*node)->next);
    }
    if (*node == NULL) {
        return;
    } else {
        struct Node *temp = *node;
        *node = temp->next;
        free(temp);
    }
}

// initialize a new cache instance with the given maximum capacity and load factor threshold
void cacheInit(struct Cache *cache, int maxEntries, float loadFactor) {
    cache->entries = malloc(sizeof(struct CacheEntry *) * maxEntries);
    if (cache->entries == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    cache->numEntries = 0;
    cache->maxEntries = maxEntries;
    cache->size = 0;
    cache->loadFactor = loadFactor;
}

// insert the given record and event into the cache
void cacheInsert(struct Cache *cache, void *record, void *event) {
    struct CacheEntry *entry = cacheEntryAlloc(record, event);
    if (cache->numEntries == cache->maxEntries) {
        // evict oldest entry from the cache
        int oldestIndex = 0;
        for (int i = 1; i < cache->numEntries; i++) {
            if (cache->entries[i]->timestamp < cache->entries[oldestIndex]->timestamp) {
                oldestIndex = i;
            }
        }
        struct CacheEntry *oldestEntry = cache->entries[oldestIndex];
        cache->size -= sizeof(struct CacheEntry);
        free(oldestEntry);
    }
    cache->numEntries++;
    cache->size += sizeof(struct CacheEntry);
    cache->entries[cache->numEntries - 1] = entry;
}

// retrieve the value associated with the given record from the cache
void *cacheGet(struct Cache *cache, void *record) {
    for (int i = 0; i < cache->numEntries; i++) {
        if (cache->entries[i]->record == record) {
            return cache->entries[i];
        }
    }
    return NULL;
}

// delete the entry with the given record from the cache
void cacheDelete(struct Cache *cache, void *record) {
    for (int i = 0; i < cache->numEntries; i++) {
        if (cache->entries[i]->record == record) {
            struct CacheEntry *entry = cache->entries[i];
            cache->size -= sizeof(struct CacheEntry);
            free(entry);
            cache->numEntries--;
            return;
        }
    }
}

// hash function for mapping keys to indices in the hash table
int hashFunction(void *key) {
    int hash = 0;
    char *c = (char *) key;
    while (*c != '\0') {
        hash = hash * 31 + *c++;
    }
    return hash % ht->numBuckets;
}

// compare two keys for equality
int keysEqual(void *key1, void *key2) {
    char *c1 = (char *) key1;
    char *c2 = (char *) key2;
    while (*c1 == *c2++) {
        if (*c1++ == '\0') {
            return 1;
        }
    }
    return 0;
}

// main function for testing the hash table and cache functionality
int main() {
    struct HashTable ht;
    struct Cache cache;
    initHashTable(&ht); // initialize the hash table with default parameters
