    void *record1 = malloc(sizeof(int));
    void *event1 = malloc(sizeof(struct Event));
    recordInit(record1);
    eventInit(event1);
    hashTableInsert(&ht, "key1", record1); // insert a new key-value pair into the hash table
    cacheInsert(&cache, record1, event1); // insert a new record and event into the cache
    void *record2 = malloc(sizeof(int));
    void *event2 = malloc(sizeof(struct Event));
    recordInit(record2);
    eventInit(event2);
    hashTableInsert(&ht, "key2", record2); // insert another key-value pair into the hash table
    cacheInsert(&cache, record2, event2); // insert another record and event into the cache
    void *val1 = hashTableGet(&ht, "key1"); // retrieve the value associated with the first key from the hash table
    printf("Value associated with 'key1' is %d\n", (int) val1);
    void *val2 = cacheGet(&cache, record1); // retrieve the value associated with the first record from the cache
    printf("Value associated with 'record1' is %d\n", (int) val2);
    hashTableDelete(&ht, "key1"); // delete the entry with the first key from the hash table
