#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <math.h>

#define MIN_CAPACITY 1024
#define RESIZE_THRESHOLD 0.75

typedef struct {
    int* keys;
    long* offsets;
    void** records;
} hash_table_t;

struct hash_node {
    int key;
    long offset;
    void* record;
    struct hash_node* next;
};

static inline uint32_t hash(int key) {
    return (uint32_t)(key % UINT32_MAX);
}

// Inserts a new record into the hash table, updating the load factor and resizing as necessary.
void insert(hash_table_t* table, int key, long offset, void* record) {
    uint32_t index = hash(key) % table->capacity;

    // Check if there is already a record with the same key in the hash table.
    struct hash_node* node = table->buckets[index];
    while (node != NULL) {
        if (node->key == key) {
            // If so, update the offset and record value.
            node->offset = offset;
            node->record = record;
            return;
        }
        node = node->next;
    }

    // If there is no existing record with the same key, create a new one.
    struct hash_node* new_node = malloc(sizeof(struct hash_node));
    if (new_node == NULL) {
        fprintf(stderr, "Failed to allocate memory for hash table node\n");
        return;
    }
    new_node->key = key;
    new_node->offset = offset;
    new_node->record = record;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    // Check if the load factor exceeds the resize threshold, and resize the hash table if necessary.
    float load_factor = (float)table->size / table->capacity;
    if (load_factor > RESIZE_THRESHOLD) {
        // Resize the hash table by doubling its capacity.
        uint32_t new_capacity = table->capacity * 2;
        struct hash_node** new_buckets = realloc(table->buckets, sizeof(struct hash_node*) * new_capacity);
        if (new_buckets == NULL) {
            fprintf(stderr, "Failed to resize hash table\n");
            return;
        }
        table->capacity = new_capacity;
        table->buckets = new_buckets;
    }
}

// Removes a record from the hash table, updating the load factor and resizing as necessary.
void remove(hash_table_t* table, int key) {
    uint32_t index = hash(key) % table->capacity;

    // Find the node with the matching key in the hash table.
    struct hash_node* prev = NULL;
    struct hash_node* node = table->buckets[index];
    while (node != NULL) {
        if (node->key == key) {
            break;
        }
        prev = node;
        node = node->next;
    }

    // If the node is found, remove it from the list and update the load factor.
    if (node != NULL) {
        if (prev == NULL) {
            table->buckets[index] = node->next;
        } else {
            prev->next = node->next;
        }
        free(node);
        --table->size;

        // Check if the load factor is below the resize threshold, and resize the hash table if necessary.
        float load_factor = (float)table->size / table->capacity;
        if (load_factor < RESIZE_THRESHOLD) {
            // Resize the hash table by halving its capacity.
            uint32_t new_capacity = table->capacity / 2;
            struct hash_node** new_buckets = realloc(table->buckets, sizeof(struct hash_node*) * new_capacity);
            if (new_buckets == NULL) {
                fprintf(stderr, "Failed to resize hash table\n");
                return;
            }
            table->capacity = new_capacity;
            table->buckets = new_buckets;
        }
    }
}

// Returns the record corresponding to the given key in the hash table, or NULL if no such record exists.
void* get(hash_table_t* table, int key) {
    uint32_t index = hash(key) % table->capacity;

    // Find the node with the matching key in the hash table.
    struct hash_node* node = table->buckets[index];
    while (node != NULL) {
        if (node->key == key) {
            return node->record;
        }
        node = node->next;
    }

    // If no matching record is found, return NULL.
    return NULL;
}

// Initializes a new hash table with the given initial capacity and resize threshold.
hash_table_t* initialize(uint32_t initial_capacity, float resize_threshold) {
    if (initial_capacity < MIN_CAPACITY) {
        fprintf(stderr, "Invalid initial capacity specified\n");
        return NULL;
    }
    hash_table_t* table = malloc(sizeof(hash_table_t));
    if (table == NULL) {
        fprintf(stderr, "Failed to allocate memory for hash table\n");
        return NULL;
    }
    table->capacity = initial_capacity;
    table->size = 0;
    table->resize_threshold = resize_threshold;
    table->buckets = calloc(initial_capacity, sizeof(struct hash_node*));
    if (table->buckets == NULL) {
        fprintf(stderr, "Failed to allocate memory for hash table buckets\n");
        free(table);
        return NULL;
    }
    return table;
}

// Deallocates the memory used by a hash table.
void destroy(hash_table_t* table) {
    if (table != NULL) {
        for (uint32_t i = 0; i < table->capacity; ++i) {
            struct hash_node* node = table->buckets[i];
            while (node != NULL) {
                struct hash_node* next = node->next;
                free(node);
                node = next;
            }
        }
        free(table->buckets);
        free(table);
    }
}

// Wrapper function for the insert operation, which updates the load factor and resizes the hash table as necessary.
void insert_update(hash_table_t* table, int key, long offset, void* record) {
    pthread_mutex_lock(&table->mutex);
    insert(table, key, offset, record);
    pthread_mutex_unlock(&table->mutex);
}

// Wrapper function for the remove operation, which updates the load factor and resizes the hash table as necessary.
void remove_update(hash_table_t* table, int key) {
    pthread_mutex_lock(&table->mutex);
    remove(table, key);
    pthread_mutex_unlock(&table->mutex);
}

// Wrapper function for the get operation, which returns the record corresponding to the given key in the hash table.
void* get_update(hash_table_t* table, int key) {
    pthread_mutex_lock(&table->mutex);
    void* result = get(table, key);
    pthread_mutex_unlock(&table->mutex);
    return result;
}
