void resolveHostname(const char *hostname) {
    // Resolve the IP address for the given hostname using standard library functions
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return;
    }

    // Print the IP address for each DNS record type (A, AAAA, MX)
    struct addrinfo *result = res;
    while (result != NULL) {
        char ip[INET6_ADDRSTRLEN];
        void *addr;
        switch (result->ai_family) {
            case AF_INET:
                addr = &((struct sockaddr_in *) result->ai_addr)->sin_addr;
                break;
            case AF_INET6:
                addr = &((struct sockaddr_in6 *) result->ai_addr)->sin6_addr;
                break;
        }

        inet_ntop(result->ai_family, addr, ip, sizeof(ip));
        printf("%s\n", ip);

        result = result->ai_next;
    }

    freeaddrinfo(res);
}
