// Custom allocator for managing dynamic memory pools
void* customAlloc(size_t size) {
    // Check if the requested size is greater than the total size of the pool
    if (size > pool.totalSize - pool.usedSize) {
        // Reallocate the buffer to make room for more data
        pool.buffer = realloc(pool.buffer, pool.totalSize + size);
        assert(pool.buffer != NULL);
        // Update the total size of the pool
        pool.totalSize += size;
    }
    // Increment the used size of the pool
    pool.usedSize += size;
    return (void*)((char*)pool.buffer + pool.usedSize - size);
}

// Custom free function for deallocating memory from the pool
void customFree(void* ptr) {
    // Calculate the offset of the pointer within the buffer
    long offset = (char*)ptr - pool.buffer;
    // Update the used size of the pool accordingly
    pool.usedSize -= (size_t)(offset + 1);
