    for (k = numRecords / 2 - 1; k >= 0; --k) {
        left[k] = right[2 * k + 1];
        if (2 * k + 2 < numRecords && right[2 * k + 2].value > right[2 * k + 1].value) {
            left[k] = right[2 * k + 2];
