ServiceInstance* alloc_service_array(int M) {
    // Allocate memory for the array
    ServiceInstance* service_array = malloc(sizeof(ServiceInstance) * M);
    if (service_array == NULL) {
        perror("Error allocating memory for service array");
        return NULL;
    }

    // Initialize the structures in the array with default values
    for (int i = 0; i < M; i++) {
        service_array[i].service_id = 0;
        service_array[i].version = 0;
        service_array[i].supported_modes = NULL;
    }

    return service_array;
}

// Function to shuffle the elements of an array randomly
void shuffle(ServiceInstance* arr, int len) {
    // If there are fewer than 2 elements in the array, no need to shuffle
    if (len < 2) {
        return;
    }

    // Randomly select a swap index between 0 and len - 1
    int swap_idx = rand() % len;

    // Swap the element at swap_idx with the last element in the array
    ServiceInstance tmp = arr[swap_idx];
    arr[swap_idx] = arr[len - 1];
    arr[len - 1] = tmp;
}

