    private ConcurrentHashMap<String, SerializedObject> cache; // concurrent hash map for storing key-value pairs in the cache
    private Zookeeper zookeeper; // Zookeeper client for managing node states and ensuring fault tolerance
    private Consul consul; // Consul client for managing node states and ensuring fault tolerance
    private CacheEvictionThread evictionThread; // thread for evicting stale or least recently used items from the cache
    private SerializationThread serializationThread; // thread for serializing the entire cache state into a compact JSON format stored in a file
    private DeserializationThread deserializationThread; // thread for deserializing the entire cache state from a previously saved file

    public DistributedCache(int cacheSize, Zookeeper zookeeper, Consul consul) {
        this.cache = new ConcurrentHashMap<>(cacheSize);
        this.zookeeper = zookeeper;
        this.consul = consul;
        this.evictionThread = new CacheEvictionThread();
        this.serializationThread = new SerializationThread();
        this.deserializationThread = new DeserializationThread();
    }

    public void insert(String key, Object value) {
        try {
            cache.putIfAbsent(key, serialize(value));
        } catch (IOException e) {
            System.out.println("Error serializing object: " + e);
        }
    }

    public void remove(String key) {
        cache.remove(key);
    }

    public Object get(String key) {
        return deserialize(cache.get(key));
    }

    private SerializedObject serialize(Object value) throws IOException {
        byte[] serializedValue = Utils.serialize(value);
        int size = serializedValue.length;
        if (size > DEFAULT_SERIALIZATION_BUFFER_SIZE) {
            System.out.println("Serialized object is too large: " + size + " bytes");
        }
        return new SerializedObject(serializedValue, size);
    }

    private Object deserialize(SerializedObject serializedValue) throws IOException {
        if (serializedValue == null) {
            return null;
        }
        try {
            return Utils.deserialize(serializedValue.getData());
        } catch (IOException e) {
            System.out.println("Error deserializing object: " + e);
            return null;
        }
    }

    private static class SerializedObject {
        byte[] data;
        int size;

        public SerializedObject(byte[] data, int size) {
            this.data = data;
            this.size = size;
        }

        public byte[] getData() {
            return data;
        }

        public int getSize() {
            return size;
        }
    }

    private class CacheEvictionThread implements Runnable {
        @Override
        public void run() {
            while (true) {
                try {
                    Thread.sleep(1000); // sleep for 1 second between evictions
                    long totalSize = getTotalCacheSize();
                    if (totalSize > CACHE_EVICTION_THRESHOLD) {
                        evictStaleOrLeastRecentlyUsedItems(totalSize - CACHE_EVICTION_THRESHOLD);
                    }
                } catch (InterruptedException e) {
                    System.out.println("Cache eviction thread interrupted: " + e);
                }
            }
        }

        private long getTotalCacheSize() {
            return cache.values().stream().mapToInt(SerializedObject::getSize).sum();
        }

        private void evictStaleOrLeastRecentlyUsedItems(int size) {
            int evictedCount = 0;
            for (Map.Entry<String, SerializedObject> entry : cache.entrySet()) {
                if (evictedCount >= size) {
                    break;
                }
                String key = entry.getKey();
                SerializedObject value = entry.getValue();
                long lastAccessed = getLastAccessedTime(key);
                if (lastAccessed == 0 || lastAccessed < System.currentTimeMillis() - 60 * 1000) { // stale or least recently used
                    cache.remove(key);
                    evictedCount++;
                }
            }
        }

        private long getLastAccessedTime(String key) {
            return zookeeper.getNodeValue(key + "/last_accessed").orElseGet(() -> consul.getNodeValue(key + "/last_accessed")).map(Long::parseLong).orElse(0L);
        }
    }

    private class SerializationThread implements Runnable {
        @Override
        public void run() {
            while (true) {
                try {
                    Thread.sleep(1000); // sleep for 1 second between serializations
                    serializeCacheState();
                } catch (InterruptedException e) {
                    System.out.println("Serialization thread interrupted: " + e);
                }
            }
        }

        private void serializeCacheState() throws IOException {
            String json = Utils.serialize(cache);
            FileUtils.writeStringToFile(CACHE_FILE_PATH, json, Charset.defaultCharset());
        }
    }

    private class DeserializationThread implements Runnable {
        @Override
        public void run() {
            while (true) {
                try {
                    Thread.sleep(1000); // sleep for 1 second between deserializations
                    deserializeCacheState();
                } catch (InterruptedException e) {
                    System.out.println("Deserialization thread interrupted: " + e);
                } catch (IOException e) {
                    System.out.println("Error deserializing cache state: " + e);
                }
            }
        }

        private void deserializeCacheState() throws IOException {
            String json = FileUtils.readFileToString(CACHE_FILE_PATH, Charset.defaultCharset());
            Map<String, SerializedObject> cacheState = Utils.deserialize(json);
            if (cacheState == null) {
                return;
            }
            cache.clear();
            for (Map.Entry<String, SerializedObject> entry : cacheState.entrySet()) {
                cache.put(entry.getKey(), entry.getValue());
            }
        }
    }
}
