    if (session_list == NULL) {
        free(sessions);
        // Handle memory allocation failure
        return;
    }

    session_list->num_sessions = 0;
    session_list->max_sessions = max_sessions;
    session_list->session_array = sessions;

    // Initialize the TX queue for each session and allocate space for the TX queue data items
    for (int i = 0; i < max_sessions; i++) {
        struct tx_queue *tx_queue = malloc(sizeof(struct tx_queue));
