// Function to filter the records based on a specified condition involving the double value and the distance from the origin (0, 0) for the point structure
void filter_records(struct record *records, int num_records, double min_double_value, int min_distance) {
    // Allocate memory for the filtered records array
    struct record *filtered_records = malloc(num_records * sizeof(struct record));
    if (filtered_records == NULL) {
        // Handle memory allocation failure
        return;
    }

    int num_filtered_records = 0;
    for (int i = 0; i < num_records; i++) {
        struct record *record = &records[i];
        if (record->double_value >= min_double_value && record->distance >= min_distance) {
            filtered_records[num_filtered_records++] = *record;
        }
    }

    // Reallocate memory for the filtered records array to match the actual number of filtered records
    struct record *new_filtered_records = realloc(filtered_records, num_filtered_records * sizeof(struct record));
    if (new_filtered_records == NULL) {
        free(filtered_records);
        // Handle memory allocation failure
        return;
    }

    filtered_records = new_filtered_records;
}

