<?php

class PasswordDAO {
    private $conn;

    public function __construct($conn) {
        $this->conn = $conn;
    }

    public function updateUserPassword($userId, $newPassword, $oldPassword) {
        // Validate the new password against the criteria specified in the task
        if (!$this->validateNewPassword($newPassword)) {
            return false;
        }

        // Check if the user is authorized to perform this action
        if (!$this->isAuthorized($userId, $oldPassword)) {
            return false;
        }

        // Check if there have been too many password change attempts within the past 5 minutes
        if ($this->hasExceededRateLimit($userId)) {
            return 'LIMIT_EXCEEDED';
        }

        // Update the user's password in the database
        try {
            $stmt = $this->conn->prepare('UPDATE users SET password = :newPassword WHERE id = :userId');
            $stmt->bindValue(':newPassword', $newPassword);
            $stmt->bindValue(':userId', $userId);
            $stmt->execute();
        } catch (PDOException $e) {
            return false;
        }

        // Log the password change attempt
        $this->logPasswordChange($userId, $oldPassword, $newPassword);

        return true;
    }

    private function validateNewPassword($password) {
        if (strlen($password) < 12) {
            return false;
        }

        $hasUppercase = preg_match('/[A-Z]/', $password);
