        $hasDigit = preg_match('/\d/', $password);
        $hasSpecialChar = preg_match('/[^A-Za-z0-9]/', $password);

        if (!$hasUppercase || !$hasLowercase || !$hasDigit || !$hasSpecialChar) {
            return false;
        }

        if (preg_match('/(.)\1+/', $password)) {
            return false;
        }

        return true;
    }

    private function isAuthorized($userId, $oldPassword) {
        // Check if the user's session is active and that the user is authorized to perform this action
        try {
            $stmt = $this->conn->prepare('SELECT password FROM users WHERE id = :userId');
            $stmt->bindValue(':userId', $userId);
            $stmt->execute();
            $result = $stmt->fetch(PDO::FETCH_ASSOC);

            if ($result['password'] !== $oldPassword) {
                return false;
            }
        } catch (PDOException $e) {
            return false;
        }

        return true;
    }

    private function hasExceededRateLimit($userId) {
        // Check if there have been too many password change attempts within the past 5 minutes
        try {
