            $stmt->bindValue(':userId', $userId);
            $stmt->execute();
            $result = $stmt->fetch(PDO::FETCH_ASSOC);

            return $result['count'] >= 10;
        } catch (PDOException $e) {
            return false;
        }
    }

    private function logPasswordChange($userId, $oldPassword, $newPassword) {
