// Custom data structure for storing a string pointer and an integer key
typedef struct {
    char *str;
    int key;
} data_node;

// Reference counting mechanism to manage shared strings
typedef struct {
    int ref_count; // reference count for the string
    pthread_mutex_t lock; // mutex for thread safety
} string_ref;

// Function to dynamically allocate memory for an array of data nodes
data_node* dynamic_alloc(int num_nodes) {
    int i;
    data_node *nodes = malloc(sizeof(data_node) * num_nodes);
    if (nodes == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (i = 0; i < num_nodes; i++) {
        nodes[i].str = NULL;
        nodes[i].key = 0;
    }

    return nodes;
}

// Function to dynamically allocate memory for a string and initialize it with the given value
char* dynamic_string(const char *str) {
    int len = strlen(str);
    char *new_str = malloc(sizeof(char) * (len + 1));
    if (new_str == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    // Copy the given string into the new memory block
    memcpy(new_str, str, len);
    new_str[len] = '\0';

    return new_str;
}

// Function to initialize a data node with a dynamically allocated string and key
void init_data_node(data_node *node, const char *str, int key) {
    // Dynamically allocate memory for the string
    node->str = dynamic_string(str);

    // Set the integer key for the data node
    node->key = key;
}

// Function to increment the reference count of a shared string
void inc_ref_count(string_ref *ref) {
    pthread_mutex_lock(&ref->lock);
    ref->ref_count++;
    pthread_mutex_unlock(&ref->lock);
}

// Function to decrement the reference count of a shared string
void dec_ref_count(string_ref *ref) {
    pthread_mutex_lock(&ref->lock);
    ref->ref_count--;
    if (ref->ref_count == 0) {
        // Free the memory for the shared string if it is no longer in use
        free(ref->str);
    }
    pthread_mutex_unlock(&ref->lock);
}

// Function to create a new data node with a dynamically allocated string and key, using reference counting for shared strings
data_node* create_data_node(const char *str, int key) {
    // Create a new data node with the given value
    data_node *new_node = malloc(sizeof(data_node));
    if (new_node == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    // Initialize the data node with a dynamically allocated string and key, using reference counting for shared strings
    init_data_node(new_node, str, key);

    // Increment the reference count of the shared string to keep it in use until no longer needed
    inc_ref_count(&new_node->str);

    return new_node;
}

// Function to free the memory for a data node with a dynamically allocated string and key, using reference counting for shared strings
void destroy_data_node(data_node *node) {
    // Decrement the reference count of the shared string to indicate that it is no longer in use
    dec_ref_count(&node->str);

    // Free the memory for the data node
    free(node);
}

// Function to copy a data node with a dynamically allocated string and key, using reference counting for shared strings
data_node* copy_data_node(data_node *node) {
    // Create a new data node with the same value as the given node
    data_node *new_node = create_data_node(node->str, node->key);

    return new_node;
}

// Function to compare two data nodes with dynamically allocated strings and integers, using reference counting for shared strings
int compare_data_nodes(data_node *node1, data_node *node2) {
    // Compare the string values of the two data nodes using strcmp()
    int str_cmp = strcmp(node1->str, node2->str);

    // If the strings are equal, compare their integer keys
    if (str_cmp == 0) {
        return node1->key - node2->key;
    } else {
        return str_cmp;
    }
}
