// Define constants for logging priority levels and storage capacity limits
#define LOG_PRIORITY_LOW   0x1
#define LOG_PRIORITY_MEDIUM 0x2
#define LOG_PRIORITY_HIGH  0x3

#define STORAGE_CAPACITY_LIMIT 1024 // maximum storage capacity in MB

// Structure to hold log entry details
typedef struct LogEntry {
    uint64_t id;
    time_t timestamp;
    int priority;
    char message[256];
} LogEntry;

// Queue data structure for incoming logs
struct LogQueue {
    int capacity;
    int size;
    LogEntry* entries;
};

// Function to add a new log entry to the queue
int addLogEntry(struct LogQueue* queue, LogEntry* entry) {
    if (queue->size == queue->capacity) {
        return -1; // Queue is full, cannot add new entry
    }

    int i = 0;
    while (i < queue->size && queue->entries[i].timestamp >= entry->timestamp) {
        i++;
    }

    if (i == queue->size) {
        queue->entries[queue->size++] = *entry;
    } else {
        memmove(&queue->entries[i+1], &queue->entries[i], sizeof(LogEntry) * (queue->size - i));
        queue->entries[i] = *entry;
    }

