    // Add the new entry to the end of the list
    list_entry_t *new_entry = malloc(sizeof(list_entry_t));
    new_entry->pdu = pdu;
    new_entry->valid = 1;
    tail->next = new_entry;
    tail = new_entry;
}

// Function to remove an entry from the list by RNTI
void remove_list_entry(uint16_t rnti) {
    // Search for the entry with the specified RNTI
    list_entry_t *entry = head;
    while (entry != NULL && entry->rnti != rnti) {
        entry = entry->next;
