    // If the entry is found, remove it from the list and free its memory
    if (entry != NULL) {
        list_entry_t *prev = head;
        while (prev->next != entry) {
            prev = prev->next;
        }
        prev->next = entry->next;
        free(entry);
    }
}

// Function to filter the list entries by RNTI range
void filter_list_entries() {
    // Search for the first entry outside of the specified RNTI range
