        if (!(RNTI_FILTER_MIN <= entry->rnti && entry->rnti <= RNTI_FILTER_MAX)) {
            first_invalid = entry;
            break;
        }
    }

    // If the list contains any entries outside of the specified range, remove them
    if (first_invalid != NULL) {
        list_entry_t *prev = head;
        while (prev->next != first_invalid) {
            prev = prev->next;
        }
        prev->next = first_invalid->next;
        free(first_invalid);
    }
}

// Function to check if the list is full and remove the oldest entry if necessary
void check_list_full() {
    // If the list is not full, return immediately
    if (head == NULL || tail != head) {
