// Function to extract metadata and compute hash from JPEG file
image_info extract_metadata(const char* filename, int quality) {
  struct jpeg_decompress_struct cinfo;
  struct jpeg_error_mgr jerr;
  JSAMPARRAY buffer;
  int row_stride;
  FILE *infile = fopen(filename, "rb");
  if (!infile) {
    perror("Error opening input file");
    return NULL;
  }

  cinfo.err = jpeg_std_error(&jerr);
  jpeg_create_decompress(&cinfo);
  jpeg_stdio_src(&cinfo, infile);
  (void)jpeg_read_header(&cinfo, TRUE);
  jpeg_calc_output_dimensions(&cinfo);
  cinfo.out_color_space = JCS_RGB; // Use RGB as the output color space
  if (quality != -1) {
    jpeg_set_quality(&cinfo, quality, TRUE);
  }

  image_info info;
  info.width = cinfo.output_width;
  info.height = cinfo.output_height;
  info.color_space = "RGB";
  info.compression_type = "JPEG";
  buffer = (*cinfo.mem->alloc_sarray)((j_common_ptr)&cinfo, JPOOL_IMAGE, cinfo.output_width * cinfo.output_components, 1);
  row_stride = cinfo.output_width * cinfo.output_components;

  while (cinfo.output_scanline < cinfo.output_height) {
    jpeg_read_scanlines(&cinfo, buffer + cinfo.output_scanline, cinfo.output_height - cinfo.output_scanline);
    for (int i = 0; i < row_stride; i++) {
      SHA256_Update(&ctx, buffer[i], row_stride);
    }
  }

  jpeg_finish_decompress(&cinfo);
  jpeg_destroy_decompress(&cinfo);
  fclose(infile);

  return info;
}
```
