// Define the struct for the weighted, labeled, and linked list of elements
struct element {
    double score;
    char label;
    struct element* next;
};

struct element* allocate_list(int N, int M, double min_score, double max_score) {
    // Validate input parameters
    if (N <= 0 || M <= 0 || min_score >= max_score) {
        return NULL;
    }

    // Allocate memory for the weights and labels arrays
    double* weights = malloc(sizeof(double) * N);
    char* labels = malloc(sizeof(char) * N);
    struct element** nodes = malloc(sizeof(struct element*) * M);

    // Initialize the weights array with random values between 0.0 and 1.0
    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        weights[i] = ((double) rand() / RAND_MAX) * (max_score - min_score) + min_score;
    }

    // Initialize the labels array with random lowercase alphabetic characters
    for (int i = 0; i < N; ++i) {
        labels[i] = 'a' + rand() % 26;
    }

    // Initialize each node's score field to a random value between min_score and max_score
    for (int i = 0; i < M; ++i) {
        nodes[i]->score = ((double) rand() / RAND_MAX) * (max_score - min_score) + min_score;
    }

    // Set the next field to point to the next node in the list or NULL if it is the last element
    for (int i = 0; i < M-1; ++i) {
        nodes[i]->next = nodes[i+1];
    }
    nodes[M-1]->next = NULL;

    // Return a pointer to the dynamically allocated struct element array
    return nodes;
}
```
