#include <sys/types.h>
#include <sys/wait.h>
#include <limits.h>
#include <errno.h>
#include <stdbool.h>

// Custom logging framework
#define LOG(format, ...) printf("[%s:%d] " format "\n", __FILE__, __LINE__, ##__VA_ARGS__)

void run_rust_binary(char* binary_path, char* args[]) {
    // Check if the Rust binary is up-to-date
    struct stat buf;
    if (stat(binary_path, &buf) != 0 || !S_ISREG(buf.st_mode)) {
        LOG("Rust binary not found: %s", binary_path);
        return;
    }

    // Construct the new filename based on the original filename and append a sequence of digits
    char* new_filename = malloc(strlen(binary_path) + 10);
    sprintf(new_filename, "%s_%d", binary_path, rand());

    // Check if the new filename is too long (> PATH_MAX) and shorten it if necessary
    size_t new_filename_len = strlen(new_filename);
    if (new_filename_len > PATH_MAX - 10) {
        LOG("New filename too long: %s", new_filename);
        free(new_filename);
        return;
    }

    // Execute the Rust binary with the new filename and specified arguments
    int status = execvp(new_filename, args);
    if (status != 0) {
        LOG("Execvp failed: %s", strerror(errno));
        free(new_filename);
        return;
    }

    // Record the execution time and memory usage of the Rust binary
    struct rusage ru;
    getrusage(RUSAGE_SELF, &ru);
    LOG("Execution time: %ld.%06ld", ru.ru_utime.tv_sec, ru.ru_utime.tv_usec);
    LOG("Memory usage: %lu bytes", ru.ru_maxrss);

    // Clean up and return
    free(new_filename);
}
```']

