    (*records)[i].name = malloc(sizeof(char) * 20);
    sprintf((*records)[i].name, "Record %d", i);
  }

  // Create a linked list of records by linking each node to the next one
  struct record *current = *records;
  for (int i = 1; i < size; i++) {
    current->next = &(*records)[i];
    current = current->next;
  }
