        printf("Error: Failed to allocate memory for the new session.\n");
        return;
    }
    memcpy(new_queue, interface->queue, sizeof(TX_QUEUE_DATA_ITEM *) * interface->num_sessions);
    free(interface->queue);
    interface->queue = new_queue;

    // Initialize the queue for the new session and set its initial values
    TX_QUEUE_DATA_ITEM *queue = malloc(sizeof(TX_QUEUE_DATA_ITEM) * interface->queue_size);
    if (queue == NULL) {
        printf("Error: Failed to allocate memory for the new queue.\n");
        return;
    }
    memset(queue, 0, sizeof(TX_QUEUE_DATA_ITEM) * interface->queue_size);
    queue[0].session_id = session_id;
    queue[0].sequence_number = 1;
    queue[0].payload_size = 0;
    interface->queue[interface->num_sessions] = queue;

    // Increment the number of sessions and log the new session addition
    interface->num_sessions++;
    printf("New session added (session ID: %d).\n", session_id);
}

void removeSession(NETWORK_INTERFACE *interface, int session_id) {
    if (interface == NULL || session_id < 0) {
        return;
    }

    // Search for the session to be removed and set its status as "closed"
    int i = 0;
    while (i < interface->num_sessions && interface->queue[i]->session_id != session_id) {
        i++;
    }
    if (i == interface->num_sessions) {
        printf("Error: Failed to find the session to be removed.\n");
        return;
    }
    interface->queue[i]->status = CLOSED;

    // Free the queue for the removed session and decrement the number of sessions
    free(interface->queue[i]);
    interface->num_sessions--;
    if (interface->num_sessions > 0) {
        memcpy(interface->queue + i, interface->queue + i + 1, sizeof(TX_QUEUE_DATA_ITEM *) * (interface->num_sessions - i));
    }

    // Log the session removal
    printf("Session removed (session ID: %d).\n", session_id);
}

void addPacketToQueue(NETWORK_INTERFACE *interface, int session_id, unsigned char *data, size_t length) {
    if (interface == NULL || session_id < 0 || data == NULL || length <= 0) {
        return;
    }

    // Search for the session and set its status as "active"
    int i = 0;
    while (i < interface->num_sessions && interface->queue[i]->session_id != session_id) {
        i++;
    }
    if (i == interface->num_sessions) {
        printf("Error: Failed to find the session for adding a packet.\n");
        return;
    }
    interface->queue[i]->status = ACTIVE;

    // Increment the sequence number and set the payload size of the new packet
    interface->queue[i]->sequence_number++;
    interface->queue[i]->payload_size += length;

    // Allocate memory for the new packet and set its values
    unsigned char *new_packet = malloc(length);
    if (new_packet == NULL) {
        printf("Error: Failed to allocate memory for the new packet.\n");
        return;
    }
    memcpy(new_packet, data, length);
    interface->queue[i]->packets = realloc(interface->queue[i]->packets, sizeof(unsigned char *) * (interface->queue[i]->num_packets + 1));
    if (interface->queue[i]->packets == NULL) {
        printf("Error: Failed to allocate memory for the new packet.\n");
        free(new_packet);
        return;
    }
    interface->queue[i]->packets[interface->queue[i]->num_packets] = new_packet;
    interface->queue[i]->num_packets++;
}

void removePacketFromQueue(NETWORK_INTERFACE *interface, int session_id, unsigned char *data) {
    if (interface == NULL || session_id < 0 || data == NULL) {
        return;
    }

    // Search for the session and set its status as "active"
    int i = 0;
    while (i < interface->num_sessions && interface->queue[i]->session_id != session_id) {
        i++;
    }
    if (i == interface->num_sessions) {
        printf("Error: Failed to find the session for removing a packet.\n");
        return;
    }
    interface->queue[i]->status = ACTIVE;

    // Search for the packet to be removed and set its status as "removed"
    int j = 0;
    while (j < interface->queue[i]->num_packets && interface->queue[i]->packets[j] != data) {
        j++;
    }
    if (j == interface->queue[i]->num_packets) {
        printf("Error: Failed to find the packet to be removed.\n");
        return;
    }
    interface->queue[i]->packets[j]->status = REMOVED;

    // Free the memory for the removed packet and update the sequence number and payload size of the remaining packets
    free(interface->queue[i]->packets[j]);
    interface->queue[i]->num_packets--;
    if (interface->queue[i]->num_packets > 0) {
        memcpy(interface->queue[i]->packets + j, interface->queue[i]->packets + j + 1, sizeof(unsigned char *) * (interface->queue[i]->num_packets - j));
    }
    interface->queue[i]->sequence_number--;
    interface->queue[i]->payload_size -= interface->queue[i]->packets[j]->length;
}

int sendPacket(NETWORK_INTERFACE *interface, int session_id, unsigned char *data, size_t length) {
    if (interface == NULL || session_id < 0 || data == NULL || length <= 0) {
        return -1;
    }

    // Search for the session and set its status as "active"
    int i = 0;
    while (i < interface->num_sessions && interface->queue[i]->session_id != session_id) {
        i++;
    }
    if (i == interface->num_sessions) {
        printf("Error: Failed to find the session for sending a packet.\n");
        return -1;
    }
    interface->queue[i]->status = ACTIVE;

    // Set the status of the new packet as "sent" and encrypt it if necessary
    int j = 0;
    while (j < interface->queue[i]->num_packets && interface->queue[i]->packets[j] != data) {
        j++;
    }
    if (j == interface->queue[i]->num_packets) {
        printf("Error: Failed to find the packet for sending.\n");
        return -1;
    }
    interface->queue[i]->packets[j]->status = SENT;
    if (interface->queue[i]->encryption_method != NULL) {
        unsigned char *encrypted_data = malloc(length);
        if (encrypted_data == NULL) {
            printf("Error: Failed to allocate memory for the encrypted packet.\n");
            return -1;
        }
        int result = interface->queue[i]->encryption_method->encrypt(interface->queue[i]->encryption_key, data, length, encrypted_data);
        if (result == 0) {
            printf("Error: Failed to encrypt the packet.\n");
            free(encrypted_data);
            return -1;
        }
        memcpy(data, encrypted_data, length);
        free(encrypted_data);
    }

    // Return the status of the new packet as "sent"
    return 0;
}

int receivePacket(NETWORK_INTERFACE *interface, int session_id, unsigned char **data) {
    if (interface == NULL || session_id < 0 || data == NULL) {
        return -1;
    }

    // Search for the session and set its status as "active"
    int i = 0;
    while (i < interface->num_sessions && interface->queue[i]->session_id != session_id) {
        i++;
    }
    if (i == interface->num_sessions) {
        printf("Error: Failed to find the session for receiving a packet.\n");
        return -1;
    }
    interface->queue[i]->status = ACTIVE;

    // Search for the first unprocessed packet and set its status as "received"
    int j = 0;
    while (j < interface->queue[i]->num_packets && interface->queue[i]->packets[j]->status != RECEIVED) {
        j++;
    }
    if (j == interface->queue[i]->num_packets) {
        printf("Error: Failed to find the first unprocessed packet.\n");
        return -1;
    }
    interface->queue[i]->packets[j]->status = RECEIVED;

    // Set the output parameter as the received packet and update the sequence number and payload size of the remaining packets
    *data = interface->queue[i]->packets[j];
    interface->queue[i]->sequence_number++;
    interface->queue[i]->payload_size += length;

    // Return the status of the received packet as "received"
    return 0;
}
