    long offset;
} record_struct;

// Define the function to initialize the record structures with random integer keys within a specified range, ensuring no duplicates using a linear probing strategy for collision resolution
record_struct* init_records(int minKey, int maxKey) {
    // Initialize an array of records with the given size estimates
    int numRecords = (maxKey - minKey + 1) * 2;
    record_struct* records = malloc(sizeof(record_struct) * numRecords);

    // Initialize the keys and offsets for each record
    srand((unsigned int)time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % (maxKey - minKey + 1) + minKey;
        records[i].offset = i * sizeof(record_struct);
    }

    // Check for duplicates and handle them using linear probing
    for (int i = 0; i < numRecords; i++) {
        int key = records[i].key;
        int j = i + 1;
        while (j < numRecords && records[j].key == key) {
            // Handle duplicate keys using linear probing
            j++;
        }
        if (j == numRecords) {
            break;
        }
        records[i].key = rand() % (maxKey - minKey + 1) + minKey;
    }

    return records;
}

