// Define struct record
struct record {
    int value;
};

// Function to dynamically allocate memory for an array of records with size M
struct record** allocate_records(int M) {
    // Check if M is a positive integer
    if (M < 0) {
        return NULL;
    }

    // Allocate memory for the array of pointers
    struct record **records = malloc(sizeof(struct record*) * M);

    // Initialize each pointer to NULL
    for (int i = 0; i < M; i++) {
        records[i] = NULL;
    }

    // Return the allocated array of pointers
    return records;
}

// Function to dynamically allocate memory for an array of long integers with size N
long* allocate_offsets(int N) {
    // Check if N is a positive integer
    if (N < 0) {
        return NULL;
    }

    // Allocate memory for the array of long integers
    long *offsets = malloc(sizeof(long) * N);

    // Set each element to a random multiple of i + 1
    for (int i = 0; i < N; i++) {
        offsets[i] = i % 2 ? i + 1 : -i - 1;
