    time_t access_timestamp;
} record;

// Linked list data structure to maintain LRU ordering
typedef struct lru_node {
    record* record;
    struct lru_node* prev;
    struct lru_node* next;
} lru_node;

// Hash-based data structure for caching recent accesses
typedef struct cache_node {
    record* record;
    int size;
    struct cache_node* next;
} cache_node;

// Function to initialize the record structure and allocate memory
