    }
    new_record->value = value;
    new_record->buffer = buffer;
    new_record->access_timestamp = time(NULL);
    return new_record;
}

// Function to add a record to the linked list and cache
void add_record(record* new_record) {
    lru_node* new_lru_node = (lru_node*) malloc(sizeof(lru_node));
    if (!new_lru_node) {
        return;
    }
    new_lru_node->record = new_record;
    new_lru_node->prev = NULL;
    new_lru_node->next = head;
    head = new_lru_node;
}

// Function to remove a record from the linked list and cache
void remove_record(record* old_record) {
    lru_node* prev = NULL;
    lru_node* current = head;
    while (current != NULL && current->record != old_record) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
}

// Function to update the access timestamp for a record
void update_access_timestamp(record* record) {
    record->access_timestamp = time(NULL);
}

// Function to cache a recently accessed record
void cache_record(record* record, int size) {
    cache_node* new_cache_node = (cache_node*) malloc(sizeof(cache_node));
    if (!new_cache_node) {
        return;
    }
    new_cache_node->record = record;
    new_cache_node->size = size;
    new_cache_node->next = head_cache;
    head_cache = new_cache_node;
}

// Function to evict an LRU record from the cache and free its memory
void evict_lru() {
    lru_node* old_lru_node = head;
    head = head->next;
    free(old_lru_node);
}

// Function to evict a least recently used record from the cache and free its memory
void evict_cache(int size) {
    while (head_cache != NULL && head_cache->size > size) {
        evict_lru();
    }
}

// Function to handle errors gracefully
void handle_error(char* message) {
    printf("Error: %s\n", message);
}

// Main function to manage records and enforce memory limits
int main() {
    // Initialize the linked list head and cache head
    lru_node* head = NULL;
    cache_node* head_cache = NULL;

