public class MemoryManager {
  private static final Logger logger = LoggerFactory.getLogger(MemoryManager.class);

  // maximum limit of memory usage in bytes
  private static final int MAX_MEMORY_LIMIT = 10 * 1024 * 1024; // 10 MB

  // array of long offset values
  private long[] offsets;

  // array of integer keys
  private int[] keys;

  // total memory usage in bytes
  private long totalMemoryUsage = 0L;

  // LRU cache eviction strategy
  private Map<Integer, Long> lruCache;

  public MemoryManager(int n) {
    this.n = n;
    this.offsets = new long[n];
    this.keys = new int[n];
    this.lruCache = new HashMap<>();
  }

  public void addRecord(int key, long offset) {
    // check if the record is already in the cache
    if (this.lruCache.containsKey(key)) {
      // update the offset and move it to the end of the LRU list
      this.offsets[key] = offset;
      this.lruCache.put(key, this.lruCache.get(key));
    } else {
      // add a new record to the cache
      this.lruCache.put(key, offset);
      this.totalMemoryUsage += 8 + 4; // 8 bytes for long and 4 bytes for integer
      if (this.totalMemoryUsage > MAX_MEMORY_LIMIT) {
        // evict the least recently used record from the cache
        int evictedKey = this.lruCache.remove(this.lruCache.keySet().iterator().next());
        this.offsets[evictedKey] = 0L;
        this.totalMemoryUsage -= 8 + 4;
      }
    }
  }

  public void removeRecord(int key) {
    // check if the record is in the cache
    if (this.lruCache.containsKey(key)) {
      // remove the record from the cache and update the total memory usage
      long evictedOffset = this.offsets[key];
      this.totalMemoryUsage -= 8 + 4;
      this.lruCache.remove(key);
    }
  }

  public void executeCommand(String command, int seed) {
