      Process process = processBuilder.start();
      BufferedReader stdoutReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
      String line;
      while ((line = stdoutReader.readLine()) != null) {
        logger.info("standard output: {}", line);
      }
      BufferedReader stderrReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
      while ((line = stderrReader.readLine()) != null) {
        logger.error("standard error: {}", line);
      }
    } catch (IOException e) {
      logger.error("failed to execute command", e);
    }
  }

  public void deleteLogFile(String logFilePath) {
    // check if the log file exists and delete it if necessary
    Path path = Paths.get(logFilePath);
    if (Files.exists(path)) {
      try {
        Files.delete(path);
      } catch (IOException e) {
        logger.error("failed to delete log file", e);
      }
    }
  }

  public void rotateLogFile(String logFilePath, int n) {
    // check if the log file exists and rotate it if necessary
    Path path = Paths.get(logFilePath);
    if (Files.exists(path)) {
      try {
        Files.move(path, Paths.get(logFilePath + "." + n));
      } catch (IOException e) {
        logger.error("failed to rotate log file", e);
      }
    }
  }
}
