// Define the mutex structure to hold information about each mutex
typedef struct {
    int lock_state; // The current lock state of the mutex (0 for unlocked, 1 for locked)
    char *name; // The name of the mutex
} Mutex;

// Define the mutexes array to hold information about all mutexes
Mutex mutexes[MAX_MUTEXES];

