    if (sem_init(sem, 0, MAX_MUTEXES)) {
        perror("Failed to initialize semaphore");
        return -1;
    }
    return 0;
}

// Destroy the semaphore
int destroy_semaphore(sem_t *sem) {
    if (sem_destroy(sem)) {
        perror("Failed to destroy semaphore");
        return -1;
    }
    return 0;
}

// Acquire a mutex from the semaphore
int acquire_mutex(sem_t *sem, int index) {
    if (sem_wait(sem)) {
        perror("Failed to acquire mutex");
        return -1;
    }
    return 0;
}

// Release a mutex from the semaphore
int release_mutex(sem_t *sem, int index) {
    if (sem_post(sem)) {
        perror("Failed to release mutex");
        return -1;
    }
    return 0;
}

// Create a new mutex with the specified initial lock state
int create_mutex(char *name, int lock_state) {
    // Acquire the mutex lock
    if (pthread_mutex_lock(&mutex_lock)) {
        perror("Failed to acquire mutex lock");
        return -1;
    }

    // Find an empty slot in the mutexes array
    int i = 0;
    while (i < MAX_MUTEXES && mutexes[i].name != NULL) {
        ++i;
    }
    if (i == MAX_MUTEXES) {
        perror("Reached maximum number of allowed mutexes");
        return -1;
    }

    // Create the new mutex
    Mutex *mutex = &mutexes[i];
    mutex->name = strdup(name);
    mutex->lock_state = lock_state;

    // Release the mutex lock
    if (pthread_mutex_unlock(&mutex_lock)) {
        perror("Failed to release mutex lock");
        return -1;
    }

    return i;
}

// Delete a mutex by name
int delete_mutex(char *name) {
    // Acquire the mutex lock
    if (pthread_mutex_lock(&mutex_lock)) {
        perror("Failed to acquire mutex lock");
        return -1;
    }

    // Find the mutex by name
    int i = 0;
    while (i < MAX_MUTEXES && strcmp(name, mutexes[i].name)) {
        ++i;
    }
    if (i == MAX_MUTEXES) {
        perror("No such mutex");
        return -1;
    }

    // Delete the mutex
    free(mutexes[i].name);
    mutexes[i].name = NULL;

    // Release the mutex lock
    if (pthread_mutex_unlock(&mutex_lock)) {
        perror("Failed to release mutex lock");
        return -1;
    }

    return 0;
}

// Update the lock state of a mutex by name
int update_mutex(char *name, int new_state) {
    // Acquire the mutex lock
    if (pthread_mutex_lock(&mutex_lock)) {
        perror("Failed to acquire mutex lock");
        return -1;
    }

    // Find the mutex by name
    int i = 0;
    while (i < MAX_MUTEXES && strcmp(name, mutexes[i].name)) {
        ++i;
