}

// Process a mixed list of integers and strings from standard input
int process_mixed_list(char **input) {
    // Initialize the largest integer found so far
    int largest = INT_MIN;

    // Iterate over the input list
    for (int i = 0; input[i] != NULL; ++i) {
        // Parse the current element as an integer or string
        char *element = input[i];
        if (*element == '"') {
            char *string = parse_string(element);
            if (string == NULL) {
