package com.example.messagingbroker;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadFactory;

public class MessagingBroker {
  private final ExecutorService workerPool;
  private final MessageHandler messageHandler;
  private final Cache cache;
  private final HealthCheck healthCheck;

  public MessagingBroker(int maxWorkers, int retryLimit, long retryInterval) {
    this.workerPool = Executors.newFixedThreadPool(maxWorkers, new ThreadFactory() {
      @Override
      public Thread newThread(Runnable r) {
        return new Thread(r);
      }
    });
    this.messageHandler = new MessageHandler();
    this.cache = new Cache();
    this.healthCheck = new HealthCheck();
  }

  public void publish(String topic, String message, int qos, boolean retain) {
    // Log the message with timestamp and source/destination information
    System.out.println("Publishing message: " + message);

    // Retry mechanism for lost messages
    int retryCount = 0;
    while (retryCount < retryLimit) {
      try {
        workerPool.execute(new MessageTask(topic, message, qos, retain));
        return;
      } catch (Exception e) {
        // Log the exception and wait for the retry interval before trying again
        System.out.println("Error publishing message: " + e.getMessage());
        Thread.sleep(retryInterval);
        retryCount++;
      }
    }
  }

  public void subscribe(String topic, int qos) {
    // Log the subscription request with topic and QoS information
    System.out.println("Subscribing to topic: " + topic + " with QoS level: " + qos);

    // Create a new worker thread for the subscription task
    workerPool.execute(new SubscriptionTask(topic, qos));
  }

  public void unsubscribe(String topic) {
    // Log the unsubscription request with topic information
    System.out.println("Unsubscribing from topic: " + topic);

    // Remove the worker thread for the subscription task
    workerPool.remove(new SubscriptionTask(topic, -1));
  }

  public void setMaxWorkers(int maxWorkers) {
    this.workerPool.setMaximumPoolSize(maxWorkers);
  }

  public void setRetryLimit(int retryLimit) {
    this.retryCount = retryLimit;
  }

  public void setRetryInterval(long retryInterval) {
    this.retryInterval = retryInterval;
  }

  private class MessageTask implements Runnable {
    private final String topic;
    private final String message;
    private final int qos;
    private final boolean retain;

    public MessageTask(String topic, String message, int qos, boolean retain) {
      this.topic = topic;
      this.message = message;
      this.qos = qos;
      this.retain = retain;
    }

    @Override
    public void run() {
      // Use the cache to improve performance for frequently requested message formats
      String messageFormat = cache.get(topic);
      if (messageFormat == null) {
        // If the message format is not cached, parse it and store it in the cache
        MessageParser parser = new MessageParser();
        try {
          messageFormat = parser.parseMessageFormat(message).toUpperCase();
          cache.put(topic, messageFormat);
        } catch (Exception e) {
          // Log the exception and continue with the default message format
          System.out.println("Error parsing message format: " + e.getMessage());
        }
      }

      // Use the appropriate protocol for the message format
      Protocol protocol = null;
      if (messageFormat.equals("JSON")) {
        protocol = new JSONProtocol();
      } else if (messageFormat.equals("XML")) {
        protocol = new XMLProtocol();
      } else if (messageFormat.equals("PROTOBUF")) {
        protocol = new ProtobufProtocol();
      }

      // Use the appropriate QoS level for the subscription
      int actualQos = qos;
      if (actualQos < 0 || actualQos > 2) {
        actualQos = 1;
      }

      // Send the message to the appropriate worker thread for processing
      workerPool.execute(new MessageProcessingTask(topic, message, protocol, actualQos));
    }
  }

  private class SubscriptionTask implements Runnable {
    private final String topic;
    private final int qos;

    public SubscriptionTask(String topic, int qos) {
      this.topic = topic;
      this.qos = qos;
    }

    @Override
    public void run() {
      // Use the appropriate protocol for the subscription
      Protocol protocol = null;
      if (qos == 0) {
        protocol = new AMQPProtocol();
      } else if (qos == 1) {
        protocol = new MQTTProtocol();
      } else if (qos == 2) {
        protocol = new ProtobufProtocol();
      }

      // Send the subscription request to the appropriate worker thread for processing
      workerPool.execute(new SubscriptionProcessingTask(topic, protocol));
    }
  }

  private class MessageProcessingTask implements Runnable {
    private final String topic;
    private final String message;
    private final Protocol protocol;
    private final int qos;

    public MessageProcessingTask(String topic, String message, Protocol protocol, int qos) {
      this.topic = topic;
      this.message = message;
      this.protocol = protocol;
      this.qos = qos;
    }

    @Override
    public void run() {
      // Use the appropriate protocol for sending messages to the destination
      if (qos == 0) {
        protocol.sendMessage(message);
      } else if (qos == 1) {
        protocol.publishMessage(message);
      } else if (qos == 2) {
        protocol.publishRetainedMessage(message);
      }
    }
  }

  private class SubscriptionProcessingTask implements Runnable {
    private final String topic;
    private final Protocol protocol;

    public SubscriptionProcessingTask(String topic, Protocol protocol) {
      this.topic = topic;
      this.protocol = protocol;
    }

    @Override
    public void run() {
      // Use the appropriate protocol for sending subscription requests to the destination
      if (qos == 0) {
        protocol.subscribeToTopic(topic);
      } else if (qos == 1) {
        protocol.subscribeToTopicWithQoS(topic, qos);
      } else if (qos == 2) {
        protocol.subscribeToRetainedTopic(topic);
      }
    }
  }
}
