public class UpdateElementHandler
{
    private readonly IUpdateService _updateService;
    private readonly ILogger<UpdateElementHandler> _logger;

    public UpdateElementHandler(IUpdateService updateService, ILogger<UpdateElementHandler> logger)
    {
        _updateService = updateService;
        _logger = logger;
    }

    [HttpPost]
    public async Task<IActionResult> HandleUpdateRequestAsync(string pageSectionId, string elementId, string newHtmlContent)
    {
        try
        {
            // Validate inputs
            if (string.IsNullOrEmpty(pageSectionId))
                throw new ArgumentException("Page section ID cannot be empty", nameof(pageSectionId));
            if (string.IsNullOrEmpty(elementId))
                throw new ArgumentException("Element ID cannot be empty", nameof(elementId));
            if (string.IsNullOrEmpty(newHtmlContent))
                throw new ArgumentException("New HTML content cannot be empty", nameof(newHtmlContent));

            // Retry strategy for transient errors
            var retryCount = 0;
            while (true)
            {
                try
                {
                    await _updateService.UpdateElementAsync(pageSectionId, elementId, newHtmlContent);
                    break;
                }
                catch (Exception ex) when (ex is TransientError || retryCount < 5)
                {
                    retryCount++;
                    _logger.LogWarning(ex, $"Transient error while updating element {elementId} in page section {pageSectionId}. Retrying...");
                }
            }

            return Ok();
        }
        catch (Exception ex)
        {
            // Log and return error response
            _logger.LogError(ex, $"Failed to update element {elementId} in page section {pageSectionId}: {ex.Message}");
            return BadRequest($"Failed to update element {elementId} in page section {pageSectionId}.");
        }
    }
}

