            throw new ArgumentException("Element ID cannot be empty", nameof(elementId));
        if (string.IsNullOrEmpty(newHtmlContent))
            throw new ArgumentException("New HTML content cannot be empty", nameof(newHtmlContent));

        // Update element in database
        await _database.UpdateElementAsync(pageSectionId, elementId, newHtmlContent);
    }
}

public interface IDatabase
{
    Task UpdateElementAsync(string pageSectionId, string elementId, string newHtmlContent);
}

public class Database : IDatabase
{
    private readonly IConnectionStringProvider _connectionStringProvider;

    public Database(IConnectionStringProvider connectionStringProvider)
    {
        _connectionStringProvider = connectionStringProvider;
    }

    public async Task UpdateElementAsync(string pageSectionId, string elementId, string newHtmlContent)
    {
        // Validate inputs
        if (string.IsNullOrEmpty(pageSectionId))
            throw new ArgumentException("Page section ID cannot be empty", nameof(pageSectionId));
        if (string.IsNullOrEmpty(elementId))
            throw new ArgumentException("Element ID cannot be empty", nameof(elementId));
        if (string.IsNullOrEmpty(newHtmlContent))
            throw new ArgumentException("New HTML content cannot be empty", nameof(newHtmlContent));

        // Update element in database
        using var connection = new SqlConnection(_connectionStringProvider.GetConnectionString());
        await connection.OpenAsync();

        using var command = new SqlCommand($"UPDATE Pages SET Elements = JSON_MODIFY(Elements, '$.{elementId}', '{newHtmlContent}') WHERE Id = {pageSectionId}", connection);
        await command.ExecuteNonQueryAsync();
    }
}']

