function updateClinicStatus($clinicId, $status, $lastModifiedIpAddress, $lastModifiedDate) {
    // Validate input parameters
    if (!$clinicId || !is_int($clinicId) || empty($clinicId)) {
        throw new InvalidArgumentException('Invalid clinic ID');
    }

    if (!$status || !is_string($status) || empty($status)) {
        throw new InvalidArgumentException('Invalid status');
    }

    if (!$lastModifiedIpAddress || !is_string($lastModifiedIpAddress) || empty($lastModifiedIpAddress)) {
        throw new InvalidArgumentException('Invalid last modified IP address');
    }

    if (!$lastModifiedDate || !is_int($lastModifiedDate) || $lastModifiedDate < 0) {
        throw new InvalidArgumentException('Invalid last modified date');
    }

    // Sanitize input parameters
    $clinicId = (int)$clinicId;
    $status = sanitize($status);
    $lastModifiedIpAddress = sanitize($lastModifiedIpAddress);
    $lastModifiedDate = (int)$lastModifiedDate;

    // Implement concurrency control mechanism
    $connection = new PDO('mysql:host=localhost;dbname=healthcare', 'root', '');
    $connection->beginTransaction();

    try {
        // Update clinic status in database table
        $statement = $connection->prepare("UPDATE clinics SET status = :status, last_modified_ip_address = :lastModifiedIpAddress, last_modified_date = :lastModifiedDate WHERE id = :clinicId");
        $statement->bindValue(':status', $status);
        $statement->bindValue(':lastModifiedIpAddress', $lastModifiedIpAddress);
        $statement->bindValue(':lastModifiedDate', $lastModifiedDate);
        $statement->bindValue(':clinicId', $clinicId);
        $statement->execute();

        // Log update attempt
        $logMessage = "User $user updated clinic $clinicId status to '$status' with IP address $lastModifiedIpAddress and last modified date $lastModifiedDate";
        logUpdateAttempt($logMessage);

        // Commit transaction
        $connection->commit();

        return "Success: Clinic status updated successfully.";
    } catch (PDOException $e) {
        // Rollback transaction on error
        $connection->rollBack();

        throw new Exception('Error updating clinic status: ' . $e->getMessage());
    } finally {
        $connection = null;
    }
}

function logUpdateAttempt($message) {
    // Implement logging system
    $logFile = './logs/update-attempts.log';

    if (file_exists($logFile)) {
        $fileHandle = fopen($logFile, 'a+');
        fwrite($fileHandle, $message . PHP_EOL);
        fclose($fileHandle);
    } else {
        // Log update attempt to file
        $logMessage = "User $user updated clinic $clinicId status to '$status' with IP address $lastModifiedIpAddress and last modified date $lastModifiedDate";
        logUpdateAttempt($logMessage);
    }
}
