int log_level = 0;
char *log_format = "%Y-%m-%d %H:%M:%S [%L] %t";
char *log_file = "./logs/app.log";
char *custom_formatter = NULL;

void load_log_config(const char *filename) {
    // Open and read the log configuration file
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Failed to open log config file");
        return;
    }

    // Read the log level
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Trim leading whitespace and comments
        char *comment = strchr(line, '#');
        if (comment) *comment = '\0';
        char *trimmed_line = trim_whitespace(line);

        // Parse the log level
        int log_level = parse_log_level(trimmed_line);
        if (log_level >= 0) {
            printf("Log level: %d\n", log_level);
            this->log_level = log_level;
        } else {
            fprintf(stderr, "Invalid log level: '%s'\n", trimmed_line);
        }

        // Parse the log format
        char *log_format = parse_log_format(trimmed_line);
        if (log_format != NULL) {
            printf("Log format: %s\n", log_format);
            this->log_format = log_format;
        } else {
            fprintf(stderr, "Invalid log format: '%s'\n", trimmed_line);
        }

        // Parse the log file path
        char *log_file = parse_log_file(trimmed_line);
        if (log_file != NULL) {
            printf("Log file: %s\n", log_file);
            this->log_file = log_file;
        } else {
            fprintf(stderr, "Invalid log file path: '%s'\n", trimmed_line);
        }

        // Parse the custom formatter function
        char *custom_formatter = parse_custom_formatter(trimmed_line);
        if (custom_formatter != NULL) {
            printf("Custom formatter: %s\n", custom_formatter);
            this->custom_formatter = custom_formatter;
        } else {
            fprintf(stderr, "Invalid custom formatter function: '%s'\n", trimmed_line);
        }
    }
}

int parse_log_level(char *trimmed_line) {
    // Parse the log level from the line (e.g., "LOG_LEVEL = DEBUG")
    char *token = strtok(trimmed_line, " ");
    if (token == NULL) return -1;

    token = strtok(NULL, "=");
    if (token == NULL) return -1;

    int log_level = atoi(token);
    if (log_level < 0 || log_level > 3) return -1;

    return log_level;
}

char *parse_log_format(char *trimmed_line) {
    // Parse the log format from the line (e.g., "LOG_FORMAT = %Y-%m-%d %H:%M:%S [%L] %t")
    char *token = strtok(trimmed_line, " ");
    if (token == NULL) return NULL;

    token = strtok(NULL, "=");
    if (token == NULL) return NULL;

    char *log_format = strdup(token);
    if (log_format == NULL) {
        perror("Failed to allocate memory for log format");
        return NULL;
    }

    return log_format;
}

char *parse_log_file(char *trimmed_line) {
    // Parse the log file path from the line (e.g., "LOG_FILE = ./logs/app.log")
    char *token = strtok(trimmed_line, " ");
    if (token == NULL) return NULL;

    token = strtok(NULL, "=");
    if (token == NULL) return NULL;

    char *log_file = strdup(token);
    if (log_file == NULL) {
        perror("Failed to allocate memory for log file");
        return NULL;
    }

    return log_file;
}

char *parse_custom_formatter(char *trimmed_line) {
    // Parse the custom formatter function from the line (e.g., "CUSTOM_FORMATTER = my_custom_formatter")
    char *token = strtok(trimmed_line, " ");
    if (token == NULL) return NULL;

    token = strtok(NULL, "=");
    if (token == NULL) return NULL;

    char *custom_formatter = strdup(token);
    if (custom_formatter == NULL) {
        perror("Failed to allocate memory for custom formatter");
        return NULL;
    }

    // Check that the custom formatter function is callable
    dlerror();  // Clear any existing error
    void *handle = dlopen(NULL, RTLD_LAZY);
    if (handle == NULL) {
        perror("Failed to open shared library");
        return NULL;
    }

    dlerror();  // Clear any existing error
    void (*formatter)(const char *, int) = dlsym(handle, custom_formatter);
    if (formatter == NULL) {
        perror("Failed to find custom formatter function");
        return NULL;
    }

    return custom_formatter;
}

void trim_whitespace(char *line) {
    // Trim leading and trailing whitespace from a line
    char *start = line;
    while (isspace(*start)) start++;

    char *end = start + strlen(start) - 1;
    while (isspace(*end) && end >= start) end--;

    int len = end - start + 1;
    memmove(line, start, len);
    line[len] = '\0';
}
