char* process_filename(const char* filename, size_t size_limit, size_t max_len) {
    // Ensure the input filename is valid and not empty
    if (filename == NULL || *filename == '\0') {
        return NULL;
    }

    // Determine the number of alphanumeric characters in the filename
    int num_chars = 0;
    for (int i = 0; i < strlen(filename); i++) {
        if (isalnum(filename[i])) {
            num_chars++;
        }
    }

    // Check if the filename contains at least two alphanumeric characters
    if (num_chars < 2) {
        return NULL;
    }

    // Create a new filename by appending the number of alphanumeric characters to the original filename
    char* new_filename = malloc(max_len + 1);
    int len = snprintf(new_filename, max_len + 1, "%s.%d", filename, num_chars);

    // Check if the length of the new filename exceeds the maximum size limit
    if (len > size_limit) {
        free(new_filename);
        return NULL;
    }

    // Replace the existing file extension with a new one formed by concatenating the first and last alphanumeric character of the filename
    int ext_len = 0;
    for (int i = strlen(new_filename) - 1; i >= 0 && isalnum(new_filename[i]); i--) {
        ext_len++;
    }

    // Append a forward slash to the end of the filename if it meets the size constraint
    if (len + ext_len <= size_limit) {
        new_filename[len] = '/';
        len++;
    } else {
        free(new_filename);
        return NULL;
    }

    // Ensure the total length of the new filename does not exceed the maximum length of 255 characters
    if (len > 255) {
        free(new_filename);
        return NULL;
    }

    // Return the modified filename
    return new_filename;
}
