// Hash table struct
struct hash_table {
    int num_buckets;
    int* buckets;
};

// Hash function for integer keys
unsigned long hash(int key) {
    return (unsigned long)key;
}

// Custom validation function for input sizes
bool validate_input(int size) {
    if (size < 0 || size > MAX_SIZE) {
        return false;
    }
    return true;
}

// Dynamically allocate memory for a hash table with a given number of buckets
struct hash_table* create_hash_table(int num_buckets) {
    struct hash_table* table = malloc(sizeof(struct hash_table));
    if (table == NULL) {
        return NULL;
    }
    table->num_buckets = num_buckets;
    table->buckets = calloc(num_buckets, sizeof(int));
    if (table->buckets == NULL) {
        free(table);
        return NULL;
    }
    return table;
}

// Insert a new entry into the hash table with a specified key and value
void insert_entry(struct hash_table* table, int key, struct value val) {
    // Calculate the index of the bucket based on the hash function
    unsigned long index = hash(key) % table->num_buckets;
    // Check if the bucket is already full
    if (table->buckets[index] == NULL) {
        // Allocate memory for the new entry
        struct entry* new_entry = malloc(sizeof(struct entry));
        if (new_entry == NULL) {
            return;
        }
        new_entry->key = key;
        new_entry->val = val;
        table->buckets[index] = new_entry;
    } else {
        // Check for duplicate keys and insert the new entry at the end of the linked list
        struct entry* current = table->buckets[index];
        while (current->next != NULL) {
            if (current->key == key) {
                return;
            }
            current = current->next;
        }
        // Allocate memory for the new entry and append it to the linked list
        struct entry* new_entry = malloc(sizeof(struct entry));
        if (new_entry == NULL) {
            return;
        }
        new_entry->key = key;
        new_entry->val = val;
        current->next = new_entry;
    }
}

// Calculate the sum of all float values associated with each key in the hash table
float calculate_sum(struct hash_table* table) {
    float total = 0.0f;
    for (int i = 0; i < table->num_buckets; i++) {
        struct entry* current = table->buckets[i];
        while (current != NULL) {
            if (isfinite(current->val.arr)) {
                total += current->val.sum;
            } else {
                return NAN;
            }
            current = current->next;
        }
    }
    return total;
}

// Serialize the hash table contents into a compact binary format stored in a file
void serialize_table(struct hash_table* table, char* filename) {
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        return;
    }
    // Write the number of buckets to the file
    fwrite(&table->num_buckets, sizeof(int), 1, fp);
    for (int i = 0; i < table->num_buckets; i++) {
        struct entry* current = table->buckets[i];
        while (current != NULL) {
            // Write the key and value to the file
            fwrite(&current->key, sizeof(int), 1, fp);
            fwrite(&current->val.sum, sizeof(float), 1, fp);
            current = current->next;
        }
    }
    // Close the file and return success
    fclose(fp);
}

// Deserialize a hash table from a compact binary format stored in a file
struct hash_table* deserialize_table(char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        return NULL;
    }
    // Read the number of buckets from the file
    int num_buckets;
    fread(&num_buckets, sizeof(int), 1, fp);
    struct hash_table* table = create_hash_table(num_buckets);
    if (table == NULL) {
        fclose(fp);
        return NULL;
    }
    // Read the key-value pairs from the file and insert them into the hash table
    for (int i = 0; i < num_buckets; i++) {
        int key;
        float val;
        // Read the key and value from the file
        fread(&key, sizeof(int), 1, fp);
        fread(&val, sizeof(float), 1, fp);
        insert_entry(table, key, val);
    }
    // Close the file and return the deserialized hash table
    fclose(fp);
    return table;
}
