['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <resolv.h>
#include <unistd.h>
#include <stdbool.h>
#include <limits.h>
#include <float.h>

// Custom data structure for storing records
struct record {
    int key;
    char *value;
};

// Function to resolve hostname to IP addresses using DNS resolution
int resolve_hostname(const char *hostname, char ***ip_array) {
    // Initialize variables
    int error = 0;
    size_t n = 16;
    long *offset_array = malloc(n * sizeof(long));
    if (!offset_array) {
        error = ENOMEM;
        goto cleanup;
    }
    int *key_array = malloc(n * sizeof(int));
    if (!key_array) {
        error = ENOMEM;
        goto cleanup;
    }
    struct record *record_array = malloc(n * sizeof(struct record));
    if (!record_array) {
        error = ENOMEM;
        goto cleanup;
    }
    size_t i, j;
    char *hostname_copy = strdup(hostname);
    if (!hostname_copy) {
        error = ENOMEM;
        goto cleanup;
    }

    // Perform DNS resolution
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_DGRAM;
    error = getaddrinfo(hostname_copy, NULL, &hints, &res);
    if (error) {
        goto cleanup;
    }

    // Iterate over the DNS records and store them in a cache
    for (i = 0; res; i++) {
        struct record *record = &(record_array[i]);
        record->key = i;
        record->value = strdup(res->ai_addr);
        if (!record->value) {
            error = ENOMEM;
            goto cleanup;
        }
        offset_array[i] = (long)(&(record->value) - &(record_array[0]));
        key_array[i] = i;
        res = res->ai_next;
    }
    freeaddrinfo(res);

    // Sort the records based on their keys
    qsort(key_array, i, sizeof(int), compare_keys);
    for (j = 0; j < i; j++) {
        struct record *record = &(record_array[key_array[j]]);
        printf("%s\n", record->value);
    }

cleanup:
    // Free the memory allocated by the function
    free(offset_array);
    free(key_array);
    free(record_array);
    free(hostname_copy);

    return error;
}

// Comparison function for sorting records based on their keys
int compare_keys(const void *a, const void *b) {
    int key1 = *((int *) a);
    int key2 = *((int *) b);
    if (key1 < key2) return -1;
    else if (key1 > key2) return 1;
    else return 0;
}

// Utility class for generating random integers within specified ranges
class RandomNumberGen {
public:
    // Constructor for initializing the seed value
    RandomNumberGen(long seed) : seed_(seed) {}

    // Function to generate a uniformly distributed random integer
    int uniform_int(int min, int max) {
        long x = (long)(min + ((max - min + 1.0) * rand() / RAND_MAX));
        return (int)(x);
    }

    // Function to generate a normally distributed random integer
    int normal_int(int mean, int stddev) {
        double x = 0;
        while (true) {
            x = mean + stddev * sqrt(-2.0 * log(rand() / RAND_MAX)) * cos(2.0 * M_PI * rand() / RAND_MAX);
            if (x >= min && x <= max) break;
        }
        return (int)(x);
    }

    // Function to generate a random float within specified range
    float uniform_float(float min, float max) {
        long x = (long)(min + ((max - min + 1.0) * rand() / RAND_MAX));
        return (float)(x);
    }

    // Function to generate a normally distributed random float
    float normal_float(float mean, float stddev) {
        double x = 0;
        while (true) {
            x = mean + stddev * sqrt(-2.0 * log(rand() / RAND_MAX)) * cos(2.0 * M_PI * rand() / RAND_MAX);
            if (x >= min && x <= max) break;
        }
        return (float)(x);
    }

private:
    long seed_;
};
```
