        return -1;
    }
    struct allocator* alloc = malloc(sizeof(struct allocator));
    if (!alloc) {
        return -2;
    }
    alloc->size = size;
    alloc->memory = malloc(size);
    if (!alloc->memory) {
        free(alloc);
        return -3;
    }
    return 0;
}

int deallocate() {
    free(alloc->memory);
    free(alloc);
    return 0;
}

int resize(size_t size) {
    if (size <= 0) {
        return -1;
    }
    void* new_memory = realloc(alloc->memory, size);
    if (!new_memory) {
        return -2;
    }
    alloc->size = size;
    alloc->memory = new_memory;
    return 0;
}

int fragmentation(double threshold) {
    int fragmentation_count = 0;
    for (int i = 0; i < alloc->size; i++) {
        if (((struct sensor_data*)alloc->memory)[i].measurement == -1) {
            fragmentation_count++;
        }
    }
    return fragmentation_count;
}

int compaction(double threshold) {
    int compacted_size = 0;
    for (int i = 0; i < alloc->size; i++) {
        if (((struct sensor_data*)alloc->memory)[i].measurement != -1) {
            ((struct sensor_data*)alloc->memory)[compacted_size++] = ((struct sensor_data*)alloc->memory)[i];
        }
    }
    alloc->size = compacted_size;
    return 0;
}
