#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>

#define MAX_CONNECTIONS 1024 // maximum number of concurrent connections
#define MAX_RECORDS 1000000 // maximum number of records to be stored

// structure for a single record
struct record {
    long offset;
    int key;
    double precision_measurement;
};

// structure for the larger structure that can support multiple concurrent operations
struct data_structure {
    struct record records[MAX_RECORDS];
    size_t num_records;
    pthread_mutex_t lock; // mutex to protect the data structure from concurrent access
};

// function to generate random values within specified ranges
long generate_random(long min, long max) {
    return min + (rand() % (max - min));
}

// function to initialize a single record
void init_record(struct record *record, long offset, int key, double precision_measurement) {
    record->offset = offset;
    record->key = key;
    record->precision_measurement = precision_measurement;
}

// function to initialize a set of records randomly within specified ranges
void init_records(struct data_structure *data, long min_offset, long max_offset, int min_key, int max_key, double min_precision_measurement, double max_precision_measurement) {
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        init_record(&data->records[i], generate_random(min_offset, max_offset), generate_random(min_key, max_key), generate_random(min_precision_measurement, max_precision_measurement));
    }
    data->num_records = MAX_RECORDS;
}

// function to establish a connection to the remote service using Java Channels
void establish_connection(struct connection *conn) {
    // create a new socket
    conn->socket = socket(AF_INET, SOCK_STREAM, 0);
    if (conn->socket < 0) {
        perror("socket");
        exit(1);
    }

    // connect to the remote service
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(PORT);
    if (inet_pton(AF_INET, "localhost", &serv_addr.sin_addr) <= 0) {
        perror("inet_pton");
        exit(1);
    }
    if (connect(conn->socket, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("connect");
        exit(1);
    }
}

// function to handle connection lifecycle events such as connection attempts, data transmission, and disconnection gracefully
void handle_connection(struct connection *conn) {
    // handle connection attempts
    if (conn->socket < 0) {
        establish_connection(conn);
    }

    // handle data transmission
    while (true) {
        // read from the socket
        ssize_t bytes = recv(conn->socket, conn->buffer, BUFFER_SIZE, 0);
        if (bytes < 0) {
            perror("recv");
            exit(1);
        } else if (bytes == 0) {
            break; // connection closed by the remote service
        }

        // handle the data received from the socket
        handle_data(conn, conn->buffer, bytes);
    }

    // handle disconnection gracefully
    close(conn->socket);
}

// function to track the status of connections and record initialization processes
void log_status(struct connection *conn) {
    // log the connection status
    printf("Connection: %s\n", conn->connected ? "established" : "disconnected");

    // log the record initialization process
    if (conn->initializing) {
        printf("Initializing records...\n");
    } else {
        printf("Records initialized successfully.\n");
    }
}

// main function
int main() {
    // create a data structure for the records
    struct data_structure data;
    pthread_mutex_init(&data.lock, NULL);

    // establish connections to the remote service
    struct connection connections[MAX_CONNECTIONS];
    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        connections[i].socket = -1;
    }

    // initialize the records randomly within specified ranges
    long min_offset = 1;
    long max_offset = 1000;
    int min_key = 1;
    int max_key = 100;
    double min_precision_measurement = 0.0;
    double max_precision_measurement = 100.0;
    init_records(&data, min_offset, max_offset, min_key, max_key, min_precision_measurement, max_precision_measurement);

    // create a thread for each connection
    pthread_t threads[MAX_CONNECTIONS];
    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        struct connection *conn = &connections[i];
        conn->initializing = true; // set the initializing flag to true
        pthread_create(&threads[i], NULL, handle_connection, (void *)conn);
    }

    // join all threads
    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        struct connection *conn = &connections[i];
        pthread_join(threads[i], NULL);
    }

    return 0;
}
