    double value;
} node_t;

struct linkedlist {
    node_t *head;
    size_t length;
};

// Custom validation function for edge cases such as empty strings or overly long keys
bool validate_key(char* key) {
    if (strlen(key) == 0 || strlen(key) > MAX_KEY_LENGTH) {
        return false;
    }
    // Additional checks for edge cases, e.g., empty strings or overly long keys
    return true;
}

// Function to insert new nodes at specific positions in the linked list
void insert_node(struct linkedlist* list, char* key, double value, size_t position) {
    // Check if the input is valid and allocate memory for the new node
    if (!validate_key(key)) {
        fprintf(stderr, "Invalid key\n");
        return;
    }
    node_t* new_node = (node_t*) malloc(sizeof(node_t));
    new_node->key = key;
    new_node->value = value;

    // Insert the new node at the specified position in the linked list
    if (position >= list->length) {
        // If the position is beyond the end of the linked list, append the node to the end
        pthread_mutex_lock(&list->mutex);
        list->head = insert(list->head, new_node);
        list->length++;
        pthread_mutex_unlock(&list->mutex);
    } else {
        // If the position is within the bounds of the linked list, insert the node at that position
        pthread_mutex_lock(&list->mutex);
        list->head = insert(list->head, new_node, position);
        list->length++;
        pthread_mutex_unlock(&list->mutex);
    }
}

// Function to rehash the entire linked list onto a secondary storage medium
void rehash(struct linkedlist* list, char* filename) {
    // Open the file for writing in binary mode and check for errors
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    // Write the linked list to the file in a serialized format
    node_t* current = list->head;
    while (current != NULL) {
        fwrite(current, sizeof(node_t), 1, fp);
        current = current->next;
    }

    // Close the file and check for errors
    if (fclose(fp) == EOF) {
        perror("fclose");
    }
}

// Function to deserialize the linked list from a serialized file
struct linkedlist* deserialize(char* filename) {
    // Open the file in binary mode and check for errors
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        perror("fopen");
        return NULL;
    }

    // Allocate memory for the linked list and read it from the file
    struct linkedlist* list = malloc(sizeof(struct linkedlist));
    list->head = NULL;
    list->length = 0;
    while (1) {
        node_t* new_node = malloc(sizeof(node_t));
        size_t bytes_read = fread(new_node, sizeof(node_t), 1, fp);
        if (bytes_read == 0) {
            break;
        }
        list->head = insert(list->head, new_node);
        list->length++;
    }

    // Close the file and check for errors
    if (fclose(fp) == EOF) {
        perror("fclose");
    }

    return list;
}

// Function to search for a specific key in the linked list and return the corresponding value
double search_key(struct linkedlist* list, char* key) {
    // Check if the input is valid and allocate memory for the new node
    if (!validate_key(key)) {
        fprintf(stderr, "Invalid key\n");
        return 0.0;
    }

    // Lock the mutex before searching the linked list
    pthread_mutex_lock(&list->mutex);

    // Search for the key in the linked list and return its corresponding value
    node_t* current = list->head;
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            pthread_mutex_unlock(&list->mutex);
            return current->value;
        }
        current = current->next;
    }

    // If the key is not found in the linked list, return a default value
    pthread_mutex_unlock(&list->mutex);
    return 0.0;
}

// Function to compute the average of all numeric values stored in the nodes
double compute_average(struct linkedlist* list) {
    // Lock the mutex before iterating over the linked list
    pthread_mutex_lock(&list->mutex);

    double sum = 0.0;
    size_t count = 0;
    node_t* current = list->head;
    while (current != NULL) {
        // Check if the value is numeric and add it to the sum if so
        char* endptr;
        double value = strtod(current->value, &endptr);
        if (*endptr == '\0') {
            sum += value;
            count++;
        }
        current = current->next;
    }

    // If the linked list is empty or only contains non-numeric values, return a default average
    pthread_mutex_unlock(&list->mutex);
    if (count == 0) {
        return 0.0;
    }

    return sum / count;
}

// Function to iterate over the linked list and print each node's key and value
void print_list(struct linkedlist* list) {
    // Lock the mutex before iterating over the linked list
    pthread_mutex_lock(&list->mutex);

    node_t* current = list->head;
    while (current != NULL) {
        printf("%s: %f\n", current->key, current->value);
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}
