#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Record structure for serialization and deserialization
typedef struct {
    int value;
} record;

// Function to serialize records into a file
void serialize_records(record *records, int size) {
    // Validate input size
    if (size <= 0 || size > 2147483647) {
        return;
    }

    // Open file for writing
    FILE *fp = fopen("records.bin", "wb");
    if (fp == NULL) {
        printf("Error: Unable to open file.\n");
        return;
    }

    // Write records to file
    for (int i = 0; i < size; i++) {
        fwrite(&records[i].value, sizeof(record), 1, fp);
    }

    // Close file
    fclose(fp);
}

// Function to deserialize records from a file
void deserialize_records(record *records, int size) {
    // Validate input size
    if (size <= 0 || size > 2147483647) {
        return;
    }

    // Open file for reading
    FILE *fp = fopen("records.bin", "rb");
    if (fp == NULL) {
        printf("Error: Unable to open file.\n");
        return;
    }

    // Read records from file
    for (int i = 0; i < size; i++) {
        fread(&records[i].value, sizeof(record), 1, fp);
    }

    // Close file
    fclose(fp);
}
