using namespace std;

// Struct to represent a single sensor data point
struct SensorData {
    int timestamp;
    float temperature;
    float humidity;
};

// Class to manage the memory pool for sensor data structures
class MemoryPool {
public:
    // Constructor to initialize the memory pool with a fixed size
    MemoryPool(size_t size) : pool_(size) {}

    // Function to allocate a new memory block in the pool
    void* allocate(size_t size) {
        lock_guard<mutex> guard(pool_mutex_);
        auto block = pool_.find_free_block(size);
        if (block == nullptr) {
            throw runtime_error("MemoryPool: Not enough memory available");
        }
        block->allocated = true;
        return block;
    }

    // Function to free a memory block in the pool
    void free(void* block, size_t size) {
        lock_guard<mutex> guard(pool_mutex_);
        auto blockPtr = static_cast<char*>(block);
        auto it = find_if(pool_.begin(), pool_.end(), [&](Block b) { return b.start == blockPtr; });
        if (it == pool_.end()) {
            throw runtime_error("MemoryPool: Block not found");
        }
        it->allocated = false;
    }

private:
    // Structure to represent a single memory block in the pool
    struct Block {
        char* start;
        bool allocated;
        size_t size;

        Block(char* start, size_t size) : start(start), allocated(false), size(size) {}

        // Function to find a free memory block in the pool that fits the given size
        void* find_free_block(size_t size) {
            for (auto it = pool_.begin(); it != pool_.end(); ++it) {
                if (!it->allocated && it->size >= size) {
                    return it;
                }
            }
            return nullptr;
        }
    };

    // Vector to store all the memory blocks in the pool
    vector<Block> pool_;

    // Mutex to ensure thread safety when allocating and freeing memory blocks
    mutex pool_mutex_;
};

// Class to manage the data collection for the sensor system
class DataCollector {
public:
    // Constructor to initialize the data collector with a memory pool and a queue
    DataCollector(MemoryPool& memory_pool, queue<SensorData>& queue) : memory_pool_(memory_pool), queue_(queue) {}

    // Function to collect data from the sensor system and add it to the queue
    void collect_data() {
        lock_guard<mutex> guard(queue_mutex_);
        for (int i = 0; i < 100; ++i) {
            SensorData data = {rand(), rand(), rand()};
            queue_.push(data);
        }
    }

    // Function to process the data in the queue and add it to the memory pool
    void process_data() {
        lock_guard<mutex> guard(queue_mutex_);
        while (!queue_.empty()) {
            auto data = queue_.front();
            queue_.pop();
            memory_pool_.allocate(sizeof(SensorData));
            memcpy(memory_pool_.allocated(), &data, sizeof(SensorData));
        }
    }

private:
    // Reference to the memory pool for managing memory blocks
    MemoryPool& memory_pool_;

    // Reference to the queue for storing data points from the sensor system
    queue<SensorData>& queue_;

    // Mutex to ensure thread safety when accessing the queue and the memory pool
    mutex queue_mutex_;
};

// Class to manage the data analysis for the sensor system
class DataAnalyzer {
public:
    // Constructor to initialize the data analyzer with a memory pool and a map
    DataAnalyzer(MemoryPool& memory_pool, map<string, int>& counter) : memory_pool_(memory_pool), counter_(counter) {}

    // Function to analyze the data in the memory pool and update the counter map
    void analyze() {
        lock_guard<mutex> guard(memory_pool_mutex_);
        auto blocks = memory_pool_.get_all_blocks();
        for (auto block : blocks) {
            auto data = static_cast<SensorData*>(block.second);
            counter_[to_string(data->timestamp)]++;
        }
    }

private:
    // Reference to the memory pool for managing memory blocks
    MemoryPool& memory_pool_;

    // Reference to the map for storing the data analysis results
    map<string, int>& counter_;

    // Mutex to ensure thread safety when accessing the memory pool and the counter map
    mutex memory_pool_mutex_;
};

int main() {
