struct channel_pool {
    struct record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    semaphore_t pool_sem;
};

channel_pool_create(size_t capacity) {
    channel_pool_t pool = malloc(sizeof(struct channel_pool));
    if (pool == NULL) {
        return NULL;
    }
    pool->records = calloc(capacity, sizeof(struct record));
    if (pool->records == NULL) {
        free(pool);
        return NULL;
    }
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    semaphore_init(&pool->pool_sem, capacity - pool->count);
    return pool;
}

channel_pool_destroy(channel_pool_t pool) {
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    semaphore_destroy(&pool->pool_sem);
    free(pool);
}

void channel_pool_resize(channel_pool_t pool, size_t new_capacity) {
    if (new_capacity > 0 && new_capacity < pool->capacity * 2) {
        struct record *new_records = calloc(new_capacity, sizeof(struct record));
        if (new_records == NULL) {
            return;
        }
        pthread_mutex_lock(&pool->lock);
        for (size_t i = 0; i < pool->count; i++) {
            struct record *record = &pool->records[i];
            new_records[i] = *record;
        }
        free(pool->records);
        pool->records = new_records;
        pool->capacity = new_capacity;
        pthread_mutex_unlock(&pool->lock);
    }
}

void channel_pool_add(channel_pool_t pool, struct record *record) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count < pool->capacity) {
        pool->records[pool->count++] = *record;
    } else {
        channel_pool_resize(pool, pool->capacity * 2);
        pool->records[pool->count++] = *record;
    }
    pthread_mutex_unlock(&pool->lock);
}

void channel_pool_remove(channel_pool_t pool, struct record *record) {
    pthread_mutex_lock(&pool->lock);
    size_t i = 0;
    while (i < pool->count && pool->records[i].key != record->key) {
        i++;
    }
    if (i < pool->count) {
        struct record *tmp = &pool->records[i];
        *record = *tmp;
        memset(tmp, 0, sizeof(struct record));
    } else {
        semaphore_post(&pool->pool_sem);
    }
    pthread_mutex_unlock(&pool->lock);
}

void channel_pool_monitor(channel_pool_t pool) {
    size_t peak_count = 0;
    time_t start = time(NULL);
    while (1) {
        sleep(5);
        pthread_mutex_lock(&pool->lock);
        if (peak_count < pool->count) {
            peak_count = pool->count;
            time_t current = time(NULL);
            struct tm *current_tm = localtime(&current);
            char buffer[64];
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", current_tm);
            printf("Peak usage at %s: %zu\n", buffer, peak_count);
        }
        pthread_mutex_unlock(&pool->lock);
    }
}
