use std::collections::HashMap;
use std::mem::size_of;
use std::ops::Deref;

#[derive(Debug)]
struct Node {
    value: f64,
    label: char,
}

impl Node {
    fn new(value: f64, label: char) -> Self {
        Self {
            value,
            label,
        }
    }
}

#[derive(Debug)]
struct Tree {
    nodes: Vec<Node>,
}

impl Tree {
    fn new() -> Self {
        Self {
            nodes: vec![],
        }
    }

    fn insert(&mut self, node: Node) {
        // Find the index where the node should be inserted
        let mut index = 0;
        while index < self.nodes.len() && self.nodes[index].value <= node.value {
            index += 1;
        }

        // Insert the node at the appropriate index
        if index == self.nodes.len() {
            self.nodes.push(node);
        } else {
            self.nodes.insert(index, node);
        }
    }

    fn calculate_average(&self) -> f64 {
        let mut sum = 0f64;
        for node in &self.nodes {
            sum += node.value;
        }
        return sum / self.nodes.len() as f64;
    }
}

fn main() {
    let tree = Tree::new();
    // Insert some nodes into the tree
    tree.insert(Node::new(3.14, 'a'));
    tree.insert(Node::new(2.71, 'b'));
    tree.insert(Node::new(1.61, 'c'));
    tree.insert(Node::new(0.59, 'd'));
    // Calculate the average of all values in the tree
    let average = tree.calculate_average();
    println!("Average: {}", average);
}
