use std::collections::HashMap;
use std::io::prelude::*;
use std::fs::File;
use std::io::Error as IoError;

fn main() -> Result<(), Box<dyn Error>> {
    // Create a HashMap to store the cache
    let mut cache: HashMap<String, String> = HashMap::new();

    // Set up a file for storing the cache
    let mut file = File::create("cache.bin")?;

    // Set up a loop that reads and writes data from/to the file
    loop {
        // Read data from the file
        let mut buffer = [0u8; 4096];
        let bytes_read = file.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }

        // Check if the data is a cache miss
        let data = String::from_utf8(buffer[..bytes_read].to_vec())?;
        if !cache.contains_key(&data) {
            // Cache miss, send request to server and store response in cache
            println!("Cache miss for {}", data);
            // Send request to server and get response
            let mut stream = TcpStream::connect("localhost:8080")?;
            stream.write_all(b"GET /")?;
            stream.flush()?;
            let mut buffer = [0u8; 4096];
            let bytes_read = stream.read(&mut buffer)?;
            if bytes_read == 0 {
                break;
            }
            cache.insert(data, String::from_utf8(buffer[..bytes_read].to_vec())?);
        } else {
            // Cache hit, send response from cache to client
            let data = cache.get(&data).unwrap();
            println!("Cache hit for {}", data);
        }
    }

    Ok(())
}
