#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

typedef struct {
    time_t timestamp;
    int amount;
    char* status;
} transaction;

void parse_transaction(const char* line, transaction* t) {
    const char* delim = ", ";
    char* token = strtok((char*)line, delim);
    if (token != NULL) {
        struct tm timeinfo;
        memset(&timeinfo, 0, sizeof(timeinfo));
        strptime(token, "%Y-%m-%d %H:%M:%S", &timeinfo);
        t->timestamp = mktime(&timeinfo);
    }
    token = strtok(NULL, delim);
    if (token != NULL) {
        sscanf(token, "%d", &t->amount);
    }
    token = strtok(NULL, delim);
    if (token != NULL) {
        t->status = strdup(token);
    }
}

void* parse_transactions(void* args) {
    int fd = ((struct thread_args*)args)->fd;
    const char* filepath = ((struct thread_args*)args)->filepath;
    transaction** transactions = (transaction**)malloc(sizeof(transaction*) * 100);
    size_t num_transactions = 0;
    while ((num_transactions < 100) && (fgets(line, sizeof(line), fd) != NULL)) {
        transaction* t = (transaction*)malloc(sizeof(transaction));
        parse_transaction(line, t);
        transactions[num_transactions++] = t;
    }
    return transactions;
}

void* write_to_db(void* args) {
    // Connect to database and write the transactions to it.
}

int main() {
    int fd = open(filepath, O_RDONLY);
    struct thread_args* args = (struct thread_args*)malloc(sizeof(struct thread_args));
    args->fd = fd;
    args->filepath = filepath;
    pthread_create(&parse_transactions_thread, NULL, parse_transactions, args);
    pthread_create(&write_to_db_thread, NULL, write_to_db, args);
    pthread_join(parse_transactions_thread, NULL);
    pthread_join(write_to_db_thread, NULL);
    return 0;
}
