offset_t* alloc_offsets(size_t num_offsets) {
    offset_t* offsets = malloc(num_offsets * sizeof(offset_t));
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for offsets\n");
        return NULL;
    }
    memset(offsets, 0, num_offsets * sizeof(offset_t));
    // Align the memory allocation to an 8-byte boundary
    if (((size_t)offsets & 0x7) != 0) {
        offsets = (offset_t*)(((size_t)offsets + 0x7) & ~0x7);
    }
    return offsets;
}

