    struct record* records = malloc(num_records * sizeof(struct record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        return NULL;
    }
    memset(records, 0, num_records * sizeof(struct record));
    // Align the memory allocation to an 8-byte boundary
    if (((size_t)records & 0x7) != 0) {
        records = (struct record*)(((size_t)records + 0x7) & ~0x7);
    }
    return records;
}

// Function to set the value field of each record to a random integer within the specified range
void set_values(struct record* records, size_t num_records, int min, int max) {
    for (size_t i = 0; i < num_records; ++i) {
        // Generate a random integer between min and max
        int value = rand() % (max - min + 1) + min;
        records[i].value = malloc(sizeof(int));
        if (records[i].value == NULL) {
            printf("Error: Failed to allocate memory for record value\n");
            return;
        }
        memcpy(records[i].value, &value, sizeof(int));
    }
}

// Function to free all allocated memory in a single call
void free_memory() {
    // Free the offsets array
    offset_t* offsets = (offset_t*)malloc(sizeof(offset_t) * num_offsets);
    if (offsets != NULL) {
        free(offsets);
    }
    // Free the keys array
