    if (keys != NULL) {
        free(keys);
    }
    // Free each record's value field
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].value != NULL) {
            free(records[i].value);
        }
    }
    // Free the records array
    struct record* records = (struct record*)malloc(sizeof(struct record) * num_records);
    if (records != NULL) {
        free(records);
    }
}

