        struct record *record = record_array[i];
        if (record) {
            int current_value = gpa_array[i];
            struct record **previous_record = &record->next;
            while (*previous_record && (*previous_record)->next != NULL) {
                struct record *current_record = *previous_record;
                int current_value = gpa_array[i];
                if (order == 1) {
                    // Sort in ascending order
                    if (gpa_array[i] > gpa_array[i + 1]) {
                        current_value = gpa_array[i + 1];
                        *previous_record = current_record->next;
                        current_record->next = record;
                    } else {
                        previous_record = &current_record->next;
