// Structure to represent a network configuration entity
struct nfe_configuration {
    char* id; // ID of the NFE
    int operational_parameters[]; // Set of operational parameters
    char* metadata; // Associated metadata
};

// Structure to represent a whitelist of active IDs
struct whitelist {
    size_t capacity; // Maximum number of IDs in the list
    size_t count; // Number of currently active IDs
    char** ids; // Array of active IDs
    pthread_mutex_t lock; // Mutex for synchronizing access to the list
};

// Function to add a new NFE configuration to the whitelist
void nfe_add(struct whitelist* wl, struct nfe_configuration* conf) {
    pthread_mutex_lock(&wl->lock);
    if (wl->count == wl->capacity) {
        // Resize the array of IDs if necessary
        char** new_ids = realloc(wl->ids, 2 * wl->capacity * sizeof(char*));
        if (!new_ids) {
            pthread_mutex_unlock(&wl->lock);
            return; // Out of memory
        }
        wl->ids = new_ids;
        wl->capacity *= 2;
    }
    // Add the ID to the list if it is not already there
    char* id = conf->id;
    for (size_t i = 0; i < wl->count; ++i) {
        if (strcmp(wl->ids[i], id) == 0) {
            pthread_mutex_unlock(&wl->lock);
            return; // ID already exists, no need to add it again
        }
    }
    wl->ids[wl->count++] = strdup(id);
    pthread_mutex_unlock(&wl->lock);
}

// Function to remove an NFE configuration from the whitelist
void nfe_remove(struct whitelist* wl, char* id) {
    pthread_mutex_lock(&wl->lock);
    for (size_t i = 0; i < wl->count; ++i) {
        if (strcmp(wl->ids[i], id) == 0) {
            free(wl->ids[i]);
            memmove(&wl->ids[i], &wl->ids[i + 1], (wl->count - i - 1) * sizeof(char*));
            --wl->count;
            pthread_mutex_unlock(&wl->lock);
            return;
        }
    }
    pthread_mutex_unlock(&wl->lock);
}

// Function to check if an NFE configuration is in the whitelist
bool nfe_exists(struct whitelist* wl, char* id) {
    bool exists = false;
    pthread_mutex_lock(&wl->lock);
    for (size_t i = 0; i < wl->count; ++i) {
        if (strcmp(wl->ids[i], id) == 0) {
            exists = true;
            break;
        }
    }
    pthread_mutex_unlock(&wl->lock);
    return exists;
}

// Function to map and verify an NFE configuration against the whitelist
void nfe_map(struct whitelist* wl, struct nfe_configuration* conf) {
    char* id = conf->id;
    if (!nfe_exists(wl, id)) {
        // ID is not in the whitelist, ignore the configuration
        return;
    }
    // Update the operational parameters and metadata
    for (int i = 0; i < conf->operational_parameters_count; ++i) {
        if (conf->operational_parameters[i].id == "active") {
            conf->operational_parameters[i].value = true;
        } else if (conf->operational_parameters[i].id == "metadata") {
            free(conf->metadata); // Free the existing metadata
            conf->metadata = strdup(conf->operational_parameters[i].value);
        }
    }
}

// Function to handle a variable number of NFE configurations and map them against the whitelist
void nfe_handle_configurations(struct whitelist* wl, struct nfe_configuration** configs, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        nfe_map(wl, configs[i]);
    }
}

// Function to update the whitelist of active IDs
void nfe_update_whitelist(struct whitelist* wl, struct nfe_configuration** configs, size_t count) {
    pthread_mutex_lock(&wl->lock);
    for (size_t i = 0; i < count; ++i) {
        if (configs[i]->operational_parameters[0].value == "active") {
            nfe_add(wl, configs[i]);
        } else {
            nfe_remove(wl, configs[i]->id);
        }
    }
    pthread_mutex_unlock(&wl->lock);
}

// Function to integrate the NFE configurations into a persistent storage medium
