        if (!strcmp(token, "value")) {
            (*record)->value = atoi(strtok(NULL, ",\n"));
        } else if (!strcmp(token, "string")) {
            (*record)->string = strdup(strtok(NULL, "\n"));
            *offset = strlen((*record)->string);
