void allocate_memory(size_t *offset_array, size_t *key_array) {
    // Validate input sizes
    if (offset_array == NULL || key_array == NULL) {
        return;
    }

    // Determine memory requirements
    size_t num_offsets = 0;
    size_t num_keys = 0;
    for (size_t i = 0; i < input_size; ++i) {
        if (input[i] > offset_array[num_offsets - 1]) {
            num_offsets++;
        }
        if (input[i] < key_array[num_keys - 1]) {
            num_keys++;
        }
    }

    // Allocate memory for arrays
    offset_array = malloc(sizeof(size_t) * num_offsets);
    key_array = malloc(sizeof(int) * num_keys);

    // Fallback strategy if memory allocation fails
    if (offset_array == NULL || key_array == NULL) {
        size_t chunk_size = 1024;
        while (num_offsets > 0 && num_keys > 0) {
            offset_array = realloc(offset_array, sizeof(size_t) * num_offsets);
            key_array = realloc(key_array, sizeof(int) * num_keys);
            if (offset_array != NULL && key_array != NULL) {
                break;
            }
            num_offsets -= chunk_size;
            num_keys -= chunk_size;
        }
    }

    // Initialize arrays with input data
    for (size_t i = 0; i < input_size; ++i) {
        if (input[i] > offset_array[num_offsets - 1]) {
            offset_array[num_offsets - 1] = input[i];
