void generate_random_numbers(int min, int max) {
    // Validate input range
    if (min > max || min < 0 || max > RAND_MAX) {
        return;
    }

    // Initialize cache
    size_t num_generated = 0;
    int *cache = malloc(sizeof(int) * RAND_CACHE_SIZE);

    // Generate random numbers until cache is full
    while (num_generated < RAND_CACHE_SIZE) {
        int random_number = rand() % (max - min + 1) + min;
        if (!contains(cache, num_generated, random_number)) {
            cache[num_generated++] = random_number;
        }
    }

    // Return random number from cache
    return cache[rand() % num_generated];
}
```
