    // Check for errors in opening or serializing file
    if (output == NULL || fwrite(records, sizeof(record), num_records, output) != num_records) {
        // Fallback strategy: use temporary buffer for serialization
        size_t buffer_size = 1024;
        char *buffer = malloc(sizeof(char) * buffer_size);
        while (num_records > 0) {
            size_t num_written = fwrite(records, sizeof(record), buffer_size, output);
            if (num_written == buffer_size || num_written == 0) {
                break;
            }
            records += num_written;
            num_records -= num_written;
        }
    }

    // Close file and return success
