    int integer;  // random integer value within a specified range
} dataItem_t;

// Function to initialize an array of `dataItem` structures with unique identifiers (UUIDs) and set the integer values randomly
void initDataItems(size_t numItems, size_t minIntValue, size_t maxIntValue, dataItem_t* items) {
    // Check for valid input parameters
    assert(numItems > 0 && minIntValue < maxIntValue);

    // Initialize the UUIDs for each item in the array
    uuid_t uuid;
    size_t i;
    for (i = 0; i < numItems; i++) {
        uuid_generate(uuid);
        items[i].string = malloc(37 * sizeof(char)); // 36 characters + null terminator
        if (!items[i].string) {
            perror("Failed to allocate memory for UUID");
            exit(1);
        }
        memcpy(items[i].string, uuid, 36);
        items[i].string[36] = '\0'; // null terminator
    }

    // Generate random integer values within the specified range for each item in the array
    size_t j;
    for (j = 0; j < numItems; j++) {
        items[j].integer = minIntValue + rand() % (maxIntValue - minIntValue);
    }
}

// Function to free memory allocated by `initDataItems` when `dataItem` structures are no longer needed
void destroyDataItems(size_t numItems, dataItem_t* items) {
    // Check for valid input parameters
    assert(numItems > 0 && items != NULL);

    size_t i;
    for (i = 0; i < numItems; i++) {
        free(items[i].string);
    }
}
```
