// Struct to hold dataItem information
typedef struct {
    char *str;
    int num;
} dataItem_t;

// Dynamic array of dataItems
dataItem_t **items;
size_t itemsLen = 0;
size_t itemsCapacity = 10; // initial capacity

// Function to initialize a new item
void initItem(dataItem_t *item) {
    char uuid[37]; // UUID string length is 36 + null-terminator
    uuid_generate(uuid); // generate a random UUID
    item->str = strdup(uuid);
    item->num = rand() % 100; // set integer to random value within range
}

// Function to insert new item at specified index
void insertItem(size_t idx, dataItem_t *item) {
    if (idx > itemsLen || !item) {
        return; // invalid input
    }
    if (itemsCapacity == itemsLen) { // check capacity
        size_t newCapacity = itemsCapacity << 1; // double capacity
        dataItem_t **newItems = realloc(items, newCapacity * sizeof(dataItem_t*));
        if (!newItems) { // allocation failed
            return;
        }
        items = newItems;
        itemsCapacity = newCapacity;
    }
    for (size_t i = itemsLen; i > idx; --i) {
        items[i] = items[i - 1]; // shift existing items down
    }
    initItem(item); // initialize new item
    items[idx] = item; // store in array
    ++itemsLen; // increment length
}

// Function to remove item at specified index
void removeItem(size_t idx) {
    if (idx >= itemsLen) {
        return; // invalid input
    }
    free(items[idx]->str); // free string memory
    for (size_t i = idx; i < itemsLen - 1; ++i) {
        items[i] = items[i + 1]; // shift existing items up
    }
    --itemsLen; // decrement length
}

// Function to update item at specified index
void updateItem(size_t idx, dataItem_t *item) {
    if (idx >= itemsLen || !item) {
        return; // invalid input
    }
    free(items[idx]->str); // free old string memory
    initItem(item); // initialize new item
}

// Function to get the number of items in the array
size_t getNumItems() {
    return itemsLen;
}

// Function to retrieve an item from the array by index
dataItem_t *getItem(size_t idx) {
    if (idx >= itemsLen) {
        return NULL; // invalid input
    }
    return items[idx];
}

// Function to free all memory allocated for the array and its contents
void freeItems() {
    for (size_t i = 0; i < itemsLen; ++i) {
        free(items[i]->str); // free string memory
        free(items[i]); // free dataItem structure memory
    }
    free(items); // free array memory
}

// Function to print an item to stdout
void printItem(dataItem_t *item) {
    printf("{%s, %d}\n", item->str, item->num);
}

// Function to print all items in the array to stdout
void printAllItems() {
    for (size_t i = 0; i < itemsLen; ++i) {
        printItem(items[i]);
    }
}

int main() {
    srand(time(NULL)); // seed random number generator
    insertItem(0, NULL); // insert initial item at index 0
    for (size_t i = 1; i < 10; ++i) {
        dataItem_t *item = malloc(sizeof(dataItem_t));
        initItem(item); // initialize new item
        insertItem(i, item); // insert new item at index i
    }
    printAllItems(); // print all items
    for (size_t i = 0; i < 5; ++i) {
        removeItem(rand() % 10); // remove random item
    }
    printAllItems(); // print updated array
    freeItems(); // free all memory allocated for the array and its contents
    return 0;
}']

