#include <uuid/uuid.h> // For UUID generation

// Custom data item structure
typedef struct {
    char* string;
    int integer;
} dataItem_t;

// Data item initialization function
void initDataItem(dataItem_t* item) {
    // Generate a unique identifier using the UUID library
    uuid_t uuid;
    uuid_generate(uuid);
    char* string = uuid_unparse(uuid);

    // Set integer to a random value within a specified range
    item->integer = rand() % 100 + 1;

    // Allocate memory for the string
    item->string = malloc(strlen(string) + 1);
    strcpy(item->string, string);
}

// Data item deallocation function
void freeDataItem(dataItem_t* item) {
    if (item->string != NULL) {
        free(item->string);
        item->string = NULL;
    }
}

// Array initialization function
void initArray(dataItem_t** array, int size) {
    // Allocate memory for the array of data items
    *array = malloc(size * sizeof(dataItem_t));

    // Initialize each data item in the array
    for (int i = 0; i < size; i++) {
        initDataItem(&(*array)[i]);
    }
}

// Array deallocation function
void freeArray(dataItem_t** array) {
    if (*array != NULL) {
        // Deallocate memory for each data item in the array
        for (int i = 0; i < size; i++) {
            freeDataItem(&(*array)[i]);
        }

        // Deallocate memory for the array itself
        free(*array);
        *array = NULL;
    }
}

// Configuration structure
typedef struct {
    int logRotationInterval;
    int maxLogFileSize;
    char* retentionPolicy;
} config_t;

// Load configuration from file
void loadConfig(config_t* config, const char* filename) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: Could not open configuration file\n");
        return;
    }

    // Read the log rotation interval from the file
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        if (strncmp(line, "logRotationInterval", strlen("logRotationInterval")) == 0) {
            config->logRotationInterval = atoi(line + strlen("logRotationInterval"));
        } else if (strncmp(line, "maxLogFileSize", strlen("maxLogFileSize")) == 0) {
            config->maxLogFileSize = atoi(line + strlen("maxLogFileSize"));
        } else if (strncmp(line, "retentionPolicy", strlen("retentionPolicy")) == 0) {
            config->retentionPolicy = malloc(strlen(line + strlen("retentionPolicy")));
            strcpy(config->retentionPolicy, line + strlen("retentionPolicy"));
        }
    }

    // Close the configuration file
    fclose(fp);
}
