#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structure to store records
typedef struct Record {
    int key;
    long offset;
} Record;

// Define the dynamic arrays to store offsets and keys
Record *records = NULL;
int *keys = NULL;

// Function to allocate memory for the record array
void alloc_record_array(int size) {
    records = (Record *) malloc(sizeof(Record) * size);
}

// Function to allocate memory for the key array
void alloc_key_array(int size) {
    keys = (int *) malloc(sizeof(int) * size);
}

// Function to initialize a record with a random value within a specified range
void init_record(Record *rec, int min, int max) {
    rec->key = rand() % (max - min + 1) + min;
}

// Function to handle concurrent access from multiple threads
void lock_mutex(pthread_mutex_t *mutex) {
    pthread_mutex_lock(mutex);
}

void unlock_mutex(pthread_mutex_t *mutex) {
    pthread_mutex_unlock(mutex);
}

// Function to insert a new record into the array
void insert_record(Record rec, int key) {
    // Lock the mutex before modifying the shared data structures
    lock_mutex(&mutex);

    // Check if the arrays have been allocated
    if (records == NULL || keys == NULL) {
        alloc_record_array(10000);
        alloc_key_array(10000);
    }

    // Find an empty slot in the records array
    int i;
    for (i = 0; i < size(records); i++) {
        if (records[i].offset == -1) {
            break;
        }
    }

    // Initialize the record and key arrays
    init_record(&records[i], min, max);
    records[i].key = key;

    // Unlock the mutex after modifying the shared data structures
    unlock_mutex(&mutex);
}

// Function to delete a record from the array
void delete_record(int index) {
    // Lock the mutex before modifying the shared data structures
    lock_mutex(&mutex);

    // Check if the record exists and is not already deleted
    if (records[index].offset != -1 && records[index].key != NULL) {
        records[index].offset = -1;
        records[index].key = NULL;
    }

    // Unlock the mutex after modifying the shared data structures
    unlock_mutex(&mutex);
}

// Function to lookup a record in the array by key
Record *lookup_record(int key) {
    // Lock the mutex before reading the shared data structures
    lock_mutex(&mutex);

    // Check if the record exists and is not already deleted
    for (int i = 0; i < size(records); i++) {
        if (records[i].key == key) {
            return &records[i];
        }
    }

    // Unlock the mutex after reading the shared data structures
    unlock_mutex(&mutex);

    // Return NULL if no record is found
    return NULL;
}

// Function to update a record's key value
void update_key(Record *rec, int new_key) {
    // Lock the mutex before modifying the shared data structures
    lock_mutex(&mutex);

    // Check if the record exists and is not already deleted
    if (rec->offset != -1 && rec->key != NULL) {
        rec->key = new_key;
    }

    // Unlock the mutex after modifying the shared data structures
    unlock_mutex(&mutex);
}

// Function to update a record's offset value
void update_offset(Record *rec, long new_offset) {
    // Lock the mutex before modifying the shared data structures
    lock_mutex(&mutex);

    // Check if the record exists and is not already deleted
    if (rec->offset != -1 && rec->key != NULL) {
        rec->offset = new_offset;
    }

    // Unlock the mutex after modifying the shared data structures
    unlock_mutex(&mutex);
}

// Function to clean up allocated memory and release all resources
void free_memory() {
    if (records != NULL) {
        free(records);
        records = NULL;
    }

    if (keys != NULL) {
        free(keys);
        keys = NULL;
    }
}

