// C function to manage dynamic memory allocation for two collections of structures in a production environment
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} Collection1Entry;

typedef struct {
    double value;
    char *buffer;
} Collection2Entry;

// Shared collections of structures
Collection1Entry *collection1 = NULL;
Collection2Entry *collection2 = NULL;

// Lock for synchronizing access to shared resources
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initCollections(int collectionSize) {
    // Allocate memory for both collections
    collection1 = malloc(sizeof(Collection1Entry) * collectionSize);
    collection2 = malloc(sizeof(Collection2Entry) * collectionSize);

    // Initialize random values and unique strings for each entry
    srand(time(NULL));
    for (int i = 0; i < collectionSize; i++) {
        collection1[i].offset = rand() % 100000;
        collection1[i].key = rand() % 1000;

        char *str = generateUniqueString();
        collection2[i].buffer = malloc(strlen(str) + 1);
        strcpy(collection2[i].buffer, str);
    }
}

void destroyCollections() {
    // Free memory for both collections
    free(collection1);
    free(collection2);
}

char *generateUniqueString() {
    // Generate a unique string from an external service with limited request capabilities
    return "unique_string";
}

void updateCollection1Entry(int index, long offset) {
    // Update the offset value for the given entry in collection 1
    pthread_mutex_lock(&lock);
    collection1[index].offset = offset;
    pthread_mutex_unlock(&lock);
}

void updateCollection2Entry(int index, double value) {
    // Update the value for the given entry in collection 2
    pthread_mutex_lock(&lock);
    collection2[index].value = value;
    pthread_mutex_unlock(&lock);
}

void updateCollection1And2Entries(int index, long offset, double value) {
    // Update both the offset and value for the given entry in both collections
    pthread_mutex_lock(&lock);
    collection1[index].offset = offset;
    collection2[index].value = value;
    pthread_mutex_unlock(&lock);
}

void adjustCollectionSizes(int newSize) {
    // Adjust the size of both collections based on runtime needs
    pthread_mutex_lock(&lock);
    collection1 = realloc(collection1, sizeof(Collection1Entry) * newSize);
    collection2 = realloc(collection2, sizeof(Collection2Entry) * newSize);
    for (int i = 0; i < newSize; i++) {
        // Initialize random values and unique strings for each entry in both collections
        collection1[i].offset = rand() % 100000;
        collection1[i].key = rand() % 1000;

        char *str = generateUniqueString();
        collection2[i].buffer = malloc(strlen(str) + 1);
        strcpy(collection2[i].buffer, str);
    }
    pthread_mutex_unlock(&lock);
}

void logMemoryAllocationEvent(int index, long offset, double value, char *buffer) {
    // Log memory allocation and deallocation events for debugging and performance analysis
    printf("Memory allocation event: index=%d, offset=%ld, value=%.2f, buffer=%s\n", index, offset, value, buffer);
}

void logMemoryDeallocationEvent(int index, long offset, double value, char *buffer) {
    // Log memory deallocation events for debugging and performance analysis
    printf("Memory deallocation event: index=%d, offset=%ld, value=%.2f, buffer=%s\n", index, offset, value, buffer);
}
