}

// Function to manage dynamic memory allocation for records
struct Record* create_record(int key, double timestamp, const char* string_field, size_t max_length) {
    struct Record* record = (struct Record*)malloc_record(sizeof(struct Record));
    if (!record) {
        return NULL;
    }
    record->key = key;
    record->timestamp = timestamp;
    record->string_field = malloc_string(max_length + 1);
    if (!record->string_field) {
        free_record(record);
        return NULL;
    }
    strncpy(record->string_field, string_field, max_length);
    record->string_field[max_length] = '\0';
    return record;
}

// Function to insert a new record into the list of records while maintaining order and avoiding duplicates
int insert_record(struct Record* record, struct Record** head) {
    if (*head == NULL || record->key > (*head)->key) {
        // Insert at front of list
        record->next = *head;
        *head = record;
        return 1;
    }
    else {
        struct Record* current = *head;
        while (current->next != NULL && current->next->key <= record->key) {
            current = current->next;
        }
        if (current->next == NULL || record->key > current->next->key) {
            // Insert at end of list
            current->next = record;
            return 1;
        }
        else {
            // Duplicate key found, do not insert
            free_record(record);
            return 0;
        }
    }
}

// Function to remove a record from the list of records by its key
struct Record* remove_record(int key, struct Record** head) {
    if (*head == NULL || key < (*head)->key) {
        // Key not found in list
        return NULL;
    }
    else {
        struct Record* current = *head;
        while (current->next != NULL && current->next->key <= key) {
            current = current->next;
        }
        if (current->next == NULL || current->next->key != key) {
            // Key not found in list
            return NULL;
        }
        else {
            struct Record* record = current->next;
            current->next = record->next;
            return record;
        }
    }
}

// Function to retrieve a record from the list of records by its key
struct Record* get_record(int key, struct Record** head) {
    if (*head == NULL || key < (*head)->key) {
        // Key not found in list
        return NULL;
    }
    else {
        struct Record* current = *head;
        while (current->next != NULL && current->next->key <= key) {
            current = current->next;
        }
        if (current->next == NULL || current->next->key != key) {
            // Key not found in list
            return NULL;
        }
        else {
            return current->next;
        }
    }
}

// Function to free all records in the list and reset the list head pointer
void clear_records(struct Record** head) {
    while (*head != NULL) {
        struct Record* record = *head;
        *head = record->next;
        free_record(record);
    }
}
