#define CACHE_SIZE 10000
#define THEME_CACHE_INIT_SIZE 256
#define THEME_CACHE_RESIZE_FACTOR 2
#define AES_KEY_LEN 32
#define AES_IV_LEN 16

struct ThemeCache {
    long offset;
    int key;
};

struct ThemeCache* themeCache;
pthread_rwlock_t cacheLock;

void init_cipher_and_theme_offset_cache(const char* password) {
    int i;
    unsigned char aesKey[AES_KEY_LEN];
    unsigned char aesIv[AES_IV_LEN];

    // Initialize AES cipher using provided password
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha1(), NULL, (unsigned char*)password, strlen(password), 0, aesKey, aesIv);

    // Allocate memory for theme cache and initialize it with empty offsets and keys
    themeCache = malloc(sizeof(struct ThemeCache) * CACHE_SIZE);
    if (themeCache == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    for (i = 0; i < CACHE_SIZE; i++) {
        themeCache[i].offset = -1;
        themeCache[i].key = -1;
    }

    // Initialize lock for cache access
    pthread_rwlock_init(&cacheLock, NULL);

    // Check if the theme bitmap is already loaded from the cache
    if (themeCache->offset == -1) {
        parsePngFile("theme.png", aesKey, aesIv);
    }
}

void parsePngFile(const char* fileName, unsigned char* aesKey, unsigned char* aesIv) {
    // Open the PNG file and read its header
    FILE* fp = fopen(fileName, "rb");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    unsigned char header[8];
    fread(header, 1, 8, fp);

    // Check the PNG file's signature and determine its size
    if (header[0] != 0x89 || header[1] != 'P' || header[2] != 'N' ||
        header[3] != 'G' || header[4] != 0x0D || header[5] != 0x0A ||
        header[6] != 0x1A || header[7] != 0x0A) {
            fprintf(stderr, "Invalid PNG file\n");
            exit(EXIT_FAILURE);
    }
    unsigned long fileSize = ftell(fp) + 8;

    // Allocate memory for the decrypted PNG data and read it from the file
    unsigned char* encryptedData = malloc(fileSize - 8);
    if (encryptedData == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    fread(encryptedData, 1, fileSize - 8, fp);

    // Decrypt the PNG data using AES-256-CBC
    unsigned char* decryptedData = malloc(fileSize - 8);
    if (decryptedData == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    AES_KEY aesKeyStruct;
    AES_set_encrypt_key(aesKey, 256, &aesKeyStruct);
    AES_cbc_encrypt(encryptedData, decryptedData, fileSize - 8, &aesKeyStruct, aesIv, AES_DECRYPT);

