} PERSISTED_DATA_ITEM;

struct DataStream {
    int id;
    int active;
    long timestamp;
    size_t payload_size;
    char *buffer; // dynamic buffer
    size_t buffer_capacity;
    size_t write_index;
    size_t read_index;
    pthread_mutex_t mutex;
};

struct DataPipeline {
    int stream_count;
    struct DataStream *streams;
    char *json_buffer; // dynamic buffer
    size_t json_buffer_capacity;
    long timestamp;
