    size_t total_data_item_count;
    int retry_interval; // seconds
    int retry_jitter; // seconds
};

void configureDataProcessingPipeline(struct DataPipeline *pipeline) {
    // initialize pipeline configuration
    pipeline->stream_count = 0;
    pipeline->json_buffer_capacity = JSON_BUFFER_SIZE;
    pipeline->retry_interval = RETRY_INTERVAL;
    pipeline->retry_jitter = RETRY_JITTER;

    // allocate memory for streams and json buffer
    pipeline->streams = (struct DataStream *)malloc(MAX_STREAM_COUNT * sizeof(struct DataStream));
    pipeline->json_buffer = (char *)malloc(JSON_BUFFER_SIZE);

    if (pipeline->streams == NULL || pipeline->json_buffer == NULL) {
        printf("Error: failed to allocate memory for data streams and json buffer\n");
        exit(1);
    }
}

void addDataStreamToPipeline(struct DataPipeline *pipeline, int id) {
    // check if stream already exists
    for (int i = 0; i < pipeline->stream_count; i++) {
        if (pipeline->streams[i].id == id) {
            printf("Error: stream with ID %d already exists in the pipeline\n", id);
            return;
        }
    }

    // check for available memory slots
    if (pipeline->stream_count >= MAX_STREAM_COUNT) {
        printf("Error: maximum number of streams reached (%d)\n", MAX_STREAM_COUNT);
        return;
    }

    // add stream to pipeline
    pipeline->streams[pipeline->stream_count].id = id;
    pipeline->streams[pipeline->stream_count].active = 1;
    pipeline->streams[pipeline->stream_count].timestamp = 0;
    pipeline->streams[pipeline->stream_count].payload_size = 0;
    pipeline->streams[pipeline->stream_count].buffer = NULL;
    pipeline->streams[pipeline->stream_count].buffer_capacity = BUFFER_SIZE;
    pipeline->streams[pipeline->stream_count].write_index = 0;
    pipeline->streams[pipeline->stream_count].read_index = 0;
    pthread_mutex_init(&pipeline->streams[pipeline->stream_count].mutex, NULL);

    // update pipeline configuration
    pipeline->stream_count++;
}

void removeDataStreamFromPipeline(struct DataPipeline *pipeline, int id) {
    // find stream index
    int index = -1;
    for (int i = 0; i < pipeline->stream_count; i++) {
        if (pipeline->streams[i].id == id) {
            index = i;
            break;
        }
    }

    // check if stream exists
    if (index == -1) {
        printf("Error: stream with ID %d does not exist in the pipeline\n", id);
        return;
    }

    // remove stream from pipeline
    pthread_mutex_destroy(&pipeline->streams[index].mutex);
    free(pipeline->streams[index].buffer);
    memmove(&pipeline->streams[index], &pipeline->streams[index + 1], (pipeline->stream_count - index) * sizeof(struct DataStream));

    // update pipeline configuration
    pipeline->stream_count--;
}

void processDataItem(struct DataPipeline *pipeline, DATA_ITEM item) {
    // find stream index
    int index = -1;
    for (int i = 0; i < pipeline->stream_count; i++) {
        if (pipeline->streams[i].id == item.id) {
            index = i;
            break;
        }
    }

    // check if stream exists
    if (index == -1) {
        printf("Error: stream with ID %d does not exist in the pipeline\n", item.id);
        return;
    }

    // acquire lock on stream mutex
    pthread_mutex_lock(&pipeline->streams[index].mutex);

    // check for available buffer space
    if (pipeline->streams[index].write_index + item.payload_size > pipeline->streams[index].buffer_capacity) {
        printf("Error: buffer overflow in stream with ID %d\n", item.id);
        pthread_mutex_unlock(&pipeline->streams[index].mutex);
        return;
    }

    // add data item to stream buffer
    memcpy(pipeline->streams[index].buffer + pipeline->streams[index].write_index, &item.payload_size, sizeof(size_t));
    memcpy(pipeline->streams[index].buffer + pipeline->streams[index].write_index + sizeof(size_t), item.payload, item.payload_size);
    pipeline->streams[index].write_index += item.payload_size + sizeof(size_t);

    // update stream timestamp and payload size
    pipeline->streams[index].timestamp = item.timestamp;
    pipeline->streams[index].payload_size += item.payload_size;

    // release lock on stream mutex
    pthread_mutex_unlock(&pipeline->streams[index].mutex);
}

void processStreamBuffer(struct DataPipeline *pipeline, int index) {
    // acquire lock on stream mutex
    pthread_mutex_lock(&pipeline->streams[index].mutex);

    // check for available buffer space
    if (pipeline->streams[index].write_index == 0) {
