    } else {
        // transform and enrich JSON data here
    }

    // release lock on stream mutex
    pthread_mutex_unlock(&pipeline->streams[index].mutex);
}

void persistData(struct DataPipeline *pipeline) {
    // acquire lock on pipeline mutex
    pthread_mutex_lock(&pipeline->mutex);

    // write persisted data to disk
    for (int i = 0; i < pipeline->stream_count; i++) {
        // check if stream is active
        if (pipeline->streams[i].active) {
            // persist stream buffer
            FILE *file = fopen("data.bin", "ab");
            if (!file) {
                printf("Error: failed to open file for writing\n");
                pthread_mutex_unlock(&pipeline->mutex);
                return;
            }
            size_t written_size = fwrite(pipeline->streams[i].buffer, 1, pipeline->streams[i].write_index, file);
            if (written_size != pipeline->streams[i].write_index) {
                printf("Error: failed to write data to disk\n");
                fclose(file);
                pthread_mutex_unlock(&pipeline->mutex);
                return;
            }
            fclose(file);
        }
    }

    // release lock on pipeline mutex
    pthread_mutex_unlock(&pipeline->mutex);
}

void shutdownDataProcessingPipeline(struct DataPipeline *pipeline) {
    // acquire lock on pipeline mutex
    pthread_mutex_lock(&pipeline->mutex);

