void alloc_mem(int **array, int size) {
    // Validate input size and attempt to allocate memory
    if (size > 0 && size <= MAX_SIZE) {
        *array = malloc(sizeof(int) * size);
        if (*array == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory\n");
        }
    } else {
        fprintf(stderr, "Error: Invalid input size %d\n", size);
    }
}

// Function to fill arrays with random values
void fill_arrays(int **offset_array, int **key_array, int size) {
    // Initialize random number generator
    srand((unsigned)time(NULL));

    // Fill offset array with random values between 0 and 1000, aligned to 8-byte boundaries
    for (int i = 0; i < size; i++) {
        (*offset_array)[i] = rand() % 1000 + 1;
    }

    // Fill key array with sequential values starting from 1 up to the length of the array, optimizing for cache line utilization
    for (int i = 0; i < size; i++) {
        (*key_array)[i] = i + 1;
    }
}

// Function to allocate memory for an array of records
void alloc_records(Record **record_array, int size) {
    // Validate input size and attempt to allocate memory
    if (size > 0 && size <= MAX_SIZE) {
        *record_array = malloc(sizeof(Record) * size);
        if (*record_array == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory\n");
        }
    } else {
        fprintf(stderr, "Error: Invalid input size %d\n", size);
    }
}

// Function to fill an array of records with random values and set the value field
void fill_records(Record **record_array, int size) {
    // Initialize random number generator
    srand((unsigned)time(NULL));

    // Fill record array with random values between 1 and MAX_VALUE, aligned to 8-byte boundaries
    for (int i = 0; i < size; i++) {
        (*record_array)[i].key = rand() % MAX_KEY + 1;
        (*record_array)[i].offset = rand() % MAX_OFFSET + 1;
        (*record_array)[i].size = rand() % (MAX_SIZE - 1) + 1;
        (*record_array)[i].value = rand() % MAX_VALUE + 1;
    }
}

// Function to set the value field of each record to a random integer within a specified range
void set_values(Record **record_array, int size, int min, int max) {
    // Check if input range is valid and set appropriate values for min and max
    if (min > max) {
        fprintf(stderr, "Error: Invalid range specified %d - %d\n", min, max);
        return;
    } else if (min == max) {
        for (int i = 0; i < size; i++) {
            (*record_array)[i].value = min;
        }
    } else {
        // Set values within the specified range
        for (int i = 0; i < size; i++) {
            (*record_array)[i].value = rand() % (max - min + 1) + min;
        }
    }
}

