    int *offset_array, *key_array;
    Record *record_array;

    // Initialize input size and allocate memory for arrays of integers
    int size = 10;
    alloc_mem(&offset_array, size);
    alloc_mem(&key_array, size);

    // Fill arrays with random values and set the value field in each record structure
    fill_arrays(offset_array, key_array, size);
    alloc_records(&record_array, size);
    fill_records(record_array, size);
    set_values(record_array, size, 1, MAX_VALUE);

    // Print contents of arrays and record structures
