// Custom memory pool for managing record structures
struct MemoryPool {
    int size; // Size of the memory pool
    int used; // Used memory in the pool
    void *mem; // Pointer to the memory pool
};

// Record structure for storing integer values
struct Record {
    int value;
};

// Validate user input for array sizes and allocate memory for records
void validate_input(int long_size, int int_size) {
    // Check if input is within system limits
    if (long_size < 0 || int_size < 0 || long_size > INT_MAX || int_size > INT_MAX) {
        printf("Invalid input: array sizes must be positive and within system limits\n");
        exit(1);
    }

    // Check if input does not cause buffer overflow
    if (long_size * sizeof(struct Record) + int_size * sizeof(int) > SIZE_MAX) {
        printf("Invalid input: array sizes too large for memory allocation\n");
        exit(1);
    }
}

// Allocate memory for an array of record structures and initialize them with random values within a specified range
void allocate_records(struct Record *records, int size, int min, int max) {
    // Validate input
    if (size < 0 || min > max) {
        printf("Invalid input: size must be positive and min must be less than or equal to max\n");
        exit(1);
    }

    // Generate random values within the specified range
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (max - min + 1) + min;
    }
}

// Sort an array of record structures based on their integer values using a stable sorting algorithm
void sort_records(struct Record *records, int size, bool ascending) {
    // Validate input
    if (size < 0) {
        printf("Invalid input: size must be positive\n");
        exit(1);
    }

    // Sort the records using a stable sorting algorithm
    for (int i = 0; i < size - 1; i++) {
        int min_index = i;
        for (int j = i + 1; j < size; j++) {
            if ((ascending && records[j].value < records[min_index].value) || (!ascending && records[j].value > records[min_index].value)) {
                min_index = j;
            }
        }

        struct Record temp = records[i];
        records[i] = records[min_index];
        records[min_index] = temp;
    }
}

// Serialize an array of record structures into a file and store the sorted records
void serialize_records(struct Record *records, int size) {
    // Validate input
    if (size < 0) {
        printf("Invalid input: size must be positive\n");
        exit(1);
    }

    // Open the file for writing
    FILE *file = fopen("sorted_records.txt", "wb");
    if (!file) {
        printf("Failed to open file for writing\n");
        exit(1);
    }

    // Write the number of records to the file
    fwrite(&size, sizeof(int), 1, file);

    // Write each record to the file
    for (int i = 0; i < size; i++) {
        struct Record record = records[i];
        fwrite(&record.value, sizeof(int), 1, file);
    }

    // Close the file
    fclose(file);
}

// Deserialize an array of record structures from a file and validate their sorted status
void deserialize_records(struct Record *records, int size) {
    // Validate input
    if (size < 0) {
        printf("Invalid input: size must be positive\n");
        exit(1);
    }

    // Open the file for reading
    FILE *file = fopen("sorted_records.txt", "rb");
    if (!file) {
        printf("Failed to open file for reading\n");
        exit(1);
    }

    // Read the number of records from the file
    fread(&size, sizeof(int), 1, file);

    // Read each record from the file and validate its sorted status
    for (int i = 0; i < size - 1; i++) {
        struct Record record = records[i];
        if ((record.value > records[i + 1].value) || (record.value == records[i + 1].value && !ascending)) {
            printf("Deserialized records are not sorted\n");
            exit(1);
        }
    }

    // Close the file
    fclose(file);
}

