}

// Function to generate random floating-point numbers within a specified range
double gen_rand_float(double min, double max) {
    if (min >= max) {
        return min;
    }
    double range = max - min;
    double rand_val = ((double)rand() / RAND_MAX) * range;
    return rand_val + min;
}

