struct profile **filter_profiles(struct profile **profiles, int size, double threshold) {
    int filtered_size = 0;
    for (int i = 0; i < size; i++) {
        if (fabs(profiles[i]->value - threshold) <= DBL_EPSILON) {
            filtered_size++;
        }
    }
    struct profile **filtered_profiles = malloc(filtered_size * sizeof(struct profile));
    int j = 0;
    for (int i = 0; i < size; i++) {
        if (fabs(profiles[i]->value - threshold) <= DBL_EPSILON) {
            filtered_profiles[j] = profiles[i];
            j++;
        }
    }
    return filtered_profiles;
}

