// Sorting algorithm using merge sort with a stable variant
void mergeSort(Record** records, int count) {
    if (count <= 1) return;

    // Split the array into two halves
    int mid = count / 2;
    Record* left = *records;
    Record* right = &left[mid];

    // Recursively sort the left and right halves
    mergeSort(&left, mid);
    mergeSort(&right, count - mid);

    // Merge the sorted halves into a single array
    merge(records, left, mid, right, count - mid);
}

// Stable sorting algorithm using insertion sort with optimization for large datasets
void insertionSort(Record** records, int count) {
    if (count <= 1) return;

    // Insertion sort the array
    Record* current = *records;
    for (int i = 1; i < count; i++) {
        Record temp = current[i];
        int j = i - 1;
        while (j >= 0 && current[j].value > temp.value) {
            current[j + 1] = current[j];
            j--;
        }
        current[j + 1] = temp;
    }
}

// Serialization and deserialization functions for file storage and integrity checking
void serializeRecords(Record** records, int count) {
    FILE* fp = fopen(FILENAME, "wb");
