    if (!*records) return;

    // Read each record from the file
    for (int i = 0; i < numRecords; i++) {
        Record* record = &(*records)[i];
        fread(record, sizeof(Record), 1, fp);
    }

    fclose(fp);
}

// Custom memory pool implementation with lock-free structures
struct MemoryPool* createMemoryPool(size_t size) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) return NULL;

    pool->start = malloc(size);
    if (!pool->start) {
        free(pool);
        return NULL;
    }

    pool->end = (void*)((uintptr_t)pool->start + size - 1);
    pool->current = pool->start;

    return pool;
}

void destroyMemoryPool(struct MemoryPool* pool) {
    free(pool->start);
    free(pool);
}

// Allocate memory from the custom memory pool with lock-free structures
void* allocateMemory(size_t size, struct MemoryPool* pool) {
    if (pool->current + size > pool->end) return NULL;

    void* result = pool->current;
    pool->current += size;

    return result;
}

