    // Initialize each service instance with a unique service identifier and version number
    for (int i = 0; i < num_services; i++) {
        services[i].id = get_next_service_identifier();
        services[i].version = get_latest_service_version(services[i].id);
    }
}

/**
 * Shuffles an array of service instances randomly.
 *
 * @param services The array of service instances to shuffle
 * @param num_services The number of services in the array
 */
static void shuffle_service_instances(service_instance_t* services, int num_services) {
    // Create a random seed based on the current time
    srand((unsigned int)time(NULL));

    // Shuffle the array of service instances randomly
    for (int i = 0; i < num_services - 1; i++) {
        int j = rand() % (num_services - i);
        service_instance_t temp = services[i];
        services[i] = services[j];
        services[j] = temp;
    }
}

/**
 * Returns the next available service identifier in the pool.
 *
 * @return The next available service identifier
 */
static int get_next_service_identifier() {
    // Lock the service identifier pool mutex to prevent concurrent access
    pthread_mutex_lock(&service_id_pool_lock);

    // Check if there are any free service identifiers in the pool
    for (int i = 0; i < MAX_SERVICES; i++) {
        if (service_id_pool[i] == -1) {
            // Allocate a new service identifier
            service_id_pool[i] = num_services++;

            // Unlock the service identifier pool mutex
            pthread_mutex_unlock(&service_id_pool_lock);

            // Return the allocated service identifier
            return i;
        }
    }

    // If no free service identifiers are found, print an error message and return -1
    printf("Error: No more service identifiers available\n");
    pthread_mutex_unlock(&service_id_pool_lock);
    return -1;
}

/**
 * Returns the latest version number for a given service identifier.
 *
 * @param id The service identifier to query
 * @return The latest version number for the specified service identifier
 */
static int get_latest_service_version(int id) {
    // Check if the configuration manager has been initialized
    assert(config_manager != NULL);

    // Query the latest version number from the configuration manager
    return config_manager->get_latest_version(id);
}

/**
 * Returns a pointer to an array of service instances based on a specified number of services.
 *
 * @param num_services The number of services to allocate
 * @return A pointer to the allocated memory
 */
static service_instance_t* get_service_instances(int num_services) {
    // Allocate memory for an array of service instances
    service_instance_t* services = (service_instance_t*)allocate_service_instances(num_services);

    // Check if the allocation failed
    if (services == NULL) {
        return NULL;
    }

    // Initialize each service instance with a unique service identifier and version number
    init_service_instances(services, num_services);

    // Shuffle the array of service instances randomly to improve operational flexibility
    shuffle_service_instances(services, num_services);

    return services;
}

/**
 * Frees an array of service instances.
 *
 * @param services The array of service instances to free
 */
static void free_service_instances(service_instance_t* services) {
    // Free the allocated memory for the array of service instances
    free(services);
}

/**
 * Retrieves a list of supported operation modes for a given service identifier.
 *
 * @param id The service identifier to query
