 */
static char** get_supported_modes(int id) {
    // Check if the configuration manager has been initialized
    assert(config_manager != NULL);

    // Retrieve the latest version number for the specified service identifier
    int version = get_latest_service_version(id);

    // Query the supported operation modes from the configuration manager
    return config_manager->get_supported_modes(id, version);
}

