#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <limits.h>
#include <math.h>

// Custom memory pool for efficient record structure management
struct MemoryPool {
    long* offsets; // Array of long offset values
    int* keys; // Array of int keys
    size_t capacity; // Capacity of the memory pool
    size_t size; // Current size of the memory pool
};

// Create a new memory pool with the given capacity
struct MemoryPool createMemoryPool(size_t capacity) {
    struct MemoryPool pool = {
        malloc(capacity * sizeof(long)),
        malloc(capacity * sizeof(int)),
        capacity,
        0
    };
    return pool;
}

// Add a new record to the memory pool
void addRecordToMemoryPool(struct MemoryPool* pool, int key, long offset) {
    // Check if there is enough space in the pool
    if (pool->size == pool->capacity) {
        // Reallocate the arrays with twice the capacity
        pool->offsets = realloc(pool->offsets, 2 * pool->capacity * sizeof(long));
        pool->keys = realloc(pool->keys, 2 * pool->capacity * sizeof(int));
        pool->capacity *= 2;
    }
    // Add the record to the pool
    pool->offsets[pool->size] = offset;
    pool->keys[pool->size] = key;
    pool->size++;
}

// Sort the records in the memory pool using a stable sorting algorithm
void sortRecordsInMemoryPool(struct MemoryPool* pool, bool ascending) {
    // Choose a stable sorting algorithm based on dataset size
    if (pool->size <= 1000) {
        insertionSort(pool, ascending);
    } else {
        mergeSort(pool, ascending);
    }
}

// Insertion sort for small datasets
void insertionSort(struct MemoryPool* pool, bool ascending) {
    // Sort the records in ascending order if specified
    if (ascending) {
        for (size_t i = 1; i < pool->size; i++) {
            int key = pool->keys[i];
            long offset = pool->offsets[i];
            size_t j = i - 1;
            while (j >= 0 && pool->keys[j] > key) {
                pool->offsets[j + 1] = pool->offsets[j];
                pool->keys[j + 1] = pool->keys[j];
                j--;
            }
            pool->offsets[j + 1] = offset;
            pool->keys[j + 1] = key;
        }
    } else {
        for (size_t i = 1; i < pool->size; i++) {
            int key = pool->keys[i];
            long offset = pool->offsets[i];
            size_t j = i - 1;
            while (j >= 0 && pool->keys[j] < key) {
                pool->offsets[j + 1] = pool->offsets[j];
                pool->keys[j + 1] = pool->keys[j];
                j--;
            }
            pool->offsets[j + 1] = offset;
            pool->keys[j + 1] = key;
        }
    }
}

// Merge sort for large datasets
void mergeSort(struct MemoryPool* pool, bool ascending) {
    // Split the memory pool into two halves
    size_t half = pool->size / 2;
    struct MemoryPool left = createMemoryPool(half);
    struct MemoryPool right = createMemoryPool(pool->size - half);

    // Copy the records to the left and right memory pools
    for (size_t i = 0; i < half; i++) {
        addRecordToMemoryPool(&left, pool->keys[i], pool->offsets[i]);
    }
    for (size_t i = half; i < pool->size; i++) {
        addRecordToMemoryPool(&right, pool->keys[i], pool->offsets[i]);
    }

    // Sort the left and right memory pools recursively
    mergeSort(&left, ascending);
    mergeSort(&right, ascending);

    // Merge the sorted left and right memory pools
    mergePools(pool, &left, &right, ascending);
}

// Merge two sorted memory pools into one
void mergePools(struct MemoryPool* pool, struct MemoryPool* left, struct MemoryPool* right, bool ascending) {
    // Choose a sorting algorithm based on dataset size
    if (left->size <= 1000) {
        insertionSort(pool, ascending);
    } else {
        mergeSort(pool, ascending);
    }
}

// Compress the sorted records into a file
void compressRecordsIntoFile(struct MemoryPool* pool, FILE* file, bool concurrent) {
    // Write the records to the file in parallel if specified
    if (concurrent) {
        #pragma omp parallel for schedule(static)
        for (size_t i = 0; i < pool->size; i++) {
            fwrite(&pool->keys[i], sizeof(int), 1, file);
            fwrite(&pool->offsets[i], sizeof(long), 1, file);
        }
    } else {
        for (size_t i = 0; i < pool->size; i++) {
            fwrite(&pool->keys[i], sizeof(int), 1, file);
            fwrite(&pool->offsets[i], sizeof(long), 1, file);
        }
    }
}

// Read records from a file and add them to the memory pool
void readRecordsFromFile(struct MemoryPool* pool, FILE* file) {
    // Allocate memory for the keys and offsets arrays
    size_t size = 1000;
    pool->keys = malloc(size * sizeof(int));
    pool->offsets = malloc(size * sizeof(long));

    while (true) {
        // Read a record from the file
        int key;
        long offset;
        if (fread(&key, sizeof(int), 1, file) != 1 || fread(&offset, sizeof(long), 1, file) != 1) {
            break;
        }

        // Add the record to the pool if there is enough space
        if (pool->size == size) {
            size *= 2;
            pool->keys = realloc(pool->keys, size * sizeof(int));
            pool->offsets = realloc(pool->offsets, size * sizeof(long));
        }
        pool->keys[pool->size] = key;
        pool->offsets[pool->size] = offset;
        pool->size++;
    }
}
