// Custom memory pool with a fixed-size block allocation scheme
struct MemoryPool {
    size_t capacity;  // maximum number of elements in the pool
    size_t used;      // current number of used elements in the pool
    size_t free;      // current number of free elements in the pool
    void **data;      // array of pointers to allocated memory blocks
};

// Initialize a custom memory pool with the given capacity
void initPool(struct MemoryPool *pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
    pool->free = capacity;
    pool->data = (void **)malloc(capacity * sizeof(void *));
}

// Destroy a custom memory pool and free its resources
void destroyPool(struct MemoryPool *pool) {
    free(pool->data);
}

// Allocate a new block of memory from the pool with the given size
void *allocBlock(struct MemoryPool *pool, size_t size) {
    void *block = NULL;
    if (pool->free > 0) {
        // Find the smallest free block that can hold the requested size
        for (size_t i = 0; i < pool->capacity; ++i) {
            if (pool->data[i] != NULL && ((struct MemoryBlock *)(pool->data[i]))->size >= size) {
                block = pool->data[i];
                break;
            }
        }
        // If a suitable free block was not found, allocate a new one
        if (block == NULL) {
            struct MemoryBlock *newBlock = (struct MemoryBlock *)malloc(sizeof(struct MemoryBlock));
            newBlock->size = size;
            newBlock->data = malloc(size);
            pool->data[pool->used++] = newBlock;
            block = newBlock->data;
        } else {
            // Remove the allocated block from the free list
            struct MemoryBlock *allocatedBlock = (struct MemoryBlock *)block;
            for (size_t i = 0; i < pool->capacity; ++i) {
                if (pool->data[i] == block) {
                    memmove(&pool->data[i], &pool->data[i + 1], pool->used - i);
                    break;
                }
            }
            --pool->free;
        }
    }
    return block;
}

// Free a previously allocated memory block from the pool
void freeBlock(struct MemoryPool *pool, void *block) {
    // Find the corresponding memory block in the used list and move it to the free list
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (pool->data[i] == block) {
            struct MemoryBlock *allocatedBlock = (struct MemoryBlock *)block;
            memmove(&pool->data[i], &pool->data[i + 1], pool->used - i);
            --pool->used;
            ++pool->free;
            free(allocatedBlock->data);
            break;
        }
    }
}

// Custom memory block structure for tracking allocated memory sizes
