// Custom memory pool for efficient memory management
struct MemoryPool {
    void* buffers[MAX_BUFFERS];
    size_t buffer_sizes[MAX_BUFFERS];
    size_t current_buffer;
};

void initialize_memory_pool(MemoryPool* pool) {
    for (int i = 0; i < MAX_BUFFERS; ++i) {
        pool->buffers[i] = NULL;
        pool->buffer_sizes[i] = 0;
    }
    pool->current_buffer = 0;
}

void* allocate_memory(MemoryPool* pool, size_t size) {
    if (pool->current_buffer >= MAX_BUFFERS) {
        // Memory pool is full, return NULL
        return NULL;
    }

    void* buffer = malloc(size);
    if (!buffer) {
        // Failed to allocate memory
        return NULL;
    }

    pool->buffers[pool->current_buffer] = buffer;
    pool->buffer_sizes[pool->current_buffer] = size;
    pool->current_buffer++;

    return buffer;
}

void deallocate_memory(MemoryPool* pool, void* buffer) {
    for (int i = 0; i < MAX_BUFFERS; ++i) {
        if (pool->buffers[i] == buffer) {
            free(buffer);
            pool->buffers[i] = NULL;
            return;
        }
    }
}

// Custom hash-based data structure for efficient lookup
struct HashTable {
    struct HashNode** nodes;
    size_t num_buckets;
};

void initialize_hash_table(HashTable* table, size_t num_buckets) {
    table->num_buckets = num_buckets;
    table->nodes = (HashNode**)malloc(sizeof(HashNode*) * num_buckets);
    for (int i = 0; i < num_buckets; ++i) {
        table->nodes[i] = NULL;
    }
}

void insert_node(HashTable* table, int key, void* value) {
    size_t bucket_index = hash(key) % table->num_buckets;
    if (table->nodes[bucket_index]) {
        // Collision occurred, use linear probing to find next available slot
        for (int i = 1; i < table->num_buckets; ++i) {
            bucket_index = (bucket_index + i) % table->num_buckets;
            if (!table->nodes[bucket_index]) {
                break;
            }
        }
    }
    HashNode* new_node = (HashNode*)malloc(sizeof(HashNode));
    new_node->key = key;
    new_node->value = value;
    table->nodes[bucket_index] = new_node;
}

void* find_node(HashTable* table, int key) {
    size_t bucket_index = hash(key) % table->num_buckets;
    while (table->nodes[bucket_index]) {
        if (table->nodes[bucket_index]->key == key) {
            return table->nodes[bucket_index]->value;
        } else {
            bucket_index = (bucket_index + 1) % table->num_buckets;
        }
    }
    // Key not found in table
    return NULL;
}

void delete_node(HashTable* table, int key) {
    size_t bucket_index = hash(key) % table->num_buckets;
    while (table->nodes[bucket_index]) {
        if (table->nodes[bucket_index]->key == key) {
            free(table->nodes[bucket_index]);
            table->nodes[bucket_index] = NULL;
            return;
        } else {
            bucket_index = (bucket_index + 1) % table->num_buckets;
        }
    }
}

// Implementation of the C function
void my_function(size_t num_offsets, size_t num_keys) {
    // Allocate memory for the offset and key arrays
    long* offsets = (long*)allocate_memory(sizeof(long) * num_offsets);
    int* keys = (int*)allocate_memory(sizeof(int) * num_keys);

    // Initialize the offset and key arrays with random values within a specified range
    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = rand() % MAX_OFFSET;
    }
    for (int i = 0; i < num_keys; ++i) {
        keys[i] = rand() % MAX_KEY;
    }

    // Create a hash table to store the records
    struct HashTable* record_table = (HashTable*)malloc(sizeof(HashTable));
    initialize_hash_table(record_table, num_keys);

    // Insert the records into the hash table
    for (int i = 0; i < num_keys; ++i) {
        struct HashNode* new_node = (HashNode*)malloc(sizeof(struct HashNode));
        new_node->key = keys[i];
        new_node->value = offsets + i; // Store the offset value as the record's value
        insert_node(record_table, keys[i], new_node);
    }

    // Sort the records based on their int values using a stable sorting algorithm
    void* context = AES_get_context(); // Get the cipher context
    for (int i = 0; i < num_keys; ++i) {
        struct HashNode* node = find_node(record_table, keys[i]);
        if (!node) {
            continue;
        }
        AES_encrypt(offsets + node->value, offsets + node->value, context); // Encrypt the offset value with the cipher
    }
    AES_cleanup(context); // Clean up the cipher context

    // Serialize the sorted records into a file
    FILE* fp = fopen("record.bin", "wb");
    for (int i = 0; i < num_keys; ++i) {
        struct HashNode* node = find_node(record_table, keys[i]);
        if (!node) {
            continue;
        }
        fwrite(offsets + node->value, sizeof(long), 1, fp); // Write the encrypted offset value to the file
    }
    fclose(fp);

    // Optimize memory usage and minimize fragmentation by implementing a custom memory pool
