#include <string.h>
#include <math.h>

// Custom memory pool structure
typedef struct {
    int size;
    double *temperatures;
    char **weather_conditions;
} MemoryPool;

// Function to validate user input and handle errors gracefully
int validateInput(int num_days) {
    if (num_days <= 0) {
        printf("Error: Invalid number of days entered.\n");
        return -1;
    } else if (num_days > 365) {
        printf("Warning: Number of days exceeds maximum allowed value (365). Proceed with caution.\n");
    }
    return num_days;
}

// Function to allocate and initialize two arrays for storing temperature and weather conditions data
MemoryPool *allocateAndInitialize(int num_days) {
    // Validate user input and handle errors gracefully
    int validated_num_days = validateInput(num_days);
    if (validated_num_days == -1) {
        return NULL;
    }

    // Allocate memory for the temperature and weather conditions arrays
    MemoryPool *memory_pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    memory_pool->temperatures = (double *)calloc(num_days, sizeof(double));
    memory_pool->weather_conditions = (char **)calloc(num_days, sizeof(char *));
    for (int i = 0; i < num_days; i++) {
        memory_pool->temperatures[i] = 0.0;
        memory_pool->weather_conditions[i] = NULL;
    }

    // Return the allocated and initialized memory pool structure
    return memory_pool;
}

// Function to calculate the average temperature
double calculateAverageTemperature(MemoryPool *memory_pool) {
    // Calculate the sum of all temperatures in the memory pool
    double total = 0.0;
    for (int i = 0; i < memory_pool->size; i++) {
        total += memory_pool->temperatures[i];
    }

    // Return the average temperature
    return total / (double)memory_pool->size;
}

// Function to display only sunny weather conditions efficiently
void filterSunnyWeatherConditions(MemoryPool *memory_pool) {
    int count = 0;
    for (int i = 0; i < memory_pool->size; i++) {
        if (strcmp(memory_pool->weather_conditions[i], "Sunny") == 0) {
            count++;
        }
    }

    // Print the number of sunny weather conditions found
    printf("Number of sunny weather conditions: %d\n", count);
}

// Function to export weather data in CSV format
void exportWeatherData(MemoryPool *memory_pool, char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        printf("Error: Could not open file for writing.\n");
        return;
    }

    // Write the header line to the CSV file
    fprintf(file, "Date,Temperature,Weather Condition\n");

    // Write each data point to the CSV file
    for (int i = 0; i < memory_pool->size; i++) {
        char *date = getDateString(i);
        fprintf(file, "%s,%f,%s\n", date, memory_pool->temperatures[i], memory_pool->weather_conditions[i]);
    }

    // Close the file
    fclose(file);
}

// Function to handle thread-safe access to weather data and synchronize concurrent access
void synchronizedAccessToWeatherData(MemoryPool *memory_pool) {
    // Implement thread-safe access to weather data using a mutex lock
    pthread_mutex_lock(&memory_pool->mutex);
    // Perform any necessary operations on the memory pool here...
    pthread_mutex_unlock(&memory_pool->mutex);
}

// Function to optimize memory allocation and deallocation patterns for improved performance
void optimizeMemoryAllocation(MemoryPool *memory_pool) {
    // Implement a custom memory pool using a linked list data structure
    struct MemoryNode {
        double temperature;
        char *weather_condition;
        struct MemoryNode *next;
    };

    // Create a new node in the linked list for each data point
    struct MemoryNode *node = (struct MemoryNode *)malloc(sizeof(struct MemoryNode));
    node->temperature = 0.0;
    node->weather_condition = NULL;
    node->next = memory_pool->head;
    memory_pool->head = node;
}

// Function to write comprehensive unit tests for all implemented functions
void writeUnitTests() {
    // Implement unit tests for each function here...
}
