// Custom hash-based data structure for efficient lookup
typedef struct {
    int *values;
    size_t capacity;
    size_t size;
} HashTable;

// Function to initialize a custom hash table with the given size
void init_hash_table(HashTable *ht, size_t size) {
    ht->values = (int *)malloc(size * sizeof(int));
    ht->capacity = size;
    ht->size = 0;
}

// Function to insert a value into the hash table and return its index
int insert_value(HashTable *ht, int value) {
    // Handle edge cases where the range might be invalid
    if (value < 0 || value > 1000000) {
        fprintf(stderr, "Invalid value\n");
        return -1;
    }

    // Calculate the index for the given value in the hash table
    size_t index = value % ht->capacity;

    // Check if the slot is already occupied and handle collision
    while (ht->values[index] != 0) {
        index = (index + 1) % ht->capacity;
    }

    // Insert the value into the hash table and return its index
    ht->values[index] = value;
    ht->size++;
    return index;
}

// Function to retrieve a value from the hash table based on its index
int get_value(HashTable *ht, int index) {
    // Handle edge cases where the index might be invalid
    if (index < 0 || index >= ht->capacity) {
        fprintf(stderr, "Invalid index\n");
        return -1;
    }

    // Return the value from the given index in the hash table
    return ht->values[index];
}
