} node_t;

// Define a function to update each node's integer field using a provided function
void traversal_func(node_t* head, void (*update_func)(int*, char*)) {
    // Initialize the current node pointer to the head of the list
    node_t* curr = head;

    // Loop through the list and update each node's integer field
    while (curr != NULL) {
        // Call the provided function to calculate a new value for the current node's integer field
        int new_value = (*update_func)(&(curr->data), curr->str);

