// Define record structure
typedef struct {
    int value;
} Record;

// Allocate memory for array of records
Record* allocateRecords(int num_records) {
    // Validate input and handle errors
    if (num_records < 0 || num_records > INT_MAX) {
        return NULL;
    }

    // Allocate memory for array of records
    Record* records = malloc(sizeof(Record) * num_records);
    if (records == NULL) {
        return NULL;
    }

    // Initialize each record with a random value within range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % INT_MAX + 1;
    }

    return records;
}

// Free memory allocated for array of records
void freeRecords(Record* records, int num_records) {
    // Validate input and handle errors
    if (num_records < 0 || num_records > INT_MAX) {
        return;
    }

    // Free memory for array of records
    free(records);
}

// Sort array of records using stable sorting algorithm
void sortRecords(Record* records, int num_records) {
    // Validate input and handle errors
    if (num_records < 0 || num_records > INT_MAX) {
        return;
    }

    // Use quicksort for small datasets, mergesort for larger ones
    if (num_records <= 10) {
        quickSort(records, 0, num_records - 1);
    } else {
        mergeSort(records, 0, num_records - 1);
    }
}

// Implement stable sorting algorithm using merge sort
void mergeSort(Record* records, int low, int high) {
    if (low >= high) {
        return;
    }

    // Divide into smaller arrays and sort each one recursively
    int mid = (low + high) / 2;
    mergeSort(records, low, mid);
    mergeSort(records, mid + 1, high);

    // Merge sorted subarrays
    merge(records, low, mid, high);
}

// Implement quicksort algorithm
void quickSort(Record* records, int low, int high) {
    if (low >= high) {
        return;
    }

    // Select a pivot and partition the array around it
    int pivot = records[low];
    int i = low + 1;
    for (int j = low + 1; j <= high; j++) {
        if (records[j] < pivot) {
            swap(&records[i], &records[j]);
            i++;
        }
    }

    // Sort left and right subarrays recursively
    quickSort(records, low, i - 1);
    quickSort(records, i, high);
}

// Implement swap function for sorting
void swap(Record* a, Record* b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}
