struct MemoryPool {
  void* data;
  size_t size;
};

void initMemoryPool(struct MemoryPool* pool) {
  pool->data = NULL;
  pool->size = 0;
}

void* allocate(struct MemoryPool* pool, size_t size) {
  if (pool->size == 0 || pool->data + pool->size < pool->data + size) {
    return NULL;
  }

  void* data = pool->data + pool->size - size;
  pool->size -= size;

  return data;
}

