// Node structure to store key and pointer to next node
typedef struct node {
    int key;
    struct node* next;
} node_t;

// Function to dynamically allocate memory for an array of nodes
node_t* create_nodes(int num_nodes) {
    // Allocate memory for the array of nodes
    node_t* nodes = (node_t*) malloc(num_nodes * sizeof(node_t));

    // Initialize each node with a key and next pointer
    for (int i = 0; i < num_nodes; i++) {
        nodes[i].key = i + 1;
        nodes[i].next = NULL;
    }

    return nodes;
}

// Function to add new nodes to the list at the end, ensuring validity
void insert_node(node_t* head, int key) {
    // Create a new node with the given key
    node_t* new_node = (node_t*) malloc(sizeof(node_t));
    new_node->key = key;
    new_node->next = NULL;

    // Traverse the list until the end is reached
    while (head != NULL) {
        if (head->next == NULL) {
            head->next = new_node;
            break;
        } else {
            head = head->next;
        }
    }
}

// Function to traverse the list and print the keys of all nodes
void traverse_and_print(node_t* head) {
    while (head != NULL) {
        printf("%d ", head->key);
        head = head->next;
    }
}

// Function to safely free all allocated memory when the list is no longer needed
void destroy_nodes(node_t* head) {
    // Traverse the list and free each node's memory
    while (head != NULL) {
        node_t* current = head;
        head = head->next;
        free(current);
    }
}
