    pthread_mutex_t mutex;
    metadata_array_t* metadata_array;
} file_cache_t;

// Initialize the file cache instance
int file_cache_init(file_cache_t* cache, compression_funcs_t* library) {
    int ret = 0;

    // Allocate memory for the metadata database
    cache->metadata_db.metadata_db = malloc(sizeof(file_metadata_t) * MAX_METADATA_SIZE);
    if (!cache->metadata_db.metadata_db) {
        ret = -1;
        goto error;
    }

    // Allocate memory for the metadata array
    cache->metadata_array = malloc(sizeof(metadata_array_t));
    if (!cache->metadata_array) {
        ret = -1;
        goto error;
    }

    // Initialize the mutex and lock-free data structure
    pthread_mutex_init(&cache->mutex, NULL);
    metadata_array_t* metadata_array = cache->metadata_array;
    metadata_array->array = malloc(sizeof(file_metadata_t) * MAX_METADATA_SIZE);
    metadata_array->capacity = MAX_METADATA_SIZE;
    metadata_array->size = 0;

    // Set the compression library instance
    cache->compression_library = library;

    return ret;

error:
    free(cache->metadata_db.metadata_db);
    free(cache->metadata_array);
    pthread_mutex_destroy(&cache->mutex);
    return ret;
}

// Release the file cache instance
int file_cache_release(file_cache_t* cache) {
    int ret = 0;

    // Release memory for the metadata database
    free(cache->metadata_db.metadata_db);

    // Release memory for the metadata array
    free(cache->metadata_array->array);

    // Destroy the mutex and lock-free data structure
    pthread_mutex_destroy(&cache->mutex);

    return ret;
}

// Insert a new file into the cache
