    if (cache->metadata_array->size >= MAX_METADATA_SIZE - 1) {
        ret = -1;
        goto error;
    }

    // Compress the data using the specified compression library
    size_t compressed_size = cache->compression_library->compress(data, size, &cache->metadata_db.metadata_db[offset].data);
    if (compressed_size == 0) {
        ret = -1;
        goto error;
    }

    // Update the metadata database with the new file metadata
    cache->metadata_db.metadata_db[offset].offset = offset;
    cache->metadata_db.metadata_db[offset].size = size;
    cache->metadata_db.total_memory_usage += compressed_size;

