    return ret;
}

// Update the metadata of a file in the cache
int file_cache_update(file_cache_t* cache, long offset, char* data) {
    int ret = 0;
    pthread_mutex_lock(&cache->mutex);

    // Check if the specified offset exists in the metadata database
    if (offset >= MAX_METADATA_SIZE || offset < 0) {
        ret = -1;
        goto error;
    }

    // Decompress the data using the specified compression library
