        offsets[i] = -1;
    }
    for (size_t i = 0; i < num_keys; i++) {
        keys[i] = -1;
    }

    // Open the file for reading
    file = fopen(filepath, "r");
    if (!file) {
        perror("fopen");
        return;
    }

    // Read the resource bundle from the file
    size_t record_index = 0;
    Record *prev_record = NULL;
    while (fgets(line, sizeof(line), file)) {
        // Parse the line to extract the record value and string
        char *value_str = strtok(line, ",");
        char *string_str = strtok(NULL, "\n");
        int value = atoi(value_str);
        char *string = malloc((strlen(string_str) + 1) * sizeof(*string));
        strcpy(string, string_str);

        // Allocate memory for the record and its string
        Record *new_record = malloc(sizeof(*new_record));
        new_record->value = value;
        new_record->string = string;

        // Add the record to the list
        if (prev_record) {
            prev_record->next = new_record;
        } else {
            record = new_record;
        }
        prev_record = new_record;

        // Update the array of offsets and keys
        offsets[record_index] = ftell(file);
        keys[record_index++] = value;
    }

    // Close the file
    fclose(file);

    // Free the memory for the record allocation
    Record *current_record = record;
    while (current_record) {
        Record *next_record = current_record->next;
        free(current_record->string);
        free(current_record);
        current_record = next_record;
    }

    // Free the memory for the array of offsets and keys
    free(offsets);
    free(keys);
}
