// Function to add a new node to the end of the list
void add_node(Node **head, Node *new_node) {
    // Check if the head is NULL
    if (!head) {
        fprintf(stderr, "Error: Invalid head pointer\n");
        return;
    }

    // If the list is empty, set the new node as the head
    if (*head == NULL) {
        *head = new_node;
        return;
    }

    // Traverse the list to find the last node
    Node *current = *head;
    while (current->next != NULL) {
        current = current->next;
    }

    // Set the new node as the next pointer of the last node
    current->next = new_node;
}

// Function to free all memory allocated for a given list of nodes
void free_nodes(Node **head) {
    if (!head || *head == NULL) {
        return;
    }

    // Free the head node and its next pointers recursively
    Node *current = *head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }
}

// Function to print a list of nodes
void print_nodes(Node **head) {
    if (!head || *head == NULL) {
        return;
    }

    // Print the head node and its next pointers recursively
    Node *current = *head;
    while (current != NULL) {
        printf("%d: %s\n", current->value, current->identifier);
        current = current->next;
    }
}
