// Memory pool for dynamic memory allocation
struct memory_pool {
    size_t size;
    void *pool;
};

static struct memory_pool mem_pool = {0, NULL};

void init_memory_pool() {
    // Initialize the memory pool with a size of MEMORY_POOL_SIZE
    mem_pool.size = MEMORY_POOL_SIZE;
    mem_pool.pool = malloc(mem_pool.size);
}

// Allocate memory from the memory pool, reallocating if necessary
void *malloc_from_pool(size_t size) {
    void *ptr = NULL;

    // Check if there is enough space in the memory pool
    if (mem_pool.size - mem_pool.used >= size) {
        ptr = mem_pool.pool + mem_pool.used;
        mem_pool.used += size;
    } else {
        // Reallocate the memory pool with a larger size
        mem_pool.size *= 2;
        mem_pool.pool = realloc(mem_pool.pool, mem_pool.size);
        ptr = mem_pool.pool + mem_pool.used;
        mem_pool.used += size;
    }

    return ptr;
}

// Custom memory pool for dynamic allocation of record structures
void *allocate_record(int num_records) {
    // Allocate space for the offset, key, and timestamp arrays
    void *ptr = malloc_from_pool(sizeof(long)*num_records + sizeof(int)*num_records + sizeof(double)*num_records);

