    for (int i = 0; i < num_records; i++) {
        timestamp_array[i] = 0.0;
    }

    return ptr;
}

// Sort the records based on their timestamps in descending order
void sort_records(record_t *records, int num_records) {
    // Use a stable sorting algorithm to sort the records
    for (int i = 0; i < num_records-1; i++) {
        for (int j = i+1; j < num_records; j++) {
            if (records[j].timestamp > records[i].timestamp) {
                record_t tmp = records[i];
                records[i] = records[j];
                records[j] = tmp;
            }
        }
    }
}

// Serialize the sorted records into a file
void serialize_records(record_t *records, int num_records, const char *filename) {
    // Open the output file in append mode
    FILE *fp = fopen(filename, "a");

    // Write the number of records to the file
    fwrite(&num_records, sizeof(int), 1, fp);

    // Write each record to the file
    for (int i = 0; i < num_records; i++) {
        fwrite(&records[i].offset, sizeof(long), 1, fp);
        fwrite(&records[i].key, sizeof(int), 1, fp);
        fwrite(&records[i].timestamp, sizeof(double), 1, fp);
