        if (len <= 0) {
            printf("Error: failed to handle graceful shutdown for current session\n");
            exit(1);
        }
    } else {
        // Handle failed cryptographic operations with retry mechanism
        bool success = false;
        int retries = 0;
        while (!success && retries < MAX_RETRIES) {
            // Perform SSL handshake
            res = SSL_do_handshake(ssl);
            if (res == -1) {
                printf("Error: failed to perform SSL handshake\n");
                exit(1);
            }

            // Check if current session has a pending handshake
            pending = SSL_pending(ssl);
            if (!pending) {
                success = true;
            } else {
                retries++;
            }
        }
    }
}
