// Structure to hold socket information and connection state
typedef struct {
    int fd; // File descriptor for the socket
    double precision; // Precision value for the record
    struct sockaddr_in addr; // Address of the remote server
} socket_info_t;

// Array to hold the pool of socket information and connection states
static socket_info_t *sockets = NULL;

// Size of the pool of sockets
static int num_sockets = 0;

// Mutex for synchronizing access to the socket pool
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a record in the socket pool
void init_socket(int index, struct sockaddr_in *addr) {
    // Acquire the mutex lock before modifying the socket pool
    pthread_mutex_lock(&mutex);

    if (index < 0 || index >= num_sockets) {
        printf("Invalid index: %d\n", index);
        return;
    }

    // Initialize the socket information and connection state for the record
    sockets[index].fd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockets[index].fd < 0) {
        printf("Failed to create socket\n");
        return;
    }

    // Set the socket options for non-blocking and keepalive
    int flags = fcntl(sockets[index].fd, F_GETFL, 0);
    if (flags < 0) {
        printf("Failed to get socket options\n");
        close(sockets[index].fd);
        return;
    }

    // Set the non-blocking flag for the socket
    flags |= O_NONBLOCK;
    if (fcntl(sockets[index].fd, F_SETFL, flags) < 0) {
        printf("Failed to set non-blocking flag\n");
        close(sockets[index].fd);
        return;
    }

    // Set the keepalive flag for the socket
    int optval = 1;
    if (setsockopt(sockets[index].fd, SOL_SOCKET, SO_KEEPALIVE, &optval, sizeof(optval)) < 0) {
        printf("Failed to set keepalive flag\n");
        close(sockets[index].fd);
        return;
    }

    // Set the socket timeout for the record
    struct timeval timeout = {15, 0}; // 15 seconds
    if (setsockopt(sockets[index].fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) < 0) {
        printf("Failed to set socket timeout\n");
        close(sockets[index].fd);
        return;
    }

    // Initialize the precision value for the record
    sockets[index].precision = drand48() * (max_precision - min_precision) + min_precision;

    // Save the socket address for the remote server
    memcpy(&sockets[index].addr, addr, sizeof(struct sockaddr_in));

    // Release the mutex lock after modifying the socket pool
    pthread_mutex_unlock(&mutex);
}

// Function to create a new record in the socket pool
int create_socket(struct sockaddr_in *addr) {
    // Acquire the mutex lock before modifying the socket pool
    pthread_mutex_lock(&mutex);

    // Check if there is space in the pool for a new record
    if (num_sockets >= MAX_SOCKETS) {
        printf("Maximum number of sockets reached\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Create a new socket and initialize the record in the pool
    int index = num_sockets++;
    init_socket(index, addr);

    // Release the mutex lock after modifying the socket pool
    pthread_mutex_unlock(&mutex);

    return index;
}

// Function to add a new remote server configuration to the socket pool
void add_server(struct sockaddr_in *addr) {
    // Acquire the mutex lock before modifying the socket pool
    pthread_mutex_lock(&mutex);

    // Check if there is space in the pool for a new record
    if (num_sockets >= MAX_SOCKETS) {
        printf("Maximum number of sockets reached\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Create a new socket and initialize the record in the pool
    int index = num_sockets++;
    init_socket(index, addr);

    // Release the mutex lock after modifying the socket pool
    pthread_mutex_unlock(&mutex);
}

// Function to get a socket from the pool for a specific remote server
int get_socket(struct sockaddr_in *addr) {
    int index = -1;

    // Acquire the mutex lock before accessing the socket pool
    pthread_mutex_lock(&mutex);

    // Check if there is an existing socket for the remote server in the pool
    for (int i = 0; i < num_sockets; i++) {
        if (memcmp(&addr, &sockets[i].addr, sizeof(struct sockaddr_in)) == 0) {
            index = i;
            break;
        }
    }

    // Release the mutex lock after accessing the socket pool
    pthread_mutex_unlock(&mutex);

    return index;
}

// Function to update the socket pool with new information about a remote server
void update_server(struct sockaddr_in *addr) {
    // Acquire the mutex lock before modifying the socket pool
    pthread_mutex_lock(&mutex);

    // Check if there is an existing socket for the remote server in the pool
    int index = get_socket(addr);
    if (index >= 0) {
        // Update the socket address and connection state for the record
        memcpy(&sockets[index].addr, addr, sizeof(struct sockaddr_in));
        sockets[index].fd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockets[index].fd < 0) {
            printf("Failed to create socket\n");
        } else {
            // Set the non-blocking flag for the socket
            int flags = fcntl(sockets[index].fd, F_GETFL, 0);
            if (flags < 0) {
                printf("Failed to get socket options\n");
                close(sockets[index].fd);
            } else {
                // Set the non-blocking flag for the socket
                flags |= O_NONBLOCK;
                if (fcntl(sockets[index].fd, F_SETFL, flags) < 0) {
                    printf("Failed to set non-blocking flag\n");
                    close(sockets[index].fd);
                }
            }
        }
    } else {
        // Add a new record for the remote server to the pool
        add_server(addr);
    }

    // Release the mutex lock after modifying the socket pool
    pthread_mutex_unlock(&mutex);
}

// Function to close and remove a socket from the pool for a specific remote server
void remove_socket(struct sockaddr_in *addr) {
    // Acquire the mutex lock before modifying the socket pool
    pthread_mutex_lock(&mutex);

    // Check if there is an existing socket for the remote server in the pool
    int index = get_socket(addr);
    if (index >= 0) {
        // Close the socket and remove the record from the pool
        close(sockets[index].fd);
        memset(&sockets[index], 0, sizeof(socket_info_t));
    }

    // Release the mutex lock after modifying the socket pool
    pthread_mutex_unlock(&mutex);
}

// Function to close and remove all sockets from the pool
void close_sockets() {
    // Acquire the mutex lock before modifying the socket pool
    pthread_mutex_lock(&mutex);

    // Close and remove all records in the socket pool
    for (int i = 0; i < num_sockets; i++) {
        close(sockets[i].fd);
        memset(&sockets[i], 0, sizeof(socket_info_t));
    }
    num_sockets = 0;

    // Release the mutex lock after modifying the socket pool
    pthread_mutex_unlock(&mutex);
}
