#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <limits.h>
#include <errno.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Function to dynamically allocate memory for an array of longs and ints
void* allocateMemory(size_t numLongs, size_t numInts) {
    // Calculate the total number of bytes needed for both arrays
    size_t totalBytes = (numLongs * sizeof(long)) + (numInts * sizeof(int));

    // Ensure that the total number of bytes does not exceed system limits
    if (totalBytes > SIZE_MAX) {
        fprintf(stderr, "Error: Invalid input. Total number of bytes exceeds system limit.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the arrays using malloc()
    void* mem = malloc(totalBytes);
    if (mem == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory. %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Return the pointer to the allocated memory
    return mem;
}

// Function to dynamically allocate memory for an array of records
void* allocateRecordMemory(size_t numRecords) {
    // Calculate the total number of bytes needed for the record structure
    size_t totalBytes = numRecords * sizeof(Record);

    // Ensure that the total number of bytes does not exceed system limits
    if (totalBytes > SIZE_MAX) {
        fprintf(stderr, "Error: Invalid input. Total number of bytes exceeds system limit.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the array using malloc()
    void* mem = malloc(totalBytes);
    if (mem == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory. %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Return the pointer to the allocated memory
    return mem;
}

// Function to set the value of each record's int field to a random value within a specified range
void setRandomValues(Record* records, size_t numRecords, int minValue, int maxValue) {
    // Check if the input range is valid
    if (minValue > maxValue) {
        fprintf(stderr, "Error: Invalid input range.\n");
        exit(EXIT_FAILURE);
    }

    // Generate a random number within the specified range for each record's int field
    srand(time(NULL));
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }
}

// Function to sort the records based on their int values using a stable sorting algorithm
void sortRecords(Record* records, size_t numRecords, int (*compare)(const void*, const void*)) {
    // Check if the input parameters are valid
    if (records == NULL || compare == NULL) {
        fprintf(stderr, "Error: Invalid input parameters.\n");
        exit(EXIT_FAILURE);
    }

    // Use a stable sorting algorithm to sort the records based on their int values
    qsort(records, numRecords, sizeof(Record), compare);
}

// Function to serialize the sorted records into a file
void serializeRecords(const Record* records, size_t numRecords, const char* filename) {
    // Check if the input parameters are valid
    if (records == NULL || filename == NULL) {
        fprintf(stderr, "Error: Invalid input parameters.\n");
        exit(EXIT_FAILURE);
    }

    // Open the file for writing in binary mode
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Error: Failed to open file %s. %s\n", filename, strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Write the number of records to the file
    size_t numBytes = fwrite(&numRecords, sizeof(size_t), 1, file);
    if (numBytes != 1) {
        fprintf(stderr, "Error: Failed to write number of records to file.\n");
        exit(EXIT_FAILURE);
    }

    // Write the records to the file
    numBytes = fwrite(records, sizeof(Record), numRecords, file);
    if (numBytes != numRecords) {
        fprintf(stderr, "Error: Failed to write all records to file.\n");
        exit(EXIT_FAILURE);
    }

    // Close the file
    fclose(file);
}

// Function to deserialize the sorted records from a file
void deserializeRecords(Record* records, size_t numRecords, const char* filename) {
    // Check if the input parameters are valid
    if (records == NULL || filename == NULL) {
        fprintf(stderr, "Error: Invalid input parameters.\n");
        exit(EXIT_FAILURE);
    }

