// Custom memory pool structure
struct MemoryPool {
    void** blocks; // array of void pointers to allocated blocks
    int block_size; // size of each block in bytes
    int num_blocks; // number of blocks in the pool
    int next_free; // index of next free block
};

// Custom validation function for user-provided input sizes
int validate_input(int* sizes, int num_sizes) {
    for (int i = 0; i < num_sizes; i++) {
        if (sizes[i] <= 0) { // check for negative or zero-sized inputs
            return -1;
        }
        else if (sizes[i] > INT_MAX / sizeof(void*)) { // check for overflow
            return -2;
        }
    }
    return 0;
}

// Custom memory allocation function with pooling and dynamic resizing
void* mem_alloc(int size) {
    void* block = NULL;
    struct MemoryPool* pool = get_memory_pool(); // retrieve the current memory pool
    if (pool == NULL || pool->num_blocks == 0) { // no pool or no blocks available
        return mmap(NULL, size, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0); // allocate new block using mmap
    }
    else if (pool->next_free < pool->num_blocks && pool->blocks[pool->next_free] == NULL) { // next free block is available
        block = pool->blocks[pool->next_free]; // assign the next free block to the new allocation
        pool->next_free++; // increment the index of the next free block
    }
    else { // no more blocks available or full pool, resize the pool and try again
        int new_num_blocks = pool->num_blocks * 2; // double the number of blocks in the pool
        void** new_blocks = realloc(pool->blocks, new_num_blocks * sizeof(void*)); // resize the block array
        if (new_blocks == NULL) { // reallocation failed, offload data storage to disk
            return mmap(NULL, size, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0); // allocate new block using mmap
        }
        pool->blocks = new_blocks; // assign the resized block array to the memory pool
        for (int i = pool->num_blocks; i < new_num_blocks; i++) { // initialize all new blocks as NULL
            pool->blocks[i] = NULL;
        }
        pool->num_blocks = new_num_blocks; // update the number of blocks in the pool
        block = mem_alloc(size); // recursively call the memory allocation function with updated pool
    }
    return block; // return the allocated block or NULL if failed
}

// Custom memory deallocation function with pooling and dynamic resizing
void mem_dealloc(void* block) {
    struct MemoryPool* pool = get_memory_pool(); // retrieve the current memory pool
    if (pool == NULL || pool->num_blocks == 0) { // no pool or no blocks available, do nothing
        return;
    }
    else if (block == NULL) { // invalid block pointer, do nothing
        return;
    }
    for (int i = 0; i < pool->num_blocks; i++) { // search for the block to deallocate
        if (pool->blocks[i] == block) { // found the block, deallocate it and update the pool
            free(block);
            pool->blocks[i] = NULL;
            pool->next_free--; // decrement the index of the next free block
            return;
        }
    }
}

// Custom memory pool management functions
struct MemoryPool* create_memory_pool() {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (pool == NULL) {
        return NULL;
    }
    pool->blocks = calloc(INITIAL_POOL_SIZE, sizeof(void*)); // allocate the initial block array
    if (pool->blocks == NULL) {
        free(pool);
        return NULL;
    }
    pool->block_size = INITIAL_BLOCK_SIZE; // set the initial block size to 1 MB
    pool->num_blocks = INITIAL_POOL_SIZE; // set the number of blocks in the pool to the initial size
    pool->next_free = 0; // set the index of the next free block to 0
    return pool;
}

void destroy_memory_pool(struct MemoryPool* pool) {
    if (pool == NULL) {
        return;
    }
    for (int i = 0; i < pool->num_blocks; i++) { // deallocate all blocks in the pool
        free(pool->blocks[i]);
    }
    free(pool->blocks); // deallocate the block array
    free(pool); // deallocate the memory pool structure
}

// Custom memory pool query functions
int get_memory_usage() {
    struct MemoryPool* pool = get_memory_pool();
    if (pool == NULL) {
        return 0;
    }
    int usage = 0;
    for (int i = 0; i < pool->num_blocks; i++) { // calculate the total memory usage of all blocks in the pool
        if (pool->blocks[i] != NULL) {
            usage += pool->block_size;
        }
    }
    return usage;
}

int get_memory_pool_size() {
    struct MemoryPool* pool = get_memory_pool();
    if (pool == NULL) {
        return 0;
    }
