typedef struct Record {
    int offset;
} Record;

typedef struct ThemeOffsetCache {
    Record** cache;
    size_t capacity;
    size_t count;
} ThemeOffsetCache;

ThemeOffsetCache* init_cipher_and_theme_offset_cache(const char* password) {
    // Allocate memory for the offset cache and initialize the elements to 0
    ThemeOffsetCache* cache = malloc(sizeof(ThemeOffsetCache));
    cache->capacity = 10_000;
    cache->count = 0;
    cache->cache = calloc(cache->capacity, sizeof(Record*));

    // Initialize the AES-256-CBC cipher using a provided password
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, password, NULL);

    // Iterate over the cache and encrypt each element using AES-256-CBC
    for (size_t i = 0; i < cache->capacity; i++) {
        Record* record = malloc(sizeof(Record));
        record->offset = i * 1000; // The offset is set to 1000 to demonstrate encryption
        EVP_EncryptUpdate(ctx, NULL, &record->offset, &record->offset);
    }

    // Clean up the cipher context and free the cache memory
    EVP_CIPHER_CTX_free(ctx);
    free(cache->cache);
    return cache;
}
