#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

// Define a structure to represent each record
struct record {
    int key;
};

// Function to allocate memory for an array of records
void* allocate_records(size_t num_records) {
    // Check if the input is valid and non-zero
    if (num_records == 0) {
        fprintf(stderr, "Error: invalid number of records\n");
        return NULL;
    }

    // Allocate memory for the array of records
    struct record* records = malloc(sizeof(struct record) * num_records);
    if (records == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize each record with a random integer value
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        records[i].key = rand() % 100 + 1;
    }

    return records;
}

// Function to free memory allocated for an array of records
void free_records(struct record* records) {
    if (records == NULL) {
        fprintf(stderr, "Error: invalid input\n");
        return;
    }
    free(records);
}

// Function to sort an array of records based on their integer values
void sort_records(struct record* records, size_t num_records) {
    // Check if the input is valid and non-zero
    if (num_records == 0 || records == NULL) {
        fprintf(stderr, "Error: invalid number of records\n");
        return;
    }

    // Define a comparison function for sorting records by their integer values
    int compare_records(const void* r1, const void* r2) {
        struct record* rec1 = (struct record*)r1;
        struct record* rec2 = (struct record*)r2;
        return rec1->key - rec2->key;
    }

    // Sort the records using the comparison function
    qsort(records, num_records, sizeof(struct record), compare_records);
}

// Function to serialize an array of records into a file
int serialize_records(struct record* records, size_t num_records, const char* filename) {
    // Check if the input is valid and non-zero
    if (num_records == 0 || records == NULL) {
        fprintf(stderr, "Error: invalid number of records\n");
        return -1;
    }

    // Open the file for writing
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open file %s for writing\n", filename);
        return -1;
    }

    // Write the records to the file
    size_t num_bytes = sizeof(struct record) * num_records;
    if (fwrite(records, 1, num_bytes, fp) != num_bytes) {
        fprintf(stderr, "Error: failed to write %zu bytes to file %s\n", num_bytes, filename);
        fclose(fp);
        return -1;
    }

    // Close the file and return successfully
    if (fclose(fp) == EOF) {
        fprintf(stderr, "Error: failed to close file %s\n", filename);
        return -1;
    }
    return 0;
}

// Function to deserialize an array of records from a file
struct record* deserialize_records(const char* filename, size_t* num_records) {
    // Check if the input is valid and non-zero
    if (filename == NULL || *num_records == 0) {
        fprintf(stderr, "Error: invalid number of records\n");
        return NULL;
    }

    // Open the file for reading
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open file %s for reading\n", filename);
        return NULL;
    }

    // Determine the number of records in the file
    *num_records = 0;
    struct record* records = NULL;
    while (!feof(fp)) {
        size_t num_bytes = sizeof(struct record);
        void* buffer = malloc(num_bytes);
        if (fread(buffer, 1, num_bytes, fp) != num_bytes) {
            fprintf(stderr, "Error: failed to read %zu bytes from file %s\n", num_bytes, filename);
            free(buffer);
            break;
        }
        if (records == NULL) {
            records = malloc(*num_records * sizeof(struct record));
        } else {
            records = realloc(records, (*num_records + 1) * sizeof(struct record));
        }
        memcpy(&records[*num_records], buffer, num_bytes);
        free(buffer);
        (*num_records)++;
    }

    // Close the file and return the deserialized records
    if (fclose(fp) == EOF) {
        fprintf(stderr, "Error: failed to close file %s\n", filename);
        free(records);
        return NULL;
    }
    return records;
}
