// Structure for each node in the linked list
typedef struct node {
    char* file_path;
    int timestamp;
    struct node* next;
} node_t;

// Function to dynamically manage a linked list of nodes
void manage_linked_list(int num_nodes) {
    // Allocate memory for the linked list
    node_t* head = malloc(sizeof(node_t));
    if (!head) {
        fprintf(stderr, "Failed to allocate memory for linked list\n");
        return;
    }

    // Initialize the first node in the linked list
    head->file_path = NULL;
    head->timestamp = 0;
    head->next = NULL;

    // Add nodes to the linked list until num_nodes are reached
    int i = 1;
    while (i < num_nodes) {
        node_t* new_node = malloc(sizeof(node_t));
        if (!new_node) {
            fprintf(stderr, "Failed to allocate memory for node %d\n", i);
            return;
        }

        // Set the file path and timestamp for the new node
        new_node->file_path = NULL;
        new_node->timestamp = 0;

        // Add the new node to the linked list
        head->next = new_node;
        head = head->next;

        i++;
    }

    // Traverse the linked list and validate file paths for existence and accessibility
    node_t* current_node = head;
    while (current_node != NULL) {
        // Validate that the file path exists and is accessible
        if (access(current_node->file_path, F_OK)) {
            fprintf(stderr, "File %s does not exist or is not accessible\n", current_node->file_path);
            return;
        }

        // Handle edge cases by logging errors without terminating the program
        if (errno == ENOENT) {
            fprintf(stderr, "Failed to open file %s: no such file or directory\n", current_node->file_path);
            return;
        } else if (errno == EACCES) {
            fprintf(stderr, "Failed to open file %s: permission denied\n", current_node->file_path);
            return;
        }

        // Move on to the next node in the linked list
        current_node = current_node->next;
    }

    // Calculate the file size for each accessible file path and store the result in a separate data structure
    int total_size = 0;
    current_node = head;
    while (current_node != NULL) {
        struct stat statbuf;
        if (stat(current_node->file_path, &statbuf)) {
            fprintf(stderr, "Failed to get file size for %s\n", current_node->file_path);
            return;
        }

        // Store the file size in a separate data structure
        total_size += statbuf.st_size;

        // Move on to the next node in the linked list
        current_node = current_node->next;
    }

    // Sort the file paths based on their modification timestamps using a stable sorting algorithm
    qsort(head, num_nodes, sizeof(node_t), compare_timestamps);

    // Serialize the sorted file paths into a JSON format and write them to a file
    char* json = serialize_json(head);
    if (!write_file("sorted_paths.json", json)) {
        fprintf(stderr, "Failed to write sorted file paths to file\n");
        return;
    }
