#include <unordered_set>

// Custom memory pool class to optimize memory usage and reduce fragmentation
class MemoryPool {
public:
    MemoryPool(size_t size) : _size(size), _freeList() {}

    // Allocate memory from the pool
    void* allocate(size_t size) {
        if (size > _size) {
            throw std::bad_alloc();
        }

        // Search for a free block of sufficient size in the free list
        for (auto it = _freeList.begin(); it != _freeList.end(); ++it) {
            if (it->second >= size) {
                auto block = *it;
                _freeList.erase(it);
                return block.first;
            }
        }

        // If no free block is found, allocate a new one from the heap
        void* ptr = std::malloc(size);
        if (!ptr) {
            throw std::bad_alloc();
        }
        _usedList.insert(std::make_pair(ptr, size));
        return ptr;
    }

    // Free memory back to the pool
    void free(void* ptr, size_t size) {
        if (size > _size) {
            throw std::bad_alloc();
        }

        // Search for the corresponding block in the used list
        auto it = _usedList.find(ptr);
        if (it == _usedList.end()) {
            return;
        }

        // If the block is found, mark it as free and add it to the free list
        it->second -= size;
        if (it->second == 0) {
            _usedList.erase(it);
        } else {
            _freeList.insert(std::make_pair(ptr, it->second));
        }
    }

private:
    size_t _size;
    std::unordered_map<void*, size_t> _usedList;
    std::unordered_set<std::pair<void*, size_t>> _freeList;
};

// Record structure for the array of records
struct Record {
    long offset;
    int key;
    float value;
    char status;

    // Comparison operator for sorting
    bool operator<(const Record& other) const {
        return this->value < other.value;
    }
};

// Filtering mechanism to retain only records within specified ranges
void filterRecords(std::vector<Record>& records, long minOffset, long maxOffset, int minKey, int maxKey) {
    std::unordered_set<int> keys;

    // Remove all records outside the range of offsets and keys
    for (auto it = records.begin(); it != records.end();) {
        if ((*it).offset < minOffset || (*it).offset > maxOffset || (*it).key < minKey || (*it).key > maxKey) {
            it = records.erase(it);
        } else {
            keys.insert((*it).key);
            ++it;
        }
    }

    // Remove all records with duplicate keys
    for (auto it = records.begin(); it != records.end();) {
        if (keys.find((*it).key) != keys.end()) {
            it = records.erase(it);
        } else {
            ++it;
        }
    }
}

// Sorting mechanism for the records based on their float values
void sortRecords(std::vector<Record>& records, bool ascending) {
    if (ascending) {
        std::sort(records.begin(), records.end());
    } else {
        std::sort(records.begin(), records.end(), [](const Record& a, const Record& b) { return a.value > b.value; });
    }
}

// Serialization protocol for storing the filtered and sorted records
void serializeRecords(std::vector<Record>& records, std::string filename) {
    // Open the file in binary mode for writing
    std::ofstream ofs(filename, std::ios::binary);

    // Write the number of records to the file
    size_t numRecords = records.size();
    ofs.write((char*)&numRecords, sizeof(size_t));

    // Write each record to the file
    for (const auto& rec : records) {
        ofs.write((char*)&rec.offset, sizeof(long));
        ofs.write((char*)&rec.key, sizeof(int));
        ofs.write((char*)&rec.value, sizeof(float));
        ofs.write(&rec.status, 1);
    }

    // Close the file
    ofs.close();
}

// Deserialization protocol for loading the filtered and sorted records from a file
std::vector<Record> deserializeRecords(std::string filename) {
    // Open the file in binary mode for reading
    std::ifstream ifs(filename, std::ios::binary);

    // Read the number of records from the file
    size_t numRecords;
    ifs.read((char*)&numRecords, sizeof(size_t));

    // Create a vector to hold the deserialized records
    std::vector<Record> records;
    records.reserve(numRecords);

    // Read each record from the file and append it to the vector
    for (size_t i = 0; i < numRecords; ++i) {
        Record rec;
        ifs.read((char*)&rec.offset, sizeof(long));
        ifs.read((char*)&rec.key, sizeof(int));
        ifs.read((char*)&rec.value, sizeof(float));
        ifs.read(&rec.status, 1);
        records.push_back(rec);
    }

    // Close the file
    ifs.close();

    return records;
}

// Thread-safe access to the data structures using locks and condition variables
class DataStructure {
public:
    void pushRecord(const Record& record) {
        std::lock_guard<std::mutex> lock(_mutex);
        _records.push_back(record);
        _condition.notify_all();
    }

    void filterRecords(long minOffset, long maxOffset, int minKey, int maxKey) {
        std::lock_guard<std::mutex> lock(_mutex);
        filterRecords(_records, minOffset, maxOffset, minKey, maxKey);
        _condition.notify_all();
    }

    void sortRecords(bool ascending) {
        std::lock_guard<std::mutex> lock(_mutex);
        sortRecords(_records, ascending);
        _condition.notify_all();
    }

    const std::vector<Record>& getRecords() const {
        std::unique_lock<std::mutex> lock(_mutex);
        return _records;
    }

private:
    mutable std::mutex _mutex;
    std::condition_variable _condition;
    std::vector<Record> _records;
};
```']

