// Custom memory pool structure
typedef struct {
    void *data;
    size_t size;
} MemoryPool;

// Dynamic memory pool management functions
void init_memory_pools(size_t num_pools) {
    // Initialize the memory pools with the specified number of pools
    for (int i = 0; i < num_pools; i++) {
        MemoryPool *pool = malloc(sizeof(MemoryPool));
        if (pool == NULL) {
            perror("Failed to allocate memory pool");
            exit(1);
        }
        pool->data = NULL;
        pool->size = 0;
    }
}

void free_memory_pools() {
    // Free all the memory pools
    for (int i = 0; i < num_pools; i++) {
        MemoryPool *pool = malloc(sizeof(MemoryPool));
        if (pool == NULL) {
            perror("Failed to free memory pool");
            exit(1);
        }
        free(pool->data);
        free(pool);
    }
}

void *allocate_memory(size_t size) {
    // Allocate memory from the specified pool
    for (int i = 0; i < num_pools; i++) {
        if (memory_pools[i].size >= size) {
            void *data = malloc(size);
            if (data == NULL) {
                perror("Failed to allocate memory");
                exit(1);
            }
            memory_pools[i].size -= size;
            return data;
        }
    }
    // If no pool has enough space, allocate a new pool
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) {
        perror("Failed to allocate memory pool");
        exit(1);
    }
    pool->data = malloc(size);
    if (pool->data == NULL) {
        perror("Failed to allocate memory for data");
        free(pool);
        return NULL;
    }
    pool->size = size;
    memory_pools[num_pools++] = *pool;
    return pool->data;
}

void deallocate_memory(void *data) {
    // Deallocate the specified memory
    for (int i = 0; i < num_pools; i++) {
        if (memory_pools[i].data == data) {
            free(data);
            memory_pools[i].size += size;
            return;
        }
    }
}

