// Macro for checking if a number is power of 2
#define IS_POWER_OF_TWO(n) (((n) & ((n) - 1)) == 0)

// Structure to represent the record
typedef struct {
    int value;
    int key;
} Record;

void manageMemory(int n) {
    // Check if n is a power of 2, if not round up to next power of 2
    if (!IS_POWER_OF_TWO(n)) {
        n = 1 << (ceil(log2(n)));
    }

    // Allocate memory for the arrays
    long *offsets = malloc(sizeof(long) * n);
    int *keys = malloc(sizeof(int) * n);
    Record *records = malloc(sizeof(Record) * n);

    // Initialize the offsets array with sequential values starting from 0
    for (int i = 0; i < n; i++) {
        offsets[i] = i;
    }

    // Initialize the keys array with unique random values between 1 and 1000, avoiding duplicates within the array
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        int key = rand() % 1000 + 1;
        if (!keys[i]) {
            keys[i] = key;
        } else {
            i--;
        }
    }

    // Initialize the records array such that each record's integer value is set to a random number between 1 and 1000, ensuring no duplicate values within the records array
    for (int i = 0; i < n; i++) {
        int value = rand() % 1000 + 1;
        if (!records[i].value) {
            records[i].value = value;
        } else {
            i--;
        }
    }

    // Set the key reference in each record to a valid index in the keys array, but handle cases where n is smaller than the maximum referenceable index
    for (int i = 0; i < n; i++) {
        if (records[i].key < n) {
            records[i].key = keys[i];
        } else {
            i--;
        }
    }

    // Print the arrays in a formatted manner, with each record displaying its integer value and the corresponding key index
    printf("Keys: ");
    for (int i = 0; i < n; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");
    printf("Offsets: ");
    for (int i = 0; i < n; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");
    printf("Records: ");
    for (int i = 0; i < n; i++) {
        Record record = records[i];
        printf("%d (key %d) ", record.value, record.key);
    }
    printf("\n");

    // Log memory usage before and after allocation to ensure that the function adheres to the 50% memory constraint
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    float maxMemory = usage.ru_maxrss / (1024 * 1024); // Convert bytes to megabytes
    if (maxMemory > 50) {
        printf("Max memory exceeded: %.2f MB\n", maxMemory);
    } else {
        printf("Max memory usage: %.2f MB\n", maxMemory);
    }

    // Free all allocated memory at the end of the function, including handling any potential errors during deallocation
    free(offsets);
    free(keys);
    for (int i = 0; i < n; i++) {
        free(records[i].value);
    }
    free(records);
}
