#include <fcntl.h>
#include <errno.h>

#define MAX_INODES 10000
#define MAX_BLOCKS 50000
#define MEMORY_LIMIT (70 * 1024 * 1024) // 70% of total memory available
#define REPLICATION_FACTOR 3
#define MIN_FILE_SIZE 1024
#define MAX_FILE_SIZE 100 * 1024 * 1024 // 100 MB
#define MIN_BLOCK_SIZE 4096
#define MAX_BLOCK_SIZE 100 * 1024 * 1024 // 100 MB

struct inode {
    int size;
    int permissions;
    char type; // regular file, directory, etc.
};

struct block {
    int id;
    void* data;
};

struct directory {
    int id;
    struct directory* parent;
    struct inode* inodes[MAX_INODES];
    struct block* blocks[MAX_BLOCKS];
};

void manage_memory(int num_inodes, int num_blocks) {
    size_t memory_usage = 0;
    // Allocate memory for the inode and block arrays
    struct inode* inodes = (struct inode*)malloc(num_inodes * sizeof(struct inode));
    if (!inodes) {
        perror("Failed to allocate memory for inodes");
        return;
    }
    memory_usage += num_inodes * sizeof(struct inode);

    struct block* blocks = (struct block*)malloc(num_blocks * sizeof(struct block));
    if (!blocks) {
        perror("Failed to allocate memory for blocks");
        free(inodes);
        return;
    }
    memory_usage += num_blocks * sizeof(struct block);

    // Initialize the inode and block arrays
    int i, j;
    for (i = 0; i < num_inodes; i++) {
        inodes[i].size = MIN_FILE_SIZE + (rand() % (MAX_FILE_SIZE - MIN_FILE_SIZE));
        inodes[i].permissions = rand() & 0x7; // 3-bit random permissions
        inodes[i].type = 'f'; // regular file
    }

    for (j = 0; j < num_blocks; j++) {
        blocks[j].id = j;
        int block_size = MIN_BLOCK_SIZE + (rand() % (MAX_BLOCK_SIZE - MIN_BLOCK_SIZE));
        void* data = malloc(block_size);
        if (!data) {
            perror("Failed to allocate memory for block data");
            free(inodes);
            free(blocks);
            return;
        }
        blocks[j].data = data;
    }

    // Initialize the directory hierarchy
    struct directory* root = (struct directory*)malloc(sizeof(struct directory));
    if (!root) {
        perror("Failed to allocate memory for root directory");
        free(inodes);
        free(blocks);
        return;
    }
    root->id = 0;
    root->parent = NULL;
    for (i = 0; i < num_inodes; i++) {
        int inode_id = rand() % MAX_INODES;
        if (!root->inodes[inode_id]) {
            struct inode* inode = &inodes[inode_id];
            root->inodes[inode_id] = inode;
            break;
        }
    }

    // Construct the directory hierarchy
    struct directory* current = root;
    while (current) {
        int num_children = rand() % 10 + 1;
        for (i = 0; i < num_children; i++) {
            int inode_id = rand() % MAX_INODES;
            struct inode* inode = &inodes[inode_id];
            if (!current->inodes[inode_id]) {
                current->inodes[inode_id] = inode;
                break;
            }
        }
        for (j = 0; j < num_blocks; j++) {
            int block_id = rand() % MAX_BLOCKS;
            struct block* block = &blocks[block_id];
            if (!current->blocks[block_id]) {
                current->blocks[block_id] = block;
                break;
            }
        }
        if (rand() % 2 == 0) {
            struct directory* child = (struct directory*)malloc(sizeof(struct directory));
            if (!child) {
                perror("Failed to allocate memory for child directory");
                free(current);
                return;
            }
            current->inodes[num_children] = child;
            child->parent = current;
            child->id = num_children;
        } else {
            struct inode* inode = &inodes[rand() % MAX_INODES];
            if (!current->inodes[num_children]) {
                current->inodes[num_children] = inode;
                break;
            }
        }
    }

    // Implement replication strategy
    for (i = 0; i < num_blocks; i++) {
        struct block* block = &blocks[i];
        int num_replicas = REPLICATION_FACTOR;
        while (num_replicas > 0) {
            int node_id = rand() % NUM_NODES;
            if (!nodes[node_id].blocks[i]) {
                nodes[node_id].blocks[i] = block;
                num_replicas--;
            }
        }
    }

    // Log memory usage before and after allocation to ensure adherence to the 70% memory constraint
    size_t available_memory = sysconf(_SC_PAGESIZE) * sysconf(_SC_AVPHYS_PAGES);
    printf("Initial memory usage: %zu\n", memory_usage);
    if (memory_usage > available_memory * 0.7) {
        perror("Memory usage exceeds the 70% limit");
        free(inodes);
        free(blocks);
        return;
    }

    // Implement failover strategies for nodes in case of failure

    // Free all allocated memory at the end of the function
    free(inodes);
    free(blocks);
    free(root);
}
