    return 0;
}

// Function to add a session to the network interface module
int add_session(uint64_t session_id) {
    // Lock the mutex to protect the shared resources of the function
    pthread_mutex_lock(&mutex);

    // Check if the maximum number of sessions has been reached
    if (tx_queue.size >= max_sessions - min_sessions) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Allocate a new TX queue data item for the session
    struct tx_queue_data_item *item = malloc(sizeof(struct tx_queue_data_item));

    if (!item) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Initialize the TX queue data item
    item->session_id = session_id;
    item->sequence_number = 0;
    item->payload_size = 0;

    // Add the TX queue data item to the linked list and cache
    TAILQ_INSERT_TAIL(&tx_queue, item, entries);
    cache[session_id % CACHE_SIZE] = item;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    return 0;
}

// Function to remove a session from the network interface module
int remove_session(uint64_t session_id) {
    // Lock the mutex to protect the shared resources of the function
    pthread_mutex_lock(&mutex);

    // Check if the session exists in the linked list and cache
    struct tx_queue_data_item *item = NULL;

    for (int i = 0; i < max_sessions - min_sessions; i++) {
        item = TAILQ_FIRST(&tx_queue);
        if (!item) {
            break;
        }

        if (item->session_id == session_id) {
            break;
        }
    }

    // Remove the TX queue data item from the linked list and cache
    if (item) {
        TAILQ_REMOVE(&tx_queue, item, entries);
        free(item);
        cache[session_id % CACHE_SIZE] = NULL;
    }

    // Unlock the mutex
