// Structure to store information about each network session
typedef struct NetworkSession {
    long timestamp;
    int identifier;
    void* network_session;
} NetworkSession;

// Pool of network sessions
static NetworkSession* pool = NULL;

// Lock-free queue for managing session requests
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t condition = PTHREAD_COND_INITIALIZER;
static int pool_size = 0;
static int max_pool_size = 10; // configurable maximum capacity of the session pool

// Function to dynamically manage a pool of network sessions
NetworkSession* allocate_session(const char* hostname, const char* port) {
    NetworkSession* new_session = NULL;
    int identifier = 0;
    long timestamp = time(NULL);

    // Lock the queue before accessing it
    pthread_mutex_lock(&lock);

    // Check if the pool has reached its maximum capacity
    if (pool_size >= max_pool_size) {
        // Attempt to reclaim space by closing inactive sessions
        for (int i = 0; i < pool_size; i++) {
            if (pool[i].identifier == identifier && pool[i].network_session != NULL) {
                close_session(pool[i].network_session);
                break;
            }
        }
    }

    // If there is still space in the pool, create a new session and add it to the pool
    if (pool_size < max_pool_size) {
        new_session = malloc(sizeof(NetworkSession));
        if (new_session != NULL) {
            identifier = generate_sequence_number(timestamp, pool_size);
            new_session->identifier = identifier;
            new_session->network_session = init_network_session(hostname, port);
            if (new_session->network_session == NULL) {
                free(new_session);
                new_session = NULL;
            } else {
                pool[pool_size++] = *new_session;
            }
        }
    }

    // Unlock the queue after accessing it
    pthread_mutex_unlock(&lock);

    return new_session;
}

// Function to close a network session
void close_session(void* network_session) {
    int index = 0;

    // Lock the queue before accessing it
    pthread_mutex_lock(&lock);

    // Find the index of the session to be closed in the pool
    for (int i = 0; i < pool_size; i++) {
        if (pool[i].network_session == network_session) {
            index = i;
            break;
        }
    }

    // If the session was found, close it and remove it from the pool
    if (index != 0) {
        close_network_session(pool[index].network_session);
        free(pool[index].network_session);
        memmove(&pool[index], &pool[index + 1], (pool_size - index - 1) * sizeof(NetworkSession));
        pool_size--;
    }

    // Unlock the queue after accessing it
    pthread_mutex_unlock(&lock);
