// Function to process a line of the log file
void process_line(const char* line, size_t line_length) {
    // Allocate memory for the log entry
    LogEntry* entry = malloc(sizeof(LogEntry));
    if (entry == NULL) {
        fprintf(stderr, "Failed to allocate memory for log entry\n");
        return;
    }

    // Extract relevant metrics from the last three fields of the line
    int field1 = 0;
    int field2 = 0;
    int field3 = 0;
    sscanf(line + line_length - 3, "%d %d %d", &field1, &field2, &field3);

    // Compute the average of the last three fields
    double avg = (double) (field1 + field2 + field3) / 3;

    // Append the average as the next field at the end of the line
    entry->field1 = field1;
    entry->field2 = field2;
    entry->field3 = field3;
    entry->field4 = avg;

    // Free the memory allocated for the log entry
    free(entry);
}

// Function to process a large log file containing structured data
void process_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        return;
    }

    // Read each line of the file and process it using process_line()
    char* line = NULL;
    size_t capacity = 0;
    while (getline(&line, &capacity, file) != -1) {
        process_line(line, strlen(line));
    }

    // Close the file and free memory allocated for it
    fclose(file);
    free(line);
}

