int compare_log_entries(const void* entry1, const void* entry2) {
    LogEntry* entry1 = (LogEntry*) entry1;
    LogEntry* entry2 = (LogEntry*) entry2;

    // Compare the specified numeric field of the log entries
    if (entry1->field4 > entry2->field4) {
        return 1;
    } else if (entry1->field4 < entry2->field4) {
        return -1;
    } else {
        // If the specified numeric fields are equal, compare the second field
        if (entry1->field3 > entry2->field3) {
            return 1;
        } else if (entry1->field3 < entry2->field3) {
            return -1;
        } else {
            // If the second fields are equal, compare the third field
            if (entry1->field2 > entry2->field2) {
                return 1;
            } else if (entry1->field2 < entry2->field2) {
                return -1;
            } else {
                // If all fields are equal, the log entries are considered equal
                return 0;
            }
        }
    }
}

// Function to persist processed log entries in a compressed format
void serialize_log_entries(LogEntry* entries, size_t num_entries) {
    // Use a custom serialization format that minimizes storage and retrieval efficiency
    for (size_t i = 0; i < num_entries; ++i) {
        LogEntry entry = entries[i];
        char buffer[50];
        sprintf(buffer, "%d %d %d %.2f\n", entry.field1, entry.field2, entry.field3, entry.field4);
        fwrite(buffer, strlen(buffer), 1, stdout);
    }
}

// Function to deserialize processed log entries from a compressed format
void deserialize_log_entries(LogEntry* entries, size_t num_entries) {
    // Use a custom deserialization format that minimizes storage and retrieval efficiency
    for (size_t i = 0; i < num_entries; ++i) {
        char buffer[50];
        fgets(buffer, 50, stdin);
        sscanf(buffer, "%d %d %d %.2f", &entries[i].field1, &entries[i].field2, &entries[i].field3, &entries[i].field4);
    }
}

