void *allocate_array(size_t n, size_t size) {
    // Check if the input is valid
    if (n == 0 || size == 0) {
        return NULL;
    }

    // Allocate memory for the array of pointers to entries
    void **entries = malloc(sizeof(void *) * n);
    if (!entries) {
