    // Check if the input is valid
    if (!file || n == 0) {
        return NULL;
    }

    // Allocate memory for an array of pointers to struct record instances
    void **records = malloc(sizeof(void *) * n);
    if (!records) {
        return NULL;
    }

    // Read the records from the input file in binary format and allocate memory for each record
    for (size_t i = 0; i < n; i++) {
        struct record *record = malloc(sizeof(struct record));
        if (!record) {
            break;
        }

        // Read the record from the input file in binary format and set its value field
        fread(record, sizeof(struct record), 1, file);
        records[i] = record;
    }

    // Check if any allocation failed and free the allocated memory if necessary
    if (i < n) {
        for (size_t j = 0; j < i; j++) {
            free(records[j]);
        }
        free(records);
        return NULL;
    }

    return records;
}

// Define a function to handle I/O errors during file serialization and deserialization by retrying with exponential backoff
void *handle_io_error(FILE *file, size_t n, void *records) {
    // Check if the input is valid
    if (!file || !records || n == 0) {
        return NULL;
    }

    // Retry the operation with exponential backoff until it succeeds or the maximum number of retries is reached
    size_t retries = 5;
    while (retries > 0) {
        // Read the records from the input file in binary format and allocate memory for each record
        void **records = deserialize_records(file, n);
        if (records) {
            return records;
        }

        // Sleep for a random amount of time between 0 and 1 second to prevent overwhelming the file system
        sleep(rand() % 1 + 1);

        retries--;
    }

    // Return NULL if all retries fail
    return NULL;
}
