// Define the structure for an item in the tree
typedef struct {
    char* name;
    int quantity;
    struct TreeNode* parent;
} Item;

// Define the structure for a node in the tree
typedef struct TreeNode {
    Item* item;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

// Function to allocate memory for a new item and initialize its fields
Item* create_item(const char* name, int quantity, TreeNode* parent) {
    Item* new_item = malloc(sizeof(Item));
    if (new_item == NULL) {
        return NULL;
    }

    // Copy the name and quantity to the new item
    size_t name_len = strlen(name);
    new_item->name = malloc(name_len + 1);
    if (new_item->name == NULL) {
        free(new_item);
        return NULL;
    }
    memcpy(new_item->name, name, name_len + 1);
    new_item->quantity = quantity;

    // Set the parent of the new item
    if (parent != NULL) {
        new_item->parent = parent;
    } else {
        new_item->parent = NULL;
    }

    return new_item;
}

// Function to allocate memory for a new tree node and initialize its fields
TreeNode* create_node(Item* item) {
    TreeNode* new_node = malloc(sizeof(TreeNode));
    if (new_node == NULL) {
        return NULL;
    }

    // Copy the item to the new node
    new_node->item = item;

    // Set the parent of the new node
    if (item != NULL && item->parent != NULL) {
        new_node->parent = item->parent;
    } else {
        new_node->parent = NULL;
    }

    return new_node;
}

// Function to add a new item to the tree
void add_item(TreeNode* root, Item* item) {
    if (root == NULL || item == NULL) {
        return;
    }

    // Check if the item is already in the tree
    if (search_item(root, item)) {
        return;
    }

    // Create a new node for the item and add it to the tree
    TreeNode* new_node = create_node(item);
    if (new_node == NULL) {
        return;
    }

    // Determine where to insert the new node in the tree
    TreeNode* parent = root;
    while (parent->left != NULL && parent->right != NULL) {
        if (strcmp(parent->item->name, item->name) > 0) {
            parent = parent->left;
        } else {
            parent = parent->right;
        }
    }

    // Insert the new node into the tree
    if (strcmp(parent->item->name, item->name) > 0) {
        parent->left = new_node;
    } else {
        parent->right = new_node;
    }
}

// Function to remove an item from the tree
void remove_item(TreeNode* root, Item* item) {
    if (root == NULL || item == NULL) {
        return;
    }

    // Check if the item is in the tree
    TreeNode* node = search_node(root, item);
    if (node == NULL) {
        return;
    }

    // Determine where to remove the node from the tree
    if (node->left != NULL && node->right != NULL) {
        // If the node has two children, replace it with its inorder successor
        TreeNode* successor = find_successor(node);
        if (successor == NULL) {
            return;
        }

        // Replace the node with its inorder successor
        strcpy(node->item->name, successor->item->name);
        node->item->quantity = successor->item->quantity;
        node->parent = successor->parent;

        // Remove the inorder successor from the tree
        remove_node(successor);
    } else {
        // If the node has only one child, replace it with its child
        if (node->left != NULL) {
            strcpy(node->item->name, node->left->item->name);
            node->item->quantity = node->left->item->quantity;
            node->parent = node->left->parent;
            free(node->left);
        } else if (node->right != NULL) {
            strcpy(node->item->name, node->right->item->name);
            node->item->quantity = node->right->item->quantity;
            node->parent = node->right->parent;
            free(node->right);
        } else {
            // If the node has no children, remove it from its parent
            if (node->parent != NULL) {
                TreeNode* child = node->parent->left == node ? node->parent->left : node->parent->right;
                if (child == NULL) {
                    return;
                }

                // Replace the node with its child
                strcpy(node->item->name, child->item->name);
                node->item->quantity = child->item->quantity;
                node->parent = child->parent;

                free(child);
            } else {
                // If the node is the root and has no children, set its fields to NULL
                node->item->name = NULL;
                node->item->quantity = 0;
                node->parent = NULL;
            }
        }
    }
}

// Function to search for an item in the tree
TreeNode* search_node(TreeNode* root, Item* item) {
    if (root == NULL || item == NULL) {
        return NULL;
    }

    // Check if the item is in the current node
    if (strcmp(root->item->name, item->name) == 0) {
        return root;
    }

    // Recursively search the left and right subtrees
    TreeNode* left = search_node(root->left, item);
    TreeNode* right = search_node(root->right, item);

    if (left != NULL) {
        return left;
    } else if (right != NULL) {
        return right;
    } else {
        return NULL;
    }
}

// Function to find the inorder successor of a node
TreeNode* find_successor(TreeNode* node) {
    // If the node has no left subtree, it has no successor
    if (node->left == NULL) {
        return NULL;
    }

    TreeNode* current = node->left;
    while (current->right != NULL) {
        current = current->right;
    }

    return current;
}

// Function to remove a node from the tree
void remove_node(TreeNode* node) {
    if (node == NULL) {
        return;
    }

    // Remove the node's left and right subtrees
    free(node->left);
    free(node->right);

    // Free the node itself
    free(node);
}

// Function to traverse the tree and print each item's details in a formatted manner
void traverse_tree(TreeNode* root, int order) {
    if (root == NULL) {
        return;
    }

    // Traverse the left subtree
    traverse_tree(root->left, order);

    // Print the item's details in a formatted manner
    printf("Item: %s, Quantity: %d\n", root->item->name, root->item->quantity);

    // Traverse the right subtree
    traverse_tree(root->right, order);
}
