    struct item* node = malloc(sizeof(struct item));
    node->name = strdup(name);
    node->quantity = quantity;
    node->parent = NULL;
    return node;
}

// Function to add a new node as a child of another node
void add_node(struct item* parent, struct item* child) {
    if (parent == NULL || child == NULL) {
        printf("Invalid argument\n");
        return;
    }
    // Add the child to the list of children of the parent
    child->parent = parent;
    // Update the parent's quantity by adding the child's quantity
    parent->quantity += child->quantity;
}

// Function to validate the integrity of the tree structure
void validate_tree(struct item* root) {
    if (root == NULL) {
        printf("Tree is empty\n");
        return;
    }
    // Check that each node points to its parent correctly
    struct item* current = root;
    while (current != NULL) {
        if (current->parent == NULL) {
            printf("Node %s has no parent\n", current->name);
            return;
        } else if (current->parent != current) {
            printf("Node %s has a cycle\n", current->name);
            return;
        }
        current = current->next;
    }
}

// Function to populate a predefined set of nodes and their respective parents
void populate_tree(struct item* root) {
    // Populate the tree with some initial nodes
    struct item* node1 = create_node("Node 1", 10);
    struct item* node2 = create_node("Node 2", 20);
    struct item* node3 = create_node("Node 3", 30);
    struct item* node4 = create_node("Node 4", 40);
    add_node(root, node1);
    add_node(root, node2);
    add_node(root, node3);
    add_node(root, node4);
}

// Function to traverse the tree and print each item's details in a formatted manner
void traverse_tree(struct item* root) {
    if (root == NULL) {
        printf("Tree is empty\n");
        return;
    }
    struct item* current = root;
    while (current != NULL) {
        printf("%s: %d, Parent: %s\n", current->name, current->quantity, current->parent ? current->parent->name : "NULL");
        current = current->next;
    }
}
