#include <arpa/inet.h>

#define MAX_CLIENTS 20 // maximum number of clients
#define MAX_MEMORY_USAGE 10000000 // maximum memory usage in bytes (10MB)
#define TEMPERATURE_MIN -50.0f
#define TEMPERATURE_MAX 80.0f
#define HUMIDITY_MIN 0.0f
#define HUMIDITY_MAX 100.0f

typedef struct {
    float temperature;
    float humidity;
    time_t timestamp;
    int sensor_id;
} SensorData;

typedef struct {
    SensorData data[20000]; // maximum number of data points per client
    int next_data_index; // index of the next data point to be written
    int num_data_points; // total number of data points received from this client
} ClientData;

typedef struct {
    int rnti; // Resource Identifier (RNTI) for the NFAPI_CRC_INDICATION_PDU_T structure
    int client_index; // index of the client in the clients array
} RNTIAssignment;

// thread-safe counter for logging total number of unique RNTIs assigned
static int rnti_counter = 0;

// disjoint-set (Union-Find) data structure for managing RNTI assignments
static RNTIAssignment *rnti_assignments = NULL;

// array of client data structures, each corresponding to a connected client
static ClientData clients[MAX_CLIENTS];

// mutex for protecting access to the clients and rnti_assignments arrays
static pthread_mutex_t clients_mutex = PTHREAD_MUTEX_INITIALIZER;

// function for handling a distributed sensor data processing module in a highly concurrent environment
void manageSensorDataAndNFAPIIndications(int client_fd, void *client_data) {
    // check if the maximum memory usage limit has been reached
    if (sizeof(rnti_assignments) >= MAX_MEMORY_USAGE) {
        printf("Maximum memory usage limit reached\n");
        return;
    }

    // get the next available RNTI from the disjoint-set data structure
    int rnti = find_rnti(rnti_assignments, -1);
    if (rnti == -1) {
        printf("Error: unable to allocate RNTI\n");
        return;
    }

    // assign the client a unique RNTI based on the RNTI assignment structure
    int client_index = *(int *)client_data;
    if (rnti_assignments[client_index].rnti != -1) {
        printf("Error: duplicate RNTI assignment\n");
        return;
    }
    rnti_assignments[client_index].rnti = rnti;

    // increment the thread-safe counter for logging total number of unique RNTIs assigned
    pthread_mutex_lock(&clients_mutex);
    ++rnti_counter;
    pthread_mutex_unlock(&clients_mutex);

    // loop over received data points from the client
    while (true) {
        // receive a data point from the client
        SensorData data;
        recv(client_fd, &data, sizeof(SensorData), 0);

        // validate the data point and ensure all values fall within predefined operational ranges
        if (!validate_sensor_data(&data)) {
            printf("Error: invalid sensor data\n");
            return;
        }

        // allocate memory for the received data point in the client's data structure
        int next_index = clients[client_index].next_data_index++;
        if (clients[client_index].num_data_points == MAX_DATA_POINTS) {
            printf("Error: maximum number of data points reached\n");
            return;
        }
        clients[client_index].data[next_index] = data;
        ++clients[client_index].num_data_points;

        // log the received data point to the console for debugging purposes
        printf("Client %d: Received data point [%d, %d, %f, %f]\n", client_index, next_index, rnti, data.temperature, data.humidity);
    }
}

// function for handling asynchronous I/O operations using non-blocking sockets
void handle_asynchronous_io(int client_fd) {
    // create a new thread to handle the client's connection
    pthread_t thread;
    if (pthread_create(&thread, NULL, manageSensorDataAndNFAPIIndications, &client_fd)) {
        printf("Error: unable to create thread\n");
        return;
    }
}

// function for managing concurrent connections efficiently using non-blocking sockets
void manage_concurrent_connections(int client_fd) {
    // loop over received data from the client
    while (true) {
        // receive a message from the client
        char buffer[1024];
        int bytes_received = recv(client_fd, &buffer, sizeof(buffer), 0);
        if (bytes_received <= 0) {
            break;
        }

        // handle the received message asynchronously in a new thread
        pthread_t thread;
        if (pthread_create(&thread, NULL, handle_asynchronous_io, &client_fd)) {
            printf("Error: unable to create thread\n");
            return;
        }
    }
}

// function for handling memory leaks in the program
void handle_memory_leak(int client_fd) {
    // get the next available RNTI from the disjoint-set data structure
    int rnti = find_rnti(rnti_assignments, -1);
    if (rnti == -1) {
        printf("Error: unable to allocate RNTI\n");
        return;
    }

    // assign the client a unique RNTI based on the RNTI assignment structure
    int client_index = *(int *)client_data;
    if (rnti_assignments[client_index].rnti != -1) {
        printf("Error: duplicate RNTI assignment\n");
        return;
    }
    rnti_assignments[client_index].rnti = rnti;

    // increment the thread-safe counter for logging total number of unique RNTIs assigned
    pthread_mutex_lock(&clients_mutex);
    ++rnti_counter;
    pthread_mutex_unlock(&clients_mutex);
}

// function for detecting and handling memory leaks in the program
void handle_memory_leak() {
    // check if any memory leaks have occurred
    if (sizeof(rnti_assignments) >= MAX_MEMORY_USAGE) {
        printf("Error: memory leak detected\n");
        return;
    }
}

// function for serializing the array of structures to a file
void serialize_data() {
    // open the output file in write mode
    FILE *output_file = fopen("sensor_data.bin", "wb+");
    if (output_file == NULL) {
        printf("Error: unable to open output file\n");
        return;
    }

    // serialize the array of structures to the output file
    for (int i = 0; i < MAX_CLIENTS; ++i) {
        fwrite(&clients[i], sizeof(ClientData), 1, output_file);
    }

    // close the output file
    fclose(output_file);
}

// function for deserializing the array of structures from a file
void deserialize_data() {
    // open the input file in read mode
    FILE *input_file = fopen("sensor_data.bin", "rb");
    if (input_file == NULL) {
        printf("Error: unable to open input file\n");
        return;
    }

    // deserialize the array of structures from the input file
    for (int i = 0; i < MAX_CLIENTS; ++i) {
        fread(&clients[i], sizeof(ClientData), 1, input_file);
    }

    // close the input file
    fclose(input_file);
}

// function for validating sensor data
bool validate_sensor_data(SensorData *data) {
    if (data->temperature < TEMPERATURE_MIN || data->temperature > TEMPERATURE_MAX) {
        return false;
    }
    if (data->humidity < HUMIDITY_MIN || data->humidity > HUMIDITY_MAX) {
        return false;
    }
    return true;
}

// function for finding the next available RNTI in the disjoint-set data structure
int find_rnti(RNTIAssignment *assignments, int exclude_client_index) {
    // loop over all possible RNTIs
    for (int i = 0; i < MAX_CLIENTS; ++i) {
        if (i == exclude_client_index) continue;
        if (assignments[i].rnti == -1) return i;
    }

    // no available RNTIs found, return -1
    return -1;
}
