#include <time.h>

// Custom record structure for storing device configurations
typedef struct {
    long device_id;
    int config_version;
    char* supported_protocols[10]; // Maximum of 10 supported wireless protocols
} Record;

// Memory pool strategy to minimize fragmentation and improve performance in high-throughput scenarios
void* memoryPoolAlloc(size_t size) {
    static void *memPool = NULL;
    if (memPool == NULL) {
        memPool = malloc(size);
    } else {
        memPool = realloc(memPool, size);
    }
    return memPool;
}

// Allocate memory for long offset values and int keys arrays
void allocateMemory(long** offsets, int** keys) {
    // Validate user input to prevent buffer overflows
    if (offsets == NULL || keys == NULL) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    // Allocate memory for long offset values array
    *offsets = malloc(sizeof(long) * userInput);
    if (*offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        return;
    }

    // Allocate memory for int keys array
    *keys = malloc(sizeof(int) * userInput);
    if (*keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        free(*offsets);
        return;
    }
}

// Allocate and initialize custom record structures
void allocateRecords(Record** records) {
    // Validate user input to prevent buffer overflows
    if (records == NULL) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    // Allocate memory for record array
    *records = malloc(sizeof(Record) * userInput);
    if (*records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        return;
    }

    // Initialize each record with a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < userInput; ++i) {
        (*records)[i].device_id = rand() % (max_id - min_id + 1) + min_id; // Generate random device ID within range
        (*records)[i].config_version = rand(); // Random config version
        for (int j = 0; j < 10; ++j) { // Maximum of 10 supported wireless protocols
            (*records)[i].supported_protocols[j] = malloc(sizeof(char) * MAX_PROTOCOL_LENGTH);
            if ((*records)[i].supported_protocols[j] == NULL) {
                fprintf(stderr, "Failed to allocate memory for supported protocol.\n");
                free(*records);
                return;
            }
        }
    }
}

// Thread-safe counter to track and log the total number of unique identifiers
void incrementCounter(long* counter) {
    pthread_mutex_lock(&counter_mutex);
    (*counter)++;
    pthread_mutex_unlock(&counter_mutex);
}

// Memory cleanup function to free allocated memory
void freeMemory(long** offsets, int** keys, Record** records) {
    if (offsets != NULL) {
        free(*offsets);
    }
    if (keys != NULL) {
        free(*keys);
    }
    if (records != NULL) {
        for (int i = 0; i < userInput; ++i) {
            free((*records)[i].supported_protocols[10]); // Free memory allocated for supported protocols
        }
        free(*records);
    }
}

// Fallback mechanism to generate unique identifiers if random generation fails frequently
long getUniqueId(long* counter) {
    long id = (*counter)++;
    if (id == 0 || id > MAX_ID) { // If ID is zero or greater than maximum ID, increment the counter and try again
        return getUniqueId(counter);
    }
    return id;
}

// Check mechanism to validate input parameters and prevent buffer overflows
bool checkInputParameters(long** offsets, int** keys) {
    if (offsets == NULL || keys == NULL) {
        fprintf(stderr, "Invalid input parameters.\n");
        return false;
    }
    return true;
}

// Function to manage dynamic memory allocation and initialization for complex data structures
void allocateAndInitialize(long* offsets, int* keys, Record** records) {
    // Validate user input to prevent buffer overflows
    if (!checkInputParameters(&offsets, &keys)) {
        return;
    }

    // Allocate memory for long offset values array
    allocateMemory(offsets, keys);
    // Allocate and initialize custom record structures
    allocateRecords(records);
    // Thread-safe counter to track and log the total number of unique identifiers
    pthread_mutex_t counter_mutex;
    long counter = 0;
    incrementCounter(&counter);

    // Fallback mechanism to generate unique identifiers if random generation fails frequently
    srand(time(NULL));
    for (int i = 0; i < userInput; ++i) {
        (*records)[i].device_id = getUniqueId(&counter);
    }
