// Function to add a new item to the cache
void addItemToCache(char *key, char *value, int expiration) {
    // Check if the key already exists in the cache
    for (int i = 0; i < CACHE_MAX_ITEMS; i++) {
        if (!strcmp(cache[i].key, key)) {
            return; // Item already exists, do nothing
        }
    }

    // Find an empty slot in the cache for the new item
    int index = -1;
    for (int i = 0; i < CACHE_MAX_ITEMS; i++) {
        if (!cache[i].key[0]) {
            index = i;
            break;
        }
    }

    // Add the new item to the cache
    if (index != -1) {
        strcpy(cache[index].key, key);
        strcpy(cache[index].value, value);
        cache[index].expiration = expiration;
    } else {
        // Cache is full, replace the least recently used item
        for (int i = 0; i < CACHE_MAX_ITEMS; i++) {
            if (cache[i].expiration < cache[i+1].expiration) {
                index = i;
                break;
            }
        }
        strcpy(cache[index].key, key);
        strcpy(cache[index].value, value);
        cache[index].expiration = expiration;
    }
}

// Function to retrieve an item from the cache by its key
char *getItemFromCache(char *key) {
    // Check if the key exists in the cache
    for (int i = 0; i < CACHE_MAX_ITEMS; i++) {
        if (!strcmp(cache[i].key, key)) {
            return cache[i].value;
        }
    }

    // If the key does not exist, return NULL
    return NULL;
}

