    // Calculate the total size required for the transactions and metadata
    size_t total_size = sizeof(struct transaction) + sizeof(struct metadata);
    if (schema_version > 0) {
        total_size += get_metadata_size(schema_version);
    }

    // Allocate memory for the transactions and metadata
