// Structure definitions
struct transaction {
    long timestamp;
    float amount;
    int status;
    char* metadata;
};

struct TX_QUEUE_DATA_ITEM {
    int session_id;
    int sequence_number;
    int payload_size;
};

// Function to dynamically allocate memory for an array of 'transaction' structures
void *allocate_transactions(int num_transactions) {
    struct transaction* transactions = malloc(num_transactions * sizeof(struct transaction));
    if (!transactions) {
        perror("malloc failed");
        return NULL;
    }
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].status = DEFAULT_STATUS; // Set default status
        transactions[i].metadata = malloc(sizeof(char) * METADATA_SIZE);
        if (!transactions[i].metadata) {
            perror("malloc failed");
            return NULL;
        }
    }
    return transactions;
}

// Function to dynamically allocate memory for an array of 'TX_QUEUE_DATA_ITEM' structures
void *allocate_queue_data_items(int num_sessions) {
    struct TX_QUEUE_DATA_ITEM* queue_data_items = malloc(num_sessions * sizeof(struct TX_QUEUE_DATA_ITEM));
    if (!queue_data_items) {
        perror("malloc failed");
        return NULL;
    }
    return queue_data_items;
}

// Function to populate the transaction array with timestamps and amounts, setting the status to a default value
void populate_transactions(struct transaction* transactions, int num_transactions) {
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].timestamp = get_timestamp();
        transactions[i].amount = get_amount();
        transactions[i].status = DEFAULT_STATUS;
    }
}

// Function to validate and initialize the transaction array's integrity
void validate_transactions(struct transaction* transactions, int num_transactions) {
    for (int i = 0; i < num_transactions; i++) {
        if (!transactions[i].metadata) {
            perror("Transaction metadata is NULL");
            return;
        }
        if (strlen(transactions[i].metadata) > METADATA_SIZE) {
            perror("Transaction metadata size exceeds limit");
            return;
        }
    }
}

// Function to deallocate resources for a transaction array
void deallocate_transactions(struct transaction* transactions, int num_transactions) {
    for (int i = 0; i < num_transactions; i++) {
        free(transactions[i].metadata);
    }
    free(transactions);
}

// Function to deallocate resources for a queue data item array
void deallocate_queue_data_items(struct TX_QUEUE_DATA_ITEM* queue_data_items, int num_sessions) {
    free(queue_data_items);
}

// Network interface module to handle dynamic number of concurrent sessions
struct network_interface {
    struct TX_QUEUE_DATA_ITEM* queue_data_items; // Array of queue data items for each session
    int num_sessions; // Number of active sessions
    pthread_mutex_t mutex; // Mutex to protect access to the queue data items array
};

// Function to allocate resources for a new network interface module instance
struct network_interface* allocate_network_interface(int num_sessions) {
    struct network_interface* ni = malloc(sizeof(struct network_interface));
    if (!ni) {
        perror("malloc failed");
        return NULL;
    }
    ni->queue_data_items = allocate_queue_data_items(num_sessions);
    if (!ni->queue_data_items) {
        perror("allocate_queue_data_items failed");
        free(ni);
        return NULL;
    }
    ni->num_sessions = num_sessions;
    pthread_mutex_init(&ni->mutex, NULL);
    return ni;
}

// Function to deallocate resources for a network interface module instance
void deallocate_network_interface(struct network_interface* ni) {
    if (ni) {
        deallocate_queue_data_items(ni->queue_data_items, ni->num_sessions);
        pthread_mutex_destroy(&ni->mutex);
        free(ni);
    }
}

// Function to add a new transaction to the queue data item array for a specific session
void enqueue_transaction(struct network_interface* ni, int session_id, struct transaction* transaction) {
    pthread_mutex_lock(&ni->mutex);
    if (ni->num_sessions < session_id) {
        perror("Session ID exceeds maximum number of sessions");
        return;
    }
    ni->queue_data_items[session_id].sequence_number++; // Increment sequence number
    ni->queue_data_items[session_id].payload_size = sizeof(struct transaction); // Set payload size
    memcpy(&ni->queue_data_items[session_id].transaction, transaction, sizeof(struct transaction)); // Copy transaction data
    pthread_mutex_unlock(&ni->mutex);
}

// Function to remove a transaction from the queue data item array for a specific session
void dequeue_transaction(struct network_interface* ni, int session_id) {
    pthread_mutex_lock(&ni->mutex);
    if (ni->num_sessions < session_id) {
        perror("Session ID exceeds maximum number of sessions");
        return;
    }
    // Decrement sequence number and reset payload size to 0
    ni->queue_data_items[session_id].sequence_number--;
    ni->queue_data_items[session_id].payload_size = 0;
    pthread_mutex_unlock(&ni->mutex);
}

// Function to retrieve the next transaction from the queue data item array for a specific session
struct transaction* peek_next_transaction(struct network_interface* ni, int session_id) {
    pthread_mutex_lock(&ni->mutex);
    if (ni->num_sessions < session_id) {
        perror("Session ID exceeds maximum number of sessions");
        return NULL;
    }
    // Return a copy of the transaction data
    struct transaction* transaction = malloc(sizeof(struct transaction));
    memcpy(transaction, &ni->queue_data_items[session_id].transaction, sizeof(struct transaction));
    pthread_mutex_unlock(&ni->mutex);
    return transaction;
}
