void init_memory_pool(MemoryPool* pool, size_t capacity) {
  pool->capacity = capacity;
  pool->used = 0;
  pool->freelist = 0;
  pool->records = (Record*)malloc(sizeof(Record) * capacity);
}

// Allocate and initialize a new record
Record* allocate_record(MemoryPool* pool, long offset, int key) {
  if (pool->used == pool->capacity) {
    // Expand memory pool if necessary
    pool->records = realloc(pool->records, sizeof(Record) * (pool->capacity + 10));
    pool->capacity += 10;
  }
  Record* record = &pool->records[pool->used++];
  record->offset = offset;
  record->key = key;
  return record;
}

// Free a previously allocated record
void free_record(MemoryPool* pool, Record* record) {
  // Add record to freelist
  pool->freelist = record - pool->records;
  --pool->used;
}

