#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <sys/wait.h>
#include <sys/select.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <signal.h>
#include <poll.h>
#include <kubernetes/client.h>
#include <logging.h>

#define MAX_MANIFESTS 100
#define MANIFEST_PATH "/path/to/manifests"
#define MANIFEST_FILE_PATTERN "manifest-%d.yaml"
#define CONFIG_FILE_PATH "/path/to/config.json"
#define LOG_FILE_PATH "/path/to/log.txt"
#define NUM_THREADS 8
#define TIMEOUT 30 // seconds
#define BACKOFF_FACTOR 2
#define MIN_BACKOFF_INTERVAL 10 // seconds
#define MAX_BACKOFF_INTERVAL 60 // seconds
#define ERROR_DELAY 5 // minutes

typedef struct manifest {
    int id;
    char *yaml;
} manifest_t;

manifest_t manifests[MAX_MANIFESTS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int num_manifests = 0;
int num_failed_deployments = 0;
int total_deployments = 0;
int failed_deployment_count = 0;
int current_deployment_id = 0;
int last_successful_deployment_id = 0;

void deploy_manifest(manifest_t *m) {
    int ret = kubernetes_apply(m->yaml);
    if (ret != 0) {
        log_error("Failed to apply manifest: %s", m->yaml);
        pthread_mutex_lock(&lock);
        num_failed_deployments++;
        total_deployments++;
        failed_deployment_count++;
        pthread_mutex_unlock(&lock);
    } else {
        log_info("Successfully deployed manifest: %s", m->yaml);
        pthread_mutex_lock(&lock);
        num_failed_deployments = 0;
        total_deployments++;
        current_deployment_id = m->id;
        last_successful_deployment_id = current_deployment_id;
        pthread_mutex_unlock(&lock);
    }
}

void deploy_manifests() {
    int i;
    for (i = 0; i < num_manifests; i++) {
        manifest_t *m = &manifests[i];
        if (m->id > current_deployment_id) {
            log_info("Deploying manifest: %s", m->yaml);
            deploy_manifest(m);
        } else {
            break;
        }
    }
}

void apply_next_manifest() {
    int ret;
    char *yaml = NULL;
    manifest_t *m = NULL;
    if (num_failed_deployments > ERROR_DELAY) {
        log_error("Reached error delay threshold, rolling back to last successful deployment");
        kubernetes_rollback(last_successful_deployment_id);
        num_failed_deployments = 0;
    } else {
        pthread_mutex_lock(&lock);
        m = &manifests[current_deployment_id];
        yaml = strdup(m->yaml);
        total_deployments++;
        current_deployment_id++;
        pthread_mutex_unlock(&lock);
        log_info("Applying manifest: %s", yaml);
        ret = kubernetes_apply(yaml);
        if (ret != 0) {
            log_error("Failed to apply manifest: %s", yaml);
            pthread_mutex_lock(&lock);
            num_failed_deployments++;
            total_deployments++;
            failed_deployment_count++;
            pthread_mutex_unlock(&lock);
        } else {
            log_info("Successfully applied manifest: %s", yaml);
            free(yaml);
        }
    }
}

void* apply_manifests_thread(void *arg) {
    int i;
    for (i = 0; i < MAX_MANIFESTS; i++) {
        if (num_failed_deployments > ERROR_DELAY) {
            log_error("Reached error delay threshold, rolling back to last successful deployment");
            kubernetes_rollback(last_successful_deployment_id);
            num_failed_deployments = 0;
        } else if (current_deployment_id < total_deployments) {
            apply_next_manifest();
        }
    }
}

int main() {
    int i, ret;
    pthread_t threads[NUM_THREADS];
    manifest_t *m = NULL;
    char *yaml = NULL;
    char file_pattern[1024];

    // Load manifests from disk
    log_info("Loading manifests from disk");
    for (i = 0; i < MAX_MANIFESTS; i++) {
        sprintf(file_pattern, MANIFEST_FILE_PATTERN, i);
        yaml = load_manifest_from_disk(MANIFEST_PATH, file_pattern);
        if (yaml != NULL) {
            m = &manifests[i];
            m->id = i;
            m->yaml = yaml;
            num_manifests++;
            log_info("Loaded manifest: %d - %s", i, yaml);
        } else {
            break;
        }
    }

    // Set up logging and configuration management
    set_logging_config(CONFIG_FILE_PATH);

    // Deploy manifests in a separate thread to allow for concurrent execution
    log_info("Deploying manifests in separate threads");
    for (i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, apply_manifests_thread, NULL);
    }

    // Deploy remaining manifests sequentially
    deploy_manifests();

    // Wait for all threads to finish
    for (i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    log_info("Cleaning up");
    for (i = 0; i < num_manifests; i++) {
        free(manifests[i].yaml);
    }

    // Return success or failure based on number of failed deployments
    if (num_failed_deployments == 0) {
        log_info("All deployments succeeded");
        return 1;
    } else {
        log_error("Number of failed deployments: %d", num_failed_deployments);
        return 0;
    }
}
