// Define a struct to represent a record in the data structure
typedef struct {
  int timestamp;
  int status_indicator;
  float value;
} Record;

// Define a hash table for fast lookups by key
typedef struct {
  Record* records;
  size_t capacity;
  size_t count;
} HashTable;

// Define a tree structure to efficiently manage and query recent records
typedef struct {
  Record* records;
  size_t count;
} Tree;

// Function to initialize the data structure with a specified number of records and random seed
void init(HashTable* hash_table, size_t num_records, unsigned int seed) {
  // Allocate memory for the records array
  hash_table->records = malloc(sizeof(Record) * num_records);
  if (hash_table->records == NULL) {
    fprintf(stderr, "Failed to allocate memory for records\n");
    exit(1);
  }

  // Set the capacity and count of the hash table to the specified number of records
  hash_table->capacity = num_records;
  hash_table->count = 0;

  // Generate a random seed for reproducibility
  srand(seed);
}

// Function to insert a record into the data structure
void insert(HashTable* hash_table, int key, Record record) {
  // Check if the hash table is full and needs to be resized
  if (hash_table->count == hash_table->capacity) {
    resize(hash_table);
  }

  // Insert the record into the hash table using the specified key
  int index = get_index(key, hash_table->capacity);
  hash_table->records[index] = record;
  hash_table->count++;
}

// Function to retrieve a record from the data structure by its key
Record* retrieve(HashTable* hash_table, int key) {
  // Check if the specified key exists in the hash table
  if (hash_table->records[get_index(key, hash_table->capacity)] == NULL) {
    return NULL;
  }

  // Return the record associated with the specified key
  return &hash_table->records[get_index(key, hash_table->capacity)];
}

// Function to update a record in the data structure by its key
void update(HashTable* hash_table, int key, Record new_record) {
  // Check if the specified key exists in the hash table
  if (hash_table->records[get_index(key, hash_table->capacity)] == NULL) {
    return;
  }

  // Update the record associated with the specified key
  int index = get_index(key, hash_table->capacity);
  hash_table->records[index] = new_record;
}

// Function to efficiently query recent records based on a specified time window
void query(Tree* tree, int min_time, int max_time) {
  // Check if the specified time range is valid
  if (min_time >= max_time) {
    return;
  }

  // Traverse the tree structure to find all records within the specified time window
  for (int i = 0; i < tree->count; i++) {
    int timestamp = tree->records[i].timestamp;
    if (timestamp >= min_time && timestamp <= max_time) {
      // Print the record to the console
      printf("Record %d: status=%d, value=%.2f\n", timestamp, tree->records[i].status_indicator, tree->records[i].value);
    }
  }
}

// Function to resize the hash table when it is full
void resize(HashTable* hash_table) {
  // Create a new hash table with twice the capacity of the old one
  HashTable new_hash_table;
  new_hash_table.capacity = 2 * hash_table->capacity;
  new_hash_table.count = 0;
  new_hash_table.records = malloc(sizeof(Record) * new_hash_table.capacity);
  if (new_hash_table.records == NULL) {
    fprintf(stderr, "Failed to allocate memory for records\n");
    exit(1);
  }

  // Copy the old hash table into the new one
  for (int i = 0; i < hash_table->count; i++) {
    new_hash_table.records[i] = hash_table->records[i];
  }

  // Free the memory used by the old hash table
  free(hash_table->records);

  // Update the hash table with the new one
  *hash_table = new_hash_table;
}

// Function to handle errors when memory allocation fails or a requested key does not exist in the data structure
void error_handler(char* message) {
  fprintf(stderr, "Error: %s\n", message);
  exit(1);
}
```
