    system->log = (LogEntry*)malloc(sizeof(LogEntry) * sensorCount);

    // Populate readings and log entries
    for (int i = 0; i < sensorCount; i++) {
        system->readings[i].timestamp = timestamp;
        system->readings[i].temperature = temperature;

        system->log[i].timestamps[0] = timestamp;
        system->log[i].events[0] = "Sensor added";
    }

