// Custom memory manager
struct MemoryManager {
    void* mem;
    size_t size;
};

// Enum for record type
enum RecordType {
    LONG_OFFSET,
    INT_KEY
};

// Struct for records
struct Record {
    enum RecordType type;
    union {
        long offset;
        int key;
    };
};

// Function to initialize the list with a specified number of records
void initList(struct MemoryManager* memMgr, size_t numRecords) {
    // Allocate memory for the list
    struct Record* list = malloc(numRecords * sizeof(struct Record));
    if (!list) {
        printf("Error: failed to allocate memory\n");
        return;
    }
    memMgr->mem = list;
    memMgr->size = numRecords;
}

// Function to add a new record to the list
void addRecord(struct MemoryManager* memMgr, enum RecordType type, long offset) {
    // Check if the list is full
    if (memMgr->size == 0) {
        printf("Error: cannot add record - list is full\n");
        return;
    }

    // Allocate memory for the new record
    struct Record* newRecord = malloc(sizeof(struct Record));
    if (!newRecord) {
        printf("Error: failed to allocate memory for new record\n");
        return;
    }

    // Set the type and value of the new record
    newRecord->type = type;
    if (type == LONG_OFFSET) {
        newRecord->offset = offset;
    } else {
        newRecord->key = (int)offset;
    }

    // Add the new record to the list
    memMgr->mem = realloc(memMgr->mem, (memMgr->size + 1) * sizeof(struct Record));
    if (!memMgr->mem) {
        printf("Error: failed to resize memory for new record\n");
        return;
    }
    memcpy(memMgr->mem + memMgr->size, newRecord, sizeof(struct Record));
    memMgr->size++;
}

// Function to lookup a record in the list by its offset or key
struct Record* findRecord(struct MemoryManager* memMgr, long offset) {
    // Check if the list is empty
    if (memMgr->size == 0) {
        printf("Error: cannot find record - list is empty\n");
        return NULL;
    }

    // Loop through the records until the correct one is found or the end of the list is reached
    for (size_t i = 0; i < memMgr->size; i++) {
        struct Record* record = (struct Record*)memMgr->mem + i;
        if (record->type == LONG_OFFSET && record->offset == offset) {
            return record;
        } else if (record->type == INT_KEY && record->key == (int)offset) {
            return record;
        }
    }

    // Return NULL if the record is not found in the list
    printf("Error: cannot find record with offset %ld\n", offset);
    return NULL;
}

// Function to remove a record from the list by its offset or key
void removeRecord(struct MemoryManager* memMgr, long offset) {
    // Check if the list is empty
    if (memMgr->size == 0) {
        printf("Error: cannot remove record - list is empty\n");
        return;
    }

    // Loop through the records until the correct one is found or the end of the list is reached
    for (size_t i = 0; i < memMgr->size; i++) {
        struct Record* record = (struct Record*)memMgr->mem + i;
        if (record->type == LONG_OFFSET && record->offset == offset) {
            // Remove the record from the list
            memcpy(memMgr->mem + i, memMgr->mem + i + 1, (memMgr->size - i - 1) * sizeof(struct Record));
            memMgr->size--;
            free(record);
            return;
        } else if (record->type == INT_KEY && record->key == (int)offset) {
            // Remove the record from the list
            memcpy(memMgr->mem + i, memMgr->mem + i + 1, (memMgr->size - i - 1) * sizeof(struct Record));
            memMgr->size--;
            free(record);
            return;
        }
    }

    // Return NULL if the record is not found in the list
    printf("Error: cannot find record with offset %ld\n", offset);
}

// Function to populate the list with a specified number of records, where each record’s value is randomly generated within a given range
void populateList(struct MemoryManager* memMgr, size_t numRecords, long minValue, long maxValue) {
    // Check if the list is full
    if (memMgr->size == 0) {
        printf("Error: cannot populate list - list is empty\n");
        return;
    }

    // Loop through the records and randomly generate values for each one
    for (size_t i = 0; i < numRecords; i++) {
        struct Record* record = (struct Record*)memMgr->mem + i;
        if (record->type == LONG_OFFSET) {
            long value = minValue + rand() % (maxValue - minValue);
            record->offset = value;
        } else {
            int key = (int)(minValue + rand() % (maxValue - minValue));
            record->key = key;
        }
    }
}

// Function to handle asynchronous data updates from a remote server
void updateFromServer(struct MemoryManager* memMgr, long offset) {
    // Check if the list is empty
    if (memMgr->size == 0) {
        printf("Error: cannot update record - list is empty\n");
        return;
    }

    // Loop through the records until the correct one is found or the end of the list is reached
    for (size_t i = 0; i < memMgr->size; i++) {
        struct Record* record = (struct Record*)memMgr->mem + i;
        if (record->type == LONG_OFFSET && record->offset == offset) {
            // Update the value of the record with a new random value within the given range
            long value = minValue + rand() % (maxValue - minValue);
            record->offset = value;
            return;
