#include <pthread.h>
#include <semaphore.h>

// Define cache item structure
struct cache_item {
  int client_id;
  char* key;
  void* value;
  time_t expiration;
};

// Define cache metadata structure
struct cache_metadata {
  int num_clients;
  struct cache_item** items;
  pthread_mutex_t mutex;
  semaphore_t semaphore;
};

// Function to initialize and configure the cache module
void init_cache(int num_clients, int* client_ids) {
  // Allocate memory for cache metadata structure
  struct cache_metadata* metadata = (struct cache_metadata*) malloc(sizeof(struct cache_metadata));

  // Initialize mutex and semaphore
  pthread_mutex_init(&metadata->mutex, NULL);
  semaphore_init(&metadata->semaphore, 0, 1);

  // Allocate memory for cache items array
  metadata->items = (struct cache_item**) malloc(num_clients * sizeof(struct cache_item*));

  // Initialize cache items array
  for (int i = 0; i < num_clients; i++) {
    metadata->items[i] = (struct cache_item*) malloc(sizeof(struct cache_item));
    metadata->items[i]->client_id = client_ids[i];
    metadata->items[i]->key = NULL;
    metadata->items[i]->value = NULL;
    metadata->items[i]->expiration = 0;
  }

  // Initialize number of clients in cache
  metadata->num_clients = num_clients;

  // Set cache metadata pointer to global variable
  *cache_metadata_ptr = metadata;
}

// Function to update a set of time-series data points in the persistent storage system
void update_data_points(int client_id, int* data_point_ids, void** data_points, int num_data_points) {
  // Get cache metadata pointer
  struct cache_metadata* metadata = *cache_metadata_ptr;

  // Lock mutex to synchronize access to cache items array
  pthread_mutex_lock(&metadata->mutex);

  // Iterate over data points and update in cache items array
  for (int i = 0; i < num_data_points; i++) {
    int data_point_id = data_point_ids[i];
    void* data_point = data_points[i];

    // Check if data point exists in cache items array
    struct cache_item* item = metadata->items[client_id]->key;

    // If data point does not exist, create new entry in cache items array
    if (item == NULL) {
      item = (struct cache_item*) malloc(sizeof(struct cache_item));
      item->key = data_point_id;
      item->value = data_point;
      item->expiration = 0;
      metadata->items[client_id]->key = item;
    } else {
      // If data point exists, update value and expiration timestamp
      item->value = data_point;
      item->expiration = time(NULL) + EXPIRATION_TIME;
    }
  }

  // Unlock mutex to release access to cache items array
  pthread_mutex_unlock(&metadata->mutex);
}

// Function to query cache for a subset of items based on filter criteria
void query_cache(int client_id, int* item_ids, void** items, int num_items) {
  // Get cache metadata pointer
  struct cache_metadata* metadata = *cache_metadata_ptr;

  // Lock mutex to synchronize access to cache items array
  pthread_mutex_lock(&metadata->mutex);

  // Iterate over item IDs and query cache items array
  for (int i = 0; i < num_items; i++) {
    int item_id = item_ids[i];

    // Check if item exists in cache items array
    struct cache_item* item = metadata->items[client_id]->key;

    // If item does not exist, set query result to NULL
    if (item == NULL) {
      items[i] = NULL;
    } else {
      // If item exists, copy value and expiration timestamp to output array
      items[i] = malloc(sizeof(void*));
      memcpy(items[i], &item->value, sizeof(void*));
      memcpy(&items[i]->expiration, &item->expiration, sizeof(time_t));
    }
  }

  // Unlock mutex to release access to cache items array
  pthread_mutex_unlock(&metadata->mutex);
}

// Function to refresh cache items from persistent storage system
void refresh_cache(int client_id) {
  // Get cache metadata pointer
  struct cache_metadata* metadata = *cache_metadata_ptr;

  // Lock mutex to synchronize access to cache items array
  pthread_mutex_lock(&metadata->mutex);

  // Iterate over cache items and update expiration timestamp
  for (int i = 0; i < metadata->num_clients; i++) {
    struct cache_item* item = metadata->items[i]->key;
    if (item != NULL) {
      item->expiration = time(NULL) + EXPIRATION_TIME;
    }
  }

  // Unlock mutex to release access to cache items array
  pthread_mutex_unlock(&metadata->mutex);
}
