// Function to find the root node of a disjoint-set structure
int findRoot(struct NetworkAndDataStructures *data, int set) {
    // If the parent is not the root, recursively call the function with the parent as the new set
    if (data->sets[set].parent != -1) {
        return findRoot(data, data->sets[set].parent);
    }

    // Otherwise, return the current set
    return set;
}

// Function to unite two disjoint-set structures into a single structure
void unionSet(struct NetworkAndDataStructures *data, int set1, int set2) {
    // Find the root nodes of both sets
    int root1 = findRoot(data, set1);
    int root2 = findRoot(data, set2);

    // If the two sets are already in the same tree, return early
    if (root1 == root2) {
        return;
    }

    // If the rank of one set is greater than the other, make the smaller set a child of the larger one
    if (data->sets[root1].rank > data->sets[root2].rank) {
        data->sets[root1].parent = root2;
    } else {
        data->sets[root2].parent = root1;
    }
}

// Function to check if two disjoint-set structures are in the same tree
int isSameTree(struct NetworkAndDataStructures *data, int set1, int set2) {
    // Find the root nodes of both sets
    int root1 = findRoot(data, set1);
    int root2 = findRoot(data, set2);

    // Return true if the two roots are the same, false otherwise
    return root1 == root2;
}

// Function to handle a new session and allocate resources for it
void *handleNewSession(struct NetworkAndDataStructures *data) {
    // Allocate memory for the dynamic list of TX_QUEUE_DATA_ITEM structures
    struct TX_QUEUE_DATA_ITEM *tx_queue = (struct TX_QUEUE_DATA_ITEM *)malloc(sizeof(struct TX_QUEUE_DATA_ITEM) * SESSION_DATA_SIZE);
    if (!tx_queue) {
        printf("Error: Failed to allocate memory for session data.\n");
        return NULL;
    }

    // Initialize the dynamic list of TX_QUEUE_DATA_ITEM structures
    for (int i = 0; i < SESSION_DATA_SIZE; i++) {
        tx_queue[i].session_id = -1;
        tx_queue[i].sequence_number = -1;
        tx_queue[i].payload_size = -1;
        tx_queue[i].timestamp = 0;
    }

    // Initialize the session ID counter and return a new session ID
    static int session_id_counter = 0;
    int session_id = session_id_counter++;
    return session_id;
}

// Function to handle a new packet for a session and update the TX queue
void handlePacketForSession(struct NetworkAndDataStructures *data, int session_id, struct PACKET *packet) {
    // Find the corresponding session in the data structures
    int set = -1;
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (data->records[i].key == session_id) {
            set = i;
            break;
        }
    }

    // If the session is not found, return early
    if (set == -1) {
        return;
    }

    // Add the packet to the TX queue
    for (int i = 0; i < SESSION_DATA_SIZE; i++) {
        if (data->tx_queue[i].session_id == -1) {
            data->tx_queue[i].session_id = session_id;
            data->tx_queue[i].sequence_number = packet.sequence_number;
            data->tx_queue[i].payload_size = packet.payload_size;
            data->tx_queue[i].timestamp = time(NULL);
        }
    }
}

// Function to send a packet for a session and update the TX queue
void sendPacketForSession(struct NetworkAndDataStructures *data, int session_id, struct PACKET *packet) {
    // Find the corresponding session in the data structures
    int set = -1;
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (data->records[i].key == session_id) {
            set = i;
            break;
        }
    }

    // If the session is not found, return early
    if (set == -1) {
        return;
    }

    // Add the packet to the TX queue
    for (int i = 0; i < SESSION_DATA_SIZE; i++) {
        if (data->tx_queue[i].session_id == session_id) {
            data->tx_queue[i].sequence_number++;
            data->tx_queue[i].timestamp = time(NULL);
        }
    }
}
