struct session {
    char *client_identifier;
    int connection_state;
    struct packet *last_packet;
};

struct packet {
    unsigned long sequence_number;
    enum type last_communication_protocol;
};

typedef struct session *session_array;

int create_sessions(size_t num_sessions, size_t initial_allocation_size) {
    session_array sessions = NULL;

    if (num_sessions == 0 || initial_allocation_size == 0) {
        return -EINVAL;
    }

    // Allocate memory for the session array
    sessions = malloc(sizeof(struct session) * num_sessions);
    if (sessions == NULL) {
        return -ENOMEM;
    }

    // Initialize each session structure with a NULL client identifier and a disconnected state
    for (size_t i = 0; i < num_sessions; i++) {
        sessions[i].client_identifier = NULL;
        sessions[i].connection_state = DISCONNECTED;
    }

    // Create the file to store the client identifiers and initialize the last packet for each session
    int fd = open("client_identifiers.txt", O_CREAT | O_EXCL, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        return -errno;
    }

    // Write the initial allocation size to the file
    char *initial_allocation_size_str = malloc(sizeof(char) * 10);
    snprintf(initial_allocation_size_str, 10, "%zu", initial_allocation_size);
    write(fd, initial_allocation_size_str, strlen(initial_allocation_size_str));
    close(fd);

    // Initialize the last packet for each session
    struct packet *last_packet = malloc(sizeof(struct packet) * num_sessions);
    if (last_packet == NULL) {
        return -ENOMEM;
    }

    for (size_t i = 0; i < num_sessions; i++) {
        last_packet[i].sequence_number = 0;
        last_packet[i].last_communication_protocol = NONE;
    }

    return 0;
}

int add_session(char *client_identifier, size_t num_sessions) {
    session_array sessions = NULL;

    // Read the current number of sessions from the file
    int fd = open("client_identifiers.txt", O_RDWR);
    if (fd == -1) {
        return -errno;
    }

    char *num_sessions_str = malloc(sizeof(char) * 10);
    read(fd, num_sessions_str, 10);
    size_t current_num_sessions = atoi(num_sessions_str);
    close(fd);

    // Allocate memory for the new session array and copy over the existing sessions
    sessions = malloc(sizeof(struct session) * (current_num_sessions + 1));
    if (sessions == NULL) {
        return -ENOMEM;
    }

    for (size_t i = 0; i < current_num_sessions; i++) {
        sessions[i].client_identifier = malloc(sizeof(char) * strlen(client_identifier));
        memcpy(sessions[i].client_identifier, client_identifier, strlen(client_identifier));
    }

    // Add the new session to the array and initialize its fields
    sessions[current_num_sessions].client_identifier = malloc(sizeof(char) * strlen(client_identifier));
    memcpy(sessions[current_num_sessions].client_identifier, client_identifier, strlen(client_identifier));
    sessions[current_num_sessions].connection_state = DISCONNECTED;

    // Update the number of sessions in the file and write the new session array to it
    size_t new_num_sessions = current_num_sessions + 1;
    num_sessions_str = malloc(sizeof(char) * 10);
    snprintf(num_sessions_str, 10, "%zu", new_num_sessions);
    lseek(fd, 0, SEEK_SET);
    write(fd, num_sessions_str, strlen(num_sessions_str));
    close(fd);

    // Free the old session array and update the pointer to the new one
    free(sessions - current_num_sessions);
    sessions = realloc(sessions, sizeof(struct session) * (new_num_sessions + 1));
    if (sessions == NULL) {
        return -ENOMEM;
    }

    return 0;
}

int remove_session(char *client_identifier, size_t num_sessions) {
    session_array sessions = NULL;

    // Read the current number of sessions from the file
    int fd = open("client_identifiers.txt", O_RDWR);
    if (fd == -1) {
        return -errno;
    }

    char *num_sessions_str = malloc(sizeof(char) * 10);
    read(fd, num_sessions_str, 10);
    size_t current_num_sessions = atoi(num_sessions_str);
    close(fd);

    // Allocate memory for the new session array and copy over the existing sessions
    sessions = malloc(sizeof(struct session) * (current_num_sessions - 1));
    if (sessions == NULL) {
        return -ENOMEM;
    }

    size_t i = 0, j = 0;
    while (i < current_num_sessions) {
        if (strcmp(sessions[i].client_identifier, client_identifier) != 0) {
            sessions[j++] = sessions[i];
        }
        i++;
    }

    // Update the number of sessions in the file and write the new session array to it
    size_t new_num_sessions = current_num_sessions - 1;
    num_sessions_str = malloc(sizeof(char) * 10);
    snprintf(num_sessions_str, 10, "%zu", new_num_sessions);
    lseek(fd, 0, SEEK_SET);
    write(fd, num_sessions_str, strlen(num_sessions_str));
    close(fd);

    // Free the old session array and update the pointer to the new one
    free(sessions - current_num_sessions);
    sessions = realloc(sessions, sizeof(struct session) * (new_num_sessions + 1));
    if (sessions == NULL) {
        return -ENOMEM;
    }

    return 0;
}

int update_session(char *client_identifier, enum type last_communication_protocol, size_t num_sessions) {
    session_array sessions = NULL;

    // Read the current number of sessions from the file
    int fd = open("client_identifiers.txt", O_RDWR);
    if (fd == -1) {
        return -errno;
    }

    char *num_sessions_str = malloc(sizeof(char) * 10);
    read(fd, num_sessions_str, 10);
    size_t current_num_sessions = atoi(num_sessions_str);
    close(fd);

    // Allocate memory for the new session array and copy over the existing sessions
    sessions = malloc(sizeof(struct session) * (current_num_sessions + 1));
    if (sessions == NULL) {
        return -ENOMEM;
    }

    size_t i = 0, j = 0;
    while (i < current_num_sessions) {
        if (strcmp(sessions[i].client_identifier, client_identifier) == 0) {
            sessions[j++] = sessions[i];
        } else {
            sessions[j++] = sessions[i];
            sessions[j - 1].last_packet.last_communication_protocol = last_communication_protocol;
        }
        i++;
    }

    // Update the number of sessions in the file and write the new session array to it
    size_t new_num_sessions = current_num_sessions + 1;
    num_sessions_str = malloc(sizeof(char) * 10);
    snprintf(num_sessions_str, 10, "%zu", new_num_sessions);
    lseek(fd, 0, SEEK_SET);
    write(fd, num_sessions_str, strlen(num_sessions_str));
    close(fd);

    // Free the old session array and update the pointer to the new one
    free(sessions - current_num_sessions);
    sessions = realloc(sessions, sizeof(struct session) * (new_num_sessions + 1));
    if (sessions == NULL) {
        return -ENOMEM;
    }

    return 0;
}

int allocate_memory(size_t num_sessions) {
    session_array sessions = malloc(sizeof(struct session) * num_sessions);
    if (sessions == NULL) {
        return -ENOMEM;
    }

    for (size_t i = 0; i < num_sessions; i++) {
        sessions[i].client_identifier = malloc(sizeof(char) * strlen(sessions[i].client_identifier));
        memcpy(sessions[i].client_identifier, sessions[i].client_identifier, strlen(sessions[i].client_identifier));
    }

    return 0;
}

int deallocate_memory() {
    free(sessions);
    return 0;
}
