// Struct for storing file metadata
typedef struct {
    long offset;
    int size;
    struct {
        time_t modification_time;
        char* type;
        unsigned int checksum;
    } metadata;
} FileMetadata;

// Global variables
static const size_t MAX_METADATA_SIZE = 1024 * 1024; // 1 MB
static const size_t BLOCK_SIZE = 1024 * 1024; // 1 MB
static const int NUM_THREADS = 4;
static const size_t MEMORY_BUDGET = 1024 * 1024 * 1024; // 1 GB
static FileMetadata* metadata_blocks;
static long next_free_offset;
static semaphore_t metadata_semaphore;

// Initialize the file caching system
void initialize_file_caching_system() {
    // Allocate memory for metadata blocks
    metadata_blocks = (FileMetadata*) malloc(MAX_METADATA_SIZE * sizeof(FileMetadata));
    if (!metadata_blocks) {
        printf("Failed to allocate memory for metadata blocks\n");
        exit(1);
    }
    // Initialize semaphore
    semaphore_init(&metadata_semaphore, 0);
}

// Add a new file to the cache
void add_file(const char* path) {
    // Acquire metadata semaphore
    semaphore_wait(&metadata_semaphore);

    // Find next free offset and allocate space for file data
    long offset = next_free_offset;
    size_t size = BLOCK_SIZE;
    if (size > MEMORY_BUDGET - next_free_offset) {
        size = MEMORY_BUDGET - next_free_offset;
    }
    next_free_offset += size;

    // Initialize metadata fields
    FileMetadata* metadata = &metadata_blocks[offset];
    metadata->offset = offset;
    metadata->size = size;
    metadata->metadata.modification_time = time(NULL);
    metadata->metadata.type = "regular file";

    // Release metadata semaphore
    semaphore_signal(&metadata_semaphore);
}

// Delete a file from the cache
void delete_file(const char* path) {
    // Acquire metadata semaphore
    semaphore_wait(&metadata_semaphore);

    // Find matching offset and free space
    long offset = 0;
    size_t size = BLOCK_SIZE;
    for (int i = 0; i < MAX_METADATA_SIZE; i++) {
        FileMetadata* metadata = &metadata_blocks[i];
        if (strcmp(path, metadata->metadata.type) == 0 && metadata->size > 0) {
            offset = metadata->offset;
            size = metadata->size;
            break;
        }
    }

    // Free space and mark as free
    next_free_offset += size;
    FileMetadata* metadata = &metadata_blocks[offset];
    metadata->offset = -1;
    metadata->size = 0;

    // Release metadata semaphore
    semaphore_signal(&metadata_semaphore);
}

// Retrieve a file from the cache
void* retrieve_file(const char* path) {
    // Acquire metadata semaphore
    semaphore_wait(&metadata_semaphore);

    // Find matching offset and size
    long offset = 0;
    size_t size = BLOCK_SIZE;
    for (int i = 0; i < MAX_METADATA_SIZE; i++) {
        FileMetadata* metadata = &metadata_blocks[i];
        if (strcmp(path, metadata->metadata.type) == 0 && metadata->size > 0) {
            offset = metadata->offset;
            size = metadata->size;
            break;
        }
    }

    // Release metadata semaphore
    semaphore_signal(&metadata_semaphore);

    // Check for valid offset and size
    if (offset < 0 || size == 0) {
        return NULL;
    }

    // Read file data from memory
    void* data = malloc(size);
    memcpy(data, &metadata_blocks[offset], size);

    return data;
}

// Release all allocated resources
void release_resources() {
    // Free metadata blocks
    free(metadata_blocks);

    // Close semaphore
    semaphore_close(&metadata_semaphore);
}
