// Define the memory pool for dynamic allocation
typedef struct {
    size_t capacity; // capacity of the memory pool in bytes
    size_t used; // amount of memory currently used by the pool
    void* data; // pointer to the start of the memory pool
} MemoryPool;

// Define the function that manages memory for multiple dynamic data structures under constrained resources
void manageMemory(size_t n, size_t M) {
    // Initialize the memory pool with a capacity of M megabytes
    MemoryPool* memPool = (MemoryPool*)malloc(sizeof(MemoryPool));
    memPool->capacity = M * 1024 * 1024;
    memPool->used = 0;
    memPool->data = malloc(memPool->capacity);
    assert(memPool->data != NULL);

    // Allocate memory for the offset and key arrays
    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(n * sizeof(int));
    assert(offsets != NULL && keys != NULL);

    // Populate the offset and key arrays with random values
    srand(time(NULL)); // initialize the random number generator with the current time
    for (size_t i = 0; i < n; i++) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % 1000;
    }

    // Allocate memory for the record array
    Record* records = (Record*)malloc(n * sizeof(Record));
    assert(records != NULL);

    // Populate the record array with random values
    for (size_t i = 0; i < n; i++) {
        records[i].value = rand() % 1000;
    }

    // Free all allocated memory when no longer needed
    free(records);
    free(keys);
    free(offsets);
    free(memPool->data);
    free(memPool);
}

// Test the function with a variety of inputs
int main() {
    manageMemory(0, 10); // test with n = 0 and M = 10 megabytes
    manageMemory(5, 20); // test with n = 5 and M = 20 megabytes
    manageMemory(10, 30); // test with n = 10 and M = 30 megabytes
    return 0;
}
```
This code defines a function `manageMemory` that takes two parameters: `n`, the number of records to be managed, and `M`, the maximum amount of memory to be used by the function. The function uses a memory pool to dynamically allocate memory for the offset and key arrays, and it populates these arrays with random values. It also allocates memory for an array of record structures and populates them with random values. Finally, the function frees all allocated memory when no longer needed.

