    // The least recently used entry
    long lru;
    // The most recently used entry
    long mru;
    // The number of entries in the cache
    size_t num_entries;
};

// Function to initialize the hash table and cache
void init_table(struct hash_table* table) {
    // Initialize the arrays for offsets, keys, and records
    table->offsets = (long*)malloc(sizeof(long) * 10);
    table->keys = (int*)malloc(sizeof(int) * 10);
    table->records = (struct record*)malloc(sizeof(struct record) * 10);

    // Initialize the number of elements in the table
    table->num_elements = 0;
}

// Function to dynamically allocate memory for and initialize an array of long offset values
long* alloc_offsets(size_t size) {
    long* offsets = (long*)malloc(sizeof(long) * size);

    // Initialize the array with default values
    for (int i = 0; i < size; i++) {
        offsets[i] = -1;
    }

    return offsets;
}

// Function to dynamically allocate memory for and initialize an array of integer keys
int* alloc_keys(size_t size) {
    int* keys = (int*)malloc(sizeof(int) * size);

    // Initialize the array with default values
    for (int i = 0; i < size; i++) {
        keys[i] = -1;
    }

    return keys;
}

// Function to dynamically allocate memory for and initialize an array of record structures
struct record* alloc_records(size_t size) {
    struct record* records = (struct record*)malloc(sizeof(struct record) * size);

    // Initialize the array with default values
    for (int i = 0; i < size; i++) {
        records[i].value = -1;
    }

    return records;
}

// Function to insert a new element into the hash table
void insert_element(struct hash_table* table, long offset, int key) {
    // Lock the table before updating it
    pthread_mutex_lock(&table->mutex);

    // Check if the cache is full
    if (table->cache.num_entries == CACHE_SIZE) {
        // Evict the least recently used entry from the cache
        long evicted = table->cache.lru;

        // Remove the element from the cache
        table->cache.lru = table->cache.mru;

        // Update the number of entries in the cache
        table->cache.num_entries--;
    }

    // Add the new element to the cache
    table->cache.mru = offset;
    table->cache.num_entries++;

    // Insert the element into the hash table
    table->offsets[table->num_elements] = offset;
    table->keys[table->num_elements] = key;
    table->records[table->num_elements].value = key;

    // Update the number of elements in the table
    table->num_elements++;

    // Unlock the table after updating it
    pthread_mutex_unlock(&table->mutex);
}

// Function to retrieve an element from the hash table
struct record* get_element(struct hash_table* table, long offset) {
    struct record* record = NULL;

    // Lock the table before accessing it
    pthread_mutex_lock(&table->mutex);

    // Check if the element exists in the cache
    if (table->cache.num_entries > 0 && offset == table->cache.mru) {
        record = &(table->records[table->cache.mru]);
    } else {
        // Search for the element in the hash table
        long index = offset % table->num_elements;
        if (index < 0) {
            index += table->num_elements;
        }

        while (table->offsets[index] != offset && table->keys[index] != -1) {
            index++;

            // If the end of the array is reached, start from the beginning again
            if (index == table->num_elements) {
                index = 0;
            }
        }

        // Check if the element was found
        if (table->keys[index] != -1) {
            record = &(table->records[index]);

            // Update the cache
            table->cache.lru = index;
            table->cache.mru = index;
            table->cache.num_entries++;
        }
    }

    // Unlock the table after accessing it
    pthread_mutex_unlock(&table->mutex);

    return record;
}
