// Define the key type for the event category
typedef int EventKey;

// Define the structure for a single event in the log system
struct Event {
    // Timestamp of the event (in milliseconds)
    long long timestamp;

    // Category of the event (encoded as a string)
    char *category;

    // Numerical identifier of the event
    int id;

    // Payload of the event (a variable-length binary data)
    void *payload;
};

// Define the structure for a single entry in the hash table index
struct IndexEntry {
    // Key of the event (used as the hash key)
    EventKey key;

    // Pointer to the event data
    struct Event *event;

    // Next pointer for chaining entries with the same key
    struct IndexEntry *next;
};

// Define a linked list structure for the cache
struct Cache {
    // Head and tail pointers for the linked list
    struct IndexEntry *head, *tail;

    // Size of the cache (in number of entries)
    int size;
};

// Global variables for the hash table index and the cache
static struct IndexEntry **index = NULL;
static struct Cache cache;

// Lock to synchronize access to the index and cache
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the hash table index
void init_index(int size) {
    // Allocate memory for the hash table index
    index = malloc(sizeof(struct IndexEntry *) * size);

    // Initialize each entry in the hash table index to NULL
    int i;
    for (i = 0; i < size; i++) {
        index[i] = NULL;
    }
}

// Function to create a new event in the log system
struct Event *create_event(long long timestamp, char *category, int id, void *payload) {
    // Allocate memory for the event data
    struct Event *event = malloc(sizeof(struct Event));
    if (!event) {
        fprintf(stderr, "Error: failed to allocate memory for new event\n");
        exit(1);
    }

    // Initialize the fields of the event data
    event->timestamp = timestamp;
    event->category = category;
    event->id = id;
    event->payload = payload;

    return event;
}

// Function to add a new event to the log system
void add_event(struct Event *event) {
    // Acquire the lock to synchronize access to the index and cache
    pthread_mutex_lock(&lock);

    // Compute the hash key for the event category
    EventKey key = hash_key(event->category);

    // Search for an existing entry with the same hash key in the index
    struct IndexEntry *entry = index[key];
    while (entry != NULL && strcmp(event->category, entry->event->category) != 0) {
        entry = entry->next;
    }

    // If no existing entry was found, create a new one and add it to the index
    if (entry == NULL) {
        entry = malloc(sizeof(struct IndexEntry));
        entry->key = key;
        entry->event = event;
        entry->next = NULL;
        index[key] = entry;
    }

    // Add the event to the cache if it is not already there
    struct CacheEntry *cache_entry = find_cache_entry(event);
    if (cache_entry == NULL) {
        add_to_cache(event);
    }

    // Release the lock to synchronize access to the index and cache
    pthread_mutex_unlock(&lock);
}

// Function to remove an event from the log system
void remove_event(struct Event *event) {
    // Acquire the lock to synchronize access to the index and cache
    pthread_mutex_lock(&lock);

    // Compute the hash key for the event category
    EventKey key = hash_key(event->category);

    // Search for an existing entry with the same hash key in the index
    struct IndexEntry *entry = index[key];
    while (entry != NULL && strcmp(event->category, entry->event->category) != 0) {
        entry = entry->next;
    }

    // If an existing entry was found, remove it from the index and cache
    if (entry != NULL) {
        remove_from_index(key);
        struct CacheEntry *cache_entry = find_cache_entry(event);
        if (cache_entry != NULL) {
            remove_from_cache(cache_entry);
        }
    }

    // Release the lock to synchronize access to the index and cache
    pthread_mutex_unlock(&lock);
}

// Function to update an event in the log system
void update_event(struct Event *old_event, struct Event *new_event) {
    // Acquire the lock to synchronize access to the index and cache
    pthread_mutex_lock(&lock);

    // Compute the hash key for the old event category
    EventKey old_key = hash_key(old_event->category);

    // Search for an existing entry with the same hash key in the index
    struct IndexEntry *entry = index[old_key];
    while (entry != NULL && strcmp(old_event->category, entry->event->category) != 0) {
        entry = entry->next;
    }

    // If an existing entry was found, update the event and cache
    if (entry != NULL) {
        struct Event *updated_event = malloc(sizeof(struct Event));
        updated_event->timestamp = new_event->timestamp;
        updated_event->category = new_event->category;
        updated_event->id = new_event->id;
        updated_event->payload = new_event->payload;

        // Update the event data in the index entry
        entry->event = updated_event;

        // Update the cache if necessary
        struct CacheEntry *cache_entry = find_cache_entry(old_event);
        if (cache_entry != NULL) {
            remove_from_cache(cache_entry);
            add_to_cache(updated_event);
        }
    }

    // Release the lock to synchronize access to the index and cache
    pthread_mutex_unlock(&lock);
}

// Function to retrieve an event from the log system
struct Event *retrieve_event(EventKey key) {
    // Acquire the lock to synchronize access to the index and cache
    pthread_mutex_lock(&lock);

    // Search for an existing entry with the same hash key in the index
    struct IndexEntry *entry = index[key];
    while (entry != NULL && entry->event->id != key) {
        entry = entry->next;
    }

    // If an existing entry was found, retrieve and return the event data
    if (entry != NULL) {
        struct Event *event = malloc(sizeof(struct Event));
        event->timestamp = entry->event->timestamp;
        event->category = entry->event->category;
        event->id = entry->event->id;
        event->payload = entry->event->payload;

        // Add the retrieved event to the cache if it is not already there
        struct CacheEntry *cache_entry = find_cache_entry(event);
        if (cache_entry == NULL) {
            add_to_cache(event);
        }
    }

    // Release the lock to synchronize access to the index and cache
    pthread_mutex_unlock(&lock);

    return event;
}

// Function to retrieve a batch of events from the log system
struct Event **retrieve_events(EventKey *keys, int num_keys) {
    // Acquire the lock to synchronize access to the index and cache
    pthread_mutex_lock(&lock);

    // Allocate memory for the retrieved events
    struct Event **events = malloc(sizeof(struct Event *) * num_keys);

    // Iterate over the keys and retrieve each corresponding event from the log system
    int i;
    for (i = 0; i < num_keys; i++) {
        struct Event *event = retrieve_event(keys[i]);
        if (event != NULL) {
            events[i] = malloc(sizeof(struct Event));
            events[i]->timestamp = event->timestamp;
            events[i]->category = event->category;
            events[i]->id = event->id;
            events[i]->payload = event->payload;
        } else {
            events[i] = NULL;
        }
    }

    // Release the lock to synchronize access to the index and cache
    pthread_mutex_unlock(&lock);

    return events;
}

// Function to release memory for an event in the log system
void free_event(struct Event *event) {
    // Free the payload data associated with the event
    free(event->payload);

    // Release the lock to synchronize access to the index and cache
    pthread_mutex_lock(&lock);

    // Search for an existing entry with the same hash key in the index
    EventKey key = hash_key(event->category);
