#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

struct record {
    int value;
    time_t timestamp;
};

struct label {
    char *label;
    struct record *record;
};

struct hash_table {
    size_t capacity;
    struct label **labels;
    struct record **records;
};

struct cache {
    size_t capacity;
    size_t size;
    struct hash_table *hash_table;
    struct label **labels;
    struct record **records;
};

void init_cache(struct cache *cache, size_t capacity) {
    // Initialize the cache with a fixed capacity and empty hash table
    cache->capacity = capacity;
    cache->size = 0;
    cache->hash_table = (struct hash_table *) malloc(sizeof(struct hash_table));
    cache->hash_table->capacity = capacity;
    cache->hash_table->labels = (struct label **) malloc(capacity * sizeof(struct label *));
    cache->hash_table->records = (struct record **) malloc(capacity * sizeof(struct record *));
}

void init_label(struct label *label, char *key) {
    // Initialize a new label with the given key and empty record
    label->label = key;
    label->record = NULL;
}

void init_record(struct record *record, int value) {
    // Initialize a new record with the given value and current timestamp
    record->value = value;
    record->timestamp = time(NULL);
}

struct hash_table *create_hash_table(size_t capacity) {
    // Create a new hash table with the given capacity
    struct hash_table *hash_table = (struct hash_table *) malloc(sizeof(struct hash_table));
    hash_table->capacity = capacity;
    hash_table->labels = (struct label **) malloc(capacity * sizeof(struct label *));
    hash_table->records = (struct record **) malloc(capacity * sizeof(struct record *));
    return hash_table;
}

void destroy_hash_table(struct hash_table *hash_table) {
    // Free the memory allocated for the hash table and its labels and records
    free(hash_table->labels);
    free(hash_table->records);
    free(hash_table);
}

void init_hash_table(struct hash_table *hash_table) {
    // Initialize all labels in the hash table to NULL
    for (size_t i = 0; i < hash_table->capacity; ++i) {
        hash_table->labels[i] = NULL;
    }
}

void insert(struct cache *cache, char *key, int value) {
    // Insert a new label and record into the cache
    struct label *label = (struct label *) malloc(sizeof(struct label));
    init_label(label, key);
    struct record *record = (struct record *) malloc(sizeof(struct record));
    init_record(record, value);
    size_t index = hash_function(key) % cache->hash_table->capacity;
    while (cache->hash_table->labels[index] != NULL && strcmp(key, cache->hash_table->labels[index]->label) != 0) {
        // If the label already exists in the hash table, increment the index and try again
        index = (index + 1) % cache->hash_table->capacity;
    }
    if (cache->hash_table->labels[index] == NULL) {
        // If a new label is created, add it to the hash table and increase the size of the cache
        cache->hash_table->labels[index] = label;
        cache->hash_table->records[index] = record;
        cache->size++;
    } else {
        // If the label already exists, update its record
        cache->hash_table->records[index]->value = value;
        cache->hash_table->records[index]->timestamp = time(NULL);
    }
}

struct record *lookup(struct cache *cache, char *key) {
    // Look up a record by key in the cache
    size_t index = hash_function(key) % cache->hash_table->capacity;
    while (index < cache->hash_table->capacity && strcmp(key, cache->hash_table->labels[index]->label) != 0) {
        // If the label does not exist in the hash table, increment the index and try again
        index = (index + 1) % cache->hash_table->capacity;
    }
    if (cache->hash_table->labels[index] == NULL) {
        return NULL;
    } else {
        // If a record is found, update its timestamp and return it
        struct record *record = cache->hash_table->records[index];
        record->timestamp = time(NULL);
        return record;
    }
}

void evict(struct cache *cache) {
    // Evict the least recently used entry in the cache
    size_t min_timestamp = 0;
    size_t min_index = 0;
    for (size_t i = 0; i < cache->hash_table->capacity; ++i) {
        if (cache->hash_table->records[i] != NULL && cache->hash_table->records[i]->timestamp < min_timestamp) {
            min_timestamp = cache->hash_table->records[i]->timestamp;
            min_index = i;
        }
    }
    free(cache->hash_table->labels[min_index]);
    free(cache->hash_table->records[min_index]);
    cache->hash_table->labels[min_index] = NULL;
    cache->hash_table->records[min_index] = NULL;
}

void destroy_cache(struct cache *cache) {
    // Free the memory allocated for the cache and its hash table
    free(cache->hash_table);
    free(cache);
}

size_t hash_function(char *key) {
    // A simple hash function that takes a key string and returns an index in the range of [0, capacity)
    size_t hash = 5381;
    int c;
    while ((c = *key++) != '\0') {
        hash = ((hash << 5) + hash) + c;
    }
    return hash % cache->capacity;
}"]

