// function to filter and sort the file_info structures based on their sizes
void filter_and_sort(int num_files, int order) {
    // allocate memory for a temporary array of file_info structures
    file_info *temp = malloc(sizeof(file_info) * num_files);
    if (temp == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for temp array\n");
        exit(1);
    }

    // copy the contents of the original array into the temporary array
    memcpy(temp, file_infos, sizeof(file_info) * num_files);

    // sort the temporary array based on the specified order and comparison method
    if (order == 0) { // ascending
        qsort(temp, num_files, sizeof(file_info), compare_double_size);
    } else if (order == 1) { // descending
        qsort(temp, num_files, sizeof(file_info), compare_double_size_desc);
    } else if (order == 2) { // by path length
        qsort(temp, num_files, sizeof(file_info), compare_path_length);
    }

    // copy the contents of the sorted temporary array back into the original array
    memcpy(file_infos, temp, sizeof(file_info) * num_files);

    free(temp);
}

// function to serialize the filtered and sorted file_info structures into a directory of files
void serialize(int num_files, char *directory) {
    // create a new directory if it doesn't already exist
    struct stat st = {0};
    if (stat(directory, &st) == -1) {
        mkdir(directory, 0700);
    }

    // allocate memory for the array of file names
