        if (file_names[i] == NULL) {
            fprintf(stderr, "Error: failed to allocate memory for file name\n");
            exit(1);
        }
        snprintf(file_names[i], PATH_MAX, "%03d", i);
    }

    // create a new file for each entry in the sorted array of file_info structures
    for (int i = 0; i < num_files; i++) {
        char *filename = malloc(sizeof(char) * PATH_MAX);
        if (filename == NULL) {
            fprintf(stderr, "Error: failed to allocate memory for filename\n");
            exit(1);
        }
        snprintf(filename, PATH_MAX, "%s/%03d.txt", directory, i);
        FILE *file = fopen(filename, "wb");
