// Structure to represent a node in the graph
struct Node {
    // The string value stored in this node
    char *value;

    // A pointer to another node in the graph
    struct Node *next;
};

// Function to parse a configuration file and populate an array of `node` structures
void parse_configuration(FILE *fp, size_t num_nodes, struct Node **nodes) {
    // Read the configuration file line by line
    char line[256];
    while (fgets(line, 256, fp) != NULL) {
        // Skip blank lines and comments
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Extract the key-value pair from the line
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        // Check if the key is a valid string and the value is a valid integer
        if (strlen(key) > 0 && strlen(value) > 0) {
            struct Node *node = (struct Node *)malloc(sizeof(struct Node));

            // Initialize the node with the extracted values
            node->value = strdup(value);
            node->next = NULL;

            // Add the node to the array of nodes
            if (nodes[0] == NULL) {
                nodes[0] = node;
            } else {
                struct Node *last_node = nodes[0];
                while (last_node->next != NULL) {
                    last_node = last_node->next;
                }
                last_node->next = node;
            }
        }
    }
}
