struct Node {
    // The string value stored in this node
    char *value;

    // A pointer to another node in the graph
    struct Node *next;
};

// Function to traverse the graph and perform a breadth-first search from a given start node to a target node
bool bfs(struct Node *start, struct Node *target) {
    // Initialize a queue to store nodes to be traversed
    struct Node *queue[100];

    // Add the start node to the queue
    queue[0] = start;

    // Traverse the graph using a breadth-first search
    while (queue[0] != NULL) {
        // Remove the first node from the queue and process it
        struct Node *node = queue[0];

        // Check if the node is the target node
        if (node == target) {
            return true;
        }

        // Add the node's neighbors to the queue
        while (node->next != NULL) {
            queue[0] = node->next;
            node = node->next;
        }
    }

    // Return false if no path was found
    return false;
}
