// Function to serialize the graph data structure into a binary format
void serialize(struct Node *graph) {
    // Create a file for output
    FILE *fp = fopen("graph.bin", "wb");

    // Write the graph structure to the file
    struct Node *node = graph;
    while (node != NULL) {
        // Write the node's value and pointer to another node
        fwrite(node->value, sizeof(char), strlen(node->value), fp);
        fwrite(&node->next, sizeof(struct Node *), 1, fp);

        // Move to the next node in the graph
        node = node->next;
    }

    // Close the file
    fclose(fp);
}
