void initRecords(int num_records) {
    // Check if the user-provided size does not exceed 1% of available system memory
    long max_memory = getMaxMemory();
    if (num_records > max_memory / 100) {
        printf("Error: The specified number of records exceeds 1% of available system memory\n");
        exit(1);
    }

    // Allocate memory for the array of Records
