    if (!records) {
        printf("Error: Failed to allocate memory for the array of Records\n");
        exit(1);
    }

    // Initialize the array of Records with default values
    for (int i = 0; i < num_records; i++) {
        records[i].key = 0;
    }
}

// Function to allocate memory for and initialize an array of longs
void initLongArray(int size) {
    // Check if the user-provided size does not exceed 1% of available system memory
    long max_memory = getMaxMemory();
    if (size > max_memory / 100) {
        printf("Error: The specified size exceeds 1% of available system memory\n");
        exit(1);
    }

    // Allocate memory for the array of longs
    long* arr = (long*)malloc(size * sizeof(long));
    if (!arr) {
        printf("Error: Failed to allocate memory for the array of longs\n");
        exit(1);
    }

