    for (int i = 0; i < size; i++) {
        arr[i] = 0;
    }
}

// Function to set a random value within a specified range for each record's key field
void setRandomValues(int min, int max) {
    // Check if the specified range is valid
    if (min > max) {
        printf("Error: The specified range is invalid\n");
        exit(1);
    }

    // Seed the random number generator with a unique value based on combined system resources
    srand(getCombinedSystemResources());

    // Set the random value for each record's key field within the specified range
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % (max - min + 1) + min;
    }
}

// Function to sort the records based on their key values using a stable sorting algorithm
void sortRecords(int order) {
    // Check if the specified order is valid
    if (order != ASCENDING && order != DESCENDING) {
        printf("Error: The specified order is invalid\n");
        exit(1);
    }

    // Sort the records based on their key values using a stable sorting algorithm
    for (int i = 0; i < num_records; i++) {
        Record temp = records[i];
        int j = i - 1;
        while (j >= 0 && order == ASCENDING ? (temp.key > records[j].key) : (temp.key < records[j].key)) {
            records[j + 1] = records[j];
            j--;
        }
        records[j + 1] = temp;
    }
}

// Function to serialize the sorted records into a file
void serializeRecords(char* filename) {
    // Check if the specified filename is valid
    if (filename == NULL || strlen(filename) < 1) {
        printf("Error: The specified filename is invalid\n");
        exit(1);
    }

    // Open the file for writing and serialize the sorted records
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        printf("Error: Failed to open the file for writing\n");
        exit(1);
    }

    // Write the number of records to the file
    fwrite(&num_records, sizeof(int), 1, fp);

    // Write each record's key value to the file
    for (int i = 0; i < num_records; i++) {
        fwrite(&records[i].key, sizeof(int), 1, fp);
    }

    // Close the file and handle potential I/O errors
    if (fclose(fp) == EOF) {
        printf("Error: Failed to close the file\n");
        exit(1);
    }
}

// Function to deserialize the sorted records from a file
void deserializeRecords(char* filename) {
    // Check if the specified filename is valid
    if (filename == NULL || strlen(filename) < 1) {
        printf("Error: The specified filename is invalid\n");
        exit(1);
    }

    // Open the file for reading and deserialize the sorted records
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error: Failed to open the file for reading\n");
        exit(1);
    }

    // Read the number of records from the file
    int num_records;
    fread(&num_records, sizeof(int), 1, fp);

    // Allocate memory for the array of Records
    records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for the array of Records\n");
        exit(1);
    }

    // Read each record's key value from the file
    for (int i = 0; i < num_records; i++) {
        fread(&records[i].key, sizeof(int), 1, fp);
    }

    // Close the file and handle potential I/O errors
    if (fclose(fp) == EOF) {
        printf("Error: Failed to close the file\n");
        exit(1);
    }
}
