    return 0;
}

void allocate_memory(int *offset, int *key, int n) {
    // Robust error-checking mechanism to prevent buffer overflows
    if (n > 0 && n <= SIZE_MAX / sizeof(int)) {
        offset = malloc(sizeof(int) * n);
        key = malloc(sizeof(int) * n);
        record = malloc(sizeof(struct record) * n);
    } else {
        printf("Error: Invalid size input.\n");
        exit(1);
    }
}

void initialize_arrays(int *offset, int *key, struct record *record, int n) {
    // Initialize arrays with user-provided values
    for (int i = 0; i < n; i++) {
        offset[i] = i * 100;
        key[i] = i * 50;
        record[i].value = i * 25;
    }
}

void set_random_values(struct record *record, int n) {
    // Set random values to the records
    for (int i = 0; i < n; i++) {
        int value = rand() % 100 + 1;
        record[i].value = value;
    }
}

void sort_records(struct record *record, int n, int order) {
    // Sort the records based on their values
    if (order == 1) {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (record[i].value > record[j].value) {
                    struct record temp = record[i];
                    record[i] = record[j];
                    record[j] = temp;
                }
            }
        }
    } else {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (record[i].value < record[j].value) {
                    struct record temp = record[i];
                    record[i] = record[j];
                    record[j] = temp;
                }
            }
        }
    }
}

void serialize_records(struct record *record, int n, char *filename) {
    // Serialize the sorted records to a file
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        printf("Error: Unable to open output file.\n");
        exit(1);
    }
    for (int i = 0; i < n; i++) {
        int value = record[i].value;
        fwrite(&value, sizeof(int), 1, fp);
    }
    fclose(fp);
