// Function to manage a dynamic collection of records for real-time monitoring system
void record_manager(record** head, size_t* num_records) {
  // Dynamically allocate memory for new records
  record* new_record = malloc(sizeof(record));
  if (new_record == NULL) {
    printf("Memory allocation failed\n");
    return;
  }

  // Add new record to the end of the linked list
  record** cursor = head;
  while (*cursor != NULL) {
    cursor = &(*cursor)->next;
  }
  *cursor = new_record;
  ++*num_records;

  // Free all allocated memory when done
  record* current = *head;
  while (current != NULL) {
    record* temp = current;
    current = current->next;
    free(temp);
  }
}

// Function to iterate over the collection and print each record's details
void print_records(record** head, size_t num_records) {
  // Iterate over the linked list and print each record's details
  record* current = *head;
  while (current != NULL) {
    printf("Record %lu: time=%llu, status=%d, tags={", current->id, current->time, current->status);
    for (size_t i = 0; i < current->num_tags; ++i) {
      printf("%s ", current->tags[i]);
    }
    printf("}\n");
    current = current->next;
  }
}

// Function to free all allocated memory when the function is done
void cleanup(record** head, size_t* num_records) {
  record* current = *head;
  while (current != NULL) {
    record* temp = current;
    current = current->next;
    free(temp);
  }
  *num_records = 0;
}
```
