    thread_pool->threads = (pthread_t*)malloc(thread_pool->size * sizeof(pthread_t));
    if (!thread_pool->threads) {
        free(thread_pool);
        return -1;
    }

    // Create a lock for protecting the queue access
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    pthread_mutex_init(&queue_lock, &attr);
    pthread_mutexattr_destroy(&attr);

    // Start threads for handling sessions
    for (int i = 0; i < thread_pool->size; ++i) {
