void process_sensor_data(SENSOR_DATA *data) {
    // Validate temperature and humidity values
    if (data->temperature < -50 || data->temperature > 80 ||
            data->humidity < 0 || data->humidity > 100) {
        printf("Invalid sensor data received: %f, %f\n", data->temperature, data->humidity);
    } else {
