        void *ptr = allocate_memory(sizeof(SENSOR_DATA));
        memcpy(ptr, data, sizeof(SENSOR_DATA));
        sensor_data[rnti->rnti] = ptr;
    }
}

// Function to manage incoming client connections and process sensor data
void *manage_client_connections() {
    int socket_fd; // file descriptor for the server socket
    struct sockaddr_in server_address; // address of the server socket
    pthread_t thread; // thread ID for managing client connections

    // Initialize the server socket and bind it to a port number
    if ((socket_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(8080); // port number
    if (bind(socket_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming client connections and spawn a new thread for each one
    if (listen(socket_fd, 3) < 0) {
        perror("Listen failed");
        exit(EXIT_FAILURE);
    }
    while (1) {
        struct sockaddr_in client_address; // address of the client socket
        int client_len = sizeof(client_address);
        if ((socket_fd = accept(socket_fd, (struct sockaddr *)&client_address, (socklen_t*)&client_len)) < 0) {
            perror("Accept failed");
            exit(EXIT_FAILURE);
        }

        // Create a new thread for managing the client connection
        pthread_create(&thread, NULL, manage_client_connection, (void*)&socket_fd);
    }
}

