#define MAX_TAGS 10

typedef struct monitoring_record {
    time_t timestamp;
    int status;
    char* tags[MAX_TAGS];
} monitoring_record;

// Doubly linked list for storing monitoring records
struct node {
    monitoring_record record;
    struct node* next;
    struct node* prev;
};

struct monitoring_records {
    int size; // number of records in the list
    struct node* head; // pointer to first node in the list
    struct node* tail; // pointer to last node in the list
} records = {0, NULL, NULL};

// Function for inserting a new monitoring record into the list
void insert_record(monitoring_record* record) {
    struct node* new_node = malloc(sizeof(struct node));
    new_node->record = *record;
    new_node->next = NULL;
    new_node->prev = records.tail;
    if (records.tail != NULL) {
        records.tail->next = new_node;
    } else {
        records.head = new_node;
    }
    records.tail = new_node;
    records.size++;
}

// Function for evicting a monitoring record from the list
void evict_record(monitoring_record* record) {
    struct node* to_remove = NULL;
    struct node* current = records.head;
    while (current != NULL) {
        if (current->record.timestamp == record->timestamp) {
            to_remove = current;
            break;
        }
        current = current->next;
    }
    // If the record is found, remove it from the list and free its memory
    if (to_remove != NULL) {
        records.size--;
        if (records.head == to_remove) {
            records.head = records.head->next;
        }
        if (records.tail == to_remove) {
            records.tail = records.tail->prev;
        }
        free(to_remove);
    }
}

// Function for iterating over the monitoring records in the list
void iterate_records(void (*callback)(monitoring_record* record)) {
    struct node* current = records.head;
    while (current != NULL) {
        callback(&current->record);
        current = current->next;
    }
}

// Function for handling the insertion of new monitoring data into the list
void handle_new_data(monitoring_record* record) {
    // If the list is empty, insert the new record directly
    if (records.size == 0) {
        insert_record(record);
    } else {
        // Check if the new record is already in the list
        struct node* current = records.head;
        while (current != NULL) {
            if (current->record.timestamp == record->timestamp) {
                // If the record is found, update its status and tags
                current->record.status = record->status;
                for (int i = 0; i < MAX_TAGS && record->tags[i] != NULL; i++) {
                    strcpy(current->record.tags[i], record->tags[i]);
                }
                return;
            }
            current = current->next;
        }
        // If the new record is not found, insert it at the end of the list
        insert_record(record);
    }
}

// Function for handling the eviction of old monitoring data from the list
void handle_old_data(time_t timestamp) {
    struct node* to_remove = NULL;
    // Find the first record with a timestamp before the given timestamp
    struct node* current = records.head;
    while (current != NULL && current->record.timestamp > timestamp) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    // Remove all records with a timestamp before the given timestamp
    while (current != NULL) {
        to_remove = current;
        current = current->next;
        evict_record(&to_remove->record);
    }
}

