Here's a sample code for a modular network interface module capable of handling up to 10,000 concurrent sessions, each managing a list of `TX_QUEUE_DATA_ITEM` structures:
```c++
#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <thread>

// Structure to hold data for each transaction queue
struct TX_QUEUE_DATA_ITEM {
    std::string transaction_id;
    uint64_t session_id;
    std::vector<uint8_t> packet_data;
};

// Structure to hold data for each session
struct SESSION_DATA {
    uint64_t session_id;
    std::vector<TX_QUEUE_DATA_ITEM> transaction_queue;
};

// Map to store all active sessions and their corresponding queue data
std::unordered_map<uint64_t, SESSION_DATA> session_data_map;

// Mutex for thread-safe access to the session data map
std::mutex session_data_map_mutex;

// Function to handle incoming network packets and route them to the appropriate session queue
void handle_incoming_packet(const std::vector<uint8_t>& packet_data) {
    // Lock the mutex for thread-safe access to the session data map
    std::lock_guard<std::mutex> lock(session_data_map_mutex);

    // Extract the session ID from the packet data
    uint64_t session_id = 0;
    memcpy(&session_id, &packet_data[0], sizeof(uint64_t));

    // Check if the session is already active
    auto it = session_data_map.find(session_id);
    if (it == session_data_map.end()) {
        // Create a new session data structure for this session ID
        SESSION_DATA new_session;
        new_session.session_id = session_id;
        it = session_data_map.insert(std::make_pair(session_id, new_session)).first;
    }

    // Add the incoming packet to the transaction queue for this session
    TX_QUEUE_DATA_ITEM new_transaction;
    memcpy(&new_transaction.transaction_id, &packet_data[8], sizeof(std::string));
    new_transaction.session_id = session_id;
    it->second.transaction_queue.push_back(new_transaction);
}

// Function to handle outgoing network packets and route them to the appropriate session queue
void handle_outgoing_packet(const std::vector<uint8_t>& packet_data) {
    // Lock the mutex for thread-safe access to the session data map
    std::lock_guard<std::mutex> lock(session_data_map_mutex);

    // Extract the session ID from the packet data
    uint64_t session_id = 0;
    memcpy(&session_id, &packet_data[0], sizeof(uint64_t));

    // Check if the session is already active
    auto it = session_data_map.find(session_id);
    if (it == session_data_map.end()) {
        return;
    }

    // Add the outgoing packet to the transaction queue for this session
    TX_QUEUE_DATA_ITEM new_transaction;
    memcpy(&new_transaction.transaction_id, &packet_data[8], sizeof(std::string));
    new_transaction.session_id = session_id;
    it->second.transaction_queue.push_back(new_transaction);
}

// Function to handle incoming sessions and initialize them in the session data map
void handle_incoming_session(uint64_t session_id) {
    // Lock the mutex for thread-safe access to the session data map
    std::lock_guard<std::mutex> lock(session_data_map_mutex);

    // Check if the incoming session is already active
    auto it = session_data_map.find(session_id);
    if (it != session_data_map.end()) {
        return;
    }

    // Create a new session data structure for this session ID
    SESSION_DATA new_session;
    new_session.session_id = session_id;
    session_data_map[session_id] = new_session;
}

// Function to handle outgoing sessions and remove them from the session data map
void handle_outgoing_session(uint64_t session_id) {
    // Lock the mutex for thread-safe access to the session data map
    std::lock_guard<std::mutex> lock(session_data_map_mutex);

    // Check if the outgoing session is active
    auto it = session_data_map.find(session_id);
    if (it == session_data_map.end()) {
        return;
    }

    // Remove the session from the session data map
    session_data_map.erase(it);
}

int main() {
    // Initialize the network interface module
    handle_incoming_packet();
    handle_outgoing_packet();
    handle_incoming_session();
    handle_outgoing_session();

    // Start the network interface loop
    while (true) {
        // Handle incoming packets and route them to the appropriate session queue
        handle_incoming_packet();

        // Handle outgoing packets and route them to the appropriate session queue
        handle_outgoing_packet();

        // Check for new incoming sessions and initialize them in the session data map
        handle_incoming_session();

        // Check for disconnected sessions and remove them from the session data map
        handle_outgoing_session();
    }

    return 0;
