#include <stdbool.h>
#include <time.h>

// Define the record structure to store offset, key, and value
typedef struct Record {
    uint32_t offset;
    int* key;
    double value;
} Record;

// Global variables for memory management
const size_t MEMORY_LIMIT = 100 * 1024 * 1024; // 100 MB
size_t current_memory = 0;
Record* records = NULL;
int record_count = 0;
bool is_initialized = false;

// Initialize the memory pool and allocate memory for the records
void initialize() {
    if (is_initialized) return;
    records = (Record*) malloc(sizeof(Record) * 1024); // initial allocation of 1024 records
    current_memory = sizeof(Record) * 1024;
    is_initialized = true;
}

// Free the memory allocated for the records
void deinitialize() {
    if (!is_initialized) return;
    free(records);
    records = NULL;
    current_memory = 0;
    record_count = 0;
    is_initialized = false;
}

// Allocate memory for a new record and update the memory usage statistics
Record* allocate_record() {
    if (!is_initialized) return NULL;
    // Check if there's enough memory available to allocate a new record
    if (current_memory + sizeof(Record) > MEMORY_LIMIT) {
        printf("Memory limit exceeded, cannot allocate more records\n");
        return NULL;
    }
    Record* new_record = (Record*) malloc(sizeof(Record));
    // Check if memory allocation failed due to fragmentation
    if (new_record == NULL) {
        printf("Memory allocation failed, trying to defragment...\n");
        defragment();
        new_record = (Record*) malloc(sizeof(Record));
        // If memory allocation still fails, return NULL to indicate failure
        if (new_record == NULL) {
            return NULL;
        }
    }
    current_memory += sizeof(Record);
    record_count++;
    return new_record;
}

// Free the memory allocated for a record and update the memory usage statistics
void free_record(Record* record) {
    if (!is_initialized || record == NULL) return;
    free(record);
    current_memory -= sizeof(Record);
    record_count--;
}

// Compact the memory footprint of the collection periodically to mitigate memory fragmentation
void compact() {
    if (!is_initialized || record_count == 0) return;
    // Determine the optimal time for compaction based on current memory usage trends
    if (current_memory < MEMORY_LIMIT * 0.8) {
        // Compact the collection when the memory usage is below 80% of the maximum limit
        Record* new_records = (Record*) malloc(sizeof(Record) * record_count);
        if (new_records == NULL) {
            printf("Compaction failed, cannot allocate more memory\n");
            return;
        }
        current_memory = sizeof(Record) * record_count;
        memcpy(new_records, records, current_memory);
        free(records);
        records = new_records;
    }
}

// Defragment the memory to minimize fragmentation and optimize for performance
void defragment() {
    if (!is_initialized || record_count == 0) return;
    // Create a new, contiguous block of memory with enough space for all records
    size_t total_size = sizeof(Record) * record_count;
    void* new_mem = malloc(total_size);
    if (new_mem == NULL) {
        printf("Defragmentation failed, cannot allocate more memory\n");
        return;
    }
    // Copy all records to the new memory block, freeing each record as it's copied
    for (int i = 0; i < record_count; i++) {
        Record* old_record = &records[i];
        Record* new_record = (Record*) new_mem + i;
        memcpy(new_record, old_record, sizeof(Record));
        free_record(old_record);
    }
    // Update the records pointer and current memory usage
    records = (Record*) new_mem;
    current_memory = total_size;
}

// Populate each record's key with a unique value derived from its index in the array
void populate_keys() {
    if (!is_initialized || record_count == 0) return;
    for (int i = 0; i < record_count; i++) {
        Record* record = &records[i];
        record->key = (int*) malloc(sizeof(int));
        *record->key = i;
    }
}

// Randomly generate and assign a double value within a specified range to each record's value field
void generate_values(double min, double max) {
    if (!is_initialized || record_count == 0) return;
    srand(time(NULL)); // seed the random number generator
    for (int i = 0; i < record_count; i++) {
        Record* record = &records[i];
        record->value = min + ((double) rand() / (RAND_MAX)) * (max - min);
    }
}

// Implement error handling to manage scenarios where memory allocation fails
void handle_allocation_failure(Record* record) {
    if (!is_initialized || record == NULL) return;
    // Free the partially allocated record and try again with a new allocation
