void init_records(size_t N, int min_value, int max_value, int num_threads) {
    // Allocate memory for the offset and key arrays
    long* offsets = malloc(sizeof(long) * N);
    int* keys = malloc(sizeof(int) * N);
    if (offsets == NULL || keys == NULL) {
        printf("Error: failed to allocate memory\n");
        return;
    }

    // Initialize the offset and key arrays
    for (size_t i = 0; i < N; i++) {
        offsets[i] = i * sizeof(Record);
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
    }

    // Allocate memory for the record array
    Record* records = malloc(sizeof(Record) * N);
    if (records == NULL) {
        printf("Error: failed to allocate memory\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the record array
    for (size_t i = 0; i < N; i++) {
        records[i].value = keys[i];
    }

    // Track and manage memory allocated for all data structures
    struct MemInfo {
        size_t offsets_size;
        size_t keys_size;
        size_t records_size;
    };
    struct MemInfo mem_info = {
        .offsets_size = sizeof(long) * N,
        .keys_size = sizeof(int) * N,
        .records_size = sizeof(Record) * N
    };
    struct MemInfo* total_mem_info = &mem_info;

    // Implement RAII principles for resource management
    void cleanup() {
        free(offsets);
        free(keys);
        free(records);
    }

    // Use a loop to set the value of each record's int field to a random value within a specified range [min_value, max_value]
    for (size_t i = 0; i < N; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Validate the range to ensure it is valid and non-empty
    if (min_value > max_value || min_value == max_value) {
        printf("Error: invalid range specified\n");
        cleanup();
        return;
    }

    // Implement a mechanism for the caller to specify the number of threads to use for parallelizing the initialization of the records
    if (num_threads < 1) {
        num_threads = 1;
    }

    // Use RAII principles to ensure that resources are properly released when the function exits, even if interrupted
    struct ThreadInfo {
        size_t thread_id;
        void* record_ptr;
    };
    struct ThreadInfo* threads[num_threads];
    for (size_t i = 0; i < num_threads; i++) {
        threads[i] = malloc(sizeof(struct ThreadInfo));
        threads[i]->thread_id = i;
        threads[i]->record_ptr = records + offsets[i];
    }

    // Measure and report the time taken to allocate memory and initialize the records using a profiling mechanism
    struct Profiler {
        clock_t start;
        void init() {
            start = clock();
        }
        double elapsed() {
            return (double)(clock() - start) / CLOCKS_PER_SEC;
        }
    };
    struct Profiler profiler;
    profiler.init();

    // Implement a mechanism for the caller to specify the number of threads to use for parallelizing the initialization of the records
    #pragma omp parallel num_threads(num_threads) default(none) shared(records, offsets, N)
    {
        size_t thread_id = omp_get_thread_num();
        void* record_ptr = records + offsets[thread_id];

        // Use a loop to set the value of each record's int field to a random value within a specified range [min_value, max_value]
        for (size_t i = 0; i < N; i++) {
            ((Record*)record_ptr)->value = rand() % (max_value - min_value + 1) + min_value;
        }
    }

    // Report the profiling results using a callback function provided at runtime
    printf("Profiling results: time taken to allocate memory and initialize the records = %.2lf seconds\n", profiler.elapsed());

    // Ensure that the function can operate efficiently even when N is very large, minimizing cache misses and ensuring optimal memory access patterns
    #pragma omp parallel num_threads(num_threads) default(none) shared(records, offsets, N)
    {
        size_t thread_id = omp_get_thread_num();
        void* record_ptr = records + offsets[thread_id];

        // Ensure that the function can operate efficiently even when N is very large, minimizing cache misses and ensuring optimal memory access patterns
        for (size_t i = 0; i < N; i++) {
            ((Record*)record_ptr)->value = keys[i];
        }
    }

    // Implement a mechanism to handle cases where N is zero gracefully, returning a null pointer for all allocated structures without causing undefined behavior
    if (N == 0) {
        printf("Error: N is zero\n");
        cleanup();
        return;
    }

    // Provide a mechanism for the caller to specify the number of threads to use for parallelizing the initialization of the records, with a default of one thread
    if (num_threads < 1) {
        num_threads = 1;
    }

    // Use RAII principles to ensure that resources are properly released when the function exits, even if interrupted
    for (size_t i = 0; i < num_threads; i++) {
        free(threads[i]);
    }
}
