#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <netdb.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1024
#define CONN_TIMEOUT 600 // 10 minutes
#define BUF_SIZE 512

typedef struct {
    int sockfd;
    char* hostname;
    in_port_t port;
    time_t last_active;
    unsigned char status;
} conn_t;

// Connection pool
static conn_t connections[MAX_CONNECTIONS];
static int num_connections = 0;

// Lock for thread-safe access to connection pool
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to establish a new connection
int connect(char* hostname, in_port_t port) {
    // Check if there's a free slot for the new connection
    if (num_connections >= MAX_CONNECTIONS) {
        printf("Error: no more free connections\n");
        return -1;
    }

    // Find the next available connection
    int i = 0;
    while (i < num_connections && connections[i].status != 0) {
        i++;
    }
    if (i == num_connections) {
        printf("Error: no more free connections\n");
        return -1;
    }

    // Establish the new connection
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        printf("Error: failed to create socket\n");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, hostname, &server_addr.sin_addr) <= 0) {
        printf("Error: failed to resolve hostname\n");
        return -1;
    }

    if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        printf("Error: failed to connect socket\n");
        close(sockfd);
        return -1;
    }

    // Set connection status and timestamp
    connections[i].status = 1;
    connections[i].last_active = time(NULL);
    connections[i].hostname = hostname;
    connections[i].port = port;
    connections[i].sockfd = sockfd;

    // Return the new connection index
    return i;
}

// Function to close a connection and remove it from the pool
void disconnect(int conn_index) {
    // Check if the connection exists
    if (conn_index < 0 || conn_index >= num_connections || connections[conn_index].status == 0) {
        printf("Error: no such connection\n");
        return;
    }

    // Close the socket and set the status to 0
    close(connections[conn_index].sockfd);
    connections[conn_index].status = 0;

    // Remove the connection from the pool
    int i = 0;
    while (i < num_connections && conn_index != i) {
        i++;
    }
    if (i == num_connections) {
        printf("Error: no such connection\n");
        return;
    }
    memmove(&connections[conn_index], &connections[conn_index + 1], sizeof(conn_t) * (num_connections - conn_index - 1));
    num_connections--;
}

// Function to check if a connection is still active and return its index
int is_active(char* hostname, in_port_t port) {
    // Check if there's a free slot for the new connection
    int i = 0;
    while (i < num_connections && connections[i].status == 0) {
        i++;
    }
    if (i == num_connections) {
        return -1;
    }

    // Check if the connection matches the specified hostname and port
    if (strcmp(connections[i].hostname, hostname) != 0 || connections[i].port != port) {
        return -1;
    }

    // Return the index of the active connection
    return i;
}

// Function to send data over a connection
int send_data(char* hostname, in_port_t port, char* buffer, int buflen) {
    // Check if there's a free slot for the new connection
    int conn_index = is_active(hostname, port);
    if (conn_index < 0) {
        printf("Error: no such active connection\n");
        return -1;
    }

    // Check if the socket is still valid and has not timed out
    time_t now = time(NULL);
    if (connections[conn_index].last_active + CONN_TIMEOUT < now) {
        printf("Error: connection timed out\n");
        disconnect(conn_index);
        return -1;
    }

    // Send the data over the socket
    int bytes = send(connections[conn_index].sockfd, buffer, buflen, 0);
    if (bytes < 0) {
        printf("Error: failed to send data\n");
        return -1;
    }

    // Update the last active timestamp and return the number of bytes sent
    connections[conn_index].last_active = now;
    return bytes;
}

// Function to receive data over a connection
int recv_data(char* hostname, in_port_t port, char* buffer, int buflen) {
    // Check if there's a free slot for the new connection
    int conn_index = is_active(hostname, port);
    if (conn_index < 0) {
        printf("Error: no such active connection\n");
        return -1;
    }

    // Check if the socket is still valid and has not timed out
    time_t now = time(NULL);
    if (connections[conn_index].last_active + CONN_TIMEOUT < now) {
        printf("Error: connection timed out\n");
        disconnect(conn_index);
        return -1;
    }

    // Receive the data over the socket
    int bytes = recv(connections[conn_index].sockfd, buffer, buflen, 0);
    if (bytes < 0) {
        printf("Error: failed to receive data\n");
        return -1;
    }

    // Update the last active timestamp and return the number of bytes received
    connections[conn_index].last_active = now;
    return bytes;
}

// Monitoring function for connection metrics
void monitor(char* hostname, in_port_t port) {
    // Check if there's a free slot for the new connection
    int conn_index = is_active(hostname, port);
    if (conn_index < 0) {
        printf("Error: no such active connection\n");
        return;
    }

    // Calculate the success rate and average response time
    float success_rate = 100 * (float)(connections[conn_index].status == 1);
    int bytes_received = recv_data(hostname, port, buffer, buflen);
    float avg_response_time = -1;
    if (bytes_received > 0) {
        avg_response_time = 100 * (float)(connections[conn_index].last_active - connections[conn_index].first_active) / CONN_TIMEOUT;
    }

    // Print the monitoring data
    printf("Hostname: %s\nPort: %d\nSuccess rate: %.2f%%\nAverage response time: %.2fms\n", hostname, port, success_rate, avg_response_time);
}
