    // Sort records using stable sorting algorithm
    for (int i = 0; i < num_records; i++) {
        for (int j = i + 1; j < num_records; j++) {
            if (descending == true && record_array[i].key > record_array[j].key) {
                swap(record_array, offset_array, i, j);
            } else if (descending == false && record_array[i].key < record_array[j].key) {
                swap(record_array, offset_array, i, j);
            }
        }
    }
}

