// Custom memory pool for allocating records
struct RecordPool {
    int capacity;
    int size;
    struct Record* records;
};

struct Record {
    int key;
    long offset;
};

int main() {
    // Initialize arrays for offsets and keys
    long *offsets = NULL;
    int *keys = NULL;

    // Get user input for size of arrays
    printf("Enter the number of records: ");
    int numRecords;
    scanf("%d", &numRecords);

    // Allocate memory for arrays and initialize with zeroes
    offsets = (long*)calloc(numRecords, sizeof(long));
    keys = (int*)calloc(numRecords, sizeof(int));

    // Validate user input and handle potential errors
    if (offsets == NULL || keys == NULL) {
        printf("Error: Failed to allocate memory for arrays\n");
        return 1;
    }

    // Initialize boundary checks and input sanitization
    int i = 0;
    while (i < numRecords && i >= 0) {
        offsets[i] = 0;
        keys[i] = 0;
        i++;
    }

    // Allocate memory for record structures and initialize with zeroes
    struct Record *records = (struct Record*)calloc(numRecords, sizeof(struct Record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return 1;
    }

    // Initialize record values with random numbers within a specified range
    int min = 0;
    int max = 10000;
    srand(time(NULL));
    for (i = 0; i < numRecords; i++) {
        records[i].key = rand() % (max - min + 1) + min;
        records[i].offset = 0;
    }

    // Use a custom memory pool to manage memory allocation efficiently
    struct RecordPool *recordPool = (struct RecordPool*)calloc(1, sizeof(struct RecordPool));
    recordPool->capacity = numRecords;
    recordPool->size = numRecords;
    recordPool->records = records;

    // Implement a strategy to dynamically resize the memory pool based on workload patterns
    int threshold = 10; // Threshold for resizing the memory pool
    if (recordPool->size >= threshold) {
        recordPool->capacity += threshold;
        recordPool->records = (struct Record*)realloc(recordPool->records, recordPool->capacity * sizeof(struct Record));
        if (recordPool->records == NULL) {
            printf("Error: Failed to reallocate memory for records\n");
            free(offsets);
            free(keys);
            return 1;
        }
    }

    // Implement a mechanism to reclaim unused memory to optimize resource utilization
    int numRecordsUsed = 0;
    for (i = 0; i < numRecords; i++) {
        if (records[i].key != 0) {
            numRecordsUsed++;
        }
    }
    recordPool->size = numRecordsUsed;

    // Sort the records based on their int values using a stable sorting algorithm
    std::stable_sort(recordPool->records, recordPool->records + recordPool->size, [](const struct Record& a, const struct Record& b) { return a.key < b.key; });

    // Implement a hybrid sorting approach that switches to a more traditional algorithm when the dataset size is below a certain threshold for better efficiency
    int smallThreshold = 1000; // Threshold for switching to a more traditional sorting algorithm
    if (recordPool->size < smallThreshold) {
        std::sort(recordPool->records, recordPool->records + recordPool->size, [](const struct Record& a, const struct Record& b) { return a.key < b.key; });
    }

    // Serialize the sorted records into a file using a secure encryption library
    FILE *fp = fopen("records.bin", "wb");
    if (fp == NULL) {
        printf("Error: Failed to open file for writing\n");
        free(offsets);
        free(keys);
        return 1;
    }
    for (i = 0; i < recordPool->size; i++) {
        struct Record *record = &recordPool->records[i];
        fwrite(&record, sizeof(struct Record), 1, fp);
    }
    fclose(fp);

    // Clean up memory and return successfully
    free(offsets);
    free(keys);
    free(records);
    return 0;
}
```
