// Define the data structure for storing double precision floating point numbers with associated char labels.
struct DoubleMap {
    map: HashMap<char, f64>,
}

impl DoubleMap {
    // Constructor for creating a new instance of the struct.
    fn new() -> Self {
        Self {
            map: HashMap::new(),
        }
    }

    // Method to insert a key-value pair into the map.
    fn insert(&mut self, key: char, value: f64) {
        self.map.insert(key, value);
    }

    // Method to retrieve a value from the map given its associated key.
    fn get(&self, key: &char) -> Option<f64> {
        self.map.get(key).copied()
    }
}

// Define the data structure for storing the tree of double maps.
struct Tree {
    root: DoubleMap,
}

impl Tree {
    // Constructor for creating a new instance of the struct.
    fn new() -> Self {
        Self {
            root: DoubleMap::new(),
        }
    }

    // Method to insert a key-value pair into the tree.
    fn insert(&mut self, key: char, value: f64) {
        let mut current = &mut self.root;
        for c in key.chars() {
            if !current.map.contains_key(&c) {
                current.map.insert(c, DoubleMap::new());
            }
            current = current.map.get_mut(&c).unwrap();
        }
        current.insert(key, value);
    }

    // Method to retrieve a value from the tree given its associated key.
    fn get(&self, key: &char) -> Option<f64> {
        let mut current = &self.root;
        for c in key.chars() {
            if !current.map.contains_key(&c) {
                return None;
            }
            current = current.map.get(&c).unwrap();
        }
        current.get(key)
    }
}

