    ushort_arr = (unsigned short*)malloc(sizeof(unsigned short) * num_elements);
    meas_arr = (measurement_t*)malloc(sizeof(measurement_t) * num_elements);

    // Check for allocation failures and handle them appropriately
    if (float_arr == NULL || ushort_arr == NULL || meas_arr == NULL) {
        printf("Memory allocation failed.\n");
        exit(1);
    }

    // Populate each array with random values, unique identifiers, and current timestamp
