// Define the structure for measurements
struct measurement {
    float value;
    unsigned short id;
    time_t timestamp;
};

// Define the configuration structure
struct config {
    char* log_file_path;
    int logging_level;
    long flush_interval; // in milliseconds
};

// Function to initialize measurements
void initializeMeasurements(int num_records, float min_value, float max_value, struct config* config) {
    // Check for valid parameters
    if (num_records < 1 || min_value >= max_value) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Allocate memory for the measurements array
    struct measurement* measurements = malloc(sizeof(struct measurement) * num_records);
    if (measurements == NULL) {
        fprintf(stderr, "Failed to allocate memory for measurements\n");
        return;
    }

    // Initialize each record with a random value within the specified range, unique ID, and current timestamp
    for (int i = 0; i < num_records; i++) {
        struct measurement* current_measurement = &measurements[i];
        current_measurement->value = min_value + (float)(rand() % (max_value - min_value));
        current_measurement->id = i + 1; // start ID at 1
        current_measurement->timestamp = time(NULL);
    }

    // Flush logs to disk periodically using the flush interval specified in the configuration
    long flush_interval_ms = config->flush_interval * 1000; // convert from seconds to milliseconds
    while (1) {
        sleep(flush_interval_ms);
        fprintf(stderr, "Flushing logs to disk...\n");
        FILE* log_file = fopen(config->log_file_path, "a+");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file for writing\n");
            continue;
        }
        for (int i = 0; i < num_records; i++) {
            struct measurement* current_measurement = &measurements[i];
            fprintf(log_file, "%f,%d,%ld\n", current_measurement->value, current_measurement->id, current_measurement->timestamp);
        }
        fclose(log_file);
    }
}
