```c
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
    char buffer[256];
} record;

// Initialize a new array of records with a given size
record** init_records(size_t size) {
    // Allocate memory for the array of records
    record **records = malloc(sizeof(record *) * size);

    // Initialize each record with a random value and unique identifier
    for (int i = 0; i < size; ++i) {
        srand(time(NULL)); // Seed the random number generator
        records[i] = malloc(sizeof(record));
        records[i]->value = rand() % 100; // Generate a random value within the specified range
        snprintf(records[i]->buffer, sizeof(records[i]->buffer), "Record-%d", i); // Create a unique identifier based on the record's index and seed value
    }

    return records;
}

// Free memory used by an array of records
void free_records(record **records, size_t size) {
    for (int i = 0; i < size; ++i) {
        free(records[i]);
    }
    free(records);
}
```
