        // Generate a random float value within the specified range
        float value = rand() % (cfg.thresholds[1] - cfg.thresholds[0]) + cfg.thresholds[0];

        // Generate a unique identifier for the device that sent the measurement
        unsigned short device_id = i % 65536;

        // Get the current timestamp and convert it to a time_t value
        time_t timestamp = time(NULL);

        // Determine the type of event based on predefined criteria
        enum event_type event = EVENT_NONE;

        // Populate the measurement record with the generated values
        measurements.values[i] = (measurement_t) {value, device_id, timestamp, event};
    }

    // Free the memory allocated for the measurements array
    free(measurements.values);

    return 0;
}

// Parse a JSON configuration file and populate the configuration settings structure
int parse_config(const char *file, struct config *cfg) {
    // Initialize the configuration settings to default values
    cfg->random_seed = time(NULL);
    cfg->sampling_interval = 10;
    cfg->thresholds[0] = 0.0f;
    cfg->thresholds[1] = 1.0f;
    cfg->thresholds[2] = 0.5f;

    // Open the JSON configuration file for reading
    FILE *fp = fopen(file, "r");
    if (!fp) {
        return -1;
    }

    // Parse the JSON data and populate the configuration settings structure
    char buffer[4096];
    while (fgets(buffer, sizeof(buffer), fp)) {
        int index = 0;
        if (!strncmp(buffer, "\"random_seed\":", 13) && sscanf(buffer + 13, "%d", &index) == 1) {
            cfg->random_seed = index;
        } else if (!strncmp(buffer, "\"sampling_interval\":", 20) && sscanf(buffer + 20, "%hu", &index) == 1) {
            cfg->sampling_interval = index;
        } else if (!strncmp(buffer, "\"thresholds\":", 13) && sscanf(buffer + 13, "[%f,%f,%f]", &cfg->thresholds[0], &cfg->thresholds[1], &cfg->thresholds[2]) == 3) {
            cfg->thresholds[0] = index;
        } else if (!strncmp(buffer, "\"type\":", 7) && sscanf(buffer + 7, "%d", &index) == 1) {
            cfg->type = index;
        }
    }

    // Close the JSON configuration file
    fclose(fp);

    return 0;
}
