['```c
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int value;
    long *pointer;
    int index;
} record_t;

struct records {
    size_t count;
    record_t **records;
};

void init_records(struct records *r) {
    r->count = 0;
    r->records = NULL;
}

void add_record(struct records *r, int value, long *pointer, int index) {
    pthread_mutex_lock(&r->mutex);
    record_t *new_record = malloc(sizeof(record_t));
    new_record->value = value;
    new_record->pointer = pointer;
    new_record->index = index;
    r->records = realloc(r->records, (r->count + 1) * sizeof(record_t*));
    r->records[r->count] = new_record;
    r->count++;
    pthread_mutex_unlock(&r->mutex);
}

void remove_record(struct records *r, int index) {
    pthread_mutex_lock(&r->mutex);
    record_t *removed = r->records[index];
    free(removed);
    r->count--;
    for (size_t i = index; i < r->count; i++) {
        r->records[i] = r->records[i + 1];
    }
    r->records = realloc(r->records, r->count * sizeof(record_t*));
    pthread_mutex_unlock(&r->mutex);
}

void clear_records(struct records *r) {
    pthread_mutex_lock(&r->mutex);
    for (size_t i = 0; i < r->count; i++) {
        free(r->records[i]);
    }
    free(r->records);
    r->count = 0;
    pthread_mutex_unlock(&r->mutex);
}

void print_records(struct records *r) {
    for (size_t i = 0; i < r->count; i++) {
        printf("%d, %ld, %d\n", r->records[i]->value, r->records[i]->pointer, r->records[i]->index);
    }
}
```
