  // Allocate memory for the array of data_points
  data_point *array = (data_point *)malloc(sizeof(data_point) * size);

  // Initialize each data_point in the array with a random value within the specified range
  for (int i = 0; i < size; i++) {
    double rand_value = (double)(rand() % 100) / 100.0;
    array[i].value = rand_value;
    array[i].buffer = NULL;
    array[i].next = NULL;
  }

  return array;
}

// Function to dynamically allocate memory for a linked list of data_points
data_point* allocate_linked_list(int size) {
  // Allocate memory for the first element in the linked list
  data_point *head = (data_point *)malloc(sizeof(data_point));
  head->value = 0;
  head->buffer = NULL;
  head->next = NULL;

  // Initialize each data_point in the linked list with a random value within the specified range
  for (int i = 1; i < size; i++) {
    double rand_value = (double)(rand() % 100) / 100.0;
    head->next = malloc(sizeof(data_point));
    head = head->next;
    head->value = rand_value;
    head->buffer = NULL;
    head->next = NULL;
  }

  return head;
}

// Function to populate the char buffer with a unique string based on the point's identifier and current timestamp
void populate_buffer(data_point *point) {
  // Get the current time as a string
  char *time_str = (char *)malloc(sizeof(char) * 20);
  strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", gmtime(&point->value));

  // Create a unique string based on the point's identifier and current timestamp
  char *buffer = (char *)malloc(sizeof(char) * 20);
  sprintf(buffer, "%d_%s", point->identifier, time_str);

  // Set the buffer field of the data_point structure
  point->buffer = buffer;
}

// Function to manage memory efficiently and avoid leaks for a linked list of data_points
void manage_linked_list(data_point *head) {
  // Traverse the linked list and free any allocated memory for each data_point
  while (head != NULL) {
    if (head->buffer != NULL) {
      free(head->buffer);
      head->buffer = NULL;
    }
    data_point *next = head->next;
    free(head);
    head = next;
  }
}

