    char *NAS_MESSAGE;
} LTE_UPLINK_NAS_TRANSPORT;

void initialize_uplink_nas_transport(LTE_UPLINK_NAS_TRANSPORT *uplink_nas_transport, int UE_ID, char *NAS_MESSAGE) {
    uplink_nas_transport->UE_ID = UE_ID;
    uplink_nas_transport->NAS_MESSAGE = NAS_MESSAGE;
}

void encrypt_uplink_nas_transport(LTE_UPLINK_NAS_TRANSPORT *uplink_nas_transport, char *key) {
    AES_KEY aes_key;
    unsigned char iv[16];
    unsigned char ciphertext[1024];
    size_t ciphertext_len = 0;
    int ret = 0;

    // Initialize the AES key from the given key
    if (ret = AES_set_encrypt_key(key, strlen(key) * 8, &aes_key)) {
        printf("Error: Invalid key length\n");
        return;
    }

    // Initialize the IV
    memset(iv, 0x00, sizeof(iv));

    // Encrypt the NAS message using AES-CBC with the given key and IV
    ret = AES_cbc_encrypt((unsigned char *)uplink_nas_transport->NAS_MESSAGE, ciphertext, strlen(uplink_nas_transport->NAS_MESSAGE), &aes_key, iv, &ciphertext_len);
    if (ret < 0) {
        printf("Error: AES encryption failed\n");
        return;
    }

    // Update the NAS message with the encrypted ciphertext
    uplink_nas_transport->NAS_MESSAGE = (char *)ciphertext;
}

