        return;
    }

    // Initialize the IV
    memset(iv, 0x00, sizeof(iv));

    // Decrypt the NAS message using AES-CBC with the given key and IV
    ret = AES_cbc_encrypt((unsigned char *)uplink_nas_transport->NAS_MESSAGE, plaintext, strlen(uplink_nas_transport->NAS_MESSAGE), &aes_key, iv, &plaintext_len);
    if (ret < 0) {
        printf("Error: AES decryption failed\n");
        return;
    }

    // Update the NAS message with the plaintext
    uplink_nas_transport->NAS_MESSAGE = (char *)plaintext;
}

void configure_uplink_nas_transport(LTE_UPLINK_NAS_TRANSPORT *uplink_nas_transport, json_object *config) {
