void init_offsets(int num_offsets) {
    // Allocate memory for the array of offsets
    offset_t* offsets = (offset_t*)malloc(sizeof(offset_t) * num_offsets);
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets.\n");
        return;
    }

    // Initialize the array of offsets
    for (int i = 0; i < num_offsets; i++) {
        offsets[i].value = -1;
        offsets[i].record = NULL;
    }
