    event_t* events = (event_t*)malloc(sizeof(event_t) * num_events);
    if (!events) {
        printf("Error: Failed to allocate memory for events.\n");
        return;
    }

    // Initialize the array of events
    for (int i = 0; i < num_events; i++) {
        events[i].record = NULL;
    }
}

// Populate each record with a random integer within the specified range
void populate_records(int min, int max) {
    // Initialize the seed for the randomizer
    srand((unsigned int)time(NULL));

    // Loop through each record and assign a random integer value
    for (int i = 0; i < num_offsets; i++) {
        offsets[i].record->random_int = rand() % (max - min + 1) + min;
    }
}

// Print the values of each offset structure and its corresponding record
void print_offsets(offset_t* offsets, int num_offsets) {
    printf("Offsets:\n");
    for (int i = 0; i < num_offsets; i++) {
        printf("%d: %ld\n", i, offsets[i].value);
        if (offsets[i].record != NULL) {
            printf("   Record: %p, Random Integer: %d\n", offsets[i].record, offsets[i].record->random_int);
        } else {
            printf("   Record: NULL\n");
        }
    }
}

