// Session object structure
struct session {
  char *session_id;
  int timeout;
  status_t connection_status;
};

// Initialize a list of sessions with randomized timeout values
void initialize_sessions(struct session **sessions, size_t num_sessions) {
  // Initialize the timeout field of each session to a random value within a specified range
  for (size_t i = 0; i < num_sessions; i++) {
    sessions[i]->timeout = generate_random_timeout(MIN_TIMEOUT, MAX_TIMEOUT);
  }
}

// Generate a random timeout value between the minimum and maximum values
int generate_random_timeout(int min, int max) {
  return rand() % (max - min + 1) + min;
}

// Add a new session to the list of sessions
void add_session(struct session **sessions, size_t num_sessions, char *session_id) {
  // Allocate memory for the new session object
  struct session *new_session = (struct session *)malloc(sizeof(struct session));
  if (!new_session) {
    perror("Failed to allocate memory for new session");
    exit(EXIT_FAILURE);
  }

  // Initialize the session ID and timeout field
  new_session->session_id = session_id;
  new_session->timeout = generate_random_timeout(MIN_TIMEOUT, MAX_TIMEOUT);

  // Add the new session to the list of sessions
  sessions[num_sessions] = new_session;
}

// Remove a session from the list of sessions
void remove_session(struct session **sessions, size_t num_sessions, char *session_id) {
  // Find the index of the session to be removed
  int i;
  for (i = 0; i < num_sessions; i++) {
    if (!strcmp(sessions[i]->session_id, session_id)) {
      break;
    }
  }

  // Remove the session from the list of sessions
  if (i < num_sessions) {
    for (size_t j = i; j < num_sessions - 1; j++) {
      sessions[j] = sessions[j + 1];
    }
    free(sessions[num_sessions - 1]);
    num_sessions--;
  } else {
    printf("Session with ID %s not found\n", session_id);
  }
}

// Update the timeout field of a session
void update_session_timeout(struct session **sessions, size_t num_sessions, char *session_id) {
  // Find the index of the session to be updated
  int i;
  for (i = 0; i < num_sessions; i++) {
    if (!strcmp(sessions[i]->session_id, session_id)) {
      break;
    }
  }

  // Update the timeout field of the session
  if (i < num_sessions) {
    sessions[i]->timeout = generate_random_timeout(MIN_TIMEOUT, MAX_TIMEOUT);
  } else {
    printf("Session with ID %s not found\n", session_id);
  }
}

// Print the list of sessions and their timeout values
void print_sessions(struct session **sessions, size_t num_sessions) {
  for (size_t i = 0; i < num_sessions; i++) {
    printf("Session %d: %s, Timeout: %d\n", i + 1, sessions[i]->session_id, sessions[i]->timeout);
  }
}

// Main function to demonstrate the usage of the session management functions
int main() {
  // Initialize the list of sessions with randomized timeout values
  struct session **sessions = NULL;
  size_t num_sessions = 0;
  initialize_sessions(&sessions, &num_sessions);

  // Add a new session to the list of sessions
  add_session(&sessions, &num_sessions, "new-session");

  // Update the timeout field of a session
  update_session_timeout(&sessions, num_sessions, "session-1");

  // Remove a session from the list of sessions
  remove_session(&sessions, num_sessions, "session-2");

  // Print the list of sessions and their timeout values
  print_sessions(sessions, num_sessions);

  return 0;
}
