// Define the record structure for storing data
typedef struct {
    long offset;
    int key;
    void* data_source;
} record;

// Define a function to initialize the array of records
void init_records(record** records, size_t num_records) {
    // Allocate memory for the array of records
    *records = malloc(num_records * sizeof(record));
    if (*records == NULL) {
        return;
    }

    // Initialize each record with a random key and offset
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].key = rand() % 1000;
        (*records)[i].offset = time(NULL);
        (*records)[i].data_source = NULL;
    }
}

// Define a function to dynamically allocate memory for the array of records and initialize it
record** init_dynamic_records(size_t num_records) {
    record** records = malloc(num_records * sizeof(record*));
    if (records == NULL) {
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i] = malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            free(records);
            return NULL;
        }
    }

    init_records((*records), num_records);

    return records;
}

// Define a function to release memory for the array of records
void release_records(record** records) {
    if (records == NULL) {
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        free((*records)[i].data_source);
        free(*records);
        records++;
    }
}
