// Structure to represent a MAC PDU (Header and SDU)
typedef struct {
    MAC_HEADER header;
    MACSDU sdu;
} MAC_PDU;

// Structure to represent the manager for the list of MAC PDUs
typedef struct {
    pthread_mutex_t mutex;
    int num_pdus;
    MAC_PDU *pdus[MAX_NUM_PDUS]; // MAX_NUM_PDUS is a constant that defines the maximum number of MAC PDUs to be stored in the manager
} MAC_PDU_MANAGER;

// Initialize the manager with an empty list of MAC PDUs
void mac_pdu_manager_init(MAC_PDU_MANAGER *manager) {
    assert(manager != NULL);

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&manager->mutex, &attr);
    manager->num_pdus = 0;
}

// Add a MAC PDU to the list of PDUs managed by the manager
void mac_pdu_manager_add(MAC_PDU_MANAGER *manager, MAC_PDU *pdu) {
    assert(manager != NULL);
    assert(pdu != NULL);

    pthread_mutex_lock(&manager->mutex);
    manager->pdus[manager->num_pdus++] = pdu;
    pthread_mutex_unlock(&manager->mutex);
}

// Remove a MAC PDU from the list of PDUs managed by the manager
void mac_pdu_manager_remove(MAC_PDU_MANAGER *manager, MAC_PDU *pdu) {
    assert(manager != NULL);
    assert(pdu != NULL);

    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->num_pdus; i++) {
        if (manager->pdus[i] == pdu) {
            // Remove the PDU from the list by shifting all subsequent PDUs one position earlier
            for (int j = i + 1; j < manager->num_pdus; j++) {
                manager->pdus[j - 1] = manager->pdus[j];
            }
            // Decrement the number of PDUs by 1
            manager->num_pdus--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

// Get a pointer to the MAC PDU at the specified index in the list managed by the manager
MAC_PDU *mac_pdu_manager_get(MAC_PDU_MANAGER *manager, int index) {
    assert(manager != NULL);

    pthread_mutex_lock(&manager->mutex);
    MAC_PDU *pdu = manager->pdus[index];
    pthread_mutex_unlock(&manager->mutex);
    return pdu;
}

// Get the number of PDUs in the list managed by the manager
int mac_pdu_manager_get_num_pdus(MAC_PDU_MANAGER *manager) {
    assert(manager != NULL);

    int num_pdus = 0;
    pthread_mutex_lock(&manager->mutex);
    num_pdus = manager->num_pdus;
    pthread_mutex_unlock(&manager->mutex);
    return num_pdus;
}

// Function to trigger alerts when the number of pending PDUs exceeds a specified limit
void mac_pdu_manager_check_thresholds(MAC_PDU_MANAGER *manager) {
    assert(manager != NULL);

    // Check if any thresholds have been set
    if (manager->num_pdus > 0 && manager->num_pdus >= THRESHOLD) {
        syslog(LOG_ALERT, "The number of pending PDUs has exceeded the threshold: %d", THRESHOLD);
    }
}

// Function to handle logging for diagnostic purposes
void mac_pdu_manager_log(MAC_PDU_MANAGER *manager) {
    assert(manager != NULL);

    pthread_mutex_lock(&manager->mutex);
    // Log the number of pending PDUs and their details
    syslog(LOG_INFO, "Number of pending PDUs: %d", manager->num_pdus);
    for (int i = 0; i < manager->num_pdus; i++) {
        MAC_PDU *pdu = manager->pdus[i];
