// Define the log levels
#define DEBUG 0
#define INFO 1
#define WARNING 2
#define ERROR 3

// Define the log message structure
struct log_message {
    int id;                 // Unique ID for the log message
    time_t timestamp;       // Timestamp of the log message
    int level;              // Log level (DEBUG, INFO, WARNING, ERROR)
    char *message;          // Message content
};

// Define the log processor structure
struct log_processor {
    pthread_mutex_t lock;   // Lock for synchronizing access to the log queue
    int id;                 // ID of the log processor
    char *name;             // Name of the log processor
    struct log_queue *queue;// Log message queue for this log processor
};

// Define the log queue structure
struct log_queue {
    pthread_mutex_t lock;   // Lock for synchronizing access to the log queue
    int id;                 // ID of the log queue
    struct log_message *head; // Head of the log message queue
    struct log_message *tail; // Tail of the log message queue
};

// Define the log system structure
struct log_system {
    pthread_mutex_t lock;   // Lock for synchronizing access to the log system
    int id;                 // ID of the log system
    struct log_processor *processors; // Array of log processors
    int num_processors;     // Number of log processors in the array
};

// Define the log message processing function
void process_log_message(struct log_system *sys, struct log_message *msg) {
    // Acquire the lock for the log queue associated with this log processor
    pthread_mutex_lock(&sys->processors[msg->id % sys->num_processors].queue->lock);

    // Append the log message to the end of the log queue
    msg->next = NULL;
    if (sys->processors[msg->id % sys->num_processors].queue->tail == NULL) {
        sys->processors[msg->id % sys->num_processors].queue->head = msg;
    } else {
        sys->processors[msg->id % sys->num_processors].queue->tail->next = msg;
    }
    sys->processors[msg->id % sys->num_processors].queue->tail = msg;

    // Release the lock for the log queue associated with this log processor
    pthread_mutex_unlock(&sys->processors[msg->id % sys->num_processors].queue->lock);
}

// Define the log message processing thread function
void *log_processor(void *arg) {
    struct log_system *sys = (struct log_system *)arg;

    // Loop indefinitely, processing log messages from the log queue
    while (1) {
        // Acquire the lock for the log queue associated with this log processor
        pthread_mutex_lock(&sys->processors[sys->id % sys->num_processors].queue->lock);

        // Check if there are any log messages in the log queue
        struct log_message *msg = sys->processors[sys->id % sys->num_processors].queue->head;
        if (msg == NULL) {
            // Release the lock for the log queue associated with this log processor
            pthread_mutex_unlock(&sys->processors[sys->id % sys->num_processors].queue->lock);

            // Sleep for a short period of time before checking the log queue again
            sleep(1);

            continue;
        }

        // Process the log message
        process_log_message(sys, msg);

        // Remove the log message from the log queue
        sys->processors[sys->id % sys->num_processors].queue->head = msg->next;
        if (msg == sys->processors[sys->id % sys->num_processors].queue->tail) {
            sys->processors[sys->id % sys->num_processors].queue->tail = NULL;
        }

        // Release the lock for the log queue associated with this log processor
        pthread_mutex_unlock(&sys->processors[sys->id % sys->num_processors].queue->lock);
    }

    return NULL;
}

// Initialize the log system
int log_system_init(struct log_system *sys, int num_processors) {
    // Allocate memory for the log processors array
    sys->processors = (struct log_processor *)malloc(num_processors * sizeof(struct log_processor));

    // Initialize the log processors
    for (int i = 0; i < num_processors; i++) {
        sys->processors[i].id = i;
        sys->processors[i].name = "log processor";
        sys->processors[i].queue = (struct log_queue *)malloc(sizeof(struct log_queue));
        sys->processors[i].queue->head = NULL;
        sys->processors[i].queue->tail = NULL;
    }

    // Initialize the log system lock
    pthread_mutex_init(&sys->lock, NULL);

    return 0;
}

// Add a log message to the log system
int log_system_add(struct log_system *sys, struct log_message *msg) {
    // Acquire the lock for the log system
    pthread_mutex_lock(&sys->lock);

    // Process the log message using the appropriate log processor
    process_log_message(sys, msg);

    // Release the lock for the log system
    pthread_mutex_unlock(&sys->lock);
}

// Shut down the log system
int log_system_shutdown(struct log_system *sys) {
    // Acquire the lock for the log system
    pthread_mutex_lock(&sys->lock);

    // Release all resources associated with the log system
    free(sys->processors);
    sys->processors = NULL;
    pthread_mutex_destroy(&sys->lock);

    return 0;
}
```
