        keys[i] = i;
        i++;
    }

    // Allocate memory for the array of records
    Record *records = malloc(max_records * sizeof(Record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        printf("Error allocating memory for records\n");
        return;
    }

    // Initialize the records with random values within specified ranges
    srand(time(NULL));
    i = 0;
    while (i < max_records) {
        records[i].offset = rand() % max_offset;
        records[i].key = keys[i];
        records[i].attribute = ((double) rand()) / RAND_MAX * 2.0 - 1.0;
