    if ((offsets = (long **)malloc(size)) == NULL) {
        printf("Error: failed to allocate memory for offsets\n");
        free(records);
        return -1;
    }

    // allocate memory for the keys array
    size = sizeof(int) * num_keys;
    if ((keys = (int *)malloc(size)) == NULL) {
        printf("Error: failed to allocate memory for keys\n");
        free(records);
        free(offsets);
        return -1;
    }

    // initialize the offsets array with null pointers
    memset(offsets, 0, size);

    // generate unique keys for the records
    srand((unsigned int)time(NULL));
    for (i = 0; i < num_keys; ++i) {
        keys[i] = rand() % range_max + range_min;
    }

    // populate the records array with random integer values and pointers to corresponding offsets
    for (i = 0; i < num_keys; ++i) {
        int key = keys[i];
        long *offset = NULL;

        // allocate memory for the offset
        size = sizeof(long);
        if ((offset = (long *)malloc(size)) == NULL) {
