#define MIN_RANDOM_VALUE 0
#define MAX_RANDOM_VALUE 100
#define SEED_DEFAULT (time(NULL))
#define MAX_ATTEMPTS 5
#define CONCURRENCY_LEVEL 4
#define ALLOCATION_GRANULARITY 64
#define POOL_SIZE (1 << 20) // 1 MiB

// Data structures
typedef struct record {
    int key;
    int value;
} record_t;

typedef struct hash_table {
    int size;
    int capacity;
    int* keys;
    bool* used;
} hash_table_t;

// Function prototypes
void init_hash_table(hash_table_t* table);
bool is_key_used(const hash_table_t* table, const int key);
void mark_key_used(hash_table_t* table, const int key);
void* allocate_memory(size_t size);
void free_memory(void* memory);
void log_allocation_event(const char* event);
