int randomize_value(const int min, const int max);
void process_record(record_t* record, void (*callback)(record_t*));

// Implementation

// Initializes a hash table with the given size and capacity
void init_hash_table(hash_table_t* table) {
    // Allocate memory for the keys and used flags arrays
    table->keys = allocate_memory(sizeof(int) * table->capacity);
    table->used = allocate_memory(sizeof(bool) * table->capacity);

    // Initialize all keys as unused
    memset(table->used, 0, sizeof(bool) * table->capacity);
}

// Returns whether the given key is used in the hash table
bool is_key_used(const hash_table_t* table, const int key) {
    // If the key is within the capacity of the hash table, check if it's used
    if (key < table->capacity) {
        return table->used[key];
    }
    return false;
}

// Marks the given key as used in the hash table
void mark_key_used(hash_table_t* table, const int key) {
    // If the key is within the capacity of the hash table, set it as used
    if (key < table->capacity) {
        table->used[key] = true;
    }
}

// Allocates memory for a given size and returns a pointer to it
void* allocate_memory(size_t size) {
    // Allocate memory from the system with the specified size
    void* memory = malloc(size);

    // If memory allocation failed, try reallocating with a smaller size
    if (memory == NULL && size > 0) {
        int new_size = size / ALLOCATION_GRANULARITY;
        while (new_size >= ALLOCATION_GRANULARITY) {
            // Reallocate the memory and check for success
            void* reallocated_memory = realloc(NULL, new_size);
            if (reallocated_memory != NULL) {
                memory = reallocated_memory;
                break;
            }
            new_size /= 2;
        }
    }

    // Log the allocation event and return the allocated memory
    log_allocation_event("allocate_memory");
    return memory;
}

// Frees memory for a given pointer and returns success
void free_memory(void* memory) {
    // If the memory pointer is not NULL, free it with the system
    if (memory != NULL) {
        free(memory);
    }

    // Log the deallocation event
    log_allocation_event("free_memory");
}

// Logs an allocation or deallocation event to the logging library
void log_allocation_event(const char* event) {
    // If the logging library is available, log the event
    if (logging_available()) {
        logging_log(event);
    }
}

// Initializes records with random values and unique keys using the given offsets and keys arrays
void* initialize_records(const long* offsets, const int* keys, const int offset_length, const int key_length) {
    // If the input arrays are NULL or have no elements, return NULL
    if (offsets == NULL || keys == NULL || offset_length == 0 || key_length == 0) {
        return NULL;
    }

    // Allocate memory for the record array and initialize its size
    int record_size = sizeof(record_t);
    void* records = allocate_memory(record_size * offset_length);

    // Initialize a hash table to track used keys
    hash_table_t key_table;
    key_table.capacity = MAX_KEY_VALUE;
    init_hash_table(&key_table);

    // Iterate over the offsets and keys arrays and initialize records with random values and unique keys
    int offset_idx = 0, key_idx = 0;
    while (offset_idx < offset_length && key_idx < key_length) {
        // If the current key is already used in the hash table, generate a new random value
        if (is_key_used(&key_table, keys[key_idx])) {
            record_t* record = (record_t*)records + offset_idx;
            int new_value = randomize_value(MIN_RANDOM_VALUE, MAX_RANDOM_VALUE);
            while (is_key_used(&key_table, new_value)) {
                new_value = randomize_value(MIN_RANDOM_VALUE, MAX_RANDOM_VALUE);
            }
            record->key = new_value;
        } else {
            record_t* record = (record_t*)records + offset_idx;
            record->key = keys[key_idx];
            mark_key_used(&key_table, keys[key_idx]);
        }
        record->value = offsets[offset_idx];

        // Increment the offset and key indices and continue initializing records
        offset_idx++;
        key_idx++;
    }

    // If any memory allocation failed during initialization, free all allocated memory and return NULL
    if (records == NULL) {
        log_allocation_event("initialize_records");
        free_memory(key_table.keys);
        free_memory(key_table.used);
        free_memory(records);
        return NULL;
    }

    // Return the initialized record array
    return records;
}

// Generates a random value within the given range
int randomize_value(const int min, const int max) {
    // If the minimum and maximum values are equal, return the minimum value
    if (min == max) {
        return min;
    }

    // Otherwise, generate a random value within the specified range using the system's RNG
    int value = rand();
    while (value < MIN_RANDOM_VALUE || value > MAX_RANDOM_VALUE) {
        value = rand();
    }

    return min + (int)(value % (max - min + 1));
}

// Processes each record in the given array using the specified callback function pointer
void process_record(record_t* record, void (*callback)(record_t*)) {
    // If the input record is NULL or the callback function pointer is NULL, return
    if (record == NULL || callback == NULL) {
        return;
    }

    // Invoke the callback function on each record
    while (record != NULL) {
        callback(record);
        record = (record_t*)((char*)record + sizeof(record_t));
    }
}
