    if (num_messages > 0) {
        buffer = malloc(sizeof(char*) * num_messages);
        if (!buffer) {
            fprintf(stderr, "Error allocating memory for log messages: %s\n", strerror(errno));
            return NULL;
        }
    }
    return buffer;
}

// Function to allocate memory for an array of log levels
