    void *buffer = NULL;
    if (num_messages > 0) {
        buffer = malloc(sizeof(log_entry_t) * num_messages);
        if (!buffer) {
            fprintf(stderr, "Error allocating memory for log entries: %s\n", strerror(errno));
            return NULL;
        }
    }
    return buffer;
}

// Function to initialize an array of log messages
