        // Generate a random log level (1 - critical, 2 - error, 3 - warning, etc.)
        levels[i] = generate_random_level();
    }
}

// Function to initialize an array of log entries
void init_log_entries(log_entry_t *entries, int num_messages) {
    for (int i = 0; i < num_messages; i++) {
        // Get the current system time and generate a random log message within the specified length range
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char *message = generate_random_message();
        int level = generate_random_level();

        // Initialize the log entry with the timestamp and message/level
        entries[i].timestamp = ts.tv_sec;
        entries[i].message = message;
        entries[i].level = level;
    }
}

// Function to free memory allocated for an array of log messages
void free_log_messages(char **messages, int num_messages) {
    if (messages != NULL) {
        for (int i = 0; i < num_messages; i++) {
            free(messages[i]);
        }
        free(messages);
    }
}

