void free_log_levels(int *levels, int num_messages) {
    if (levels != NULL) {
        free(levels);
    }
}

// Function to free memory allocated for an array of log entries
void free_log_entries(log_entry_t *entries, int num_messages) {
    if (entries != NULL) {
        for (int i = 0; i < num_messages; i++) {
            free(entries[i].message);
        }
        free(entries);
    }
}

// Function to generate a random log message within the specified length range
char *generate_random_message() {
    // Generate a random number between 10 and 50 characters
    int len = rand() % 40 + 10;

    // Allocate memory for the log message
    char *message = malloc(len);
    if (!message) {
        fprintf(stderr, "Error allocating memory for log message: %s\n", strerror(errno));
        return NULL;
    }

    // Generate a random string within the specified length range
    for (int i = 0; i < len - 1; i++) {
        message[i] = 'a' + rand() % 26;
    }
    message[len - 1] = '\0';

    return message;
}

// Function to generate a random log level (1 - critical, 2 - error, 3 - warning, etc.)
int generate_random_level() {
    // Generate a random number between 1 and 5 for the log level
    int level = rand() % 5 + 1;

    return level;
}

// Function to handle concurrent memory allocation and initialization
void *handle_concurrent_memory_allocation(int num_messages) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    void *buffer = allocate_log_entries(num_messages);

    if (buffer == NULL) {
        fprintf(stderr, "Error allocating memory for log entries: %s\n", strerror(errno));
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    init_log_entries(buffer, num_messages);
    pthread_mutex_unlock(&mutex);

    return buffer;
}
