    pthread_mutex_lock(&logLock);
    // Add the new log entry to the end of the list
    LogEntry** current = &head;
    while (*current != NULL) {
        current = &(*current)->next;
    }
    *current = entry;
    pthread_mutex_unlock(&logLock);
}

// Function to acquire the lock and retrieve a log entry from the list
LogEntry* getLogEntry(int index) {
    pthread_mutex_lock(&logLock);
    // Find the log entry at the given index
    LogEntry** current = &head;
    for (int i = 0; i < index; i++) {
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&logLock);
    return *current;
}
