#include <stdlib.h>
#include <string.h>

struct LogEntry {
    int timestamp;
    int level;
    char* message;
};

// Linked list of log entries
LogEntry* head = NULL;

// Function to append a new log entry to the list
void appendLogEntry(LogEntry* entry) {
    // Create a new node for the log entry
    LogEntryNode* node = (LogEntryNode*) malloc(sizeof(LogEntryNode));
    node->entry = entry;
    node->next = NULL;

    // Add the new node to the end of the list
    if (head == NULL) {
        head = node;
    } else {
        LogEntryNode* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

// Function to traverse the log entries in reverse order
void traverseLogEntries(void (*callback)(LogEntry*)) {
    // Start with the tail of the list and move backwards
    LogEntryNode* current = head;
    while (current != NULL) {
        callback(current->entry);
        current = current->next;
    }
}
