// Define a custom data structure to hold a 'double' value and a pointer to a dynamically allocated string
typedef struct {
    double val;
    char *str;
} DataStruct;

// Define a logging mechanism to track memory allocation and deallocation events
#define LOG_FILE "memory_log.txt"
void log_event(const char* event, const int size) {
    FILE* fp = fopen(LOG_FILE, "a");
    if (fp == NULL) return;
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(fp, "%s [%d-%02d-%02d %02d:%02d:%02d] %s: %d bytes\n", event, 1900+tm->tm_year, tm->tm_mon+1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, event, size);
    fclose(fp);
}

// Define a function to initialize the custom data structure with randomly generated double values within a specified range and pointers to strings created using `malloc` and initialized with random alphanumeric characters
DataStruct* init_data_struct(double min_val, double max_val) {
    // Generate a random double value within the specified range
    double val = (double)rand() / RAND_MAX * (max_val - min_val) + min_val;

    // Create a dynamically allocated string of length 10 using `malloc` and initialize with random alphanumeric characters
    char* str = malloc(10);
    for (int i=0; i<10; i++) {
        int rand_char = rand() % ('Z' - 'A') + 'A';
        if (rand_char < 'a') rand_char += 'a' - 'A';
        str[i] = rand_char;
    }

    // Create a new instance of the custom data structure and initialize its fields
    DataStruct* ds = malloc(sizeof(DataStruct));
    ds->val = val;
    ds->str = str;

    return ds;
}

// Define a function to manage memory allocation for an array of custom data structures, handling potential errors gracefully and ensuring efficient resource management
void* manage_memory(int size) {
    // Allocate memory for the array of custom data structures using `malloc`
    void* mem = malloc(size * sizeof(DataStruct));

    // Check if allocation was successful
    if (mem == NULL) {
        printf("Out of memory!\n");
        return NULL;
    }

    // Initialize each element in the array with a new instance of the custom data structure using `init_data_struct`
    for (int i=0; i<size; i++) {
        DataStruct* ds = init_data_struct(MIN_VAL, MAX_VAL);
        mem[i] = ds;
    }

    // Log the memory allocation event to the logging mechanism
    log_event("Memory allocated", size * sizeof(DataStruct));

    return mem;
}

// Define a function to deallocate resources, allowing for repeated allocations and deallocations while ensuring efficient resource management
void free_memory(void* mem) {
    // Check if the memory pointer is NULL before attempting to free it
    if (mem == NULL) return;

    // Cast the void* pointer back to a void** array of custom data structures and iterate over each element
    DataStruct** ds = (DataStruct**)mem;
    for (int i=0; i<size; i++) {
        // Free the string allocated in the `str` field using `free`
        free(ds[i]->str);

        // Free the structure itself using `free`
        free(ds[i]);
    }

    // Log the memory deallocation event to the logging mechanism
    log_event("Memory deallocated", size * sizeof(DataStruct));

    // Free the array of custom data structures using `free`
    free(mem);
}

// Define a function to monitor the current memory usage and identify potential bottlenecks, taking into account caching and copying behavior
size_t get_memory_usage() {
    FILE* fp = fopen("/proc/self/stat", "r");
    if (fp == NULL) return 0;

    // Skip the first line of the file, which contains information about the process
    char buf[256];
    fgets(buf, sizeof(buf), fp);

    // Read the second line of the file, which contains information about the virtual memory usage
    fgets(buf, sizeof(buf), fp);
    int rss = atoi(strtok(buf, " "));

    return (size_t)rss;
}
