const int CHUNK_SIZE = 1024 * 16; // 16 KB chunk size

// Function to manage and populate an array of record structures
Record* initRecords(int N, int minKey, int maxKey, float minLatency, float maxLatency) {
    if (N <= 0) {
        return NULL;
    }

    // Allocate memory pool for records
    Record* records = malloc(POOL_SIZE);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        return NULL;
    }

    // Initialize record array
    for (int i = 0; i < N; ++i) {
        records[i].offset = i * CHUNK_SIZE;
        records[i].key = minKey + rand() % (maxKey - minKey);
        records[i].value = minLatency + ((float)rand()) / RAND_MAX * (maxLatency - minLatency);
    }

    // Dynamically resize record array if necessary
    if (N > POOL_SIZE / CHUNK_SIZE) {
        int newPoolSize = N * CHUNK_SIZE;
        Record* newRecords = realloc(records, newPoolSize);
        if (!newRecords) {
            fprintf(stderr, "Failed to resize memory pool\n");
            free(records);
            return NULL;
        }
        records = newRecords;
    }

    // Log allocation sizes and reallocation events
    printf("Allocated %d bytes for record array\n", POOL_SIZE);
    if (N > POOL_SIZE / CHUNK_SIZE) {
        printf("Realized size of record array is %d MB\n", newPoolSize / 1024 / 1024);
    }

    return records;
}

// Function to handle edge cases and return appropriate status codes or messages
