#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the struct for the Node
typedef struct Node {
    char* key;
    double value;
} Node;

// Define the struct for the Record
typedef struct Record {
    char* key;
    Node* node;
} Record;

// Define the custom allocator
void* my_alloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Failed to allocate memory!\n");
        return NULL;
    }
    return ptr;
}

// Define the function for dynamic array management
void manageArray(Node** arr, size_t maxSize, size_t* curSize, size_t* curIndex) {
    // Check if the current index is out of bounds
    if (*curIndex >= *curSize) {
        // If so, resize the array
        *arr = realloc(*arr, (maxSize + 1) * sizeof(Node));
        if (*arr == NULL) {
            printf("Failed to resize array!\n");
            return;
        }
        // Update the current size and index
        *curSize += 1;
        *curIndex = *curSize - 1;
    }
}

// Define the function for dynamic linked list management
void manageLinkedList(Record** head, size_t maxSize, size_t* curSize) {
    // Check if the current size is out of bounds
    if (*curSize >= maxSize) {
        // If so, resize the linked list
        *head = realloc(*head, (maxSize + 1) * sizeof(Record));
        if (*head == NULL) {
            printf("Failed to resize linked list!\n");
            return;
        }
    }
}

// Define the function for inserting a new node into the array
void insertNode(Node** arr, size_t maxSize, size_t* curSize, size_t* curIndex, char* key, double value) {
    // Manage the array
    manageArray(arr, maxSize, curSize, curIndex);

    // Insert the new node
    Node* newNode = my_alloc(sizeof(Node));
    newNode->key = strdup(key);
    newNode->value = value;
    arr[*curIndex] = newNode;

    // Update the current index
    *curIndex += 1;
}

// Define the function for deleting a node from the array
void deleteNode(Node** arr, size_t maxSize, size_t* curSize, size_t* curIndex) {
    // Check if the current index is in bounds
    if (*curIndex < *curSize) {
        // If so, free the node at the current index
        Node* node = arr[*curIndex];
        my_free(node);

        // Shift the remaining nodes to the left
        for (size_t i = *curIndex; i < maxSize - 1; ++i) {
            arr[i] = arr[i + 1];
        }

        // Update the current size and index
        *curSize -= 1;
        *curIndex -= 1;
    }
}

// Define the function for inserting a new record into the linked list
void insertRecord(Record** head, size_t maxSize, size_t* curSize) {
    // Manage the linked list
    manageLinkedList(head, maxSize, curSize);

    // Insert the new record
    Record* newRecord = my_alloc(sizeof(Record));
    newRecord->key = strdup("");
    newRecord->node = NULL;
    head[*curSize] = newRecord;

    // Update the current size
    *curSize += 1;
}

// Define the function for deleting a record from the linked list
void deleteRecord(Record** head, size_t maxSize, size_t* curSize) {
    // Check if the current size is in bounds
    if (*curSize > 0) {
        // If so, free the first record in the list
        Record* record = head[0];
        my_free(record);

        // Shift the remaining records to the left
        for (size_t i = 0; i < maxSize - 1; ++i) {
            head[i] = head[i + 1];
        }

        // Update the current size
        *curSize -= 1;
    }
}

// Define the function for resizing the array and linked list based on configuration parameters
void resize(Node** arr, Record** head, size_t maxSize, size_t* curSize) {
    // Check if the current size is out of bounds
    if (*curSize >= maxSize) {
        // If so, resize both the array and linked list
        *arr = realloc(*arr, (maxSize + 1) * sizeof(Node));
        if (*arr == NULL) {
            printf("Failed to resize array!\n");
            return;
        }

        *head = realloc(*head, (maxSize + 1) * sizeof(Record));
        if (*head == NULL) {
            printf("Failed to resize linked list!\n");
            return;
        }
    }
}
