        Record record = recordMap.get(station);
        if (record == null) {
            return "Unknown";
        }

        double temperature = node.value;
        double humidity = record.value;

        // Compose the string summary of the current weather conditions
        StringBuilder builder = new StringBuilder();
        builder.append("Temperature: ");
        builder.append(temperature);
        builder.append("°C, Humidity: ");
        builder.append(humidity);
        builder.append("%");

        return builder.toString();
    }
}
