    size_t allocatedSize; // Size of the allocated memory block
    size_t poolSize; // Size of the memory pool
    size_t usedSize; // Used size of the memory pool
    int numRecords; // Number of records in the pool
    Record *records[]; // Array of records in the pool
};

// Define the LRU eviction policy
struct LRUEviction {
    int head; // Index of the most recently used record
    int tail; // Index of the least recently used record
    int *accesses; // Access times for each record
    int *usage; // Usage counts for each record
};

// Function to initialize the memory pool allocator
void initMemoryPoolAllocator(struct MemoryPoolAllocator *allocator, size_t poolSize) {
    allocator->poolSize = poolSize;
    allocator->usedSize = 0;
    allocator->numRecords = 0;
}

// Function to allocate a new record in the memory pool
Record *allocateRecord(struct MemoryPoolAllocator *allocator) {
    if (allocator->usedSize == allocator->poolSize) {
        // Reallocate the memory pool if it is full
        size_t newSize = allocator->poolSize * 2;
        void *newMemory = mmap(NULL, newSize, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
        if (newMemory == NULL) {
            // Return NULL if memory allocation fails
            return NULL;
        }
        allocator->records = newMemory;
        allocator->poolSize = newSize;
    }
    // Allocate a new record in the memory pool
    Record *record = &allocator->records[allocator->numRecords++];
    allocator->usedSize += sizeof(Record);
    return record;
}

// Function to free a record in the memory pool
void freeRecord(struct MemoryPoolAllocator *allocator, Record *record) {
    if (record == NULL) {
        // Do nothing if the record is already freed
        return;
    }
    allocator->usedSize -= sizeof(Record);
}

// Function to populate an array of records with random values
