using namespace std;

const string kubeconfig_path = "/path/to/kubeconfig";
const string manifests_directory = "/path/to/manifests";
const int max_retries = 3;
const long retry_timeout = 5000; // in milliseconds
const long log_interval = 10000; // in milliseconds

vector<string> get_manifests() {
  vector<string> manifests;

  DIR *dir = opendir(manifests_directory.c_str());
  if (dir == NULL) {
    cerr << "Error opening manifests directory: " << manifests_directory << endl;
    return manifests;
  }

  struct dirent *entry;
  while ((entry = readdir(dir)) != NULL) {
    string filename = entry->d_name;
    if (filename.find(".yaml") != string::npos || filename.find(".yml") != string::npos) {
      manifests.push_back(manifests_directory + "/" + filename);
    }
  }

  closedir(dir);

  return manifests;
}

int deploy_manifests(vector<string> manifests) {
  for (const string& manifest : manifests) {
    if (!apply_manifest(manifest)) {
      return 0;
    }
  }

  return 1;
}

bool apply_manifest(const string& manifest) {
  vector<string> args = {"kubectl", "apply", "-f", manifest};

  pid_t child = fork();

  if (child == 0) { // child process
    execvp(args[0].c_str(), &args[0]);
    exit(1);
  } else if (child > 0) { // parent process
    int status;
    waitpid(child, &status, 0);
    return WIFEXITED(status) && WEXITSTATUS(status) == 0;
  }
}

void handle_signal(int signal) {
  cerr << "Received signal: " << signal << endl;
  exit(1);
}

int main() {
  vector<string> manifests = get_manifests();
  if (manifests.empty()) {
    cerr << "No manifests found in directory: " << manifests_directory << endl;
    return 0;
  }

  signal(SIGINT, handle_signal);
  signal(SIGTERM, handle_signal);

  int retries = max_retries;
  while (retries > 0) {
    if (!deploy_manifests(manifests)) {
      cerr << "Error deploying manifests. Retrying..." << endl;
      retries--;
    } else {
      break;
    }

    usleep(retry_timeout * 1000); // convert milliseconds to microseconds
  }

  if (retries == 0) {
    cerr << "Error deploying manifests after " << max_retries << " retries. Exiting." << endl;
    return 0;
  }

  cout << "Deployed manifests successfully" << endl;

  return 1;
}
```
