    // Validate input using custom validation function
    if (size <= 0) {
        printf("Invalid input\n");
        exit(1);
    }

    // Sort the array of records using a stable sorting algorithm
    qsort(records, size, sizeof(Record), compareRecords);
}

// Comparison function for sorting the array of records based on their values
int compareRecords(const void *a, const void *b) {
    // Cast the arguments to the appropriate data type
    Record *r1 = (Record *)a;
    Record *r2 = (Record *)b;

    // Compare the values of the two records
    if (r1->value < r2->value) {
        return -1;
    } else if (r1->value > r2->value) {
        return 1;
    } else {
        return 0;
    }
}

int main() {
