    int size;
    printf("Enter the number of records to sort: ");
    scanf("%d", &size);

    // Allocate memory for the array of records
    Record *records = (Record *)malloc(sizeof(Record) * size);

    // Initialize the value field of each record with a random integer between 1 and 100
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % 100 + 1;
    }

    // Sort the array of records based on their values using a stable sorting algorithm
    sortRecords(records, size);

    // Print the sorted values of the records
    printf("Sorted values: ");
    for (int i = 0; i < size; i++) {
        printf("%d ", records[i].value);
    }
    printf("\n");

    // Free memory for the array of records
    free(records);

    return 0;
}
