} Resource;

// Define constants for resource management
const int MAX_RESOURCES = 100; // maximum number of resources allowed
const int RESOURCE_LIMIT = 50; // maximum number of active resources at any given time
const int MIN_PRIORITY = 1; // minimum priority level (inclusive)
const int MAX_PRIORITY = 3; // maximum priority level (exclusive)
const double RANDOM_VALUE_MIN = 0.0; // minimum value for randomly generated values
const double RANDOM_VALUE_MAX = 100.0; // maximum value for randomly generated values

// Define the pool of resources and its mutex
Resource *resources[MAX_RESOURCES];
pthread_mutex_t resourcePoolMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate memory for an array of custom data structures
void initResources(int numResources) {
    // Check that the number of resources is valid and initialize the pool
    if (numResources > 0 && numResources <= MAX_RESOURCES) {
        for (int i = 0; i < numResources; i++) {
            Resource *resource = malloc(sizeof(Resource));
            resource->timestamp = 0;
            resource->value = RANDOM_VALUE_MIN + ((RANDOM_VALUE_MAX - RANDOM_VALUE_MIN) * (double)rand() / (double)RAND_MAX);
            resource->resource = NULL; // set the pointer to NULL for now
            resources[i] = resource;
        }
    } else {
        printf("Invalid number of resources: %d\n", numResources);
    }
}

// Function to release memory used by an array of custom data structures
void freeResources(int numResources) {
    // Check that the number of resources is valid and release the pool
    if (numResources > 0 && numResources <= MAX_RESOURCES) {
        for (int i = 0; i < numResources; i++) {
            free(resources[i]);
            resources[i] = NULL;
        }
    } else {
        printf("Invalid number of resources: %d\n", numResources);
    }
}

// Function to allocate a resource from the pool
void *allocateResource(int taskID, int priority) {
    // Check that the task ID and priority are valid
    if (taskID < 0 || taskID >= MAX_RESOURCES || priority < MIN_PRIORITY || priority > MAX_PRIORITY) {
        printf("Invalid task ID or priority: %d, %d\n", taskID, priority);
        return NULL;
    }

    // Lock the resource pool mutex to prevent concurrent access
    pthread_mutex_lock(&resourcePoolMutex);

    // Find a suitable resource from the pool that is not currently in use
    int i = 0;
    while (i < MAX_RESOURCES) {
        if (resources[i] != NULL && resources[i]->taskID == taskID && resources[i]->priority == priority) {
            // If a suitable resource is found, return it and unlock the mutex
            void *resource = resources[i];
            resources[i] = NULL;
            pthread_mutex_unlock(&resourcePoolMutex);
            return resource;
        } else {
            i++;
        }
    }

    // If no suitable resource is found, log a warning and unlock the mutex
    printf("Warning: No available resources for task ID %d and priority %d\n", taskID, priority);
    pthread_mutex_unlock(&resourcePoolMutex);
    return NULL;
}

// Function to release a resource back to the pool
void releaseResource(int taskID, int priority, void *resource) {
    // Check that the task ID and priority are valid and that the resource is not NULL
    if (taskID < 0 || taskID >= MAX_RESOURCES || priority < MIN_PRIORITY || priority > MAX_PRIORITY || resource == NULL) {
        printf("Invalid task ID or priority: %d, %d\n", taskID, priority);
        return;
    }

    // Lock the resource pool mutex to prevent concurrent access
    pthread_mutex_lock(&resourcePoolMutex);

    // Find the index of the resource in the pool and update its timestamp and value
    int i = 0;
    while (i < MAX_RESOURCES) {
        if (resources[i] != NULL && resources[i]->taskID == taskID && resources[i]->priority == priority) {
            Resource *res = resources[i];
            res->timestamp = 0;
            res->value = RANDOM_VALUE_MIN + ((RANDOM_VALUE_MAX - RANDOM_VALUE_MIN) * (double)rand() / (double)RAND_MAX);
            pthread_mutex_unlock(&resourcePoolMutex);
            return;
        } else {
            i++;
        }
    }

    // If the resource is not found, log a warning and unlock the mutex
    printf("Warning: Resource for task ID %d and priority %d not found\n", taskID, priority);
    pthread_mutex_unlock(&resourcePoolMutex);
}
