        crc_indication_array[i].rnti = rnti;
        crc_indication_array[i].crc_indication.tag = CRC_INDICATION_REL8_TAG;
        crc_indication_array[i].crc_indication.crci = calculate_crc_indication(current_element, crc_indication_accuracy_threshold);
    }

    // Return the populated array of NFAPI_CRC_INDICATION_PDU structures
    return crc_indication_array;
}

// Define the function to calculate the CRC indication value based on the specified accuracy threshold
uint8_t calculate_crc_indication(json_object* current_element, uint8_t crc_indication_accuracy_threshold) {
    // Get the current CRC block from the JSON object
    json_object* crc_block = json_object_dotget_object(current_element, "crc.block");

    // Extract the CRC value and accuracy from the CRC block
    uint32_t crc_value;
    char* crc_accuracy_str = json_object_dotget_string(crc_block, "accuracy");
    sscanf(crc_accuracy_str, "%u", &crc_value);

    // Calculate the CRC indication based on the specified accuracy threshold
    uint8_t crc_indication = (uint8_t)(crc_value >= crc_indication_accuracy_threshold ? 1 : 0);

    // Return the calculated CRC indication value
    return crc_indication;
}
