    // Increase the size of the message list by one if necessary
    if (num_messages >= messages->max_num_messages) {
        int new_size = messages->max_num_messages * 2;
        NFAPI_MESSAGE_T* new_messages = realloc(messages, sizeof(NFAPI_MESSAGE_T) * new_size);
        if (new_messages == NULL) {
            return -1;
        }
        messages = new_messages;
        messages->max_num_messages = new_size;
    }

