// Define a structure to represent a record
typedef struct {
    long offset;
    int key;
    record value;
} record_t;

// Define a memory pool with a fixed-size block allocation scheme
typedef struct {
    size_t capacity; // total number of blocks in the pool
    size_t size; // current number of used blocks in the pool
    record_t* blocks; // array of record blocks
} mempool_t;

// Define a mutex to protect concurrent access to the memory pool
pthread_mutex_t mempool_lock = PTHREAD_MUTEX_INITIALIZER;

// Define a function to allocate a new block in the memory pool
static void* mempool_alloc(size_t size) {
    // Lock the mutex before allocating a new block
    pthread_mutex_lock(&mempool_lock);

    // Allocate a new block from the memory pool
    record_t* block = (record_t*)malloc(sizeof(record_t));
    if (!block) {
        printf("Failed to allocate memory for new block\n");
        pthread_mutex_unlock(&mempool_lock);
        return NULL;
    }

    // Initialize the fields of the new block
    block->offset = 0;
    block->key = 0;
    memset(&block->value, 0, sizeof(record_t));

    // Increment the size of the memory pool and return a pointer to the new block
    mempool.size++;
    pthread_mutex_unlock(&mempool_lock);
    return block;
}

// Define a function to free a block in the memory pool
static void mempool_free(record_t* block) {
    // Lock the mutex before freeing the block
    pthread_mutex_lock(&mempool_lock);

    // Free the block from the memory pool and decrement the size of the pool
    free(block);
    mempool.size--;

    // Unlock the mutex after freeing the block
    pthread_mutex_unlock(&mempool_lock);
}

// Define a function to insert a new record into the memory pool
static void mempool_insert(record_t* record) {
    // Lock the mutex before inserting the record
    pthread_mutex_lock(&mempool_lock);

    // Allocate a new block from the memory pool if necessary
    if (mempool.size == mempool.capacity) {
        mempool_alloc(sizeof(record_t));
    }

    // Copy the record into the next available block in the memory pool
    memcpy(mempool.blocks[mempool.size], record, sizeof(record_t));
    mempool.size++;

    // Unlock the mutex after inserting the record
    pthread_mutex_unlock(&mempool_lock);
}

// Define a function to delete a record from the memory pool
static void mempool_delete(long offset) {
    // Lock the mutex before deleting the record
    pthread_mutex_lock(&mempool_lock);

    // Find the block containing the record with the given offset
    int i;
    for (i = 0; i < mempool.size; i++) {
        if (mempool.blocks[i]->offset == offset) {
            break;
        }
    }

    // If the record was found, free the block and decrement the size of the pool
    if (i < mempool.size) {
        mempool_free(mempool.blocks[i]);
        mempool.size--;
    } else {
        printf("Record with offset %ld not found\n", offset);
    }

    // Unlock the mutex after deleting the record
    pthread_mutex_unlock(&mempool_lock);
}

// Define a function to retrieve a record from the memory pool
static record_t* mempool_retrieve(long offset) {
    // Lock the mutex before retrieving the record
    pthread_mutex_lock(&mempool_lock);

    // Find the block containing the record with the given offset
    int i;
    for (i = 0; i < mempool.size; i++) {
        if (mempool.blocks[i]->offset == offset) {
            break;
        }
    }

    // If the record was found, return a pointer to it
    if (i < mempool.size) {
        pthread_mutex_unlock(&mempool_lock);
        return mempool.blocks[i];
    } else {
        printf("Record with offset %ld not found\n", offset);
        pthread_mutex_unlock(&mempool_lock);
        return NULL;
    }
}

// Define a function to sort the records in the memory pool
static void mempool_sort(int order) {
    // Lock the mutex before sorting the records
    pthread_mutex_lock(&mempool_lock);

    // Sort the records in the memory pool based on their integer values
    qsort(mempool.blocks, mempool.size, sizeof(record_t), compare_records);

    // Unlock the mutex after sorting the records
    pthread_mutex_unlock(&mempool_lock);
}

// Define a function to serialize the memory pool to a file
static void mempool_serialize(FILE* fp) {
    // Lock the mutex before serializing the memory pool
    pthread_mutex_lock(&mempool_lock);

    // Write the number of blocks in the memory pool to the file
    fwrite(&mempool.size, sizeof(int), 1, fp);

    // Write each block in the memory pool to the file
    for (int i = 0; i < mempool.size; i++) {
        fwrite(mempool.blocks[i], sizeof(record_t), 1, fp);
    }

    // Unlock the mutex after serializing the memory pool
    pthread_mutex_unlock(&mempool_lock);
}

// Define a function to deserialize the memory pool from a file
static void mempool_deserialize(FILE* fp) {
    // Lock the mutex before deserializing the memory pool
    pthread_mutex_lock(&mempool_lock);

    // Read the number of blocks in the memory pool from the file
    int size;
    fread(&size, sizeof(int), 1, fp);

    // Allocate a new memory pool with the correct capacity
    mempool.capacity = size;
    mempool.blocks = (record_t**)malloc(sizeof(record_t*) * size);

    // Read each block from the file and allocate a new block in the memory pool
    for (int i = 0; i < size; i++) {
        record_t* block = (record_t*)malloc(sizeof(record_t));
        fread(block, sizeof(record_t), 1, fp);
        mempool.blocks[i] = block;
    }

    // Increment the size of the memory pool to match the number of blocks read from the file
    mempool.size = size;

    // Unlock the mutex after deserializing the memory pool
    pthread_mutex_unlock(&mempool_lock);
}
