package main

import (
	"encoding/json"
	"fmt"
	"log"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"
)

const (
	defaultMaxConns      = 1000
	defaultConnectionTTL = time.Minute * 30
	defaultPort          = 8080
)

type Conn struct {
	IPAddress string `json:"ip_address"`
	Port      int    `json:"port"`
}

// TCPConnCache is a scalable cache for TCP connection metadata structures.
type TCPConnCache struct {
	mu     sync.Mutex
	conns  map[int]*Conn
	ttl    time.Duration
	maxCon int
}

func (c *TCPConnCache) get(id int) (*Conn, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	conn, ok := c.conns[id]
	return conn, ok
}

func (c *TCPConnCache) set(id int, conn *Conn) {
	c.mu.Lock()
	defer c.mu.Unlock()

	c.conns[id] = conn
}

func (c *TCPConnCache) delete(id int) {
	c.mu.Lock()
	defer c.mu.Unlock()

	delete(c.conns, id)
}

func (c *TCPConnCache) evict() {
	c.mu.Lock()
	defer c.mu.Unlock()

	for k, v := range c.conns {
		if time.Since(v.LastActivity) > c.ttl {
			delete(c.conns, k)
		}
	}
}

func (c *TCPConnCache) Len() int {
	c.mu.Lock()
	defer c.mu.Unlock()

	return len(c.conns)
}

func NewTCPConnCache(ttl time.Duration, maxCon int) *TCPConnCache {
	if ttl <= 0 {
		ttl = defaultConnectionTTL
	}
	if maxCon <= 0 {
		maxCon = defaultMaxConns
	}

	return &TCPConnCache{
		conns:  make(map[int]*Conn),
		ttl:    ttl,
		maxCon: maxCon,
	}
}

func (c *TCPConnCache) StartEvictor() {
	go func() {
		for {
			time.Sleep(time.Second)
			c.evict()
		}
	}()
}

// ConnID returns a unique identifier for the connection.
func (c *TCPConnCache) ConnID(conn *Conn) int {
	return conn.Port
}

// Add adds a new TCP connection to the cache.
func (c *TCPConnCache) Add(conn *Conn) {
	id := c.ConnID(conn)
	c.set(id, conn)
}

// Get gets a TCP connection from the cache by ID.
func (c *TCPConnCache) Get(id int) (*Conn, bool) {
	return c.get(id)
}

// Remove removes a TCP connection from the cache by ID.
func (c *TCPConnCache) Remove(id int) {
	c.delete(id)
}

// Len returns the number of connections in the cache.
func (c *TCPConnCache) Len() int {
	return c.Len()
}
```']

