    long *offset;
    int *key;
} record_t;

// Function to allocate and initialize the arrays of offsets and keys
record_t* allocate_records(int N, int M) {
    // Allocate memory for the arrays of offsets and keys
    long *offsets = malloc(N * sizeof(long));
    int *keys = malloc(M * sizeof(int));

    if (offsets == NULL || keys == NULL) {
        printf("Error: Failed to allocate memory\n");
        return NULL;
    }

    // Initialize the arrays of offsets and keys with random values within the range -1000000 to 1000000
    for (int i = 0; i < N; i++) {
        offsets[i] = rand() % 2000000 - 1000000;
    }
    for (int i = 0; i < M; i++) {
        keys[i] = i + 1;
    }

    // Allocate memory for the array of records
    record_t *records = malloc(N * sizeof(record_t));

    if (records == NULL) {
        printf("Error: Failed to allocate memory\n");
        return NULL;
    }

    // Initialize the pointers in each record structure with the corresponding elements from the arrays of offsets and keys
    for (int i = 0; i < N; i++) {
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
    }

    // Handle case where N is less than M by setting the remaining keys to zero
    if (N < M) {
        for (int i = N; i < M; i++) {
            keys[i] = 0;
        }
    }

    // Free memory allocated for arrays of offsets and keys when function exits
    free(offsets);
    free(keys);

    return records;
}
