    int key;
} KeyValuePair;

// Define the arrays to store the offset and key values
KeyValuePair *offsetArray = NULL;
KeyValuePair *keyArray = NULL;

// Define a semaphore to synchronize access to the arrays
sem_t sem;

// Initialize the arrays and semaphore
void init() {
    // Allocate memory for the offset and key arrays
    offsetArray = (KeyValuePair *)malloc(MAX_OFFSET_SIZE * sizeof(KeyValuePair));
    keyArray = (KeyValuePair *)malloc(MAX_KEY_SIZE * sizeof(KeyValuePair));

    // Initialize the semaphore to allow concurrent access
    sem_init(&sem, 0, 1);
}

// Add a new key-value pair to the arrays
void add(long offset, int key) {
    // Check if the input size is within the maximum limits
    if (offset > MAX_OFFSET_SIZE || key > MAX_KEY_SIZE) {
        printf("Invalid input size\n");
        return;
    }

    // Acquire the semaphore to synchronize access to the arrays
    sem_wait(&sem);

    // Add the new key-value pair to the offset and key arrays
    KeyValuePair *newOffset = (KeyValuePair *)malloc(sizeof(KeyValuePair));
    newOffset->offset = offset;
    newOffset->key = key;
    offsetArray[offset] = *newOffset;

    // Add the new key-value pair to the key array if it is not already present
    for (int i = 0; i < MAX_KEY_SIZE; i++) {
        if (keyArray[i].key == key) {
            // The key is already present in the key array, no need to add it again
            break;
        } else if (i == MAX_KEY_SIZE - 1) {
            // The key is not present in the key array and there is no space left for it, add it as a new element
            KeyValuePair *newKey = (KeyValuePair *)malloc(sizeof(KeyValuePair));
            newKey->key = key;
            newKey->offset = offset;
            keyArray[i] = *newKey;
        }
    }

    // Release the semaphore to allow other threads to access the arrays
    sem_post(&sem);
}

// Get a value from the offset array
long getOffset(int index) {
    long result = -1;

    // Acquire the semaphore to synchronize access to the arrays
    sem_wait(&sem);

    // Check if the index is within the bounds of the offset array
    if (index >= 0 && index < MAX_OFFSET_SIZE) {
        result = offsetArray[index].offset;
    }

    // Release the semaphore to allow other threads to access the arrays
    sem_post(&sem);

    return result;
}

// Get a value from the key array
int getKey(long offset) {
    int result = -1;

    // Acquire the semaphore to synchronize access to the arrays
    sem_wait(&sem);

    // Check if the offset is within the bounds of the offset array
    if (offset >= 0 && offset < MAX_OFFSET_SIZE) {
        for (int i = 0; i < MAX_KEY_SIZE; i++) {
            if (keyArray[i].offset == offset) {
                result = keyArray[i].key;
                break;
            }
        }
    }

    // Release the semaphore to allow other threads to access the arrays
    sem_post(&sem);

    return result;
}

// Clean up the arrays and semaphore
void cleanup() {
    if (offsetArray != NULL) {
        free(offsetArray);
    }

    if (keyArray != NULL) {
        free(keyArray);
    }

    // Destroy the semaphore to prevent resource leaks
    sem_destroy(&sem);
}
