// Define a custom memory pool for task management
class MemoryPool {
private:
    vector<Task*> tasks; // List of all tasks in the pool
    mutex mtx;           // Mutex to protect concurrent access to the pool
    condition_variable cv; // Condition variable to signal changes to the pool
public:
    MemoryPool() {}

    void addTask(const Task& task) {
        // Lock the mutex before modifying the pool
        lock_guard<mutex> lg(mtx);
        tasks.push_back(&task);
        cv.notify_all();
    }

    bool removeTask(int index) {
        // Lock the mutex before modifying the pool
        lock_guard<mutex> lg(mtx);
        if (index >= 0 && index < tasks.size()) {
            Task* task = tasks[index];
            tasks.erase(tasks.begin() + index);
            cv.notify_all();
            return true;
        } else {
            return false;
        }
    }

    vector<Task*> getTasks() const {
        // Lock the mutex before accessing the pool
        lock_guard<mutex> lg(mtx);
        return tasks;
    }
};

// Define a function to validate and add new tasks
bool addNewTask(const Task& task) {
    if (task.start >= task.end) {
        cerr << "Invalid start/end time for task \"" << task.name << "\"\n";
        return false;
    }
    // Add the new task to the memory pool
    MemoryPool::getInstance().addTask(task);
    return true;
}

// Define a function to sort tasks based on their end times
void sortTasks(vector<Task*>& tasks, bool ascending) {
    if (ascending) {
        // Use a stable sorting algorithm to sort the tasks by end time
        std::sort(tasks.begin(), tasks.end(), [](const Task* t1, const Task* t2) {
            return t1->end < t2->end;
        });
    } else {
        // Use a stable sorting algorithm to sort the tasks by end time in descending order
        std::sort(tasks.begin(), tasks.end(), [](const Task* t1, const Task* t2) {
            return t1->end > t2->end;
        });
    }
}

// Define a function to serialize tasks into a file
void serializeTasks(const vector<Task*>& tasks, const string& filename) {
