    ofs.write((char*)&numTasks, sizeof(int));
    // For each task, write its name and end time to the output file
    for (const Task* task : tasks) {
        string name = task->name;
        chrono::time_point<chrono::system_clock> end = task->end;
        ofs.write((char*)&name, sizeof(string));
        ofs.write((char*)&end, sizeof(chrono::time_point<chrono::system_clock>));
    }
}

