        exit(EXIT_FAILURE);
    }

    // Find the first event with an ID greater than or equal to the start ID
    struct Event* current = event_list;
    while (current->id < start) {
        if (current->id == 0) {
            // No events found, return early
            sem_post(sem);
            return NULL;
        }
        current++;
    }

    // Find the last event with an ID less than or equal to the end ID
    struct Event* previous = current;
    while (current->id <= end) {
        if (current->id == 0) {
            // No events found, return early
            sem_post(sem);
            return NULL;
        }
        previous = current;
        current++;
    }

    // Create a copy of the retrieved events
    struct Event* events = (struct Event*)mmap_alloc((previous - current + 1) * EVENT_SIZE);
    memcpy(events, current - previous, (previous - current + 1) * EVENT_SIZE);

    // Release the semaphore for synchronizing access to the events list
    if (sem_post(sem)) {
        perror("sem_post");
        exit(EXIT_FAILURE);
    }

    // Process each event in the retrieved range
    for (uint32_t i = 0; i < previous - current + 1; i++) {
        process_event(&events[i]);
    }

    return events;
