int allocateMemory(int numOffsets, int numKeys) {
    // Validate input values to prevent buffer overflows and ensure that the allocated memory does not exceed system limits
    if (numOffsets < 0 || numKeys < 0) {
        return -1;
    }

    long *offsets = NULL;
    int *keys = NULL;

    // Allocate memory for the arrays using malloc() and handle potential failure
    offsets = (long *)malloc(numOffsets * sizeof(long));
    if (!offsets) {
        goto cleanup;
    }
    keys = (int *)malloc(numKeys * sizeof(int));
    if (!keys) {
        goto cleanup;
    }

    // Initialize the arrays with random values within a specified range
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = rand() % 10000;
    }
    for (int i = 0; i < numKeys; i++) {
        keys[i] = rand() % 10000;
    }

    // Return the pointers to the allocated arrays
    return offsets, keys;

cleanup:
    free(offsets);
    free(keys);
    return NULL;
}

