    if (!records) {
        goto cleanup;
    }

    // Initialize the array with random values within a specified range
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 10000;
    }

    // Return the pointer to the allocated array
    return records;

cleanup:
    free(records);
    return NULL;
}

// Function to set the value of each record's int field to a random value within a specified range
void setRandomValues(record *records, int numRecords, int lowerBound, int upperBound) {
    // Validate input values to prevent buffer overflows and ensure that the allocated memory does not exceed system limits
    if (numRecords < 0 || lowerBound > upperBound) {
        return;
    }

    // Initialize a random number generator using time(NULL)
    srand(time(NULL));

    // Set the value of each record's int field to a random value within the specified range
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % (upperBound - lowerBound + 1) + lowerBound;
    }
}

// Function to sort an array of record structures based on their int values using a stable sorting algorithm
void sortRecords(record *records, int numRecords, bool ascending) {
    // Validate input value to prevent buffer overflows and ensure that the allocated memory does not exceed system limits
    if (numRecords < 0) {
        return;
    }

    // Define a comparison function for sorting records based on their int values
    bool compare(const record &a, const record &b) {
        if (ascending) {
            return a.value < b.value;
        } else {
            return a.value > b.value;
        }
    }

    // Sort the array of records using the comparison function and stable sorting algorithm
    std::stable_sort(records, records + numRecords, compare);
}

// Function to dynamically allocate memory for an array of record structures, periodically trimming the dataset to maintain memory efficiency
record *allocateRecordMemoryWithTrimming(int numRecords) {
    // Validate input value to prevent buffer overflows and ensure that the allocated memory does not exceed system limits
    if (numRecords < 0) {
        return NULL;
    }

    record *records = NULL;
    int trimmedSize = 0;

    // Allocate memory for the array using malloc() and handle potential failure
    records = (record *)malloc(numRecords * sizeof(record));
    if (!records) {
        goto cleanup;
    }

    // Initialize the array with random values within a specified range
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 10000;
    }

    // Periodically trim the dataset by removing the least significant records until successful allocation is achieved
    while (!records) {
        if (trimmedSize >= numRecords / 2) {
            break;
        }

        trimmedSize += 100;
        int newNumRecords = numRecords - trimmedSize;

        records = (record *)realloc(records, newNumRecords * sizeof(record));
    }

    // Return the pointer to the allocated array or NULL if allocation failed
    return records;

cleanup:
    free(records);
    return NULL;
}
