system_status_t initialize_system(size_t max_buffer_size, size_t segment_count,
                                  value_t value_range_min, value_t value_range_max) {
    // Validate input parameters
    if (max_buffer_size == 0 || segment_count == 0 ||
        max_buffer_size > INT_MAX || segment_count > INT_MAX) {
        return NULL;
    }

    // Allocate memory for offset, key, and record arrays
    size_t offset_size = sizeof(offset_t) * segment_count;
    size_t key_size = sizeof(key_t) * segment_count;
    size_t record_size = sizeof(record_t) * segment_count;
    offset_t *offset = malloc(offset_size);
    key_t *key = malloc(key_size);
    record_t *record = malloc(record_size);
    if (offset == NULL || key == NULL || record == NULL) {
        free(offset);
        free(key);
        free(record);
        return NULL;
    }

    // Initialize offset, key, and record arrays
    for (size_t i = 0; i < segment_count; ++i) {
        offset[i] = 0;
        key[i] = 0;
        record[i].value = random() % (value_range_max - value_range_min + 1) + value_range_min;
    }

    // Allocate memory for raw data buffer
    size_t buffer_size = sizeof(char) * max_buffer_size;
    char *buffer = malloc(buffer_size);
    if (buffer == NULL) {
        free(offset);
        free(key);
        free(record);
        return NULL;
    }

    // Allocate memory for segment list
    size_t segment_list_size = sizeof(offset_t *) * segment_count;
    offset_t **segment_list = malloc(segment_list_size);
    if (segment_list == NULL) {
        free(buffer);
        free(offset);
        free(key);
        free(record);
        return NULL;
    }

    // Initialize segment list
    for (size_t i = 0; i < segment_count; ++i) {
        segment_list[i] = offset + i;
    }

    // Allocate memory for key list
    size_t key_list_size = sizeof(key_t *) * segment_count;
    key_t **key_list = malloc(key_list_size);
    if (key_list == NULL) {
        free(segment_list);
        free(buffer);
        free(offset);
        free(key);
        free(record);
        return NULL;
    }

    // Initialize key list
    for (size_t i = 0; i < segment_count; ++i) {
        key_list[i] = key + i;
    }

    // Allocate memory for record list
    size_t record_list_size = sizeof(record_t *) * segment_count;
    record_t **record_list = malloc(record_list_size);
    if (record_list == NULL) {
        free(key_list);
        free(segment_list);
        free(buffer);
        free(offset);
        free(key);
        free(record);
        return NULL;
    }

    // Initialize record list
    for (size_t i = 0; i < segment_count; ++i) {
        record_list[i] = record + i;
    }

    // Return success
    return (system_status_t){
        .offset = offset,
        .key = key,
        .record = record,
        .buffer = buffer,
        .segment_list = segment_list,
        .key_list = key_list,
        .record_list = record_list
    };
}
