void init_arrays(int num_doubles, int num_strings, int node_alloc_size) {
    // Allocate memory for the double array
    double* doubles = (double*)malloc(num_doubles * sizeof(double));
    if (!doubles) {
        printf("Error: Failed to allocate memory for the double array.\n");
        exit(1);
    }
    // Initialize the double array with random values
    srand(time(NULL));
    for (int i = 0; i < num_doubles; i++) {
        doubles[i] = rand() / (double)RAND_MAX;
    }

    // Allocate memory for the string array
    char** strings = (char**)malloc(num_strings * sizeof(char*));
    if (!strings) {
        printf("Error: Failed to allocate memory for the string array.\n");
        exit(1);
    }
    // Initialize the string array with random strings of length 10
    for (int i = 0; i < num_strings; i++) {
        char* str = (char*)malloc(10 * sizeof(char));
        if (!str) {
            printf("Error: Failed to allocate memory for string %d.\n", i);
            exit(1);
        }
        snprintf(str, 10, "%09d", rand() / (double)RAND_MAX);
        strings[i] = str;
    }

    // Allocate memory for the node pointers array
    struct node** nodes = (struct node**)malloc(node_alloc_size * sizeof(struct node*));
    if (!nodes) {
        printf("Error: Failed to allocate memory for the node pointers array.\n");
        exit(1);
    }

    // Initialize the node pointers array with null pointers
    for (int i = 0; i < node_alloc_size; i++) {
        nodes[i] = NULL;
    }
}

// Function to populate the double array from a file
void populate_doubles(double* doubles, int num_doubles, char* filename) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        printf("Error: Failed to open file %s.\n", filename);
        exit(1);
    }

    // Read the doubles from the file and store them in the array
    for (int i = 0; i < num_doubles; i++) {
        if (!fscanf(fp, "%lf", &doubles[i])) {
            printf("Error: Failed to read double value %d from file.\n", i);
            exit(1);
        }
    }

    // Close the file
    fclose(fp);
}

// Function to sort the char strings based on their length
void sort_strings(char** strings, int num_strings) {
    // Initialize a temporary array for storing sorted indices
    int* indices = (int*)malloc(num_strings * sizeof(int));
    if (!indices) {
        printf("Error: Failed to allocate memory for the sorted indices.\n");
        exit(1);
    }

    // Sort the strings based on their length and store the indices in the temporary array
    for (int i = 0; i < num_strings; i++) {
        int idx = 0;
        for (int j = 0; j < num_strings; j++) {
            if (strlen(strings[j]) > strlen(strings[idx])) {
                idx = j;
            }
        }
        indices[i] = idx;
    }

    // Swap the strings and their corresponding indices in the array based on the sorted indices
    for (int i = 0; i < num_strings; i++) {
        char* tmp = strings[i];
        strings[i] = strings[indices[i]];
        strings[indices[i]] = tmp;
    }
}

// Function to traverse the linked list of nodes and update their char* fields
void update_nodes(struct node** nodes, int num_nodes) {
    // Iterate over the nodes in the linked list and update their char* fields
    for (int i = 0; i < num_nodes; i++) {
        struct node* current = nodes[i];
        while (current != NULL) {
            // Allocate memory for a dynamically allocated copy of the corresponding string from the sorted array
            char* str = (char*)malloc(strlen(strings[current->data]) * sizeof(char));
            if (!str) {
                printf("Error: Failed to allocate memory for the updated string.\n");
                exit(1);
            }
            // Copy the string and update the char* field in the current node
            strcpy(str, strings[current->data]);
            current->data = str;

            // Move to the next node in the linked list
            current = current->next;
        }
    }
}

// Function to serialize the updated linked list into a file
void serialize_nodes(struct node** nodes, int num_nodes, char* filename) {
    // Open the file for writing
    FILE* fp = fopen(filename, "w");
    if (!fp) {
        printf("Error: Failed to open file %s.\n", filename);
        exit(1);
    }

    // Iterate over the nodes in the linked list and write them to the file
    for (int i = 0; i < num_nodes; i++) {
        struct node* current = nodes[i];
        while (current != NULL) {
            fprintf(fp, "%s ", current->data);
            // Write the double value associated with the string to the file
            fprintf(fp, "%lf\n", current->value);

            // Move to the next node in the linked list
            current = current->next;
        }
    }

    // Close the file
    fclose(fp);
}
