// Memory pool implementation
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct node {
    char* data;
    double value;
} node_t;

struct mem_pool {
    size_t num_nodes;
    size_t capacity;
    node_t* nodes;
};

void init_mem_pool(struct mem_pool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->num_nodes = 0;
    pool->nodes = (node_t*)malloc(sizeof(node_t) * pool->capacity);
}

void free_mem_pool(struct mem_pool* pool) {
    for (size_t i = 0; i < pool->num_nodes; ++i) {
        free(pool->nodes[i].data);
    }
    free(pool->nodes);
}

int add_node_to_mem_pool(struct mem_pool* pool, const char* data, double value) {
    if (pool->num_nodes == pool->capacity) {
        // Reallocate memory
        pool->capacity *= 2;
        pool->nodes = (node_t*)realloc(pool->nodes, sizeof(node_t) * pool->capacity);
    }
    pool->nodes[pool->num_nodes].data = strdup(data);
    pool->nodes[pool->num_nodes].value = value;
    ++pool->num_nodes;
}

int get_node_from_mem_pool(struct mem_pool* pool, size_t index, char** data, double* value) {
    if (index >= pool->num_nodes) {
        return -1;
    }
    *data = pool->nodes[index].data;
    *value = pool->nodes[index].value;
    return 0;
}
