// File reader implementation
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

void read_file(const char* filepath, double** data, size_t* num_data) {
    FILE* fp = fopen(filepath, "r");
    if (!fp) {
        printf("Error: Failed to open file %s\n", filepath);
        return;
    }

    // Get the number of doubles in the file
    size_t num_doubles = 0;
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        if (strtod(line, NULL) == 0.0) {
            continue;
        }
        ++num_doubles;
    }

    // Allocate memory for the data
    *data = (double*)malloc(sizeof(double) * num_doubles);
    if (!*data) {
        printf("Error: Failed to allocate memory for %zu doubles\n", num_doubles);
        return;
    }

    // Read the data from the file
    rewind(fp);
    size_t i = 0;
    while ((read = getline(&line, &len, fp)) != -1) {
        if (strtod(line, NULL) == 0.0) {
            continue;
        }
        (*data)[i] = strtod(line, NULL);
        ++i;
    }

    // Close the file
    fclose(fp);

    // Set the number of doubles in the data array
    *num_data = num_doubles;
}
