// Sorting algorithm implementation
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <limits.h>

void sort_strings(char** strings, size_t num_strings, int order) {
    // Initialize the sorting structure
    struct node* nodes = (struct node*)malloc(sizeof(struct node) * num_strings);
    if (!nodes) {
        printf("Error: Failed to allocate memory for %zu nodes\n", num_strings);
        return;
    }

    // Populate the sorting structure with data
    for (size_t i = 0; i < num_strings; ++i) {
        nodes[i].data = strings[i];
        nodes[i].value = strlen(strings[i]);
    }

    // Sort the data based on the length of the strings
    if (order == DESCENDING) {
        qsort(nodes, num_strings, sizeof(struct node), compare_strings);
    } else {
        qsort(nodes, num_strings, sizeof(struct node), compare_strings_ascending);
    }

    // Copy the sorted data back to the original array
    for (size_t i = 0; i < num_strings; ++i) {
        strings[i] = nodes[i].data;
    }

    // Free the memory used by the sorting structure
    free(nodes);
}

int compare_strings(const void* a, const void* b) {
    struct node* na = (struct node*)a;
    struct node* nb = (struct node*)b;
    return strcmp(na->data, nb->data);
}

int compare_strings_ascending(const void* a, const void* b) {
    struct node* na = (struct node*)a;
    struct node* nb = (struct node*)b;
    return strcmp(na->data, nb->data);
}
