void* custom_alloc(size_t size) {
    // Memory pool with fixed-size blocks for allocation
    static void** mem_pool = NULL;
    static int mem_pool_size = 0;
    static int block_size = 1024 * 1024; // 1MB block size

    // Allocate memory pool on the first call
    if (mem_pool == NULL) {
        mem_pool = malloc(sizeof(void*) * block_size);
        memset(mem_pool, 0, sizeof(void*) * block_size);
        mem_pool_size = block_size;
    }

    // Reallocate memory pool if full
    if (mem_pool_size == block_size) {
        mem_pool = realloc(mem_pool, sizeof(void*) * (block_size + 1));
        memset(&mem_pool[block_size], 0, sizeof(void*));
        mem_pool_size++;
    }

    // Return pointer to allocated memory block
    return &mem_pool[block_size - 1];
}

// Custom free function for memory pool
void custom_free(void* ptr) {
    if (ptr == NULL) return;

    // Free memory block and update memory pool size
    free(ptr);
    mem_pool_size--;
