    op->status = calculate_status(op->element);
    // Log the status of the operation
    fprintf(stderr, "Operation %s completed with status %d\n", op->name, op->status);
    fflush(stderr);
    return NULL;
}

// Define the function to calculate the packet loss
double calculate_packet_loss(struct element *element) {
    // Calculate the packet loss based on the trigonometric and logarithmic operations
    double packet_loss = 0.0;
    for (int i = 0; i < element->index; i++) {
        packet_loss += sin(log(element->value)) * cos(log2(element->value));
    }
    return packet_loss;
}

// Define the function to calculate the latency
double calculate_latency(struct operation *operation) {
    // Calculate the latency based on the trigonometric and logarithmic operations
    double latency = 0.0;
    for (int i = 0; i < operation->index; i++) {
        latency += sin(log(operation->value)) * cos(log2(operation->value));
    }
    return latency;
}

// Define the function to calculate the throughput
double calculate_throughput(struct element *element) {
    // Calculate the throughput based on the trigonometric and logarithmic operations
    double throughput = 0.0;
    for (int i = 0; i < element->index; i++) {
        throughput += sin(log(element->value)) * cos(log2(element->value));
    }
    return throughput;
}

// Define the function to calculate the status of an operation
int calculate_status(struct element *element) {
    // Calculate the status based on the trigonometric and logarithmic operations
    int status = 0;
    for (int i = 0; i < element->index; i++) {
        if (sin(log(element->value)) > 0.5) {
            status++;
        }
    }
    return status;
}

// Define the main function to manage the dynamic collection of network statistics structures
int main() {
    // Initialize the memory management variables
    total_elements = 0;
    max_elements = 500;
    element_indexes = NULL;
    elements = NULL;
    operations = NULL;
    network_stats = NULL;

    // Allocate memory for the arrays of structures
    element_indexes = (int *)malloc(max_elements * sizeof(int));
    elements = (struct element *)malloc(max_elements * sizeof(struct element));
    operations = (struct operation *)malloc(max_elements * sizeof(struct operation));
    network_stats = (struct network_stats *)malloc(max_elements * sizeof(struct network_stats));

    // Initialize the mutex for thread-safe data structures and synchronization mechanisms
    pthread_mutex_init(&mutex, NULL);

    // Loop until the user exits the program
    while (1) {
        // Prompt the user to enter the number of elements
        printf("Enter the number of elements: ");
        fflush(stdout);
        int num_elements = 0;
        scanf("%d", &num_elements);

        // Validate the input and handle errors gracefully
        if (num_elements <= 0) {
            printf("Error: Invalid number of elements\n");
            continue;
        } else if (num_elements > max_elements) {
            printf("Error: Too many elements entered\n");
            continue;
        }

        // Allocate memory for the arrays based on the user input
        element_indexes = realloc(element_indexes, num_elements * sizeof(int));
        elements = realloc(elements, num_elements * sizeof(struct element));
        operations = realloc(operations, num_elements * sizeof(struct operation));
        network_stats = realloc(network_stats, num_elements * sizeof(struct network_stats));

        // Initialize the arrays based on the user input
        for (int i = 0; i < num_elements; i++) {
            elements[i].value = 0.0;
            elements[i].index = 0;
            operations[i].name = NULL;
            operations[i].element = &elements[i];
            network_stats[i].packet_loss = 0.0;
            network_stats[i].latency = 0.0;
            network_stats[i].throughput = 0.0;
        }

        // Handle the operations in parallel using multi-threading
        pthread_t *threads = (pthread_t *)malloc(num_elements * sizeof(pthread_t));
        for (int i = 0; i < num_elements; i++) {
            threads[i] = handle_operation(&operations[i]);
        }
        for (int i = 0; i < num_elements; i++) {
            pthread_join(threads[i], NULL);
        }
        free(threads);

        // Manage the dynamic collection of network statistics structures
        manage_network_statistics(network_stats, num_elements);
    }

    // Clean up memory and return 0
    free(element_indexes);
    free(elements);
    free(operations);
    free(network_stats);
    pthread_mutex_destroy(&mutex);
    return 0;
}
