    int size;
    Node* nodes[];
} Tree;

// Function to dynamically manage memory for the tree
void* malloc_tree(int size) {
    // Check if the input is valid
    if (size < 0 || size > INT_MAX) {
        return NULL;
    }

    // Allocate memory for the tree
    Tree* tree = malloc(sizeof(Tree));
    if (!tree) {
        return NULL;
    }

    // Initialize the tree
    tree->size = size;
    tree->nodes = malloc(sizeof(Node) * size);
    if (!tree->nodes) {
        free(tree);
        return NULL;
    }

    // Return the initialized tree
    return tree;
}

// Function to insert new nodes into the tree with specified labels and values
void insert_node(Tree* tree, int index, double value, char label) {
    // Check if the input is valid
    if (index < 0 || index >= tree->size || !isfinite(value)) {
        return;
    }

    // Insert the node into the tree
    tree->nodes[index].value = value;
    tree->nodes[index].label = label;
}

// Function to calculate the average of all values in the tree
double average_tree(Tree* tree) {
    // Check if the input is valid
    if (!tree || !tree->nodes) {
        return NAN;
    }

    // Calculate the sum of all values in the tree
    double sum = 0.0;
    for (int i = 0; i < tree->size; i++) {
        sum += tree->nodes[i].value;
    }

    // Return the average of all values in the tree
    return sum / tree->size;
}

// Function to serialize the contents of the tree into a compressed binary format
void serialize_tree(Tree* tree, char* buffer) {
    // Check if the input is valid
    if (!tree || !buffer) {
        return;
    }

    // Serialize the tree data into the buffer
    for (int i = 0; i < tree->size; i++) {
        buffer[i] = tree->nodes[i].value;
        buffer[i + 1] = tree->nodes[i].label;
    }
}
