    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records: %s\n", strerror(errno));
        return;
    }

    // Initialize random value range and sorting algorithm
    int random_range = MAX_RANDOM_VALUE - MIN_RANDOM_VALUE + 1;
    bool ascending = true;

    // Populate records with random values within the specified range
    for (int i = 0; i < num_keys; i++) {
        int value = rand() % random_range + MIN_RANDOM_VALUE;
        records[i].value = value;
    }

    // Sort records based on their values
    if (num_keys > SORTING_THRESHOLD) {
        quicksort(records, 0, num_keys - 1);
    } else {
        mergesort(records, 0, num_keys - 1);
    }

    // Serialize records to file
    FILE *file = fopen("records.dat", "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing: %s\n", strerror(errno));
        free(records);
        return;
