void sort_records(int *records, int num_records) {
    // If the dataset is small, use the quicksort algorithm
    if (num_records < 100) {
        quicksort(records, 0, num_records - 1);
    } else if (num_records < 500) {
        // If the dataset is medium-sized, use the mergesort algorithm
        mergesort(records, 0, num_records - 1);
