    while (current != NULL && current->data.key != key) {
        current = current->next;
    }

    // If the node is found, update its data
    if (current != NULL) {
        current->data = *new_record;
    }
}

// Function to free the memory used by the dataset
void free_dataset() {
    Node* current = dataset;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    dataset = NULL;
}
