    unsigned short rnti;
    unsigned char crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

struct cache_entry {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct cache_entry *next;
};

struct cache_list {
    struct cache_entry *head;
    struct cache_entry *tail;
};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // mutex for thread safety
pthread_cond_t cond = PTHREAD_COND_INITIALIZER; // condition variable for signaling new elements
struct cache_list cache; // list of cached structures
int cache_size = 0; // current size of the cache

void *allocate(unsigned int n) {
    void *ptr;
    if (n > MAX_CACHE_SIZE) { // allocate new structure from heap if not in cache
        ptr = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!ptr) {
            return NULL; // handle allocation failure
        }
    } else { // get cached structure
        struct cache_entry *entry = cache.head;
        while (entry && entry->next != NULL) {
            entry = entry->next;
        }
        if (!entry) { // no cached structures available
            return NULL; // handle allocation failure
        }
        ptr = entry->data;
        entry->next = NULL;
    }
    return ptr;
}

void deallocate(void *ptr, unsigned int n) {
    if (n > MAX_CACHE_SIZE) { // deallocate structure from heap
        free(ptr);
    } else { // add to cache
        struct cache_entry *entry = malloc(sizeof(struct cache_entry));
        entry->data = ptr;
        entry->next = NULL;
        if (cache.tail == NULL) {
            cache.head = entry;
        } else {
            cache.tail->next = entry;
        }
        cache.tail = entry;
    }
}

