    return ptr;
}

void deallocate_and_destroy(void *ptr, unsigned int n) {
    deallocate(ptr, n);
    free(ptr);
}

void dynamic_resize(unsigned int n) {
    if (n > MAX_CACHE_SIZE) { // resize cache if new size exceeds threshold
        struct cache_entry *entry = cache.head;
        while (entry && entry->next != NULL) {
            entry = entry->next;
        }
        if (!entry) {
            return; // handle allocation failure
        }
        entry->next = malloc(sizeof(struct cache_entry));
        entry->next->data = ptr;
        entry->next->next = NULL;
        cache.tail = entry->next;
    } else { // release extra cached structures if new size is less than threshold
        struct cache_entry *entry = cache.head;
        while (entry && cache_size > n) {
            struct cache_entry *temp = entry;
            entry = entry->next;
            deallocate(temp, MAX_CACHE_SIZE);
            temp->data = NULL;
        }
    }
}

void *thread_routine(void *arg) {
