            if (cache_size < MIN_ALLOC_SIZE) {
                pthread_cond_wait(&cond, &lock); // wait for new elements to arrive
            }
        }
        void *ptr = allocate(cache_size); // get cached structure from head of list
        if (ptr == NULL) {
            pthread_mutex_unlock(&lock); // release mutex
            break; // handle allocation failure
