    // Memory pool for efficient allocation and deallocation of sensor data structures
    memory_pool = CreateMemoryPool(MAX_BLOCK_SIZE, FREE_LIST_LENGTH);

    // Thread-safe loop to consume and process data from the real-time data stream
    thread_loop = NewThreadLoop();
