// Function to initialize the linked list from a JSON configuration file
void init_list(const char* filename) {
    // Open the JSON configuration file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: failed to open %s\n", filename);
        exit(EXIT_FAILURE);
    }

    // Read the JSON data from the file into a json_object
    json_object* root = json_object_from_file(fp);
    if (root == NULL) {
        printf("Error: failed to read %s\n", filename);
        fclose(fp);
        exit(EXIT_FAILURE);
    }

    // Get the number of nodes from the JSON data
    int num_nodes = json_object_get_int(json_object_object_get(root, "num_nodes"));

    // Get the range for generating random double values from the JSON data
    json_object* range_obj = json_object_object_get(root, "range");
    int min_value = json_object_get_int(json_object_array_get_idx(range_obj, 0));
    int max_value = json_object_get_int(json_object_array_get_idx(range_obj, 1));

    // Get the maximum length of random strings from the JSON data
    int string_length = json_object_get_int(json_object_object_get(root, "string_length"));

    // Initialize a linked list with num_nodes nodes
    struct Node* head = NULL;
    for (int i = 0; i < num_nodes; ++i) {
        // Allocate memory for the new node
        struct Node* new_node = malloc(sizeof(struct Node));
        if (new_node == NULL) {
            printf("Error: failed to allocate memory\n");
            json_object_put(root);
            fclose(fp);
            exit(EXIT_FAILURE);
        }

        // Generate a random double value within the specified range
        new_node->value = (double)rand() / RAND_MAX * (max_value - min_value) + min_value;

        // Generate a random string of the specified length
        char* str = malloc(string_length + 1);
        if (str == NULL) {
            printf("Error: failed to allocate memory\n");
            json_object_put(root);
            fclose(fp);
            exit(EXIT_FAILURE);
        }
        for (int j = 0; j < string_length; ++j) {
            str[j] = 'a' + rand() % ('z' - 'a');
        }
        str[string_length] = '\0';
        new_node->string = str;

        // Link the new node to the list
        if (head == NULL) {
            head = new_node;
        } else {
            struct Node* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    // Close the JSON configuration file
    json_object_put(root);
    fclose(fp);

    // Log the initialization of the linked list
    printf("Initialized linked list with %d nodes\n", num_nodes);
}

// Function to free the memory allocated by the init_list function
void free_list(struct Node* head) {
    struct Node* current = head;
    while (current != NULL) {
        // Free the string and next node pointers in each node
        free(current->string);
        if (current->next != NULL) {
            free(current->next);
        }
        current = current->next;
    }
}
