["```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for a node in the primary linked list
struct node {
    double value;
    char* str1;
    char* str2;
    struct node* next;
};

// Define the structure for a node in the secondary linked list
struct sec_node {
    void* addr;
    struct sec_node* next;
};

void initialize_lists(int num_nodes, int range) {
    // Allocate memory for the primary and secondary linked lists
    struct node* primary = malloc(num_nodes * sizeof(struct node));
    struct sec_node* secondary = malloc(num_nodes * sizeof(struct sec_node));

    // Initialize the primary linked list
    for (int i = 0; i < num_nodes; i++) {
        primary[i].value = rand() % range;
        primary[i].str1 = generate_random_string();
        primary[i].str2 = generate_random_string();
        primary[i].next = NULL;
    }

    // Initialize the secondary linked list
    for (int i = 0; i < num_nodes; i++) {
        secondary[i].addr = &(primary[i]);
        secondary[i].next = NULL;
    }

    // Traverse the primary linked list and set each node's double value to a random number within a specified range
    for (int i = 0; i < num_nodes; i++) {
        struct node* curr = &(primary[i]);
        while (curr != NULL) {
            curr->value = rand() % range;
            curr = curr->next;
        }
    }

    // Traverse the primary linked list and set each node's char pointer to point to a newly allocated string of random length and characters
    for (int i = 0; i < num_nodes; i++) {
        struct node* curr = &(primary[i]);
        while (curr != NULL) {
            curr->str1 = generate_random_string();
            curr = curr->next;
        }
    }

    // Traverse the primary linked list and set each node's char* pointer to point to a newly allocated string of random length and characters containing only digits
    for (int i = 0; i < num_nodes; i++) {
        struct node* curr = &(primary[i]);
        while (curr != NULL) {
            curr->str2 = generate_random_string();
            curr = curr->next;
        }
    }

    // Traverse the secondary linked list and set each node's address to point to the corresponding node in the primary linked list
    for (int i = 0; i < num_nodes; i++) {
        struct sec_node* curr = &(secondary[i]);
        while (curr != NULL) {
            curr->addr = &(primary[i]);
            curr = curr->next;
        }
    }

    // Release all allocated memory before returning
    free(primary);
    free(secondary);
}

// Function to generate a random string of a specified length and containing only digits
