        fwrite(curr->str1, strlen(curr->str1), 1, fp);
        fwrite(curr->str2, strlen(curr->str2), 1, fp);
        curr = curr->next;
    }

    // Write the nodes of the secondary linked list to the file
    struct sec_node* curr_sec = secondary;
    while (curr_sec != NULL) {
        void* addr = &(primary[i]);
        fwrite(&addr, sizeof(void*), 1, fp);
        curr_sec = curr_sec->next;
    }
}

// Function to deserialize the entire data structure from a binary file
void deserialize(struct node** primary, struct sec_node** secondary, FILE* fp) {
    // Read the number of nodes in the primary and secondary linked lists from the file
    int num_nodes = 0;
    fread(&num_nodes, sizeof(int), 1, fp);
    *primary = malloc(num_nodes * sizeof(struct node));
    *secondary = malloc(num_nodes * sizeof(struct sec_node));

    // Read the nodes of the primary linked list from the file
    struct node* curr = *primary;
    for (int i = 0; i < num_nodes; i++) {
        fread(&(curr->value), sizeof(double), 1, fp);
        curr->str1 = malloc(strlen(curr->str1) + 1);
        fread(curr->str1, strlen(curr->str1), 1, fp);
        curr->str2 = malloc(strlen(curr->str2) + 1);
        fread(curr->str2, strlen(curr->str2), 1, fp);
        curr = curr->next;
    }

    // Read the nodes of the secondary linked list from the file
    struct sec_node* curr_sec = *secondary;
    for (int i = 0; i < num_nodes; i++) {
        void* addr = malloc(sizeof(void*));
        fread(&addr, sizeof(void*), 1, fp);
        curr_sec->addr = addr;
        curr_sec = curr_sec->next;
    }
}

// Function to count the number of nodes in a linked list
int count_nodes(struct node* head) {
    int count = 0;
    struct node* curr = head;
    while (curr != NULL) {
        count++;
        curr = curr->next;
    }
    return count;
}
