struct Product {
    char name[256];
    int quantity;
    double price;
};

// Function to dynamically allocate memory for an array of products
struct Product* allocate_products(int num_products) {
    // Validate the input and prevent buffer overflows
    if (num_products <= 0 || num_products > 100000) {
        return NULL;
    }

    struct Product *products = malloc(sizeof(struct Product) * num_products);
    if (!products) {
        return NULL;
    }

    // Initialize the products structure
    for (int i = 0; i < num_products; i++) {
        strcpy(products[i].name, "");
        products[i].quantity = 0;
        products[i].price = 0.0;
    }

    return products;
}

// Function to custom validation for the number of products
int validate_num_products(int num_products) {
    if (num_products <= 0 || num_products > 100000) {
        return -1;
    }
    return 0;
}

// Function to update the price of each product based on a specified discount percentage
void apply_discount(struct Product *products, int num_products, double discount_percentage) {
    // Validate the input and prevent invalid input
    if (num_products <= 0 || discount_percentage < 0.0 || discount_percentage > 100.0) {
        return;
    }

    for (int i = 0; i < num_products; i++) {
        products[i].price -= products[i].price * (discount_percentage / 100);
    }
}

// Function to filter and sort products based on user-specified criteria
void filter_and_sort_products(struct Product *products, int num_products, char *criteria) {
    // Validate the input and prevent invalid input
    if (num_products <= 0 || !criteria) {
        return;
    }

    // Initialize the sorted products array
    struct Product *sorted_products = malloc(sizeof(struct Product) * num_products);
    if (!sorted_products) {
        return;
    }

    // Copy the original products into the sorted products array
    for (int i = 0; i < num_products; i++) {
        sorted_products[i] = products[i];
    }

    // Sort the products based on the specified criteria
    if (!strcmp(criteria, "quantity")) {
        qsort(sorted_products, num_products, sizeof(struct Product), compare_product_by_quantity);
    } else if (!strcmp(criteria, "price")) {
        qsort(sorted_products, num_products, sizeof(struct Product), compare_product_by_price);
    }

    // Print the sorted products to the console
    for (int i = 0; i < num_products; i++) {
        printf("%s, %d, %.2f\n", sorted_products[i].name, sorted_products[i].quantity, sorted_products[i].price);
    }

    free(sorted_products);
}

// Function to compare two products by their quantity
int compare_product_by_quantity(const void *p1, const void *p2) {
    struct Product *product1 = (struct Product *) p1;
    struct Product *product2 = (struct Product *) p2;

    if (product1->quantity > product2->quantity) {
        return 1;
    } else if (product1->quantity < product2->quantity) {
        return -1;
    }
    return 0;
}

// Function to compare two products by their price
int compare_product_by_price(const void *p1, const void *p2) {
    struct Product *product1 = (struct Product *) p1;
    struct Product *product2 = (struct Product *) p2;

    if (product1->price > product2->price) {
        return 1;
    } else if (product1->price < product2->price) {
        return -1;
    }
    return 0;
}
