// Function to perform an exponential backoff on I/O errors
void backoff(int attempt, int max_attempts) {
    // Calculate the wait time based on the number of attempts made so far
    int wait_time = (1 << (attempt - 1)) * 100;

    // Check if the maximum number of attempts has been reached
    if (attempt <= max_attempts) {
        printf("Error: I/O error occurred. Waiting %d milliseconds before retrying...\n", wait_time);
        sleep(wait_time / 1000);
        return;
    } else {
        printf("Error: Maximum number of attempts reached. Aborting.\n");
    }
}

