    Task *tasks;
    // The number of tasks in the list
    int numTasks;
};

// Function to add a new task to the list
int addTask(TaskList *list, const char *name, int priority, unsigned long duration) {
    // Check if the list is full
    if (list->numTasks == MAX_TASKS) {
        return -1;
    }

    // Allocate memory for the new task
    Task *newTask = malloc(sizeof(Task));
    if (!newTask) {
        return -1;
    }

    // Set the fields of the new task
    strcpy(newTask->name, name);
    newTask->priority = priority;
    newTask->duration = duration;
    newTask->status = PENDING;

    // Add the new task to the list
    list->tasks[list->numTasks++] = newTask;

    return 0;
}

// Function to update the status of a task in the list
int updateTaskStatus(TaskList *list, int index, enum status newStatus) {
    // Check if the index is valid
    if (index < 0 || index >= list->numTasks) {
        return -1;
    }

    // Update the status of the task
    list->tasks[index]->status = newStatus;

    return 0;
}

// Function to calculate the total estimated completion time based on the durations and priorities of all tasks in the list
unsigned long calculateTotalCompletionTime(TaskList *list) {
    // Initialize the total completion time to 0
    unsigned long total = 0;

    // Iterate over all tasks and calculate their estimated completion times
    for (int i = 0; i < list->numTasks; i++) {
        Task *task = list->tasks[i];
        if (task->status != PENDING) {
            continue;
        }
        total += task->priority * task->duration;
    }

    return total;
}

// Function to periodically purge expired tasks based on their creation time and a configurable expiration threshold in days
void purgeExpiredTasks(TaskList *list, int expirationThreshold) {
    // Get the current time
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

    // Iterate over all tasks and check if they have expired
    for (int i = 0; i < list->numTasks; i++) {
        Task *task = list->tasks[i];
        if (task->status != PENDING) {
            continue;
        }

        // Calculate the expiration time based on the creation time and the expiration threshold
        struct timespec expirationTime = {now.tv_sec + expirationThreshold * 86400, now.tv_nsec};

        // Check if the task has expired
        if (task->creationTime <= expirationTime) {
            updateTaskStatus(list, i, COMPLETED);
        }
    }
}

// Function to serialize and deserialize the task list to and from a file for persistence
void serializeTasks(TaskList *list, FILE *file) {
