        fwrite(task->name, strlen(task->name) + 1, 1, file);
        fwrite(&task->priority, sizeof(int), 1, file);
        fwrite(&task->duration, sizeof(unsigned long), 1, file);
        fwrite(&task->status, sizeof(enum status), 1, file);
    }
}

void deserializeTasks(TaskList *list, FILE *file) {
    // Deserialize the number of tasks in the list
    fread(&list->numTasks, sizeof(int), 1, file);

    // Allocate memory for the task array
    list->tasks = malloc(sizeof(Task *) * list->numTasks);

