void addTask(char* name, int priority, unsigned long duration) {
  // Check if the task already exists in the array
  for (int i = 0; i < numTasks; i++) {
    if (strcmp(tasks[i].name, name) == 0) {
      return; // Task already exists, so just return
    }
  }

  // If we reach this point, the task does not exist, so add it to the array
  tasks = realloc(tasks, (numTasks + 1) * sizeof(Task));
  tasks[numTasks].name = name;
  tasks[numTasks].priority = priority;
  tasks[numTasks].duration = duration;
  numTasks++;
}

// Function to update an existing task
void updateTask(char* name, int newPriority, unsigned long newDuration) {
  // Find the index of the task in the array
  for (int i = 0; i < numTasks; i++) {
    if (strcmp(tasks[i].name, name) == 0) {
      tasks[i].priority = newPriority;
      tasks[i].duration = newDuration;
      return; // Task found and updated, so just return
    }
  }

  // If we reach this point, the task does not exist, so add it to the array
  addTask(name, newPriority, newDuration);
}

