// Define a function to dynamically manage the list of CRC_INDICATION_PDUs
void manageCrcIndicationList(struct CrcIndicationList *list) {
    // Check if the list needs to be resized
    if (list->len == list->capacity) {
        // Resize the list by a factor of 2
        list->capacity *= 2;
        list->arr = realloc(list->arr, list->capacity * sizeof(struct CrcIndication));
    }
}

// Define a function to insert a new CRC_INDICATION_PDU into the list
void insertCrcIndication(struct CrcIndicationList *list, struct CrcIndication crcInd) {
    pthread_mutex_lock(&list->lock);
    manageCrcIndicationList(list);
    list->arr[list->len++] = crcInd;
    pthread_mutex_unlock(&list->lock);
}

// Define a function to delete an existing CRC_INDICATION_PDU from the list
void deleteCrcIndication(struct CrcIndicationList *list, struct CrcIndication crcInd) {
    pthread_mutex_lock(&list->lock);
    // Find the index of the CRC_INDICATION_PDU to be deleted
    size_t i;
    for (i = 0; i < list->len; i++) {
        if (memcmp(&list->arr[i], &crcInd, sizeof(struct CrcIndication)) == 0) {
            break;
        }
