// Custom memory pool class to manage fixed-size and variable-size allocations efficiently
class MemoryPool {
public:
    MemoryPool(size_t size) : size_(size), capacity_(0), blocks_(vector<pair<void*, size_t>>()) {}

    ~MemoryPool() {
        for (auto& block : blocks_) {
            delete[] block.first;
        }
    }

    void* allocate(size_t size) {
        if (size > size_) {
            throw runtime_error("Memory pool exceeded maximum allocation size");
        }

        // Check for available blocks with sufficient capacity
        for (auto& block : blocks_) {
            if (block.second >= size) {
                return block.first;
            }
        }

        // Allocate a new block if all existing blocks are insufficient
        auto* new_block = new char[size];
        capacity_ += size;
        blocks_.push_back(make_pair(new_block, size));
        return new_block;
    }

    void deallocate(void* ptr) {
        // Find the block that contains the given pointer and mark it as free
        for (auto& block : blocks_) {
            if (ptr == block.first) {
                block.second = 0;
                return;
            }
        }
    }

private:
    size_t size_; // maximum allocation size per block
    size_t capacity_; // total allocated capacity in bytes
    vector<pair<void*, size_t>> blocks_; // list of available blocks
};

// Custom record structure to store integer values and their indices in the sorted array
struct Record {
    int key;
    int index;
};

// Data processing pipeline that processes records based on user-defined input parameters
void dataProcessingPipeline(const vector<long>& offsets, const vector<int>& keys) {
    // Validate input sizes to prevent buffer overflows and ensure system-defined limits
    if (offsets.size() != keys.size()) {
        throw runtime_error("Invalid input size: mismatch between offset and key arrays");
    }

    // Allocate memory for the array of records
    const int numRecords = offsets.back();
    auto* recordArray = new Record[numRecords];
    MemoryPool pool(sizeof(Record) * numRecords); // custom memory pool for efficient allocation

    // Initialize records with random values within a specified range, handling invalid ranges gracefully
    uniform_int_distribution<int> distribution(0, 100);
    for (int i = 0; i < numRecords; ++i) {
        recordArray[i].key = keys[i] == -1 ? distribution(randomEngine) : keys[i];
    }

    // Set fixed values for some records based on a configuration file, stored in JSON format
    ifstream configFile("config.json");
    string line;
    while (getline(configFile, line)) {
        istringstream ss(line);
        int index, value;
        ss >> index >> value;
        recordArray[index].key = value;
    }

    // Sort the records based on their integer values using a stable sorting algorithm
    auto sortFunction = [](const Record& lhs, const Record& rhs) { return lhs.key < rhs.key; };
    stable_sort(recordArray, recordArray + numRecords, sortFunction);

    // Serialize the sorted records into a file in a binary format designed for minimal storage overhead
    ofstream serializedFile("sorted_records.bin", ios::binary);
    serialize(serializedFile, recordArray, numRecords, pool);

    // Delete the file if it exists before executing a command using Runtime.getRuntime().exec(String, String, File)
    string command = "rm -f sorted_records.bin";
    system(command.c_str());
}

// Custom serialization function to serialize records into a file in a binary format efficiently
void serialize(ostream& out, const Record* recordArray, int numRecords, MemoryPool& pool) {
    // Ensure that the file is thread-safe for concurrent writes without data corruption
    mutex mtx;
    unique_lock<mutex> lock(mtx);

    // Serialize records using a custom binary format designed for minimal storage overhead
    for (int i = 0; i < numRecords; ++i) {
        Record record = recordArray[i];
        out.write((char*)&record, sizeof(Record));
    }

    // Compress the serialized data using a compression library like Zlib or LZO for better storage efficiency
    vector<byte> compressedData;
    zlibCompress(out.str(), compressedData);

    // Write the compressed data to the file and update versioning information
    ofstream compressedFile("sorted_records.bin.z", ios::binary);
    compressedFile << compressedData;
}

// Custom zlib compression function to compress data efficiently
vector<byte> zlibCompress(const string& in, vector<byte>& out) {
    // Initialize a zlib compression stream with appropriate options for minimal storage overhead
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    deflateInit(&strm, Z_BEST_COMPRESSION);

    // Compress the input data and update the output buffer with the compressed data
    byte* inBuffer = (byte*)in.c_str();
    int inSize = in.size();
    vector<byte> outBuffer(out.size() + inSize * 1.05);
    int outSize = deflate(&strm, Z_FINISH);
    if (outSize != Z_STREAM_END) {
        throw runtime_error("zlib compression failed");
    }
    deflateEnd(&strm);
    out.clear();
    out.insert(out.end(), outBuffer.begin(), outBuffer.begin() + outSize);
}
```
