// Function to dynamically allocate memory for two arrays: one for long offsets and one for int keys
void allocate_arrays(int* arr1, int* arr2) {
  // Get the number of elements from the user
  printf("Enter the number of elements: ");
  int n;
  scanf("%d", &n);

  // Allocate memory for the arrays
  long* offsets = (long*)malloc(sizeof(long) * n);
  int* keys = (int*)malloc(sizeof(int) * n);

  // Check if allocation was successful
  if (offsets == NULL || keys == NULL) {
    printf("Memory allocation failed. Retrying...\n");
    sleep(10);
    free(offsets);
    free(keys);
    allocate_arrays(arr1, arr2);
