// Custom allocator for memory pooling
struct MemoryPool {
    int *buffer;
    size_t capacity;
    size_t used;
};

void initMemoryPool(struct MemoryPool *pool, size_t capacity) {
    // Initialize the memory pool with a given capacity
    pool->capacity = capacity;
    pool->used = 0;
    pool->buffer = (int *)malloc(sizeof(int) * capacity);
}

void destroyMemoryPool(struct MemoryPool *pool) {
    // Destroy the memory pool and free its buffer
    free(pool->buffer);
}

bool allocateFromMemoryPool(struct MemoryPool *pool, int size) {
    // Allocate a block of memory from the memory pool
    if (pool->used + size > pool->capacity) {
        return false;
    }

    pool->buffer[pool->used++] = size;
    return true;
}

void deallocateFromMemoryPool(struct MemoryPool *pool, int offset) {
    // Deallocate a block of memory from the memory pool
    if (offset >= pool->used || offset < 0) {
        return;
    }

    int i = offset + 1;
    while (i < pool->used) {
        pool->buffer[i - 1] = pool->buffer[i];
        i++;
    }

    pool->used--;
}

