```rust
use std::collections::HashMap;
use std::fs::{File, OpenOptions};
use std::io::prelude::*;
use std::path::PathBuf;

struct Cache {
    data: HashMap<String, Vec<u8>>,
    files: HashMap<String, PathBuf>,
}

impl Cache {
    fn new() -> Self {
        Self {
            data: HashMap::new(),
            files: HashMap::new(),
        }
    }

    fn get(&mut self, key: &str) -> Option<Vec<u8>> {
        if let Some(data) = self.data.get(key) {
            return Some(data.clone());
        }

        // Check if the data is stored in a file
        if let Some(file_path) = self.files.get(key) {
            let mut f = OpenOptions::new()
                .read(true)
                .open(file_path)
                .unwrap();
            let mut buffer = Vec::new();
            f.read_to_end(&mut buffer).unwrap();
            return Some(buffer);
        }

        None
    }

    fn set(&mut self, key: &str, value: &[u8]) {
        self.data.insert(key.to_owned(), value.to_vec());
    }

    fn remove(&mut self, key: &str) -> bool {
        self.data.remove(key).is_some() || self.files.remove(key).is_some()
    }

    fn flush(&self, file: &mut File, key: &str) -> Result<(), std::io::Error> {
        let data = self.get(key);
        if let Some(data) = data {
            file.write_all(&data)?;
        }
        Ok(())
    }

    fn flush_all(&self, file: &mut File) -> Result<(), std::io::Error> {
        for (key, value) in self.data.iter() {
            self.flush(file, key)?;
        }
        Ok(())
    }
}
```
