};

void read_temperature_data(char *file_path, int socket_fd) {
    // Initialize variables
    struct entry *entries = NULL;
    size_t num_entries = 0;
    size_t max_entries = 1000;
    ssize_t read_bytes = 0;
    off_t file_offset = 0;
    char line[256];
    int ret;

    // Open file and socket
    FILE *file = fopen(file_path, "r");
    if (!file) {
        perror("fopen");
        exit(1);
    }

    struct addrinfo hints, *servinfo, *p;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    if ((ret = getaddrinfo("localhost", "8080", &hints, &servinfo)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(ret));
        exit(1);
    }

    // Connect to socket
    for (p = servinfo; p != NULL; p = p->ai_next) {
        if ((socket_fd = socket(p->ai_family, p->ai_socktype, p->ai_protocol)) == -1) {
            perror("socket");
            continue;
        }
        if (connect(socket_fd, p->ai_addr, p->ai_addrlen) == -1) {
            close(socket_fd);
            perror("connect");
            continue;
        }
        break;
    }

    // Read temperature data from file and socket
    while ((read_bytes = getline(&line, &num_entries, file)) != -1) {
        if (strlen(line) > 0) {
            char *timestamp_str = strtok(line, ",");
            char *temperature_str = strtok(NULL, "\n");
            long timestamp = atol(timestamp_str);
            double temperature = atof(temperature_str);
            if (temperature < -273 || temperature > 5000) {
                // Validate temperature value
                continue;
            }
            entries = realloc(entries, sizeof(struct entry) * (num_entries + 1));
            entries[num_entries].timestamp = timestamp;
            entries[num_entries].temperature = temperature;
            num_entries++;
        }
    }

    // Handle file I/O errors and network connectivity issues
    if (read_bytes == -1) {
        perror("getline");
        exit(1);
    }
    freeaddrinfo(servinfo);
    fclose(file);

    // Reallocate memory if necessary
    if (num_entries > max_entries) {
        entries = realloc(entries, sizeof(struct entry) * num_entries);
        max_entries = num_entries;
    }

    // Validate temperature values and store in array
    for (size_t i = 0; i < num_entries; i++) {
        if (entries[i].temperature < -273 || entries[i].temperature > 5000) {
            // Validate temperature value
            continue;
        }
        entries[i].timestamp = timestamp;
        entries[i].temperature = temperature;
    }

    // Write array to socket
    write(socket_fd, entries, sizeof(struct entry) * num_entries);

    // Clean up resources
    free(entries);
}
