void sort_records(record_t* arr, size_t len) {
    // Validate input parameters
    if (arr == NULL || len < 1) {
        printf("Invalid input parameters\n");
        return;
    }

    // Sort records by their int values using a stable sorting algorithm
    for (size_t i = 0; i < len - 1; i++) {
        for (size_t j = i + 1; j < len; j++) {
            if (arr[i].value > arr[j].value) {
                record_t temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }
    }
}

// Define function to serialize records into a file in compressed format
void serialize_records(record_t* arr, size_t len) {
    // Validate input parameters
    if (arr == NULL || len < 1) {
        printf("Invalid input parameters\n");
        return;
    }

    // Open file for writing in binary mode
    FILE* fp = fopen("records.bin", "wb");
    if (fp == NULL) {
        printf("Failed to open file for writing\n");
        return;
    }

    // Write records to file in compressed format
    for (size_t i = 0; i < len; i++) {
        fwrite(&arr[i], sizeof(record_t), 1, fp);
    }

    // Close file
    fclose(fp);
}

// Define function to read records from a file in compressed format
void deserialize_records(record_t* arr, size_t len) {
    // Validate input parameters
    if (arr == NULL || len < 1) {
        printf("Invalid input parameters\n");
        return;
    }

    // Open file for reading in binary mode
    FILE* fp = fopen("records.bin", "rb");
    if (fp == NULL) {
        printf("Failed to open file for reading\n");
        return;
    }

    // Read records from file into array
    for (size_t i = 0; i < len; i++) {
        fread(&arr[i], sizeof(record_t), 1, fp);
    }

    // Close file
    fclose(fp);
}
