// Custom memory pool for efficient matrix operations
class MatrixPool {
public:
    MatrixPool(size_t size) : size_(size), used_(0) {}

    void* allocate(size_t bytes) {
        if (used_ + bytes > size_) {
            return nullptr;
        }

        used_ += bytes;
        return buffer_ + used_ - bytes;
    }

    void deallocate(void* ptr, size_t bytes) {
        assert((char*)ptr >= (char*)buffer_ && (char*)ptr < (char*)buffer_ + size_);
        used_ -= bytes;
    }

private:
    char buffer_[size_];
    size_t size_;
    size_t used_;
};

// Matrix structure with float values and custom memory pool
struct Matrix {
    Matrix(size_t rows, size_t cols) : rows_(rows), cols_(cols), pool_(rows * cols * sizeof(float)) {}

    size_t rows() const { return rows_; }
    size_t cols() const { return cols_; }
    float* data() { return (float*)pool_.allocate(rows_ * cols_ * sizeof(float)); }
    void deallocate() { pool_.deallocate((char*)data_, rows_ * cols_ * sizeof(float)); }

private:
    size_t rows_;
    size_t cols_;
    MatrixPool pool_;
};

// Function to perform matrix addition
void add(const Matrix& A, const Matrix& B, Matrix& C) {
    assert(A.rows() == B.rows() && A.cols() == B.cols());
    for (size_t i = 0; i < A.rows(); ++i) {
        for (size_t j = 0; j < A.cols(); ++j) {
            C.data()[i * A.cols() + j] = A.data()[i * A.cols() + j] + B.data()[i * B.cols() + j];
        }
    }
}

// Function to perform matrix multiplication
void multiply(const Matrix& A, const Matrix& B, Matrix& C) {
    assert(A.cols() == B.rows());
    for (size_t i = 0; i < A.rows(); ++i) {
        for (size_t j = 0; j < B.cols(); ++j) {
            float sum = 0;
            for (size_t k = 0; k < A.cols(); ++k) {
                sum += A.data()[i * A.cols() + k] * B.data()[k * B.cols() + j];
            }
            C.data()[i * B.cols() + j] = sum;
        }
    }
}

// Function to perform matrix transposition
void transpose(const Matrix& A, Matrix& B) {
    assert(A.rows() == B.cols() && A.cols() == B.rows());
    for (size_t i = 0; i < A.rows(); ++i) {
        for (size_t j = 0; j < A.cols(); ++j) {
            B.data()[j * B.rows() + i] = A.data()[i * A.cols() + j];
        }
    }
}

// Function to calculate matrix determinant
float det(const Matrix& A, size_t n) {
    assert(n == 0 || n == 1);
    if (n == 0) {
        return 1;
    } else {
        float sum = 0;
        for (size_t i = 0; i < A.rows(); ++i) {
            sum += A.data()[i] * pow(-1, i) * det(A, n - 1);
        }
        return sum;
    }
}

// Function to perform matrix operations in a single thread
void perform_operation(const Matrix& A, const Matrix& B, Matrix& C, size_t op) {
    switch (op) {
        case 0: add(A, B, C); break;
        case 1: multiply(A, B, C); break;
        case 2: transpose(A, C); break;
        case 3: C.data()[0] = det(A, A.rows()); break;
    }
}

// Function to perform matrix operations in multiple threads
void multi_threaded_perform_operation(const Matrix& A, const Matrix& B, Matrix& C, size_t op) {
    // Split the work among threads using a thread-safe queue
