                        case 1: C.data()[i * B.cols() + j] = A.data()[i * A.cols() + j] * B.data()[i * B.cols() + j]; break;
                        case 2: std::swap(A.data()[i * A.cols() + j], C.data()[i * B.cols() + j]); break;
                        case 3: C.data()[0] += pow(-1, i) * det(Matrix(A.rows(), A.cols()), n); break;
                    }
                }
            }
        }, i));
    }

    // Wait for all threads to complete their work
    for (auto& t : threads) {
        t.join();
    }
}
