    // Constructor to initialize the memory allocator
    MemoryAllocator() {}

    // Function to allocate memory for a given size
    void* allocate(size_t size) {
        // Check if there is enough free memory to allocate the requested size
        if (freeMemory >= size) {
            // If there is enough free memory, allocate it and update the free memory count
            void* ptr = &memory[usedMemory];
            usedMemory += size;
            freeMemory -= size;
            return ptr;
        } else {
            // If there is not enough free memory, check if there is any disk space available to store the data
