        vector<thread> threads;
        mutex mtx;

        // Divide the data into chunks that can be processed in parallel
        size_t chunkSize = size / threads.size();
        vector<vector<float>> chunks(threads.size());
        for (int i = 0; i < chunks.size(); ++i) {
            // Calculate the starting and ending indices of the current chunk
            int start = i * chunkSize;
            int end = min((i + 1) * chunkSize, size);

            // Create a new thread for processing the current chunk
            threads.push_back(thread([&]() {
                // Sort the current chunk using the specified sorting algorithm
                sort(chunks[i].begin(), chunks[i].end());

                // Lock the mutex to synchronize access to the data
