// Define a hash table that uses a custom memory allocator for storing and retrieving data
class HashTable {
public:
    // Constructor to initialize the hash table with the given parameters
    HashTable(size_t size, MemoryAllocator& allocator) : size(size), allocator(allocator) {}

    // Function to insert a key-value pair into the hash table
    void insert(string key, float value) {
        // Calculate the index of the key in the hash table
        size_t index = std::hash<string>{}(key) % size;

        // If there is already an entry for the key, merge its associated values with the new value and update the entry
        if (table[index].find(key) != table[index].end()) {
            float& v = table[index][key];
            v += value;
        } else {
            // If there is no existing entry for the key, create a new one with the given value
            table[index][key] = value;
        }
    }

    // Function to retrieve the sum of all values associated with a given key in the hash table
    float get(string key) {
        // Calculate the index of the key in the hash table
        size_t index = std::hash<string>{}(key) % size;

        // If there is no entry for the key, return 0
        if (table[index].find(key) == table[index].end()) {
            return 0.0f;
        } else {
            // Return the sum of all values associated with the key
            float sum = 0.0f;
            for (auto& v : table[index][key]) {
                sum += v;
            }
            return sum;
        }
    }

private:
    // Size of the hash table
    size_t size;

    // Memory allocator for storing and retrieving data
    MemoryAllocator& allocator;

    // Table that maps keys to values, with each entry being a vector of values
    map<string, vector<float>> table;
};

// Define a command-line tool for managing the hash table
class CommandLineTool {
public:
    // Constructor to initialize the command-line tool with the given parameters
    CommandLineTool(size_t size, MemoryAllocator& allocator) : size(size), allocator(allocator) {}

    // Function to perform the specified operation on the hash table
    void operate(string op, string key, float value) {
        if (op == "insert") {
            // Insert a new key-value pair into the hash table
            table.insert(key, value);
        } else if (op == "get") {
            // Retrieve the sum of all values associated with a given key in the hash table
            cout << table.get(key) << endl;
        }
    }

private:
    // Size of the hash table
    size_t size;

    // Memory allocator for storing and retrieving data
    MemoryAllocator& allocator;

    // Hash table that maps keys to values, with each entry being a vector of values
    HashTable table;
};

// Main function for the command-line tool
int main(int argc, char* argv[]) {
    // Define the size of the hash table and the memory allocator
    const size_t size = 1000000;
    MemoryAllocator allocator;

    // Create a command-line tool with the specified parameters
    CommandLineTool tool(size, allocator);

    // Loop through all the arguments passed to the program
    for (int i = 1; i < argc; ++i) {
        // Parse the current argument as an operation string and a key-value pair
        string op, key, value;
        istringstream iss(argv[i]);
        if (!(iss >> op)) continue;
        if (op != "insert" && op != "get") continue;
        if (!(iss >> key)) continue;
        if (!(iss >> value)) continue;

        // Perform the specified operation on the hash table
        tool.operate(op, key, stof(value));
    }

    return 0;
}
