    if (keys == NULL) {
        perror("Failed to allocate memory for int keys");
        return;
    }

    // Initialize int keys array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < maxRecordValue; i++) {
        keys[i] = rand() % maxRecordValue;
    }

    // Allocate memory for record structures and initialize each record with a random value within the specified range
    record *records = (record *)malloc(sizeof(record) * maxRecordValue);
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        return;
    }
    for (int i = 0; i < maxRecordValue; i++) {
        records[i].value = rand() % maxRecordValue;
    }

    // Establish connection to remote address using Java Channel
    struct sockaddr_in serverAddress;
    memset(&serverAddress, 0, sizeof(serverAddress));
    serverAddress.sin_family = AF_INET;
    inet_pton(AF_INET, remoteAddress, &serverAddress.sin_addr);
    int socketFd = socket(AF_INET, SOCK_STREAM, 0);
    if (socketFd == -1) {
        perror("Failed to create socket");
        return;
    }
    if (connect(socketFd, (struct sockaddr *)&serverAddress, sizeof(serverAddress)) < 0) {
        perror("Failed to connect to remote address");
        return;
    }

    // Handle connection state changes and ensure proper management of the connection lifecycle within the C environment
    fd_set readFds;
    FD_ZERO(&readFds);
    FD_SET(socketFd, &readFds);
    struct timeval timeout = { 1, 0 }; // 1 second timeout
    int selectRetVal = select(socketFd + 1, &readFds, NULL, NULL, &timeout);
    if (selectRetVal == -1) {
        perror("Failed to wait for data");
        return;
    } else if (selectRetVal == 0) {
        printf("No data received from remote address\n");
        close(socketFd);
        return;
    }

    // Update element's HTML content using a service class and return a response indicating that the page should be refreshed
    char *htmlContentUpdate = "UPDATE_HTML_CONTENT";
    write(socketFd, htmlContentUpdate, strlen(htmlContentUpdate));
    close(socketFd);
    printf("Updated element's HTML content successfully\n");
}
