                    retry_count--;
                    if (retry_count <= 0) {
                        crc_indication->valid = false;
                        printf("CR Indication PDU %d is discarded due to failed data transformations\n", i);
                    } else {
                        int backoff = (int)(backoff_factor * pow(2, retry_count - 1) + jitter_factor * rand() / RAND_MAX);
                        sleep(backoff);
                        crc_indication->valid = true;
                    }
                }
            }
            pthread_mutex_unlock(&crc_indication_lock);
        } else {
            // Process CR Indication PDUs as normal if resource usage is within limits
            pthread_mutex_lock(&crc_indication_lock);
            for (int i = 0; i < num_crc_indications; i++) {
                crc_indication = crc_indications[i];
                if (crc_indication->valid) {
