    struct MyAllocator *alloc = (struct MyAllocator *)ptr;
    if (count == 0 || alloc->size >= count) return ptr;
    void *new_mem = malloc(count * sizeof(long));
    memcpy(new_mem, alloc->memory, alloc->used * sizeof(long));
    free(alloc->memory);
    alloc->memory = new_mem;
    alloc->size = count;
    return alloc;
