#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <unistd.h>
#include <pthread.h>

// Define structure for log entry
struct LogEntry {
    time_t timestamp;
    struct in_addr source_ip;
    struct in_addr destination_ip;
    char protocol[4];
    int packet_size;
};

// Define structure for hash table
struct HashTable {
    struct LogEntry** entries;
    size_t capacity;
};

// Define configuration file format
struct ConfigFile {
    char* filtering_criteria;
    int memory_usage_limit;
};

// Function to read log entry from file and validate its integrity
int readLogEntry(FILE* fp, struct LogEntry* entry) {
    // Read timestamp and source IP address
    fscanf(fp, "%d", &entry->timestamp);
    fscanf(fp, "%s", entry->source_ip.s_addr);

    // Validate timestamp and source IP address
    if (entry->timestamp <= 0 || !inet_aton(entry->source_ip.s_addr, &entry->source_ip)) {
        return -1;
    }

    // Read destination IP address, protocol, and packet size
    fscanf(fp, "%s", entry->destination_ip.s_addr);
    fscanf(fp, "%s", entry->protocol);
    fscanf(fp, "%d", &entry->packet_size);

    // Validate destination IP address and protocol
    if (!inet_aton(entry->destination_ip.s_addr, &entry->destination_ip) || strcmp(entry->protocol, "TCP") && strcmp(entry->protocol, "UDP")) {
        return -1;
    }

    // Return success
    return 0;
}

// Function to parse log entry and categorize it based on filtering criteria
int processLogEntry(struct LogEntry* entry, struct ConfigFile* config) {
    // Check if source IP address or destination IP address matches filtering criteria
    for (int i = 0; i < config->num_filters; i++) {
        if (strcmp(entry->source_ip.s_addr, config->filters[i].source_ip.s_addr) == 0 || strcmp(entry->destination_ip.s_addr, config->filters[i].destination_ip.s_addr) == 0) {
            return i;
        }
    }

    // Return -1 if no match found
    return -1;
}

// Function to add log entry to hash table and update memory usage
void addLogEntry(struct HashTable* table, struct LogEntry* entry) {
    // Check if hash table is full
    if (table->capacity == 0) {
        // Resize hash table if necessary
        table->capacity *= 2;
        table->entries = realloc(table->entries, table->capacity * sizeof(struct LogEntry*));
    }

    // Add log entry to hash table
    table->entries[table->size++] = entry;
}

// Function to remove duplicate entries from hash table and update memory usage
void removeDuplicateEntries(struct HashTable* table) {
    // Initialize hash set for fast lookups of unique IP addresses
    struct HashSet {
        int* ips;
        size_t capacity;
    } ip_set = {NULL, 0};

    // Iterate over log entries in hash table
    for (int i = 0; i < table->size; i++) {
        struct LogEntry* entry = table->entries[i];
        if (!checkDuplicate(ip_set, &entry->source_ip) && !checkDuplicate(ip_set, &entry->destination_ip)) {
            addLogEntry(&ip_set, &entry->source_ip);
            addLogEntry(&ip_set, &entry->destination_ip);
        }
    }
}

// Function to check if IP address is a duplicate in hash set
int checkDuplicate(struct HashSet* set, struct in_addr* ip) {
    // Iterate over IP addresses in hash set
    for (int i = 0; i < set->capacity; i++) {
        if (!inet_aton(set->ips[i], &set->ips[i])) {
            return -1;
        }
        if (strcmp(ip->s_addr, set->ips[i]) == 0) {
            // Return index of duplicate IP address in hash set
            return i;
        }
    }

    // Return -1 if no match found
    return -1;
}

// Function to periodically clear hash table and free unused memory
void cleanupHashTable(struct HashTable* table, int memory_usage_limit) {
    // Check if memory usage limit has been reached
    if (table->size * sizeof(struct LogEntry*) >= memory_usage_limit) {
        // Resize hash table to fit new number of entries
        int new_capacity = table->size / 2;
        struct HashTable* new_table = malloc(new_capacity * sizeof(struct LogEntry*));

        // Copy log entries from old table to new table
        for (int i = 0, j = 0; i < table->size && j < new_capacity; i++) {
            if (table->entries[i] != NULL) {
                new_table->entries[j++] = table->entries[i];
            }
        }

        // Update hash table with new table
        free(table);
        table = new_table;
    }
}

// Function to process network logs and categorize them based on filtering criteria
struct LogEntry** processNetworkLogs(char* log_file, struct ConfigFile* config) {
    // Open file for reading
    FILE* fp = fopen(log_file, "r");
    if (fp == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    // Initialize hash table and config file parsing variables
    struct HashTable table = {{NULL}, 0};
    int num_entries = 0;
    int memory_usage_limit = config->memory_usage_limit;

    // Iterate over log entries in file
    while (readLogEntry(fp, &entry) == 0) {
        // Categorize log entry based on filtering criteria
        int category = processLogEntry(&entry, config);

        // Add log entry to hash table if not a duplicate
        if (category != -1) {
            addLogEntry(&table, &entry);
            num_entries++;
        }
    }

    // Remove duplicate entries from hash table and update memory usage
    removeDuplicateEntries(&table);
    cleanupHashTable(&table, memory_usage_limit);

    // Return pointer to dynamically allocated structure containing categorized logs
    return table.entries;
}
