// Define the structure for the records
typedef struct {
    int key;
    long offset;
} Record;

// Define the function to manage the collection of records
void manage_records(int num_records, int* keys, long* offsets) {
    // Allocate memory for the record pool
    Record* record_pool = malloc(sizeof(Record) * num_records);

    // Initialize the semaphore for concurrent access
    sem_t sem;
    sem_init(&sem, 0, 1);

    // Loop through each record and add it to the pool
    for (int i = 0; i < num_records; i++) {
        Record* record = &record_pool[i];
        record->key = keys[i];
        record->offset = offsets[i];
        sem_post(&sem);
    }

    // Sort the records based on their integer values
    qsort(record_pool, num_records, sizeof(Record), compare_keys);

    // Serialize the collection into a file
    FILE* file = fopen("records.bin", "wb");
    if (!file) {
        perror("fopen");
        exit(1);
    }
    fwrite(record_pool, sizeof(Record), num_records, file);
    fclose(file);

    // Expand the pool of available keys as needed
    int new_key = 0;
    for (int i = 0; i < num_records; i++) {
        Record* record = &record_pool[i];
        if (record->key == new_key) {
            new_key++;
        }
    }

    // Ensure the system can handle external dependencies, including third-party libraries for file I/O operations
    FILE* file = fopen("records.bin", "rb");
    if (!file) {
        perror("fopen");
        exit(1);
    }
    fread(record_pool, sizeof(Record), num_records, file);
    fclose(file);

    // Clean up the semaphore and record pool
    sem_destroy(&sem);
    free(record_pool);
}

// Define a custom comparison function for sorting records based on their integer values
int compare_keys(const void* a, const void* b) {
    Record* record_a = (Record*)a;
    Record* record_b = (Record*)b;
    return record_a->key - record_b->key;
}
```
