// Structure to represent a record
typedef struct Record {
    int key;
    long offset;
} Record;

// Custom allocator for managing memory
void* custom_alloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Handle allocation failure
        fprintf(stderr, "Failed to allocate memory\n");
        exit(1);
    }
    return ptr;
}

// Custom deallocator for freeing memory
void custom_free(void* ptr) {
    if (ptr) {
        free(ptr);
    }
}

// Function to resize the arrays based on user input
void resize_arrays(int key_size, int offset_size) {
    // Check for overflows and handle them gracefully
    if (key_size < 0 || offset_size < 0) {
        fprintf(stderr, "Invalid size input\n");
        exit(1);
    }
    Record* new_records = custom_alloc(sizeof(Record) * key_size * offset_size);
    if (new_records) {
        // Replace the old arrays with the new ones
        custom_free(records);
        records = new_records;
        keys = custom_alloc(key_size * sizeof(int));
        offsets = custom_alloc(offset_size * sizeof(long));
    } else {
        // Handle allocation failure
        fprintf(stderr, "Failed to allocate memory\n");
        exit(1);
    }
}

// Function to add a record to the arrays
void add_record(int key, long offset) {
    // Check if the arrays need to be resized
    if (key_size == 0 || offset_size == 0) {
        resize_arrays(16, 16);
    } else if (keys[key_size - 1] == key || offsets[offset_size - 1] == offset) {
        // Check for duplicates and resize the arrays accordingly
        int new_key_size = key_size * 2;
        int new_offset_size = offset_size * 2;
        resize_arrays(new_key_size, new_offset_size);
    }
    // Add the record to the arrays
    records[key_size++] = (Record){key, offset};
    keys[key_size - 1] = key;
    offsets[offset_size++] = offset;
}

// Function to remove a record from the arrays
void remove_record(int key) {
    // Find the index of the record in the keys array
    int i = 0;
    while (i < key_size && keys[i] != key) {
        i++;
    }
    if (i == key_size) {
        return;
    }
    // Remove the corresponding offset from the offsets array
    for (int j = 0; j < offset_size; j++) {
        if (offsets[j] == records[i].offset) {
            offsets[j--] = offsets[--offset_size];
        }
    }
    // Shift all the remaining records to the left
    for (int j = i; j < key_size - 1; j++) {
        records[j] = records[j + 1];
        keys[j] = keys[j + 1];
    }
    key_size--;
}

// Function to search for a record in the arrays
int search_record(int key) {
    // Find the index of the record in the keys array
    int i = 0;
    while (i < key_size && keys[i] != key) {
        i++;
    }
    return i == key_size ? -1 : records[i].offset;
}
