#define NUM_RECORDS 3
#define KEY_VALUE_RANGE 100
#define BUFFER_SIZE 256

typedef struct {
    int key;
    char *buffer;
} Record;

void initialize_records(Record *records) {
    for (int i = 0; i < NUM_RECORDS; i++) {
        records[i].key = rand() % KEY_VALUE_RANGE;
        sprintf(records[i].buffer, "%d", records[i].key);
    }
}

void establish_connection(char *host, int port) {
    // create a socket for the connection
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        exit(1);
    }

    // populate the address struct with host and port information
    struct addrinfo hints, *addr;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(host, NULL, &hints, &addr) != 0) {
        perror("getaddrinfo");
        exit(1);
    }

    // connect to the remote address
    if (connect(sock, addr->ai_addr, addr->ai_addrlen) < 0) {
        perror("connect");
        exit(1);
    }

    freeaddrinfo(addr);
}

void send_records(Record *records) {
    // create a thread-safe mutex for managing concurrent access to the connection
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // establish the connection and initialize the connection status flag
    char *host = "example.com";
    int port = 80;
    establish_connection(host, port);
    bool is_connected = true;

    // loop through each record and send it over the established channel
    for (int i = 0; i < NUM_RECORDS; i++) {
        Record *record = &records[i];

        pthread_mutex_lock(&lock);
        if (!is_connected) {
            // re-establish the connection if it has been closed
            establish_connection(host, port);
            is_connected = true;
        }

        send(sock, record->buffer, BUFFER_SIZE, 0);
        pthread_mutex_unlock(&lock);
    }

    // close the connection and release resources
    close(sock);
    pthread_mutex_destroy(&lock);
}
