        for (int j = 0; j < num_protocols; ++j) {
            const char *proto = json_string_value(json_array_get(protocols, j));
            if (proto == NULL) {
                fprintf(stderr, "error: invalid protocol\n");
                goto out;
            }
            s->protocols[j] = strdup(proto);
        }
    }
out:
    if (root != NULL) {
        json_decref(root);
    }
}
