#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

#define MAX_CONNECTIONS 1024
#define MIN_RANDOM_KEY 1
#define MAX_RANDOM_KEY 65535

typedef struct {
    long offset;
    int key;
    NetworkChannel *channel;
} ConnectionPoolRecord;

ConnectionPoolRecord *connectionPool = NULL;
int numConnections = 0;
int maxConnections = MAX_CONNECTIONS;
int minRandomKey = MIN_RANDOM_KEY;
int maxRandomKey = MAX_RANDOM_KEY;

bool initializeConnectionPool(const char *ipAddress, int port) {
    // allocate memory for the connection pool
    connectionPool = (ConnectionPoolRecord *)malloc(maxConnections * sizeof(ConnectionPoolRecord));
    if (!connectionPool) {
        printf("Error: unable to allocate memory for connection pool\n");
        return false;
    }

    // initialize each record's key with a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < maxConnections; i++) {
        int randomKey = rand() % (maxRandomKey - minRandomKey + 1) + minRandomKey;
        connectionPool[i].key = randomKey;
    }

    // initialize each record's channel with a new NetworkChannel object
    for (int i = 0; i < maxConnections; i++) {
        connectionPool[i].channel = createNetworkChannel(ipAddress, port);
        if (!connectionPool[i].channel) {
            printf("Error: unable to create network channel\n");
            return false;
        }
    }

    numConnections = maxConnections;

    return true;
}

bool openConnection(const char *ipAddress, int port) {
    if (numConnections == maxConnections) {
        // maximum number of connections has been reached, retry after a delay
        printf("Warning: maximum number of connections has been reached, retrying in 1 second\n");
        sleep(1);
        return openConnection(ipAddress, port);
    }

    // find the first available connection record
    int i = 0;
    while (i < maxConnections && connectionPool[i].channel) {
        i++;
    }

    if (i == maxConnections) {
        printf("Error: unable to open connection, no available records\n");
        return false;
    }

    // allocate a new NetworkChannel object and assign it to the record
    connectionPool[i].channel = createNetworkChannel(ipAddress, port);
    if (!connectionPool[i].channel) {
        printf("Error: unable to create network channel\n");
        return false;
    }

    numConnections++;

    return true;
}

bool closeConnection(const char *ipAddress, int port) {
    if (numConnections == 0) {
        printf("Error: unable to close connection, no open connections\n");
        return false;
    }

    // find the first available connection record
    int i = 0;
    while (i < maxConnections && strcmp(connectionPool[i].channel->ipAddress, ipAddress) != 0 || connectionPool[i].channel->port != port) {
        i++;
    }

    if (i == maxConnections) {
        printf("Error: unable to close connection, no matching records found\n");
        return false;
    }

    // deallocate the NetworkChannel object and mark the record as closed
    destroyNetworkChannel(connectionPool[i].channel);
    connectionPool[i].channel = NULL;

    numConnections--;

    return true;
}

bool isConnectionOpen(const char *ipAddress, int port) {
    if (numConnections == 0) {
        return false;
    }

    // find the first available connection record
    int i = 0;
    while (i < maxConnections && strcmp(connectionPool[i].channel->ipAddress, ipAddress) != 0 || connectionPool[i].channel->port != port) {
        i++;
    }

    if (i == maxConnections) {
        return false;
    }

    return true;
}

bool sendData(const char *ipAddress, int port, const void *data, size_t dataSize) {
    if (!isConnectionOpen(ipAddress, port)) {
        printf("Error: unable to send data, connection is not open\n");
        return false;
    }

    // find the first available connection record
    int i = 0;
    while (i < maxConnections && strcmp(connectionPool[i].channel->ipAddress, ipAddress) != 0 || connectionPool[i].channel->port != port) {
        i++;
    }

    if (i == maxConnections) {
        printf("Error: unable to send data, no matching records found\n");
        return false;
    }

    // send the data over the network channel
    int ret = connectionPool[i].channel->send(data, dataSize);
    if (ret < 0) {
        printf("Error: unable to send data over network channel\n");
        return false;
    }

    return true;
}
