// Define the structure for the log entries
typedef struct {
    int level;
    char* message;
    struct record* records;
} log_entry;

// Define the structure for the records
typedef struct {
    time_t timestamp;
    const char* name;
    char* description;
} record;

// Define a mutex to protect the linked list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to initialize an array of log entries
void init_log_entries(int n, int level, char* message) {
    // Allocate memory for the log entries
    log_entry* entries = malloc(n * sizeof(log_entry));
    if (!entries) {
        perror("malloc");
        exit(1);
    }

    // Initialize the log levels and messages
    for (int i = 0; i < n; i++) {
        entries[i].level = level;
        entries[i].message = message;
    }

    // Create a linked list of records for each entry
    for (int i = 0; i < n; i++) {
        int num_records = rand() % 10 + 1;
        entries[i].records = malloc(num_records * sizeof(record));
        if (!entries[i].records) {
            perror("malloc");
            exit(1);
        }

        for (int j = 0; j < num_records; j++) {
            entries[i].records[j].timestamp = time(NULL);
            entries[i].records[j].name = "Record #" + i * n + j;
            entries[i].records[j].description = "This is a description for record #" + i * n + j;
        }
    }
}

// Define a function to simulate various logging scenarios
void log_scenario(int scenario) {
    // Simulate a logging scenario
    switch (scenario) {
        case 1:
            // Log an error message with a record
            log_entry* entry = malloc(sizeof(log_entry));
            if (!entry) {
                perror("malloc");
                exit(1);
            }

            entry->level = LOG_ERROR;
            entry->message = "This is an error message with a record";
            entry->records = malloc(sizeof(record));
            if (!entry->records) {
                perror("malloc");
                exit(1);
            }

            entry->records[0].timestamp = time(NULL);
            entry->records[0].name = "Record #1";
            entry->records[0].description = "This is a description for record #1";
            break;
        case 2:
            // Log a warning message without a record
            log_entry* entry = malloc(sizeof(log_entry));
            if (!entry) {
                perror("malloc");
                exit(1);
            }

            entry->level = LOG_WARNING;
            entry->message = "This is a warning message without a record";
            break;
        case 3:
            // Log an information message with multiple records
            log_entry* entry = malloc(sizeof(log_entry));
            if (!entry) {
                perror("malloc");
                exit(1);
            }

            entry->level = LOG_INFO;
            entry->message = "This is an information message with multiple records";
            int num_records = rand() % 10 + 1;
            entry->records = malloc(num_records * sizeof(record));
            if (!entry->records) {
                perror("malloc");
                exit(1);
            }

            for (int i = 0; i < num_records; i++) {
                entry->records[i].timestamp = time(NULL);
                entry->records[i].name = "Record #" + i * n + j;
                entry->records[i].description = "This is a description for record #" + i * n + j;
            }
    }
}

// Define a function to traverse the linked list of records associated with each log entry
void traverse_records(log_entry* entry) {
    // Acquire the mutex to protect the linked list
    pthread_mutex_lock(&mutex);

    // Traverse the linked list of records
    record* current = entry->records;
    while (current != NULL) {
        printf("Record: %s\n", current->name);
        current = current->next;
    }

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}
```
