#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <stdbool.h>
#include <assert.h>
#include <stdint.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <limits.h>
#include <semaphore.h>

#define MAX_CONCURRENT_REQUESTS 100
#define CACHE_SIZE 10000
#define LRU_EVICTION_STRATEGY 1
#define TTL_EVICTION_STRATEGY 2
#define EXPIRATION_TIMEOUT 3600 /* seconds */

typedef struct {
    char* key;
    void* value;
} cache_entry_t;

cache_entry_t* cache = NULL;
sem_t semaphore;
int cache_size = 0;
int cache_max_size = CACHE_SIZE;
bool lru_eviction_strategy = true;
bool ttl_eviction_strategy = false;
int64_t expiration_timeout = EXPIRATION_TIMEOUT * 1000000; /* microseconds */

void cache_init() {
    int err;
    sem_unlink("cache_semaphore");
    err = sem_init(&semaphore, 0, MAX_CONCURRENT_REQUESTS);
    if (err != 0) {
        perror("Error creating semaphore");
        exit(1);
    }
    cache = malloc(sizeof(cache_entry_t) * CACHE_SIZE);
    if (cache == NULL) {
        perror("Error allocating memory for cache");
        exit(1);
    }
}

void cache_destroy() {
    int err;
    err = sem_destroy(&semaphore);
    if (err != 0) {
        perror("Error destroying semaphore");
        exit(1);
    }
    free(cache);
}

int get_cache_size() {
    return cache_size;
}

void set_cache_size(int new_size) {
    int err;
    err = sem_wait(&semaphore);
    if (err != 0) {
        perror("Error waiting for semaphore");
        exit(1);
    }
    cache_max_size = new_size;
    err = sem_post(&semaphore);
    if (err != 0) {
        perror("Error posting to semaphore");
        exit(1);
    }
}

bool is_cache_full() {
    int err;
    bool full;
    err = sem_wait(&semaphore);
    if (err != 0) {
        perror("Error waiting for semaphore");
        exit(1);
    }
    full = cache_size >= cache_max_size;
    err = sem_post(&semaphore);
    if (err != 0) {
        perror("Error posting to semaphore");
        exit(1);
    }
    return full;
}

void add_cache_entry(char* key, void* value) {
    int err;
    cache_entry_t entry = {key, value};
    err = sem_wait(&semaphore);
    if (err != 0) {
        perror("Error waiting for semaphore");
        exit(1);
    }
    if (is_cache_full()) {
        evict_least_recently_used();
    }
    cache[cache_size++] = entry;
    err = sem_post(&semaphore);
    if (err != 0) {
        perror("Error posting to semaphore");
        exit(1);
    }
}

void update_cache_entry(char* key, void* value) {
    int err;
    bool found = false;
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(key, cache[i].key) == 0) {
            cache[i].value = value;
            found = true;
            break;
        }
    }
    if (!found) {
        add_cache_entry(key, value);
    }
}

void get_cache_entry(char* key, void** value) {
    int err;
    bool found = false;
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(key, cache[i].key) == 0) {
            *value = cache[i].value;
            found = true;
            break;
        }
    }
    if (!found) {
        *value = NULL;
    }
}

void evict_least_recently_used() {
    int64_t min_ts = 0;
    int min_idx = -1;
    for (int i = 0; i < cache_size; i++) {
        if (min_idx == -1 || min_ts > cache[i].timestamp) {
            min_idx = i;
            min_ts = cache[i].timestamp;
        }
    }
    cache[min_idx] = NULL;
}

void evict_least_frequently_used() {
    int64_t min_freq = INT_MAX;
    int min_idx = -1;
    for (int i = 0; i < cache_size; i++) {
        if (min_idx == -1 || min_freq > cache[i].frequency) {
            min_idx = i;
            min_freq = cache[i].frequency;
        }
    }
    cache[min_idx] = NULL;
}

void purge_cache() {
    int err;
    for (int i = 0; i < cache_size; i++) {
        if (cache[i].value == NULL) {
            continue;
        }
        void* value = cache[i].value;
        free(value);
        cache[i] = NULL;
    }
}

void set_lru_eviction_strategy() {
    int err;
    lru_eviction_strategy = true;
    ttl_eviction_strategy = false;
    err = sem_wait(&semaphore);
    if (err != 0) {
        perror("Error waiting for semaphore");
        exit(1);
    }
    purge_cache();
    err = sem_post(&semaphore);
    if (err != 0) {
        perror("Error posting to semaphore");
        exit(1);
    }
}

void set_ttl_eviction_strategy() {
    int err;
    lru_eviction_strategy = false;
    ttl_eviction_strategy = true;
    err = sem_wait(&semaphore);
    if (err != 0) {
        perror("Error waiting for semaphore");
        exit(1);
    }
    purge_cache();
    err = sem_post(&semaphore);
    if (err != 0) {
        perror("Error posting to semaphore");
        exit(1);
    }
}

void set_expiration_timeout(int64_t new_timeout) {
    int err;
    expiration_timeout = new_timeout * 1000000; /* microseconds */
    err = sem_wait(&semaphore);
    if (err != 0) {
        perror("Error waiting for semaphore");
        exit(1);
    }
    purge_cache();
    err = sem_post(&semaphore);
    if (err != 0) {
        perror("Error posting to semaphore");
        exit(1);
    }
}
