#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

// Record structure definition
struct record {
    int key;
    long offset;
    int value;
};

// Data structure for managing multiple record sets
struct record_set {
    struct record* records; // Array of records
    size_t num_records; // Number of records in the set
    size_t capacity; // Maximum number of records in the set
};

// Data structure for managing all record sets
struct record_manager {
    struct record_set** sets; // Array of record sets
    size_t num_sets; // Number of record sets
    size_t capacity; // Maximum number of record sets
    pthread_mutex_t lock; // Lock for thread-safe access to the record manager
};

// Initialize a new record set with given capacity
struct record_set* init_record_set(size_t capacity) {
    struct record_set* set = (struct record_set*)malloc(sizeof(struct record_set));
    if (!set) return NULL;

    // Allocate memory for records
    set->records = (struct record*)calloc(capacity, sizeof(struct record));
    if (!set->records) {
        free(set);
        return NULL;
    }

    // Initialize other fields
    set->num_records = 0;
    set->capacity = capacity;

    return set;
}

// Free a record set and all its records
void free_record_set(struct record_set* set) {
    if (!set) return;

    // Free the record array
    free(set->records);

    // Free the set structure
    free(set);
}

// Add a new record to the given record set
int add_record(struct record_set* set, int key, long offset, int value) {
    pthread_mutex_lock(&set->lock);

    // Check if the set is full
    if (set->num_records == set->capacity) {
        pthread_mutex_unlock(&set->lock);
        return -1;
    }

    // Add the record to the set
    struct record* rec = &set->records[set->num_records++];
    rec->key = key;
    rec->offset = offset;
    rec->value = value;

    pthread_mutex_unlock(&set->lock);

    return 0;
}

// Remove a record from the given record set by index
int remove_record(struct record_set* set, size_t index) {
    pthread_mutex_lock(&set->lock);

    // Check if the index is valid
    if (index >= set->num_records) {
        pthread_mutex_unlock(&set->lock);
        return -1;
    }

    // Shift all records after the given index down by one
    for (size_t i = index + 1; i < set->num_records; ++i) {
        struct record* rec = &set->records[i];
        memmove(rec, rec + 1, sizeof(struct record));
    }

    // Decrement the number of records in the set
    --set->num_records;

    pthread_mutex_unlock(&set->lock);

    return 0;
}

// Find a record in the given record set by key
struct record* find_record(struct record_set* set, int key) {
    // Linear search for the record with the given key
    for (size_t i = 0; i < set->num_records; ++i) {
        struct record* rec = &set->records[i];
        if (rec->key == key) return rec;
    }

    // Record not found
    return NULL;
}

// Get the total number of records across all sets
size_t get_num_records(struct record_manager* manager) {
    size_t num_records = 0;
    for (size_t i = 0; i < manager->num_sets; ++i) {
        struct record_set* set = manager->sets[i];
        num_records += set->num_records;
    }

    return num_records;
}

// Get a record by index across all sets
struct record* get_record(struct record_manager* manager, size_t index) {
    // Linear search for the record with the given index
    for (size_t i = 0; i < manager->num_sets; ++i) {
        struct record_set* set = manager->sets[i];
        if (index >= set->num_records) continue;

        struct record* rec = &set->records[index];
        return rec;
    }

    // Record not found
    return NULL;
}

// Free a record manager and all its record sets and records
void free_record_manager(struct record_manager* manager) {
    if (!manager) return;

    // Free all record sets
    for (size_t i = 0; i < manager->num_sets; ++i) {
        struct record_set* set = manager->sets[i];
        free_record_set(set);
    }

    // Free the record manager structure
    free(manager->sets);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
