#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Data structure to represent a record
typedef struct {
    int key;
    long offset;
    int value;
} Record;

// Function to create and initialize a new record
Record *create_record(int key, long offset, int value) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        printf("Error: Failed to allocate memory for new record.\n");
        exit(1);
    }

    record->key = key;
    record->offset = offset;
    record->value = value;

    return record;
}

// Function to add a new record to the collection
void add_record(Record **records, int num_records, int key, long offset, int value) {
    // Check if the record already exists in the collection
    for (int i = 0; i < num_records; i++) {
        if (records[i]->key == key && records[i]->offset == offset) {
            records[i]->value = value;
            return;
        }
    }

    // If the record does not exist, create a new one and add it to the collection
    Record *new_record = create_record(key, offset, value);
    if (new_record) {
        records[num_records++] = new_record;
    }
}

// Function to remove a record from the collection
void remove_record(Record **records, int num_records, int key, long offset) {
    // Find the index of the record to be removed
    int idx = -1;
    for (int i = 0; i < num_records; i++) {
        if (records[i]->key == key && records[i]->offset == offset) {
            idx = i;
            break;
        }
    }

    // If the record is found, remove it from the collection
    if (idx != -1) {
        // Shift all records after the removed one to fill the gap
        for (int i = idx; i < num_records - 1; i++) {
            records[i] = records[i + 1];
        }

        // Decrease the number of records by 1
        num_records--;
    }
}

// Function to query a record from the collection
void *query_record(Record **records, int num_records, int key, long offset) {
    // Find the index of the requested record
    for (int i = 0; i < num_records; i++) {
        if (records[i]->key == key && records[i]->offset == offset) {
            return records[i];
        }
    }

    // If the record is not found, return NULL
    return NULL;
}

// Function to update a record in the collection
void update_record(Record **records, int num_records, int key, long offset, int value) {
