    }
}

// Function to manage memory allocation for a large number of records
void allocate_records(Record ***records, int *num_records, int size) {
    // Allocate memory for the record collection
    *records = (Record **)malloc(sizeof(Record *) * size);
    if (!*records) {
        printf("Error: Failed to allocate memory for record collection.\n");
        exit(1);
    }

    // Initialize each record in the collection
    for (int i = 0; i < size; i++) {
        (*records)[i] = NULL;
    }

    *num_records = 0;
}

// Function to deallocate memory allocated for a record collection
void free_records(Record **records, int num_records) {
    // Free each record in the collection
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
}

// Thread-safe function to add a new record to the collection
void thread_add_record(Record **records, int *num_records, int key, long offset, int value) {
    pthread_mutex_lock(&mutex);
    add_record(records, *num_records, key, offset, value);
    pthread_mutex_unlock(&mutex);
}

// Thread-safe function to remove a record from the collection
void thread_remove_record(Record **records, int *num_records, int key, long offset) {
    pthread_mutex_lock(&mutex);
    remove_record(records, *num_records, key, offset);
    pthread_mutex_unlock(&mutex);
}

// Thread-safe function to query a record from the collection
void thread_query_record(Record **records, int num_records, int key, long offset) {
    pthread_mutex_lock(&mutex);
    void *result = query_record(records, num_records, key, offset);
    pthread_mutex_unlock(&mutex);
}

// Thread-safe function to update a record in the collection
void thread_update_record(Record **records, int *num_records, int key, long offset, int value) {
    pthread_mutex_lock(&mutex);
    update_record(records, *num_records, key, offset, value);
    pthread_mutex_unlock(&mutex);
}
