struct connection_pool {
    pthread_mutex_t mutex;
    int num_connections;
    int max_connections;
    record_t** connections;
};

// Function to initialize the connection pool
void init_connection_pool(struct connection_pool* pool, int max_connections) {
    // Allocate memory for the connections array
    pool->connections = (record_t**)malloc(sizeof(record_t*) * max_connections);
    if (!pool->connections) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the mutex for synchronization
    pthread_mutex_init(&pool->mutex, NULL);

    // Set the maximum number of connections and initialize the counter
    pool->max_connections = max_connections;
    pool->num_connections = 0;

    // Initialize the connections array with NULL pointers
    for (int i = 0; i < max_connections; i++) {
        pool->connections[i] = NULL;
    }
}

// Function to allocate a new connection
record_t* allocate_connection(struct connection_pool* pool) {
    // Acquire the mutex lock
    pthread_mutex_lock(&pool->mutex);

    // Check if there are any free connections available
    for (int i = 0; i < pool->max_connections; i++) {
        if (!pool->connections[i]) {
            // Allocate a new connection
            record_t* conn = (record_t*)malloc(sizeof(record_t));
            if (!conn) {
                printf("Memory allocation failed\n");
                pthread_mutex_unlock(&pool->mutex);
                return NULL;
            }

            // Initialize the connection key and offset
            conn->key = rand() % 10000 + 1;
            conn->offset = -1;

            // Add the connection to the pool
            pool->connections[i] = conn;
            pool->num_connections++;

            // Release the mutex lock and return the connection
            pthread_mutex_unlock(&pool->mutex);
            return conn;
        }
    }

    // Release the mutex lock and return NULL if no free connections are available
    pthread_mutex_unlock(&pool->mutex);
    return NULL;
}

// Function to deallocate a connection
void deallocate_connection(struct connection_pool* pool, record_t* conn) {
    // Acquire the mutex lock
    pthread_mutex_lock(&pool->mutex);

    // Find the index of the connection in the pool
    int i;
    for (i = 0; i < pool->max_connections; i++) {
        if (pool->connections[i] == conn) {
            break;
        }
    }

    // Check if the connection was found in the pool
    if (i >= pool->max_connections) {
        printf("Connection not found in pool\n");
        pthread_mutex_unlock(&pool->mutex);
        return;
    }

    // Deallocate the connection and remove it from the pool
    free(conn);
    pool->connections[i] = NULL;
    pool->num_connections--;

    // Release the mutex lock
    pthread_mutex_unlock(&pool->mutex);
}

// Function to get a connection from the pool
record_t* get_connection(struct connection_pool* pool, int device_id) {
    // Acquire the mutex lock
    pthread_mutex_lock(&pool->mutex);

    // Check if there is a free connection available for the given device ID
    for (int i = 0; i < pool->max_connections; i++) {
        if (pool->connections[i] && pool->connections[i]->key == device_id) {
            record_t* conn = pool->connections[i];
            pool->connections[i] = NULL;
            pool->num_connections--;
            pthread_mutex_unlock(&pool->mutex);
            return conn;
        }
    }

    // Release the mutex lock and return NULL if no free connection is available
    pthread_mutex_unlock(&pool->mutex);
    return NULL;
}

// Function to release a connection back to the pool
void release_connection(struct connection_pool* pool, record_t* conn) {
    // Acquire the mutex lock
    pthread_mutex_lock(&pool->mutex);

    // Check if the connection is already in the pool
    for (int i = 0; i < pool->max_connections; i++) {
        if (pool->connections[i] == conn) {
            printf("Connection already exists in pool\n");
            pthread_mutex_unlock(&pool->mutex);
            return;
        }
    }

    // Add the connection to the pool and release the mutex lock
    pool->connections[pool->num_connections] = conn;
    pool->num_connections++;
    pthread_mutex_unlock(&pool->mutex);
}

