        pool->network_configs[i].version = 0;
        pool->network_configs[i].supported_protocols = NULL;
    }
}

// Function to update the network configuration data structure with new protocol lists
void update_network_config(struct connection_pool* pool, int num_elements) {
    // Check if the new number of elements is larger than the current capacity
    if (num_elements > pool->max_connections) {
        printf("New number of elements exceeds maximum capacity\n");
        return;
    }

    // Update the number of elements in the network configuration data structure
    pool->num_elements = num_elements;

    // Allocate memory for the new protocol lists
    pool->network_configs[pool->max_connections].supported_protocols = (char**)malloc(sizeof(char*) * num_elements);
    if (!pool->network_configs[pool->max_connections].supported_protocols) {
        printf("Memory allocation failed\n");
        return;
