        pool->network_configs[i].version = 0;
        pool->network_configs[i].supported_protocols = NULL;
    }
}

// Function to randomly shuffle the network configuration data structure
void shuffle_network_config(struct connection_pool* pool) {
    // Implement a randomized algorithm to shuffle the network configurations
    // For simplicity, this implementation uses a simple Fisher-Yates shuffle
    for (int i = 0; i < pool->num_elements - 1; i++) {
        int j = rand() % (pool->num_elements - i);
        record_t temp = pool->network_configs[i];
        pool->network_configs[i] = pool->network_configs[i + j];
