    for (size_t i = 0; i < pool->num_items; i++) {
        pool->items[i].value = transformation(pool->items[i].value);
    }
    unlock(&pool->mutex);
}

// Function to filter and aggregate `item` records based on their `double` values and `int` indices, allowing users to specify filtering criteria and aggregation functions
void filter_and_aggregate(struct pool* pool, double(*filter)(double), double(*aggregate)(double)) {
    lock(&pool->mutex);
    for (size_t i = 0; i < pool->num_items; i++) {
        if (filter(pool->items[i].value)) {
            aggregate(pool->items[i].value);
        }
    }
    unlock(&pool->mutex);
}

// Function to handle memory exhaustion and fragmentation in a distributed system
void handle_memory_exhaustion(struct pool* pool) {
    lock(&pool->mutex);
    if (pool->num_items == 0) {
        deallocate_item(pool, NULL);
    } else {
        size_t i = 0;
        while (i < pool->num_items && pool->items[i].value != 0.0) {
            i++;
        }
        if (i == pool->num_items) {
            deallocate_item(pool, &pool->items[i - 1]);
        } else {
            deallocate_item(pool, &pool->items[i]);
        }
    }
    unlock(&pool->mutex);
}
