// Function to allocate memory blocks from a memory pool
void *allocateMemory(size_t size) {
    // Check if the memory pool is initialized
    if (memory_pool == NULL) {
        fprintf(stderr, "Error: Memory pool is not initialized\n");
        exit(EXIT_FAILURE);
    }

    // Loop through the memory pool until a free block of sufficient size is found
    for (int i = 0; i < MEMORY_POOL_SIZE; i++) {
        if (memory_pool[i] == NULL) {
            continue;
        } else if (size <= MEMORY_BLOCK_SIZE) {
            // If a free block of sufficient size is found, return it to the caller
            void *block = memory_pool[i];
            memory_pool[i] = NULL;
            return block;
        }
    }

    // If no free block of sufficient size is found, allocate a new block of memory
    void *block = malloc(size);
    if (block == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    return block;
}

// Function to deallocate memory blocks from a memory pool
void deallocateMemory(void *block) {
    // Check if the memory pool is initialized
    if (memory_pool == NULL) {
        fprintf(stderr, "Error: Memory pool is not initialized\n");
        exit(EXIT_FAILURE);
    }

    // Loop through the memory pool until a matching block of memory is found
    for (int i = 0; i < MEMORY_POOL_SIZE; i++) {
        if (memory_pool[i] == block) {
            // If a matching block of memory is found, mark it as free
            memory_pool[i] = NULL;
            break;
        }
    }
}
