void* allocate_and_initialize_memory(int num_offsets, int num_keys, int num_records) {
    // Allocate memory for the offsets and keys arrays
    long *offsets = malloc(num_offsets * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets array\n");
        return NULL;
    }
    int *keys = malloc(num_keys * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for keys array\n");
        free(offsets);
        return NULL;
    }

    // Initialize the offsets and keys arrays with sequential values
    int i = 0;
    for (i = 0; i < num_offsets; i++) {
        offsets[i] = i * sizeof(long);
    }
    for (i = 0; i < num_keys; i++) {
        keys[i] = -1;
    }

    // Handle potential overflow conditions when initializing the arrays
    if (num_offsets > INT_MAX / sizeof(long) || num_keys > INT_MAX / sizeof(int)) {
        fprintf(stderr, "Overflow detected in initialization of offsets and keys arrays\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Allocate memory for the struct record objects
    record_t *records = malloc(num_records * sizeof(record_t));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records array\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the values of each record with a random value between 1 and 100
    srand((unsigned int)time(NULL));
    for (i = 0; i < num_records; i++) {
        records[i].value = rand() % 100 + 1;
    }

    // Combine the offsets and keys arrays with the records array
    void *memory_block = malloc(num_offsets * sizeof(long) + num_keys * sizeof(int) + num_records * sizeof(record_t));
    if (memory_block == NULL) {
        fprintf(stderr, "Failed to allocate memory for the combined array\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }
    memcpy(memory_block, offsets, num_offsets * sizeof(long));
    memcpy((char*)memory_block + num_offsets * sizeof(long), keys, num_keys * sizeof(int));
    memcpy((char*)memory_block + (num_offsets + num_keys) * sizeof(long), records, num_records * sizeof(record_t));

    // Free any unnecessary memory and return the combined array
    free(offsets);
    free(keys);
    free(records);
    return memory_block;
}
