void init_arrays(int num_records, int min_key, int max_key, long min_offset, long max_offset) {
    // Check if input parameters are valid
    if (num_records <= 0 || min_key > max_key || min_offset > max_offset) {
        printf("Invalid initialization parameters\n");
        return;
    }

    // Allocate memory for the arrays and initialize them to default values
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        printf("Failed to allocate memory for record array\n");
        return;
    }
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        printf("Failed to allocate memory for offset array\n");
        free(records);
        return;
    }
    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        printf("Failed to allocate memory for key array\n");
        free(offsets);
        free(records);
        return;
    }
    for (int i = 0; i < num_records; i++) {
        records[i].key = min_key;
        offsets[i] = min_offset;
        keys[i] = min_key;
    }

    // Set the value of each record's int field to a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        offsets[i] = rand() % (max_offset - min_offset + 1) + min_offset;
        keys[i] = rand() % (max_key - min_key + 1) + min_key;
    }

    // Increment the access counter for each record and log access events to a file
    FILE* log_file = fopen("access_log.txt", "a");
    if (!log_file) {
        printf("Failed to open log file\n");
    } else {
        for (int i = 0; i < num_records; i++) {
            records[i].access_count++;
            fprintf(log_file, "%d %d %ld\n", records[i].key, offsets[i], keys[i]);
        }
    }
    fclose(log_file);
}

// Function to free the allocated memory when exiting
void cleanup() {
    // Free the memory for the arrays and record structs
    free(offsets);
    free(keys);
    free(records);
}
