#define MAX_LOG_LEVEL 5
#define MIN_LOG_LEVEL 0
#define DEFAULT_LOG_FILE "log.txt"
#define DEFAULT_ROTATION_SIZE 1024 * 1024 * 10 // 10 MB
#define DEFAULT_ROTATION_INTERVAL 3600 // 1 hour
#define MAX_BUFFER_SIZE (1024 * 1024) // 1 MB
#define MIN_BUFFER_SIZE 512 // 0.5 KB
#define DEFAULT_BUFFER_GROWTH_FACTOR 2
#define DEFAULT_QUEUE_SIZE 1024
#define DEFAULT_ASYNC_LEVEL_BASED_THROTTLING 1
#define DEFAULT_ASYNC_FLUSHING_INTERVAL 3 // 3 seconds
#define MAX_ARGC 100
#define MAX_LOG_BUFFERS 1024
#define MIN_LOG_BUFFER_SIZE 512 // 0.5 KB
#define DEFAULT_LOG_BUFFER_GROWTH_FACTOR 2
#define DEFAULT_MAX_MEMORY_USAGE 1024 * 1024 * 10 // 10 MB
#define MIN_MAX_MEMORY_USAGE 512 * 1024 // 5 MB

typedef struct LogBuffer {
    size_t capacity;
    size_t used;
    char* buffer;
} LogBuffer;

typedef struct LogFile {
    char* path;
    int fd;
    size_t rotation_size;
    time_t rotation_interval;
    size_t rotation_count;
    size_t rotation_current;
} LogFile;

typedef struct Logger {
    char* log_levels[MAX_LOG_LEVEL + 1];
    int log_level;
    LogBuffer buffer[MAX_BUFFER_SIZE / MIN_LOG_BUFFER_SIZE + 1];
    size_t buffer_size;
    size_t buffer_capacity;
    size_t buffer_used;
    size_t queue_size;
    int async_level_based_throttling;
    time_t async_flushing_interval;
    pthread_mutex_t lock;
} Logger;

void parseArguments(int argc, char** argv) {
    if (argc > MAX_ARGC) {
        printf("Too many arguments. Maximum is %d\n", MAX_ARGC);
        exit(1);
    }

    for (int i = 0; i < argc; i++) {
        char* argument = argv[i];
        if (!strcmp(argument, "--log-level")) {
            // Validate log level
            if (i == argc - 1) {
                printf("Invalid number of arguments for %s\n", argument);
                exit(1);
            }
            char* log_level = argv[++i];
            int valid_log_level = 0;
            for (int j = MIN_LOG_LEVEL; j <= MAX_LOG_LEVEL; j++) {
                if (!strcmp(log_level, logger.log_levels[j])) {
                    valid_log_level = 1;
                    break;
                }
            }
            if (!valid_log_level) {
                printf("Invalid log level %s\n", log_level);
                exit(1);
            }
        } else if (!strcmp(argument, "--log-file")) {
            // Validate log file path
            if (i == argc - 1) {
                printf("Invalid number of arguments for %s\n", argument);
                exit(1);
            }
            char* log_file = argv[++i];
            struct stat buffer;
            if (stat(log_file, &buffer)) {
                printf("Log file %s does not exist\n", log_file);
                exit(1);
            } else if (!S_ISREG(buffer.st_mode)) {
                printf("%s is not a regular file\n", log_file);
                exit(1);
            }
        } else if (!strcmp(argument, "--rotation-size")) {
            // Validate rotation size
            if (i == argc - 1) {
                printf("Invalid number of arguments for %s\n", argument);
                exit(1);
            }
            char* rotation_size = argv[++i];
            long int rotation_size_value;
            if (!sscanf(rotation_size, "%ld", &rotation_size_value) ||
                    rotation_size_value <= 0) {
                printf("Invalid rotation size %s\n", rotation_size);
                exit(1);
            } else if (rotation_size_value > SIZE_MAX) {
                printf("Rotation size exceeds maximum value\n");
                exit(1);
            }
        } else if (!strcmp(argument, "--rotation-interval")) {
            // Validate rotation interval
            if (i == argc - 1) {
                printf("Invalid number of arguments for %s\n", argument);
                exit(1);
            }
            char* rotation_interval = argv[++i];
            long int rotation_interval_value;
            if (!sscanf(rotation_interval, "%ld", &rotation_interval_value) ||
                    rotation_interval_value <= 0) {
                printf("Invalid rotation interval %s\n", rotation_interval);
                exit(1);
            } else if (rotation_interval_value > LONG_MAX / 1000) {
                printf("Rotation interval exceeds maximum value\n");
                exit(1);
            }
        } else if (!strcmp(argument, "--buffer-size")) {
            // Validate buffer size
            if (i == argc - 1) {
                printf("Invalid number of arguments for %s\n", argument);
                exit(1);
            }
            char* buffer_size = argv[++i];
            long int buffer_size_value;
            if (!sscanf(buffer_size, "%ld", &buffer_size_value) ||
                    buffer_size_value <= 0) {
                printf("Invalid buffer size %s\n", buffer_size);
                exit(1);
            } else if (buffer_size_value > SIZE_MAX) {
                printf("Buffer size exceeds maximum value\n");
                exit(1);
            }
        } else if (!strcmp(argument, "--queue-size")) {
            // Validate queue size
            if (i == argc - 1) {
                printf("Invalid number of arguments for %s\n", argument);
                exit(1);
            }
            char* queue_size = argv[++i];
            long int queue_size_value;
            if (!sscanf(queue_size, "%ld", &queue_size_value) ||
                    queue_size_value <= 0) {
                printf("Invalid queue size %s\n", queue_size);
                exit(1);
            } else if (queue_size_value > SIZE_MAX / sizeof(LogBuffer)) {
                printf("Queue size exceeds maximum value\n");
                exit(1);
            }
        } else if (!strcmp(argument, "--async-level-based-throttling")) {
            // Validate async level based throttling
            if (i == argc - 1) {
                printf("Invalid number of arguments for %s\n", argument);
                exit(1);
            }
            char* async_level_based_throttling = argv[++i];
            long int async_level_based_throttling_value;
            if (!sscanf(async_level_based_throttling, "%ld", &async_level_based_throttling_value) ||
                    async_level_based_throttling_value <= 0) {
                printf("Invalid async level based throttling %s\n", async_level_based_throttling);
                exit(1);
            } else if (async_level_based_throttling_value > LONG_MAX / 1000) {
                printf("Async level based throttling exceeds maximum value\n");
                exit(1);
            }
        } else if (!strcmp(argument, "--async-flushing-interval")) {
            // Validate async flushing interval
            if (i == argc - 1) {
                printf("Invalid number of arguments for %s\n", argument);
                exit(1);
            }
            char* async_flushing_interval = argv[++i];
            long int async_flushing_interval_value;
            if (!sscanf(async_flushing_interval, "%ld", &async_flushing_interval_value) ||
                    async_flushing_interval_value <= 0) {
                printf("Invalid async flushing interval %s\n", async_flushing_interval);
                exit(1);
            } else if (async_flushing_interval_value > LONG_MAX / 1000) {
                printf("Async flushing interval exceeds maximum value\n");
                exit(1);
            }
        } else if (!strcmp(argument, "--max-memory-usage")) {
            // Validate max memory usage
            if (i == argc - 1) {
                printf("Invalid number of arguments for %s\n", argument);
                exit(1);
            }
            char* max_memory_usage = argv[++i];
            long int max_memory_usage_value;
            if (!sscanf(max_memory_usage, "%ld", &max_memory_usage_value) ||
                    max_memory_usage_value <= 0) {
                printf("Invalid max memory usage %s\n", max_memory_usage);
                exit(1);
            } else if (max_memory_usage_value > SIZE_MAX) {
                printf("Max memory usage exceeds maximum value\n");
                exit(1);
            }
        } else {
            printf("Invalid argument %s\n", argument);
            exit(1);
        }
    }
}

void initializeLogging() {
    // Initialize log file
    LogFile* log_file = malloc(sizeof(LogFile));
    if (log_file == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    log_file->path = DEFAULT_LOG_FILE;
    log_file->fd = open(log_file->path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file->fd < 0) {
        printf("Error opening log file %s: %s\n", log_file->path, strerror(errno));
        exit(1);
    }
    log_file->rotation_size = DEFAULT_ROTATION_SIZE;
    log_file->rotation_interval = DEFAULT_ROTATION_INTERVAL;
    log_file->rotation_count = 0;
    log_file->rotation_current = time(NULL);

    // Initialize logging system
    Logger* logger = malloc(sizeof(Logger));
    if (logger == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    logger->log_levels[MIN_LOG_LEVEL] = "DEBUG";
    logger->log_levels[MAX_LOG_LEVEL + 1] = "ERROR";
    logger->log_level = DEFAULT_LOG_LEVEL;
    for (int i = MIN_LOG_LEVEL + 1; i < MAX_LOG_LEVEL + 1; i++) {
        logger->log_levels[i] = malloc(sizeof(char) * 6);
        if (logger->log_levels[i] == NULL) {
            printf("Memory allocation failed\n");
            exit(1);
        }
    }
    logger->buffer_size = DEFAULT_BUFFER_SIZE;
    logger->buffer_capacity = DEFAULT_BUFFER_CAPACITY;
    logger->buffer_used = 0;
    logger->queue_size = DEFAULT_QUEUE_SIZE;
    logger->async_level_based_throttling = DEFAULT_ASYNC_LEVEL_BASED_THROTTLING;
    logger->async_flushing_interval = DEFAULT_ASYNC_FLUSHING_INTERVAL;
    pthread_mutex_init(&logger->lock, NULL);
}

void log(char* message, ...) {
    // Lock mutex to prevent concurrent access
    pthread_mutex_lock(&logger.lock);

    // Validate log level
    int valid_log_level = 0;
    for (int i = MIN_LOG_LEVEL; i <= MAX_LOG_LEVEL; i++) {
        if (!strcmp(logger.log_levels[i], message)) {
            valid_log_level = 1;
            break;
        }
    }
    if (!valid_log_level) {
        printf("Invalid log level %s\n", message);
        exit(1);
    }

    // Create log buffer if necessary
    if (logger.buffer_used == logger.buffer_capacity) {
        if (logger.queue_size > 0) {
            pthread_mutex_unlock(&logger.lock);
            printf("Log buffer overflow. Increase buffer size or decrease logging rate.\n");
            exit(1);
        } else {
            logger->buffer_used = 0;
            if (logger.buffer_size < SIZE_MAX / 2) {
                logger->buffer_size *= 2;
            }
        }
    }

    // Create log message
    va_list args;
    va_start(args, message);
    int length = vsnprintf(logger.buffer + logger.buffer_used, logger.buffer_capacity - logger.buffer_used, message, args);
    va_end(args);
    if (length < 0) {
        printf("Error formatting log message\n");
        exit(1);
    }
    logger->buffer_used += length;

    // Flush buffer to file if necessary
    time_t current = time(NULL);
    if (logger.rotation_current != current) {
        if (logger.queue_size > 0 && logger.queue_size == logger.buffer_used) {
            printf("Log file rotation failed. Increase queue size or decrease logging rate.\n");
            exit(1);
        }
        // Flush buffer to file
        size_t bytes = write(log_file->fd, logger.buffer, logger.buffer_used);
        if (bytes < 0) {
            printf("Error writing to log file %s: %s\n", log_file->path, strerror(errno));
            exit(1);
        }
        // Reset buffer and update rotation current time
        logger.buffer_used = 0;
        logger.rotation_current = current;
    }

    // Unlock mutex
    pthread_mutex_unlock(&logger.lock);
}
