// Structure to represent a cache item
typedef struct CacheItem {
    int client_id;
    char key[64];
    void* value;
    uint32_t expiration_timestamp;
} CacheItem;

// Structure to represent the distributed cache module
typedef struct DistributedCache {
    pthread_mutex_t mutex; // Mutex for synchronizing access to the cache
    CacheItem* items; // Array of cache items
    int num_items; // Number of items in the cache
    int capacity; // Capacity of the cache
} DistributedCache;

// Initialize and configure the distributed cache module
void initDistributedCache(DistributedCache* cache, int capacity) {
    cache->capacity = capacity;
    cache->num_items = 0;
    cache->mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(&cache->mutex, NULL);
    cache->items = (CacheItem*)malloc(capacity * sizeof(CacheItem));
}

// Add a new cache item to the distributed cache
void addCacheItem(DistributedCache* cache, int client_id, const char* key, void* value, uint32_t expiration_timestamp) {
    pthread_mutex_lock(&cache->mutex);
    if (cache->num_items >= cache->capacity) {
        // Evict the least recently used item from the cache
        int lru_index = -1;
        for (int i = 0; i < cache->num_items; ++i) {
            if (lru_index == -1 || cache->items[i].expiration_timestamp < cache->items[lru_index].expiration_timestamp) {
                lru_index = i;
            }
        }
        free(cache->items[lru_index].value);
        --cache->num_items;
    }
    // Add the new item to the cache
    int index = cache->num_items++;
    cache->items[index].client_id = client_id;
    strcpy(cache->items[index].key, key);
    cache->items[index].value = value;
    cache->items[index].expiration_timestamp = expiration_timestamp;
    pthread_mutex_unlock(&cache->mutex);
}

// Get a cache item from the distributed cache
void* getCacheItem(DistributedCache* cache, const char* key) {
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->num_items; ++i) {
        if (strcmp(cache->items[i].key, key) == 0) {
            // Update the expiration timestamp of the item
            cache->items[i].expiration_timestamp = time(NULL) + 60; // 1 minute
            pthread_mutex_unlock(&cache->mutex);
            return cache->items[i].value;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
    return NULL;
}

// Remove a cache item from the distributed cache
void removeCacheItem(DistributedCache* cache, const char* key) {
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->num_items; ++i) {
        if (strcmp(cache->items[i].key, key) == 0) {
            free(cache->items[i].value);
            --cache->num_items;
            for (int j = i; j < cache->num_items; ++j) {
                cache->items[j] = cache->items[j + 1];
            }
            break;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
}

