void* dynamicAllocation(int numOffsets, int numKeys, int numRecords) {
    // Get the current time in nanoseconds
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long seed = (long)(ts.tv_nsec + getpid() * sysconf(_SC_PAGESIZE) + gethostid());

    // Allocate memory for offsets and keys arrays
    int* offsets = (int*)malloc(numOffsets * sizeof(int));
    int* keys = (int*)malloc(numKeys * sizeof(int));
    record** records = (record**)malloc(numRecords * sizeof(record*));

    // Initialize the offsets and keys arrays with random values within a specified range
