        records[i] = (record*)malloc(sizeof(record));
    }

    // Initialize the values of each record with random values within a specified range
    for (int i = 0; i < numRecords; i++) {
        records[i]->value = rand_r(&seed) % 100 + 1;
    }

    // Set up locks for thread-safe operations
    pthread_mutex_t lock[2];
    pthread_mutex_init(lock, NULL, PTHREAD_MUTEX_NORMAL);

    // Return the allocated memory and locks as a single pointer
    return (void*)malloc(sizeof(int*) * 3 + sizeof(record**) + sizeof(pthread_mutex_t));
}

// Function to handle multiple file formats efficiently and manage memory allocation for large datasets
void* handleMultipleFormats(FILE* file, int format) {
    // Determine the appropriate file reading strategy based on the format
