        size_t bufferSize = 4096;
        void* buffer = malloc(bufferSize);
        fread(buffer, 1, bufferSize, file);
        return buffer;
    } else if (format == TEXT_FORMAT) {
        // Use a streaming approach for text files
        char line[256];
        while (fgets(line, sizeof(line), file)) {
            // Parse the line and store the data in the appropriate arrays
        }
    } else {
        // Unknown format; return an error message
        printf("Unknown file format\n");
        exit(1);
    }
}

// Function to handle partial reads from input files gracefully, allowing for efficient retries or fallbacks in case of incomplete data
void* handlePartialReads(FILE* file) {
    // Set up a buffer for the data read from the file
    char buffer[4096];
    int bytesRead = 0;

    // Loop until all data has been read
    while (bytesRead < sizeof(buffer)) {
        // Read data from the file into the buffer
        size_t readBytes = fread(buffer + bytesRead, 1, sizeof(buffer) - bytesRead, file);

        // Check for errors or end of file
        if (readBytes == 0 || (ferror(file) != 0 && feof(file) == 0)) {
            printf("Error reading from file\n");
            exit(1);
        }

        // Update the number of bytes read and continue reading if more data is available
        bytesRead += readBytes;
    }
}
