  offset_array = (long*)malloc(num_records * sizeof(long));
  key_array = (int*)malloc(num_records * sizeof(int));
  record_array = (Record**)malloc(num_records * sizeof(Record*));

  // Initialize the arrays with random values and timestamps
  srand(time(NULL));

  for (size_t i = 0; i < num_records; i++) {
    offset_array[i] = rand();
    key_array[i] = rand() % 1000000;

    record_array[i] = malloc(sizeof(Record));
    record_array[i]->value = rand() % 1000000;
    record_array[i]->timestamp = time(NULL);
    record_array[i]->string = (char*)malloc(sizeof(char) * 32);
    sprintf(record_array[i]->string, "%d", rand() % 1000000);
  }

  // Write the data to file
  FILE* fp = fopen(output_file, "wb");

  if (fp == NULL) {
    perror("fopen");
    exit(EXIT_FAILURE);
  }

  for (size_t i = 0; i < num_records; i++) {
    fwrite(&offset_array[i], sizeof(long), 1, fp);
    fwrite(&key_array[i], sizeof(int), 1, fp);
    fwrite(record_array[i], sizeof(Record), 1, fp);
  }

  fclose(fp);
}
