// Function to sort the strings based on lexicographical order
void sort_strings(Arrays* arrays, int case_sensitive) {
    // Check if the arrays are valid
    if (!arrays || !arrays->strings) {
        return;
    }

    // Define a comparison function for sorting the strings
    int compare_function(const void* a, const void* b) {
        char** str1 = (char**)a;
        char** str2 = (char**)b;

        if (!case_sensitive) {
            // Convert both strings to lowercase before comparison
            char lower_str1[MAX_ARRAY_SIZE];
            char lower_str2[MAX_ARRAY_SIZE];

            for (int i = 0; i < strlen(*str1); ++i) {
