    keys = malloc(sizeof(int) * n);
    if (!offsets || !keys) {
        return;
    }
    // Initialize the arrays with random values
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        offsets[i] = rand() % INT_MAX;
        keys[i] = rand() % INT_MAX;
