#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <mutex>
#include <thread>
#include <chrono>
#include <ctime>

class Log {
public:
    enum class Level { DEBUG, INFO, WARNING, ERROR };
    static std::string levelToString(Level level) {
        switch (level) {
            case Level::DEBUG: return "DEBUG";
            case Level::INFO: return "INFO";
            case Level::WARNING: return "WARNING";
            case Level::ERROR: return "ERROR";
            default: return "UNKNOWN";
        }
    }
    static Level stringToLevel(const std::string& str) {
        if (str == "DEBUG") {
            return Level::DEBUG;
        } else if (str == "INFO") {
            return Level::INFO;
        } else if (str == "WARNING") {
            return Level::WARNING;
        } else if (str == "ERROR") {
            return Level::ERROR;
        } else {
            return Level::UNKNOWN;
        }
    }
};

class LogManager {
private:
    std::mutex mtx_; // mutex for synchronizing access to log buffers
    std::map<Log::Level, std::vector<std::string>> logs_[4]; // map of log levels and their corresponding vectors
    int currentLogIdx_; // index of the next log message to be written
    bool isLoggingEnabled_; // flag indicating whether logging is enabled or not
public:
    LogManager() : mtx_(), logs_{}, currentLogIdx_(0), isLoggingEnabled_(false) {}
    void enableLogging(bool enable) {
        std::lock_guard<std::mutex> lock(mtx_);
        isLoggingEnabled_ = enable;
    }
    bool isLoggingEnabled() {
        std::lock_guard<std::mutex> lock(mtx_);
        return isLoggingEnabled_;
    }
    void writeLog(const std::string& msg, Log::Level level) {
        if (!isLoggingEnabled_) {
            return;
        }
        std::lock_guard<std::mutex> lock(mtx_);
        logs_[static_cast<int>(level)].push_back(msg);
    }
    void flush() {
        if (!isLoggingEnabled_) {
            return;
        }
        std::lock_guard<std::mutex> lock(mtx_);
        for (int i = 0; i < 4; ++i) {
            auto& logs = logs_[i];
            if (!logs.empty()) {
                // write log messages to file
                std::ofstream ofs("log_" + Log::levelToString(static_cast<Log::Level>(i)) + ".txt", std::ios::app);
                for (const auto& msg : logs) {
                    ofs << msg << "\n";
                }
                logs.clear();
            }
        }
    }
};

class LogBufferManager {
private:
    std::mutex mtx_; // mutex for synchronizing access to the log buffer
    std::vector<std::string> logBuffers_; // vector of log buffers
public:
    LogBufferManager() : mtx_(), logBuffers_(0) {}
    void allocate(int size) {
        std::lock_guard<std::mutex> lock(mtx_);
        logBuffers_.resize(size);
    }
    void deallocate() {
        std::lock_guard<std::mutex> lock(mtx_);
        logBuffers_.clear();
    }
    bool isBufferFull(int bufferIdx) {
        if (bufferIdx < 0 || bufferIdx >= logBuffers_.size()) {
            return true;
        }
        return false;
    }
    int getNextFreeBufferIndex() {
        std::lock_guard<std::mutex> lock(mtx_);
        for (int i = 0; i < logBuffers_.size(); ++i) {
            if (logBuffers_[i].empty()) {
                return i;
            }
        }
        // no free buffers found, return -1
        return -1;
    }
    int getBufferSize(int bufferIdx) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (bufferIdx < 0 || bufferIdx >= logBuffers_.size()) {
            return -1;
        }
        return logBuffers_[bufferIdx].size();
    }
    void appendMessage(int bufferIdx, const std::string& msg) {
        if (bufferIdx < 0 || bufferIdx >= logBuffers_.size()) {
            return;
        }
        std::lock_guard<std::mutex> lock(mtx_);
        logBuffers_[bufferIdx].push_back(msg);
    }
    void flush() {
        std::lock_guard<std::mutex> lock(mtx_);
        for (int i = 0; i < logBuffers_.size(); ++i) {
            if (!logBuffers_[i].empty()) {
                // write log messages to file
                std::ofstream ofs("log_" + Log::levelToString(static_cast<Log::Level>(i)) + ".txt", std::ios::app);
                for (const auto& msg : logBuffers_[i]) {
                    ofs << msg << "\n";
                }
                logBuffers_[i].clear();
            }
        }
    }
};

class LogArchiver {
private:
    std::mutex mtx_; // mutex for synchronizing access to the archived logs
    std::vector<std::string> archivedLogs_; // vector of archived log files
public:
    LogArchiver() : mtx_(), archivedLogs_(0) {}
    void allocate(int size) {
        std::lock_guard<std::mutex> lock(mtx_);
        archivedLogs_.resize(size);
    }
    void deallocate() {
        std::lock_guard<std::mutex> lock(mtx_);
        archivedLogs_.clear();
    }
    bool isArchiveFull(int archiveIdx) {
        if (archiveIdx < 0 || archiveIdx >= archivedLogs_.size()) {
            return true;
        }
        return false;
    }
    int getNextFreeArchiveIndex() {
        std::lock_guard<std::mutex> lock(mtx_);
        for (int i = 0; i < archivedLogs_.size(); ++i) {
            if (archivedLogs_[i].empty()) {
                return i;
            }
        }
        // no free archives found, return -1
        return -1;
    }
    void addArchive(int archiveIdx, const std::string& logFile) {
        if (archiveIdx < 0 || archiveIdx >= archivedLogs_.size()) {
            return;
        }
        std::lock_guard<std::mutex> lock(mtx_);
        archivedLogs_[archiveIdx] = logFile;
    }
    void flush() {
        std::lock_guard<std::mutex> lock(mtx_);
        for (int i = 0; i < archivedLogs_.size(); ++i) {
            if (!archivedLogs_[i].empty()) {
                // write log messages to file
                std::ofstream ofs("log_" + Log::levelToString(static_cast<Log::Level>(i)) + ".txt", std::ios::app);
                for (const auto& msg : archivedLogs_[i]) {
                    ofs << msg << "\n";
                }
                archivedLogs_[i].clear();
            }
        }
    }
};

int main() {
    LogManager logMgr; // create a logging manager instance
    LogBufferManager logBufMgr(1024); // create a log buffer manager with 1024 buffers
    LogArchiver logArchiver(3); // create a log archiver with 3 archives
    logMgr.enableLogging(); // enable logging
    std::string msg = "Hello, world!"; // message to be logged
    Log::Level level = Log::Level::INFO; // log level (DEBUG, INFO, WARNING, ERROR)
    int bufferIdx = logBufMgr.getNextFreeBufferIndex(); // get the next free buffer index
    if (!logBufMgr.isBufferFull(bufferIdx)) {
        logBufMgr.appendMessage(bufferIdx, msg); // append message to the buffer
        if (bufferIdx >= 1024) { // if the buffer is full, flush it and allocate a new one
            logBufMgr.flush();
            logBufMgr.allocate(1024);
        }
    } else {
        int archiveIdx = logArchiver.getNextFreeArchiveIndex(); // get the next free archive index
        if (!logArchiver.isArchiveFull(archiveIdx)) {
            logArchiver.addArchive(archiveIdx, msg); // add message to the archive
            if (archiveIdx >= 3) { // if the archive is full, flush it and allocate a new one
                logArchiver.flush();
                logArchiver.allocate(3);
            }
        } else {
            std::cout << "Log buffer and archives are full, dropping message..." << std::endl; // drop the message if no space available
        }
    }
    return 0;
}']

