        pthread_mutex_init(&session_mutex[i], NULL);
    }

    // Configure error handling and logging mechanisms to ensure robustness under high-load conditions
    FILE *error_log = fopen("network_module_errors.log", "a");

    while (1) {
        // Read data from network interface
        unsigned char *data = read_from_network();

        // Extract session ID and payload size from data
        int id = extract_session_id(data);
        size_t payload_size = extract_payload_size(data);

        // Look up session based on ID
        struct session *s = NULL;
        for (int i = 0; i < num_sessions; ++i) {
            if (sessions[i].id == id) {
                s = &sessions[i];
                break;
            }
        }

        // If session not found, allocate new one and add to queue
        if (!s) {
            s = malloc(sizeof(*s));
            s->id = id;
            s->queue = malloc(100000 * sizeof(struct tx_queue_data_item));
            pthread_mutex_lock(&session_mutex[id - 1]);
            session_insert(sessions, num_sessions, s);
            pthread_mutex_unlock(&session_mutex[id - 1]);
        }

        // Insert data item into session queue and update last activity timestamp
        struct tx_queue_data_item *item = malloc(sizeof(*item));
        item->seq = s->queue.size + 1;
        item->payload_size = payload_size;
        item->last_activity = time(NULL);
        pthread_mutex_lock(&session_mutex[id - 1]);
        session_insert(s->queue, 100000, item);
        pthread_mutex_unlock(&session_mutex[id - 1]);

        // Update password in database and log any errors or warnings
        update_password_in_database(dao, id);
        if (dao->error) {
            fprintf(error_log, "Error updating password for session %d: %s\n", id, dao->error_msg);
        } else if (dao->warning) {
            fprintf(error_log, "Warning updating password for session %d: %s\n", id, dao->warning_msg);
        }
    }
}

// Function to insert data item into session queue
void session_insert(struct tx_queue_data_item *queue, int capacity, struct tx_queue_data_item *item) {
    if (queue->size >= capacity) {
        // Remove oldest item from queue and free its memory
        struct tx_queue_data_item *removed = queue->first;
        queue->first = removed->next;
        free(removed);
    }

    // Add new item to end of queue
    queue->size++;
    struct tx_queue_data_item *tail = queue->last;
    tail->next = item;
    queue->last = item;
}

